#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_TIMEOUT 1000

void handle_signal(int signum) {
    if (spi != -1) {
        spiClose(spi);
    }
    pigpioStop();
    exit(signum);
}

int main() {
    int spi = -1;
    int result;
    unsigned char cmd[3] = {0x01, 0x80, 0x00}; // Single-ended, channel 0, no clock stretching
    unsigned char data[3];
    unsigned int raw_value;

    // Initialize pigpio
    if (pigpioOpen() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize SPI
    spi = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_TIMEOUT);
    if (spi < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return 1;
    }

    while (1) {
        result = spiXfer(spi, cmd, 3, data);
        if (result != 3) {
            fprintf(stderr, "SPI transfer failed\n");
            spiClose(spi);
            pigpioStop();
            return 1;
        }

        // Extract the 10-bit ADC value from the data
        raw_value = (data[1] << 8) | data[2];

        // Log the raw value with a timestamp
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        printf("%04d-%02d-%02d %02d:%02d:%02d: Raw Value = %u\n",
               now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
               now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, raw_value);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up on exit
    spiClose(spi);
    pigpioStop();

    return 0;
}

