#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x48
#define I2C_BUS 1
#define MLX91219_SENSITIVITY 0.04 // 40mV/A
#define MLX91219_OFFSET 2.5 // Mid-supply voltage
#define SAMPLE_RATE 128 // Samples per second
#define SAMPLE_INTERVAL (1000000 / SAMPLE_RATE) // Microseconds
#define LOG_INTERVAL 500000 // 500ms

void handle_sigint(int signum) {
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) >= 0) {
        i2cClose(I2C_BUS, I2C_ADDR);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d for address 0x%x.\n", I2C_BUS, I2C_ADDR);
        return 1;
    }

    uint8_t configRegister = 0x01; // Single-shot mode
    uint8_t muxRegister = 0x00; // AIN0 single-ended
    uint8_t pgaRegister = 0x01; // PGA ±4.096V
    uint8_t dataRateRegister = 0x00; // 128 samples per second

    uint8_t configBuffer[2] = {configRegister, 0};
    uint8_t muxBuffer[2] = {muxRegister, 0};
    uint8_t pgaBuffer[2] = {pgaRegister, 0};
    uint8_t dataRateBuffer[2] = {dataRateRegister, 0};

    if (i2cWriteI2CBlockData(I2C_BUS, I2C_ADDR, 0x00, configBuffer, 2) < 0) {
        fprintf(stderr, "Failed to write to configuration register.\n");
        i2cClose(I2C_BUS, I2C_ADDR);
        return 1;
    }

    if (i2cWriteI2CBlockData(I2C_BUS, I2C_ADDR, 0x01, muxBuffer, 2) < 0) {
        fprintf(stderr, "Failed to write to MUX register.\n");
        i2cClose(I2C_BUS, I2C_ADDR);
        return 1;
    }

    if (i2cWriteI2CBlockData(I2C_BUS, I2C_ADDR, 0x02, pgaBuffer, 2) < 0) {
        fprintf(stderr, "Failed to write to PGA register.\n");
        i2cClose(I2C_BUS, I2C_ADDR);
        return 1;
    }

    if (i2cWriteI2CBlockData(I2C_BUS, I2C_ADDR, 0x03, dataRateBuffer, 2) < 0) {
        fprintf(stderr, "Failed to write to data rate register.\n");
        i2cClose(I2C_BUS, I2C_ADDR);
        return 1;
    }

    uint16_t adcValue;
    double voltage;
    double current;

    while (1) {
        if (i2cReadI2CBlockData(I2C_BUS, I2C_ADDR, 0x00, (uint8_t*)&adcValue, 2) < 0) {
            fprintf(stderr, "Failed to read ADC value.\n");
            i2cClose(I2C_BUS, I2C_ADDR);
            return 1;
        }

        voltage = (double)adcValue * 4.096 / 65536; // Convert ADC value to voltage
        current = (voltage - MLX91219_OFFSET) / MLX91219_SENSITIVITY; // Calculate current

        printf("Current: %.2f A\n", current);

        usleep(LOG_INTERVAL);
    }

    i2cClose(I2C_BUS, I2C_ADDR);
    gpioTerminate();

    return 0;
}

