#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define GPIO_D0 4
#define FILE_NAME "flame_data.csv"

void handle_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

int main() {
    if (gpioInitialise() < 0) {
        handle_error("Failed to initialize pigpio");
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        handle_error("Failed to open SPI channel");
    }

    FILE *file = fopen(FILE_NAME, "w");
    if (!file) {
        handle_error("Failed to open file for writing");
    }

    fprintf(file, "Timestamp,FlameDetected,Temperature\n");

    while (1) {
        int flameDetected = gpioRead(GPIO_D0);
        if (flameDetected < 0) {
            handle_error("Failed to read flame sensor");
        }

        uint8_t buffer[3];
        buffer[0] = 0x01; // Single-ended, channel 0
        buffer[1] = 0x80; // Start bit
        buffer[2] = 0x00; // Dummy byte

        if (spiXfer(SPI_CHANNEL, buffer, 3, buffer) != 3) {
            handle_error("Failed to transfer data over SPI");
        }

        int adcValue = (buffer[1] << 8) | buffer[2];
        double temperature = (adcValue * 30.0) / 1023.0 + 10.0; // Linear map 0-1023 to 10-40°C

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d,%d,%f\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
                flameDetected, temperature);

        if (flameDetected == 0 || spiXfer(SPI_CHANNEL, buffer, 3, buffer) != 3) {
            fprintf(stderr, "Sensor absent or SPI failure, skipping log entry\n");
        }

        usleep(1000000); // Sleep for 1 second
    }

    fclose(file);
    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

