#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define CHANNEL AIN0
#define GAIN 4096
#define SPS 128
#define TEMP_THRESHOLD 60
#define DEBOUNCE_TIME 50
#define LOG_FILE "fire_log.txt"

volatile int flame_detected = 0;
volatile int last_flame_time = 0;
volatile int running = 1;

void flame_isr(int gpio, int level, uint32_t tick) {
    if (level == 0 && (tick - last_flame_time) >= DEBOUNCE_TIME) {
        flame_detected = 1;
        last_flame_time = tick;
    }
}

int main(int argc, char *argv[]) {
    int i2c_handle;
    FILE *log_file;
    int flame_sensor_state = 0;
    int temperature = 0;
    int adc_result = 0;
    int adc_config = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Set up flame sensor pin with internal pull-up
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to configure flame sensor GPIO.\n");
        gpioTerminate();
        return 1;
    }

    // Set up buzzer pin
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to configure buzzer GPIO.\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    // Configure ADC
    adc_config = (GAIN << 4) | (SPS << 2) | (CHANNEL << 0);
    if (i2cWriteDevice(i2c_handle, &adc_config, 1) < 0) {
        fprintf(stderr, "Failed to configure ADC.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register flame sensor ISR
    if (gpioSetISRFunc(FLAME_SENSOR_PIN, PI_ISR_FALLING_EDGE, flame_isr) < 0) {
        fprintf(stderr, "Failed to register flame sensor ISR.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        // Read flame sensor state
        flame_sensor_state = gpioRead(FLAME_SENSOR_PIN);

        // Read temperature from ADC
        if (i2cReadDevice(i2c_handle, &adc_result, 2) < 0) {
            fprintf(stderr, "Failed to read ADC.\n");
            continue;
        }

        // Map ADC result to temperature
        temperature = (adc_result * 3300 / 4096) + 20;

        // Check for fire condition
        if (flame_detected && temperature > TEMP_THRESHOLD) {
            fprintf(log_file, "Fire detected at %s\n", ctime(&time(NULL)));
            gpioWrite(BUZZER_PIN, PI_ON);
            usleep(2000000);
            gpioWrite(BUZZER_PIN, PI_OFF);
        } else if (flame_sensor_state == 0) {
            fprintf(log_file, "Flame detected at %s\n", ctime(&time(NULL)));
        } else if (temperature > TEMP_THRESHOLD) {
            fprintf(log_file, "Temperature %d°C detected at %s\n", temperature, ctime(&time(NULL)));
        }

        // Reset flame_detected flag
        flame_detected = 0;

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    gpioWrite(BUZZER_PIN, PI_OFF);
    gpioSetISRFunc(FLAME_SENSOR_PIN, 0, NULL);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

