#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <stdint.h>
#include <gpiod.h>
#include <spidev.h>

#define DEFAULT_SENSITIVITY 100 // mV/A
#define DEFAULT_THRESHOLD 5.0  // A

static struct spidev *spi;
static struct gpiod_line *fan_line;

static void cleanup(void) {
    if (fan_line) {
        gpiod_line_request_release(fan_line);
        free(fan_line);
    }
    if (spi) {
        close(spi->fd);
        free(spi);
    }
}

static void handle_signal(int signum) {
    cleanup();
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

static int read_adc(uint8_t channel) {
    uint8_t cmd[3] = {0x01, (channel << 4) | 0x80, 0x00};
    uint8_t rx[3];

    if (spidev_readwrite(spi, cmd, rx, 3) < 0) {
        perror("spidev_readwrite");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    if (adc_value == 0 || adc_value == 0x3FF) {
        fprintf(stderr, "Sensor absent or error reading ADC\n");
        return -1;
    }

    return adc_value;
}

static void drive_fan(int state) {
    if (gpiod_line_set_value(fan_line, state) < 0) {
        perror("gpiod_line_set_value");
    }
}

int main(int argc, char *argv[]) {
    int sensitivity = DEFAULT_SENSITIVITY;
    double threshold = DEFAULT_THRESHOLD;

    if (argc > 1 && strcmp(argv[1], "-s") == 0) {
        if (argc > 2) {
            sensitivity = atoi(argv[2]);
        } else {
            fprintf(stderr, "Missing sensitivity value after -s\n");
            return EXIT_FAILURE;
        }
    }

    if (argc > 3 && strcmp(argv[3], "-t") == 0) {
        if (argc > 4) {
            threshold = atof(argv[4]);
        } else {
            fprintf(stderr, "Missing threshold value after -t\n");
            return EXIT_FAILURE;
        }
    }

    spi = malloc(sizeof(struct spidev));
    if (!spi) {
        perror("malloc");
        return EXIT_FAILURE;
    }

    if (spidev_open(spi, "/dev/spidev0.0", 0) < 0) {
        perror("spidev_open");
        free(spi);
        return EXIT_FAILURE;
    }

    if (gpiod_chip_open("gpiochip4", &fan_line) < 0) {
        if (gpiod_chip_open("gpiochip0", &fan_line) < 0) {
            perror("gpiod_chip_open");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    if (gpiod_line_request(fan_line, "fan", GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        perror("gpiod_line_request");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int adc_value = read_adc(0);
        if (adc_value >= 0) {
            double voltage = (adc_value * 3.3) / 1024.0;
            double current = (voltage * 1000) / sensitivity;

            if (current > threshold) {
                drive_fan(1);
            } else {
                drive_fan(0);
            }

            char timestamp[20];
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%FT%T", now_tm);

            printf("%s %.2f A\n", timestamp, current);
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

