#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define GPIO_D0 4
#define GPIO_A0 0

#define TEMP_MIN 10.0
#define TEMP_MAX 40.0
#define ADC_MIN 0
#define ADC_MAX 1023

void handle_interrupt(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int spi_handle;
    int flame_detected;
    float temperature;
    char filename[] = "flame_data.csv";
    FILE *file;

    // Set up signal handling for SIGINT (Ctrl+C)
    signal(SIGINT, handle_interrupt);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    // Set GPIO D0 as input
    if (gpioSetMode(GPIO_D0, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_D0);
        goto cleanup;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        goto cleanup;
    }

    // Open file for writing
    file = fopen(filename, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file %s\n", filename);
        goto cleanup;
    }

    while (1) {
        // Read flame detection
        flame_detected = gpioRead(GPIO_D0);

        // Read temperature from ADC
        uint8_t adc_data[3];
        adc_data[0] = 0;
        adc_data[1] = 0;
        adc_data[2] = 0;

        if (spiXfer(spi_handle, adc_data, 3) != 3) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        uint16_t adc_value = (adc_data[1] << 8) | adc_data[2];
        temperature = TEMP_MIN + ((TEMP_MAX - TEMP_MIN) * (adc_value - ADC_MIN)) / (ADC_MAX - ADC_MIN);

        // Write to file
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        fprintf(file, "%d-%02d-%02d %02d:%02d:%02d, %d, %.2f\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
                flame_detected, temperature);

        // Sleep for 1 second
        sleep(1);
    }

cleanup:
    // Close file
    if (file) {
        fclose(file);
    }

    // Close SPI
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Terminate pigpio
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio\n");
    }

    return 0;
}

