#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x44
#define I2C_CO_REG 0x00
#define I2C_NO2_REG 0x02
#define I2C_READ_LEN 4
#define ALERT_THRESHOLD 25
#define LOG_INTERVAL 5000 // 5 seconds

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int read_sensor_data(unsigned char *data) {
    int result = i2c_read_device(I2C_ADDR, data, I2C_READ_LEN);
    if (result != I2C_READ_LEN) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

double calculate_ppm(unsigned char *data) {
    unsigned short co_value = (data[0] << 8) | data[1];
    unsigned short no2_value = (data[2] << 8) | data[3];
    // Assuming a linear conversion from ADC to PPM (example values)
    // Replace with actual conversion formula if known
    double co_ppm = (double)co_value / 65535.0 * 1000.0; // Example conversion
    return co_ppm;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *co_log = fopen("co_log.txt", "w");
    if (!co_log) {
        fprintf(stderr, "Failed to open co_log.txt\n");
        return 1;
    }

    FILE *alert_log = fopen("alert_log.txt", "w");
    if (!alert_log) {
        fprintf(stderr, "Failed to open alert_log.txt\n");
        fclose(co_log);
        return 1;
    }

    unsigned char data[I2C_READ_LEN];

    while (!stop_flag) {
        if (read_sensor_data(data) == 0) {
            double co_ppm = calculate_ppm(data);
            fprintf(co_log, "CO level: %.2f PPM\n", co_ppm);
            if (co_ppm >= ALERT_THRESHOLD) {
                fprintf(alert_log, "Alert: CO level %.2f PPM exceeds threshold %d PPM\n", co_ppm, ALERT_THRESHOLD);
            }
        }
        gpioDelay(LOG_INTERVAL);
    }

    fclose(co_log);
    fclose(alert_log);
    gpioTerminate();

    return 0;
}

