#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR1 0x48
#define I2C_ADDR2 0x49
#define I2C_BUS 1
#define SAMPLE_INTERVAL 100000 // 100ms in microseconds
#define MIC_SENSITIVITY -38.0 // dBV/Pa
#define REF_PRESSURE 20e-6 // Pa

double convert_to_db(int16_t raw_data) {
    double voltage = (double)raw_data * 3.3 / 32768.0; // Convert raw data to voltage
    double pressure = pow(10.0, (voltage + MIC_SENSITIVITY) / 20.0); // Convert voltage to pressure
    double db = 20.0 * log10(pressure / REF_PRESSURE); // Convert pressure to dB
    return db;
}

void handle_signal(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    if (i2cUnregister(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to unregister I2C bus %d\n", I2C_BUS);
        exit(EXIT_FAILURE);
    }
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio\n");
        exit(EXIT_FAILURE);
    }
    exit(EXIT_SUCCESS);
}

