    FILE *log_file = fopen("audio_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR1, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%x\n", I2C_BUS, I2C_ADDR1);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR2, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%x\n", I2C_BUS, I2C_ADDR2);
        fclose(log_file);
        i2cUnregister(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        uint8_t data1[2] = {0};
        uint8_t data2[2] = {0};

        if (i2cRead(I2C_BUS, I2C_ADDR1, 0x00, data1, 2) < 0) {
            fprintf(log_file, "Error reading from sensor 1\n");
            fprintf(log_file, "%f %f\n", -999.0, -999.0);
        } else {
            int16_t raw_data1 = (data1[0] << 8) | data1[1];
            double db1 = convert_to_db(raw_data1);
            fprintf(log_file, "%f ", db1);
        }

        if (i2cRead(I2C_BUS, I2C_ADDR2, 0x00, data2, 2) < 0) {
            fprintf(log_file, "Error reading from sensor 2\n");
            fprintf(log_file, "%f\n", -999.0);
        } else {
            int16_t raw_data2 = (data2[0] << 8) | data2[1];
            double db2 = convert_to_db(raw_data2);
            fprintf(log_file, "%f\n", db2);
        }

        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2cUnregister(I2C_BUS);
    gpioTerminate();

    return EXIT_SUCCESS;
}

