This C program reads sound pressure levels from two STMicroelectronics IMP23ABSU analog MEMS microphones connected to the Raspberry Pi 4 Model B's I2C bus. It logs the timestamped average sound pressure levels to `audio_log.txt`. The program uses the pigpio library to emulate the I2C interface and reads 2 bytes from register 0x00 of each sensor. It samples every 100ms and converts the 16-bit signed raw data to sound pressure level in dB. If either sensor read fails, it logs an error value of -999.0 dB and continues running. The program handles SIGINT and SIGTERM signals for graceful shutdown, closing all I2C handles and terminating pigpio cleanly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pigpio.h>
#include <unistd.h>

#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1
#define SAMPLE_INTERVAL 1000 // 1 ms
#define SAMPLING_WINDOW 100 // 100 samples per channel
#define THRESHOLD 0.7
#define LED_PIN 27
#define CSV_FILE "audio_events.csv"

void handle_interrupt(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }
    gpioWrite(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

double calculate_rms(int channel, int samples) {
    double sum = 0.0;
    for (int i = 0; i < samples; i++) {
        int value = spiRead(channel);
        sum += value * value;
        usleep(SAMPLE_INTERVAL);
    }
    return sqrt(sum / samples);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    FILE *csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = handle_interrupt;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        double mic1_rms = calculate_rms(MIC1_CHANNEL, SAMPLING_WINDOW);
        double mic2_rms = calculate_rms(MIC2_CHANNEL, SAMPLING_WINDOW);

        time_t timestamp = time(NULL);
        fprintf(csv_file, "%ld,%f,%f\n", (long)timestamp, mic1_rms, mic2_rms);

        if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            usleep(500000); // 500 ms
            gpioWrite(LED_PIN, 0);
        }

        fflush(csv_file);
        usleep(1000000); // 1 second between sampling windows
    }

    fclose(csv_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

