This C program initializes the GPIO and pigpio library, sets up an interrupt handler for SIGINT, and continuously samples audio from two microphones connected to an MCP3008 ADC. It calculates the RMS value for each microphone, logs the data to a CSV file, and turns on an LED if the RMS value exceeds a threshold. The program handles errors and exits gracefully on SIGINT.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x48
#define I2C_BUS 1
#define I2C_REG_CONFIG 0x01
#define I2C_REG_DATA 0x00
#define I2C_REG_CONFIG_SINGLE_ENDED 0x80
#define I2C_REG_CONFIG_CHANNEL_A0 0x00
#define I2C_REG_CONFIG_GAIN_1_256 0x00
#define I2C_REG_CONFIG_DATA_RATE_128SPS 0x00
#define I2C_REG_CONFIG_MODE_CONTINUOUS 0x00
#define I2C_REG_CONFIG_POLARITY_POSITIVE 0x00
#define I2C_REG_CONFIG_REFERENCE_EXTERNAL 0x00
#define I2C_REG_CONFIG_MODE_SINGLE_ENDED (I2C_REG_CONFIG_SINGLE_ENDED | I2C_REG_CONFIG_CHANNEL_A0 | I2C_REG_CONFIG_GAIN_1_256 | I2C_REG_CONFIG_DATA_RATE_128SPS | I2C_REG_CONFIG_MODE_CONTINUOUS | I2C_REG_CONFIG_POLARITY_POSITIVE | I2C_REG_CONFIG_REFERENCE_EXTERNAL)

#define LED_GPIO 17
#define BUFFER_SIZE 100
#define THRESHOLD 50.0

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

void setup_adc() {
    uint8_t config = I2C_REG_CONFIG_MODE_SINGLE_ENDED | I2C_REG_CONFIG_CHANNEL_A0 | I2C_REG_CONFIG_GAIN_1_256 | I2C_REG_CONFIG_DATA_RATE_128SPS | I2C_REG_CONFIG_MODE_CONTINUOUS | I2C_REG_CONFIG_POLARITY_POSITIVE | I2C_REG_CONFIG_REFERENCE_EXTERNAL;
    uint8_t buffer[2];

    if (i2cWriteDevice(I2C_ADDR, I2C_REG_CONFIG, &config, 1) < 0) {
        fprintf(stderr, "Failed to configure ADC\n");
        exit(EXIT_FAILURE);
    }

    if (i2cReadDevice(I2C_ADDR, I2C_REG_DATA, buffer, 2) < 0) {
        fprintf(stderr, "Failed to read ADC data\n");
        exit(EXIT_FAILURE);
    }
}

void read_adc() {
    uint8_t buffer[2];
    int16_t adc_value;
    float voltage;
    float current;

    if (i2cReadDevice(I2C_ADDR, I2C_REG_DATA, buffer, 2) < 0) {
        fprintf(stderr, "Failed to read ADC data\n");
        exit(EXIT_FAILURE);
    }

    adc_value = (buffer[0] << 8) | buffer[1];
    voltage = (float)adc_value * 4.096 / 32767.0; // Assuming 4.096V reference
    current = (voltage - 0.5) * 100.0 / 4.0; // Convert voltage to current

    printf("Current: %.2f A\n", current);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        exit(EXIT_FAILURE);
    }

    setup_adc();

    signal(SIGINT, handle_sigint);

    float buffer[BUFFER_SIZE];
    int buffer_index = 0;
    float sum = 0.0;

    while (!stop) {
        read_adc();
        buffer[buffer_index] = sum / BUFFER_SIZE;
        sum += buffer[buffer_index];
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        if (buffer[buffer_index] > THRESHOLD) {
            if (gpioWrite(LED_GPIO, PI_ON) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                exit(EXIT_FAILURE);
            }
        } else {
            if (gpioWrite(LED_GPIO, PI_OFF) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
                exit(EXIT_FAILURE);
            }
        }

        usleep(100000); // 100ms delay for 10Hz sampling
    }

    if (gpioWrite(LED_GPIO, PI_OFF) < 0) {
        fprintf(stderr, "Failed to turn off LED on exit\n");
        exit(EXIT_FAILURE);
    }

    gpioTerminate();

    return 0;
}

