int read_i2c_register(int handle, int address, uint8_t *data, int length) {
    int i;
    for (i = 0; i < length; i++) {
        if (i2c_read_byte_data(handle, address + i) < 0) {
            fprintf(stderr, "I2C read error at address 0x%02X\n", address + i);
            return -1;
        }
        data[i] = i2c_read_byte_data(handle, address + i);
    }
    return 0;
}

int write_i2c_register(int handle, int address, uint8_t *data, int length) {
    int i;
