#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 10
#define SPI_CS_GPIO 8
#define MOISTURE_LOG "moisture_log.csv"

static struct spidev *spi;
static struct gpiod_line *cs_line;

void cleanup(int signum) {
    if (spi) {
        spidev_close(spi);
        free(spi);
    }
    if (cs_line) {
        gpiod_line_free(cs_line);
    }
    exit(signum);
}

int read_adc(int channel) {
    uint8_t tx[2] = {((channel << 4) & 0x0F) | 0x01, 0x00};
    uint8_t rx[2];

    if (spidev_write(spi, tx, 2) != 2) {
        perror("spidev_write");
        return -1;
    }

    if (spidev_read(spi, rx, 2) != 2) {
        perror("spidev_read");
        return -1;
    }

    return ((rx[1] << 8) | rx[0]) >> 2;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct spidev_data data;
    struct timespec ts;
    FILE *log_file;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    memset(&request, 0, sizeof(request));
    request.consumer = "Moisture Sensor";
    request.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    request.flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    request.line_consumer = "Moisture Sensor";
    request.line_type = GPIOD_LINE_TYPE_LINE;
    request.line_consumer_type = GPIOD_LINE_CONSUMER_TYPE_DRIVER;

    if ((cs_line = gpiod_line_request_open(chip, SPI_CS_GPIO, &request)) == NULL) {
        perror("gpiod_line_request_open");
        gpiod_chip_close(chip);
        return 1;
    }

    if ((spi = spidev_open(SPI_DEVICE, 0)) == NULL) {
        perror("spidev_open");
        gpiod_line_free(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (spidev_write_buf(spi, &data, 2, 0) < 0) {
        perror("spidev_write_buf");
        spidev_close(spi);
        gpiod_line_free(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if ((log_file = fopen(MOISTURE_LOG, "w")) == NULL) {
        perror("fopen");
        spidev_close(spi);
        gpiod_line_free(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");

    while (1) {
        time_t rawtime;
        struct tm *timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        gpiod_line_set_value(cs_line, 0);
        int moisture1 = read_adc(0);
        int moisture2 = read_adc(1);
        gpiod_line_set_value(cs_line, 1);

        if (moisture1 >= 0 && moisture2 >= 0) {
            double moisture1_percent = (double)moisture1 * 100.0 / 1023.0;
            double moisture2_percent = (double)moisture2 * 100.0 / 1023.0;
            fprintf(log_file, "%s,%f,%f\n", buffer, moisture1_percent, moisture2_percent);
        }

        usleep(5000000); // Sleep for 5 seconds
    }

    fclose(log_file);
    gpiod_line_free(cs_line);
    gpiod_chip_close(chip);
    spidev_close(spi);

    return 0;
}

