This C program reads analog values from two Seeed Studio Grove Moisture Sensors connected to an MCP3008 SPI ADC on a Raspberry Pi Zero W. It uses the libgpiod API to control the chip-select line and the standard Linux spidev interface for SPI communication. The program logs timestamped readings to a CSV file named `moisture_log.csv` with a header and samples every 5 seconds. It includes robust error handling for SPI and libgpiod initialization, sensor-absent or SPI bus-error paths, and ensures clean release of all resources on all exit paths via SIGINT/SIGTERM signal handling.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEV_PATH "/dev/spidev0.0"
#define CURRENT_LOG_FILE "current_log.csv"
#define MOTOR_SHUTDOWN_PIN "17"
#define OVERCURRENT_LIMIT 10.0
#define ADC_MAX 1023
#define ADC_VOLTAGE_RANGE 3.3
#define ADC_TO_VOLTAGE_FACTOR (ADC_VOLTAGE_RANGE / ADC_MAX)
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define SPI_MAX_RETRIES 3

static struct gpiod_line *shutdown_pin;
static struct spidev *spi;
static FILE *log_file;

void handle_signal(int signum) {
    gpiod_line_free(shutdown_pin);
    spidev_close(spi);
    fclose(log_file);
    exit(signum);
}

int read_adc() {
    int ret, i;
    uint8_t tx[1] = {0x00};
    uint8_t rx[3];

    for (i = 0; i < SPI_MAX_RETRIES; i++) {
        ret = spidev_readwrite_bytes(spi, tx, 1, rx, 3);
        if (ret == 3) {
            return (rx[1] << 8) | rx[2];
        }
        usleep(100000); // 100ms delay
    }
    return -1;
}

double adc_to_current(int adc_value) {
    double voltage = adc_value * ADC_TO_VOLTAGE_FACTOR;
    double current = (voltage - OFFSET) / SENSITIVITY;
    return current;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct spidev_data spi_data;
    int adc_value;
    double current;
    time_t timestamp;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    memset(&request, 0, sizeof(request));
    request.consumer = "current_monitor";
    request.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    request.flags = GPIOD_LINE_REQUEST_ACTIVE_LOW;
    request.line_name = MOTOR_SHUTDOWN_PIN;

    if ((shutdown_pin = gpiod_line_request_open(chip, &request)) == NULL) {
        perror("gpiod_line_request_open");
        gpiod_chip_close(chip);
        return 1;
    }

    if ((spi = spidev_open(SPI_DEV_PATH, 0)) == NULL) {
        perror("spidev_open");
        gpiod_line_free(shutdown_pin);
        gpiod_chip_close(chip);
        return 1;
    }

    spi_data.bits_per_word = 8;
    spi_data.max_speed_hz = 1000000;
    if (ioctl(spi->fd, SPI_IOC_WR_MODE, &spi_data.mode) < 0 ||
        ioctl(spi->fd, SPI_IOC_RD_MODE, &spi_data.mode) < 0 ||
        ioctl(spi->fd, SPI_IOC_WR_BITS_PER_WORD, &spi_data.bits_per_word) < 0 ||
        ioctl(spi->fd, SPI_IOC_RD_BITS_PER_WORD, &spi_data.bits_per_word) < 0 ||
        ioctl(spi->fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_data.max_speed_hz) < 0 ||
        ioctl(spi->fd, SPI_IOC_RD_MAX_SPEED_HZ, &spi_data.max_speed_hz) < 0) {
        perror("ioctl");
        spidev_close(spi);
        gpiod_line_free(shutdown_pin);
        gpiod_chip_close(chip);
        return 1;
    }

    if ((log_file = fopen(CURRENT_LOG_FILE, "a")) == NULL) {
        perror("fopen");
        spidev_close(spi);
        gpiod_line_free(shutdown_pin);
        gpiod_chip_close(chip);
        return 1;
    }

    fprintf(log_file, "timestamp,current_in_Amperes\n");

    while (1) {
        adc_value = read_adc();
        if (adc_value == -1) {
            perror("read_adc");
            continue;
        }

        current = adc_to_current(adc_value);
        timestamp = time(NULL);

        fprintf(log_file, "%ld,%f\n", (long)timestamp, current);
        fflush(log_file);

        if (current > OVERCURRENT_LIMIT) {
            gpiod_line_set_value(shutdown_pin, 1); // Drive LOW
            printf("Overcurrent detected: %.2f A - Motor shutdown\n", current);
            sleep(1);
            gpiod_line_set_value(shutdown_pin, 0); // Drive HIGH
            printf("Motor re-enabled\n");
        }

        sleep(1);
    }

    return 0;
}

