    if ((shutdown_pin = gpiod_line_request_open(chip, &request)) == NULL) {
        perror("gpiod_line_request_open");
        gpiod_chip_close(chip);
        return 1;
    }

    if ((spi = spidev_open(SPI_DEV_PATH, 0)) == NULL) {
        perror("spidev_open");
        gpiod_line_free(shutdown_pin);
        gpiod_chip_close(chip);
        return 1;
    }

    spi_data.bits_per_word = 8;
    spi_data.max_speed_hz = 1000000;
    if (ioctl(spi->fd, SPI_IOC_WR_MODE, &spi_data.mode) < 0 ||
        ioctl(spi->fd, SPI_IOC_RD_MODE, &spi_data.mode) < 0 ||
        ioctl(spi->fd, SPI_IOC_WR_BITS_PER_WORD, &spi_data.bits_per_word) < 0 ||
        ioctl(spi->fd, SPI_IOC_RD_BITS_PER_WORD, &spi_data.bits_per_word) < 0 ||
        ioctl(spi->fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_data.max_speed_hz) < 0 ||
        ioctl(spi->fd, SPI_IOC_RD_MAX_SPEED_HZ, &spi_data.max_speed_hz) < 0) {
        perror("ioctl");
        spidev_close(spi);
        gpiod_line_free(shutdown_pin);
        gpiod_chip_close(chip);
        return 1;
    }

    if ((log_file = fopen(CURRENT_LOG_FILE, "a")) == NULL) {
        perror("fopen");
        spidev_close(spi);
        gpiod_line_free(shutdown_pin);
        gpiod_chip_close(chip);
        return 1;
    }

    fprintf(log_file, "timestamp,current_in_Amperes\n");

    while (1) {
        adc_value = read_adc();
        if (adc_value == -1) {
            perror("read_adc");
            continue;
        }

        current = adc_to_current(adc_value);
        timestamp = time(NULL);

        fprintf(log_file, "%ld,%f\n", (long)timestamp, current);
        fflush(log_file);

        if (current > OVERCURRENT_LIMIT) {
            gpiod_line_set_value(shutdown_pin, 1); // Drive LOW
            printf("Overcurrent detected: %.2f A - Motor shutdown\n", current);
            sleep(1);
            gpiod_line_set_value(shutdown_pin, 0); // Drive HIGH
            printf("Motor re-enabled\n");
        }

        sleep(1);
    }

    return 0;
}
