#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define PRESSURE_REGISTER 0x00
#define PRESSURE_SCALE 500.0
#define PRESSURE_MAX 65535.0

FILE *log_file;
int i2c_handle;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cUnexport(i2c_handle);
    }
    gpioTerminate();
    exit(signum);
}

void log_pressure(double pressure_kPa) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%f\n", buffer, pressure_kPa);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (i2cOpen(1, 0x40, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x40\n");
        return 1;
    }

    i2c_handle = 1;

    log_file = fopen("pressure_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    fprintf(log_file, "timestamp,pressure_kPa\n");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        uint16_t raw_value;
        int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, 2, (char*)&raw_value, 2);

        if (result < 0) {
            fprintf(stderr, "Failed to read from register 0x%02X: %d\n", PRESSURE_REGISTER, result);
            continue;
        }

        double pressure_kPa = (double)raw_value / PRESSURE_MAX * PRESSURE_SCALE;
        log_pressure(pressure_kPa);

        sleep(1);
    }

    return 0;
}

