#define LED_PIN 17

void handle_sigint(int signum) {
    if (pi != NULL) {
        gpioTerminate();
        free(pi);
    }
    exit(0);
}

int read_adc(int adc_addr, int gain) {
    int i, result = -1;
    for (i = 0; i < 3; i++) {
        if (i2cRead(adc_addr, 0, 2, &result, 2) == 0) {
            break;
        }
    }
    return result;
}

double voltage_to_pressure(int voltage) {
    return (double)voltage * PRESSURE_GAIN;
}

double voltage_to_temperature(int voltage) {
    return (double)voltage * TEMP_GAIN;
}

int main() {
    int pressure_voltage, temp_voltage;
    double pressure, temperature;
    int retries = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED\n");
        goto cleanup;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        pressure_voltage = read_adc(ADS1115_ADDR, 2);
        if (pressure_voltage < 0) {
            fprintf(stderr, "Failed to read pressure voltage\n");
            continue;
        }

        temp_voltage = read_adc(ADS1115_ADDR, 2);
        if (temp_voltage < 0) {
            fprintf(stderr, "Failed to read temperature voltage\n");
            continue;
        }

        pressure = voltage_to_pressure(pressure_voltage);
        temperature = voltage_to_temperature(temp_voltage);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            if (gpioWrite(LED_PIN, PI_ON) < 0) {
                fprintf(stderr, "Failed to set LED HIGH\n");
            }
        } else {
            if (gpioWrite(LED_PIN, PI_OFF) < 0) {
                fprintf(stderr, "Failed to set LED LOW\n");
            }
        }

        sleep(1);
    }

cleanup:
    if (pi != NULL) {
        gpioTerminate();
        free(pi);
    }

    return 0;
}

