#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS_GPIO 8
#define SPI_CLK_GPIO 11
#define SPI_MOSI_GPIO 10
#define SPI_MISO_GPIO 9
#define ADC_CHANNEL 0
#define ADC_FULL_SCALE 3.3
#define ADC_STEPS 1024
#define CURRENT_SENSITIVITY 66.0 // mV/A
#define CURRENT_THRESHOLD 10.0 // A
#define GPIO_SHUTDOWN 27
#define LOG_FILE "current_log.txt"

int spiHandle;
FILE *logFile;

void spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    if (spi_write(spiHandle, tx, len, rx) != len) {
        fprintf(stderr, "SPI transfer error\n");
        exit(EXIT_FAILURE);
    }
}

int read_adc() {
    unsigned char tx[3] = {0x01, (ADC_CHANNEL << 6) | 0x00, 0x00};
    unsigned char rx[3];

    spi_transfer(tx, rx, 3);

    int adc_value = (rx[1] << 8) | rx[2];

    if (adc_value < 0 || adc_value > ADC_STEPS) {
        fprintf(stderr, "Invalid ADC value\n");
        exit(EXIT_FAILURE);
    }

    return adc_value;
}

double adc_to_voltage(int adc_value) {
    return (double)adc_value * ADC_FULL_SCALE / ADC_STEPS;
}

double voltage_to_current(double voltage) {
    double midpoint = ADC_FULL_SCALE / 2.0;
    double offset = midpoint - (voltage * ADC_STEPS / ADC_FULL_SCALE);
    return offset / CURRENT_SENSITIVITY * 1000.0; // Convert mV to A
}

void log_current(double current) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(logFile, "%s %.2f A\n", buffer, current);
    fflush(logFile);
}

void handle_interrupt(int signum) {
    if (spiHandle != -1) {
        spi_close(spiHandle);
    }

    if (logFile != NULL) {
        fclose(logFile);
    }

    gpioWrite(GPIO_SHUTDOWN, PI_OUTPUT_LOW);
    gpioTerminate();

    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spiHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, PI_OUTPUT_LOW);

    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    while (1) {
        int adc_value = read_adc();
        double voltage = adc_to_voltage(adc_value);
        double current = voltage_to_current(voltage);

        if (current > CURRENT_THRESHOLD) {
            gpioWrite(GPIO_SHUTDOWN, PI_OUTPUT_HIGH);
            fprintf(logFile, "OVERCURRENT event at %.2f A\n", current);
            fflush(logFile);
            break;
        }

        log_current(current);

        usleep(100000); // 100ms delay
    }

    if (spiHandle != -1) {
        spiClose(spiHandle);
    }

    if (logFile != NULL) {
        fclose(logFile);
    }

    gpioWrite(GPIO_SHUTDOWN, PI_OUTPUT_LOW);
    gpioTerminate();

    return EXIT_SUCCESS;
}

