This C program reads motor current using a Melexis MLX91209 Hall-effect current sensor via an MCP3008 10-bit SPI ADC on a Raspberry Pi 3 Model B+. It handles errors, logs readings with timestamps, and implements a safety monitor to shut down the motor if the current exceeds 10A.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ALARM_PIN 4
#define LOG_FILE "co_log.txt"

void handle_signal(int signum) {
    spiClose(SPI_CHANNEL);
    fclose(stdout);
    gpioWrite(ALARM_PIN, LOW);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, LOW);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        uint8_t cmd[3] = {0x01, (ADC_CHANNEL << 6) | 0x00, 0x00};
        uint8_t data[3];

        if (spiXfer(spi_handle, cmd, 3, data) != 3) {
            fprintf(stderr, "SPI transfer failed.\n");
            spiClose(SPI_CHANNEL);
            fclose(log_file);
            gpioTerminate();
            sleep(1);
            continue;
        }

        uint16_t adc_value = ((data[1] & 0x03) << 8) | data[2];
        float voltage = (adc_value * 3.3) / 1024.0;

        char timestamp[20];
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
        fflush(log_file);

        if (voltage > 2.5) {
            gpioWrite(ALARM_PIN, HIGH);
        } else {
            gpioWrite(ALARM_PIN, LOW);
        }

        sleep(1);
    }

    return 0;
}

