#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x48
#define I2C_BUS 1
#define ADC_CHANNEL 0
#define ADC_REFERENCE 4096
#define ADC_OFFSET 0.5
#define ADC_SENSITIVITY 0.1
#define PRESSURE_MIN 0
#define PRESSURE_MAX 100

void handle_sigint(int signum) {
    printf("\nReceived SIGINT, cleaning up resources...\n");
    close_i2c_device(i2c_handle);
    gpioInitialise();
    exit(0);
}

int main() {
    int i2c_handle = -1;
    int raw_value = 0;
    float voltage = 0.0;
    float pressure = 0.0;
    char timestamp[20];
    FILE *log_file = fopen("pressure_log.txt", "a");

    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        fclose(log_file);
        return 1;
    }

    if ((i2c_handle = open_i2c_device(I2C_BUS, I2C_ADDR)) < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        if (read_i2c_device(i2c_handle, ADC_CHANNEL, &raw_value) < 0) {
            perror("Failed to read ADC value");
            continue;
        }

        voltage = (float)raw_value * 3.3 / ADC_REFERENCE;
        pressure = (voltage - ADC_OFFSET) / ADC_SENSITIVITY;

        if (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX) {
            time_t rawtime;
            struct tm *timeinfo;
            char buffer[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

            fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure);
            fflush(log_file);
        }

        usleep(1000000); // Sleep for 1 second
    }

    fclose(log_file);
    close_i2c_device(i2c_handle);
    gpioTerminate();

    return 0;
}

