    int humidity_adc_value, temperature_adc_value;
    double humidity, temperature;
    char timestamp[20];
    FILE *log_file;

    // Initialize pigpio
    if ((pi = pigpio_start()) < 0) {
        fprintf(stderr, "pigpio_start failed (%d)\n", pi);
        return 1;
    }

    // Set up SPI
    if (spiBegin(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "spiBegin failed\n");
        goto cleanup;
    }

    // Open log file
    if ((log_file = fopen("humidity_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        goto spi_cleanup;
    }

