    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Read humidity ADC value
        if (spiRead(SPI_CHANNEL, &humidity_adc_value, 1) < 0) {
            fprintf(stderr, "spiRead failed for humidity\n");
            goto spi_cleanup;
        }

