        double humidity_voltage = (double)humidity_adc_value * 5.0 / 4096.0;
        double temperature_voltage = (double)temperature_adc_value * 5.0 / 4096.0;

        // Calculate humidity and temperature
        humidity = (humidity_voltage - 0.824) / 0.0315;
        temperature = 1 / (log((double)temperature_voltage / 10000.0) / 3950.0 + 1 / 298.15) - 273.15;

        // Log readings
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
        fflush(log_file);

        // Check humidity threshold
        if (humidity > HUMIDITY_THRESHOLD) {
            system("ssmtp -f 'your_email@example.com' -t 'your_email@example.com' -u 'your_email@example.com' -p 'your_password' -H 'Subject: 'Humidity Alert' ' <<< 'Humidity exceeded 80%.'");
        }

        // Sleep for 1 minute
        sleep(60);
    }

spi_cleanup:
    spiEnd(SPI_CHANNEL);

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (pi != 0) {
        gpioTerminate();
    }

    return 0;
}

