        spidev_close(spi);
    }
    exit(signum);
}

int read_adc() {
    unsigned char tx[1] = {0x01};
    unsigned char rx[3];
    int ret;

    ret = spidev_write_read(spi, tx, 1, rx, 3);
    if (ret < 0) {
        perror("spidev_write_read");
        return -1;
    }

    int adc_value = (rx[1] << 8) | rx[2];
    if (adc_value > 4095 || adc_value < 0) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

double convert_to_celsius(int adc_value) {
    double voltage = (adc_value * VREF) / 4095.0;
    double temperature = (voltage - 0.5) / 0.01;

    if (temperature < -40 || temperature > 125) {
        fprintf(stderr, "Temperature out of range: %.2fC\n", temperature);
        return -1.0;
    }

    return temperature;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi = spidev_open(SPI_DEV, 0);
    if (spi == NULL) {
        perror("spidev_open");
        return 1;
    }

    int ret = spidev_ioctl(spi, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("SPI_IOC_WR_MODE");
        goto spi_cleanup;
    }

    ret = spidev_ioctl(spi, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS);
    if (ret < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        goto spi_cleanup;
    }

    ret = spidev_ioctl(spi, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        goto spi_cleanup;
    }

    struct gpiod_chip *chip;
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto spi_cleanup;
    }

    cs_line = gpiod_line_request_by_name(chip, "gpio8", "CS", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!cs_line) {
        perror("gpiod_line_request_by_name");
        goto chip_cleanup;
    }

    gpiod_line_set_value(cs_line, 1);

    log_file = fopen(FILE_LOG, "a");
    if (!log_file) {
        perror("fopen");
        goto line_cleanup;
    }

    if (fseek(log_file, 0, SEEK_END) != 0) {
        perror("fseek");
        goto file_cleanup;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        gpiod_line_set_value(cs_line, 0);
        int adc_value = read_adc();
        gpiod_line_set_value(cs_line, 1);

        if (adc_value >= 0) {
            double temperature = convert_to_celsius(adc_value);
            if (temperature >= 0) {
                fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n",
                        now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                        now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, temperature);
            }
        }

        fflush(log_file);
        usleep(1000000); // 1 second delay
    }

file_cleanup:
    fclose(log_file);
line_cleanup:
    gpiod_line_free(cs_line);
chip_cleanup:
    gpiod_chip_put(chip);
spi_cleanup:
    spidev_close(spi);

    return 0;
}
