#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CS_PIN 8
#define LOG_FILE "impact_log.txt"
#define SAMPLE_RATE 100 // Hz
#define IMPACT_THRESHOLD 2.0 // g

int spiHandle;
FILE *logFile;

void handle_interrupt(int signum) {
    if (spiHandle != -1) {
        spiClose(spiHandle);
    }
    if (logFile != NULL) {
        fclose(logFile);
    }
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode.\n");
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    logFile = fopen(LOG_FILE, "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    while (1) {
        unsigned char tx[3] = {0x01, 0x80, 0x00};
        unsigned char rx[6];

        if (gpioWrite(CS_PIN, PI_LOW) < 0) {
            fprintf(stderr, "Failed to set CS pin low.\n");
            break;
        }

        if (spiXfer(spiHandle, tx, 3, rx, 6) < 0) {
            fprintf(stderr, "Failed SPI transfer.\n");
            break;
        }

        if (gpioWrite(CS_PIN, PI_HIGH) < 0) {
            fprintf(stderr, "Failed to set CS pin high.\n");
            break;
        }

        int x = ((rx[1] << 8) | rx[2]) & 0x3FF;
        int y = ((rx[3] << 8) | rx[4]) & 0x3FF;
        int z = ((rx[5] << 8) | rx[6]) & 0x3FF;

        double vx = (x * 3.3 / 1024.0 - 1.65) / 0.3;
        double vy = (y * 3.3 / 1024.0 - 1.65) / 0.3;
        double vz = (z * 3.3 / 1024.0 - 1.65) / 0.3;

        double magnitude = sqrt(vx * vx + vy * vy + vz * vz);

        fprintf(logFile, "%ld,%d,%d,%d,%f\n", ts.tv_sec, x, y, z, magnitude);

        if (magnitude > IMPACT_THRESHOLD) {
            fprintf(logFile, "IMPACT DETECTED\n");
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        usleep(1000000 / SAMPLE_RATE);
    }

    fclose(logFile);
    spiClose(spiHandle);
    gpioTerminate();

    return 0;
}

