This C program interfaces with an ADXL335 accelerometer using an MCP3008 ADC on a Raspberry Pi 4 Model B. It logs the raw ADC values for X, Y, and Z axes at 100 Hz, computes the acceleration magnitude, and flags impacts exceeding 2.0g. It includes robust error handling for pigpio initialization, SPI operations, and file I/O. The program also handles SIGINT by cleanly closing SPI, the log file, and terminating pigpio.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define CMD_REG 0xC0
#define DATA_REG 0xC1
#define SAMPLE_RATE 1000 // 1 second

int main() {
    int handle;
    FILE *log_file;
    char timestamp[32];
    int ir_adc, red_adc;
    int error_flag = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Open I2C bus
    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus. Sensor absent or uninitialized.\n");
        error_flag = 2;
        goto cleanup;
    }

    // Open log file
    log_file = fopen("biometric_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        error_flag = 2;
        goto cleanup;
    }

    // Write header row
    fprintf(log_file, "Timestamp,IR_ADC,RED_ADC,Error\n");

    // Main loop
    while (1) {
        // Trigger measurement
        if (i2cWriteReg(handle, CMD_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to write to command register.\n");
            error_flag = 1;
            goto cleanup;
        }

        // Read data
        if (i2cReadReg(handle, DATA_REG, &ir_adc, 2) < 0 || i2cReadReg(handle, DATA_REG + 2, &red_adc, 2) < 0) {
            fprintf(stderr, "Failed to read data from sensor.\n");
            error_flag = 1;
            goto cleanup;
        }

        // Log data
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, ir_adc, red_adc, error_flag);
        fflush(log_file);

        // Wait for next sample
        usleep(SAMPLE_RATE);
    }

cleanup:
    // Close I2C handle
    if (handle >= 0) {
        i2cClose(handle);
    }

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    return error_flag;
}

