#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define VOLTAGE_RANGE 3.3
#define FLOW_RATE_RANGE 5.0

FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (spi_channel >= 0) {
        spi_close(spi_channel);
    }
    pigpio_stop();
    exit(signum);
}

int main() {
    int spi_channel = -1;
    int spi_fd = -1;
    char log_filename[] = "flow_log.csv";

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    spi_channel = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_channel < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        pigpioStop();
        return 1;
    }

    log_file = fopen(log_filename, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        spiClose(spi_channel);
        pigpioStop();
        return 1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        uint8_t buffer[3];
        buffer[0] = 0; // Dummy byte for SPI transfer
        buffer[1] = (ADC_CHANNEL << 6) | 0x18; // Start conversion
        buffer[2] = 0; // Dummy byte for SPI transfer

        if (spiXfer(spi_channel, buffer, buffer, 3) != 3) {
            fprintf(stderr, "SPI transfer error.\n");
            continue;
        }

        uint16_t adc_value = (buffer[1] << 8) | buffer[2];

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent condition detected.\n");
            continue;
        }

        double voltage = (double)adc_value * VOLTAGE_RANGE / 1023.0;
        double flow_rate = voltage * FLOW_RATE_RANGE / VOLTAGE_RANGE;

        if (flow_rate < 0.0 || flow_rate > FLOW_RATE_RANGE) {
            fprintf(stderr, "Invalid flow rate detected: %.2f L/min.\n", flow_rate);
            continue;
        }

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        char flow_rate_str[10];
        sprintf(flow_rate_str, "%.6f", flow_rate);

        fprintf(log_file, "%s,%s\n", timestamp, flow_rate_str);
        fflush(log_file);

        clock_gettime(CLOCK_REALTIME, &ts);
        usleep(1000000); // Sleep for 1 second
    }

    handle_signal(0); // Clean up on exit
    return 0;
}

