This C program interfaces with a Honeywell SpiroQuant A+ ES1-005 Mass Flow Sensor using the pigpio library on a Raspberry Pi 4 Model B. It reads the analog signal via an external MCP3008 ADC over SPI, converts the ADC value to a flow rate, and logs the timestamp and flow rate to a CSV file every second. It includes robust error handling for pigpio initialization, SPI operations, ADC reads, and sensor-absent conditions. The program also ensures clean resource release on all exit paths, including handling SIGINT and SIGTERM signals.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x67
#define MEASUREMENT_CMD 0x6845
#define RESULT_LEN 6
#define TEMP_OFFSET 27315
#define PRESSURE_OFFSET 28672
#define TEMP_SCALE 0.01
#define PRESSURE_SCALE 0.0098
#define LOG_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL 5000 // 5 seconds

int i2c_fd;
FILE *log_file;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

void read_sensor_data() {
    char buffer[RESULT_LEN];
    int bytes_read;

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return;
    }

    if (write(i2c_fd, &MEASUREMENT_CMD, 2) != 2) {
        perror("Failed to write measurement command");
        return;
    }

    while (1) {
        bytes_read = read(i2c_fd, buffer, RESULT_LEN);
        if (bytes_read == RESULT_LEN) {
            break;
        } else if (bytes_read < 0) {
            perror("Failed to read sensor data");
            return;
        }
        sleep(1); // Retry after 1 second
    }

    uint16_t pressure_msb = (buffer[0] << 8) | buffer[1];
    uint16_t pressure_lsb = (buffer[2] << 8) | buffer[3];
    uint16_t temperature_msb = (buffer[4] << 8) | buffer[5];

    double pressure = (pressure_msb + pressure_lsb) * PRESSURE_SCALE + PRESSURE_OFFSET;
    double temperature = (temperature_msb * TEMP_SCALE) + TEMP_OFFSET;

    fprintf(log_file, "%ld,%.2f,%.2f\n", time(NULL), temperature, pressure);
    printf("Temperature: %.2f°C, Pressure: %.2f Pa\n", temperature, pressure);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
