#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x67
#define MEASUREMENT_CMD 0x6845
#define RESULT_LEN 6
#define TEMP_OFFSET 27315
#define PRESSURE_OFFSET 28672
#define TEMP_SCALE 0.01
#define PRESSURE_SCALE 0.0098
#define LOG_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL 5000 // 5 seconds

int i2c_fd;
FILE *log_file;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

void read_sensor_data() {
    char buffer[RESULT_LEN];
    int bytes_read;

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return;
    }

    if (write(i2c_fd, &MEASUREMENT_CMD, 2) != 2) {
        perror("Failed to write measurement command");
        return;
    }

    while (1) {
        bytes_read = read(i2c_fd, buffer, RESULT_LEN);
        if (bytes_read == RESULT_LEN) {
            break;
        } else if (bytes_read < 0) {
            perror("Failed to read sensor data");
            return;
        }
        sleep(1); // Retry after 1 second
    }

    uint16_t pressure_msb = (buffer[0] << 8) | buffer[1];
    uint16_t pressure_lsb = (buffer[2] << 8) | buffer[3];
    uint16_t temperature_msb = (buffer[4] << 8) | buffer[5];

    double pressure = (pressure_msb + pressure_lsb) * PRESSURE_SCALE + PRESSURE_OFFSET;
    double temperature = (temperature_msb * TEMP_SCALE) + TEMP_OFFSET;

    fprintf(log_file, "%ld,%.2f,%.2f\n", time(NULL), temperature, pressure);
    printf("Temperature: %.2f°C, Pressure: %.2f Pa\n", temperature, pressure);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        read_sensor_data();
        sleep(1); // Wait for 1 second before next sample
    }

    return 0;
}
