#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define SPI_SPEED 1000000
#define LOG_FILE "moisture_log.txt"

void handle_sigint(int signum) {
    if (spi != -1) {
        spiClose(spi);
    }
    gpioTerminate();
    exit(signum);
}

int main() {
    int spi = -1;
    FILE *log_file = NULL;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Open SPI channel
    spi = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi < 0) {
        fprintf(stderr, "Failed to open SPI channel %d.\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s.\n", LOG_FILE);
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Infinite loop to read moisture levels
    while (1) {
        uint8_t cmd = 0x01; // Start bit + single-ended conversion
        uint8_t adc_data[3];

        // Send command to ADC
        if (spiXfer(spi, &cmd, 1, adc_data, 3) != 3) {
            fprintf(stderr, "Failed to send command to ADC.\n");
            continue;
        }

        // Read ADC value
        uint16_t adc_value = (adc_data[1] << 8) | adc_data[2];

        // Validate ADC range
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d.\n", adc_value);
            continue;
        }

        // Log the reading
        time_t now = time(NULL);
        struct tm *now_tm = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", now_tm);
        fprintf(log_file, "%s,%d\n", timestamp, adc_value);

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    fclose(log_file);
    spiClose(spi);
    gpioTerminate();

    return 0;
}

