#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define BUZZER_PIN 18
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 10
#define SPI_CS_ACTIVE_LOW 1
#define SPI_CS_HIGH 0
#define SPI_CS_LOW 1
#define TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL 500
#define MAX_RETRIES 3

static int spi_fd;
static struct gpiod_chip *spi_chip;
static struct gpiod_line *spi_cs;
static struct gpiod_line *buzzer;

static void handle_sigint(int signum) {
    gpiod_line_set_value(buzzer, 0);
    gpiod_line_free(buzzer);
    gpiod_chip_put(spi_chip);
    close(spi_fd);
    exit(0);
}

static int read_adc(void) {
    unsigned char tx[3] = {0b00000001, 0b00000000, 0b00000000};
    unsigned char rx[3];
    int retries = 0;
    int adc_value = 0;

    while (retries < MAX_RETRIES) {
        gpiod_line_set_value(spi_cs, SPI_CS_LOW);
        int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx, &rx);
        gpiod_line_set_value(spi_cs, SPI_CS_HIGH);

        if (ret < 1) {
            fprintf(stderr, "SPI transfer failed, retrying...\n");
            retries++;
            continue;
        }

        adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        if (adc_value >= 0 && adc_value <= 1023) {
            break;
        }

        fprintf(stderr, "ADC value out of range, retrying...\n");
        retries++;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read valid ADC value after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    return adc_value;
}

static float read_temperature(void) {
    FILE *temp_file = fopen(TEMP_FILE, "r");
    if (!temp_file) {
        return 25.0;
    }

    float temp;
    if (fscanf(temp_file, "%f", &temp) != 1) {
        fclose(temp_file);
        return 25.0;
    }

    fclose(temp_file);
    return temp;
}

static void log_reading(int adc_value, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S,", timeinfo);

    fprintf(log_file, "%s%d,%f,%f,%f,%d\n", buffer, adc_value, voltage, compensated_voltage, temperature, flame_detected);
    fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        return 1;
    }

    spi_chip = gpiod_chip_open("/dev/gpiomem");
    if (!spi_chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    spi_cs = gpiod_line_request_any(spi_chip, "spi_cs", "spi_cs", 0);
    if (!spi_cs) {
        perror("Failed to request SPI CS line");
        gpiod_chip_put(spi_chip);
        close(spi_fd);
        return 1;
    }

    buzzer = gpiod_line_request_by_name(spi_chip, "gpio%d", BUZZER_PIN, "buzzer", 0);
    if (!buzzer) {
        perror("Failed to request buzzer GPIO line");
        gpiod_line_free(spi_cs);
        gpiod_chip_put(spi_chip);
        close(spi_fd);
        return 1;
    }

    gpiod_line_set_value(spi_cs, SPI_CS_HIGH);
    gpiod_line_set_value(buzzer, 0);

    float temperature = read_temperature();

    while (1) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            continue;
        }

        float voltage = (adc_value * 3.3) / 1023.0;
        float compensated_voltage = voltage + (temperature - 25.0) * 0.001;
        int flame_detected = compensated_voltage > 1.0;

        log_reading(adc_value, voltage, compensated_voltage, temperature, flame_detected);

        gpiod_line_set_value(buzzer, flame_detected);

        sleep(SAMPLE_INTERVAL / 1000);
    }

    gpiod_line_free(buzzer);
    gpiod_line_free(spi_cs);
    gpiod_chip_put(spi_chip);
    close(spi_fd);

    return 0;
}

