#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CHANNEL 0
#define JSON_FILE "water_levels.json"

int spiHandle;
FILE *jsonFile;

void spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    int result = spiXfer(spiHandle, tx, rx, len);
    if (result < 0) {
        fprintf(stderr, "SPI transfer error: %s\n", pigpio_error(result));
        return;
    }
}

void read_water_level() {
    unsigned char tx[3] = {0x01, 0x80 | CHANNEL << 4, 0x00};
    unsigned char rx[3];

    spi_transfer(tx, rx, 3);

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    float percentage = (float)adc_value / 1023.0 * 100.0;

    struct tm *time_info;
    time_t rawtime;
    time(&rawtime);
    time_info = localtime(&rawtime);

    fprintf(jsonFile, "{\"timestamp\": \"%04d-%02d-%02dT%02d:%02d:%02d.%03dZ\", \"water_level\": %.2f}\n",
            time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
            time_info->tm_hour, time_info->tm_min, time_info->tm_sec, time_info->tm_usec / 1000, percentage);

    fflush(jsonFile);

    if (percentage > WATER_LEVEL_THRESHOLD) {
        if (!gpioRead(LED_GPIO)) {
            gpioWrite(LED_GPIO, PI_ON);
        }
    } else if (percentage < 70) {
        if (gpioRead(LED_GPIO)) {
            gpioWrite(LED_GPIO, PI_OFF);
        }
    }
}

void handle_signal(int signum) {
    if (jsonFile) {
        fclose(jsonFile);
    }
    if (spiHandle >= 0) {
        spiClose(spiHandle);
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error(gpioInitialise()));
        exit(1);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error(gpioInitialise()));
        return 1;
    }

    spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", pigpio_error(spiHandle));
        gpioTerminate();
        return 1;
    }

    jsonFile = fopen(JSON_FILE, "a");
    if (!jsonFile) {
        fprintf(stderr, "Failed to open JSON file: %s\n", strerror(errno));
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    fprintf(jsonFile, "[");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_water_level();
        gpioDelay(100000); // 100ms delay
    }

    return 0;
}

