        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        spi_close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if file is newly created
    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
