        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        // Write to log file
        fprintf(log_file, "%s,%d,%.2f\n", timestamp, adc_value, flow_rate_lpm);

        // Sleep for 100 milliseconds
        usleep(SAMPLING_INTERVAL * 1000);
    }

    // Clean up resources
    fclose(log_file);
    spi_close(spi_fd);
    gpioTerminate();

    return 0;
}

