This C program reads airflow data from an analog Honeywell AWM7300V mass airflow sensor using an external MCP3008 10-bit ADC on a Raspberry Pi Zero W. It uses the pigpio library for GPIO and SPI operations, logs timestamped readings and converted flow rates in Liters Per Minute (LPM) to a comma-separated file named `airflow_log.csv`, and implements robust error handling for pigpio initialization, SPI transmission failures, and file I/O errors. It also ensures clean resource release on all exit paths, including graceful shutdown via SIGINT and SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define DRY_RAW 300
#define WET_RAW 700
#define THRESHOLD 30
#define LOG_INTERVAL 60
#define EMAIL_RECIPIENT "recipient@example.com"
#define MSMTP_CONFIG_FILE "/etc/msmtp.cf"

void handle_signal(int signum) {
    if (spi_close(SPI_CHANNEL) < 0) {
        fprintf(stderr, "Failed to close SPI channel %d\n", SPI_CHANNEL);
    }
    if (pi_stop() < 0) {
        fprintf(stderr, "Failed to stop pigpio\n");
    }
    exit(signum);
}

double calculate_moisture_percentage(int raw_value) {
    return (double)(raw_value - DRY_RAW) / (WET_RAW - DRY_RAW) * 100.0;
}

int main(int argc, char *argv[]) {
    if (argc != 8) {
        fprintf(stderr, "Usage: %s <spi_channel> <adc_channel> <dry_raw> <wet_raw> <threshold> <log_interval> <email_recipient> <msmtp_config_file>\n", argv[0]);
        return 1;
    }

    int spi_channel = atoi(argv[1]);
    int adc_channel = atoi(argv[2]);
    int dry_raw = atoi(argv[3]);
    int wet_raw = atoi(argv[4]);
    int threshold = atoi(argv[5]);
    int log_interval = atoi(argv[6]);
    char *email_recipient = argv[7];
    char *msmtp_config_file = argv[8];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (spi_open(spi_channel, 0, 500000, 0) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", spi_channel);
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    FILE *log_file = fopen("plant_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        int raw_value = spi_read(spi_channel, 1);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        double moisture_percentage = calculate_moisture_percentage(raw_value);
        char timestamp[20];
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage);
        fflush(log_file);

        if (moisture_percentage < threshold) {
            char email_body[100];
            snprintf(email_body, sizeof(email_body), "Soil moisture level is below threshold (%.2f%%).", moisture_percentage);
            char command[256];
            snprintf(command, sizeof(command), "msmtp -f 'Plant Monitor' -C %s %s < /dev/stdin", msmtp_config_file, email_recipient);
            FILE *email_pipe = popen(command, "w");
            if (!email_pipe) {
                fprintf(stderr, "Failed to send email\n");
            } else {
                fprintf(email_pipe, "%s", email_body);
                pclose(email_pipe);
            }
        }

        sleep(log_interval);
    }

    fclose(log_file);
    spi_close(spi_channel);
    pi_stop();

    return 0;
}

