#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <mcp3008.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "soil_moisture.log"

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int main(int argc, char *argv[]) {
    int spi_fd;
    int sample_rate = 1; // Default sample rate: 1 second
    FILE *log_file;
    int moisture_value;
    double moisture_percentage;

    if (argc > 1) {
        sample_rate = atoi(argv[1]);
        if (sample_rate <= 0) {
            fprintf(stderr, "Invalid sample rate. Using default (1 second).\n");
            sample_rate = 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    spi_fd = open_spi(SPI_DEVICE, SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device.\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        moisture_value = spi_read(spi_fd, SPI_CHANNEL);
        if (moisture_value < 0) {
            fprintf(stderr, "Error reading SPI value. Continuing...\n");
            continue;
        }

        moisture_percentage = (double)moisture_value / 1023.0 * 100.0;
        moisture_percentage = fmin(moisture_percentage, 100.0);

        struct tm *time_info;
        time_t rawtime;
        char timestamp[32];

        time(&rawtime);
        time_info = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

        fprintf(log_file, "%s, ADC Value: %d, Moisture %%: %.2f\n", timestamp, moisture_value, moisture_percentage);
        fflush(log_file);

        usleep(sample_rate * 1000000);
    }

    fclose(log_file);
    close(spi_fd);
    gpioTerminate();

    return 0;
}

