#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 10
#define SPI_CS_GPIO 8
#define SPI_MOSI_GPIO 10
#define SPI_MISO_GPIO 9
#define SPI_CLK_GPIO 11

#define DRY_ADC_VALUE 700
#define WET_ADC_VALUE 300

static int spi_fd = -1;

void cleanup_spi() {
    if (spi_fd != -1) {
        close(spi_fd);
        printf("SPI device closed.\n");
    }
    exit(EXIT_SUCCESS);
}

int main() {
