    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_line_request(chip, SPI_CS_GPIO, "SPI_CS", 0);
    if (!lines[0]) {
        perror("Failed to request SPI CS line");
        goto error_lines;
    }

    lines[1] = gpiod_line_request(chip, SPI_MOSI_GPIO, "SPI_MOSI", 0);
    if (!lines[1]) {
        perror("Failed to request SPI MOSI line");
        goto error_lines;
    }

    lines[2] = gpiod_line_request(chip, SPI_MISO_GPIO, "SPI_MISO", 0);
    if (!lines[2]) {
        perror("Failed to request SPI MISO line");
        goto error_lines;
    }

    lines[3] = gpiod_line_request(chip, SPI_CLK_GPIO, "SPI_CLK", 0);
    if (!lines[3]) {
        perror("Failed to request SPI CLK line");
        goto error_lines;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        goto error_lines;
    }

    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        goto error_spi;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        goto error_spi;
    }

    // Set up signal handler for SIGINT/SIGTERM
    struct sigaction sa;
    sa.sa_handler = cleanup_spi;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        uint8_t tx[3] = {0b00000001, 0b00000000, 0b00000000};
        uint8_t rx[3];

        ret = write(spi_fd, tx, 3);
        if (ret != 3) {
            perror("Failed to write to SPI device");
            goto error_spi;
        }

        ret = read(spi_fd, rx, 3);
        if (ret != 3) {
            perror("Failed to read from SPI device");
            goto error_spi;
        }

        uint16_t adc_value = (rx[1] << 8) | rx[2];
        float moisture_percentage = (adc_value - WET_ADC_VALUE) / (DRY_ADC_VALUE - WET_ADC_VALUE) * 100.0;
        moisture_percentage = fmax(0.0, fmin(100.0, moisture_percentage));

        printf("ADC Value: %d, Moisture Percentage: %.2f%%\n", adc_value, moisture_percentage);

        sleep(5);
    }

error_spi:
    close(spi_fd);
error_lines:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_free(lines[i]);
        }
    }
    gpiod_chip_put(chip);

    return EXIT_FAILURE;
}

