#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define PRESSURE_SENSOR_CHANNEL 0
#define PRESSURE_SENSOR_MIN_VOLTAGE 0.5
#define PRESSURE_SENSOR_MAX_VOLTAGE 4.5
#define PRESSURE_SENSOR_MIN_PRESSURE 10
#define PRESSURE_SENSOR_MAX_PRESSURE 150
#define PRESSURE_SENSOR_VOLTAGE_RANGE (PRESSURE_SENSOR_MAX_VOLTAGE - PRESSURE_SENSOR_MIN_VOLTAGE)
#define PRESSURE_SENSOR_PRESSURE_RANGE (PRESSURE_SENSOR_MAX_PRESSURE - PRESSURE_SENSOR_MIN_PRESSURE)

void handle_signal(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioGetErrorStr(pigtailGetError()));
    }
    exit(signum);
}

void read_pressure_sensor() {
    uint32_t adc_value;
    double voltage;
    double pressure;

    if (spiRead(PRESSURE_SENSOR_CHANNEL, &adc_value, 1) < 0) {
        fprintf(stderr, "Failed to read ADC value: %s\n", pigtailGetErrorStr(pigtailGetError()));
        return;
    }

    voltage = (double)adc_value * 3.3 / 1023;

    if (voltage < PRESSURE_SENSOR_MIN_VOLTAGE || voltage > PRESSURE_SENSOR_MAX_VOLTAGE) {
        fprintf(stderr, "ADC value out of range: %.2fV\n", voltage);
        return;
    }

    pressure = (voltage - PRESSURE_SENSOR_MIN_VOLTAGE) * PRESSURE_SENSOR_PRESSURE_RANGE / PRESSURE_SENSOR_VOLTAGE_RANGE + PRESSURE_SENSOR_MIN_PRESSURE;

    printf("%s: Pressure = %.2f kPa\n", iso8601_timestamp(), pressure);
}

char* iso8601_timestamp() {
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return buffer;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigtailGetErrorStr(pigtailGetError()));
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_pressure_sensor();
        sleep(1);
    }

    return 0;
}

