        return 1;
    }

    if ((spi_cs = gpiod_line_request_by_name(chip, "SPI0_CE0", "spi_cs", GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
        fprintf(stderr, "Failed to request SPI CS line\n");
        return 1;
    }

    if (gpiod_line_set_value(spi_cs, 1) < 0) {
        fprintf(stderr, "Failed to set SPI CS line value\n");
        return 1;
    }

    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        if (gpiod_line_set_value(spi_cs, 0) < 0) {
            fprintf(stderr, "Failed to set SPI CS line value\n");
            return 1;
        }

