        moisture_percentage = (adc_value - MIN_ADC_VALUE) / (float)(MAX_ADC_VALUE - MIN_ADC_VALUE) * 100.0;

        clock_gettime(CLOCK_REALTIME, &ts);
        printf("Timestamp: %ld.%09ld, ADC Value: %d, Moisture Percentage: %.2f%%\n",
