#define SPI_BITS 8
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define SPI_CMD_START 0b01100000
#define SPI_CMD_CONFIG 0b00000000
#define SPI_CMD_DATA 0b00000000
#define SPI_CMD_LEN 3
#define SPI_TIMEOUT 1000

static volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int main() {
    int spi_fd;
    struct spi_ioc_transfer spi_transfer;
    uint8_t spi_cmd[SPI_CMD_LEN] = {SPI_CMD_START, SPI_CMD_CONFIG, SPI_CMD_DATA};
    uint8_t spi_result[SPI_CMD_LEN];
    uint16_t moisture_value;
    float moisture_percentage;

    // Register signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Configure SPI
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        // Prepare SPI transfer
        memset(&spi_transfer, 0, sizeof(spi_transfer));
        spi_transfer.tx_buf = (unsigned long)spi_cmd;
        spi_transfer.rx_buf = (unsigned long)spi_result;
        spi_transfer.len = SPI_CMD_LEN;
        spi_transfer.delay_usecs = 0;
        spi_transfer.speed_hz = SPI_SPEED;
        spi_transfer.bits_per_word = SPI_BITS;

        // Perform SPI transfer
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
            perror("Failed SPI transfer");
            close(spi_fd);
            return EXIT_FAILURE;
        }

        // Extract 10-bit result
        moisture_value = (spi_result[1] << 8) | spi_result[2];

        // Calculate moisture percentage
        moisture_percentage = (moisture_value * 100.0) / 1023.0;

        // Clamp to 0-100 range
        if (moisture_percentage < 0.0) {
            moisture_percentage = 0.0;
        } else if (moisture_percentage > 100.0) {
            moisture_percentage = 100.0;
        }

        // Log moisture percentage
        printf("Moisture percentage: %.2f%%\n", moisture_percentage);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    close(spi_fd);
    return EXIT_SUCCESS;
}
