#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEV_PATH "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define NUM_CHANNELS 4
#define VREF 3.3

static gpiod_line *cs_line;
static struct spi_ioc_transfer spi_transfer[NUM_CHANNELS];
static FILE *csv_file;

void cleanup(int signum) {
    if (csv_file) {
        fclose(csv_file);
    }
    if (cs_line) {
        gpiod_line_free(cs_line);
    }
    exit(signum);
}

int main() {
    int fd;
    struct spi_ioc_transfer *transfer;
    uint8_t buffer[NUM_CHANNELS];
    uint32_t result;
    char filename[] = "environmental_data.csv";
    struct timespec ts;

    // Open CSV file for writing
    csv_file = fopen(filename, "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        return 1;
    }

    // Initialize libgpiod
    if (gpiod_chip_open("/dev/gpiochip0", &cs_line) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO8 for chip select
    if (gpiod_line_request(cs_line, "MCP3008_CS", GPIOD_LINE_DIRECTION_OUTPUT, 0) < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    // Open SPI device
    fd = open(SPI_DEV_PATH, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI mode or speed");
        return 1;
    }

    // Set up SPI transfers
    for (int i = 0; i < NUM_CHANNELS; i++) {
        spi_transfer[i].tx_buf = (unsigned long) &buffer[i];
        spi_transfer[i].rx_buf = (unsigned long) &buffer[i];
        spi_transfer[i].len = 3;
        spi_transfer[i].delay_usecs = 0;
        spi_transfer[i].speed_hz = SPI_SPEED;
        spi_transfer[i].bits_per_word = 8;
    }

    // Signal handling
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Set chip select low
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("Failed to set chip select low");
            cleanup(1);
        }

        // Perform SPI transfers
        for (int i = 0; i < NUM_CHANNELS; i++) {
            spi_transfer[i].tx_buf = (unsigned long) &buffer[i];
            spi_transfer[i].rx_buf = (unsigned long) &buffer[i];
            spi_transfer[i].len = 3;
            spi_transfer[i].delay_usecs = 0;
            spi_transfer[i].speed_hz = SPI_SPEED;
            spi_transfer[i].bits_per_word = 8;

            if (ioctl(fd, SPI_IOC_MESSAGE(1), &spi_transfer[i]) < 1) {
                perror("Failed SPI transfer");
                cleanup(1);
            }

            // Calculate voltage
            result = (buffer[i] << 8) | buffer[i + 1];
            double voltage = (double)result * VREF / 1024.0;

            // Log timestamped voltage
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(csv_file, "%ld.%09ld,%f\n", (long)ts.tv_sec, (long)ts.tv_nsec, voltage);
        }

        // Set chip select high
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Failed to set chip select high");
            cleanup(1);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    cleanup(0);

    return 0;
}

