#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define BUFFER_SIZE 20
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CE0 0
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11
#define GPIO_PUMP 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define SAMPLE_INTERVAL 5000

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int log_index = 0;

void handle_signal(int signum) {
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio.\n");
    }
    if (spiClose(spiChannel) < 0) {
        fprintf(stderr, "Failed to close SPI channel.\n");
    }
    if (gpioWrite(GPIO_PUMP, 0) < 0) {
        fprintf(stderr, "Failed to turn off pump.\n");
    }
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    int spiChannel = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spiChannel < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_PUMP, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for pump.\n");
        spiClose(spiChannel);
        gpioTerminate();
        return 1;
    }

    int pump_state = 0;
    int last_moisture_level = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        uint8_t tx[3] = {0x01, 0x80, 0x00};
        uint8_t rx[3];

        if (spiXfer(spiChannel, tx, 3, rx) < 0) {
            fprintf(stderr, "Failed to transfer SPI data.\n");
            continue;
        }

        int moisture_level = (rx[1] << 8) | rx[2];

        if (moisture_level < LOW_THRESHOLD && pump_state == 0) {
            if (gpioWrite(GPIO_PUMP, 1) < 0) {
                fprintf(stderr, "Failed to turn on pump.\n");
            }
            pump_state = 1;
        } else if (moisture_level > HIGH_THRESHOLD && pump_state == 1) {
            if (gpioWrite(GPIO_PUMP, 0) < 0) {
                fprintf(stderr, "Failed to turn off pump.\n");
            }
            pump_state = 0;
        }

        time_t timestamp = time(NULL);
        LogEntry entry = {timestamp, moisture_level, pump_state};
        log_buffer[log_index] = entry;
        log_index = (log_index + 1) % BUFFER_SIZE;

        printf("Timestamp: %ld, Moisture Level: %d, Pump State: %d\n",
               timestamp, moisture_level, pump_state);

        sleep(SAMPLE_INTERVAL / 1000);
    }

    spiClose(spiChannel);
    gpioTerminate();

    return 0;
}

