#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MAX30102_ADDR 0x57
#define PART_ID_REG 0xFF
#define MODE_CONFIG_REG 0x06
#define SPO2_CONFIG_REG 0x08
#define LED1_PA_REG 0x09
#define LED2_PA_REG 0x0A
#define FIFO_DATA_REG 0x07

#define RED_CHANNEL 0
#define IR_CHANNEL 1

#define SP_THRESHOLD 95
#define HR_THRESHOLD 100

void handle_sigint(int signum) {
    if (pi != NULL) {
        i2cUnexport(1);
        pigpioStop();
    }
    exit(0);
}

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    FILE *log = fopen("health_log.txt", "a");
    if (log != NULL) {
        fprintf(log, "%s\n", msg);
        fclose(log);
    }
}

int main() {
    int pi;
    int i2c_handle;
    char part_id[3];
    char sp_data[3];
    char ir_data[3];
    double spo2;
    int heart_rate;
    struct tm *time_info;
    char timestamp[20];

    if ((pi = pigpio_start()) < 0) {
        log_error("Failed to start pigpio");
        return 1;
    }

    if (i2cOpen(1, MAX30102_ADDR, &i2c_handle) < 0) {
        log_error("Failed to open I2C bus");
        pigpioStop();
        return 1;
    }

    if (i2cReadI2CBlockData(i2c_handle, PART_ID_REG, 1, part_id) < 0) {
        log_error("Failed to read Part ID");
        i2cClose(i2c_handle);
        pigpioStop();
        return 1;
    }

    if (part_id[0] != 0x15) {
        log_error("Sensor not found or incorrect Part ID");
        i2cClose(i2c_handle);
        pigpioStop();
        return 1;
    }

    if (i2cWriteI2CBlockData(i2c_handle, MODE_CONFIG_REG, 1, (char[]){0x40}) < 0) {
        log_error("Failed to reset sensor");
        i2cClose(i2c_handle);
        pigpioStop();
        return 1;
    }

    if (i2cWriteI2CBlockData(i2c_handle, MODE_CONFIG_REG, 1, (char[]){0x03}) < 0) {
        log_error("Failed to configure SpO2 mode");
        i2cClose(i2c_handle);
        pigpioStop();
        return 1;
    }

    if (i2cWriteI2CBlockData(i2c_handle, SPO2_CONFIG_REG, 1, (char[]){0x27}) < 0) {
        log_error("Failed to set SPO2 configuration");
        i2cClose(i2c_handle);
        pigpioStop();
        return 1;
    }

    if (i2cWriteI2CBlockData(i2c_handle, LED1_PA_REG, 1, (char[]){0x24}) < 0) {
        log_error("Failed to set LED1 pulse amplitude");
        i2cClose(i2c_handle);
        pigpioStop();
        return 1;
    }

    if (i2cWriteI2CBlockData(i2c_handle, LED2_PA_REG, 1, (char[]){0x24}) < 0) {
        log_error("Failed to set LED2 pulse amplitude");
        i2cClose(i2c_handle);
        pigpioStop();
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        if (i2cReadI2CBlockData(i2c_handle, FIFO_DATA_REG, 6, (char[]){sp_data, ir_data}) < 0) {
            log_error("Failed to read FIFO data");
            continue;
        }

        // Convert raw data to SpO2 and heart rate
        // (This is a placeholder for actual conversion logic)
        spo2 = (double)sp_data[0] / 255.0;
        heart_rate = (int)ir_data[0];

        time_info = localtime(&time(NULL));
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", time_info);

        if (spo2 < SP_THRESHOLD) {
            log_error(sprintf("SpO2: %.2f%% @ %s", spo2 * 100, timestamp));
        }

        if (heart_rate > HR_THRESHOLD) {
            log_error(sprintf("Heart Rate: %d BPM @ %s", heart_rate, timestamp));
        }

        usleep(1000000); // Sleep for 1 second
    }

    handle_sigint(0); // Cleanup on exit

    return 0;
}

