#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_TIMEOUT 1000
#define LOG_FILE "analog_log.csv"

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int read_adc(int channel) {
    uint8_t tx_buf[3] = {0x01, (channel << 4) | 0x18, 0x00};
    uint8_t rx_buf[3];
    int spi_result;

    spi_result = spi_read(SPI_CHANNEL, tx_buf, 3, rx_buf, SPI_TIMEOUT);
    if (spi_result != 3) {
        fprintf(stderr, "SPI read error: %d\n", spi_result);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

double calculate_voltage(int adc_value) {
    return (double)adc_value * VREF / 1024.0;
}

void log_voltage(int channel, double voltage) {
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s,%d,%.3f\n", buffer, channel, voltage);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (spi_open(SPI_CHANNEL, SPI_MODE, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    FILE *file = fopen(LOG_FILE, "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spi_close(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    fprintf(file, "Timestamp,Channel,Voltage\n");
    fclose(file);

    while (!stop) {
        for (int channel = 0; channel < 3; channel++) {
            int adc_value = read_adc(channel);
            if (adc_value >= 0) {
                double voltage = calculate_voltage(adc_value);
                log_voltage(channel, voltage);
            }
        }

        usleep(500000); // Sleep for 500 ms
    }

    spi_close(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

