#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE_GPIO 8
#define ADC_CHANNEL 0
#define GAS_THRESHOLD 500
#define BUZZER_GPIO 24
#define SAMPLING_INTERVAL 500

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CE_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI CE GPIO mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SPI_CE_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set SPI CE GPIO state.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, 1000000, 0) < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (!stop) {
        uint32_t adc_value;
        if (spiRead(SPI_CHANNEL, &adc_value, 2) < 0) {
            fprintf(stderr, "Failed to read ADC value.\n");
            spiClose(SPI_CHANNEL);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        adc_value = (adc_value >> 8) & 0xFF; // Extract 8-bit ADC value

        if (adc_value < GAS_THRESHOLD) {
            if (gpioWrite(BUZZER_GPIO, 0) < 0) {
                fprintf(stderr, "Failed to turn off buzzer.\n");
                spiClose(SPI_CHANNEL);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        } else {
            if (gpioWrite(BUZZER_GPIO, 1) < 0) {
                fprintf(stderr, "Failed to turn on buzzer.\n");
                spiClose(SPI_CHANNEL);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        usleep(SAMPLING_INTERVAL * 1000); // Sleep for 500 ms
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return EXIT_SUCCESS;
}

