#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_ADDR 0x48
#define I2C_DEV "/dev/i2c-1"
#define BASELINE_SAMPLES 10
#define BASELINE_INTERVAL 50
#define POLL_INTERVAL 200
#define THRESHOLD_PERCENTAGE 0.8
#define RELAY_GPIO 17
#define REED_GPIO 27
#define LOG_FILE "/var/log/door_events.log"

static int i2c_fd;
static struct gpiod_line *relay_line, *reed_line;
static int baseline_samples[BASELINE_SAMPLES];
static int baseline_sum = 0;
static int baseline_avg = 0;
static int threshold = 0;

void handle_signal(int signum) {
    gpiod_line_request_free(relay_line);
    gpiod_line_request_free(reed_line);
    close(i2c_fd);
    exit(signum);
}

int read_adc() {
    int ret;
    char buf[3];

    ret = read(i2c_fd, buf, 3);
    if (ret != 3) {
        fprintf(stderr, "Failed to read ADC value: %d\n", ret);
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

void calibrate_threshold() {
    int i;

    for (i = 0; i < BASELINE_SAMPLES; i++) {
        baseline_samples[i] = read_adc();
        baseline_sum += baseline_samples[i];
        usleep(BASELINE_INTERVAL * 1000);
    }

    baseline_avg = baseline_sum / BASELINE_SAMPLES;
    threshold = baseline_avg * THRESHOLD_PERCENTAGE;
}

int main() {
    struct gpiod_line_request *req;
    struct gpiod_line_consumer *consumer;
    struct gpiod_line_consumer_config config;
    struct timespec ts;
    int adc_value;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    req = gpiod_line_request_alloc(RELAY_GPIO, "relay", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!req) {
        perror("Failed to allocate relay line request");
        close(i2c_fd);
        return 1;
    }

    consumer = gpiod_line_consumer_alloc(req, &config);
    if (!consumer) {
        perror("Failed to allocate relay line consumer");
        gpiod_line_request_free(req);
        close(i2c_fd);
        return 1;
    }

    relay_line = gpiod_line_consumer_get_line(consumer);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_line_consumer_free(consumer);
        gpiod_line_request_free(req);
        close(i2c_fd);
        return 1;
    }

    req = gpiod_line_request_alloc(REED_GPIO, "reed", GPIOD_LINE_DIRECTION_INPUT);
    if (!req) {
        perror("Failed to allocate reed line request");
        gpiod_line_consumer_free(consumer);
        gpiod_line_request_free(req);
        close(i2c_fd);
        return 1;
    }

    consumer = gpiod_line_consumer_alloc(req, &config);
    if (!consumer) {
        perror("Failed to allocate reed line consumer");
        gpiod_line_request_free(req);
        gpiod_line_consumer_free(consumer);
        close(i2c_fd);
        return 1;
    }

    reed_line = gpiod_line_consumer_get_line(consumer);
    if (!reed_line) {
        perror("Failed to get reed line");
        gpiod_line_consumer_free(consumer);
        gpiod_line_request_free(req);
        close(i2c_fd);
        return 1;
    }

    calibrate_threshold();

    while (1) {
        adc_value = read_adc();
        if (adc_value < 0) {
            continue;
        }

        if (adc_value < threshold) {
            gpiod_line_set_value(relay_line, 1);
            sleep(3);
            gpiod_line_set_value(relay_line, 0);

            if (gpiod_line_get_value(reed_line) == 0) {
                ts.tv_sec = time(NULL);
                ts.tv_nsec = 0;
                fprintf(stdout, "door opened at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
            } else {
                ts.tv_sec = time(NULL);
                ts.tv_nsec = 0;
                fprintf(stdout, "door not opened at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    return 0;
}

