    struct spi_ioc_transfer spi_transfer = {
        .tx_buf = (unsigned long) &spi_transfer.tx_buf,
        .rx_buf = (unsigned long) &spi_transfer.rx_buf,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 1,
    };

    spi_transfer.tx_buf = (unsigned long) &spi_transfer.tx_buf;
    spi_transfer.tx_buf[0] = 0x01;
    spi_transfer.tx_buf[1] = (0x08 | CHANNEL) << 4;
    spi_transfer.tx_buf[2] = 0x00;

