        perror("fseek");
        fclose(log_file);
        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_free(cs_lines[i]);
        }
        spidev_close(spi);
        return 1;
    }

    char header[] = "timestamp,sensor1,sensor2,sensor3\n";
    if (ftell(log_file) == 0) {
        fwrite(header, sizeof(header), 1, log_file);
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        int sensor_values[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_set_value(cs_lines[i], 0);
            sensor_values[i] = read_sensor(i);
            gpiod_line_set_value(cs_lines[i], 1);
