            }
        }

        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor_values[0], sensor_values[1], sensor_values[2]);
        fflush(log_file);

        sleep(5);
    }

    fclose(log_file);
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_free(cs_lines[i]);
    }
    spidev_close(spi);

    return 0;
