This C program reads soil moisture sensor values from three MCP3008 chips connected to a Raspberry Pi 5, logs the readings every 5 seconds into a CSV file, and handles errors and signals gracefully.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_INTERVAL 60

#define SPI_CHANNEL 0
#define SPI_CE_PIN 8
#define SPI_CLK_FREQ 1000000
#define SPI_MODE 0

#define ADC_MAX 1023
#define ADC_MIN 0

#define DRY_BOUND 200
#define WET_BOUND 800

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int read_adc(int channel) {
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        if (spi_read(channel, 1) == 0) {
            result = spi_read(channel, 1);
            if (result >= 0) {
                break;
            }
        }
        retries--;
        usleep(100000); // 100 ms delay
    }

    if (result < 0) {
        fprintf(stderr, "Failed to read ADC after %d retries.\n", 3 - retries);
        return -1;
    }

    return result;
}

void map_adc_to_percentage(int adc_value, int *percentage) {
    if (adc_value < DRY_BOUND) {
        *percentage = 0;
    } else if (adc_value > WET_BOUND) {
        *percentage = 100;
    } else {
        *percentage = (adc_value - DRY_BOUND) * 100 / (WET_BOUND - DRY_BOUND);
    }
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int interval = DEFAULT_INTERVAL;

    if (argc > 1) {
        if (strcmp(argv[1], "-t") == 0) {
            threshold = atoi(argv[2]);
        } else if (strcmp(argv[1], "-d") == 0) {
            duration = atoi(argv[2]);
        } else if (strcmp(argv[1], "-s") == 0) {
            interval = atoi(argv[2]);
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (spiOpen(SPI_CE_PIN, SPI_CHANNEL, SPI_CLK_FREQ, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO18 as output.\n");
        spiClose(SPI_CE_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("irrigation.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        spiClose(SPI_CE_PIN);
        gpioTerminate();
        return 1;
    }

    while (!stop_flag) {
        int adc_value = read_adc(SPI_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        int moisture_percentage;
        map_adc_to_percentage(adc_value, &moisture_percentage);

        fprintf(log_file, "Moisture: %d%%\n", moisture_percentage);

        if (moisture_percentage < threshold) {
            fprintf(log_file, "Activating pump...\n");
            if (gpioWrite(18, PI_ON) < 0) {
                fprintf(stderr, "Failed to activate pump.\n");
            }
            sleep(duration);
            if (gpioWrite(18, PI_OFF) < 0) {
                fprintf(stderr, "Failed to deactivate pump.\n");
            }
            fprintf(log_file, "Deactivating pump...\n");
        }

        sleep(interval);
    }

    if (gpioWrite(18, PI_OFF) < 0) {
        fprintf(stderr, "Failed to deactivate pump on exit.\n");
    }

    spiClose(SPI_CE_PIN);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

