This C program uses the pigpio library to control a submersible 12V water pump connected to GPIO18 (active-high) and reads moisture levels from a Vegetronix VH400 soil moisture sensor connected to an MCP3008 SPI ADC. It accepts command-line options for threshold, duration, and interval, logs moisture readings and pump activation/deactivation with timestamps, and handles SPI errors with retries. On SIGINT or SIGTERM, it shuts off the pump, closes SPI, terminates pigpio, and exits cleanly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_TIMEOUT 1000
#define EMA_ALPHA 0.1
#define THRESHOLD_MARGIN 0.2

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int spi_read(int channel) {
    int result;
    unsigned char cmd[3] = {0x01, 0x80, 0x00};
    unsigned char data[3];

    if (spi_write(channel, cmd, 3, data, 3, SPI_SPEED, SPI_TIMEOUT) != 3) {
        perror("SPI write failed");
        return -1;
    }

    result = (data[1] << 8) | data[2];
    return result;
}

int main() {
    int spi_fd;
    int raw_value, ema_value;
    double threshold;
    FILE *log_file;

    if (gpioInitialise() < 0) {
        perror("pigpio initialization failed");
        return 1;
    }

    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_fd < 0) {
        perror("SPI open failed");
        gpioTerminate();
        return 1;
    }

    ema_value = 0;
    threshold = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen("/var/log/sound_events.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (!stop_flag) {
        raw_value = spi_read(spi_fd);
        if (raw_value < 0) {
            continue;
        }

        ema_value = EMA_ALPHA * raw_value + (1 - EMA_ALPHA) * ema_value;
        threshold = ema_value * (1 + THRESHOLD_MARGIN);

        if (raw_value > threshold) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d.%09ld %d\n",
                    ts.tv_sec / 3600 % 24, ts.tv_sec / 60 % 60, ts.tv_sec % 60,
                    ts.tv_sec / 3600 % 24, ts.tv_sec / 60 % 60, ts.tv_sec % 60,
                    ts.tv_nsec, raw_value);
            fflush(log_file);
        }

        usleep(10000);
    }

    fclose(log_file);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

