#define SAMPLE_INTERVAL 100 // in milliseconds

int i2c_fd;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(1);
}

void handle_sigint(int signum) {
    cleanup();
}

int main() {
    signal(SIGINT, handle_sigint);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C device");
        cleanup();
    }

    // Configure control byte for single-ended mode on channel 0 (AIN0)
    uint8_t control_byte = 0x01; // Single-ended mode on channel 0
    if (write(i2c_fd, &control_byte, 1) != 1) {
        perror("Failed to write control byte");
        cleanup();
    }

    // Perform a dummy read to get the previous conversion result
    uint8_t dummy_read;
    if (read(i2c_fd, &dummy_read, 1) != 1) {
        perror("Failed to read dummy value");
        cleanup();
    }

    while (1) {
        uint8_t sample;
        if (read(i2c_fd, &sample, 1) != 1) {
            perror("Failed to read sample value");
            cleanup();
        }

        printf("AIN0 sample: %u\n", sample);

        usleep(SAMPLE_INTERVAL * 1000); // Sleep for 100 ms
    }

    cleanup();
    return 0;
}

