#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

#define I2C_ADDR 0x48
#define ADC_CHANNEL 0
#define BUFFER_SIZE 10
#define THRESHOLD 500
#define GPIO_PIN 27

int buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_count = 0;

void handle_signal(int signum) {
    if (pigpio_stop() < 0) {
        syslog(LOG_ERR, "Failed to stop pigpio");
    }
    if (wiringPiI2CUnexport(I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to unexport I2C device");
    }
    if (pigpio_set_mode(GPIO_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
    }
    if (pigpio_write(GPIO_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO to LOW");
    }
    exit(signum);
}

void read_adc() {
    int16_t adc_value;
    int voltage;

    if (wiringPiI2CReadReg16(I2C_ADDR, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to read ADC register");
        return;
    }

    adc_value = wiringPiI2CReadReg16(I2C_ADDR, 0x00);
    voltage = (adc_value * 3300) / 32768; // Convert to millivolts

    if (voltage < 0 || voltage > 3300) {
        syslog(LOG_ERR, "Invalid voltage reading: %d mV", voltage);
        return;
    }

    double magnetic_field = (voltage - 2500) / 1.4; // Convert to Gauss

    buffer[buffer_head] = (int)magnetic_field;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    buffer_count = (buffer_count < BUFFER_SIZE) ? buffer_count + 1 : BUFFER_SIZE;

    double rolling_average = 0;
    for (int i = 0; i < buffer_count; i++) {
        rolling_average += buffer[(buffer_tail + i) % BUFFER_SIZE];
    }
    rolling_average /= buffer_count;

    if (rolling_average > THRESHOLD) {
        if (pigpio_write(GPIO_PIN, 1) < 0) {
            syslog(LOG_ERR, "Failed to set GPIO to HIGH");
        } else {
            syslog(LOG_INFO, "Threshold exceeded: %.2f Gauss (GPIO27 HIGH)", rolling_average);
        }
    } else {
        if (pigpio_write(GPIO_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to set GPIO to LOW");
        } else {
            syslog(LOG_INFO, "Magnetic field: %.2f Gauss (GPIO27 LOW)", rolling_average);
        }
    }
}

int main() {
    if (openlog("hall_sensor_monitor", LOG_PID, LOG_USER) < 0) {
        syslog(LOG_ERR, "Failed to open syslog");
        return 1;
    }

    if (pigpio_start() < 0) {
        syslog(LOG_ERR, "Failed to start pigpio");
        closelog();
        return 1;
    }

    if (wiringPiI2CSetup(I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set up I2C device");
        pigpio_stop();
        closelog();
        return 1;
    }

    if (pigpio_set_mode(GPIO_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        pigpio_stop();
        wiringPiI2CUnexport(I2C_ADDR);
        closelog();
        return 1;
    }

    if (pigpio_write(GPIO_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO to LOW");
        pigpio_stop();
        wiringPiI2CUnexport(I2C_ADDR);
        closelog();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_adc();
        sleep(1);
    }

    return 0;
}

