This C program uses the pigpio library to monitor a Honeywell SS49E linear Hall-effect sensor connected to an ADS1115 ADC on a Raspberry Pi 3 Model B+. It reads the sensor's voltage output, converts it to magnetic field strength in Gauss, and maintains a rolling average of the last 10 readings. If the rolling average exceeds a compile-time threshold (500 Gauss), it drives GPIO27 HIGH to signal motor shutdown. The program logs all readings, threshold events, and errors via syslog. It handles pigpio initialization failure, I2C/ADC read failures, and invalid voltage readings. On SIGINT/SIGTERM, it stops the I2C handle, resets GPIO27 to LOW, terminates pigpio, and closes syslog.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define WATERING_THRESHOLD 300
#define WATERING_INTERVAL 60
#define PUMP_DURATION 10
#define GPIO_PUMP 18

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int read_adc(int channel) {
    uint8_t cmd[3] = {0x01, (channel & 7) << 4, 0};
    uint8_t data[3];

    if (spiXfer(0, cmd, 3, data, 3) != 3) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    int adc_value = ((data[1] & 0x0F) << 8) | data[2];

    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

void water_pump(int duration) {
    if (gpioWrite(GPIO_PUMP, PI_ON) < 0) {
        fprintf(stderr, "Failed to activate pump\n");
        return;
    }

    sleep(duration);

    if (gpioWrite(GPIO_PUMP, PI_OFF) < 0) {
        fprintf(stderr, "Failed to deactivate pump\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (spiOpen(0, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_PUMP, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for pump\n");
        spiClose(0);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("watering_events.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(0);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        int moisture_level = read_adc(ADC_CHANNEL);

        if (moisture_level < 0) {
            continue;
        }

        if (moisture_level < WATERING_THRESHOLD) {
            water_pump(PUMP_DURATION);
            fprintf(log_file, "Watering event at %s, moisture level: %d\n", ctime(&time(NULL)), moisture_level);
        }

        sleep(WATERING_INTERVAL);
    }

    fclose(log_file);
    spiClose(0);
    gpioTerminate();

    return 0;
}

