This C program reads soil moisture from a Vegetronix VH400 sensor using an MCP3008 ADC connected to the Raspberry Pi Zero W. It activates a 12V submersible water pump when the ADC reading drops below a threshold of 300, runs the pump for 10 seconds, and then reads the moisture level again every 60 seconds. It logs timestamps and moisture levels to 'watering_events.txt'. The program includes robust SPI communication error handling and graceful GPIO initialization failure recovery. The pump is deactivated immediately on any error or shutdown path, with clean resource release on SIGINT/SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define SPI_BUS 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define ADC_FULL_SCALE 1023
#define INTENSITY_SCALE 10

int spiHandle = -1;

void handle_sigint(int signum) {
    if (spiHandle != -1) {
        spiClose(spiHandle);
    }
    pigpioStop();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    spiHandle = spiOpen(SPI_BUS, SPI_MODE, SPI_SPEED);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        pigpioStop();
        return 1;
    }

    while (1) {
        uint8_t cmd[3] = {0x01, (ADC_CHANNEL << 6) | 0x18, 0x00};
        uint8_t data[3];

        if (spiXfer(spiHandle, cmd, 3, data, 3) != 3) {
            fprintf(stderr, "SPI transfer failed, retrying...\n");
            continue;
        }

        uint16_t adcValue = ((data[1] & 0x03) << 8) | data[2];
        int intensityLevel = (int)((double)adcValue / ADC_FULL_SCALE * INTENSITY_SCALE);

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        printf("%02d:%02d:%02d - ADC Value: %d - Intensity Level: %d\n",
               now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, adcValue, intensityLevel);

        sleep(1);
    }

    if (spiHandle != -1) {
        spiClose(spiHandle);
    }

    pigpioStop();
    return 0;
}

