#define SPI_TIMEOUT 100
#define PWM_FREQUENCY 1000
#define READ_INTERVAL 100

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetSignalFunc(SIGINT, handle_signal);
    gpioSetSignalFunc(SIGTERM, handle_signal);

    int spiHandle = spiOpen(0, SPI_SPEED, SPI_MODE);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(PWM_GPIO, SPI_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        uint8_t buffer[3] = {0x01, 0x80 | (ADC_CHANNEL << 4), 0x00};
        uint8_t result[3];

        if (spiXfer(spiHandle, buffer, 3, result, 3) != 3) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        uint16_t adcValue = ((result[1] & 0x0F) << 8) | result[2];
        printf("ADC Value: %d\n", adcValue);

        if (gpioPWM(PWM_GPIO, adcValue) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
        }

        usleep(READ_INTERVAL * 1000);
    }

    gpioPWM(PWM_GPIO, 0);
    spiClose(spiHandle);
    gpioTerminate();

    return 0;
}
