#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x48
#define ADC_GAIN 4.096
#define ADC_RESOLUTION (2 * 1024) // 12-bit ADC
#define ADC_OFFSET 1.65 // Zero-gauss output voltage
#define ADC_SENSITIVITY 0.001 // 1.0 mV/Gauss
#define THRESHOLD 100.0 // Default threshold in Gauss
#define LED_PIN 17
#define BLINK_INTERVAL 50 // 50 ms on / 50 ms off
#define BLINK_DURATION 1000 // 1 second

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int read_adc(int addr) {
    int fd;
    char buffer[3];
    int result;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire I2C bus");
        close(fd);
        return -1;
    }

    if (read(fd, buffer, 3) != 3) {
        perror("Failed to read ADC data");
        close(fd);
        return -1;
    }

    result = ((buffer[0] << 8) | buffer[1]) & 0x0FFF;
    close(fd);

    return result;
}

void blink_led(int pin, int duration) {
    gpioSetMode(pin, PI_OUTPUT);
    for (int i = 0; i < duration / BLINK_INTERVAL; i++) {
        gpioWrite(pin, PI_ON);
        usleep(BLINK_INTERVAL * 1000);
        gpioWrite(pin, PI_OFF);
        usleep(BLINK_INTERVAL * 1000);
    }
    gpioWrite(pin, PI_OFF);
}

int main(int argc, char *argv[]) {
    int threshold = THRESHOLD;
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        int adc_value = read_adc(I2C_ADDR);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        float voltage = (adc_value * ADC_GAIN) / ADC_RESOLUTION;
        float gauss = (voltage - ADC_OFFSET) / ADC_SENSITIVITY;

        printf("Magnetic field strength: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            blink_led(LED_PIN, BLINK_DURATION);
        }

        usleep(100000); // 100 ms
    }

    gpioTerminate();
    return 0;
}

