#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <signal.h>
#include <mraa/spi.h>
#include <mraa/gpio.h>
#include <mraa/aio.h>
#include <paho-mqtt/MQTTClient.h>

#define SPI_CHANNEL 0
#define SPI_CLK_MHZ 1
#define SPI_CE_GPIO 8
#define SPI_MODE 0
#define SPI_BITS 8
#define HUMIDITY_THRESHOLD_LOW 30
#define HUMIDITY_THRESHOLD_HIGH 35
#define MQTT_BROKER "broker.hivemq.com"
#define MQTT_PORT 1883
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"

static int spiHandle = -1;
static int relayPin = -1;
static int aioHandle = -1;
static MQTTClient *client = NULL;
static MQTTClient_connectOptions connOpts = MQTTClient_connectOptions_initializer;

void handle_signal(int signum) {
    if (relayPin != -1) {
        mraa_gpio_write(relayPin, 0);
        mraa_gpio_close(relayPin);
    }
    if (spiHandle != -1) {
        mraa_spi_stop(spiHandle);
        mraa_spi_close(spiHandle);
    }
    if (aioHandle != -1) {
        mraa_aio_close(aioHandle);
    }
    if (client != NULL) {
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(client);
    }
    pigpio_stop();
    exit(signum);
}

int read_soil_moisture() {
    uint8_t buffer[3];
    int result = mraa_spi_transfer(spiHandle, buffer, 3);
    if (result != 3) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }
    int moisture = (buffer[1] << 8) | buffer[2];
    return moisture;
}

void on_message_callback(void *context, char *topicName, int topicLen, MQTTString *message) {
    char *command = (char *)message->len;
    if (strcmp(command, "pump_on") == 0) {
        mraa_gpio_write(relayPin, 1);
    } else if (strcmp(command, "pump_off") == 0) {
        mraa_gpio_write(relayPin, 0);
    }
}

int main() {
    if (pigpio_start() < 0) {
        syslog(LOG_ERR, "Failed to start pigpio");
        return 1;
    }

    if (mraa_init() != MRAA_SUCCESS) {
        syslog(LOG_ERR, "Failed to initialize mraa");
        return 1;
    }

    spiHandle = mraa_spi_init(SPI_CHANNEL);
    if (spiHandle < 0) {
        syslog(LOG_ERR, "Failed to initialize SPI");
        return 1;
    }

    mraa_spi_mode(spiHandle, SPI_MODE);
    mraa_spi_frequency(spiHandle, SPI_CLK_MHZ * 1000000);

    relayPin = mraa_gpio_init(SPI_CE_GPIO);
    if (relayPin < 0) {
        syslog(LOG_ERR, "Failed to initialize relay GPIO");
        return 1;
    }

    mraa_gpio_dir(relayPin, MRAA_GPIO_OUT);
    mraa_gpio_write(relayPin, 0);

    aioHandle = mraa_aio_init(0);
    if (aioHandle < 0) {
        syslog(LOG_ERR, "Failed to initialize ADC");
        return 1;
    }

    connOpts.keepAliveInterval = 20;
    connOpts.cleansession = 1;
    client = MQTTClient_create("client-id", MQTT_BROKER, MQTT_PORT, NULL, NULL);
    if (client == NULL) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        return 1;
    }

    MQTTClient_setCallbacks(client, NULL, NULL, on_message_callback, NULL);

    int rc = MQTTClient_connect(client, &connOpts);
    if (rc != MRAA_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        return 1;
    }

    rc = MQTTClient_subscribe(client, MQTT_TOPIC_PUMP_CONTROL, 0);
    if (rc != MRAA_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int moisture = read_soil_moisture();
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to read soil moisture");
            continue;
        }

        if (moisture < HUMIDITY_THRESHOLD_LOW) {
            mraa_gpio_write(relayPin, 1);
        } else if (moisture > HUMIDITY_THRESHOLD_HIGH) {
            mraa_gpio_write(relayPin, 0);
        }

        MQTTString msg = MQTTString_initializer;
        MQTTString_set(&msg, "%d", moisture);
        MQTTClient_publishMessage(client, MQTT_TOPIC_SOIL_MOISTURE, &msg, 0, 0);
        MQTTString_free(&msg);

        sleep(60);
    }

    return 0;
}

