#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_DEV_PATH "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 10
#define SPI_CS_ACTIVE_LOW 1
#define SPI_CS_HIGH 0
#define SPI_CS_LOW 1

#define ADC_CHANNEL 0
#define ADC_CONFIG_SINGLE_ENDED 0x80
#define ADC_CONFIG_CHANNEL(channel) ((channel & 0x07) << 4)

#define VREF 3.3

static volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

int main() {
    int fd;
    struct spi_ioc_transfer tr;
    uint8_t tx_buf[3] = {0x01, ADC_CONFIG_CHANNEL(ADC_CHANNEL) | ADC_CONFIG_SINGLE_ENDED, 0x00};
    uint8_t rx_buf[3];
    double voltage;

    // Register signal handler
    signal(SIGINT, handle_sigint);

    // Open SPI device
    fd = open(SPI_DEV_PATH, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI mode or speed");
        close(fd);
        return 1;
    }

    // Configure SPI transfer
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS;

    while (!stop_flag) {
        // Send SPI transfer
        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
            perror("Failed to send SPI message");
            close(fd);
            return 1;
        }

        // Extract 10-bit ADC value
        uint16_t raw_value = (rx_buf[1] << 8) | rx_buf[2];

        // Calculate voltage
        voltage = (double)raw_value * VREF / 1024.0;

        // Print raw value and voltage
        printf("Raw Value: %d, Voltage: %.2f V\n", raw_value, voltage);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    close(fd);
    return 0;
}

