#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define MOTOR_PIN1 17
#define MOTOR_PIN2 27
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define THRESHOLD 500
#define PWM_FREQUENCY 100
#define PWM_DUTY_MAX 1023

int spi_fd;

void handle_signal(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (pi_stop()) {
        fprintf(stderr, "Failed to stop pigpio cleanly.\n");
    }
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

int read_adc(int channel) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long) &channel,
        .rx_buf = (unsigned long) &channel,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("SPI read failed");
        return -1;
    }

    return (channel << 8) | channel;
}

void log_event(int adc_value) {
    FILE *file = fopen("vibration_log.txt", "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    fprintf(file, "%s - ADC Value: %d\n", asctime(timeinfo), adc_value);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE_0) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD_8) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS_PER_WORD_8) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to configure SPI device");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (pi_set_PWM_frequency(MOTOR_PIN1, PWM_FREQUENCY) < 0 ||
        pi_set_PWM_frequency(MOTOR_PIN2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency.\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        if (adc_value > THRESHOLD) {
            int duty_cycle = (adc_value - THRESHOLD) * PWM_DUTY_MAX / (1023 - THRESHOLD);
            pi_set_PWM_dutycycle(MOTOR_PIN1, duty_cycle);
            pi_set_PWM_dutycycle(MOTOR_PIN2, duty_cycle);
            log_event(adc_value);
        } else {
            pi_set_PWM_dutycycle(MOTOR_PIN1, 0);
            pi_set_PWM_dutycycle(MOTOR_PIN2, 0);
        }

        usleep(10000);
    }

    close(spi_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

