#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>

#define MAX9814_SPI_DEV "/dev/spidev0.0"
#define MAX9814_I2C_ADDR 0x23
#define BH1750_I2C_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES 0x11
#define BH1750_RESULT_LEN 2
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define LOG_INTERVAL 5000 // 5 seconds
#define LOG_FILE "tamper_log.csv"

int spi_fd;
int i2c_fd;
FILE *log_file;

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(0);
}

void handle_signal(int signum) {
    cleanup();
}

int read_adc(int channel) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long) &channel,
        .rx_buf = (unsigned long) &channel,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer failed");
        return -1;
    }

    return channel;
}

int read_bh1750() {
    char cmd[2] = {BH1750_CONTINUOUS_HIGH_RES, 0};
    if (write(i2c_fd, cmd, 1) != 1) {
        perror("Failed to write to BH1750");
        return -1;
    }

    usleep(180000); // Wait 180 ms

    char result[BH1750_RESULT_LEN];
    if (read(i2c_fd, result, BH1750_RESULT_LEN) != BH1750_RESULT_LEN) {
        perror("Failed to read from BH1750");
        return -1;
    }

    return (result[0] << 8) | result[1];
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_fd = open(MAX9814_SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");

    while (1) {
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        int sound_level = read_adc(0);
        int light_level = read_bh1750();

        if (sound_level < 0 || light_level < 0) {
            fprintf(log_file, "%d,%d,%d,-1\n", now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec);
        } else {
            fprintf(log_file, "%d,%d,%d,0\n", now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec);
        }

        fflush(log_file);
        sleep(LOG_INTERVAL / 1000); // Sleep for 5 seconds
    }

    cleanup();
    return 0;
}

