#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_BUFFER_SIZE 3
#define SPI_CMD 0b11000000
#define SPI_CHANNEL_0 0b00000000
#define SPI_CHANNEL_1 0b00000001
#define SPI_CHANNEL_2 0b00000010
#define SPI_CHANNEL_3 0b00000011
#define SPI_CHANNEL_4 0b00000100
#define SPI_CHANNEL_5 0b00000101
#define SPI_CHANNEL_6 0b00000110
#define SPI_CHANNEL_7 0b00000111
#define SPI_READ 0b00000001
#define SPI_WRITE 0b00000000
#define SPI_RETRY_COUNT 3
#define HUMIDITY_THRESHOLD 30
#define GPIO_PUMP 17

volatile sig_atomic_t shutdown = 0;

void handle_signal(int signum) {
    shutdown = 1;
}

int spi_read(int channel) {
    int retries = 0;
    int result = -1;
    uint8_t spi_buffer[SPI_BUFFER_SIZE] = {SPI_CMD | (channel << 4) | SPI_READ, 0, 0};

    while (retries < SPI_RETRY_COUNT) {
        if (wiringPiSPIDataRW(SPI_CHANNEL, spi_buffer, SPI_BUFFER_SIZE) == SPI_BUFFER_SIZE) {
            result = (spi_buffer[1] << 8) | spi_buffer[2];
            break;
        }
        retries++;
    }

    return result;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to initialize SPI.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (wiringPiSPISetupChipSelect(SPI_CHANNEL, 0) < 0) {
        fprintf(stderr, "Failed to set SPI chip select.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PUMP, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for pump.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!shutdown) {
        int moisture_value = spi_read(SPI_CHANNEL_0);

        if (moisture_value >= 0) {
            double moisture_percentage = (double)moisture_value / 1023.0 * 100.0;
            printf("Moisture: %.2f%% at %s\n", moisture_percentage, ctime(&time(NULL)));

            if (moisture_percentage < HUMIDITY_THRESHOLD) {
                if (gpioWrite(GPIO_PUMP, PI_ON) < 0) {
                    fprintf(stderr, "Failed to activate pump.\n");
