                    fprintf(stderr, "Failed to deactivate pump.\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read moisture value.\n");
        }

        sleep(60);
    }

    if (gpioWrite(GPIO_PUMP, PI_OFF) < 0) {
        fprintf(stderr, "Failed to deactivate pump during shutdown.\n");
    }

    wiringPiSPIDeinit();
    gpioTerminate();

    return EXIT_SUCCESS;
}
