    if (mcp3008Init(SPI_CHANNEL) < 0) {
        fprintf(stderr, "Failed to initialize MCP3008.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for fan.\n");
        mcp3008DeInit();
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("air_quality.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioSetMode(FAN_GPIO, PI_INPUT);
        mcp3008DeInit();
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp,co2_ppm,fan_state\n");

