            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        double co2_ppm = 0.5 * adc_value - 50;
        int fan_state = co2_ppm > CO2_THRESHOLD ? 1 : 0;

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s,%f,%d\n", timestamp, co2_ppm, fan_state);

        if (fan_state) {
            if (gpioWrite(FAN_GPIO, 1) < 0) {
                fprintf(stderr, "Failed to turn on fan.\n");
            }
        } else {
            if (gpioWrite(FAN_GPIO, 0) < 0) {
                fprintf(stderr, "Failed to turn off fan.\n");
            }
        }

        sleep(SAMPLING_INTERVAL / 1000);
    }

    fclose(log_file);
    gpioSetMode(FAN_GPIO, PI_INPUT);
    mcp3008DeInit();
    gpioTerminate();

    return 0;
}

