#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define SPI_SPEED 1000000
#define DEBOUNCE_DELAY 1000
#define PROXIMITY_THRESHOLD 20
#define GPIO_RELAY 17
#define LOG_FILE "door_events.log"

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *relay_line;

static void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void cleanup() {
    if (sensor_line) {
        gpiod_line_free(sensor_line);
    }
    if (relay_line) {
        gpiod_line_free(relay_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
}

static void log_event(const char *event) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        handle_error("Failed to open log file");
    }

    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - %s\n",
            now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
            now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, event);

    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        handle_error("Failed to initialize pigpio");
    }

    chip = gpiod_chip_open("/dev/gpiomem");
    if (!chip) {
        handle_error("Failed to open GPIO chip");
    }

    sensor_line = gpiod_line_request_any(chip, "sensor", GPIOD_LINE_DIRECTION_IN);
    if (!sensor_line) {
        handle_error("Failed to request sensor line");
    }

    relay_line = gpiod_line_request_any(chip, "relay", GPIOD_LINE_DIRECTION_OUT);
    if (!relay_line) {
        handle_error("Failed to request relay line");
    }

    if (gpiod_line_set_value(relay_line, 0) < 0) {
        handle_error("Failed to set relay line value");
    }

    while (1) {
        int adc_value = spiRead(ADC_CHANNEL, SPI_SPEED);
        if (adc_value < 0) {
            handle_error("Failed to read ADC value");
        }

        if (adc_value < PROXIMITY_THRESHOLD) {
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                handle_error("Failed to set relay line value");
            }
            log_event("Proximity detected, relay energized");
            usleep(DEBOUNCE_DELAY * 1000);
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                handle_error("Failed to set relay line value");
            }
        }

        usleep(100 * 1000); // 100 ms polling interval
    }

    cleanup();
    gpioTerminate();
    return 0;
}

