#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define PWM_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define NUM_SENSORS 3
#define ADC_RANGE 1023
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_INTERVAL 5000 // 5 seconds

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int main() {
    FILE *log_file;
    int spi_handle;
    int pwm_handle;
    int raw_values[NUM_SENSORS];
    int avg_value;
    int duty_cycle;
    char timestamp[32];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    // Set up PWM for valve control
    pwm_handle = pigpio_pwm_start(PWM_PIN, PWM_FREQUENCY, PWM_RANGE);
    if (pwm_handle < 0) {
        fprintf(stderr, "Failed to set up PWM\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_pwm_stop(PWM_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        // Read ADC values
        int valid_readings = 0;
        avg_value = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            uint8_t cmd[3] = {0x01, 0x80 | (i << 4), 0x00};
            uint8_t data[3];
            if (spiXfer(spi_handle, cmd, 3, data, 3) != 3) {
                fprintf(stderr, "Failed to read ADC value for sensor %d\n", i);
                continue;
            }
            raw_values[i] = (data[1] << 8) | data[2];
            avg_value += raw_values[i];
            valid_readings++;
        }

        // Calculate average and map to duty cycle
        if (valid_readings > 0) {
            avg_value /= valid_readings;
            duty_cycle = (ADC_RANGE - avg_value) * PWM_RANGE / ADC_RANGE;
        } else {
            duty_cycle = 0;
        }

        // Log data
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
        fprintf(log_file, "%s\tRaw Values: ", timestamp);
        for (int i = 0; i < NUM_SENSORS; i++) {
            fprintf(log_file, "%d ", raw_values[i]);
        }
        fprintf(log_file, "\tAverage: %d\tDuty Cycle: %d\n", avg_value, duty_cycle);

        // Set PWM duty cycle
        pigpio_pwm_dutycycle(PWM_PIN, duty_cycle);

        // Sleep for 5 seconds
        sleep(LOG_INTERVAL / 1000);
    }

    // Graceful shutdown
    pigpio_pwm_dutycycle(PWM_PIN, 0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

