#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CMD_START 0b11
#define SPI_CMD_SINGLE_ENDED 0b00
#define SPI_CMD_CHANNEL_0 0b000
#define SPI_CMD_FORMAT (SPI_CMD_START | SPI_CMD_SINGLE_ENDED | SPI_CMD_CHANNEL_0)
#define SPI_CMD_LENGTH 3
#define SPI_CMD_BUFFER_SIZE 4
#define SPI_CMD_BUFFER[0] = SPI_CMD_FORMAT
#define SPI_CMD_BUFFER[1] = 0
#define SPI_CMD_BUFFER[2] = 0
#define SPI_CMD_BUFFER[3] = 0
#define SPI_CMD_BUFFER_LEN 3
#define SPI_READ_BUFFER_SIZE 4
#define SPI_READ_BUFFER[0] = 0
#define SPI_READ_BUFFER[1] = 0
#define SPI_READ_BUFFER[2] = 0
#define SPI_READ_BUFFER[3] = 0
#define SPI_READ_BUFFER_LEN 4
#define SPI_RETRY_COUNT 5
#define SPI_BACKOFF_FACTOR 2
#define MOISTURE_PERCENTAGE_MAX 1023

void handle_signal(int signum) {
    if (spi != -1) {
        spi_close(spi);
    }
    gpioTerminate();
    exit(signum);
}

int read_adc(int spi_handle) {
    int retry = 0;
    int backoff = 1;
    int adc_value = 0;

    while (retry < SPI_RETRY_COUNT) {
        if (spi_write_read(spi_handle, SPI_CMD_BUFFER, SPI_CMD_BUFFER_LEN, SPI_READ_BUFFER, SPI_READ_BUFFER_LEN) == SPI_CMD_BUFFER_LEN) {
            // Extract 10-bit ADC value from the 4-byte read buffer
            adc_value = ((SPI_READ_BUFFER[1] & 0x03) << 8) | SPI_READ_BUFFER[2];
            if (adc_value >= 0 && adc_value <= MOISTURE_PERCENTAGE_MAX) {
                return adc_value;
            }
        }
        retry++;
        if (retry < SPI_RETRY_COUNT) {
            usleep(backoff * 1000); // Exponential backoff
            backoff *= SPI_BACKOFF_FACTOR;
        }
    }
    return -1; // Persistent SPI error
}

int main() {
    int spi = -1;
    int adc_value = 0;
    struct timespec sleep_duration = {0, 50000000}; // 5 seconds

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    spi = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi == -1) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *file = fopen("soil_data.txt", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for logging.\n");
        spi_close(spi);
        gpioTerminate();
        return 1;
    }

    while (1) {
        adc_value = read_adc(spi);
        if (adc_value != -1) {
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            fprintf(file, "%ld.%09ld: %d\n", now.tv_sec, now.tv_nsec / 1000, adc_value);
        } else {
            fprintf(stderr, "SPI read failed, skipping reading.\n");
        }
        nanosleep(&sleep_duration, NULL);
    }

    fclose(file);
    spi_close(spi);
    gpioTerminate();
    return 0;
}

