#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <gpiod.h>
#include <mcp3008.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 100

#define CONFIG_FILE "theremin_config.txt"

struct theremin_config {
    int trig_pin;
    int echo_pin;
    int pwm_pin;
    int pwm_freq;
    int pwm_duty_min;
    int pwm_duty_max;
};

static struct theremin_config config = {
    .trig_pin = TRIG_PIN,
    .echo_pin = ECHO_PIN,
    .pwm_pin = PWM_PIN,
    .pwm_freq = PWM_FREQ,
    .pwm_duty_min = PWM_DUTY_MIN,
    .pwm_duty_max = PWM_DUTY_MAX,
};

static struct gpiod_chip *chip;
static struct gpiod_line *trig_line, *echo_line, *pwm_line;
static int pwm_fd;

static void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void cleanup() {
    if (trig_line) {
        gpiod_line_free(trig_line);
    }
    if (echo_line) {
        gpiod_line_free(echo_line);
    }
    if (pwm_line) {
        gpiod_line_free(pwm_line);
    }
    if (pwm_fd >= 0) {
        close(pwm_fd);
    }
    gpiod_chip_put(chip);
}

static int read_config() {
    FILE *config_file = fopen(CONFIG_FILE, "r");
    if (!config_file) {
        return 0;
    }

    if (fscanf(config_file, "%d %d %d %d %d %d",
               &config.trig_pin, &config.echo_pin, &config.pwm_pin,
               &config.pwm_freq, &config.pwm_duty_min, &config.pwm_duty_max) != 6) {
        fclose(config_file);
        return 0;
    }

    fclose(config_file);
    return 1;
}

static void write_config() {
    FILE *config_file = fopen(CONFIG_FILE, "w");
    if (!config_file) {
        handle_error("Failed to open config file for writing");
    }

    fprintf(config_file, "%d %d %d %d %d %d\n",
            config.trig_pin, config.echo_pin, config.pwm_pin,
            config.pwm_freq, config.pwm_duty_min, config.pwm_duty_max);

    fclose(config_file);
}

static int read_distance() {
    int trig_fd = gpiod_line_get_request(trig_line, "theremin_trig");
    if (trig_fd < 0) {
        handle_error("Failed to request GPIO line for trigger");
    }

    int echo_fd = gpiod_line_get_request(echo_line, "theremin_echo");
    if (echo_fd < 0) {
        handle_error("Failed to request GPIO line for echo");
    }

    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);

    int echo_start = -1, echo_end = -1;
    while (gpiod_line_get_value(echo_line) == 0) {
        echo_start = gpiod_line_get_value(echo_line);
        if (echo_start < 0) {
            handle_error("Failed to read echo start");
        }
    }

    while (gpiod_line_get_value(echo_line) == 1) {
        echo_end = gpiod_line_get_value(echo_line);
        if (echo_end < 0) {
            handle_error("Failed to read echo end");
        }
    }

    int duration = echo_end - echo_start;
    if (duration <= 0) {
        handle_error("Invalid echo duration");
    }

    int distance = (duration * 34300) / 2; // Speed of sound in cm/s
    distance /= 10000; // Convert to cm

    close(trig_fd);
    close(echo_fd);

    return distance;
}

static int read_volume() {
    int adc_fd = open("/dev/spidev0.0", O_RDWR);
    if (adc_fd < 0) {
        handle_error("Failed to open SPI device");
    }

    int result = mcp3008_read(adc_fd, 0);
    if (result < 0) {
        handle_error("Failed to read ADC value");
    }

    close(adc_fd);

    return result;
}

static void set_frequency(int frequency) {
    char freq_path[256];
    snprintf(freq_path, sizeof(freq_path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", config.pwm_pin);

    int duty_cycle = (frequency - 220) * (config.pwm_duty_max - config.pwm_duty_min) / (880 - 220) + config.pwm_duty_min;
    if (duty_cycle < config.pwm_duty_min) {
        duty_cycle = config.pwm_duty_min;
    } else if (duty_cycle > config.pwm_duty_max) {
        duty_cycle = config.pwm_duty_max;
    }

    FILE *freq_file = fopen(freq_path, "w");
    if (!freq_file) {
        handle_error("Failed to open PWM duty cycle file");
    }

    fprintf(freq_file, "%d\n", duty_cycle);
    fclose(freq_file);
}

int main() {
    if (read_config()) {
        printf("Loaded configuration from %s\n", CONFIG_FILE);
    } else {
        printf("No configuration found, using defaults\n");
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        handle_error("Failed to open GPIO chip");
    }

    trig_line = gpiod_line_request_any(chip, "trig", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!trig_line) {
        handle_error("Failed to request GPIO line for trigger");
    }

    echo_line = gpiod_line_request_any(chip, "echo", GPIOD_LINE_DIRECTION_INPUT);
    if (!echo_line) {
        handle_error("Failed to request GPIO line for echo");
    }

    pwm_line = gpiod_line_request_any(chip, "pwm", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!pwm_line) {
        handle_error("Failed to request GPIO line for PWM");
    }

    pwm_fd = open("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", O_WRONLY);
    if (pwm_fd < 0) {
        handle_error("Failed to open PWM duty cycle file");
    }

    while (1) {
        int distance = read_distance();
        if (distance < 0) {
            printf("Failed to read distance, holding last valid state\n");
            continue;
        }

        int frequency = 220 + (distance * (880 - 220)) / 100; // Map distance to frequency
        set_frequency(frequency);

        int volume = read_volume();
        if (volume < 0) {
            printf("Failed to read volume, holding last valid state\n");
            continue;
        }

        int duty_cycle = (volume * (config.pwm_duty_max - config.pwm_duty_min)) / 1023 + config.pwm_duty_min;
        if (duty_cycle < config.pwm_duty_min) {
            duty_cycle = config.pwm_duty_min;
        } else if (duty_cycle > config.pwm_duty_max) {
            duty_cycle = config.pwm_duty_max;
        }

        write(pwm_fd, &duty_cycle, sizeof(duty_cycle));

        printf("Distance: %d cm, Frequency: %d Hz, Volume: %d\n", distance, frequency, volume);

        sleep(1);
    }

    cleanup();
    return 0;
}

