#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_FREQ 1000000
#define SPI_MODE 0
#define AQI_THRESHOLD 100
#define AQI_MAX 500
#define AQI_MIN 0
#define AQI_RANGE (AQI_MAX - AQI_MIN)
#define ADC_MAX 1023
#define ADC_MIN 0
#define ADC_RANGE (ADC_MAX - ADC_MIN)
#define RETRY_COUNT 3
#define RETRY_DELAY 1000

FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (spi_channel_open(SPI_CHANNEL, SPI_FREQ, SPI_MODE) >= 0) {
        spi_channel_close(SPI_CHANNEL);
    }
    pigpio_stop();
    exit(signum);
}

int read_adc(int channel) {
    int spi_fd = spi_channel_open(SPI_CHANNEL, SPI_FREQ, SPI_MODE);
    if (spi_fd < 0) {
        perror("spi_channel_open");
        return -1;
    }

    uint8_t cmd[3] = {0x01, 0x08 | (channel << 4), 0x00};
    uint8_t resp[3];
    int retry = 0;

    while (retry < RETRY_COUNT) {
        if (spi_write(spi_fd, cmd, 3) != 3) {
            perror("spi_write");
            if (retry < RETRY_COUNT - 1) {
                sleep(RETRY_DELAY / 1000);
            }
            retry++;
        } else {
            if (spi_read(spi_fd, resp, 3) != 3) {
                perror("spi_read");
                if (retry < RETRY_COUNT - 1) {
                    sleep(RETRY_DELAY / 1000);
                }
                retry++;
            } else {
                spi_channel_close(SPI_CHANNEL);
                return ((resp[1] << 8) | resp[2]) & 0x3FF;
            }
        }
    }

    spi_channel_close(SPI_CHANNEL);
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if (gpioSetMode(18, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }

    log_file = fopen("air_quality.log", "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            perror("read_adc");
            continue;
        }

        int aqi = (int)((double)adc_value / ADC_RANGE * AQI_RANGE) + AQI_MIN;

        if (aqi > AQI_THRESHOLD) {
            if (gpioWrite(18, PI_ON) < 0) {
                perror("gpioWrite");
            }
        } else {
            if (gpioWrite(18, PI_OFF) < 0) {
                perror("gpioWrite");
            }
        }

        fprintf(log_file, "%s AQI: %d\n", ctime(&time(NULL)), aqi);
        fflush(log_file);

        sleep(5);
    }

    return 0;
}

