#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define LOG_FILE "alcohol_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY 100

static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void handle_signal(int signum) {
    if (line) {
        gpiod_line_free(line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    close(spi_fd);
    exit(signum);
}

int read_adc(int channel) {
    unsigned char tx[3] = {0x01, (channel << 4) | 0x80, 0x00};
    unsigned char rx[3];
    int ret;

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx, &rx);
        if (ret < 1) {
            if (retry < MAX_RETRIES - 1) {
                usleep(RETRY_DELAY * 1000);
                continue;
            }
            fprintf(stderr, "Failed to read ADC: %s\n", strerror(errno));
            return -1;
        }
        break;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    // Check for sensor-absent condition
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Sensor absent or disconnected.\n");
        return -1;
    }

    return adc_value;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0) {
        perror("Failed to set SPI mode");
        goto spi_error;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_8) < 0) {
        perror("Failed to set bits per word");
        goto spi_error;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &1000000) < 0) {
        perror("Failed to set SPI speed");
        goto spi_error;
    }

    chip = gpiod_chip_open("/dev/gpiomem");
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto spi_error;
    }

    line = gpiod_line_request_any(chip, "CE0", GPIOD_LINE_DIRECTION_OUT);
    if (!line) {
        perror("Failed to request GPIO line");
        goto chip_error;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto line_error;
    }

    while (1) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            continue;
        }

        double ppm = (adc_value * 0.5) - 10.0;
        char status[50];
        if (ppm > 50) {
            strcpy(status, "Alcohol detected! Limit exceeded.");
        } else if (ppm < 20) {
            strcpy(status, "Sobriety confirmed.");
        } else {
            strcpy(status, "Alcohol level within acceptable range.");
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&ts.tv_sec));

        fprintf(log_file, "%s, ADC: %d, PPM: %.2f, Status: %s\n", timestamp, adc_value, ppm, status);
        fflush(log_file);

        sleep(1);
    }

line_error:
    gpiod_line_free(line);
chip_error:
    gpiod_chip_put(chip);
spi_error:
    close(spi_fd);
    return 1;
}

