#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GPIO_CE0 8
#define GPIO_CLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_PUMP 18
#define THRESHOLD 300
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 60000

void spi_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        exit(EXIT_FAILURE);
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (spiChipSelect(SPI_CHANNEL, GPIO_CE0) < 0) {
        fprintf(stderr, "Failed to set SPI chip select.\n");
        spiClose(SPI_CHANNEL);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void spi_close() {
    spiClose(SPI_CHANNEL);
    gpioTerminate();
}

int read_sensor() {
    uint8_t cmd[3] = {0x01, 0x80, 0x00}; // Start bit, channel 0, no clock stretching
    uint8_t data[3];

    if (spiXfer(SPI_CHANNEL, cmd, 3, data) != 3) {
        fprintf(stderr, "Failed to read from sensor.\n");
        return -1;
    }

    int moisture_value = (data[1] << 8) | data[2];
    return moisture_value;
}

void log_reading(int moisture_value, int pump_status) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Moisture: %d, Pump: %s\n", buffer, moisture_value, pump_status ? "ON" : "OFF");
    fclose(log_file);
}

int main() {
    spi_init();

    gpioSetMode(GPIO_PUMP, PI_OUTPUT);
    gpioWrite(GPIO_PUMP, 0); // Start with pump off

    while (1) {
        int moisture_value = read_sensor();
        if (moisture_value >= 0) {
            int pump_status = (moisture_value < THRESHOLD) ? 1 : 0;
            if (pump_status != gpioRead(GPIO_PUMP)) {
                gpioWrite(GPIO_PUMP, pump_status);
            }
            log_reading(moisture_value, pump_status);
        }

        sleep(SAMPLE_INTERVAL / 1000);
    }

    spi_close();
    return 0;
}

