#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <mcp3008.h>

#define MIN_SPEED 50
#define MAX_SPEED 255
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11
#define SPI_CE0 8
#define POT_CHANNEL_1 0
#define POT_CHANNEL_2 1

volatile sig_atomic_t stop = 0;

void cleanup(int signum) {
    stop = 1;
    gpioTerminate();
    mcp3008_close();
    exit(0);
}

double log_map(int value, int min_val, int max_val, double min_out, double max_out) {
    double ratio = (double)(value - min_val) / (double)(max_val - min_val);
    return min_out + (max_out - min_out) * log(1 + ratio);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (mcp3008_init(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_MOSI, SPI_MISO, SPI_SCLK, SPI_CE0) < 0) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    int pot_value_1, pot_value_2;
    double speed_factor_1, speed_factor_2;

    while (!stop) {
        pot_value_1 = mcp3008_read(POT_CHANNEL_1);
        pot_value_2 = mcp3008_read(POT_CHANNEL_2);

        speed_factor_1 = log_map(pot_value_1, 0, 1023, 0.5, 1.5);
        speed_factor_2 = log_map(pot_value_2, 0, 1023, 0.5, 1.5);

        int speed_1 = MIN_SPEED + (int)((MAX_SPEED - MIN_SPEED) * speed_factor_1);
        int speed_2 = MIN_SPEED + (int)((MAX_SPEED - MIN_SPEED) * speed_factor_2);

        // Move Motor 1 forward and Motor 2 backward
        gpioSetMode(18, PI_OUTPUT);
        gpioSetMode(23, PI_OUTPUT);
        gpioSetMode(24, PI_OUTPUT);
        gpioSetMode(25, PI_OUTPUT);

        gpioPWM(18, 0);
        gpioPWM(24, 0);

        for (int i = MIN_SPEED; i <= MAX_SPEED; i += 10) {
            gpioPWM(18, i * speed_factor_1);
            gpioPWM(24, i * speed_factor_2);
            gpioWrite(23, 0);
            gpioWrite(25, 1);
            usleep(100000);
        }

        for (int i = MAX_SPEED; i >= MIN_SPEED; i -= 10) {
            gpioPWM(18, i * speed_factor_1);
            gpioPWM(24, i * speed_factor_2);
            gpioWrite(23, 0);
            gpioWrite(25, 1);
            usleep(100000);
        }

        usleep(2000000); // Hold constant speed for 2 seconds

        // Pause for 5 seconds
        usleep(5000000);

        // Reverse directions
        for (int i = MIN_SPEED; i <= MAX_SPEED; i += 10) {
            gpioPWM(18, i * speed_factor_1);
            gpioPWM(24, i * speed_factor_2);
            gpioWrite(23, 1);
            gpioWrite(25, 0);
            usleep(100000);
        }

        for (int i = MAX_SPEED; i >= MIN_SPEED; i -= 10) {
            gpioPWM(18, i * speed_factor_1);
            gpioPWM(24, i * speed_factor_2);
            gpioWrite(23, 1);
            gpioWrite(25, 0);
            usleep(100000);
        }

        usleep(2000000); // Hold constant speed for 2 seconds
    }

    gpioTerminate();
    mcp3008_close();

    return 0;
}

