#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define GPIO_LED 17
#define GPIO_DEBOUNCE_MS 10
#define CALIBRATION_TIME 5000
#define NOISE_THRESHOLD_PERCENTAGE 10

volatile sig_atomic_t stop = 0;

void cleanup(int signum) {
    stop = 1;
    gpioWrite(GPIO_LED, 0);
    spiClose(SPI_CHANNEL);
    pigpioStop();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    if (spiOpen(SPI_CHANNEL, 0, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        pigpioStop();
        return 1;
    }

    int calibration_samples = 0;
    int calibration_sum = 0;
    int calibration_avg = 0;

    printf("Calibrating for %d seconds...\n", CALIBRATION_TIME / 1000);

    for (int i = 0; i < CALIBRATION_TIME; i += 10) {
        if (stop) {
            break;
        }

        uint8_t cmd[3] = {0x01, 0x00, 0x00};
        uint8_t data[3];

        if (spiXfer(SPI_CHANNEL, cmd, 3, data) != 3) {
            fprintf(stderr, "Failed to transfer SPI data\n");
            spiClose(SPI_CHANNEL);
            pigpioStop();
            return 1;
        }

        calibration_sum += (data[1] << 8) | data[2];
        calibration_samples++;

        if (i % 1000 == 0) {
            printf("Calibration progress: %d ms\n", i);
        }
    }

    calibration_avg = calibration_sum / calibration_samples;
    printf("Calibration complete. Average ambient level: %d\n", calibration_avg);

    int noise_threshold = calibration_avg * (1 + NOISE_THRESHOLD_PERCENTAGE / 100.0);

    while (!stop) {
        uint8_t cmd[3] = {0x01, 0x00, 0x00};
        uint8_t data[3];

        if (spiXfer(SPI_CHANNEL, cmd, 3, data) != 3) {
            fprintf(stderr, "Failed to transfer SPI data\n");
            spiClose(SPI_CHANNEL);
            pigpioStop();
            return 1;
        }

        int sample = (data[1] << 8) | data[2];

        if (sample > noise_threshold) {
            if (gpioRead(GPIO_LED) == 0) {
                gpioWrite(GPIO_LED, 1);
                usleep(GPIO_DEBOUNCE_MS * 1000);
            }
        } else {
            if (gpioRead(GPIO_LED) == 1) {
                gpioWrite(GPIO_LED, 0);
            }
        }
    }

    spiClose(SPI_CHANNEL);
    pigpioStop();

    return 0;
}

