#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <time.h>
#include <gpiod.h>
#include <spidev.h>
#include <stdint.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpio"
#define GPIO_LINE 8
#define CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SAMPLE_RATE 1000
#define SAMPLE_PERIOD (1000000 / SAMPLE_RATE)
#define LOG_FILE "audio_log.txt"

int main() {
    struct spidev spi;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int spi_fd;
    int ret;
    uint8_t tx_buf[3] = {0x01, (0x08 | CHANNEL) << 4, 0x00};
    uint8_t rx_buf[3];
    struct timespec sleep_time;
    struct timespec start_time;
    struct timespec current_time;
    FILE *log_file;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return spi_fd;
    }

    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        goto spi_close;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        goto spi_close;
    }

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        goto spi_close;
    }

    // Request GPIO line
    line = gpiod_line_request_any(chip, "CS", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        goto chip_close;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto line_release;
    }

    // Initialize sleep time
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_PERIOD;

    // Main loop
    while (1) {
        // Get current time
        clock_gettime(CLOCK_MONOTONIC_RAW, &current_time);

        // Calculate time until next sample
        if (current_time.tv_sec < start_time.tv_sec) {
            sleep_time.tv_sec = start_time.tv_sec - current_time.tv_sec;
        } else {
            sleep_time.tv_sec = 0;
        }

        if (current_time.tv_nsec < start_time.tv_nsec) {
            sleep_time.tv_nsec = start_time.tv_nsec - current_time.tv_nsec;
        } else {
            sleep_time.tv_nsec = 0;
        }

        // Sleep until next sample
        nanosleep(&sleep_time, NULL);

        // Drive CS low
        gpiod_line_set_value(line, 0);

        // Perform SPI transfer
        ret = spi_transfer(spi_fd, tx_buf, rx_buf, 3);
        if (ret < 0) {
            perror("Failed SPI transfer");
            goto file_close;
        }

        // Drive CS high
        gpiod_line_set_value(line, 1);

        // Log the reading
        fprintf(log_file, "%ld|%d\n", current_time.tv_sec * 1000000000 + current_time.tv_nsec, (rx_buf[1] << 2) | (rx_buf[2] >> 6));
        fflush(log_file);
    }

file_close:
    fclose(log_file);
line_release:
    gpiod_line_release(line);
chip_close:
    gpiod_chip_close(chip);
spi_close:
    close(spi_fd);

    return 0;
}

