#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define VREF 3.3
#define CHANNEL 0
#define SPI_SPEED 1000000
#define LOG_FILE "gas_log.txt"

void handle_sigint(int signum) {
    if (spi != -1) {
        spiStop(spi);
    }
    if (pi != 0) {
        pigpioStop();
    }
    exit(0);
}

int main() {
    int spi = -1;
    int pi = 0;
    unsigned char cmd[3] = {0x01, 0x80 | (CHANNEL << 4), 0x00};
    unsigned char data[3];
    double voltage, ppm;
    FILE *log_file;

    // Initialize pigpio
    if ((pi = pigpioOpen(NULL)) < 0) {
        fprintf(stderr, "pigpioOpen failed\n");
        return 1;
    }

    // Initialize SPI
    if ((spi = spiOpen(0, SPI_SPEED, 0)) < 0) {
        fprintf(stderr, "spiOpen failed\n");
        pigpioStop();
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiStop(spi);
        pigpioStop();
        return 1;
    }

    while (1) {
        int retries = 0;
        int max_retries = 5;

        do {
            if (spiXfer(spi, cmd, 3, data, 3) != 3) {
                if (retries < max_retries) {
                    fprintf(stderr, "SPI transfer failed, retrying...\n");
                    usleep(100000); // 100 ms delay
                    retries++;
                } else {
                    fprintf(stderr, "SPI transfer failed after %d retries\n", max_retries);
                    break;
                }
            }

            // Convert ADC value to voltage
            voltage = (double)(data[1] << 8 | data[2]) * VREF / 1024.0;
            ppm = voltage * 1000.0;

            // Log to file
            fprintf(log_file, "%ld, %.2f, %.2f\n", time(NULL), voltage, ppm);

            // Print to console
            printf("Voltage: %.2f V, PPM: %.2f\n", voltage, ppm);

            fflush(log_file);
            usleep(1000000); // 1 second delay
        } while (retries < max_retries);
    }

    // Cleanup
    fclose(log_file);
    spiStop(spi);
    pigpioStop();

    return 0;
}

