        fprintf(stderr, "spiOpen failed\n");
        pigpioStop();
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiStop(spi);
        pigpioStop();
        return 1;
    }

    while (1) {
        int retries = 0;
        int max_retries = 5;

        do {
            if (spiXfer(spi, cmd, 3, data, 3) != 3) {
                if (retries < max_retries) {
                    fprintf(stderr, "SPI transfer failed, retrying...\n");
                    usleep(100000); // 100 ms delay
                    retries++;
                } else {
                    fprintf(stderr, "SPI transfer failed after %d retries\n", max_retries);
                    break;
                }
            }

            // Convert ADC value to voltage
            voltage = (double)(data[1] << 8 | data[2]) * VREF / 1024.0;
            ppm = voltage * 1000.0;

            // Log to file
            fprintf(log_file, "%ld, %.2f, %.2f\n", time(NULL), voltage, ppm);

            // Print to console
            printf("Voltage: %.2f V, PPM: %.2f\n", voltage, ppm);

            fflush(log_file);
            usleep(1000000); // 1 second delay
        } while (retries < max_retries);
    }

    // Cleanup
    fclose(log_file);
    spiStop(spi);
    pigpioStop();

    return 0;
}
```

This C program initializes the pigpio library and SPI on the Raspberry Pi 4 Model B. It sets up a signal handler for SIGINT (Ctrl+C) to cleanly terminate the program. The program continuously reads the analog voltage from the Honeywell MICROpeL MP-741 Combustible Gas Sensor using the MCP3008 ADC, converts the ADC value to voltage, calculates PPM, logs the timestamp, voltage, and PPM to 'gas_log.txt', and prints the voltage and PPM to the console every second. It handles SPI initialization, SPI transfer failures, and file open errors, and retries ADC read on failure.

