    double voltage = (double)adc_value * ADC_REFERENCE_VOLTAGE / ADC_RESOLUTION;
    return voltage;
}

double apply_kalman_filter(double measurement, double prev_estimate, double process_noise, double measurement_noise) {
    double kalman_gain = process_noise / (process_noise + measurement_noise);
    double new_estimate = prev_estimate + kalman_gain * (measurement - prev_estimate);
    double new_process_noise = (1 - kalman_gain) * process_noise;
    return new_estimate;
}

