        double acceleration_z = (voltage_z - ZERO_G_BIAS) * 1000 / SENSITIVITY;

        prev_estimate_x = apply_kalman_filter(acceleration_x, prev_estimate_x, process_noise, measurement_noise);
        prev_estimate_y = apply_kalman_filter(acceleration_y, prev_estimate_y, process_noise, measurement_noise);
        prev_estimate_z = apply_kalman_filter(acceleration_z, prev_estimate_z, process_noise, measurement_noise);

        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", prev_estimate_x, prev_estimate_y, prev_estimate_z);

        usleep(PRINT_RATE * 1000);
