#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PINS {4, 17, 27}
#define NUM_SENSORS 3
#define VCC 3.3
#define V_QUIESCENT (VCC / 2)
#define SENSITIVITY 0.025
#define LOG_FILE "magnetic_log.txt"
#define LOG_INTERVAL 100 // milliseconds

gpiod_chip *chip;
gpiod_line *lines[NUM_SENSORS];
FILE *log_file;

void handle_sigint(int signum) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_free(lines[i]);
    }
    gpiod_chip_put(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO lines
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_line_request_by_name(chip, "gpio%d", GPIO_PINS[i], "sensor", 0);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_PINS[i]);
            for (int j = 0; j < i; j++) {
                gpiod_line_free(lines[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }
        ret = gpiod_line_direction_input(lines[i]);
        if (ret) {
            fprintf(stderr, "Failed to set direction for GPIO line %d\n", GPIO_PINS[i]);
            for (int j = 0; j < i; j++) {
                gpiod_line_free(lines[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_free(lines[i]);
        }
        gpiod_chip_put(chip);
        return 1;
    }

    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        char log_line[100];
        int valid_readings = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            double magnetic_field = (value * VCC - V_QUIESCENT) / SENSITIVITY;

            if (magnetic_field < -100 || magnetic_field > 100) {
                fprintf(stderr, "Warning: Magnetic field value %f mT is out of range\n", magnetic_field);
            }

            if (value != -1) {
                valid_readings++;
                sprintf(log_line + strlen(log_line), "%f,", magnetic_field);
            }
        }

        if (valid_readings > 0) {
            log_line[strlen(log_line) - 1] = '\0'; // Remove trailing comma
            fprintf(log_file, "%s\n", log_line);
            fflush(log_file);
        }

        usleep(LOG_INTERVAL * 1000); // Sleep for 100 milliseconds
    }

    // Cleanup
    fclose(log_file);
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_free(lines[i]);
    }
    gpiod_chip_put(chip);

    return 0;
}

