#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define SPI_CE_SELECT 0
#define SPI_FREQ 500000
#define PUMP_GPIO 17
#define THRESHOLD 30
#define LOG_FILE "watering.log"

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", buffer, event);
        fclose(log_file);
    } else {
        fprintf(stderr, "Failed to open log file for writing.\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (spiOpen(SPI_CE_SELECT, SPI_FREQ, 0) < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for pump.\n");
        spiClose(SPI_CE_SELECT);
        gpioTerminate();
        return 1;
    }

    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_event("Program started");

    while (!stop) {
        int moisture_level = spiRead(ADC_CHANNEL, 1);

        if (moisture_level < 0) {
            log_event("ADC read failed");
            continue;
        }

        double percentage = (double)moisture_level / 1023.0 * 100.0;

        if (percentage < THRESHOLD) {
            if (gpioWrite(PUMP_GPIO, 1) < 0) {
                log_event("Failed to turn on pump");
            } else {
                log_event("Pump turned on");
            }
        } else {
            if (gpioWrite(PUMP_GPIO, 0) < 0) {
                log_event("Failed to turn off pump");
            } else {
                log_event("Pump turned off");
            }
        }

        log_event(sprintf("Moisture level: %.2f%%", percentage));

        sleep(60); // Check every 60 seconds
    }

    log_event("Program terminated");

    spiClose(SPI_CE_SELECT);
    gpioTerminate();

    return 0;
}

