#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define SPI_PATH "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define CHANNEL_COUNT 3
#define CHANNEL_INTERVAL 1000 // 1 second

int spi_fd;

void handle_sigint(int signum) {
    printf("\nReceived SIGINT (Ctrl+C). Closing CSV file and releasing SPI resources...\n");
    close(spi_fd);
    exit(0);
}

int read_adc(int channel) {
    unsigned char cmd[3] = {0x01, 0x80 | (channel << 4), 0x00};
    unsigned char data[3];

    if (read(spi_fd, data, 3) != 3) {
        perror("Error reading from SPI");
        return -1;
    }

    int adc_value = ((data[1] & 0x03) << 8) | data[2];
    return adc_value;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    spi_fd = open(SPI_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return 1;
    }

    FILE *csv_file = fopen("sensor_data.csv", "w");
    if (!csv_file) {
        perror("Error opening CSV file");
        close(spi_fd);
        return 1;
    }

    fprintf(csv_file, "Time,Channel0,Channel1,Channel2\n");

    while (1) {
        int adc_values[CHANNEL_COUNT];
        for (int i = 0; i < CHANNEL_COUNT; i++) {
            adc_values[i] = read_adc(i);
            if (adc_values[i] < 0) {
                fclose(csv_file);
                close(spi_fd);
                return 1;
            }
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(csv_file, "%s,%d,%d,%d\n", time_str, adc_values[0], adc_values[1], adc_values[2]);

        usleep(CHANNEL_INTERVAL * 1000); // Sleep for 1 second
    }

    fclose(csv_file);
    close(spi_fd);
    return 0;
}

