#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cJSON.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define MAX_RECONNECT_DELAY 60

volatile sig_atomic_t shutdown = 0;

void sig_handler(int signum) {
    shutdown = 1;
}

void mqtt_connect_callback(struct mosquitto *mosq, void *obj, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        printf("Failed to connect to MQTT broker: %d\n", result);
    }
}

void mqtt_message_callback(struct mosquitto *mosq, void *obj, const struct mosquitto_message *message) {
    if (shutdown) {
        return;
    }

    cJSON *root = cJSON_Parse(message->payload);
    if (!root) {
        fprintf(stderr, "Failed to parse JSON: %s\n", cJSON_GetErrorPtr());
        return;
    }

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(root, "led_state");
    if (!led_state || !cJSON_IsBool(led_state)) {
        fprintf(stderr, "Invalid JSON payload: expected 'led_state' boolean\n");
        cJSON_Delete(root);
        return;
    }

    int state = cJSON_IsTrue(led_state) ? 1 : 0;
    gpioWrite(17, state);

    cJSON_Delete(root);
}

void mqtt_disconnect_callback(struct mosquitto *mosq, void *obj, int rc) {
    if (rc) {
        printf("MQTT disconnect error: %d\n", rc);
    }
}

void reconnect_attempt(struct mosquitto *mosq, void *obj, int rc) {
    if (shutdown) {
        return;
    }

    if (rc == MOSQ_ERR_SUCCESS) {
        printf("Reconnected to MQTT broker\n");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        printf("Failed to reconnect to MQTT broker: %d\n", rc);
    }
}

int main() {
    struct mosquitto *mosq;
    int reconnect_delay = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(17, PI_OUTPUT);
    gpioWrite(17, 0); // Turn off LED on startup

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Failed to create MQTT client\n");
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_reconnect_callback_set(mosq, reconnect_attempt);

    if (mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60)) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        return 1;
    }

    mosquitto_loop_start(mosq);

    while (!shutdown) {
        sleep(1);
    }

    mosquitto_disconnect(mosq);
    mosquitto_loop_stop(mosq, true);
    mosquitto_destroy(mosq);

    gpioTerminate();

    return 0;
}

