#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_SOUND_SENSOR 17
#define GPIO_LED 18
#define DELAY_MS 100
#define BLINK_DURATION 1000

static gpiod_chip *chip;
static gpiod_line *sensor_line, *led_line;

void cleanup(int signum) {
    if (sensor_line) {
        gpiod_line_request_release(sensor_line);
        gpiod_line_free(sensor_line);
    }
    if (led_line) {
        gpiod_line_request_release(led_line);
        gpiod_line_free(led_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    int ret;

    // Register cleanup function for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open the GPIO chip
    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO lines
    sensor_line = gpiod_line_request(chip, GPIO_SOUND_SENSOR, "sensor", 0);
    if (!sensor_line) {
        fprintf(stderr, "Failed to request sensor GPIO line\n");
        goto error_sensor;
    }

    led_line = gpiod_line_request(chip, GPIO_LED, "led", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!led_line) {
        fprintf(stderr, "Failed to request LED GPIO line\n");
        goto error_led;
    }

    // Set LED to initial state (OFF)
    gpiod_line_set_value(led_line, 0);

    while (1) {
        // Read sensor value
        int sensor_value = gpiod_line_get_value(sensor_line);

        // Print sensor value
        printf("Sound level: %d\n", sensor_value);

        // Check for sound detection and blink LED
        if (sensor_value == 0) {
            gpiod_line_set_value(led_line, 1); // Turn LED ON
            usleep(BLINK_DURATION * 1000); // Wait for 1 second
            gpiod_line_set_value(led_line, 0); // Turn LED OFF
        }

        // Delay between readings
        usleep(DELAY_MS * 1000);
    }

error_led:
    gpiod_line_request_release(sensor_line);
    gpiod_line_free(sensor_line);
error_sensor:
    gpiod_chip_put(chip);

    return 0;
}

