#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <gpiod.h>

volatile sig_atomic_t shutdown_requested = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        shutdown_requested = 1;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event *event;
    FILE *log_file;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    if (gpiod_line_get_by_name(chip, "17", &line) < 0) {
        perror("gpiod_line_get_by_name");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line for falling-edge event detection
    if (gpiod_line_request(line, "vibration-monitor", GPIOD_LINE_DIRECTION_IN, 0, 0, 0) < 0) {
        perror("gpiod_line_request");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen("/var/log/vibration_shutdown.log", "a");
    if (log_file == NULL) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Wait for and read events
    while (!shutdown_requested) {
        if (gpiod_line_event_wait(line, &event) < 0) {
            perror("gpiod_line_event_wait");
            gpiod_line_event_put(event);
            gpiod_line_release(line);
            gpiod_line_put(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            return EXIT_FAILURE;
        }

        // Read the event
        if (gpiod_line_event_read(event) < 0) {
            perror("gpiod_line_event_read");
            gpiod_line_event_put(event);
            gpiod_line_release(line);
            gpiod_line_put(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            return EXIT_FAILURE;
        }

        // Log the event
        fprintf(log_file, "Vibration detected at %s\n", ctime(&event->timestamp));
        if (ferror(log_file)) {
            perror("fprintf");
            gpiod_line_event_put(event);
            gpiod_line_release(line);
            gpiod_line_put(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            return EXIT_FAILURE;
        }

        // Print the event to stdout
        printf("Vibration detected at %s\n", ctime(&event->timestamp));

        // Trigger shutdown
        system("sudo shutdown -h now");

        // Clean up
        gpiod_line_event_put(event);
    }

    // Clean up on exit
    gpiod_line_release(line);
    gpiod_line_put(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

