    int i2c_fd;
    int ret;
    char filename[] = "altitude_log.txt";
    FILE *log_file;
    unsigned char calib_data[BMP280_CALIB_LEN];
    unsigned char temp_data[3];
    unsigned char press_data[3];
    float altitude;
    float temperature;
    float pressure;
    float sea_level_pressure = BMP280_SEA_LEVEL_PRESSURE;
    float sea_level_temperature = 25.0; // Assume 25°C at sea level
    float temperature_coeff_t1, temperature_coeff_t2, temperature_coeff_t3;
    float pressure_coeff_p1, pressure_coeff_p2, pressure_coeff_p3, pressure_coeff_p4, pressure_coeff_p5, pressure_coeff_p6, pressure_coeff_p7, pressure_coeff_p8, pressure_coeff_p9;
