#define BUFFER_SIZE 120
#define LOG_INTERVAL 5000 // 5 seconds
#define LM35_SCALE 0.01 // 10mV/°C
#define MCP3008_VREF 3.3 // 3.3V

float temp_buffer[BUFFER_SIZE];
int buffer_index = 0;
FILE *log_file = NULL;

void handle_signal(int signum) {
    if (spi >= 0) {
        spiClose(spi);
    }
    if (pi >= 0) {
        pigpioStop();
    }
    exit(signum);
}

float read_temperature() {
    uint8_t cmd[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    uint16_t adc_value;

    if (spi < 0) {
        fprintf(stderr, "SPI not initialized.\n");
        return -1.0;
    }

    if (spiXfer(spi, cmd, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed.\n");
        return -1.0;
    }

    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    float voltage = (adc_value * MCP3008_VREF) / 1024.0;
    float temperature = voltage / LM35_SCALE;

    return temperature;
}

