    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened.\n");
        return;
    }

    if (fwrite(&temperature, sizeof(float), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write to log file.\n");
    }
}

