                    fwrite(temp_buffer, sizeof(float), BUFFER_SIZE, log_file);
                    fflush(log_file);
                }
            }
        }

        usleep(LOG_INTERVAL * 1000);
    }

    if (spi >= 0) {
        spiClose(spi);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    pigpioStop();

    return 0;
}

