    if (gpiod_chip_open(chip_name, &chip) < 0) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    if (gpiod_line_request(chip, line_name, "flame_sensor", 0, &line) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    // Set the line direction and pull
    if (gpiod_line_direction(line, direction) < 0) {
        perror("gpiod_line_direction");
        gpiod_line_free(line);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_set_pull(line, pull) < 0) {
        perror("gpiod_line_set_pull");
        gpiod_line_free(line);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

