#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define TEMP_MIN 0
#define TEMP_MAX 50
#define VREF 3.3
#define SPI_SPEED 500000
#define I2C_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 500 // milliseconds

void handle_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

void init_pigpio() {
    if (gpioInitialise() < 0) {
        handle_error("Failed to initialize pigpio");
    }
}

void init_spi() {
    if (spiOpen(0, SPI_SPEED, 0) < 0) {
        handle_error("Failed to open SPI");
    }
}

void init_i2c() {
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        handle_error("Failed to open I2C");
    }
}

void read_adc() {
    uint8_t cmd[3] = {0x01, 0x80 | ADC_CHANNEL, 0x00};
    uint8_t data[3];

    if (spiXfer(0, cmd, 3, data) != 3) {
        handle_error("Failed to read ADC");
    }

    uint16_t adc_value = (data[1] << 8) | data[2];
    return adc_value;
}

void write_dac(uint16_t value) {
    uint8_t cmd[3] = {0x40, (uint8_t)(value >> 8), (uint8_t)(value & 0xFF)};

    if (i2cWriteDevice(I2C_BUS, I2C_ADDR, cmd, 3) < 0) {
        handle_error("Failed to write to DAC");
    }
}

void log_reading(uint16_t adc_value, float temperature, float voltage) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        handle_error("Failed to open log file");
    }

    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    fprintf(log_file, "%s %d %f %f %f\n", asctime(timeinfo), adc_value, temperature, voltage);
    fclose(log_file);
}

int main() {
    init_pigpio();
    init_spi();
    init_i2c();

    while (1) {
        uint16_t adc_value = read_adc();
        float voltage = (adc_value * VREF) / 1024.0;
        float temperature = (voltage - 0.5) * 100.0;

        if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
            fprintf(stderr, "Temperature out of range: %f C\n", temperature);
            continue;
        }

        uint16_t dac_value = (uint16_t)((temperature - TEMP_MIN) * (VREF * 1024.0 / (TEMP_MAX - TEMP_MIN)));
        write_dac(dac_value);

        printf("Timestamp: %s, ADC Value: %d, Temperature: %.2f C, DAC Voltage: %.2f V\n", asctime(localtime(&time(NULL))), adc_value, temperature, voltage);
        log_reading(adc_value, temperature, voltage);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    spiClose(0);
    i2cClose(I2C_BUS, I2C_ADDR);
    gpioTerminate();

    return 0;
}

