#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define NUM_SENSORS 3

int spi_fd;
FILE *log_file;

void log_reading(int sensor, double moisture) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s Sensor %d: %.2f%%\n", buffer, sensor + 1, moisture);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    spi_fd = spiOpen(SPI_CHANNEL, SPI_MODE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("soil_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            uint8_t cmd[3] = {0x01, (i << 6) | 0x18, 0x00};
            uint8_t data[3];

            if (spiXfer(spi_fd, cmd, 3, data, 3) != 3) {
                fprintf(stderr, "Failed to read from sensor %d.\n", i + 1);
                continue;
            }

            uint16_t adc_value = (data[1] << 8) | data[2];
            double moisture = (1.0 - (adc_value / 1023.0)) * 100.0;

            if (moisture < 0.0 || moisture > 100.0) {
                fprintf(stderr, "Invalid ADC value for sensor %d.\n", i + 1);
                continue;
            }

            log_reading(i, moisture);
        }

        gpioDelay(60000); // Sleep for 60 seconds
    }

    fclose(log_file);
    spiClose(spi_fd);
    gpioTerminate();

    printf("Goodbye!\n");
    return 0;
}

