// GPIO pins for the relays
#define RELAY_1 17
#define RELAY_2 22
#define RELAY_3 23
#define RELAY_4 24

// Global variables for gpiod lines
struct gpiod_line *lines[4];

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(lines[i], 0); // Deactivate all relays
    }
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]); // Release all GPIO lines
    }
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *req;

    // Initialize libgpiod
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request GPIO lines for relays
    for (int i = 0; i < 4; i++) {
        req = gpiod_line_request(chip, i + RELAY_1, "Relay", 0, 0);
        if (req == NULL) {
            perror("gpiod_line_request");
            return 1;
        }
        lines[i] = req->line;
    }

    // Set all relay pins to inactive (LOW)
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_set_value(lines[i], 0) < 0) {
            perror("gpiod_line_set_value");
            return 1;
        }
    }

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop: activate each relay in sequence
    while (1) {
        for (int i = 0; i < 4; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("gpiod_line_set_value");
                return 1;
            }
            sleep(1); // Keep relay active for 1 second
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("gpiod_line_set_value");
                return 1;
            }
            sleep(1); // Delay between relays
        }
    }

    // Cleanup: Deactivate all relays and release GPIO lines
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(lines[i], 0);
    }
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}
```

This C program uses the libgpiod library to control four relays connected to GPIO pins 17, 22, 23, and 24 on a Raspberry Pi 3 Model B+. It sequentially activates each relay for 1 second, then deactivates it, with a 1-second delay between relays, creating a light sequencer effect. The program installs a signal handler for SIGINT and SIGTERM to ensure all relays are deactivated and GPIO lines are released before exiting.

