#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define GPIO_LED 16
#define GPIO_SOUND_SENSOR 8
#define ADC_THRESHOLD 500
#define DEBOUNCE_DELAY 50

void handle_sigint(int signum) {
    if (spi_open(SPI_CHANNEL, SPI_SPEED, 0) >= 0) {
        spi_close(SPI_CHANNEL);
    }
    if (pi_stop() == 0) {
        printf("Terminated pigpio.\n");
    }
    if (pi_write(GPIO_LED, 0) == 0) {
        printf("Turned off LED.\n");
    }
    exit(0);
}

int main() {
    if (pi_start() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }

    if (spi_open(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        pi_stop();
        return 1;
    }

    if (pi_set_mode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO LED mode setting failed.\n");
        spi_close(SPI_CHANNEL);
        pi_stop();
        return 1;
    }

    if (pi_write(GPIO_LED, 0) < 0) {
        fprintf(stderr, "Failed to turn off LED initially.\n");
        spi_close(SPI_CHANNEL);
        pi_stop();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    FILE *log_file = fopen("sound_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        spi_close(SPI_CHANNEL);
        pi_stop();
        return 1;
    }

    while (1) {
        uint8_t cmd = 0b11000000; // Single-ended, channel 0
        uint8_t adc_data[3];

        if (spi_read(SPI_CHANNEL, &cmd, 1) != 1) {
            fprintf(stderr, "SPI read failed.\n");
            continue;
        }

        if (spi_read(SPI_CHANNEL, adc_data, 2) != 2) {
            fprintf(stderr, "SPI read failed.\n");
            continue;
        }

        uint16_t adc_value = (adc_data[1] << 8) | adc_data[0];

        if (adc_value > ADC_THRESHOLD) {
            if (pi_write(GPIO_LED, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED.\n");
            } else {
                time_t now = time(NULL);
                struct tm *now_tm = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
                fprintf(log_file, "%s: Sound level exceeded threshold.\n", timestamp);
                fflush(log_file);
                usleep(500000); // 500 ms delay
                if (pi_write(GPIO_LED, 0) < 0) {
                    fprintf(stderr, "Failed to turn off LED.\n");
                }
            }
            usleep(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        usleep(10000); // 10 ms delay
    }

    fclose(log_file);
    spi_close(SPI_CHANNEL);
    pi_stop();

    return 0;
}

