#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define PWM_PIN 27
#define PWM_RANGE 255
#define PWM_DUTY 150
#define RAIN_THRESHOLD 5
#define LOG_FILE "rain_log.txt"

volatile sig_atomic_t shutdown_flag = 0;

void handle_signal(int signum) {
    shutdown_flag = 1;
}

void spi_transfer(unsigned char *tx, unsigned char *rx) {
    if (spi_write(SPI_CHANNEL, tx, 3, rx) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        exit(EXIT_FAILURE);
    }
}

void log_rain_level(int rain_level) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: Rain level %d\n", buffer, rain_level);
    fflush(log_file);
    fclose(log_file);
}

void drive_motor(int direction, int duration) {
    if (direction == 1) {
        gpioWrite(17, 1);
        gpioWrite(18, 0);
    } else {
        gpioWrite(17, 0);
        gpioWrite(18, 1);
    }

    gpioSetPWMrange(PWM_PIN, PWM_RANGE);
    gpioPWM(PWM_PIN, PWM_DUTY);

    sleep(duration);

    gpioPWM(PWM_PIN, 0);
    gpioSetMode(PWM_PIN, PI_INPUT);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioSetMode(17, PI_OUTPUT);
    gpioSetMode(18, PI_OUTPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!shutdown_flag) {
        unsigned char tx[3] = {0x01, (0x08 | ADC_CHANNEL) << 4, 0x00};
        unsigned char rx[3];

        spi_transfer(tx, rx);

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        int rain_level = (10 - (adc_value * 10) / 1023);

        log_rain_level(rain_level);

        if (rain_level >= RAIN_THRESHOLD) {
            drive_motor(1, 3);
        } else {
            drive_motor(0, 3);
        }

        sleep(1);
    }

    drive_motor(0, 0); // Stop motor
    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

