#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_LED 16
#define GPIO_MIC 26
#define ADC_THRESHOLD 700
#define DEBOUNCE_TIME 50000 // 50 ms in microseconds

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode.\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_MIC, PI_ALT5) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to ADC mode.\n", GPIO_MIC);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec last_clap = {0, DEBOUNCE_TIME};

    signal(SIGINT, handle_sigint);

    while (!stop) {
        int adc_value = gpioGetADC(GPIO_MIC);

        if (adc_value >= ADC_THRESHOLD) {
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);

            if (now.tv_sec - last_clap.tv_sec >= 1 || (now.tv_sec == last_clap.tv_sec && now.tv_nsec - last_clap.tv_nsec >= DEBOUNCE_TIME)) {
                printf("Clap detected at %ld.%09ld\n", now.tv_sec, now.tv_nsec);
                gpioWrite(GPIO_LED, PI_ON);
                usleep(50000); // 500 ms
                gpioWrite(GPIO_LED, PI_OFF);
                last_clap = now;
            }
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

