#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <signal.h>

#define GPIO_PATH "/sys/class/gpio/gpio17"
#define LOG_FILE "distance_log.txt"
#define A 26.0
#define B -6.0
#define VOLTAGE_HIGH 3.3
#define VOLTAGE_LOW 0.0
#define DISTANCE_THRESHOLD 200

void handle_signal(int signum) {
    if (unlink(GPIO_PATH "/value") == 0) {
        printf("GPIO 17 unexporting on signal %d\n", signum);
    } else {
        perror("Error unexporting GPIO 17");
    }
    exit(signum);
}

int read_distance() {
    int fd;
    char buffer[10];
    int voltage;
    double distance;

    fd = open(GPIO_PATH "/value", O_RDONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        sleep(1);
        return -1;
    }

    if (read(fd, buffer, sizeof(buffer)) != 1) {
        perror("Error reading GPIO value");
        close(fd);
        sleep(1);
        return -1;
    }

    close(fd);

    if (buffer[0] == '1') {
        voltage = VOLTAGE_HIGH;
    } else {
        voltage = VOLTAGE_LOW;
    }

    distance = A / voltage + B;

    return (int)distance;
}

int main() {
    struct sigaction sa;
    int distance;
    time_t now;
    FILE *log_file;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (access(GPIO_PATH, F_OK) != 0) {
        printf("Exporting GPIO 17\n");
        if (system("echo 17 > /sys/class/gpio/export") != 0) {
            perror("Error exporting GPIO 17");
            exit(1);
        }
    }

    printf("Setting GPIO 17 to input\n");
    if (system("echo in > " GPIO_PATH "/direction") != 0) {
        perror("Error setting GPIO 17 to input");
        exit(1);
    }

    while (1) {
        distance = read_distance();
        if (distance < 0) {
            continue;
        }

        now = time(NULL);
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            continue;
        }

        fprintf(log_file, "%s %.2f mm\n", ctime(&now), distance);
        fclose(log_file);

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    return 0;
}

