#include <linux/spi/spidev.h>
#include <time.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define GPIO_PIN_PUMP 17
#define GPIO_PIN_CE0 0
#define ADC_CHANNEL 0
#define DRY_ADC_VALUE 800
#define WET_ADC_VALUE 300
#define THRESHOLD_PERCENTAGE 30

static gpiod_chip *chip;
static gpiod_line *pump_line;
static int spi_fd;

void handle_sigint(int signum) {
    gpiod_line_request_free(pump_line);
    gpiod_chip_put(chip);
    close(spi_fd);
    exit(0);
}

int read_adc(int channel) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)channel,
        .rx_buf = (unsigned long)channel,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer failed");
        return -1;
    }

    return (int)tr.rx_buf;
}

