#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEV_PATH "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL 500

static gpiod_line *cs_line;
static int spi_fd;
static FILE *log_file;

void cleanup(void) {
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_free(cs_line);
    }
    exit(EXIT_FAILURE);
}

void handle_signal(int signum) {
    cleanup();
}

int main(void) {
    struct spidev_ioc_transfer spi_transfer;
    uint8_t spi_buffer[2];
    int result;
    uint32_t adc_value;
    double B_mt;
    struct timespec sleep_time;

    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open SPI device
    spi_fd = open(SPI_DEV_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI mode or speed");
        cleanup();
    }

    // Open GPIO line for chip select
    cs_line = gpiod_line_request(GPIO_CHIP, GPIO_LINE, "CS_LINE", 0);
    if (!cs_line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        cleanup();
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
    }

    // Main loop
    while (1) {
        // Drive chip select low
        gpiod_line_set_value(cs_line, 0);

        // Prepare SPI transfer
        spi_transfer.tx_buf = spi_buffer;
        spi_transfer.rx_buf = spi_buffer;
        spi_transfer.len = 2;
        spi_transfer.delay_usecs = 0;
        spi_transfer.speed_hz = SPI_SPEED;
        spi_transfer.bits_per_word = SPI_BITS;

        // Perform SPI transfer
        result = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer);
        if (result < 1) {
            perror("Failed SPI transfer");
            gpiod_line_set_value(cs_line, 1);
            continue;
        }

        // Read ADC value
        adc_value = (spi_buffer[1] << 8) | spi_buffer[0];

        // Compute magnetic field in mT
        B_mt = ((double)adc_value * 3300 / 1023 - 1650) / 100;

        // Drive chip select high
        gpiod_line_set_value(cs_line, 1);

        // Log the result
        fprintf(log_file, "%ld,%0.2f\n", time(NULL), B_mt);
        fflush(log_file);

        // Sleep for 500 ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = SAMPLE_INTERVAL * 1000000;
        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return 0;
}

