This C program reads analog voltage from a DRV5055-A1 Hall-effect sensor using an external MCP3008 ADC over SPI on a Raspberry Pi Zero W. It uses the libgpiod library to control the chip-select line and the Linux spidev interface for SPI communication. The program logs the magnetic field strength in milliteslas (mT) to a CSV file every 500 milliseconds. It handles errors, signals, and resource cleanup appropriately.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define VCC 3.3
#define SENSITIVITY_mV_PER_mT 1.65
#define THRESHOLD_mT 10.0
#define GPIO_LED 21
#define FILE_LOG "magnetic_log.txt"
#define DELAY_MS 100

void handle_sigint(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    gpioWrite(GPIO_LED, PI_OFF);
    spiStop(SPI_CHANNEL);
    pigpioStop();
    exit(0);
}

int main(int argc, char *argv[]) {
    int spi_fd;
    int adc_value;
    double voltage, field_mT;
    FILE *log_file;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED\n");
        return 1;
    }

    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        adc_value = spiRead(spi_fd, 1, 0x00);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        voltage = (double)adc_value * VCC / 1023;
        field_mT = ((voltage - VCC / 2) * 1000) / SENSITIVITY_mV_PER_mT;

        log_file = fopen(FILE_LOG, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            continue;
        }

        fprintf(log_file, "%ld: %.2f mT\n", time(NULL), field_mT);
        fclose(log_file);

        if (field_mT > THRESHOLD_mT) {
            gpioWrite(GPIO_LED, PI_ON);
        } else {
            gpioWrite(GPIO_LED, PI_OFF);
        }

        usleep(DELAY_MS * 1000);
    }

    return 0;
}

