This C program initializes the pigpio library and SPI, reads the analog voltage from the MCP3008 ADC, converts it to magnetic field strength, logs the readings, and controls an LED based on the field strength. It handles SIGINT for graceful cleanup and checks for errors in SPI, ADC, and file operations.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CHANNEL 0
#define LOG_FILE "moisture_log.txt"

void spi_read(int spi_channel, uint8_t *rx_buf) {
    uint8_t tx_buf[3] = {0x01, 0x80 | (CHANNEL << 4), 0x00};
    int result = spi_read(spi_channel, tx_buf, rx_buf, 3);
    if (result == -1) {
        fprintf(stderr, "SPI read failed\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint8_t rx_buf[3];
        spi_read(spi_handle, rx_buf);

        uint16_t adc_value = (rx_buf[1] & 0x03) << 8 | rx_buf[2];

        time_t rawtime;
        struct tm *timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (fprintf(log_file, "%s %d\n", buffer, adc_value) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        }

        sleep(60);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

