#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CE 0
#define LOG_FILE "current_log.txt"

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    int spi_fd = spiOpen(SPI_CE, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device.\n");
        gpioTerminate();
        return 1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (!exit_flag) {
        uint8_t tx[3] = {0x01, 0x80 | (CHANNEL << 4), 0x00};
        uint8_t rx[3];

        if (spiXfer(spi_fd, tx, 3, rx) != 3) {
            fprintf(stderr, "SPI transfer error.\n");
            continue;
        }

        uint16_t raw_code = ((rx[1] & 0x03) << 8) | rx[2];
        double voltage = (double)raw_code * 5.0 / 1023.0;

        if (voltage < 0.0 || voltage > 5.0) {
            fprintf(stderr, "Voltage out of range: %.2fV\n", voltage);
            continue;
        }

        double current = (voltage - 2.5) * (50.0 / 2.5);

        char timestamp[20];
        struct tm *tm_info;
        time_t rawtime = time(NULL);
        tm_info = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s %.2f A\n", timestamp, current);
        fflush(log_file);

        usleep(100000); // 100 ms delay
    }

    fclose(log_file);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

