#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_SAMPLES 5
#define DEBOUNCE_DELAY 2

static gpiod_chip *chip;
static gpiod_line *line1, *line2;

void cleanup(int signum) {
    if (line1) {
        gpiod_line_release(line1);
        free(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
        free(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
        free(chip);
    }
    exit(0);
}

int read_sensor(gpiod_line *line) {
    int samples[NUM_SAMPLES];
    int majority = 0;

    for (int i = 0; i < NUM_SAMPLES; i++) {
        samples[i] = gpiod_line_get_value(line);
        usleep(DEBOUNCE_DELAY * 1000);
    }

    for (int i = 0; i < NUM_SAMPLES; i++) {
        if (samples[i] == 0) {
            majority++;
        }
    }

    return majority > NUM_SAMPLES / 2;
}

int main() {
    int err;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO4 as input
    line1 = gpiod_line_request(chip, 4, "sensor1", 0, 0);
    if (!line1) {
        fprintf(stderr, "Failed to request GPIO4\n");
        goto cleanup;
    }
    err = gpiod_line_request_input(line1);
    if (err) {
        fprintf(stderr, "Failed to set GPIO4 as input\n");
        goto cleanup;
    }

    // Request GPIO17 as input
    line2 = gpiod_line_request(chip, 17, "sensor2", 0, 0);
    if (!line2) {
        fprintf(stderr, "Failed to request GPIO17\n");
        goto cleanup;
    }
    err = gpiod_line_request_input(line2);
    if (err) {
        fprintf(stderr, "Failed to set GPIO17 as input\n");
        goto cleanup;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        int sensor1_state = read_sensor(line1);
        int sensor2_state = read_sensor(line2);

        printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_state, sensor2_state);

        if (sensor1_state == 0 && sensor2_state == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        sleep(1);
    }

cleanup:
    cleanup(0);

    return 0;
}

