#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t terminate = 0;

int read_mcp3008(int channel) {
    uint8_t cmd[3] = {0x01, 0x80 | (channel << 4), 0x00};
    uint8_t rx_buf[3];
    int adc_value;

    if (spi_read(SPI_CHANNEL, cmd, rx_buf, 3) != 3) {
        printf("SPI transfer failed, retrying...\n");
        sleep(1);
        return -1;
    }

    adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

double calculate_moisture_level(int adc_value) {
    double moisture_percentage = 100.0 - ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
    return fmax(0.0, fmin(100.0, moisture_percentage));
}

void log_data(double moisture_level) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        printf("Failed to open log file for writing.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", now_tm);

    fprintf(file, "%s%.2f\n", timestamp, moisture_level);
    fclose(file);
}

void signal_handler(int signal) {
    terminate = 1;
}

void spi_setup(spi_config_t config) {
    if (spi_open(SPI_CHANNEL, SPI_BAUD, &config) < 0) {
        printf("Failed to open SPI channel.\n");
        terminate = 1;
        return;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio.\n");
        return 1;
    }

    spi_config_t config = {0};
    spi_setup(config);

    if (terminate) {
        spi_close(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            double moisture_level = calculate_moisture_level(adc_value);
            printf("Moisture level: %.2f%%\n", moisture_level);
            log_data(moisture_level);
        }
        sleep(READ_DELAY);
    }

    spi_close(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

