    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        log_event("Failed to set GPIO mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
        log_event("Failed to set GPIO pull-down");
        gpioTerminate();
        return EXIT_FAILURE;
