                    continue;
                } else if (pid == 0) {
                    // Child process
                    execvp("/usr/bin/libcamera-still", NULL);
                    log_event("Failed to execute libcamera-still");
                    exit(EXIT_FAILURE);
                } else {
                    // Parent process
                    int child_status;
                    waitpid(pid, &child_status, 0);
                    if (WIFEXITED(child_status)) {
                        if (WEXITSTATUS(child_status) == 0) {
                            log_event("Capture successful");
                        } else {
                            log_event("Capture failed");
                        }
                    } else {
                        log_event("Capture process terminated unexpectedly");
                    }
                }
            }
        }

        old_state = new_state;

        // Poll every 50 ms
        usleep(50 * 1000);
    }

    // On SIGINT or SIGTERM, stop the main loop
    signal(SIGINT, [](int sig) {
        log_event("Received SIGINT, stopping");
        gpioTerminate();
        closelog();
        exit(EXIT_SUCCESS);
    });

    signal(SIGTERM, [](int sig) {
        log_event("Received SIGTERM, stopping");
        gpioTerminate();
        closelog();
        exit(EXIT_SUCCESS);
    });

    return EXIT_SUCCESS;
