#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <signal.h>
#include <errno.h>
#include <libv4l2.h>

#define BUFFER_COUNT 1
#define IMAGE_FORMAT V4L2_PIX_FMT_GREY
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480

static void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void handle_signal(int signum) {
    printf("Received signal %d, stopping capture...\n", signum);
    exit(EXIT_SUCCESS);
}

static void cleanup(int fd, struct v4l2_buffer *buffers, void **mapped_buffers) {
    if (fd >= 0) {
        close(fd);
    }
    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (mapped_buffers[i] != NULL) {
            munmap(mapped_buffers[i], buffers[i].length);
        }
    }
    free(buffers);
    free(mapped_buffers);
}

int main(int argc, char *argv[]) {
    const char *device_name = "/dev/video0";
    if (argc > 1) {
        device_name = argv[1];
    }

    int fd = open(device_name, O_RDWR /* required */ | O_NONBLOCK);
    if (fd < 0) {
        handle_error("Failed to open device");
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        handle_error("Failed to query device capabilities");
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        handle_error("Device is not a video capture device");
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        handle_error("Failed to set format");
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        handle_error("Failed to request buffers");
    }

    struct v4l2_buffer buf;
    struct v4l2_buffer *buffers = malloc(sizeof(struct v4l2_buffer) * BUFFER_COUNT);
    void **mapped_buffers = malloc(sizeof(void *) * BUFFER_COUNT);

    for (int i = 0; i < BUFFER_COUNT; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            handle_error("Failed to query buffer");
        }

        mapped_buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (mapped_buffers[i] == MAP_FAILED) {
            handle_error("Failed to map buffer");
        }

        buffers[i] = buf;
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            handle_error("Failed to queue buffer");
        }
    }

    struct v4l2_buf_type type;
    type.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        handle_error("Failed to start streaming");
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int frame_count = 0;
    while (1) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        struct timeval tv = { .tv_sec = 2, .tv_usec = 0 };
        int select_result = select(fd + 1, &fds, NULL, NULL, &tv);

        if (select_result < 0 && errno != EAGAIN) {
            handle_error("Failed to select");
        }

        if (select_result == 0) {
            continue;
        }

        for (int i = 0; i < BUFFER_COUNT; i++) {
            memset(&buf, 0, sizeof(buf));
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = i;

            if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
                if (errno == EAGAIN) {
                    continue;
                }
                handle_error("Failed to dequeue buffer");
            }

            if (buf.flags & V4L2_BUF_FLAG_EOF) {
                printf("End of stream reached.\n");
                break;
            }

            char filename[20];
            sprintf(filename, "image_%04d.pgm", frame_count + 1);

            FILE *pgm_file = fopen(filename, "wb");
            if (!pgm_file) {
                handle_error("Failed to open PGM file");
            }

            fprintf(pgm_file, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
            fwrite(mapped_buffers[i], IMAGE_WIDTH * IMAGE_HEIGHT, 1, pgm_file);
            fclose(pgm_file);

            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                handle_error("Failed to requeue buffer");
            }

            frame_count++;
        }
    }

    cleanup(fd, buffers, mapped_buffers);
    return EXIT_SUCCESS;
}

