#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>

#define VIDEO_DEV "/dev/video0"
#define FRAME_LOG "frame_log.txt"

static int video_fd;
static struct v4l2_format fmt;
static struct v4l2_requestbuffers req;
static struct v4l2_buffer buf;
static char *mmap_buf;
static int mmap_size;

void cleanup() {
    if (video_fd >= 0) {
        munmap(mmap_buf, mmap_size);
        close(video_fd);
    }
    unlink(FRAME_LOG);
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    video_fd = open(VIDEO_DEV, O_RDWR | O_NONBLOCK);
    if (video_fd < 0) {
        perror("Failed to open video device");
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(video_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set video format");
        cleanup();
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    req.count = 1;

    if (ioctl(video_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(video_fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Failed to query buffer");
        cleanup();
        exit(EXIT_FAILURE);
    }

    mmap_size = buf.length;
    mmap_buf = mmap(NULL, mmap_size, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, buf.m.offset);
    if (mmap_buf == MAP_FAILED) {
        perror("Failed to mmap buffer");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(video_fd, VIDIOC_STREAMON, &buf) < 0) {
        perror("Failed to start streaming");
        cleanup();
        exit(EXIT_FAILURE);
    }

    fd_set readfds;
    int ret;
    FILE *log_file = fopen(FRAME_LOG, "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(video_fd, &readfds);

        ret = select(video_fd + 1, &readfds, NULL, NULL, NULL);
        if (ret < 0) {
            perror("select failed");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (FD_ISSET(video_fd, &readfds)) {
            if (ioctl(video_fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("Failed to dequeue buffer");
                cleanup();
                exit(EXIT_FAILURE);
            }

            if (buf.flags & V4L2_BUF_FLAG_EOF) {
                printf("End of stream\n");
                break;
            }

            struct timeval tv;
            gettimeofday(&tv, NULL);
            double timestamp = tv.tv_sec + (double)tv.tv_usec / 1e6;
            fprintf(log_file, "%f\n", timestamp);

            if (ioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
                perror("Failed to queue buffer");
                cleanup();
                exit(EXIT_FAILURE);
            }
        }
    }

    fclose(log_file);
    cleanup();

    return 0;
}

