#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <signal.h>
#include <linux/videodev2.h>

#define BUFFER_COUNT 4
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define FRAME_SIZE (FRAME_WIDTH * FRAME_HEIGHT * 2) // YUYV format
#define MAX_UDP_DATAGRAM_SIZE 65000

struct frame_header {
    uint32_t frame_index;
    uint32_t fragment_index;
    uint32_t total_fragments;
    uint32_t payload_size;
};

void handle_signal(int signum) {
    printf("Received signal %d, stopping streaming...\n", signum);
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    char *server_ip = argv[1];
    uint16_t server_port = atoi(argv[2]);

    int video_fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (video_fd < 0) {
        perror("Failed to open video device");
        return 1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(video_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set video format");
        close(video_fd);
        return 1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(video_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(video_fd);
        return 1;
    }

    struct v4l2_buffer buf;
    uint8_t *buffers[BUFFER_COUNT];
    for (int i = 0; i < BUFFER_COUNT; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(video_fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            close(video_fd);
            return 1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Failed to mmap buffer");
            close(video_fd);
            return 1;
        }
    }

    struct v4l2_buffer start_buf;
    memset(&start_buf, 0, sizeof(start_buf));
    start_buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    start_buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(video_fd, VIDIOC_STREAMON, &start_buf) < 0) {
        perror("Failed to start streaming");
        for (int i = 0; i < BUFFER_COUNT; i++) {
            munmap(buffers[i], buf.length);
        }
        close(video_fd);
        return 1;
    }

    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("Failed to create socket");
        for (int i = 0; i < BUFFER_COUNT; i++) {
            munmap(buffers[i], buf.length);
        }
        close(video_fd);
        return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    inet_pton(AF_INET, server_ip, &server_addr.sin_addr);

    int frame_index = 0;
    int fragment_index = 0;
    int total_fragments = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(video_fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            perror("Failed to dequeue buffer");
            break;
        }

        total_fragments = (buf.bytesused + MAX_UDP_DATAGRAM_SIZE - 1) / MAX_UDP_DATAGRAM_SIZE;

        for (int i = 0; i < total_fragments; i++) {
            struct frame_header header;
            header.frame_index = frame_index;
            header.fragment_index = i;
            header.total_fragments = total_fragments;
            header.payload_size = (i == total_fragments - 1) ? buf.bytesused - i * MAX_UDP_DATAGRAM_SIZE : MAX_UDP_DATAGRAM_SIZE;

            uint8_t *payload = (uint8_t *)buffers[buf.index] + i * MAX_UDP_DATAGRAM_SIZE;
            ssize_t sent = sendto(sock, (const void *)&header, sizeof(header), 0, (const struct sockaddr *)&server_addr, sizeof(server_addr));
            if (sent < 0) {
                perror("Failed to send header");
                break;
            }

            sent = sendto(sock, payload, header.payload_size, 0, (const struct sockaddr *)&server_addr, sizeof(server_addr));
            if (sent < 0) {
                perror("Failed to send payload");
                break;
            }
        }

        if (ioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
            break;
        }

        frame_index++;
    }

    if (ioctl(video_fd, VIDIOC_STREAMOFF, &start_buf) < 0) {
        perror("Failed to stop streaming");
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        munmap(buffers[i], buf.length);
    }

    close(video_fd);
    close(sock);

    return 0;
}

