#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_PIN 6
#define TILT_DOWN_PIN 7
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9

#define PWM_PERIOD 20000 // 20 ms
#define PWM_DUTY_MIN 50  // 1 ms
#define PWM_DUTY_MAX 100 // 2 ms
#define PWM_DUTY_MID 75  // Mid-position

#define BUTTON_POLARITY GPIOD_POLARITY_ACTIVE_LOW
#define BUTTON_PULL_UP GPIOD_LINE_POLARITY_ACTIVE_LOW

static gpiod_chip *chip;
static gpiod_line *pan_servo, *tilt_servo, *tilt_up, *tilt_down, *pan_left, *pan_right;

void cleanup(int signum) {
    if (pan_servo) gpiod_line_request_release(pan_servo);
    if (tilt_servo) gpiod_line_request_release(tilt_servo);
    if (tilt_up) gpiod_line_request_release(tilt_up);
    if (tilt_down) gpiod_line_request_release(tilt_down);
    if (pan_left) gpiod_line_request_release(pan_left);
    if (pan_right) gpiod_line_request_release(pan_right);
    if (chip) gpiod_chip_put(chip);
    exit(signum);
}

int main() {
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request lines for servos and buttons
    pan_servo = gpiod_line_request(chip, PAN_SERVO_PIN, "pan_servo", "Servo control for pan", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!pan_servo) {
        perror("Failed to request pan servo line");
        goto cleanup;
    }

    tilt_servo = gpiod_line_request(chip, TILT_SERVO_PIN, "tilt_servo", "Servo control for tilt", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!tilt_servo) {
        perror("Failed to request tilt servo line");
        goto cleanup;
    }

    tilt_up = gpiod_line_request(chip, TILT_UP_PIN, "tilt_up", "Button to move tilt up", GPIOD_LINE_DIRECTION_INPUT);
    if (!tilt_up) {
        perror("Failed to request tilt up button line");
        goto cleanup;
    }

    tilt_down = gpiod_line_request(chip, TILT_DOWN_PIN, "tilt_down", "Button to move tilt down", GPIOD_LINE_DIRECTION_INPUT);
    if (!tilt_down) {
        perror("Failed to request tilt down button line");
        goto cleanup;
    }

    pan_left = gpiod_line_request(chip, PAN_LEFT_PIN, "pan_left", "Button to move pan left", GPIOD_LINE_DIRECTION_INPUT);
    if (!pan_left) {
        perror("Failed to request pan left button line");
        goto cleanup;
    }

    pan_right = gpiod_line_request(chip, PAN_RIGHT_PIN, "pan_right", "Button to move pan right", GPIOD_LINE_DIRECTION_INPUT);
    if (!pan_right) {
        perror("Failed to request pan right button line");
        goto cleanup;
    }

    // Set initial PWM duty cycle for servos
    gpiod_line_set_value(pan_servo, PWM_DUTY_MID);
    gpiod_line_set_value(tilt_servo, PWM_DUTY_MID);

    // Set button polarity and pull-up
    gpiod_line_set_polarity(tilt_up, BUTTON_POLARITY);
    gpiod_line_set_polarity(tilt_down, BUTTON_POLARITY);
    gpiod_line_set_polarity(pan_left, BUTTON_POLARITY);
    gpiod_line_set_polarity(pan_right, BUTTON_POLARITY);

    gpiod_line_set_debounce(tilt_up, 100);
    gpiod_line_set_debounce(tilt_down, 100);
    gpiod_line_set_debounce(pan_left, 100);
    gpiod_line_set_debounce(pan_right, 100);

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        int pan_duty = PWM_DUTY_MID;
        int tilt_duty = PWM_DUTY_MID;

        // Check button states
        if (gpiod_line_get_value(tilt_up)) {
            tilt_duty = (tilt_duty + 5) > PWM_DUTY_MAX ? PWM_DUTY_MAX : tilt_duty + 5;
        }
        if (gpiod_line_get_value(tilt_down)) {
            tilt_duty = (tilt_duty - 5) < PWM_DUTY_MIN ? PWM_DUTY_MIN : tilt_duty - 5;
        }
        if (gpiod_line_get_value(pan_left)) {
            pan_duty = (pan_duty - 5) < PWM_DUTY_MIN ? PWM_DUTY_MIN : pan_duty - 5;
        }
        if (gpiod_line_get_value(pan_right)) {
            pan_duty = (pan_duty + 5) > PWM_DUTY_MAX ? PWM_DUTY_MAX : pan_duty + 5;
        }

        // Set new PWM duty cycles
        gpiod_line_set_value(pan_servo, pan_duty);
        gpiod_line_set_value(tilt_servo, tilt_duty);

        // Sleep for 50 ms
        usleep(50000);
    }

cleanup:
    cleanup(0);
    return 0;
}

