#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <time.h>
#include <libjpeg.h>
#include <libgpiod.h>

#define BUFFER_COUNT 4
#define BUFFER_SIZE (640 * 480 * 2) // YUYV format (2 bytes per pixel)

struct buffer {
    void *data;
    int index;
};

static void cleanup(int fd, struct buffer *buffers, int count) {
    for (int i = 0; i < count; i++) {
        munmap(buffers[i].data, BUFFER_SIZE);
    }
    close(fd);
}

static void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void apply_box_blur(unsigned char *rgb, int width, int height) {
    int kernel_size = 5;
    int half_kernel = kernel_size / 2;
    unsigned char *temp = malloc(width * height * 3);
    if (!temp) {
        handle_error("malloc");
    }

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int sum_r = 0, sum_g = 0, sum_b = 0;
            for (int ky = -half_kernel; ky <= half_kernel; ky++) {
                int y_offset = y + ky;
                if (y_offset < 0 || y_offset >= height) {
                    continue;
                }
                for (int kx = -half_kernel; kx <= half_kernel; kx++) {
                    int x_offset = x + kx;
                    if (x_offset < 0 || x_offset >= width) {
                        continue;
                    }
                    int index = (y_offset * width + x_offset) * 3;
                    sum_r += rgb[index];
                    sum_g += rgb[index + 1];
                    sum_b += rgb[index + 2];
                }
            }
            int index = (y * width + x) * 3;
            temp[index] = sum_r / (kernel_size * kernel_size);
            temp[index + 1] = sum_g / (kernel_size * kernel_size);
            temp[index + 2] = sum_b / (kernel_size * kernel_size);
        }
    }

    memcpy(rgb, temp, width * height * 3);
    free(temp);
}

static void save_jpeg(const char *filename, unsigned char *rgb, int width, int height) {
    struct jpeg_compress_struct jpeg_compress;
    struct jpeg_error_mgr jpeg_error;
    FILE *output = fopen(filename, "wb");
    if (!output) {
        handle_error("fopen");
    }

    jpeg_compress.dest = (struct jpeg_destination_mgr *)malloc(sizeof(struct jpeg_destination_mgr));
    if (!jpeg_compress.dest) {
        handle_error("malloc");
    }

    jpeg_compress.err = jpeg_std_error(&jpeg_error);
    jpeg_create_compress(&jpeg_compress);
    jpeg_compress.dest->init_destination = (void (*) (struct jpeg_compress_struct *)) &jpeg_init_destination;
    jpeg_compress.dest->write_destination = (void (*) (struct jpeg_compress_struct *)) &jpeg_write_destination;
    jpeg_compress.dest->term_destination = (void (*) (struct jpeg_compress_struct *)) &jpeg_term_destination;

    jpeg_compress.image_width = width;
    jpeg_compress.image_height = height;
    jpeg_compress.input_components = 3;
    jpeg_compress.in_color_space = JCS_RGB;
    jpeg_set_defaults(&jpeg_compress);
    jpeg_set_quality(&jpeg_compress, 75, TRUE);

    jpeg_start_compress(&jpeg_compress, TRUE);

    while (jpeg_compress.next_scanline < height) {
        JSAMPROW row_pointer[1] = { (JSAMPROW) rgb + jpeg_compress.next_scanline * width * 3 };
        jpeg_write_scanlines(&jpeg_compress, row_pointer, 1);
    }

    jpeg_finish_compress(&jpeg_compress);
    fclose(output);
    jpeg_destroy_compress(&jpeg_compress);
    free(jpeg_compress.dest);
}

int main() {
    int fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        handle_error("open");
    }

    struct v4l2_format format;
    memset(&format, 0, sizeof(format));
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    format.fmt.pix.width = 640;
    format.fmt.pix.height = 480;
    format.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    format.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &format) < 0) {
        handle_error("VIDIOC_S_FMT");
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        handle_error("VIDIOC_REQBUFS");
    }

    struct buffer buffers[BUFFER_COUNT];
    for (int i = 0; i < BUFFER_COUNT; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            handle_error("VIDIOC_QUERYBUF");
        }
        buffers[i].data = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].data == MAP_FAILED) {
            handle_error("mmap");
        }
        buffers[i].index = i;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_STREAMON, &buf) < 0) {
        handle_error("VIDIOC_STREAMON");
    }

    fd_set readfds;
    struct timeval timeout = { .tv_sec = 2 };
    int ret;
    while (1) {
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);
        ret = select(fd + 1, &readfds, NULL, NULL, &timeout);
        if (ret < 0) {
            handle_error("select");
        }
        if (ret == 0) {
            continue;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            handle_error("VIDIOC_DQBUF");
        }

        unsigned char *yuyv = buffers[buf.index].data;
        unsigned char *rgb = malloc(640 * 480 * 3);
        if (!rgb) {
            handle_error("malloc");
        }

        for (int y = 0; y < 480; y++) {
            for (int x = 0; x < 640; x += 2) {
                int index = (y * 640 + x) * 3;
                rgb[index] = yuyv[y * 640 + x];
                rgb[index + 1] = yuyv[y * 640 + x + 1];
                rgb[index + 2] = yuyv[y * 640 + x];
            }
        }

        apply_box_blur(rgb, 640, 480);

        time_t now = time(NULL);
        char filename[20];
        strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", localtime(&now));
        save_jpeg(filename, rgb, 640, 480);

        free(rgb);
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            handle_error("VIDIOC_QBUF");
        }
    }

    cleanup(fd, buffers, BUFFER_COUNT);
    return 0;
}

