        printf("  %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
        frmsize.index++;
    }
    if (errno != EINVAL) {
        perror("Failed to enumerate frame sizes");
        close(fd);
        return 1;
    }

    // Enumerate supported frame intervals
    memset(&frmival, 0, sizeof(frmival));
    frmival.index = 0;
    frmival.pixel_format = V4L2_PIX_FMT_MJPEG; // Example format, adjust as needed

    printf("Supported frame rates:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
        printf("  %d/%d\n", frmival.discrete.numerator, frmival.discrete.denominator);
        frmival.index++;
    }
    if (errno != EINVAL) {
        perror("Failed to enumerate frame intervals");
        close(fd);
        return 1;
    }

    // Query autofocus support
    memset(&queryctrl, 0, sizeof(queryctrl));
    queryctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == 0) {
        printf("Autofocus is supported.\n");
    } else {
        printf("Autofocus is not supported.\n");
    }

    // Close the device
    close(fd);

    return 0;
}

