#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define CENTER_POSITION 1500
#define MIN_POSITION 1000
#define MAX_POSITION 2000
#define STEP_SIZE 10
#define DELAY_MS 50

volatile int pan_position = CENTER_POSITION;
volatile int tilt_position = CENTER_POSITION;
volatile int running = 1;

void handle_signal(int signum) {
    running = 0;
    gpioServo(PAN_SERVO_PIN, CENTER_POSITION);
    gpioServo(TILT_SERVO_PIN, CENTER_POSITION);
    gpioTerminate();
    exit(0);
}

void setup_servos() {
    if (gpioServo(PAN_SERVO_PIN, pan_position) < 0) {
        fprintf(stderr, "Failed to initialize pan servo on GPIO%d\n", PAN_SERVO_PIN);
        exit(1);
    }
    if (gpioServo(TILT_SERVO_PIN, tilt_position) < 0) {
        fprintf(stderr, "Failed to initialize tilt servo on GPIO%d\n", TILT_SERVO_PIN);
        exit(1);
    }
}

void setup_buttons() {
    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for UP button on GPIO%d\n", UP_BUTTON_PIN);
        exit(1);
    }
    if (gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for DOWN button on GPIO%d\n", DOWN_BUTTON_PIN);
        exit(1);
    }
    if (gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for LEFT button on GPIO%d\n", LEFT_BUTTON_PIN);
        exit(1);
    }
    if (gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for RIGHT button on GPIO%d\n", RIGHT_BUTTON_PIN);
        exit(1);
    }
    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for UP button on GPIO%d\n", UP_BUTTON_PIN);
        exit(1);
    }
    if (gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for DOWN button on GPIO%d\n", DOWN_BUTTON_PIN);
        exit(1);
    }
    if (gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for LEFT button on GPIO%d\n", LEFT_BUTTON_PIN);
        exit(1);
    }
    if (gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for RIGHT button on GPIO%d\n", RIGHT_BUTTON_PIN);
        exit(1);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    printf("Startup: Pan servo on GPIO%d, Tilt servo on GPIO%d, Center position: %d us\n",
           PAN_SERVO_PIN, TILT_SERVO_PIN, CENTER_POSITION);

    setup_servos();
    setup_buttons();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        if (gpioRead(UP_BUTTON_PIN) == 0) {
            tilt_position = (tilt_position + STEP_SIZE > MAX_POSITION) ? MAX_POSITION : tilt_position + STEP_SIZE;
            gpioServo(TILT_SERVO_PIN, tilt_position);
        }
        if (gpioRead(DOWN_BUTTON_PIN) == 0) {
            tilt_position = (tilt_position - STEP_SIZE < MIN_POSITION) ? MIN_POSITION : tilt_position - STEP_SIZE;
            gpioServo(TILT_SERVO_PIN, tilt_position);
        }
        if (gpioRead(LEFT_BUTTON_PIN) == 0) {
            pan_position = (pan_position - STEP_SIZE < MIN_POSITION) ? MIN_POSITION : pan_position - STEP_SIZE;
            gpioServo(PAN_SERVO_PIN, pan_position);
        }
        if (gpioRead(RIGHT_BUTTON_PIN) == 0) {
            pan_position = (pan_position + STEP_SIZE > MAX_POSITION) ? MAX_POSITION : pan_position + STEP_SIZE;
            gpioServo(PAN_SERVO_PIN, pan_position);
        }

        usleep(DELAY_MS * 1000);
    }

    return 0;
}

