#define PULL_DOWN 0
#define DEBOUNCE_TIME 2000 // 2 seconds
#define SNAPSHOT_WIDTH 640
#define SNAPSHOT_HEIGHT 480
#define SNAPSHOT_QUALITY 85
#define SNAPSHOT_FORMAT "jpeg"

static int motion_detected = 0;
static int last_motion_time = 0;
static int last_snapshot_time = 0;
static int snapshot_count = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        gpioTerminate();
        curl_global_cleanup();
        exit(0);
    }
}

void send_json_payload(const char *filename, time_t timestamp, int motion_status, int pin_number, const char *server_ip, int server_port) {
    CURL *curl;
    CURLcode res;
    char payload[256];
    char url[128];

    snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        snprintf(payload, sizeof(payload), "{\"filename\": \"%s\", \"timestamp\": \"%ld\", \"motion_status\": %d, \"pin_number\": %d}", filename, (long)timestamp, motion_status, pin_number);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE_LARGE, strlen(payload));
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioGetErrorStr(pigtailGetError()));
        return 1;
    }

    if (gpioSetMode(17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as input: %s\n", pigpioGetErrorStr(pigtailGetError()));
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(17, PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO17: %s\n", pigpioGetErrorStr(pigtailGetError()));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    char snapshot_dir[128] = "motion_captures";
    mkdir(snapshot_dir, 0755);
    if (errno == EEXIST) {
        printf("Directory '%s' already exists.\n", snapshot_dir);
    } else if (errno != 0) {
        fprintf(stderr, "Failed to create directory '%s': %s\n", snapshot_dir, strerror(errno));
        gpioTerminate();
        return 1;
    }

    while (1) {
        int current_level = gpioRead(17);
        if (current_level == 1 && (time(NULL) - last_motion_time) > DEBOUNCE_TIME) {
            if (!motion_detected) {
                motion_detected = 1;
                last_motion_time = time(NULL);

                char snapshot_filename[128];
                snprintf(snapshot_filename, sizeof(snapshot_filename), "%s/motion_%04d.jpg", snapshot_dir, snapshot_count++);

