                } else {
                    time_t timestamp = time(NULL);
                    send_json_payload(snapshot_filename, timestamp, 1, 17, argv[1], atoi(argv[2]));
                }
            }
        } else if (current_level == 0) {
            motion_detected = 0;
        }

        usleep(100000); // 100 ms
    }

    return 0;
}
