static gpiod_line *line;
static FILE *log_file;

void cleanup(int signum) {
    if (line) {
        gpiod_line_free(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    char filename[256];
    int ret;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return 1;
    }

    // Claim GPIO17 as input
    line = gpiod_line_request(chip, GPIO_PIN, "motion_sensor", 0, GPIOD_LINE_DIRECTION_IN);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        fclose(log_file);
        return 1;
    }

    // Set edge detection
    gpiod_line_set_debounce(line, DEBOUNCE_MS);
    gpiod_line_set_edge(line, GPIOD_LINE_EDGE_RISING);

    // Register cleanup function for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        // Read GPIO state
        int state = gpiod_line_get_value(line);

        // Check for motion (falling edge)
        if (state == 0) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            sprintf(filename, "%04d%02d%02d_%02d%02d%02d_%.3d.jpg",
                    tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                    tm->tm_hour, tm->tm_min, tm->tm_sec,
                    rand() % 1000);

            char cmd[256];
            sprintf(cmd, "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename);

            printf("Capturing image: %s\n", cmd);
            fputs("Capturing image: ", log_file);
            fputs(cmd, log_file);
            fputs("\n", log_file);

            ret = system(cmd);
            if (ret != 0) {
                fprintf(log_file, "Failed to capture image: %s\n", filename);
            } else {
                fprintf(log_file, "Image captured: %s\n", filename);
            }
        }

        // Sleep for a short period
        usleep(100000);
    }

    return 0;
}

