#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <signal.h>
#include <linux/videodev2.h>

#define BUFFER_COUNT 1
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150

static void cleanup(void) {
    munmap(buffers[0].start, buffers[0].length);
    close(fd);
    free(buffers);
}

static void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct v4l2_crop crop;
    struct v4l2_plane planes[1];
    struct v4l2_buffer mapped_buf;
    char *buffer_data;
    FILE *out_file;

    int fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        exit(EXIT_FAILURE);
    }

    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        exit(EXIT_FAILURE);
    }

    struct v4l2_buffer *buffers = malloc(sizeof(struct v4l2_buffer) * BUFFER_COUNT);
    if (!buffers) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        memset(&buffers[i], 0, sizeof(struct v4l2_buffer));
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buffers[i]) < 0) {
            perror("VIDIOC_QUERYBUF");
            exit(EXIT_FAILURE);
        }

        buffers[i].start = mmap(NULL, buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buffers[i].m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
    }

    crop.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    crop.c = { .left = CROP_X, .top = CROP_Y, .width = CROP_WIDTH, .height = CROP_HEIGHT };

    if (ioctl(fd, VIDIOC_S_CROP, &crop) < 0) {
        perror("VIDIOC_S_CROP");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_STREAMON, &fmt) < 0) {
        perror("VIDIOC_STREAMON");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    out_file = fopen("cropped.yuv", "wb");
    if (!out_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        if (select(fd + 1, &fds, NULL, NULL, NULL) < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("select");
            exit(EXIT_FAILURE);
        }

        if (FD_ISSET(fd, &fds)) {
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;

            if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
                if (errno == EAGAIN) {
                    continue;
                }
                perror("VIDIOC_DQBUF");
                exit(EXIT_FAILURE);
            }

            if (buf.width != fmt.fmt.pix.width || buf.height != fmt.fmt.pix.height || buf.format != fmt.fmt.pix.pixelformat) {
                fprintf(stderr, "Captured frame size or format mismatch\n");
                exit(EXIT_FAILURE);
            }

            buffer_data = (char *)buffers[buf.index].start;

            for (int y = 0; y < CROP_HEIGHT; y++) {
                for (int x = 0; x < CROP_WIDTH; x += 2) {
                    fwrite(&buffer_data[((y + CROP_Y) * fmt.fmt.pix.bytesperline) + ((x + CROP_X) * 2)], 2, 1, out_file);
                }
            }

            if (fwrite(NULL, 0, 0, out_file) != 0) {
                perror("fwrite");
                exit(EXIT_FAILURE);
            }

            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF");
                exit(EXIT_FAILURE);
            }
        }
    }

    fclose(out_file);
    cleanup();

    return EXIT_SUCCESS;
}

