    char cpu_usage_str[10];
    FILE *cpu_file = fopen("/proc/stat", "r");
    if (cpu_file == NULL) {
        display_text(x, y, "Error: CPU");
        return;
    }
    char line[256];
    while (fgets(line, sizeof(line), cpu_file)) {
        if (strncmp(line, "cpu ", 4) == 0) {
            char *token = strtok(line + 4, " ");
            long total = 0, idle = 0;
            while (token != NULL) {
                if (strcmp(token, "user") == 0 || strcmp(token, "nice") == 0 ||
                    strcmp(token, "system") == 0 || strcmp(token, "iowait") == 0 ||
