This code provides a basic implementation for displaying real-time CPU temperature and usage on an SSD1306 OLED screen using the pigpio library. It includes error handling for file reads and I2C communication, as well as signal handling for graceful shutdown. Note that the bitmap font data is not included in this example; you would need to define the `font` array with the appropriate 5x7 pixel data for each character.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define WATER_FLOW_SENSOR_PIN 17
#define LCD_I2C_BUS 1
#define LCD_I2C_ADDRESS 0x27
#define PULSES_PER_LITER 450
#define UPDATE_INTERVAL 1000  // 1 second
#define LCD_UPDATE_INTERVAL 10000  // 10 seconds

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

void update_lcd(double flow_rate, double total_volume) {
    char buffer[32];
    sprintf(buffer, "Flow: %.2f L/min, Total: %.2f L", flow_rate, total_volume);

    int result = i2c_write_device(LCD_I2C_BUS, LCD_I2C_ADDRESS, (unsigned char*)buffer, strlen(buffer));
    if (result < 0) {
        fprintf(stderr, "Error writing to LCD: %s\n", pigpio_perror(result));
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_perror(gpioInitialise()));
        return 1;
    }

    if (i2cOpen(LCD_I2C_BUS, LCD_I2C_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", pigpio_perror(i2cOpen(LCD_I2C_BUS, LCD_I2C_ADDRESS, 0)));
        gpioTerminate();
        return 1;
    }

    gpioSetMode(WATER_FLOW_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(WATER_FLOW_SENSOR_PIN, PI_PUD_OFF);

    double total_volume = 0.0;
    double last_update_time = 0.0;
    double last_pulse_count = 0.0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        double current_time = pigpioGetTime();
        int pulse_count = gpioGetPulseLength(WATER_FLOW_SENSOR_PIN, 0, -1);

        if (pulse_count < 0) {
            fprintf(stderr, "Error reading pulse length: %s\n", pigpio_perror(pulse_count));
            continue;
        }

        double elapsed_time = current_time - last_update_time;
        if (elapsed_time >= UPDATE_INTERVAL) {
            double flow_rate = (pulse_count - last_pulse_count) / (elapsed_time / 1000.0) * 60.0 / PULSES_PER_LITER;
            total_volume += flow_rate * elapsed_time / 60.0;

            printf("Flow rate: %.2f L/min, Total volume: %.2f L\n", flow_rate, total_volume);

            if (current_time - last_update_time >= LCD_UPDATE_INTERVAL) {
                update_lcd(flow_rate, total_volume);
                last_update_time = current_time;
            }

            last_update_time = current_time;
            last_pulse_count = pulse_count;
        }

        usleep(100000);  // Sleep for 100 ms
    }

    i2cClose(LCD_I2C_BUS, LCD_I2C_ADDRESS);
    gpioTerminate();

    return 0;
}

