This C program reads pulses from a YF-S201 water flow sensor connected to GPIO17 on a Raspberry Pi 4 Model B. It calculates the flow rate in liters per minute and logs the current flow rate and the running total volume to the console every 1 second. Every 10 seconds, it updates an HD44780 LCD screen connected via I2C to display the current flow rate and the accumulated volume. The program handles GPIO initialization failures, I2C communication errors, and SIGINT and SIGTERM signals for a graceful shutdown that releases all GPIO and I2C resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define LCD_I2C_ADDR 0x27
#define LCD_I2C_BUS 1
#define LCD_ROWS 2
#define LCD_COLS 16

#define WIND_SPEED_SCALE 0.5
#define WIND_VANA_ADC_CHANNEL 0
#define WIND_VANA_ADC_MAX 1023
#define WIND_VANA_ANGLE_MAX 359

volatile int pulse_count = 0;
volatile int wind_speed = 0;
volatile int wind_direction = 0;

void handle_interrupt(int gpio, int level, uint32_t tick) {
    pulse_count++;
}

void handle_signal(int signum) {
    if (pigpio_i2c_close(lcd_handle) < 0) {
        fprintf(stderr, "Failed to close I2C handle.\n");
    }
    if (pigpio_spi_close(spi_handle) < 0) {
        fprintf(stderr, "Failed to close SPI handle.\n");
    }
    if (pigpio_stop() < 0) {
        fprintf(stderr, "Failed to stop pigpio.\n");
    }
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (pigpio_i2c_open(LCD_I2C_BUS, LCD_I2C_ADDR, &lcd_handle) < 0) {
        fprintf(stderr, "Failed to open I2C handle for LCD.\n");
        return 1;
    }

    if (pigpio_spi_open(0, 0, &spi_handle) < 0) {
        fprintf(stderr, "Failed to open SPI handle.\n");
        return 1;
    }

    if (gpioSetMode(17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as input.\n");
        return 1;
    }

    if (gpioSetAlertFunc(17, handle_interrupt) < 0) {
        fprintf(stderr, "Failed to set alert function for GPIO17.\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        wind_speed = pulse_count * WIND_SPEED_SCALE;
        pulse_count = 0;

        uint8_t adc_data[2];
        if (pigpio_spi_read(spi_handle, adc_data, 2) < 0) {
            fprintf(stderr, "Failed to read ADC data.\n");
            continue;
        }

        uint16_t adc_value = (adc_data[1] << 8) | adc_data[0];
        if (adc_value == 0 || adc_value == WIND_VANA_ADC_MAX) {
            fprintf(stderr, "ADC reading stuck at 0 or 1023, assuming sensor absent.\n");
            wind_direction = 0;
        } else {
            wind_direction = (adc_value * WIND_VANA_ANGLE_MAX) / WIND_VANA_ADC_MAX;
        }

        char wind_speed_str[10];
        char wind_direction_str[10];
        sprintf(wind_speed_str, "%.1f", wind_speed);
        sprintf(wind_direction_str, "%d", wind_direction);

        uint8_t lcd_buffer[LCD_ROWS * LCD_COLS / 8];
        memset(lcd_buffer, 0, sizeof(lcd_buffer));

        sprintf((char*)lcd_buffer, "WS: %s m/s", wind_speed_str);
        sprintf((char*)lcd_buffer + 16, "WD: %s deg", wind_direction_str);

        if (pigpio_i2c_write_device(lcd_handle, lcd_buffer, sizeof(lcd_buffer)) < 0) {
            fprintf(stderr, "Failed to write to LCD.\n");
        }

        usleep(500000);
    }

    return 0;
}

