        return 1;
    }

    if (pigpio_i2c_open(LCD_I2C_BUS, LCD_I2C_ADDR, &lcd_handle) < 0) {
        fprintf(stderr, "Failed to open I2C handle for LCD.\n");
        return 1;
    }

    if (pigpio_spi_open(0, 0, &spi_handle) < 0) {
        fprintf(stderr, "Failed to open SPI handle.\n");
        return 1;
    }

    if (gpioSetMode(17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as input.\n");
        return 1;
    }

    if (gpioSetAlertFunc(17, handle_interrupt) < 0) {
        fprintf(stderr, "Failed to set alert function for GPIO17.\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        wind_speed = pulse_count * WIND_SPEED_SCALE;
        pulse_count = 0;

        uint8_t adc_data[2];
        if (pigpio_spi_read(spi_handle, adc_data, 2) < 0) {
            fprintf(stderr, "Failed to read ADC data.\n");
            continue;
        }

        uint16_t adc_value = (adc_data[1] << 8) | adc_data[0];
        if (adc_value == 0 || adc_value == WIND_VANA_ADC_MAX) {
            fprintf(stderr, "ADC reading stuck at 0 or 1023, assuming sensor absent.\n");
            wind_direction = 0;
        } else {
            wind_direction = (adc_value * WIND_VANA_ANGLE_MAX) / WIND_VANA_ADC_MAX;
        }

        char wind_speed_str[10];
        char wind_direction_str[10];
        sprintf(wind_speed_str, "%.1f", wind_speed);
        sprintf(wind_direction_str, "%d", wind_direction);

        uint8_t lcd_buffer[LCD_ROWS * LCD_COLS / 8];
        memset(lcd_buffer, 0, sizeof(lcd_buffer));

        sprintf((char*)lcd_buffer, "WS: %s m/s", wind_speed_str);
        sprintf((char*)lcd_buffer + 16, "WD: %s deg", wind_direction_str);

        if (pigpio_i2c_write_device(lcd_handle, lcd_buffer, sizeof(lcd_buffer)) < 0) {
            fprintf(stderr, "Failed to write to LCD.\n");
        }

        usleep(500000);
    }

    return 0;
}
