    int flow_pin = 17;
    int pulses = 0;
    float flow_rate = 0.0;
    float calibration_factor = 7.5;
    float liters_per_minute = 0.0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(flow_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for flow pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(flow_pin, &pulses) < 0) {
        fprintf(stderr, "Failed to set alert function for flow pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init();
    lcd_clear();
    lcd_print("Flow Rate:");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        sleep(1);
        if (pulses > 0) {
            liters_per_minute = (pulses / calibration_factor) * 60;
            char buffer[32];
            sprintf(buffer, "%5.2f L/min", liters_per_minute);
            lcd_clear();
            lcd_print(buffer);
            pulses = 0;
        }
