#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define ROWS 8
#define COLS 8
#define SCAN_DELAY 800 // microseconds

gpiod_chip *chip;
gpiod_line *rows[ROWS];
gpiod_line *cols[COLS];

void cleanup(int signum) {
    for (int i = 0; i < ROWS; i++) {
        gpiod_line_request_free(rows[i]);
    }
    for (int i = 0; i < COLS; i++) {
        gpiod_line_request_free(cols[i]);
    }
    gpiod_chip_put(chip);
    exit(0);
}

void wave_animation(int direction) {
    int pattern[ROWS][COLS] = {0};
    int shift = 0;

    while (1) {
        for (int row = 0; row < ROWS; row++) {
            for (int col = 0; col < COLS; col++) {
                int index = (row + shift + COLS) % COLS;
                if (pattern[row][index] == 1) {
                    gpiod_line_set_value(cols[col], 0);
                } else {
                    gpiod_line_set_value(cols[col], 1);
                }
            }
            gpiod_line_set_value(rows[row], 1);
            usleep(SCAN_DELAY * 1000); // Convert microseconds to nanoseconds
            gpiod_line_set_value(rows[row], 0);
        }

        if (direction == 1) {
            shift = (shift + 1) % COLS;
        } else {
            shift = (shift + COLS - 1) % COLS;
        }

        usleep(1000000); // 1 second delay between frames
    }
}

int main() {
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    for (int i = 0; i < ROWS; i++) {
        rows[i] = gpiod_line_request_by_name(chip, "gpio%d", i + 17, "row", GPIOD_LINE_DIRECTION_OUTPUT);
        if (!rows[i]) {
            fprintf(stderr, "Failed to request row %d\n", i + 17);
            return 1;
        }
    }

    for (int i = 0; i < COLS; i++) {
        cols[i] = gpiod_line_request_by_name(chip, "gpio%d", i + 5, "col", GPIOD_LINE_DIRECTION_OUTPUT);
        if (!cols[i]) {
            fprintf(stderr, "Failed to request column %d\n", i + 5);
            return 1;
        }
    }

    signal(SIGINT, cleanup);

    wave_animation(1); // Start left-to-right wave animation

    return 0;
}

