This C program uses the libgpiod library to control an 8x8 common-anode LED matrix on a Raspberry Pi. It sets up the GPIO lines for rows and columns, then implements a scanning display function to create a wave-like animation. The program handles errors by checking the return values of libgpiod calls and prints descriptive error messages to stderr. It also gracefully handles SIGINT by releasing GPIO lines and cleaning up resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define ROW_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define COL_PINS {14, 15, 18, 23, 24, 25, 8, 7}

static gpiod_chip *chip;
static gpiod_line *row_lines[8];
static gpiod_line *col_lines[8];

void cleanup(int signum) {
    for (int i = 0; i < 8; i++) {
        if (row_lines[i]) {
            gpiod_line_free(row_lines[i]);
        }
        if (col_lines[i]) {
            gpiod_line_free(col_lines[i]);
        }
    }
    gpiod_chip_put(chip);
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0", 0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO lines for rows and columns
    for (int i = 0; i < 8; i++) {
        row_lines[i] = gpiod_line_request(chip, ROW_PINS[i], "row", 0, GPIOD_LINE_DIRECTION_OUTPUT);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to request row GPIO %d\n", ROW_PINS[i]);
            cleanup(0);
        }

        col_lines[i] = gpiod_line_request(chip, COL_PINS[i], "col", 0, GPIOD_LINE_DIRECTION_OUTPUT);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to request column GPIO %d\n", COL_PINS[i]);
            cleanup(0);
        }
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main animation loop
    while (1) {
        for (int col = 0; col < 8; col++) {
            // Clear the matrix
            for (int row = 0; row < 8; row++) {
                gpiod_line_set_value(row_lines[row], 0);
                gpiod_line_set_value(col_lines[col], 1);
            }
            usleep(150000); // 150 ms delay

            // Light the column
            gpiod_line_set_value(col_lines[col], 0);
            for (int row = 0; row < 8; row++) {
                gpiod_line_set_value(row_lines[row], 1);
            }
            usleep(150000); // 150 ms delay
        }
    }

    return 0;
}

