#define VL53L3CX_I2C_ADDR 0x29
#define VL53L3CX_MODEL_ID 0x00
#define VL53L3CX_MEASURE_PERIOD 100 // ms

void handle_sigint(int signum) {
    printf("\nReceived SIGINT, cleaning up...\n");
    gpioTerminate();
    exit(0);
}

int init_sensor() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return -1;
    }

    // Stub proprietary firmware download (not implemented here)
    // ...

    // Verify sensor model ID
    uint8_t model_id[2];
    if (i2cReadDevice(1, VL53L3CX_I2C_ADDR, VL53L3CX_MODEL_ID, model_id, 2) < 0) {
        fprintf(stderr, "Failed to read sensor model ID.\n");
        gpioTerminate();
        return -1;
    }

    if (model_id[0] != 0x56 || model_id[1] != 0x4C) {
        fprintf(stderr, "Invalid sensor model ID.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

int read_distance() {
    uint8_t data[2];
    if (i2cReadDevice(1, VL53L3CX_I2C_ADDR, 0x83, data, 2) < 0) {
        fprintf(stderr, "Failed to read distance.\n");
        return -1;
    }

    int distance = (data[0] << 8) | data[1];
    return distance;
}

int main() {
    signal(SIGINT, handle_sigint);

    if (init_sensor() < 0) {
        return 1;
    }

    while (1) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm - %s\n", distance, gmtime_r((time_t *)&distance, gmtime_r_buf));
        }
        usleep(VL53L3CX_MEASURE_PERIOD * 1000); // Sleep for 100 ms
    }

    return 0;
}

