code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x60
#define PART_ID_REG 0x00
#define COMMAND_REG 0x18

FILE *log_file;

void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (pi >= 0) {
        i2cUnexport(I2C_BUS, SENSOR_ADDR);
        gpioTerminate();
    }
    exit(1);
}

int main() {
    int pi = -1;
    int part_id;
    int status;
    char timestamp[20];
    struct tm *time_info;

    // Initialize pigpio
    if ((pi = pigpio_start()) < 0) {
        fprintf(stderr, "pigpio_start failed\n");
        return 1;
    }

    // Export I2C bus
    if (i2c_export(I2C_BUS, SENSOR_ADDR) < 0) {
        fprintf(stderr, "i2c_export failed\n");
        goto cleanup;
    }

    // Open log file
    if ((log_file = fopen("biometric_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Verify PART ID
    if (i2c_read_byte_data(I2C_BUS, SENSOR_ADDR, PART_ID_REG) < 0) {
        fprintf(stderr, "Failed to read PART ID\n");
        goto cleanup;
    }
    part_id = i2c_read_byte_data(I2C_BUS, SENSOR_ADDR, PART_ID_REG);
    if (part_id != 0x45) {
        fprintf(stderr, "Invalid PART ID: 0x%02X\n", part_id);
        goto cleanup;
    }

    // Initialize sensor
    if (i2c_write_byte_data(I2C_BUS, SENSOR_ADDR, COMMAND_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Read proximity and ambient light data
        int proximity = i2c_read_byte_data(I2C_BUS, SENSOR_ADDR, 0x0F);
        int ambient_light = i2c_read_byte_data(I2C_BUS, SENSOR_ADDR, 0x10);

        // Log data
        time_info = localtime(&time(NULL));
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);
        fprintf(log_file, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);
        fflush(log_file);

        // Sleep for 500 ms
        usleep(500000);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (pi >= 0) {
        i2cUnexport(I2C_BUS, SENSOR_ADDR);
        gpioTerminate();
    }
    return (pi < 0) ? 1 : 0;
}

