#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_SENSOR 4
#define GPIO_LED 17
#define POLL_INTERVAL 100 // ms

static void handle_error(const char *msg, int err) {
    fprintf(stderr, "%s: %s\n", msg, gpiod_get_error_string(err));
    exit(EXIT_FAILURE);
}

static void blink_led(struct gpiod_line *led) {
    gpiod_line_set_value(led, 1); // Turn LED ON
    usleep(100 * 1000); // 100 ms
    gpiod_line_set_value(led, 0); // Turn LED OFF
}

static void log_event(const char *event) {
    FILE *log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%FT%T%z", utc_time);

    fprintf(log_file, "%s %s\n", timestamp, event);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor = NULL;
    struct gpiod_line *led = NULL;

    int err;

    // Open GPIO chip
    err = gpiod_chip_open_by_name("gpiochip4", &chip);
    if (err < 0) {
        err = gpiod_chip_open_by_name("gpiochip0", &chip);
        if (err < 0) {
            handle_error("Failed to open GPIO chip", err);
        }
    }

    // Request GPIO lines
    err = gpiod_line_request_by_name(chip, "gpio%d", GPIO_SENSOR, "sensor", &sensor, GPIOD_LINE_DIRECTION_IN);
    if (err < 0) {
        handle_error("Failed to request sensor GPIO line", err);
    }

    err = gpiod_line_request_by_name(chip, "gpio%d", GPIO_LED, "led", &led, GPIOD_LINE_DIRECTION_OUT);
    if (err < 0) {
        handle_error("Failed to request LED GPIO line", err);
    }

    // Set LED to OFF initially
    gpiod_line_set_value(led, 0);

    int prev_value = 1; // Assume initially no object detected (HIGH)

    while (1) {
        int current_value;
        err = gpiod_line_get_value(sensor, &current_value);
        if (err < 0) {
            handle_error("Failed to read sensor value", err);
        }

        if (prev_value == 1 && current_value == 0) { // Falling edge detected (object entered range)
            blink_led(led);
            log_event("Object detected");
        }

        prev_value = current_value;
        usleep(POLL_INTERVAL * 1000); // Sleep for 100 ms
    }

    // Cleanup
    if (sensor) {
        gpiod_line_free(sensor);
    }
    if (led) {
        gpiod_line_free(led);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }

    return 0;
}

