    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, SENSOR_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d for sensor at address 0x%02X.\n", I2C_BUS, SENSOR_ADDR);
        return 1;
    }

    // Verify PART_ID
    uint8_t part_id;
    if (i2cRead(I2C_BUS, SENSOR_ADDR, PART_ID, &part_id, 1) < 0) {
        fprintf(stderr, "Failed to read PART_ID from sensor.\n");
        return 1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Invalid PART_ID: expected 0x45, got 0x%02X.\n", part_id);
        return 1;
    }

    // Write HW_KEY
    uint8_t hw_key = 0x17;
    if (i2cWrite(I2C_BUS, SENSOR_ADDR, HW_KEY, &hw_key, 1) < 0) {
        fprintf(stderr, "Failed to write HW_KEY to sensor.\n");
        return 1;
    }

    // Set CH_LIST
    uint8_t ch_list = 0x03; // Enable PS1 and ALS_VIS
    if (i2cWrite(I2C_BUS, SENSOR_ADDR, CH_LIST, &ch_list, 1) < 0) {
        fprintf(stderr, "Failed to set CH_LIST on sensor.\n");
        return 1;
    }

    // Configure measurement rates
    uint8_t rate_config = 0x00; // Default rates
    if (i2cWrite(I2C_BUS, SENSOR_ADDR, 0x46, &rate_config, 1) < 0) {
        fprintf(stderr, "Failed to configure measurement rates on sensor.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Infinite loop to read data
    while (1) {
        uint8_t ps1_data[PS1_DATA_LEN];
        uint8_t als_vis_data[ALS_VIS_DATA_LEN];

        // Trigger measurements
        if (i2cWrite(I2C_BUS, SENSOR_ADDR, COMMAND, &PS_FORCE, 1) < 0 ||
            i2cWrite(I2C_BUS, SENSOR_ADDR, COMMAND, &ALS_FORCE, 1) < 0) {
            fprintf(stderr, "Failed to trigger measurements.\n");
            continue;
        }

        // Read PS1 data
        if (i2cRead(I2C_BUS, SENSOR_ADDR, PS1_DATA, ps1_data, PS1_DATA_LEN) < 0) {
            fprintf(stderr, "Failed to read PS1 data.\n");
            continue;
        }

        // Read ALS_VIS data
        if (i2cRead(I2C_BUS, SENSOR_ADDR, ALS_VIS_DATA, als_vis_data, ALS_VIS_DATA_LEN) < 0) {
            fprintf(stderr, "Failed to read ALS_VIS data.\n");
            continue;
        }

        // Convert to little-endian
        uint16_t ps1_value = (ps1_data[1] << 8) | ps1_data[0];
        uint16_t als_vis_value = (als_vis_data[1] << 8) | als_vis_data[0];

