        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", now_tm);

        fprintf(log_file, "%s,%u,%u\n", timestamp, ps1_value, als_vis_value);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    i2cClose(I2C_BUS, SENSOR_ADDR);
    gpioTerminate();

    return 0;
}
