#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define VOLTAGE_DIVIDER_FACTOR 3.3 / 5.0
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define WATERING_THRESHOLD 15
#define POLL_INTERVAL 60
#define TIMEOUT_INTERVAL 30

static gpiod_chip *chip;
static gpiod_line *trigger_line;
static gpiod_line *echo_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (trigger_line) {
        gpiod_line_request_free(trigger_line);
    }
    if (echo_line) {
        gpiod_line_request_free(echo_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum == SIGINT ? 0 : 1);
}

void log_measurement(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s %s\n", buffer, message);
    fflush(log_file);
}

int main() {
    int err;
    struct gpiod_line_request_config trigger_config = {
        .consumer = "trigger",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .flags = GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
    };

    struct gpiod_line_request_config echo_config = {
        .consumer = "echo",
        .request_type = GPIOD_LINE_REQUEST_INPUT,
        .flags = GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    struct gpiod_line_event_config echo_event_config = {
        .event_type = GPIOD_LINE_EVENT_BOTH_EDGES,
        .debounce_timeout_ns = 10000000, // 10ms debounce
    };

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    trigger_line = gpiod_line_request_by_name(chip, "gpio%d", TRIGGER_PIN, &trigger_config);
    if (!trigger_line) {
        perror("Failed to request trigger line");
        goto error_trigger;
    }

    echo_line = gpiod_line_request_by_name(chip, "gpio%d", ECHO_PIN, &echo_config);
    if (!echo_line) {
        perror("Failed to request echo line");
        goto error_echo;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto error_log;
    }

    struct gpiod_line_event *echo_event = gpiod_line_event_request(echo_line, &echo_event_config);
    if (!echo_event) {
        perror("Failed to request echo event");
        goto error_event;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        struct timespec timeout = { .tv_sec = TIMEOUT_INTERVAL / 1000, .tv_nsec = (TIMEOUT_INTERVAL % 1000) * 1000000 };
        struct timespec start_time = { .tv_sec = 0, .tv_nsec = 0 };
        struct timespec end_time = { .tv_sec = 0, .tv_nsec = 0 };
        double pulse_seconds = 0;

        gpiod_line_set_value(trigger_line, 0);
        nanosleep(&start_time, NULL);
        gpiod_line_set_value(trigger_line, 1);
        nanosleep(&start_time, NULL);
        gpiod_line_set_value(trigger_line, 0);

        err = gpiod_line_event_wait(echo_event, &end_time, &timeout);
        if (err == -ETIMEDOUT) {
            log_measurement("Timeout: Sensor absent");
            continue;
        } else if (err < 0) {
            perror("Error waiting for echo event");
            goto error_event;
        }

        pulse_seconds = (double)(end_time.tv_sec - start_time.tv_sec) + (double)(end_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;
        double distance = (pulse_seconds * 34300) / 2 * VOLTAGE_DIVIDER_FACTOR;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            log_measurement("Invalid reading");
            continue;
        }

        log_measurement(sprintf("Distance: %.2f cm", distance));

        if (distance < WATERING_THRESHOLD) {
            log_measurement("Time to water the plant!");
        }

        nanosleep(&start_time, NULL);
        sleep(POLL_INTERVAL);
    }

error_event:
    gpiod_line_event_free(echo_event);
error_log:
    fclose(log_file);
error_echo:
    gpiod_line_request_free(echo_line);
error_trigger:
    gpiod_line_request_free(trigger_line);
error_chip:
    gpiod_chip_put(chip);
    return 1;
}

