#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define SENSOR_ID_REG 0x92
#define ENABLE_REG 0x80
#define ATIME_REG 0x81
#define WTIME_REG 0x83
#define PPULSE_REG 0x8E
#define CONTROL_REG 0xF1
#define CONFIG2_REG 0x90
#define RGB_REG_START 0x96
#define PROXIMITY_REG 0x9C
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"

FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle) {
        i2c_close(i2c_handle);
    }
    if (pi_connected) {
        pi_stop();
    }
    exit(signum);
}

void init_sensor() {
    uint8_t sensor_id;
    uint8_t enable_reg_val = 0x03;
    uint8_t atime_reg_val = 0xDB;
    uint8_t wtime_reg_val = 0xF6;
    uint8_t ppulse_reg_val = 0x87;
    uint8_t control_reg_val = 0x03;
    uint8_t config2_reg_val = 0x01;

    if (i2c_write_device(i2c_handle, I2C_ADDR, &sensor_id, 1) < 0) {
        fprintf(stderr, "Failed to read sensor ID register.\n");
        exit(1);
    }

    if (sensor_id != 0xAB) {
        fprintf(stderr, "Invalid sensor ID. Expected 0xAB, got 0x%02X.\n", sensor_id);
        exit(1);
    }

    if (i2c_write_device(i2c_handle, I2C_ADDR, &enable_reg_val, 1) < 0) {
        fprintf(stderr, "Failed to write ENABLE register.\n");
        exit(1);
    }

    if (i2c_write_device(i2c_handle, I2C_ADDR, &atime_reg_val, 1) < 0) {
        fprintf(stderr, "Failed to write ATIME register.\n");
        exit(1);
    }

    if (i2c_write_device(i2c_handle, I2C_ADDR, &wtime_reg_val, 1) < 0) {
        fprintf(stderr, "Failed to write WTIME register.\n");
        exit(1);
    }

    if (i2c_write_device(i2c_handle, I2C_ADDR, &ppulse_reg_val, 1) < 0) {
        fprintf(stderr, "Failed to write PPULSE register.\n");
        exit(1);
    }

    if (i2c_write_device(i2c_handle, I2C_ADDR, &control_reg_val, 1) < 0) {
        fprintf(stderr, "Failed to write CONTROL register.\n");
        exit(1);
    }

    if (i2c_write_device(i2c_handle, I2C_ADDR, &config2_reg_val, 1) < 0) {
        fprintf(stderr, "Failed to write CONFIG2 register.\n");
        exit(1);
    }
}

int main() {
    int i2c_handle;
    uint8_t rgb_data[6];
    uint8_t proximity_data;
    uint32_t timestamp;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        return 1;
    }

    init_sensor();

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (i2c_read_device(i2c_handle, I2C_ADDR, rgb_data, 6) < 0) {
            fprintf(stderr, "Failed to read RGB data.\n");
            i2c_close(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reopen I2C bus.\n");
                handle_signal(1);
            }
            init_sensor();
            continue;
        }

        if (i2c_read_device(i2c_handle, I2C_ADDR, &proximity_data, 1) < 0) {
            fprintf(stderr, "Failed to read proximity data.\n");
            i2c_close(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reopen I2C bus.\n");
                handle_signal(1);
            }
            init_sensor();
            continue;
        }

        timestamp = time(NULL);
        if (proximity_data > PROXIMITY_THRESHOLD) {
            fprintf(log_file, "%lu,%02X,%02X,%02X,%02X,%02X,%02X\n", timestamp, rgb_data[0], rgb_data[1], rgb_data[2], rgb_data[3], rgb_data[4], rgb_data[5], proximity_data);
        }

        usleep(100000); // 100 ms delay
    }

    fclose(log_file);
    i2c_close(i2c_handle);
    pi_stop();

    return 0;
}

