            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reopen I2C bus.\n");
                handle_signal(1);
            }
            init_sensor();
            continue;
        }

        timestamp = time(NULL);
        if (proximity_data > PROXIMITY_THRESHOLD) {
