#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x5A
#define PART_ID_REGISTER 0x00
#define MEAS_RATE0_REGISTER 0x08
#define COMMAND_REGISTER 0x47
#define PS_DATA0_REGISTER 0x24
#define PS_DATA1_REGISTER 0x25
#define RATE_VALUE 0x01
#define RESET_COMMAND 0x00
#define SAMPLE_INTERVAL 100 // ms

volatile sig_atomic_t running = true;

void handle_signal(int signum) {
    running = false;
}

int main() {
    int fd;
    char filename[] = "heartrate.csv";
    FILE *csv_file;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Verify PART_ID
    uint8_t part_id;
    if (read_register(fd, PART_ID_REGISTER, &part_id) < 0) {
        perror("Failed to read PART_ID register");
        close(fd);
        return 1;
    }
    if (part_id != 0x52) {
        fprintf(stderr, "Invalid PART_ID: expected 0x52, got 0x%02X\n", part_id);
        close(fd);
        return 1;
    }

    // Configure continuous proximity measurement
    if (write_register(fd, MEAS_RATE0_REGISTER, RATE_VALUE) < 0) {
        perror("Failed to configure MEAS_RATE0 register");
        close(fd);
        return 1;
    }

    // Start measurement
    if (write_register(fd, COMMAND_REGISTER, RESET_COMMAND) < 0) {
        perror("Failed to start measurement");
        close(fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(filename, "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(fd);
        return 1;
    }

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (running) {
        uint16_t proximity_data;
        if (read_register(fd, PS_DATA0_REGISTER, (uint8_t*)&proximity_data) < 0 ||
            read_register(fd, PS_DATA1_REGISTER, (uint8_t*)&proximity_data + 1) < 0) {
            fprintf(stderr, "Failed to read proximity data\n");
            continue;
        }

        // Compute placeholder BPM
        int bpm = proximity_data / 10; // Placeholder calculation

        // Log sample
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);
        fprintf(csv_file, "%s,%d\n", timestamp, bpm);
        fflush(csv_file);

        // Sleep for 100 ms
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Cleanup
    fclose(csv_file);
    close(fd);

    return 0;
}

int read_register(int fd, uint8_t reg, uint8_t *data) {
    return i2c_smbus_read_byte_data(fd, reg);
}

int write_register(int fd, uint8_t reg, uint8_t data) {
    return i2c_smbus_write_byte_data(fd, reg, data);
}

