This C program interfaces with a Silicon Labs Si1182-A-GMR optical sensor on a Raspberry Pi 5 using the Linux i2c-dev kernel interface. It verifies the sensor's part ID, configures continuous proximity measurement, and logs heart rate data every 100 ms to a CSV file. It handles errors gracefully and installs a signal handler for clean shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B
#define RESULT_DATA_RATE_MCPS 0x0D
#define RESULT_RANGE_STATUS_VALID 0x01

#define TIMEOUT_MS 100

void handle_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

void handle_i2c_error(int result) {
    if (result < 0) {
        handle_error("I2C transaction failed");
    }
}

void handle_sensor_absent() {
    handle_error("VL53L0X sensor not found at address 0x29");
}

void handle_timeout() {
    handle_error("Timeout while waiting for measurement completion");
}

int main(int argc, char *argv[]) {
    int handle;
    FILE *log_file;
    unsigned char buffer[14];
    unsigned int distance;
    unsigned long timestamp;
    int result;
    int i2c_result;
    int timeout_count = 0;

    if (gpioInitialise() < 0) {
        handle_error("Failed to initialize pigpio");
    }

    handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (handle < 0) {
        handle_sensor_absent();
    }

    log_file = fopen("distance_log.txt", "w");
    if (log_file == NULL) {
        handle_error("Failed to open log file");
    }

    if (gpioSetMode(17, PI_INPUT) < 0) {
        handle_error("Failed to set GPIO 17 mode");
    }

    if (gpioSetPullUpDown(17, PI_PUD_UP) < 0) {
        handle_error("Failed to set GPIO 17 pull-up");
    }

    while (1) {
        if (gpioGetLevel(17) == 0) {
            i2c_result = i2cWriteReg(handle, SYSRANGE_START, 0x01);
            handle_i2c_error(i2c_result);

            timeout_count = 0;
            while (1) {
                i2c_result = i2cReadReg(handle, RESULT_INTERRUPT_STATUS, &buffer[0], 1);
                handle_i2c_error(i2c_result);

                if (buffer[0] & 0x01) {
                    break;
                }

                if (++timeout_count > TIMEOUT_MS) {
                    handle_timeout();
                }

                usleep(10000); // 10 ms
            }

            i2c_result = i2cReadReg(handle, RESULT_RANGE_STATUS, &buffer[0], 14);
            handle_i2c_error(i2c_result);

            if (buffer[0] & RESULT_RANGE_STATUS_VALID) {
                distance = (buffer[10] << 8) | buffer[11];
                timestamp = time(NULL) * 1000 + (long)usleep(0);

                fprintf(log_file, "%lu,%u\n", timestamp, distance);
                fflush(log_file);

                i2c_result = i2cWriteReg(handle, SYSTEM_INTERRUPT_CLEAR, 0x01);
                handle_i2c_error(i2c_result);
            }
        }
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

