This C program initializes the pigpio library, opens the I2C bus, and configures GPIO 17 with a pull-up. It then enters an infinite loop where it waits for a falling edge on GPIO 17, triggers a distance measurement, polls the sensor for completion, reads the distance, logs it, and clears the interrupt. It handles errors for I2C transactions, sensor absence, and timeouts. The program also handles SIGINT for graceful shutdown, closing the I2C handle and log file, and releasing pigpio resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define I2C_CMD_TRIGGER 0x40
#define I2C_CMD_READ 0x41
#define I2C_CMD_WRITE 0x42
#define I2C_CMD_STOP 0x43

#define BUFFER_SIZE 16
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char timestamp[BUFFER_SIZE];
    struct tm *time_info;
    time_t rawtime;

    signal(SIGINT, handle_sigint);

    while (!stop) {
        time(&rawtime);
        time_info = localtime(&rawtime);
        strftime(timestamp, BUFFER_SIZE, "%Y-%m-%d %H:%M:%S, ", time_info);

        int cmd = I2C_CMD_TRIGGER;
        if (i2cWriteDevice(i2c_handle, &cmd, 1) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        usleep(50000); // Wait for about 50 ms

        cmd = I2C_CMD_READ;
        if (i2cWriteDevice(i2c_handle, &cmd, 1) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        uint16_t distance;
        if (i2cReadDevice(i2c_handle, (char*)&distance, 2) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        printf("%s%d mm\n", timestamp, distance);
        fprintf(log_file, "%s%d mm\n", timestamp, distance);

        fflush(log_file);
        usleep(200000); // Sample every 200 ms
    }

    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

