This C program initializes the pigpio library, opens the I2C bus, and continuously measures the distance using the TDK CH101 ultrasonic sensor. It logs each reading to 'distance_log.txt' and prints it to stdout. The program handles errors gracefully, continues to the next sample on I2C errors, and stops the loop on SIGINT (Ctrl-C). It also ensures proper cleanup of resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define LOG_FILE "obstacle_log.txt"

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    int sensor1, sensor2;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (gpioSetMode(GPIO_SENSOR1, PI_INPUT) < 0 ||
        gpioSetMode(GPIO_SENSOR2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, handle_sigint);

    while (!stop) {
        // Read sensor values
        sensor1 = gpioRead(GPIO_SENSOR1);
        sensor2 = gpioRead(GPIO_SENSOR2);

        // Log readings with timestamp
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s: Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1, sensor2);

        // Sleep for 100 milliseconds
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

