    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (gpioSetMode(GPIO_SENSOR1, PI_INPUT) < 0 ||
        gpioSetMode(GPIO_SENSOR2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, handle_sigint);

    while (!stop) {
        // Read sensor values
        sensor1 = gpioRead(GPIO_SENSOR1);
        sensor2 = gpioRead(GPIO_SENSOR2);

        // Log readings with timestamp
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s: Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1, sensor2);

