#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_REG 0x16
#define MAX_RETRIES 3

FILE *log_file;

void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (pi >= 0) {
        gpioTerminate();
    }
    exit(0);
}

int read_i2c_register(int reg, uint16_t *data) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cReadDevice(I2C_BUS, I2C_ADDR, reg, 2, (char *)data) == 2) {
            return 0; // Success
        }
        retries++;
    }
    return -1; // Failed after retries
}

int main() {
    int pi = pigpio_start();
    if (pi < 0) {
        fprintf(stderr, "pigpio_start failed\n");
        return 1;
    }

    log_file = fopen("biometric_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_stop();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        uint16_t proximity_data, ambient_data;
        time_t timestamp;

        if (read_i2c_register(PROXIMITY_REG, &proximity_data) == 0 &&
            read_i2c_register(AMBIENT_REG, &ambient_data) == 0) {
            timestamp = time(NULL);
            fprintf(log_file, "%ld: Proximity: %d, Ambient: %d\n", timestamp, proximity_data, ambient_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(0.5); // Sleep for 500 ms
    }

    handle_sigint(0); // This will be reached when the loop is exited

    return 0;
}

