#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define WHO_AM_I 0x00
#define DISTANCE_REG 0x04
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100
#define LOG_FILE "tof_log.txt"

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int read_distance(int handle) {
    int distance = 0;
    if (i2c_read_device(handle, &distance, 1, DISTANCE_REG) != 1) {
        fprintf(stderr, "Error reading distance from sensor.\n");
        return -1;
    }
    return distance;
}

void write_log(int distance, time_t timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }
    fprintf(log_file, "%ld: %d\n", timestamp, distance);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value.\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    int who_am_i = 0;
    if (i2c_read_device(handle, &who_am_i, 1, WHO_AM_I) != 1 || who_am_i != 0x20) {
        fprintf(stderr, "Sensor not found or WHO_AM_I check failed.\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    signal(SIGINT, handle_sigint);

    while (!stop) {
        int distance = read_distance(handle);
        if (distance >= 0) {
            time_t timestamp = time(NULL);
            write_log(distance, timestamp);
            if (distance < threshold) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        }
        usleep(50000); // 50 ms delay
    }

    i2cClose(handle);
    gpioTerminate();
    return 0;
}

