This C program initializes the pigpio library and opens the I2C bus to communicate with the TDK InvenSense ICU-20201 ultrasonic Time-of-Flight sensor. It reads the WHO_AM_I register to verify the sensor's presence and then continuously reads distance measurements every 50 ms. Each reading is logged with a timestamp to 'tof_log.txt'. An LED connected to GPIO 17 is turned on if the measured distance falls below a configurable threshold, passed as the first command-line argument. The program handles errors gracefully and releases resources on all exit paths via a SIGINT handler.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <signal.h>

#define I2C_DEV "/dev/i2c-1"
#define CMD_FRAME {0x50, 0x0A, 0x00, 0x01}
#define RESPONSE_SIZE 15
#define MAX_SAMPLES 10
#define THRESHOLD 1000
#define LOG_FILE "intrusion_log.txt"

int i2c_fd;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int read_sensor() {
    uint8_t response[RESPONSE_SIZE];
    int bytes_read;

    if (ioctl(i2c_fd, I2C_SLAVE, 0x50) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(i2c_fd, CMD_FRAME, sizeof(CMD_FRAME)) != sizeof(CMD_FRAME)) {
        perror("Failed to write command frame");
        return -1;
    }

    usleep(10000); // Wait at least 10 ms

    bytes_read = read(i2c_fd, response, RESPONSE_SIZE);
    if (bytes_read != RESPONSE_SIZE) {
        perror("Failed to read response frame");
        return -1;
    }

    if (response[0] != 0x50) {
        fprintf(stderr, "Invalid header byte 0 in response frame\n");
        return -1;
    }

    uint16_t distance = (response[11] << 8) | response[12];
    return distance;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    int total_distance = 0;
    for (int i = 0; i < MAX_SAMPLES; i++) {
        int distance = read_sensor();
        if (distance < 0) {
            fprintf(stderr, "Failed to read sensor\n");
            break;
        }
        total_distance += distance;
        usleep(100000); // 100 ms delay
    }

    if (i == MAX_SAMPLES) {
        int avg_distance = total_distance / MAX_SAMPLES;
        if (avg_distance < THRESHOLD) {
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d: Intrusion detected, distance = %d mm\n",
                    now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                    now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, avg_distance);
        }
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

