            elapsed_time = time(NULL) - start_time;
            if (elapsed_time > TIMEOUT_MS) {
                fprintf(stderr, "Timeout waiting for measurement completion\n");
                break;
            }

            usleep(100000); // Sleep for 100 ms
        }

        // Read distance
        if (i2cReadI2CBlockData(i2c_handle, RESULT_RANGE_STATUS, 2, (uint8_t[]){0, 0}) < 0) {
            fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
            continue;
