        distance = (uint16_t)((((uint16_t)(((uint8_t[]){0, 0})[1])) << 8) | ((uint16_t)(((uint8_t[]){0, 0})[0])));

        // Clear interrupt
        if (i2cWriteI2CBlockData(i2c_handle, SYSTEM_INTERRUPT_CLEAR, 1, (uint8_t[]){0x01}) < 0) {
            fprintf(stderr, "Failed to clear interrupt: %s\n", strerror(errno));
            continue;
        }

        // Print distance
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        printf("%04d-%02d-%02d %02d:%02d:%02d Distance: %d mm\n",
               now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
               now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, distance);

        // Sleep for 500 ms
        usleep(INTERVAL_MS * 1000);
    }

    // Clean up
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

