#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x39
#define CONFIG_REG 0x18
#define IRQ_STATUS_REG 0x25
#define PROX_LSB_REG 0x2A
#define PROX_MSB_REG 0x2B
#define PROX_INTERVAL 500 // ms

int i2c_fd;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    gpioTerminate();
    exit(0);
}

int read_proximity() {
    uint8_t data[2];
    int result = 0;

    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C bus");
        return -1;
    }

    result = (data[1] << 8) | data[0];
    return result;
}

int main() {
    int proximity_value;
    uint8_t config_data = 0x01;
    uint8_t irq_status;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (write(i2c_fd, &config_data, 1) != 1) {
        perror("Failed to write to CONFIG register");
        close(i2c_fd);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        if (read(i2c_fd, &irq_status, 1) != 1) {
            perror("Error reading from I2C bus");
            break;
        }

        if (irq_status & 0x01) {
            proximity_value = read_proximity();
            if (proximity_value >= 0) {
                printf("Proximity value: %d\n", proximity_value);
            }
        }

        usleep(PROX_INTERVAL * 1000); // Sleep for 500 ms
    }

    handle_sigint(0); // Clean up on exit
    return 0;
}

