#include <time.h>

#define I2C_ADDR 0x4C
#define I2C_DEV "/dev/i2c-1"
#define I2C_TIMEOUT 1000
#define I2C_READ_REG 0x00
#define I2C_READ_LEN 2
#define MILLIMETERS_PER_COUNT 0.125
#define READ_INTERVAL 500000000 // 500 ms in nanoseconds

int i2c_fd;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }

    char buffer[I2C_READ_LEN];
    while (1) {
        if (read(i2c_fd, buffer, I2C_READ_LEN) != I2C_READ_LEN) {
            perror("Failed to read from I2C device");
            continue;
        }

        uint16_t distance = (buffer[1] << 8) | buffer[0];
        double distance_mm = distance * MILLIMETERS_PER_COUNT;

        printf("Distance: %.2f mm\n", distance_mm);

        nanosleep(&struct timespec { .tv_sec = 0, .tv_nsec = READ_INTERVAL }, NULL);
    }

    close(i2c_fd);
    return 0;
}

