#define OPT3101_ADDR 0x44
#define OPT3101_REG_DIST 0x00
#define OPT3101_REG_AMBIENT 0x01
#define OPT3101_REG_ERROR 0x02

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

int read_sensor_data(int i2c_handle) {
    uint8_t data[3];
    int result;

    // Read distance
    result = i2c_read_device(i2c_handle, OPT3101_ADDR, &data[0], 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read distance data from sensor.\n");
        return -1;
    }

    // Read ambient light
    result = i2c_read_device(i2c_handle, OPT3101_ADDR, &data[1], 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read ambient light data from sensor.\n");
        return -1;
    }

    // Read error flags
    result = i2c_read_device(i2c_handle, OPT3101_ADDR, &data[2], 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read error flags from sensor.\n");
        return -1;
    }

    // Print data
    printf("Distance: %d, Ambient Light: %d, Error Flags: %d\n",
           data[0], data[1], data[2]);

    return 0;
}

int main() {
    int i2c_handle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Open I2C bus 1
    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        if (read_sensor_data(i2c_handle) < 0) {
            stop_flag = 1;
        }
        gpioDelay(500000); // 500 ms delay
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

