#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define ECHO_TIMEOUT 200000 // 200 ms in microseconds
#define MIN_PULSE_US 1 // Minimum valid pulse duration in microseconds
#define MAX_PULSE_US 38000 // Maximum valid pulse duration in microseconds (38 ms)

volatile sig_atomic_t shutdown = 0;

void handle_signal(int signum) {
    shutdown = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!shutdown) {
        struct timespec delay = {0, 1000000000}; // 1 second delay

        // Send a 10 microsecond trigger pulse
        gpioWrite(TRIGGER_PIN, PI_LOW);
        usleep(2);
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        usleep(10);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        // Measure echo pulse width
        int echo_rising = gpioWaitForEdge(ECHO_PIN, PI_RISING_EDGE, ECHO_TIMEOUT);
        if (echo_rising == -1) {
