            continue;
        }

        int echo_falling = gpioWaitForEdge(ECHO_PIN, PI_FALLING_EDGE, ECHO_TIMEOUT);
        if (echo_falling == -1) {
            fprintf(stderr, "Timeout waiting for echo falling edge.\n");
            continue;
        }

        int pulse_us = echo_falling - echo_rising;
        if (pulse_us <= 0 || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Invalid pulse duration: %d us.\n", pulse_us);
            continue;
        }

        // Compute distance in cm
        double distance_cm = (pulse_us * 0.0343) / 2;

        // Log reading with timestamp
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        printf("%s: Distance = %.2f cm\n", timestamp, distance_cm);

        nanosleep(&delay, NULL);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

