#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0
#define RANGE_RESOLUTION 0.0486
#define NUM_RANGE_BINS 64
#define MAGIC_HEADER "\x02\x01\x04\x03\x06\x05\x08\x07"

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int open_uart() {
    int fd;
    struct termios options;

    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Failed to open UART device");
        return -1;
    }

    if (tcgetattr(fd, &options) == -1) {
        perror("Failed to get UART options");
        close(fd);
        return -1;
    }

    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;

    if (tcsetattr(fd, TCSANOW, &options) == -1) {
        perror("Failed to set UART options");
        close(fd);
        return -1;
    }

    return fd;
}

void close_uart(int fd) {
    if (tcsetattr(fd, TCSANOW, NULL) == -1) {
        perror("Failed to reset UART options");
    }
    close(fd);
}

void read_range_profile(int fd, float *range_profile) {
    char buffer[136];
    uint8_t magic_header[8];
    uint16_t *data = (uint16_t *) &buffer[8];

    if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read data from UART");
        return;
    }

    if (memcmp(buffer, MAGIC_HEADER, 8) != 0) {
        fprintf(stderr, "Invalid magic header\n");
        return;
    }

    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        range_profile[i] = (float)data[i] * RANGE_RESOLUTION;
    }
}

void check_intrusion(float *range_profile) {
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        if (range_profile[i] <= DISTANCE_THRESHOLD) {
            printf("Intrusion detected at %.2f meters\n", range_profile[i]);
            write_log(range_profile[i]);
            gpioWrite(GPIO_LED, 1);
            sleep(2);
            gpioWrite(GPIO_LED, 0);
            break;
        }
    }
}

void write_log(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    FILE *log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%.2f\n", buffer, distance);
    fclose(log_file);
}

int main() {
    int fd;
    float range_profile[NUM_RANGE_BINS];

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    fd = open_uart();
    if (fd == -1) {
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        read_range_profile(fd, range_profile);
        check_intrusion(range_profile);
        usleep(100000); // Sleep for 100ms
    }

    close_uart(fd);
    gpioTerminate();

    return 0;
}

