#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define BUZZER_PIN 18
#define SENSOR_PIN 17
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL 100 // ms

static gpiod_chip *chip;
static gpiod_line *sensor_line;
static gpiod_line *buzzer_line;

void handle_signal(int signum) {
    if (sensor_line) {
        gpiod_line_request_free(sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_request_free(buzzer_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct timespec ts;
    int prev_sensor_state = 1; // Assume no obstacle initially
    int current_sensor_state;

    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open the GPIO chip
    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request sensor line
    sensor_line = gpiod_line_request_by_name(chip, "gpio%d", SENSOR_PIN, "Obstacle Sensor", 0);
    if (!sensor_line) {
        fprintf(stderr, "Failed to request sensor line\n");
        goto error_sensor_line;
    }

    // Set sensor line to input
    if (gpiod_line_direction_set(sensor_line, GPIOD_LINE_DIRECTION_IN) < 0) {
        fprintf(stderr, "Failed to set sensor line direction\n");
        goto error_sensor_direction;
    }

    // Request buzzer line
    buzzer_line = gpiod_line_request_by_name(chip, "gpio%d", BUZZER_PIN, "Buzzer", 0);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to request buzzer line\n");
        goto error_buzzer_line;
    }

    // Set buzzer line to output
    if (gpiod_line_direction_set(buzzer_line, GPIOD_LINE_DIRECTION_OUT) < 0) {
        fprintf(stderr, "Failed to set buzzer line direction\n");
        goto error_buzzer_direction;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto error_log_file;
    }

    // Main loop
    while (1) {
        // Read sensor state
        if (gpiod_line_get_value(sensor_line) < 0) {
            fprintf(stderr, "Failed to read sensor line\n");
            goto error_read_sensor;
        }
        current_sensor_state = gpiod_line_get_value(sensor_line);

        // Check for state transition
        if (current_sensor_state != prev_sensor_state) {
            prev_sensor_state = current_sensor_state;

            // Log state transition
            time_t rawtime;
            struct tm *timeinfo;
            char buffer[80];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(buffer, sizeof(buffer), "%FT%T", timeinfo);
            fprintf(log_file, "%s: Obstacle detected: %s\n", buffer, current_sensor_state ? "No" : "Yes");
            fflush(log_file);

            // Control buzzer
            if (current_sensor_state == 0) {
                if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                    fprintf(stderr, "Failed to set buzzer line\n");
                    goto error_set_buzzer;
                }
            } else {
                if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                    fprintf(stderr, "Failed to set buzzer line\n");
                    goto error_set_buzzer;
                }
            }
        }

        // Sleep for 100 ms
        ts.tv_sec = 0;
        ts.tv_nsec = POLL_INTERVAL * 1000000;
        nanosleep(&ts, NULL);
    }

error_set_buzzer:
error_log_file:
error_buzzer_direction:
error_buzzer_line:
error_sensor_direction:
error_sensor_line:
    gpiod_chip_put(chip);
    return 1;
}

