This C program uses the libgpiod library to read obstacle detection data from an E18-D80NK IR sensor connected to GPIO 17 on a Raspberry Pi 4 Model B. It activates a buzzer on GPIO 18 when an obstacle is detected and deactivates it when the obstacle is removed. The program polls the sensor every 100 ms and logs every state transition with an ISO 8601 timestamp to 'obstacle_log.txt'. It checks all libgpiod return values and handles errors robustly, including chip open failure, line request failure, and read/write errors. It also handles SIGINT and SIGTERM for graceful shutdown, releasing all GPIO lines and closing the chip.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define GPIO_ALERT 17
#define SAMPLE_INTERVAL 100 // ms
#define MIN_DISTANCE 10.0 // cm

FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (pi >= 0) {
        gpioTerminate();
    }
    exit(signum);
}

int read_distance() {
    int high_byte, low_byte, distance;
    if (i2c_read_device(I2C_BUS, I2C_ADDR, &high_byte, 1, 0) < 0) {
        fprintf(stderr, "Error reading high byte from sensor.\n");
        return -1;
    }
    if (i2c_read_device(I2C_BUS, I2C_ADDR, &low_byte, 1, 0) < 0) {
        fprintf(stderr, "Error reading low byte from sensor.\n");
        return -1;
    }
    distance = (high_byte << 8) | low_byte;
    return distance;
}

void log_distance(int distance) {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);

    if (fprintf(log_file, "%s, Distance: %d cm\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
    }
}

int main() {
    int distance;
    int status;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if ((log_file = fopen("distance_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (signal_pending(0)) {
            handle_signal(0);
        }

        distance = read_distance();
        if (distance < 0) {
            continue;
        }

        if (distance < MIN_DISTANCE) {
            status = gpioWrite(GPIO_ALERT, PI_ON);
            if (status < 0) {
                fprintf(stderr, "Failed to trigger GPIO alert.\n");
            }
        } else {
            status = gpioWrite(GPIO_ALERT, PI_OFF);
            if (status < 0) {
                fprintf(stderr, "Failed to reset GPIO alert.\n");
            }
        }

        log_distance(distance);

        usleep(SAMPLE_INTERVAL * 1000); // Convert ms to us
    }

    return 0;
}

