        perror("Failed to write to I2C bus");
        close(fd);
        gpioTerminate();
        return 1;
    }

    usleep(2000);

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C bus");
        close(fd);
        gpioTerminate();
        return 1;
    }

    model_id = (buffer[0] << 8) | buffer[1];
    if (model_id != 0xEA) {
        fprintf(stderr, "VL53L1X sensor not found\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    if (write(fd, "\x01", 1) != 1) {
        perror("Failed to write to I2C bus");
        close(fd);
        gpioTerminate();
        return 1;
    }

