        if (clock_gettime(CLOCK_REALTIME, &current_time) < 0) {
            perror("Failed to get current time");
            close(fd);
            gpioTerminate();
            return 1;
        }

        if (current_time.tv_sec - start_time.tv_sec >= 1) {
            break;
        }

        if (clock_nanosleep(CLOCK_REALTIME, 0, &timeout, NULL) < 0) {
            perror("Failed to sleep");
            close(fd);
            gpioTerminate();
            return 1;
        }

        if (read(fd, buffer, 1) != 1) {
            perror("Failed to read from I2C bus");
            close(fd);
            gpioTerminate();
            return 1;
        }

        if ((buffer[0] & 0x01) == 0) {
            continue;
        }

        if (read(fd, buffer, 2) != 2) {
            perror("Failed to read from I2C bus");
            close(fd);
            gpioTerminate();
            return 1;
        }

        distance = (buffer[0] << 8) | buffer[1];

        if (write(fd, "\x01", 1) != 1) {
            perror("Failed to write to I2C bus");
            close(fd);
            gpioTerminate();
            return 1;
        }

        if (!log_file) {
            log_file = fopen("distance_log.csv", "w");
            if (!log_file) {
                perror("Failed to open log file");
                close(fd);
                gpioTerminate();
                return 1;
            }
            fprintf(log_file, "timestamp,distance_mm\n");
        }

        fprintf(log_file, "%ld,%d\n", current_time.tv_sec, distance);

        if (distance < STOP_THRESHOLD) {
            strcpy(message, "STOP");
        } else if (distance < APPROACH_THRESHOLD) {
            strcpy(message, "APPROACH");
        } else if (distance < SLOW_THRESHOLD) {
            strcpy(message, "SLOW");
        } else {
            strcpy(message, "CLEAR");
        }

        printf("%s\n", message);

        usleep(100000); // 100 ms
    }

    if (log_file) {
        fclose(log_file);
    }

    close(fd);
    gpioTerminate();

    return 0;
}

