#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x45
#define I2C_CMD_READ 0x80
#define I2C_CMD_WRITE 0x00
#define I2C_CMD_TOF 0x00
#define I2C_CMD_STATUS 0x01
#define I2C_CMD_CONFIG 0x02
#define I2C_CMD_RANGE 0x03
#define I2C_CMD_DATA 0x04

#define MAX_RETRIES 3
#define RETRY_DELAY 10

void handle_signal(int signum) {
    if (i2c_handle != -1) {
        close(i2c_handle);
    }
    if (pi_handle != -1) {
        pi_stop();
    }
    exit(signum);
}

int i2c_read(int cmd, int retries) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        close(fd);
        perror("Failed to acquire I2C bus");
        return -1;
    }

    int data = 0;
    int retry_count = 0;
    while (retry_count < retries) {
        if (write(fd, &cmd, 1) != 1) {
            perror("Failed to write to I2C bus");
            close(fd);
            return -1;
        }

        if (read(fd, &data, 1) != 1) {
            perror("Failed to read from I2C bus");
            close(fd);
            return -1;
        }

        if (data != -1) {
            break;
        }

        retry_count++;
        usleep(RETRY_DELAY * 1000);
    }

    close(fd);
    return data;
}

int i2c_write(int cmd, int retries) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        close(fd);
        perror("Failed to acquire I2C bus");
        return -1;
    }

    int retry_count = 0;
    while (retry_count < retries) {
        if (write(fd, &cmd, 1) != 1) {
            perror("Failed to write to I2C bus");
            close(fd);
            return -1;
        }

        retry_count++;
        usleep(RETRY_DELAY * 1000);
    }

    close(fd);
    return 0;
}

int main() {
    int pi_handle = -1;
    int i2c_handle = -1;
    int led_pin = 18;
    int retry_count = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    pi_handle = pigpio_start();
    if (pi_handle < 0) {
        perror("Failed to start pigpio");
        return 1;
    }

    gpioSetMode(led_pin, PI_OUTPUT);

    while (1) {
        if (i2c_handle == -1) {
            i2c_handle = open(I2C_BUS, O_RDWR);
            if (i2c_handle < 0) {
                perror("Failed to open I2C bus");
                sleep(1);
                continue;
            }

            if (ioctl(i2c_handle, I2C_SLAVE, I2C_ADDR) < 0) {
                close(i2c_handle);
                perror("Failed to acquire I2C bus");
                sleep(1);
                continue;
            }
        }

        int distance = i2c_read(I2C_CMD_TOF, MAX_RETRIES);
        if (distance < 0) {
            perror("Failed to read distance");
            sleep(1);
            continue;
        }

        double frequency = 1.0 / ((distance - 50) / 450.0 + 1.0);
        frequency = (frequency < 1.0) ? 1.0 : (frequency > 10.0) ? 10.0 : frequency;

        int duty_cycle = (int)(frequency * 1000000.0 / 2.0);
        if (duty_cycle < 1000) {
            duty_cycle = 1000;
        }

        if (gpioSetPWMfrequency(led_pin, frequency) < 0) {
            perror("Failed to set PWM frequency");
            sleep(1);
            continue;
        }

        if (gpioPWM(led_pin, duty_cycle) < 0) {
            perror("Failed to set PWM duty cycle");
            sleep(1);
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("Timestamp: %ld.%09ld, Distance: %d mm, Frequency: %.2f Hz\n",
               (long)ts.tv_sec, (long)ts.tv_nsec, distance, frequency);

        usleep(100000);
    }

    if (i2c_handle != -1) {
        close(i2c_handle);
    }

    if (pi_handle != -1) {
        pi_stop();
    }

    return 0;
}

