#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MLX75030_I2C_ADDR 0x5A
#define MLX75030_CMD_MEASURE 0x00
#define MLX75030_CMD_READ_DATA 0x01
#define MLX75030_CMD_READ_DATA_LEN 2
#define MLX75030_DELAY_MS 10
#define MLX75030_INTERVAL_MS 100

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        stop_flag = 1;
    }
}

int read_distance(int i2c_handle) {
    uint8_t cmd = MLX75030_CMD_MEASURE;
    uint8_t data[MLX75030_CMD_READ_DATA_LEN];
    int retries = 3;

    while (retries > 0) {
        if (i2c_write_device(i2c_handle, MLX75030_I2C_ADDR, &cmd, 1) == 1) {
            usleep(MLX75030_DELAY_MS * 1000);
            if (i2c_read_device(i2c_handle, MLX75030_I2C_ADDR, &data, MLX75030_CMD_READ_DATA_LEN) == MLX75030_CMD_READ_DATA_LEN) {
                return (data[0] << 8) | data[1];
            }
        }
        retries--;
    }

    fprintf(stderr, "Failed to read distance from MLX75030 sensor.\n");
    return -1;
}

