#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_27 27
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 10

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

void log_event(int sensor_id, int old_state, int new_state) {
    char timestamp[20];
    time_t rawtime;
    struct tm * timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    FILE *log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }

    if (new_state == 0 && old_state == 1) {
        fprintf(log_file, "%s, Sensor %d, DETECTED\n", timestamp, sensor_id);
    } else if (new_state == 1 && old_state == 0) {
        fprintf(log_file, "%s, Sensor %d, CLEARED\n", timestamp, sensor_id);
    }

    fclose(log_file);
}

int main() {
    int old_state_1 = 1, old_state_2 = 1;
    int new_state_1, new_state_2;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetMode(GPIO_17, PI_INPUT);
    if (gpioInitialisePwm() < 0) {
        fprintf(stderr, "Failed to initialize PWM.\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_27, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        new_state_1 = gpioRead(GPIO_17);
        new_state_2 = gpioRead(GPIO_27);

        if (new_state_1 != old_state_1) {
            log_event(1, old_state_1, new_state_1);
            old_state_1 = new_state_1;
            usleep(DEBOUNCE_MS * 1000);
        }

        if (new_state_2 != old_state_2) {
            log_event(2, old_state_2, new_state_2);
            old_state_2 = new_state_2;
            usleep(DEBOUNCE_MS * 1000);
        }

        usleep(POLL_INTERVAL_MS * 1000 - DEBOUNCE_MS * 1000);
    }

    fclose(stdout); // Ensure stdout is closed before terminating pigpio
    gpioTerminate();

    return 0;
}

