#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <errno.h>

#define I2C_DEV "/dev/i2c-1"
#define TDK_ADDR 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define TIMEOUT_MS 50
#define SAMPLING_INTERVAL_MS 500

void log_error(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
}

int i2c_open() {
    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, TDK_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

void i2c_close(int fd) {
    if (close(fd) < 0) {
        log_error("Failed to close I2C device");
    }
}

int i2c_read_register(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        log_error("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, data, len) != len) {
        log_error("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int main() {
    int fd = i2c_open();
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    FILE *csv_file = fopen("distance_log.csv", "w");
    if (!csv_file) {
        log_error("Failed to open CSV file");
        i2c_close(fd);
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,distance_mm\n");

    struct timespec start_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    while (1) {
        uint8_t status;
        if (i2c_read_register(fd, MEAS_STATUS, &status, 1) < 0) {
            continue;
        }

        if (!(status & 0x01)) {
            usleep(TIMEOUT_MS * 1000);
            continue;
        }

        uint8_t high, low;
        if (i2c_read_register(fd, DIST_HIGH, &high, 1) < 0 ||
            i2c_read_register(fd, DIST_LOW, &low, 1) < 0) {
            continue;
        }

        uint16_t distance = (high << 8) | low;

        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) +
                              (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        fprintf(csv_file, "%s,%d\n", ctime(&current_time.tv_sec), distance);

        usleep(SAMPLING_INTERVAL_MS * 1000);
    }

    fclose(csv_file);
    i2c_close(fd);

    return EXIT_SUCCESS;
}

