#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_ADDR 0x29
#define I2C_DEV "/dev/i2c-1"
#define ZONE_COUNT 64
#define ZONE_DATA_REG 0x80
#define ZONE_CONFIG_REG 0x00
#define ZONE_CONFIG_8X8 0x00

void cleanup(int signum) {
    close(i2c_fd);
    printf("Cleanup: I2C device closed.\n");
    exit(signum);
}

int main() {
    int i2c_fd;
    char buffer[2];
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg msg[2];

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access/set slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure sensor for 8x8 zone grid
    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = (char[]){ZONE_CONFIG_REG};

    msg[1].addr = I2C_ADDR;
    msg[1].flags = 0;
    msg[1].len = 1;
    msg[1].buf = (char[]){ZONE_CONFIG_8X8};

    i2c_data.msgs = msg;
    i2c_data.nmsgs = 2;

    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to configure sensor");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        for (int i = 0; i < ZONE_COUNT; i++) {
            msg[0].addr = I2C_ADDR;
            msg[0].flags = 0;
            msg[0].len = 1;
            msg[0].buf = (char[]){ZONE_DATA_REG + (i * 2)};

            msg[1].addr = I2C_ADDR;
            msg[1].flags = 0;
            msg[1].len = 2;
            msg[1].buf = buffer;

            i2c_data.msgs = msg;
            i2c_data.nmsgs = 2;

            if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
                perror("Failed to read zone data");
                close(i2c_fd);
                exit(EXIT_FAILURE);
            }

            // Convert 16-bit data to distance
            int distance = (buffer[0] << 8) | buffer[1];
            printf("Zone %d: %d mm\n", i, distance);
        }

        printf("\n");
        sleep(0.5); // Sleep for 500 ms
    }

    return 0;
}

