#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L4CX_DEFAULT_ADDR 0x29
#define VL53L4CX_SOFT_RESET_REG 0x7FFF
#define VL53L4CX_RANGE_CONFIG_REG 0x0009
#define VL53L4CX_INTERRUPT_STATUS_REG 0x0046
#define VL53L4CX_RANGE_RESULT_HIGH_REG 0x0096
#define VL53L4CX_RANGE_RESULT_LOW_REG 0x0097

void handle_signal(int signum) {
    printf("\nReceived signal %d, shutting down...\n", signum);
    close(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    int i2c_handle = -1;
    int result = -1;
    unsigned char data[2];
    struct timespec ts;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Open I2C bus 1
    i2c_handle = i2cOpen(1, VL53L4CX_DEFAULT_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        gpioTerminate();
        return 1;
    }

    // Perform soft reset
    result = i2cWriteReg(i2c_handle, VL53L4CX_SOFT_RESET_REG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to perform soft reset.\n");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait 10 ms
    nanosleep(&ts, NULL);
    ts.tv_sec = 0;
    ts.tv_nsec = 10000000;

    // Begin ranging
    result = i2cWriteReg(i2c_handle, VL53L4CX_RANGE_CONFIG_REG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to begin ranging.\n");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Poll interrupt status register
        result = i2cReadReg(i2c_handle, VL53L4CX_INTERRUPT_STATUS_REG, (unsigned char *)&data, 1);
        if (result < 0) {
            fprintf(stderr, "Failed to read interrupt status.\n");
            continue;
        }

        // Check if bit 0 is set
        if (data[0] & 0x01) {
            // Read distance result
            result = i2cReadReg(i2c_handle, VL53L4CX_RANGE_RESULT_HIGH_REG, (unsigned char *)&data, 2);
            if (result < 0) {
                fprintf(stderr, "Failed to read distance result.\n");
                continue;
            }

            // Log distance with timestamp
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d.%06ld, Distance: %d mm\n",
                   timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                   timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
                   (long)timeinfo->tm_usec, (data[0] << 8) | data[1]);
        }

        // Sleep for 500 ms
        nanosleep(&ts, NULL);
        ts.tv_sec = 0;
        ts.tv_nsec = 500000000;
    }

    // Clean up
    close(i2c_handle);
    gpioTerminate();

    return 0;
}

