#define CONFIGURATION_APPLIED 0

volatile int config_applied = CONFIGURATION_APPLIED;
volatile int distance_below_threshold = 0;

void handle_sigint(int signum) {
    if (distance_below_threshold) {
        gpioWrite(BUZZER_GPIO, PI_OUTPUT);
        distance_below_threshold = 0;
    }
    if (config_applied == CONFIGURATION_APPLIED) {
        i2cWriteReg(1, VL53L1X_DEFAULT_I2C_ADDR, VL53L1X_SOFT_RESET, 0x0000);
    }
    gpioTerminate();
    exit(0);
}

void apply_configuration() {
    if (config_applied == CONFIGURATION_APPLIED) {
        i2cWriteReg(1, VL53L1X_DEFAULT_I2C_ADDR, VL53L1X_SOFT_RESET, 0x0001);
        i2cWriteReg(1, VL53L1X_DEFAULT_I2C_ADDR, VL53L1X_I2C_SLAVE_DEVICE_ADDRESS, 0x0001);
        i2cWriteReg(1, VL53L1X_DEFAULT_I2C_ADDR, VL53L1X_SYSTEM_MODE_START, 0x0007);
        config_applied = 1;
    }
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

