        fprintf(stderr, "Failed to open I2C bus 1.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        apply_configuration();

        uint16_t distance = i2cReadReg(1, VL53L1X_DEFAULT_I2C_ADDR, VL53L1X_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM);

        if (distance < THRESHOLD_DISTANCE) {
            if (!distance_below_threshold) {
                gpioWrite(BUZZER_GPIO, PI_OUTPUT);
                distance_below_threshold = 1;
            }
        } else {
            if (distance_below_threshold) {
                gpioWrite(BUZZER_GPIO, PI_INPUT);
                distance_below_threshold = 0;
            }
        }

        usleep(500000); // Sleep for 500 ms
    }

    return 0;
}

