code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define TIMEOUT_MS 50
#define LOG_INTERVAL_MS 200

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

double calculate_distance(int echo_start, int echo_end) {
    if (echo_end == 0 || echo_start == 0) {
        return -1; // Timeout or invalid reading
    }

    double pulse_duration = (double)(echo_end - echo_start) / 1000000000.0;
    double distance = pulse_duration * 34300.0 / 2.0; // Speed of sound in cm/s

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1; // Out of range
    }

    return distance;
}

void map_distance_to_angle(double distance, int *servo_pulse_width) {
    double angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * 180.0;
    *servo_pulse_width = (int)((angle + 90) * 10000.0 / 180.0); // Convert to microseconds
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SERVO_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("sensor_data.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        int echo_start, echo_end;
        gpioWrite(TRIGGER_PIN, PI_LOW);
        usleep(2);
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        usleep(10);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        echo_start = gpioGetTick(ECHO_PIN);
        if (echo_start == 0) {
            fprintf(stderr, "Timeout on echo start\n");
            continue;
        }

        echo_end = echo_start;
        while (echo_end == echo_start && !stop) {
            echo_end = gpioGetTick(ECHO_PIN);
            if (echo_end == 0 || (echo_end - echo_start) > TIMEOUT_MS) {
                fprintf(stderr, "Timeout on echo end\n");
                break;
            }
        }

        double distance = calculate_distance(echo_start, echo_end);
        if (distance < 0) {
            continue;
        }

        int servo_pulse_width;
        map_distance_to_angle(distance, &servo_pulse_width);
        gpioServo(SERVO_PIN, servo_pulse_width);

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        fprintf(log_file, "%02d:%02d:%02d %.2f cm\n", now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, distance);
        fflush(log_file);

        usleep(LOG_INTERVAL_MS * 1000);
    }

    gpioServo(SERVO_PIN, 0); // Stop the servo
    fclose(log_file);
    gpioTerminate();

    return 0;
}

