    }
    if (write(handle, &reg, 1) != 1) {
        perror("write");
        return -1;
    }
    if (read(handle, data, length) != length) {
        perror("read");
        return -1;
    }
    return result;
}

int i2c_write(int handle, uint8_t reg, uint8_t *data, int length) {
    int result = 0;
    uint8_t buffer[length + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, length);
    if (ioctl(handle, I2C_SLAVE, VL53L1X_DEFAULT_ADDR) < 0) {
        perror("I2C_SLAVE");
        return -1;
    }
    if (write(handle, buffer, length + 1) != length + 1) {
        perror("write");
        return -1;
    }
    return result;
}

int main() {
    int handle;
    mqd_t mqdes;
    struct mq_attr attr;
    uint8_t model_id[2];
    uint8_t soft_reset[2] = {0x00, 0x01};
    uint8_t timeout_upper[2] = {0x00, 0x00};
    uint8_t timeout_lower[2] = {0x00, 0x00};
    uint8_t measure_period[2] = {0x00, 0x01};
    uint8_t range_status;
    uint16_t distance;
    uint8_t range_data[2];

