        return 1;
    }

    if (i2c_read(handle, VL53L1X_MODEL_ID_REG, model_id, 2) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        close(handle);
        return 1;
    }

    if (model_id[0] != 0xEA) {
        fprintf(stderr, "Invalid VL53L1X model ID\n");
        close(handle);
        return 1;
    }

    if (i2c_write(handle, VL53L1X_SOFT_RESET_REG, soft_reset, 2) < 0) {
        fprintf(stderr, "Failed to perform software reset\n");
        close(handle);
        return 1;
    }

    if (i2c_write(handle, VL53L1X_CONFIG_TIMEOUT_MACROP_UPPER_REG, timeout_upper, 2) < 0) {
        fprintf(stderr, "Failed to configure timeout upper\n");
        close(handle);
        return 1;
    }

    if (i2c_write(handle, VL53L1X_CONFIG_TIMEOUT_MACROP_LOWER_REG, timeout_lower, 2) < 0) {
        fprintf(stderr, "Failed to configure timeout lower\n");
        close(handle);
        return 1;
    }

    if (i2c_write(handle, VL53L1X_CONFIG_GLOBAL_CONFIG_REG, measure_period, 2) < 0) {
        fprintf(stderr, "Failed to configure measure period\n");
        close(handle);
        return 1;
    }

    if ((mqdes = mq_open(MESSAGE_QUEUE_NAME, O_CREAT | O_RDWR, 0644, &attr)) == (mqd_t)-1) {
        perror("mq_open");
        close(handle);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        if (i2c_read(handle, VL53L1X_CONFIG_GLOBAL_CONFIG_REG, &range_status, 1) < 0) {
            fprintf(stderr, "Failed to read range status\n");
            continue;
        }

        if (range_status & 0x01) {
            if (i2c_read(handle, VL53L1X_RANGE_DATA_REG, range_data, 2) < 0) {
                fprintf(stderr, "Failed to read range data\n");
                continue;
            }

            distance = (range_data[0] << 8) | range_data[1];

            if (distance < DISTANCE_THRESHOLD) {
                if (gpioWrite(BUZZER_GPIO, BUZZER_ACTIVE_STATE) < 0) {
                    fprintf(stderr, "Failed to activate buzzer\n");
                }
            } else {
                if (gpioWrite(BUZZER_GPIO, BUZZER_INACTIVE_STATE) < 0) {
                    fprintf(stderr, "Failed to deactivate buzzer\n");
                }
            }

            char message[20];
            sprintf(message, "%d\n", distance);
            if (mq_send(mqdes, message, strlen(message), 0) < 0) {
                perror("mq_send");
            }
        }

        usleep(50000);
    }

    mq_close(mqdes);
    close(handle);
    gpioTerminate();

    return 0;
}

