This C program initializes the pigpio library, opens the I2C bus, reads the VL53L1X sensor's model ID, performs a software reset, configures the sensor's timing budget, and starts ranging. It then enters a loop where it polls the sensor's data-ready bit, reads the distance, and activates a buzzer if the distance is below 100mm. Distance readings are logged using a POSIX message queue. The program handles I2C read/write errors and gracefully releases all resources on SIGINT.

code:
#include <stdio.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22
#define SPEED_OF_SOUND 34300 // cm/s
#define MIN_DISTANCE 2 // cm
#define MAX_DISTANCE 400 // cm
#define BUZZER_THRESHOLD 30 // cm
#define INTERVAL 100 // ms

volatile int distance = 0;
volatile int buzzer_active = 0;

void handle_alert(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge (echo pulse ends)
        uint32_t duration = pigpio_tickDiff(pigpio_get_current_tick(), tick);
        distance = (duration * SPEED_OF_SOUND) / 20000000; // cm

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading: %d cm\n", distance);
        } else {
            printf("Distance: %d cm\n", distance);
        }

        if (distance < BUZZER_THRESHOLD) {
            if (!buzzer_active) {
                gpioWrite(BUZZER_PIN, PI_ON);
                buzzer_active = 1;
            }
        } else {
            if (buzzer_active) {
                gpioWrite(BUZZER_PIN, PI_OFF);
                buzzer_active = 0;
            }
        }
    }
}

void cleanup(int signum) {
    if (buzzer_active) {
        gpioWrite(BUZZER_PIN, PI_OFF);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        goto cleanup;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        goto cleanup;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN mode\n");
        goto cleanup;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, handle_alert, 0) < 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        goto cleanup;
    }

    signal(SIGINT, cleanup);

    while (1) {
        gpioWrite(TRIGGER_PIN, PI_ON);
        usleep(10000); // 10 microsecond HIGH pulse
        gpioWrite(TRIGGER_PIN, PI_OFF);

        usleep(INTERVAL * 1000); // Wait for 100 ms
    }

cleanup:
    gpioTerminate();
    return 1;
}

