#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define SERVO_PIN 18
#define MAX_DISTANCE 20 // cm
#define LOG_FILE "gate_log.txt"

volatile sig_atomic_t running = 1;

void handle_sigint(int signum) {
    running = 0;
}

void i2c_init() {
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%x\n", I2C_BUS, I2C_ADDR);
        exit(EXIT_FAILURE);
    }
}

void i2c_software_reset() {
    if (i2cWriteReg(I2C_BUS, I2C_ADDR, 0x06, 0x01) < 0) {
        fprintf(stderr, "Failed to perform software reset on VL53L1X\n");
        exit(EXIT_FAILURE);
    }
}

void i2c_start_ranging() {
    if (i2cWriteReg(I2C_BUS, I2C_ADDR, 0x00, 0x00) < 0) {
        fprintf(stderr, "Failed to start ranging on VL53L1X\n");
        exit(EXIT_FAILURE);
    }
}

uint16_t read_distance() {
    uint16_t distance = 0;
    if (i2cReadReg(I2C_BUS, I2C_ADDR, 0x14, &distance, 2) < 0) {
        fprintf(stderr, "Failed to read distance from VL53L1X\n");
        exit(EXIT_FAILURE);
    }
    return distance;
}

void open_gate() {
    if (piServo(SERVO_PIN, 1.5) < 0) {
        fprintf(stderr, "Failed to set servo position for opening the gate\n");
        exit(EXIT_FAILURE);
    }
}

void close_gate() {
    if (piServo(SERVO_PIN, 0.5) < 0) {
        fprintf(stderr, "Failed to set servo position for closing the gate\n");
        exit(EXIT_FAILURE);
    }
}

void log_event(const char *event) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        exit(EXIT_FAILURE);
    }

    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    fprintf(log_file, "%s %s\n", asctime(timeinfo), event);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);

    i2c_init();
    i2c_software_reset();
    i2c_start_ranging();

    while (running) {
        uint16_t distance = read_distance();
        if (distance <= MAX_DISTANCE) {
            open_gate();
            log_event("Gate opened due to object detection");
        } else {
            close_gate();
            log_event("Gate closed due to clear path");
        }

        sleep(1); // Adjust the sleep duration as needed
    }

    close_gate();
    log_event("Gate closed due to program termination");

    i2cClose(I2C_BUS, I2C_ADDR);
    gpioTerminate();

    return 0;
}

