        exit(1);
    }

    fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
    fflush(log_file);
    fclose(log_file);

    printf("%s, %.2f cm\n", timestamp, distance);
}

void handle_echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t rising_edge_tick = 0;
    static uint32_t falling_edge_tick = 0;

    if (level == 1) {
        rising_edge_tick = tick;
    } else {
        falling_edge_tick = tick;

        if (rising_edge_tick != 0 && falling_edge_tick != 0) {
            uint32_t pulse_width = falling_edge_tick - rising_edge_tick;

            // Handle 32-bit tick wraparound
            if (pulse_width > (1 << 31)) {
                pulse_width -= (1 << 32);
            }

            double distance = (pulse_width * 0.0343) / 2;

            if (distance < MIN_PULSE_WIDTH || distance > MAX_PULSE_WIDTH) {
                fprintf(stderr, "Warning: Invalid pulse width %.2f cm\n", distance);
            } else {
                char timestamp[20];
                time_t now = time(NULL);
                struct tm *now_tm = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);
                log_reading(distance, timestamp);
            }

            rising_edge_tick = 0;
            falling_edge_tick = 0;
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioWrite(TRIG_PIN, PI_LOW);

    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    gpioSetAlertFunc(ECHO_PIN, handle_echo_callback);

    while (1) {
        gpioWrite(TRIG_PIN, PI_HIGH);
        usleep(10);
        gpioWrite(TRIG_PIN, PI_LOW);

        usleep(MEASURE_INTERVAL * 1000 - TIMEOUT_INTERVAL * 1000);

        if (gpioTickDiff(0, 0) >= TIMEOUT_INTERVAL * 1000) {
            fprintf(stderr, "Warning: Timeout after %d ms\n", TIMEOUT_INTERVAL);
        }
    }

    gpioTerminate();
    return 0;
}

