#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_SHUTDOWN_PIN 23
#define VL53L1X_INT_PIN 24
#define SERVO_PWM_PIN 18
#define GATE_OPEN_POS 1.5
#define GATE_CLOSE_POS 2.5
#define MIN_DISTANCE 50
#define MAX_DISTANCE 60
#define HYSTERESIS 5

FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(signum);
}

void log_gate_state(int state, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Gate state: %s, Distance: %d cm\n", buffer, state == 1 ? "Open" : "Closed", distance);
}

int main() {
    int i2c_fd;
    int shutdown_pin_state = 0;
    int int_pin_state = 0;
    int current_distance = 0;
    int gate_state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if ((i2c_fd = i2cOpen(1, VL53L1X_I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (i2cWriteReg(i2c_fd, 0x00, 0x00) < 0) { // Set to Measurement mode
        fprintf(stderr, "Failed to set sensor to measurement mode\n");
        return 1;
    }

    if (i2cReadReg(i2c_fd, 0x00, 1, &shutdown_pin_state) < 0) {
        fprintf(stderr, "Failed to read shutdown pin state\n");
        return 1;
    }

    if (i2cWriteReg(i2c_fd, 0x00, 0x01) < 0) { // Enable the sensor
        fprintf(stderr, "Failed to enable sensor\n");
        return 1;
    }

    if (i2cReadReg(i2c_fd, 0x00, 1, &int_pin_state) < 0) {
        fprintf(stderr, "Failed to read interrupt pin state\n");
        return 1;
    }

    if (gpioSetMode(VL53L1X_SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set shutdown pin mode\n");
        return 1;
    }

    if (gpioWrite(VL53L1X_SHUTDOWN_PIN, shutdown_pin_state) < 0) {
        fprintf(stderr, "Failed to set shutdown pin state\n");
        return 1;
    }

    if (gpioSetMode(VL53L1X_INT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set interrupt pin mode\n");
        return 1;
    }

    if (gpioSetAlertFunc(VL53L1X_INT_PIN, NULL) < 0) {
        fprintf(stderr, "Failed to set interrupt pin alert function\n");
        return 1;
    }

    if (gpioSetAlertFuncEx(VL53L1X_INT_PIN, NULL, 0, 0) < 0) {
        fprintf(stderr, "Failed to set interrupt pin alert function with parameters\n");
        return 1;
    }

    if (gpioSetPWMfrequency(SERVO_PWM_PIN, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    if ((log_file = fopen("parking_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (i2cReadReg(i2c_fd, 0x00, 1, &current_distance) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        if (current_distance < MIN_DISTANCE) {
            if (gate_state == 0) {
                gate_state = 1;
                log_gate_state(gate_state, current_distance);
                gpioServo(SERVO_PWM_PIN, GATE_OPEN_POS);
            }
        } else if (current_distance > MAX_DISTANCE) {
            if (gate_state == 1) {
                gate_state = 0;
                log_gate_state(gate_state, current_distance);
                gpioServo(SERVO_PWM_PIN, GATE_CLOSE_POS);
            }
        }

        sleep(1);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

