#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define RANGE_INTERVAL 500
#define MAX_DISTANCE 200

FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (pi >= 0) {
        gpioSetMode(GPIO_OPEN, PI_INPUT);
        gpioSetMode(GPIO_CLOSE, PI_INPUT);
        gpioTerminate();
    }
    exit(signum);
}

void log_event(const char *event, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s - %s - Distance: %d mm\n", buffer, event, distance);
}

int main() {
    int i2c_handle = -1;
    int distance = 0;
    int status = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen("gate_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Perform soft reset
    if (i2cWriteI2CBlockData(i2c_handle, 0x00, (uint8_t[]) {0x00, 0x01}, 2) < 0) {
        fprintf(stderr, "Failed to perform soft reset\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure timing budget
    if (i2cWriteI2CBlockData(i2c_handle, 0x00, (uint8_t[]) {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, 16) < 0) {
        fprintf(stderr, "Failed to configure timing budget\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Start ranging
    if (i2cWriteI2CBlockData(i2c_handle, 0x00, (uint8_t[]) {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, 16) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (1) {
        uint8_t data[2];
        if (i2cReadI2CBlockData(i2c_handle, 0x80, data, 2) < 0) {
            fprintf(stderr, "Failed to read distance data\n");
            continue;
        }

        distance = (data[0] << 8) | data[1];

        if (distance <= MAX_DISTANCE) {
            if (gpioRead(GPIO_OPEN) == 0) {
                if (gpioWrite(GPIO_OPEN, 1) < 0 || gpioWrite(GPIO_CLOSE, 0) < 0) {
                    fprintf(stderr, "Failed to set GPIO states\n");
                } else {
                    log_event("Gate Opened", distance);
                }
            }
        } else {
            if (gpioRead(GPIO_CLOSE) == 0) {
                if (gpioWrite(GPIO_OPEN, 0) < 0 || gpioWrite(GPIO_CLOSE, 1) < 0) {
                    fprintf(stderr, "Failed to set GPIO states\n");
                } else {
                    log_event("Gate Closed", distance);
                }
            }
        }

        usleep(RANGE_INTERVAL * 1000);
    }

    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

