#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x5A
#define I2C_DEV "/dev/i2c-1"
#define GPIO_PINS {17, 18, 27, 22}
#define NUM_ELECTRODES 12
#define POLL_INTERVAL 50 // ms

static gpiod_chip *chip;
static gpiod_line *led_lines[4];

static void handle_signal(int signum) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_request_free(led_lines[i]);
    }
    gpiod_chip_put(chip);
    exit(signum);
}

static void write_i2c(uint8_t reg, uint8_t value) {
    FILE *file = fopen(I2C_DEV, "r+");
    if (!file) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fileno(file), I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    if (write(fileno(file), &value, 1) != 1) {
        perror("Failed to write to I2C device");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    fclose(file);
}

static uint8_t read_i2c(uint8_t reg) {
    FILE *file = fopen(I2C_DEV, "r+");
    if (!file) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fileno(file), I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    uint8_t value;
    if (read(fileno(file), &value, 1) != 1) {
        perror("Failed to read from I2C device");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    fclose(file);
    return value;
}

static void init_gpiod() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_line_request_by_name(chip, "gpio%d", GPIO_PINS[i], "led", GPIOD_LINE_DIRECTION_OUTPUT);
        if (!led_lines[i]) {
            perror("Failed to request GPIO line");
            exit(EXIT_FAILURE);
        }
    }
}

static void cleanup_gpiod() {
    for (int i = 0; i < 4; i++) {
        gpiod_line_request_free(led_lines[i]);
    }
    gpiod_chip_put(chip);
}

static void set_led_pattern(uint8_t pattern) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(led_lines[i], (pattern >> i) & 1);
    }
}

static void log_proximity_event(int electrode, time_t timestamp) {
    printf("Proximity detected on electrode ELE%d at %s\n", electrode, ctime(&timestamp));
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpiod();

    // Soft reset
    write_i2c(0x80, 0x63);

    // Verify sensor presence
    uint8_t version = read_i2c(0x00);
    if (version != 0x01) {
        fprintf(stderr, "Sensor not present or incorrect version (expected 0x01, got 0x%02X)\n", version);
        cleanup_gpiod();
        exit(EXIT_FAILURE);
    }

    // Initialize sensor
    write_i2c(0x00, 0x00); // Stop mode
    write_i2c(0x01, 0x01); // Baseline filtering
    write_i2c(0x02, 0x01);
    write_i2c(0x03, 0x0E);
    write_i2c(0x04, 0x00);
    write_i2c(0x5A, 0x0B); // Auto-configuration thresholds
    write_i2c(0x5D, 0xC8);
    write_i2c(0x5E, 0x82);
    write_i2c(0x5F, 0xB4);
    write_i2c(0x00, 0x0C); // Enable all electrodes in run mode

    while (1) {
        time_t timestamp = time(NULL);
        uint8_t touch_status = read_i2c(0x00);

        if (touch_status == 0) {
            set_led_pattern(0);
            printf("No electrode active at %s\n", ctime(&timestamp));
        } else {
            int electrode = 0;
            for (int i = 0; i < 4; i++) {
                if (touch_status & (1 << i)) {
                    electrode = i;
                    break;
                }
            }
            if (electrode < NUM_ELECTRODES) {
                log_proximity_event(electrode, timestamp);
                set_led_pattern(1 << electrode);
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    cleanup_gpiod();
    return 0;
}

