code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MPR121_I2C_BUS 1
#define MPR121_ADDR 0x5A
#define MPR121_DEVICE_ID 0x00
#define MPR121_ELEC0_TOUCH_THRESHOLD 0x0A
#define MPR121_ELEC0_RELEASE_THRESHOLD 0x05
#define GPIO_LED 27

void handle_signal(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void write_i2c_register(int bus, int addr, int reg, int value) {
    int fd = i2cOpen(bus, addr, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", bus);
        exit(EXIT_FAILURE);
    }

    if (i2cWriteReg(fd, reg, value) < 0) {
        fprintf(stderr, "Failed to write to register 0x%02X\n", reg);
        i2cClose(fd);
        exit(EXIT_FAILURE);
    }

    i2cClose(fd);
}

int read_i2c_register(int bus, int addr, int reg) {
    int fd = i2cOpen(bus, addr, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", bus);
        exit(EXIT_FAILURE);
    }

    int value = i2cReadReg(fd, reg);
    if (value < 0) {
        fprintf(stderr, "Failed to read from register 0x%02X\n", reg);
        i2cClose(fd);
        exit(EXIT_FAILURE);
    }

    i2cClose(fd);
    return value;
}

void configure_mpr121() {
    write_i2c_register(MPR121_I2C_BUS, MPR121_ADDR, 0x00, MPR121_DEVICE_ID); // Check device ID
    if (read_i2c_register(MPR121_I2C_BUS, MPR121_ADDR, 0x00) != MPR121_DEVICE_ID) {
        fprintf(stderr, "MPR121 device ID mismatch\n");
        exit(EXIT_FAILURE);
    }

    write_i2c_register(MPR121_I2C_BUS, MPR121_ADDR, 0x01, 0x00); // FFI
    write_i2c_register(MPR121_I2C_BUS, MPR121_ADDR, 0x02, 0x00); // SFI
    write_i2c_register(MPR121_I2C_BUS, MPR121_ADDR, 0x03, 0x00); // ESI
    write_i2c_register(MPR121_I2C_BUS, MPR121_ADDR, 0x04, 0x00); // Debounce
    write_i2c_register(MPR121_I2C_BUS, MPR121_ADDR, 0x05, 0x00); // AFE config
    write_i2c_register(MPR121_I2C_BUS, MPR121_ADDR, 0x06, 0x00); // Baseline filtering

    write_i2c_register(MPR121_I2C_BUS, MPR121_ADDR, 0x07, MPR121_ELEC0_TOUCH_THRESHOLD); // Touch threshold
    write_i2c_register(MPR121_I2C_BUS, MPR121_ADDR, 0x08, MPR121_ELEC0_RELEASE_THRESHOLD); // Release threshold
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    configure_mpr121();

    while (1) {
        int status = read_i2c_register(MPR121_I2C_BUS, MPR121_ADDR, 0x09); // Read status register
        if ((status & (1 << 0)) != 0) { // Check if electrode 0 is touched
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

            printf("Proximity detected on electrode 0 at %s\n", timestamp);

            if (gpioWrite(GPIO_LED, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                continue;
            }

            sleep(1);

            if (gpioWrite(GPIO_LED, 0) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
            }
        }
    }

    return EXIT_SUCCESS;
}

