#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define TRIGGER_LINE 17
#define ECHO_LINE 18
#define SPEED_OF_SOUND 343.0 // m/s
#define MIN_DISTANCE 2.0 // cm
#define MAX_DISTANCE 400.0 // cm
#define TIMEOUT_US 30000 // 30 ms

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

int main() {
    gpiod_chip *chip;
    gpiod_line *trigger_line, *echo_line;
    FILE *log_file;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_line_request(chip, TRIGGER_LINE, "trigger", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!trigger_line) {
        perror("Failed to request trigger line");
        gpiod_chip_put(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_line_request(chip, ECHO_LINE, "echo", GPIOD_LINE_DIRECTION_INPUT);
    if (!echo_line) {
        perror("Failed to request echo line");
        gpiod_line_put(trigger_line);
        gpiod_chip_put(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        // Hold trigger low for 5 microseconds
        gpiod_line_set_value(trigger_line, 0);
        usleep(5);

        // Pulse high for 10 microseconds
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo rising edge with a 30 ms timeout
        int echo_value = gpiod_line_get_value(echo_line);
        if (echo_value != 1) {
            fprintf(log_file, "Sensor absent at %s\n", ctime(&ts.tv_sec));
            fflush(log_file);
            continue;
        }

        // Measure echo pulse width with a 30 ms timeout
        struct timespec start_time, end_time;
        clock_gettime(CLOCK_REALTIME, &start_time);
        while (gpiod_line_get_value(echo_line) == 1 && (clock_gettime(CLOCK_REALTIME, &end_time) - start_time).tv_sec < 0.03) {
            usleep(100); // Small delay to avoid busy-waiting
        }

        if ((end_time - start_time).tv_sec >= 0.03) {
            fprintf(log_file, "Timeout at %s\n", ctime(&ts.tv_sec));
            fflush(log_file);
            continue;
        }

        long pulse_us = (end_time - start_time).tv_sec * 1000000 + (end_time - start_time).tv_nsec / 1000;
        double distance = (pulse_us * 0.0343) / 2.0;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(log_file, "Invalid distance %.2f cm at %s\n", distance, ctime(&ts.tv_sec));
            fflush(log_file);
            continue;
        }

        fprintf(log_file, "Distance: %.2f cm at %s\n", distance, ctime(&ts.tv_sec));
        fflush(log_file);

        clock_gettime(CLOCK_REALTIME, &ts);
        sleep(1);
    }

    gpiod_line_put(echo_line);
    gpiod_line_put(trigger_line);
    gpiod_chip_put(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

