#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

void echo_isr(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static uint32_t end_tick = 0;

    if (level == 0) {
        end_tick = tick;
        if (start_tick != 0) {
            uint32_t pulse_us = (end_tick - start_tick) * 1000000 / 95;
            if (pulse_us > 0 && pulse_us <= 25000000) {
                double distance = pulse_us * 343.0 / 2e6;
                time_t now = time(NULL);
                struct tm *now_tm = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
                FILE *log_file = fopen(LOG_FILE, "a");
                if (log_file != NULL) {
                    fprintf(log_file, "%s: %.2f meters\n", timestamp, distance);
                    fclose(log_file);
                } else {
                    fprintf(stderr, "Failed to open log file for writing.\n");
                }
            }
        }
        start_tick = 0;
    } else {
        start_tick = tick;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG_PIN mode.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, &echo_isr) < 0) {
        fprintf(stderr, "Failed to set ISR function for ECHO_PIN.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (!stop) {
        gpioWrite(TRIG_PIN, 0);
        usleep(2);
        gpioWrite(TRIG_PIN, 1);
        usleep(10);
        gpioWrite(TRIG_PIN, 0);
        usleep(500);
    }

    gpioSetISRFunc(ECHO_PIN, 0);
    fclose(fopen(LOG_FILE, "w")); // Clear the log file on exit
    gpioTerminate();

    return 0;
}

