#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_ADDR 0x29
#define XSHUT_PIN 27
#define RANGE_REG 0x0014
#define STATUS_REG 0x0016
#define CONTINUOUS_MODE_REG 0x0018
#define TIMEOUT_REG 0x0019
#define START_RANGING_REG 0x0020

void handle_signal(int signum) {
    if (i2c_handle != -1) {
        close(i2c_handle);
    }
    if (pi_connected) {
        pi_stop();
    }
    exit(signum);
}

int main() {
    int i2c_handle = -1;
    int status;
    uint8_t status_byte;
    uint16_t distance;
    struct timeval tv;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if ((i2c_handle = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C device\n");
        close(i2c_handle);
        return 1;
    }

    if (gpioSetMode(XSHUT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        close(i2c_handle);
        return 1;
    }

    if (gpioWrite(XSHUT_PIN, PI_HIGH) < 0) {
        fprintf(stderr, "Failed to set GPIO high\n");
        close(i2c_handle);
        return 1;
    }

    // Configure sensor
    if (write(i2c_handle, "\x00", 1) != 1) {
        fprintf(stderr, "Failed to write to register 0x0018\n");
        close(i2c_handle);
        return 1;
    }

    if (write(i2c_handle, "\x00", 1) != 1) {
        fprintf(stderr, "Failed to write to register 0x0019\n");
        close(i2c_handle);
        return 1;
    }

    if (write(i2c_handle, "\x01", 1) != 1) {
        fprintf(stderr, "Failed to write to register 0x0020\n");
        close(i2c_handle);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (read(i2c_handle, (char*)&distance, 2) != 2) {
            syslog(LOG_ERR, "Failed to read distance");
            continue;
        }

        if (read(i2c_handle, (char*)&status_byte, 1) != 1) {
            syslog(LOG_ERR, "Failed to read status");
            continue;
        }

        gettimeofday(&tv, NULL);
        syslog(LOG_INFO, "Timestamp: %ld.%06ld, Distance: %d mm, Status: %d",
               (long)tv.tv_sec, (long)tv.tv_usec, ntohs(distance), status_byte);

        usleep(100000); // 100 ms
    }

    if (i2c_handle != -1) {
        close(i2c_handle);
    }

    if (pi_connected) {
        pi_stop();
    }

    return 0;
}

