                fprintf(log_file, "Closing gate (timestamp: %ld.%09ld)\n", (long)ts.tv_sec, (long)ts.tv_nsec);
                gpioWrite(GPIO_PIN, 0);
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    return 0;
