#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define SPEED_OF_SOUND 34300 // cm/s
#define MIN_DISTANCE 2 // cm
#define MAX_DISTANCE 400 // cm
#define AVG_WINDOW 5
#define SERVO_MIN_PULSE 500 // us
#define SERVO_MAX_PULSE 2500 // us
#define SERVO_DEFAULT_ANGLE 90 // degrees
#define SERVO_DEFAULT_PULSE (SERVO_MIN_PULSE + ((SERVO_MAX_PULSE - SERVO_MIN_PULSE) * SERVO_DEFAULT_ANGLE / 180)) // us
#define LOG_FILE "distance_log.csv"

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

void servo_angle_to_pulse(int angle, int *pulse_width) {
    *pulse_width = SERVO_MIN_PULSE + ((SERVO_MAX_PULSE - SERVO_MIN_PULSE) * angle / 180);
}

void log_data(double distance, int angle) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }

    fprintf(file, "%f,%d\n", distance, angle);
    fclose(file);
}

void distance_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static uint32_t end_tick = 0;
    static int pulse_width = 0;
    static int pulse_count = 0;
    static double distances[AVG_WINDOW] = {0};
    static int avg_index = 0;
    static int avg_sum = 0;
    static int avg_count = 0;
    static int angle = SERVO_DEFAULT_ANGLE;

    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        end_tick = tick;
        pulse_width = end_tick - start_tick;

        if (pulse_width > 0 && pulse_width < 30000000) { // 30 ms timeout
            double distance = (pulse_width * SPEED_OF_SOUND) / 20000000.0;

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                distances[avg_index] = distance;
                avg_sum += distance;
                avg_count++;

                if (avg_count == AVG_WINDOW) {
                    double avg_distance = avg_sum / AVG_WINDOW;
                    log_data(avg_distance, angle);

                    int pulse_width;
                    servo_angle_to_pulse(angle, &pulse_width);
                    gpioServo(SERVO_PIN, pulse_width);

                    avg_sum -= distances[avg_index];
                    avg_count--;
                    avg_index = (avg_index + 1) % AVG_WINDOW;
                }
            } else {
                log_data(-1.0, angle);
            }
        } else {
            log_data(-1.0, angle);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    int pulse_width = SERVO_DEFAULT_PULSE;
    gpioServo(SERVO_PIN, pulse_width);

    if (gpioSetAlertFunc(ECHO_PIN, distance_callback) < 0) {
        fprintf(stderr, "Failed to set alert function.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        gpioWrite(TRIGGER_PIN, 1);
        usleep(10);
        gpioWrite(TRIGGER_PIN, 0);
        usleep(100000); // 100 ms
    }

    gpioServo(SERVO_PIN, SERVO_DEFAULT_PULSE);
    gpioTerminate();

    return 0;
}

