#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define BUFFER_SIZE 10
#define WARNING_THRESHOLD 200
#define GPIO_PIN 17

vl53l1x_t sensor;
int i2c_handle;
int buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int warning_led_state = 0;

void handle_sigint(int signum) {
    if (warning_led_state) {
        gpioWrite(GPIO_PIN, 0);
    }
    close(i2c_handle);
    pigpioStop();
    exit(0);
}

void init_sensor() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%x\n", I2C_BUS, I2C_ADDR);
        exit(1);
    }

    if (vl53l1x_init(&sensor, i2c_handle) != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to initialize VL53L1X sensor\n");
        close(i2c_handle);
        exit(1);
    }

    if (vl53l1x_set_default_config(&sensor) != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to set default configuration\n");
        vl53l1x_shutdown(&sensor);
        close(i2c_handle);
        exit(1);
    }

    if (vl53l1x_set_signal_rate_limit(&sensor, 0.25) != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to enable signal rate check\n");
        vl53l1x_shutdown(&sensor);
        close(i2c_handle);
        exit(1);
    }

    if (vl53l1x_set_xtalk_compensation(&sensor, 0.0) != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to configure cross-talk compensation\n");
        vl53l1x_shutdown(&sensor);
        close(i2c_handle);
        exit(1);
    }

    if (vl53l1x_start_ranging(&sensor) != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to start ranging\n");
        vl53l1x_shutdown(&sensor);
        close(i2c_handle);
        exit(1);
    }
}

void read_distance() {
    int distance;
    if (vl53l1x_get_distance(&sensor, &distance) != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to read distance\n");
        return;
    }

    buffer[buffer_head] = distance;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    if (buffer_head == buffer_tail) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    }

    if (distance < WARNING_THRESHOLD) {
        if (!warning_led_state) {
            warning_led_state = 1;
            gpioWrite(GPIO_PIN, 1);
        }
    } else {
        if (warning_led_state) {
            warning_led_state = 0;
            gpioWrite(GPIO_PIN, 0);
        }
    }
}

int main() {
    if (pigpioInit() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        pigpioStop();
        exit(1);
    }

    init_sensor();

    signal(SIGINT, handle_sigint);

    while (1) {
        read_distance();
        usleep(50000); // 50 ms delay
    }

    return 0;
}

