#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_ADDR 0x60
#define DEFAULT_THRESHOLD 1000

int threshold = DEFAULT_THRESHOLD;
int i2c_fd = -1;
int proximity_pin = 27;
int proximity_flag = 0;

void handle_interrupt(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        proximity_flag = 1;
    }
}

void read_proximity(FILE *log_file) {
    uint8_t high_byte, low_byte;
    uint16_t proximity_value;

    if (i2c_read_device(i2c_fd, 0x08, &high_byte, 1) != 1 ||
        i2c_read_device(i2c_fd, 0x09, &low_byte, 1) != 1) {
        fprintf(stderr, "Error reading proximity value from sensor.\n");
        return;
    }

    proximity_value = (high_byte << 8) | low_byte;

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (proximity_value <= threshold) {
        fprintf(log_file, "%s %d SAFE\n", buffer, proximity_value);
    } else {
        fprintf(log_file, "%s %d ALERT\n", buffer, proximity_value);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    char *i2c_address_str = NULL;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address_str = optarg;
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a <i2c_address>] [-t <threshold>]\n", argv[0]);
                return 1;
        }
    }

    if (i2c_address_str == NULL) {
        i2c_address_str = "0x60";
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
