void read_proximity(FILE *log_file) {
    uint8_t high_byte, low_byte;
    uint16_t proximity_value;

    if (i2c_read_device(i2c_fd, 0x08, &high_byte, 1) != 1 ||
        i2c_read_device(i2c_fd, 0x09, &low_byte, 1) != 1) {
        fprintf(stderr, "Error reading proximity value from sensor.\n");
        return;
    }

    proximity_value = (high_byte << 8) | low_byte;

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (proximity_value <= threshold) {
        fprintf(log_file, "%s %d SAFE\n", buffer, proximity_value);
    } else {
        fprintf(log_file, "%s %d ALERT\n", buffer, proximity_value);
    }
}

