This code sets up a theremin-like instrument using the pigpio library on a Raspberry Pi Zero W. It uses an HC-SR04 ultrasonic sensor to measure distance and an 8-ohm speaker connected to GPIO18 (PWM0) to produce a tone. The frequency of the tone is controlled by the distance measured, mapped using a logarithmic formula. The program includes robust error checking for every pigpio call and handles SIGINT and SIGTERM signals to cleanly stop the PWM output and terminate pigpio.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MIN_DIST 5
#define MAX_DIST 50

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

double calculate_frequency(double distance) {
    double freq = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
    return freq < MIN_FREQ ? MIN_FREQ : (freq > MAX_FREQ ? MAX_FREQ : freq);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    double last_distance = 0;

    signal(SIGINT, handle_sigint);

    while (!stop) {
        gpioWrite(TRIGGER_PIN, PI_LOW);
        gpioDelay(2);
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        int start = 0, end = 0;
        for (int i = 0; i < 1000000; i++) {
            if (gpioRead(ECHO_PIN) == PI_HIGH) {
                start = i;
                break;
            }
        }

        if (start == 0) {
            printf("Timeout reading echo pulse\n");
            continue;
        }

        for (int i = start; i < 1000000; i++) {
            if (gpioRead(ECHO_PIN) == PI_LOW) {
                end = i;
                break;
            }
        }

        if (end == 0) {
            printf("Timeout reading echo pulse\n");
            continue;
        }

        double distance = (end - start) * 0.034 / 2; // Speed of sound is approximately 340 m/s

        if (distance < MIN_DIST || distance > MAX_DIST) {
            printf("Distance out of range: %.2f cm\n", distance);
            distance = last_distance;
        } else {
            last_distance = distance;
        }

        double freq = calculate_frequency(distance);

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, freq);

        if (gpioHardwarePWM(BUZZER_PIN, freq) < 0) {
            fprintf(stderr, "Failed to set PWM frequency\n");
            stop = 1;
        }

        gpioDelay(10000); // 10 ms delay
    }

    gpioHardwarePWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();

    return 0;
}

