#include <stdio.h>
#include <pigpio.h>
#include <signal.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define TIMEOUT 50000 // 50 ms

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, PI_LOW);

    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        usleep(10);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        int pulse_width = gpioGetPulseWidth(ECHO_PIN, 0, TIMEOUT);

        if (pulse_width == -1) {
            fprintf(stderr, "Timeout occurred while measuring echo pulse\n");
            continue;
