            printf("Distance: %.2f cm", distance);
            if (distance < 10) {
                printf(" - Too close!\n");
            } else {
                printf("\n");
            }
        }

        usleep(500000); // 500 ms delay
    }

    gpioTerminate();
    return 0;
}

