#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define GPIO_CS 8

void handle_signal(int signum) {
    if (spiHandle != -1) {
        spiStop(spiHandle);
        spiClose(spiHandle);
    }
    if (logFile != NULL) {
        fclose(logFile);
    }
    exit(signum);
}

int main() {
    int spiHandle = -1;
    FILE *logFile = NULL;
    char buffer[3];
    int distance;
    struct tm *timeinfo;
    time_t rawtime;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Open SPI channel
    spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO as output for chip select
    if (gpioWrite(GPIO_CS, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO as output.\n");
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
