        close(i2c_fd);
        return 1;
    }

    fprintf(log_file, "timestamp,als_visible\n");

    while (1) {
        als_visible = read_als_visible();
        if (als_visible == 0) {
            continue;
        }

        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%u\n", timestamp, als_visible);

        delay.tv_sec = 5;
        delay.tv_nsec = 0;
        nanosleep(&delay, NULL);
    }

    fclose(log_file);
    close(i2c_fd);

    return 0;
}

