#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define I2C_REG_RESET 0x30
#define I2C_REG_PART_ID 0x00
#define I2C_REG_ALS_LOW 0x22
#define I2C_REG_ALS_HIGH 0x23
#define I2C_REG_PROX_LOW 0x18
#define I2C_REG_PROX_HIGH 0x19
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 10

void handle_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

int read_i2c_register(int handle, uint8_t reg, uint8_t *data) {
    int retries = 0;
    while (retries < I2C_RETRY_COUNT) {
        if (i2c_read_device(handle, reg, 1, data) == 0) {
            return 0;
        }
        retries++;
        usleep(I2C_RETRY_DELAY * 1000);
    }
    return -1;
}

int write_i2c_register(int handle, uint8_t reg, uint8_t data) {
    int retries = 0;
    while (retries < I2C_RETRY_COUNT) {
        if (i2c_write_device(handle, reg, &data, 1) == 0) {
            return 0;
        }
        retries++;
        usleep(I2C_RETRY_DELAY * 1000);
    }
    return -1;
}

int main() {
    int handle;
    FILE *log_file;
    uint8_t part_id[2];
    uint16_t als_data, prox_data;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        handle_error("Failed to initialize pigpio");
    }

    // Open I2C bus
    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        handle_error("Failed to open I2C bus");
    }

    // Reset sensor
    if (write_i2c_register(handle, I2C_REG_RESET, 0x01)) {
        handle_error("Failed to reset sensor");
    }

    // Verify part ID
    if (read_i2c_register(handle, I2C_REG_PART_ID, part_id)) {
        handle_error("Failed to read part ID");
    }
    if (part_id[0] != 0x41) {
        handle_error("Invalid part ID");
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (!log_file) {
        handle_error("Failed to open log file");
    }

    // Main loop
    while (1) {
        // Read ALS data
        uint8_t als_low, als_high;
        if (read_i2c_register(handle, I2C_REG_ALS_LOW, &als_low) ||
            read_i2c_register(handle, I2C_REG_ALS_HIGH, &als_high)) {
            handle_error("Failed to read ALS data");
        }
        als_data = (als_high << 8) | als_low;

        // Read proximity data
        uint8_t prox_low, prox_high;
        if (read_i2c_register(handle, I2C_REG_PROX_LOW, &prox_low) ||
            read_i2c_register(handle, I2C_REG_PROX_HIGH, &prox_high)) {
            handle_error("Failed to read proximity data");
        }
        prox_data = (prox_high << 8) | prox_low;

        // Log data
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
        fprintf(log_file, "%s: ALS=%d, Proximity=%d\n", timestamp, als_data, prox_data);
        fflush(log_file);

        // Sleep for 500 ms
        usleep(500 * 1000);

        // Check for SIGINT
        if (signal(SIGINT, SIG_DFL) == SIG_ERR) {
            handle_error("Failed to reset SIGINT handler");
        }
        if (kill(getpid(), SIGINT) == -1) {
            handle_error("Failed to send SIGINT to self");
        }
    }

    // Cleanup
    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

