#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x39
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define AMBIENT_LIGHT_REG 0x22
#define PROXIMITY_REG 0x24

static int i2c_fd;
static FILE *log_file;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct i2c_rdwr_ioctl_data rdwr;
    struct i2c_msg msg[2];
    char part_id[2];
    uint16_t ambient_light, proximity;
    struct timespec ts;
    char timestamp[20];

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Verify part ID
    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = &PART_ID_REG;

    msg[1].addr = I2C_ADDR;
    msg[1].flags = 0;
    msg[1].len = 1;
    msg[1].buf = part_id;

    rdwr.msgs = msg;
    rdwr.nmsgs = 2;

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to read part ID");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    if (part_id[0] != 0x53 || part_id[1] != 0x00) {
        fprintf(stderr, "Sensor not found or incorrect part ID\n");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Configure measurement rate
    msg[0].len = 1;
    msg[0].buf = &MEAS_RATE_REG;
    msg[1].len = 1;
    msg[1].buf = &0x07;

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to configure measurement rate");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ambient light and proximity
        msg[0].len = 2;
        msg[0].buf = &AMBIENT_LIGHT_REG;
        msg[1].len = 2;
        msg[1].buf = &PROXIMITY_REG;

        if (ioctl(i2c_fd, I2C_RDWR, &rdwr) < 0) {
            perror("Failed to read sensor data");
            close(i2c_fd);
            fclose(log_file);
            return 1;
