int main() {
    FILE *logFile = NULL;
    int i2cHandle = -1;
    unsigned char data[2];
    unsigned int proximityValue;
    int retries = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

