    i2cHandle = i2cOpen(I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus at address 0x%02X.\n", I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (i2cWriteByteData(i2cHandle, 0x07, 0x03) < 0 ||
        i2cWriteByteData(i2cHandle, 0x06, 0x02) < 0 ||
        i2cWriteByteData(i2cHandle, 0x1A, 0x00) < 0 ||
        i2cWriteByteData(i2cHandle, 0x21, 0x0B) < 0 ||
        i2cWriteByteData(i2cHandle, 0x24, 0x00) < 0 ||
        i2cWriteByteData(i2cHandle, 0x22, 0x49) < 0 ||
        i2cWriteByteData(i2cHandle, 0x0C, 0x03) < 0 ||
        i2cWriteByteData(i2cHandle, 0x0F, 0x0F) < 0 ||
        i2cWriteByteData(i2cHandle, 0x11, 0x03) < 0 ||
        i2cWriteByteData(i2cHandle, 0x0D, 0x07) < 0 ||
        i2cWriteByteData(i2cHandle, 0x80, 0x03) < 0) {
        fprintf(stderr, "Failed to initialize Si1145 sensor.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read proximity data
        if (i2cReadByteData(i2cHandle, 0x16, &data[0]) < 0 ||
            i2cReadByteData(i2cHandle, 0x17, &data[1]) < 0) {
            if (retries < MAX_RETRIES) {
                retries++;
                continue;
            } else {
                fprintf(stderr, "Failed to read proximity data after %d retries.\n", MAX_RETRIES);
                break;
            }
        }

        // Combine low and high bytes into a 16-bit unsigned integer
        proximityValue = (data[1] << 8) | data[0];

        // Log the reading with a timestamp
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
        fprintf(logFile, "%s: Proximity Value = %u\n", timestamp, proximityValue);
        fflush(logFile);

        // Reset retries
        retries = 0;
    }

    // Clean up
    if (logFile != NULL) {
        fclose(logFile);
    }
    i2cClose(i2cHandle);
    gpioTerminate();

    return 0;
}

