#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define DISTANCE_THRESHOLD 20
#define SPEED_OF_SOUND 0.0343

volatile sig_atomic_t running = 1;

void handle_interrupt(int gpio, int level, uint32_t tick) {
    static uint32_t start_time = 0;
    static uint32_t end_time = 0;

    if (level == 1) {
        start_time = tick;
    } else if (level == 0) {
        end_time = tick;
        uint32_t pulse_width = end_time - start_time;
        double distance = (double)pulse_width * SPEED_OF_SOUND / 2;

        printf("Distance: %.2f cm\n", distance);

        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(BUZZER_PIN, 1);
        } else {
            gpioWrite(BUZZER_PIN, 0);
        }
    }
}

void handle_sigint(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    if (gpioInitialiseAlert(ECHO_PIN, PI_FALLING_EDGE | PI_RISING_EDGE, handle_interrupt) < 0) {
        fprintf(stderr, "Failed to initialize alert on ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);

    signal(SIGINT, handle_sigint);

    while (running) {
        gpioWrite(TRIGGER_PIN, 0);
        gpioDelay(2);
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        while (running && !gpioRead(ECHO_PIN)) {
            gpioDelay(1000);
        }
    }

    gpioTerminate();
    return 0;
}

