#include <stdio.h>
#include <pigpio.h>
#include <signal.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

double calculate_distance(int echo_pin) {
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, PI_LOW);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, PI_HIGH);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, PI_LOW);

    int start = 0;
    int end = 0;

    while (gpioRead(echo_pin) == PI_LOW) {
        if (start == 0) {
            start = gpioTick();
        }
    }

    while (gpioRead(echo_pin) == PI_HIGH) {
        end = gpioTick();
    }

    if (end == 0) {
        return -1.0; // Timeout
    }

    double duration = (double)(end - start) / 1000000000.0;
    double distance = (duration * 34300.0) / 2.0; // Speed of sound in cm/s

    return distance;
}

void set_servo_angle(int servo_pin, double angle) {
    double pulse_width = 500.0 + (angle * 10.0);
    gpioServo(servo_pin, pulse_width);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!stop) {
        double distance = calculate_distance(ECHO_PIN);

        if (distance >= 0.0) {
            double angle = (distance - 20.0) / (200.0 - 20.0) * 160.0;
            angle = (angle < 0.0) ? 0.0 : (angle > 180.0) ? 180.0 : angle;
            set_servo_angle(SERVO_PIN, angle);
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        } else {
            printf("Sensor error or timeout\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    set_servo_angle(SERVO_PIN, 90.0); // Stop servo at 90 degrees
    gpioTerminate();

    return 0;
}

