#include <stdio.h>
#include <pigpio.h>
#include <signal.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

double measure_distance() {
    gpioWrite(TRIGGER_PIN, PI_LOW);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, PI_HIGH);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, PI_LOW);

    int start_tick = gpioTick(ECHO_PIN);
    int timeout_us = 50000;
    int end_tick = start_tick;

    while (gpioRead(ECHO_PIN) == PI_LOW && (end_tick - start_tick) < timeout_us) {
        end_tick = gpioTick(ECHO_PIN);
    }

    if ((end_tick - start_tick) >= timeout_us) {
        return -1.0;
    }

    double pulse_duration_us = (double)(end_tick - start_tick);
    double distance_cm = (pulse_duration_us * 0.0343) / 2;

    return distance_cm;
}

double map_distance_to_angle(double distance_cm) {
    if (distance_cm < 20) {
        return 0.0;
    } else if (distance_cm > 200) {
        return 180.0;
    } else {
        return ((distance_cm - 20) / 180.0) * 180.0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    signal(SIGINT, handle_sigint);

    while (!stop) {
        double distance_cm = measure_distance();

        if (distance_cm >= 0) {
            double angle = map_distance_to_angle(distance_cm);
            double pulse_width_us = 500 + (angle * (2500 - 500) / 180.0);
            gpioServo(SERVO_PIN, pulse_width_us);

            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance_cm, angle);
        } else {
            printf("Timeout measuring distance\n");
        }

        gpioServo(SERVO_PIN, 0); // Stop servo
        gpioDelay(100); // 100 ms delay
    }

    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();

    return 0;
}

