#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMIDITY_REG 0x02
#define WAIT_TIME 10000 // 10 ms

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    pigpio_stop();
    exit(0);
}

int main() {
    int i2c_handle = -1;
    uint8_t config_data = 0x00;
    uint16_t raw_temp, raw_humidity;
    double temp, humidity;

    // Initialize pigpio
    if (pigpio_start() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Register SIGINT handler
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2c_handle = i2c_open(I2C_BUS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_stop();
        return 1;
    }

    // Write to CONFIG register
    if (i2c_write_device(i2c_handle, I2C_ADDR, &config_data, 1) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Wait for the sensor to stabilize
    usleep(WAIT_TIME);

    // Main loop
    while (1) {
        // Read temperature register
        if (i2c_read_device(i2c_handle, I2C_ADDR, &raw_temp, 2) < 0) {
            fprintf(stderr, "Failed to read temperature register\n");
            i2c_close(i2c_handle);
            pigpio_stop();
            return 1;
        }

        // Wait for conversion
        usleep(WAIT_TIME);

        // Read humidity register
        if (i2c_read_device(i2c_handle, I2C_ADDR, &raw_humidity, 2) < 0) {
            fprintf(stderr, "Failed to read humidity register\n");
            i2c_close(i2c_handle);
            pigpio_stop();
            return 1;
        }

        // Convert raw readings to temperature and humidity
        temp = (175.72 * raw_temp) / 65536.0 - 46.85;
        humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;

        // Print readings
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, humidity);

        // Sleep for 2 seconds
        sleep(2);
    }

    // Cleanup on exit
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    pigpio_stop();

    return 0;
}

