#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define DATA_REG_START 0x3B
#define DATA_LEN 14

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    printf("Starting accelerometer and gyroscope data logger...\n");

    int i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    uint8_t whoAmI;
    if (i2cReadI2CBlockData(i2cHandle, WHO_AM_I, 1, &whoAmI) != 1 || whoAmI != 0x68) {
        fprintf(stderr, "Sensor not found or WHO_AM_I register does not match expected value.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Reset the device
    uint8_t reset = 0x80;
    if (i2cWriteReg(i2cHandle, PWR_MGMT_1, &reset, 1) != 1) {
        fprintf(stderr, "Failed to reset the sensor.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Wait for the sensor to stabilize
    usleep(100000);

    // Clear the sleep bit
    uint8_t clearSleep = 0x00;
    if (i2cWriteReg(i2cHandle, PWR_MGMT_1, &clearSleep, 1) != 1) {
        fprintf(stderr, "Failed to clear sleep bit.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Set sample rate divider
    uint8_t sampleRate = 7;
    if (i2cWriteReg(i2cHandle, SMPLRT_DIV, &sampleRate, 1) != 1) {
        fprintf(stderr, "Failed to set sample rate divider.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Configure accelerometer and gyroscope ranges
    uint8_t accelConfig = 0x00; // ±2g
    uint8_t gyroConfig = 0x00; // ±250 deg/s
    if (i2cWriteReg(i2cHandle, ACCEL_CONFIG, &accelConfig, 1) != 1 ||
        i2cWriteReg(i2cHandle, GYRO_CONFIG, &gyroConfig, 1) != 1) {
        fprintf(stderr, "Failed to configure accelerometer and gyroscope ranges.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        uint8_t data[DATA_LEN];
        if (i2cReadI2CBlockData(i2cHandle, DATA_REG_START, DATA_LEN, data) != DATA_LEN) {
            fprintf(stderr, "Failed to read data from sensor.\n");
            continue;
        }

        int16_t accelX = (data[0] << 8) | data[1];
        int16_t accelY = (data[2] << 8) | data[3];
        int16_t accelZ = (data[4] << 8) | data[5];
        int16_t temp = (data[6] << 8) | data[7];
        int16_t gyroX = (data[8] << 8) | data[9];
        int16_t gyroY = (data[10] << 8) | data[11];
        int16_t gyroZ = (data[12] << 8) | data[13];

        printf("Accelerometer: X=%d, Y=%d, Z=%d, Temp=%d, Gyroscope: X=%d, Y=%d, Z=%d\n",
               accelX, accelY, accelZ, temp, gyroX, gyroY, gyroZ);

        usleep(100000); // 100 ms delay
    }

    printf("Shutting down...\n");
    i2cClose(i2cHandle);
    gpioTerminate();

    return 0;
}

