#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define CMD_MEASURE 0xFD
#define TEMP_OFFSET -45
#define TEMP_SCALE 175
#define HUMIDITY_OFFSET -6
#define HUMIDITY_SCALE 125
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

void handle_signal(int signum) {
    if (pi != 0) {
        i2cUnexport(I2C_BUS, SHT40_ADDR);
        pigpioStop();
    }
    exit(signum);
}

int main() {
    int pi = 0;
    int i2c_handle = -1;
    unsigned char buffer[6];
    unsigned char crc_temp, crc_humidity;
    unsigned int raw_temp, raw_humidity;
    float temp, humidity;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((pi = pigpioOpen(NULL)) < 0) {
        fprintf(stderr, "pigpioOpen failed\n");
        return 1;
    }

    if (i2cOpen(pi, I2C_BUS, SHT40_ADDR, 0) < 0) {
        fprintf(stderr, "i2cOpen failed\n");
        pigpioStop();
        return 1;
    }

    while (1) {
        if (i2cWriteDevice(pi, SHT40_ADDR, &CMD_MEASURE, 1) < 0) {
            fprintf(stderr, "i2cWriteDevice failed\n");
            continue;
        }

        usleep(10000); // Wait at least 10 ms

        if (i2cReadDevice(pi, SHT40_ADDR, buffer, 6) < 0) {
            fprintf(stderr, "i2cReadDevice failed\n");
            continue;
        }

        raw_temp = (buffer[0] << 8) | buffer[1];
        crc_temp = buffer[2];
        raw_humidity = (buffer[3] << 8) | buffer[4];
        crc_humidity = buffer[5];

        if (crc8(buffer, 5, CRC_POLY, CRC_INIT) != crc_temp ||
            crc8(buffer + 3, 3, CRC_POLY, CRC_INIT) != crc_humidity) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        temp = TEMP_OFFSET + (TEMP_SCALE * raw_temp) / 65535.0;
        humidity = HUMIDITY_OFFSET + (HUMIDITY_SCALE * raw_humidity) / 65535.0;

        if (temp < 0) temp = 0;
        if (temp > 100) temp = 100;
        if (humidity < 0) humidity = 0;
        if (humidity > 100) humidity = 100;

        printf("Temperature: %.2f C, Humidity: %.2f %\n", temp, humidity);

        usleep(5000000); // Wait 5 seconds
    }

    if (i2c_handle >= 0) {
        i2cUnexport(I2C_BUS, SHT40_ADDR);
    }

    pigpioStop();

    return 0;
}

unsigned char crc8(unsigned char *data, int len, unsigned char poly, unsigned char init) {
    unsigned char crc = init;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

