#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"

void handle_sigint(int signum) {
    printf("\nReceived SIGINT, cleaning up...\n");
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

int read_i2c_register(int fd, uint8_t reg) {
    char buffer[3];
    int bytes_read;

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if ((bytes_read = read(fd, buffer, 2)) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

int main() {
    int i2c_fd;
    FILE *log_file;
    struct timespec ts;
    uint16_t ambient_temp, object_temp;

    // Register signal handler
    signal(SIGINT, handle_sigint);

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Ambient Temperature,Object Temperature\n");

    while (1) {
        // Read ambient temperature
        ambient_temp = read_i2c_register(i2c_fd, AMBIENT_TEMP_REG);
        if (ambient_temp < 0) {
            fprintf(log_file, "Error reading ambient temperature\n");
            continue;
        }

        // Read object temperature
        object_temp = read_i2c_register(i2c_fd, OBJECT_TEMP_REG);
        if (object_temp < 0) {
            fprintf(log_file, "Error reading object temperature\n");
            continue;
        }

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Write to log file
        fprintf(log_file, "%ld,%d,%d\n", ts.tv_sec, ambient_temp, object_temp);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close resources
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

