This C program reads ambient and object temperatures from a Melexis MLX90614ESF-BAA infrared temperature sensor connected to a Raspberry Pi 3 Model B+ via the I2C interface. It logs the readings to a comma-separated file named 'temperature_log.csv' every 5 seconds. The program handles I2C initialization failures, sensor-absent scenarios, and file I/O errors gracefully. It also handles SIGINT for clean resource release, closing both the I2C file descriptor and the log file before the process exits.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define TEMP_LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define PERIOD 5000 // 5 seconds

FILE *temp_log_file;
FILE *error_log_file;

void handle_sigint(int signum) {
    if (temp_log_file) {
        fclose(temp_log_file);
    }
    if (error_log_file) {
        fclose(error_log_file);
    }
    gpioTerminate();
    exit(0);
}

void log_error(const char *msg) {
    if (error_log_file) {
        fprintf(error_log_file, "%s\n", msg);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    temp_log_file = fopen(TEMP_LOG_FILE, "a");
    if (!temp_log_file) {
        log_error("Failed to open temperature log file");
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        log_error("Failed to open error log file");
        fclose(temp_log_file);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        int result = i2cOpen(I2C_BUS, I2C_ADDR, 0);
        if (result < 0) {
            log_error("Failed to open I2C bus");
            continue;
        }

        char buffer[2];
        result = i2cRead(I2C_ADDR, buffer, 2);
        if (result < 0) {
            log_error("Failed to read from sensor");
            i2cClose(I2C_ADDR);
            continue;
        }

        double temperature = (buffer[0] << 8) | buffer[1];
        temperature /= 100.0; // Convert to Celsius

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(temp_log_file, "%d-%02d-%02d %02d:%02d:%02d %.2f\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, temperature);

        i2cClose(I2C_ADDR);

        sleep(PERIOD / 1000); // Sleep for 5 seconds
    }

    return 0;
}

