#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define PRESSURE_CMD 0x36
#define PRESSURE_DATA_LEN 9
#define PRESSURE_DATA_INTERVAL 1000 // 1 second
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// CRC-8 function
uint8_t crc8(uint8_t *data, uint8_t len) {
    uint8_t crc = CRC_INIT;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(uint8_t *data) {
    int result = i2c_read_device(I2C_BUS, I2C_ADDR, data, PRESSURE_DATA_LEN);
    if (result != PRESSURE_DATA_LEN) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to write command to the sensor
int write_command(uint8_t cmd) {
    int result = i2c_write_device(I2C_BUS, I2C_ADDR, &cmd, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw pressure and temperature
void convert_data(uint8_t *data, double *pressure, double *temperature) {
    uint16_t raw_pressure = (data[0] << 8) | data[1];
    uint16_t raw_temperature = (data[3] << 8) | data[4];
    uint16_t scale_pressure = (data[6] << 8) | data[7];
    uint16_t scale_temperature = (data[8] << 8) | data[9];

    *pressure = (double)raw_pressure / scale_pressure;
    *temperature = (double)raw_temperature / scale_temperature;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    printf("\nReceived signal %d, cleaning up...\n", signum);
    if (pi != NULL) {
        gpioTerminate();
    }
