#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define CMD_TRIGGER 0x21
#define CMD_DATA 0x96
#define RETRIES 3
#define BACKOFF_FACTOR 2
#define BACKOFF_MAX 1000
#define SAMPLE_INTERVAL 100

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    exit_flag = 1;
}

int i2c_write_retry(int handle, const char *data, size_t length) {
    int retries = 0;
    int result = -1;
    int backoff = 1;

    while (retries < RETRIES) {
        result = i2cWriteDevice(handle, data, length);
        if (result == length) {
            break;
        }
        retries++;
        if (backoff < BACKOFF_MAX) {
            backoff *= BACKOFF_FACTOR;
        }
        usleep(backoff * 1000);
    }

    return result;
}

int i2c_read_retry(int handle, char *data, size_t length) {
    int retries = 0;
    int result = -1;
    int backoff = 1;

    while (retries < RETRIES) {
        result = i2cReadDevice(handle, data, length);
        if (result == length) {
            break;
        }
        retries++;
        if (backoff < BACKOFF_MAX) {
            backoff *= BACKOFF_FACTOR;
        }
        usleep(backoff * 1000);
    }

    return result;
}

int main() {
    int handle;
    FILE *log_file;
    char data[6];
    double pressure_pa, temperature_c;
    struct timespec ts;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("airflow.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!exit_flag) {
        clock_gettime(CLOCK_REALTIME, &ts);

        if (i2c_write_retry(handle, (const char[]){CMD_TRIGGER, CMD_DATA}) != 2) {
            fprintf(stderr, "Failed to send trigger command\n");
            continue;
        }

        usleep(1000);

        if (i2c_read_retry(handle, data, 6) != 6) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }

        unsigned int raw_pressure = (data[0] << 8) | data[1];
        unsigned int raw_temperature = (data[3] << 8) | data[4];

        pressure_pa = (double)raw_pressure / 60.0;
        temperature_c = (double)raw_temperature / 200.0;

        fprintf(log_file, "%ld,%f,%f\n", ts.tv_sec, pressure_pa, temperature_c);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

