#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMIDITY_CMD 0xF5
#define FILE_NAME "sensor_data.txt"
#define SAMPLE_INTERVAL 5000 // 5 seconds

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    pigpio_stop();
    if (file != NULL) {
        fclose(file);
    }
    exit(0);
}

int read_sensor(int command) {
    int raw_value = 0;
    int retries = 3;

    while (retries > 0) {
        if (i2c_write_device(i2c_handle, &command, 1) == 1) {
            int retries_read = 20;
            while (retries_read > 0) {
                if (i2c_read_device(i2c_handle, (char*)&raw_value, 2) == 2) {
                    break;
                }
                retries_read--;
                usleep(10000); // 10 ms sleep
            }
            if (retries_read > 0) {
                break;
            }
        }
        retries--;
        usleep(100000); // 100 ms sleep
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read sensor data: %s\n", pigpio_error());
        return -1;
    }

    return raw_value;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpio_error());
        pigpio_stop();
        return 1;
    }

    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        int temp_raw = read_sensor(TEMP_CMD);
        if (temp_raw == -1) {
            continue;
        }

        double temp = (175.72 * temp_raw / 65536.0) - 46.85;

        int humidity_raw = read_sensor(HUMIDITY_CMD);
        if (humidity_raw == -1) {
            continue;
        }

        double humidity = (125.0 * humidity_raw / 65536.0) - 6.0;
        if (humidity < 0) {
            humidity = 0;
        } else if (humidity > 100) {
            humidity = 100;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d %.2f C %.2f %%RH\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, temp, humidity);

        printf("%04d-%02d-%02d %02d:%02d:%02d %.2f C %.2f %%RH\n",
               now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
               now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, temp, humidity);

        fflush(file);
        usleep(SAMPLE_INTERVAL * 1000); // Convert seconds to microseconds
    }

    fclose(file);
    i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

