#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x25
#define I2C_DEV "/dev/i2c-1"
#define PRESSURE_CMD 0x362F
#define PRESSURE_DATA_LEN 9
#define PRESSURE_SCALE_FACTOR 0x00
#define TEMPERATURE_SCALE_FACTOR 0x03
#define CRC_OFFSET 3
#define CRC_LEN 1

int i2c_fd;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

unsigned char crc8(unsigned char *data, int len) {
    unsigned char crc = 0;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x07;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("ioctl");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("airflow_data.txt", "w");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,pressure (Pa),temperature (°C)\n");

    while (1) {
        unsigned char cmd[2] = {0x36, 0x2F};
        if (write(i2c_fd, cmd, 2) != 2) {
            perror("write");
            break;
        }

        usleep(45000);

        unsigned char data[PRESSURE_DATA_LEN];
        if (read(i2c_fd, data, PRESSURE_DATA_LEN) != PRESSURE_DATA_LEN) {
            perror("read");
            break;
        }

        unsigned char pressure_crc = crc8(data, 3);
        unsigned char temperature_crc = crc8(data + 3, 3);
        unsigned char scale_factor_crc = crc8(data + 6, 3);

        if (pressure_crc != data[CRC_OFFSET] || temperature_crc != data[CRC_OFFSET + 3] || scale_factor_crc != data[CRC_OFFSET + 6]) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        unsigned int pressure = (data[0] << 16) | (data[1] << 8) | data[2];
        unsigned int temperature = (data[3] << 16) | (data[4] << 8) | data[5];
