#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define MEASUREMENT_CMD 0x2C06
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define CRC_DATA_LEN 2
#define CRC_CHECK_DELAY 15
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG "error_log.txt"

void handle_sigint(int signum) {
    fclose(stderr);
    fclose(stdout);
    close(I2C_BUS);
    gpioTerminate();
    exit(0);
}

int main() {
    FILE *log_file = fopen(LOG_FILE, "a");
    FILE *error_log = fopen(ERROR_LOG, "a");

    if (log_file == NULL || error_log == NULL) {
        perror("Failed to open log files");
        exit(1);
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        fclose(log_file);
        fclose(error_log);
        exit(1);
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        perror("Failed to open I2C bus");
        fclose(log_file);
        fclose(error_log);
        gpioTerminate();
        exit(1);
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        int cmd[2] = {MEASUREMENT_CMD >> 8, MEASUREMENT_CMD & 0xFF};
        uint8_t data[3];
        uint8_t crc;
        uint8_t calculated_crc;

        if (i2cWriteDevice(I2C_ADDR, cmd, 2) < 0) {
            fprintf(error_log, "Failed to write measurement command at %s\n", ctime(&time(NULL)));
            continue;
        }

        usleep(CRC_CHECK_DELAY * 1000);

        if (i2cReadDevice(I2C_ADDR, data, 3) < 0) {
            fprintf(error_log, "Failed to read data at %s\n", ctime(&time(NULL)));
            continue;
        }

        crc = data[2];
        calculated_crc = 0xFF;

        for (int i = 0; i < CRC_DATA_LEN; i++) {
            calculated_crc ^= data[i];
            for (int j = 0; j < 8; j++) {
                if (calculated_crc & 0x80) {
                    calculated_crc = (calculated_crc << 1) ^ CRC_POLYNOMIAL;
                } else {
                    calculated_crc <<= 1;
                }
            }
        }

        if (crc != calculated_crc) {
            fprintf(error_log, "CRC mismatch at %s\n", ctime(&time(NULL)));
            continue;
        }

        int raw_value = (data[0] << 8) | data[1];
        double temperature = -45 + 175 * (double)raw_value / 65535;

        fprintf(log_file, "%s: %.2f C\n", ctime(&time(NULL)), temperature);

        fflush(log_file);
        fflush(error_log);

        sleep(5);
    }

    fclose(log_file);
    fclose(error_log);
    close(I2C_BUS);
    gpioTerminate();

    return 0;
}

