#define I2C_DEV "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEAS_CMD 0xFD
#define T_MSB 0
#define T_LSB 1
#define T_CRC 2
#define RH_MSB 3
#define RH_LSB 4
#define RH_CRC 5
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

int i2c_fd;
