    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        unsigned char cmd[2] = {MEAS_CMD, 0};
        unsigned char data[6];

        if (write(i2c_fd, cmd, 2) != 2) {
            perror("Failed to write command to I2C device");
            continue;
        }

        usleep(8500); // Wait at least 8.5 ms

        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read data from I2C device");
            continue;
