        double rh = 100 * rh_raw / 65535.0;

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - Temperature: %.2f C, Humidity: %.2f %\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, temp, rh);

        fflush(log_file);

        sleep(5); // Wait 5 seconds before next reading
    }

    fclose(log_file);
    close(i2c_fd);

    return 0;
}

