#define I2C_DEV "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define SCALE_FACTOR_PRESSURE 240
#define SCALE_FACTOR_TEMPERATURE 200
#define TEMP_OFFSET -45

int i2c_fd;

void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
