    ret = read(i2c_fd, response, 6);
    if (ret != 6) {
        perror("Error reading from I2C device");
        return -1;
    }

    uint8_t pressure_msb = response[0];
    uint8_t pressure_lsb = response[1];
    uint8_t pressure_crc = response[2];
    uint8_t temperature_msb = response[3];
    uint8_t temperature_lsb = response[4];
    uint8_t temperature_crc = response[5];

    uint16_t pressure = (pressure_msb << 8) | pressure_lsb;
    uint16_t temperature = (temperature_msb << 8) | temperature_lsb;

    if (crc8(&response[0], 2) != pressure_crc || crc8(&response[3], 2) != temperature_crc) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    double pressure_pa = pressure * SCALE_FACTOR_PRESSURE;
    double temperature_c = (temperature * SCALE_FACTOR_TEMPERATURE) + TEMP_OFFSET;

    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);

    fprintf(stderr, "%f, %f, %d-%02d-%02d %02d:%02d:%02d\n", pressure_pa, temperature_c, now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday, now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec);

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd == -1) {
        perror("Error opening I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (read_sensor_data() == -1) {
            break;
        }
    }

    fclose(log_file);
    close(i2c_fd);

    return 0;
}
