#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define TEMP_CMD 0xE3
#define HUMIDITY_CMD 0xE5
#define TEMP_OFFSET -46.85
#define HUMIDITY_OFFSET -6.0
#define TEMP_SCALE 175.72
#define HUMIDITY_SCALE 125.0
#define BUFFER_SIZE 60
#define FAN_GPIO 18
#define FAN_ON 1
#define FAN_OFF 0
#define MAX_RETRIES 3

typedef struct {
    double temperature;
    double humidity;
    time_t timestamp;
} SensorReading;

SensorReading buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int fan_state = FAN_OFF;

void handle_sigint(int signum) {
    if (fan_state == FAN_ON) {
        gpioWrite(FAN_GPIO, FAN_OFF);
    }
    i2cStop(I2C_BUS);
    gpioTerminate();
    exit(0);
}

double read_sensor(int command) {
    int retries = 0;
    int status;
    unsigned char data[2];

    while (retries < MAX_RETRIES) {
        status = i2cWriteReg(I2C_BUS, I2C_ADDR, command, 0, 0);
        if (status == 0) {
            usleep(10000); // Wait at least 10 ms
            status = i2cReadReg(I2C_BUS, I2C_ADDR, 0, 2, data);
            if (status == 0) {
                return ((double)data[0] << 8 | data[1]) * (command == TEMP_CMD ? TEMP_SCALE : HUMIDITY_SCALE) / 65536.0 + (command == TEMP_CMD ? TEMP_OFFSET : HUMIDITY_OFFSET);
            }
        }
        retries++;
    }
    return 0.0; // Return 0.0 if sensor is absent or error persists
}

void log_reading(double temperature, double humidity) {
    time_t now = time(NULL);
    SensorReading reading = {temperature, humidity, now};

    buffer[buffer_head] = reading;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    if (buffer_head == buffer_tail) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    }

    printf("Timestamp: %s, Temperature: %.2f °C, Humidity: %.2f %%\n", ctime(&now), temperature, humidity);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        double temperature = read_sensor(TEMP_CMD);
        double humidity = read_sensor(HUMIDITY_CMD);

        if (temperature > 28.0) {
            if (fan_state == FAN_OFF) {
                gpioWrite(FAN_GPIO, FAN_ON);
                fan_state = FAN_ON;
            }
        } else if (temperature < 27.0) {
            if (fan_state == FAN_ON) {
                gpioWrite(FAN_GPIO, FAN_OFF);
                fan_state = FAN_OFF;
            }
        }

        log_reading(temperature, humidity);

        sleep(2);
    }

    return 0;
}

