#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x62
#define CMD_START_MEASUREMENT 0x21B1
#define CMD_STOP_MEASUREMENT 0x3F86
#define DATA_READY_FLAG 0xE4B8
#define READ_DATA 0xEC05
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "air_quality.log"

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_write_device(i2c_handle, &CMD_STOP_MEASUREMENT, 2);
        i2c_close(i2c_handle);
    }
    if (pi != -1) {
        pigpio_stop();
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    int pi = -1;
    int i2c_handle = -1;
    FILE *log_file = NULL;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    pi = pigpio_start();
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio.\n");
        return 1;
    }

    i2c_handle = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        pigpio_stop();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    fprintf(log_file, "timestamp,CO2_ppm,Temperature_C,Humidity_pct\n");

    if (i2c_write_device(i2c_handle, &CMD_START_MEASUREMENT, 2) < 0) {
        fprintf(stderr, "Failed to send start measurement command.\n");
        fclose(log_file);
        i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        usleep(1000000); // Wait at least 1 second

        uint8_t data[9];
        if (i2c_read_device(i2c_handle, &data, 9) != 9) {
            fprintf(stderr, "Failed to read data from sensor.\n");
            continue;
        }

        if ((data[0] & 0x80) == 0) { // Check data-ready flag
            uint16_t co2 = (data[1] << 8) | data[2];
            uint16_t temp = (data[3] << 8) | data[4];
            uint16_t hum = (data[5] << 8) | data[6];

            uint8_t crc = 0xFF;
            for (int i = 0; i < 6; i++) {
                crc = (crc >> 1) ^ ((crc & 1) * CRC_POLYNOMIAL);
                crc ^= data[i];
            }

            if (crc != data[7]) {
                fprintf(stderr, "CRC check failed.\n");
                continue;
            }

            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

            fprintf(log_file, "%s,%d,%f,%f\n", timestamp, co2, -45 + 175.0 * temp / (1 << 16), 100.0 * hum / (1 << 16));
            fflush(log_file);
        }

        sleep(5); // Poll every 5 seconds
    }

    handle_sigint(0); // This will be called on SIGINT

    return 0;
}

