This C program initializes the pigpio library, opens the I2C bus, and sends the Start Periodic Measurement command to the Sensirion SCD40 CO2 sensor. It waits for at least 1 second before attempting to read data, polls the data-ready flag, and reads 9 bytes of data, verifying the CRC-8 checksum. It logs the CO2, temperature, and humidity to 'air_quality.log' every 5 seconds. On SIGINT (Ctrl+C), it sends the Stop Periodic Measurement command, closes the I2C handle, terminates pigpio, closes the log file, and exits cleanly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x62
#define LED_GPIO 17
#define MEASUREMENT_INTERVAL 5000 // 5 seconds
#define CIRCULAR_BUFFER_SIZE 20

typedef struct {
    int co2;
    int temperature;
    int humidity;
} SensorReading;

SensorReading readings[CIRCULAR_BUFFER_SIZE];
int buffer_index = 0;

void handle_signal(int signum) {
    if (pi_stop_periodic_measurement(I2C_ADDR, 0x21B1)) {
        fprintf(stderr, "Failed to stop periodic measurement.\n");
    }
    if (i2c_close(I2C_BUS)) {
        fprintf(stderr, "Failed to close I2C bus.\n");
    }
    if (gpio_set_mode(LED_GPIO, PI_INPUT)) {
        fprintf(stderr, "Failed to set LED GPIO to input.\n");
    }
    if (pi_stop()) {
        fprintf(stderr, "Failed to stop pigpio.\n");
    }
    exit(1);
}

void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int crc8(unsigned char *data, int length) {
    int crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >> 1) ^ 0x07;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data() {
    unsigned char buffer[9];
    if (i2c_write_device(I2C_BUS, I2C_ADDR, (unsigned char[]){0xEC, 0x05}, 2)) {
        fprintf(stderr, "Failed to write to sensor.\n");
        return -1;
    }
    if (i2c_read_device(I2C_BUS, I2C_ADDR, buffer, 9)) {
        fprintf(stderr, "Failed to read from sensor.\n");
        return -1;
    }
    if (crc8(buffer, 6) != buffer[6] || crc8(buffer + 1, 6) != buffer[7] || crc8(buffer + 2, 6) != buffer[8]) {
        fprintf(stderr, "CRC-8 checksum failed.\n");
        return -1;
    }
    SensorReading reading;
    reading.co2 = (buffer[0] << 8) | buffer[1];
    reading.temperature = (buffer[2] << 8) | buffer[3];
    reading.humidity = (buffer[4] << 8) | buffer[5];
    readings[buffer_index] = reading;
    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
    printf("CO2: %d ppm, Temperature: %d, Humidity: %d\n", reading.co2, reading.temperature, reading.humidity);
    if (reading.co2 > 1000) {
        if (gpio_write(LED_GPIO, PI_ON)) {
            fprintf(stderr, "Failed to turn on LED.\n");
        }
    } else {
        if (gpio_write(LED_GPIO, PI_OFF)) {
            fprintf(stderr, "Failed to turn off LED.\n");
        }
    }
    return 0;
}

int main() {
    if (pi_start()) {
        fprintf(stderr, "Failed to start pigpio.\n");
        return 1;
    }
    if (i2c_open(I2C_BUS, 0)) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        pi_stop();
        return 1;
    }
    if (gpio_set_mode(LED_GPIO, PI_OUTPUT)) {
        fprintf(stderr, "Failed to set LED GPIO to output.\n");
        i2c_close(I2C_BUS);
        pi_stop();
        return 1;
    }
    if (pi_start_periodic_measurement(I2C_ADDR, 0x21B1, MEASUREMENT_INTERVAL)) {
        fprintf(stderr, "Failed to start periodic measurement.\n");
        i2c_close(I2C_BUS);
        gpio_set_mode(LED_GPIO, PI_INPUT);
        pi_stop();
        return 1;
    }
    setup_signal_handler();
    while (1) {
        if (read_sensor_data() == -1) {
            break;
        }
    }
    return 0;
}

