#define MAX_FAILURES 3
#define TEMP_FILE "temperature_log.txt"

volatile int failure_count = 0;
volatile int running = 1;

void handle_signal(int signum) {
    running = 0;
}

void log_temperature(double temperature) {
    FILE *file = fopen(TEMP_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file '%s'\n", TEMP_FILE);
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(file, "%s %.2f\n", buffer, temperature);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    FILE *log_file = fopen(TEMP_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open file '%s'\n", TEMP_FILE);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        int TH = 0, TL = 0;
        unsigned long start_time, end_time;

        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            if (gpioTick() - start_time > 50000) { // 50 ms timeout
                fprintf(log_file, "%s SENSOR MALFUNCTION\n", TEMP_FILE);
                failure_count = MAX_FAILURES;
                break;
            }
        }

        if (failure_count == MAX_FAILURES) {
            continue;
        }

        end_time = gpioTick();
        TH = end_time - start_time;

        start_time = end_time;
        while (gpioRead(GPIO_PIN) == 1) {
            if (gpioTick() - start_time > 50000) { // 50 ms timeout
                fprintf(log_file, "%s SENSOR MALFUNCTION\n", TEMP_FILE);
                failure_count = MAX_FAILURES;
                break;
            }
        }

        if (failure_count == MAX_FAILURES) {
            continue;
        }

        end_time = gpioTick();
        TL = end_time - start_time;

        if (TL == 0) {
            fprintf(log_file, "%s Division by zero error\n", TEMP_FILE);
            failure_count++;
            continue;
        }

        double temperature = 4215.0 - (2143.0 * TH / TL);

        if (temperature < -40.0 || temperature > 150.0) {
            fprintf(log_file, "%s Invalid temperature reading: %.2f\n", TEMP_FILE, temperature);
            failure_count++;
        } else {
            log_temperature(temperature);
            failure_count = 0;
        }

        if (failure_count == MAX_FAILURES) {
            fprintf(log_file, "%s SENSOR MALFUNCTION\n", TEMP_FILE);
        }

        sleep(SAMPLING_INTERVAL / 1000); // Convert to seconds
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

