code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

#define SHT35_ADDR 0x44
#define SHT35_MEASURE_CMD 0x24
#define SHT35_MEASURE_DATA_CMD 0x00
#define SHT35_TEMP_MSB 0x00
#define SHT35_TEMP_LSB 0x01
#define SHT35_HUMIDITY_MSB 0x02
#define SHT35_HUMIDITY_LSB 0x03
#define SHT35_CRC 0x04
#define SHT35_CRC_LEN 1
#define SHT35_DATA_LEN 6
#define SHT35_RETRY_COUNT 3
#define SHT35_RETRY_DELAY 1000 // ms
#define SHT35_OFFSET_AMPLITUDE_TEMP 2.0
#define SHT35_OFFSET_AMPLITUDE_HUMIDITY 5.0
#define SHT35_OFFSET_PERIOD 3600 // seconds
#define SHT35_LOG_INTERVAL 5000 // ms

double calculate_temperature(uint16_t raw_temp) {
    double temp = (double)raw_temp / 65536.0 * 165.0 - 40.0;
    return temp;
}

double calculate_humidity(uint16_t raw_humidity) {
    double humidity = (double)raw_humidity / 65536.0 * 125.0 - 6.0;
    return humidity;
}

void handle_signal(int signum) {
    if (pi_i2c_close(0) < 0) {
        fprintf(stderr, "Failed to close I2C handle.\n");
    }
    if (fclose(stdout) != 0) {
        fprintf(stderr, "Failed to close log file.\n");
    }
    if (pi_stop() < 0) {
        fprintf(stderr, "Failed to stop pigpio.\n");
    }
    exit(signum);
}

int main(int argc, char *argv[]) {
    int i2c_handle = -1;
    FILE *log_file = NULL;
    struct tm *tm_info;
    time_t current_time;
    double temperature, humidity;
    uint8_t data[SHT35_DATA_LEN];
    uint8_t crc;
    int retry_count;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    i2c_handle = pi_i2c_open(1, SHT35_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle.\n");
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        current_time = time(NULL);
        tm_info = localtime(&current_time);

        retry_count = 0;
        while (retry_count < SHT35_RETRY_COUNT) {
            if (pi_i2c_write(i2c_handle, &SHT35_MEASURE_CMD, 1) < 0) {
                fprintf(stderr, "Failed to write measurement command.\n");
                break;
            }

            usleep(15000); // Wait at least 15 ms

            if (pi_i2c_read(i2c_handle, data, SHT35_DATA_LEN) < 0) {
                fprintf(stderr, "Failed to read data.\n");
                break;
            }

            crc = data[SHT35_CRC];
            if (crc != (data[SHT35_TEMP_MSB] + data[SHT35_TEMP_LSB] + data[SHT35_HUMIDITY_MSB] + data[SHT35_HUMIDITY_LSB])) {
                fprintf(stderr, "CRC check failed.\n");
                break;
            }

            uint16_t raw_temp = (data[SHT35_TEMP_MSB] << 8) | data[SHT35_TEMP_LSB];
            uint16_t raw_humidity = (data[SHT35_HUMIDITY_MSB] << 8) | data[SHT35_HUMIDITY_LSB];

            temperature = calculate_temperature(raw_temp);
            humidity = calculate_humidity(raw_humidity);

            // Simulate sinusoidal offset
            double offset_temp = SHT35_OFFSET_AMPLITUDE_TEMP * sin(2 * M_PI * (double)current_time / SHT35_OFFSET_PERIOD);
            double offset_humidity = SHT35_OFFSET_AMPLITUDE_HUMIDITY * sin(2 * M_PI * (double)current_time / SHT35_OFFSET_PERIOD);

            temperature += offset_temp;
            humidity += offset_humidity;

            fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ %.2f C %.2f %%RH\n",
                    tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                    tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                    temperature, humidity);

            fflush(log_file);
            usleep(SHT35_LOG_INTERVAL * 1000); // Sleep for 5 seconds
            retry_count = SHT35_RETRY_COUNT; // Exit loop successfully
        }

        if (retry_count < SHT35_RETRY_COUNT) {
            fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ NaN C NaN %%RH\n",
                    tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                    tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);
            fflush(log_file);
            usleep(SHT35_RETRY_DELAY * 1000); // Sleep for 1 second before retrying
        }
    }

    fclose(log_file);
    pi_i2c_close(i2c_handle);
    pi_stop();

    return 0;
}

