This C program initializes the pigpio library, opens an I2C handle to the Sensirion SHT35-DIS-B sensor, and continuously reads temperature and humidity data. It validates the CRC and retries up to 3 times if the CRC check fails or if there's an I2C read/write error. It logs the data in ISO-8601 UTC format to 'environmental_data.txt' every 5 seconds, applying a simulated sinusoidal offset to the readings. The program handles SIGINT and SIGTERM signals for graceful shutdown, ensuring all resources are properly released.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define CONV_TIME 45
#define DATA_SIZE 9
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

int i2c_fd;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

unsigned char crc8(unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDR) == -1) {
        perror("Failed to acquire bus access/talk to slave");
        close(i2c_fd);
        return 1;
    }

    FILE *csv_file = fopen("airflow.csv", "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (°C)\n");

    while (1) {
        unsigned char cmd[2] = {CMD_CONT_MEAS >> 8, CMD_CONT_MEAS & 0xFF};
        if (write(i2c_fd, cmd, 2) != 2) {
            perror("Failed to send command");
            break;
        }

        unsigned char data[DATA_SIZE];
        if (read(i2c_fd, data, DATA_SIZE) != DATA_SIZE) {
            perror("Failed to read data");
            break;
        }

        unsigned char crc = crc8(data, DATA_SIZE - 1);
        if (crc != data[DATA_SIZE - 1]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        unsigned short pressure = (data[0] << 8) | data[1];
        unsigned short temperature = (data[2] << 8) | data[3];

        double pressure_pa = pressure * 0.001;
        double temperature_c = temperature * 0.01 - 50.0;

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(csv_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
                pressure_pa, temperature_c);

        fflush(csv_file);

        sleep(1);
    }

    fclose(csv_file);
    close(i2c_fd);

    return 0;
}

