    FILE *csv_file = fopen("airflow.csv", "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (°C)\n");

    while (1) {
        unsigned char cmd[2] = {CMD_CONT_MEAS >> 8, CMD_CONT_MEAS & 0xFF};
        if (write(i2c_fd, cmd, 2) != 2) {
            perror("Failed to send command");
            break;
        }

        unsigned char data[DATA_SIZE];
        if (read(i2c_fd, data, DATA_SIZE) != DATA_SIZE) {
            perror("Failed to read data");
            break;
        }

        unsigned char crc = crc8(data, DATA_SIZE - 1);
        if (crc != data[DATA_SIZE - 1]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        unsigned short pressure = (data[0] << 8) | data[1];
        unsigned short temperature = (data[2] << 8) | data[3];

        double pressure_pa = pressure * 0.001;
        double temperature_c = temperature * 0.01 - 50.0;

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(csv_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
                pressure_pa, temperature_c);

        fflush(csv_file);

        sleep(1);
    }

    fclose(csv_file);
    close(i2c_fd);

    return 0;
}
