#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SHT35_ADDR 0x44
#define MEASUREMENT_CMD 0x2400
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define TEMPERATURE_OFFSET -45
#define TEMPERATURE_SCALE 175
#define HUMIDITY_SCALE 100

void handle_signal(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    gpioTerminate();
    exit(signum);
}

int read_sensor(void) {
    uint8_t data[6];
    uint8_t crc_temp, crc_hum;
    int status;

    status = i2c_write_device(i2c_handle, SHT35_ADDR, &MEASUREMENT_CMD, 2);
    if (status != 2) {
        fprintf(stderr, "Failed to send measurement command to SHT35 sensor.\n");
        return -1;
    }

    usleep(15000); // Wait at least 15 ms

    status = i2c_read_device(i2c_handle, SHT35_ADDR, data, 6);
    if (status != 6) {
        fprintf(stderr, "Failed to read data from SHT35 sensor.\n");
        return -1;
    }

    crc_temp = data[2];
    crc_hum = data[5];

    if (crc_temp != calculate_crc8(data, 4, CRC_POLYNOMIAL, CRC_INITIAL_VALUE) ||
        crc_hum != calculate_crc8(data + 3, 3, CRC_POLYNOMIAL, CRC_INITIAL_VALUE)) {
        fprintf(stderr, "CRC validation failed for SHT35 sensor data.\n");
        return -1;
    }

    int16_t raw_temp = (data[0] << 8) | data[1];
    int16_t raw_hum = (data[3] << 8) | data[4];

    float temperature = TEMPERATURE_OFFSET + (float)raw_temp * TEMPERATURE_SCALE / 65535.0;
    float humidity = (float)raw_hum * HUMIDITY_SCALE / 65535.0;

    return 0;
}

uint8_t calculate_crc8(uint8_t *data, int length, uint8_t polynomial, uint8_t initial_value) {
    uint8_t crc = initial_value;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, SHT35_ADDR, 0);
    if (i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus 1 for SHT35 sensor.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *file = fopen("environment.csv", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open environment.csv for writing.\n");
        i2c_close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (fseek(file, 0, SEEK_END) == 0 && ftell(file) == 0) {
        fprintf(file, "timestamp,temperature_c,humidity_pct\n");
    }

    while (1) {
        struct tm *time_info;
        time_t raw_time;
        char timestamp[20];

        time(&raw_time);
        time_info = localtime(&raw_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

        if (read_sensor() == 0) {
            fprintf(file, "%s,%f,%f\n", timestamp, temperature, humidity);
        }

        sleep(5);
    }

    fclose(file);
    i2c_close(i2c_handle);
    gpioTerminate();

    return 0;
}

