This C program uses the pigpio library to read temperature and humidity from a Sensirion SHT35-DIS-B sensor connected to I2C bus 1 at address 0x44. It validates CRC-8 checksums, converts raw values, and logs each reading with an ISO-8601 timestamp to a CSV file named 'environment.csv'. It checks for errors at each step and handles them appropriately. A SIGINT/SIGTERM handler is installed for clean shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>

#define I2C_ADDR 0x40
#define I2C_BUS 1
#define I2C_RESET 0xFE
#define I2C_TEMP_CMD 0xF3
#define I2C_HUMIDITY_CMD 0xF5
#define I2C_PAIR_CMD 0xE0
#define I2C_TIMEOUT_MS 100
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0x00

int i2c_fd;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

unsigned char crc8(unsigned char *data, int len) {
    unsigned char crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

double read_temperature() {
    unsigned char data[3];
    int ret;

    ret = write(i2c_fd, &I2C_TEMP_CMD, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to write temperature command\n");
        return -1.0;
    }

    struct timespec timeout;
    timeout.tv_sec = 0;
    timeout.tv_nsec = I2C_TIMEOUT_MS * 1000000;

    ret = read(i2c_fd, data, 3);
    if (ret != 3) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1.0;
    }

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC error in temperature data\n");
        return -1.0;
    }

    unsigned int raw = (data[0] << 8) | data[1];
    return 175.72 * raw / 65536.0 - 46.85;
}

double read_humidity() {
    unsigned char data[3];
    int ret;

    ret = write(i2c_fd, &I2C_HUMIDITY_CMD, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to write humidity command\n");
        return -1.0;
    }

    struct timespec timeout;
    timeout.tv_sec = 0;
    timeout.tv_nsec = I2C_TIMEOUT_MS * 1000000;

    ret = read(i2c_fd, data, 3);
    if (ret != 3) {
        fprintf(stderr, "Failed to read humidity data\n");
        return -1.0;
    }

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC error in humidity data\n");
        return -1.0;
    }

    unsigned int raw = (data[0] << 8) | data[1];
    return 125.0 * raw / 65536.0 - 6.0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen("environment.log", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");

    while (1) {
        double temperature = read_temperature();
        double humidity = read_humidity();

        if (temperature < 0.0 || humidity < 0.0) {
            fprintf(stderr, "I2C error, resetting sensor\n");
            write(i2c_fd, &I2C_RESET, 1);
            continue;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);

        if (temperature >= 0.0 && humidity >= 0.0) {
            fprintf(log_file, "%s,%f,%f\n", timestamp, temperature, humidity);
        } else {
            fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
        }

        fflush(log_file);
        sleep(5);
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

