This C program sets up a SIGINT/SIGTERM handler to gracefully exit, opens the I2C bus, and reads temperature and humidity from the Adafruit Si7021 sensor at regular intervals. It logs the data to a CSV file and handles errors by resetting the sensor and logging an error message.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define CONV_TIME 1000000 // 1 second in microseconds
#define FILE_NAME "airflow.dat"

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int main() {
    FILE *file;
    int i2c_handle;
    uint8_t buffer[9];
    float pressure, temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open file for writing
    file = fopen(FILE_NAME, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file %s\n", FILE_NAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        // Send continuous measurement command
        if (i2cWriteDevice(i2c_handle, (uint8_t*)&CMD_CONT_MEAS, 2) != 2) {
            fprintf(stderr, "Failed to write command to sensor\n");
            break;
        }

        // Wait for conversion time
        usleep(CONV_TIME);

        // Read 9 bytes from sensor
        if (i2cReadDevice(i2c_handle, buffer, 9) != 9) {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
        }

        // Validate CRC-8 for pressure and temperature
        uint8_t crc_pressure = buffer[2];
        uint8_t crc_temperature = buffer[5];
        uint8_t calculated_crc_pressure = 0;
        uint8_t calculated_crc_temperature = 0;

        for (int i = 0; i < 2; i++) {
            calculated_crc_pressure ^= buffer[i];
        }

        for (int i = 3; i < 5; i++) {
            calculated_crc_temperature ^= buffer[i];
        }

        if (crc_pressure != calculated_crc_pressure || crc_temperature != calculated_crc_temperature) {
            fprintf(stderr, "CRC validation failed\n");
            break;
        }

        // Convert raw values to pressure and temperature
        uint16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        uint16_t raw_temperature = (buffer[3] << 8) | buffer[4];
        uint16_t scale_factor = (buffer[6] << 8) | buffer[7];

        pressure = (float)raw_pressure / scale_factor - 1000.0;
        temperature = (float)raw_temperature / 200.0 - 45.0;

        // Write pressure and temperature to file
        if (fwrite(&pressure, sizeof(float), 1, file) != 1 || fwrite(&temperature, sizeof(float), 1, file) != 1) {
            fprintf(stderr, "Failed to write to file\n");
            break;
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    fclose(file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

