#define CONV_TIME 45
#define SCALE_FACTOR 60.0
#define LOG_FILE "pressure_log.txt"

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int i2c_write(int handle, unsigned char *data, int length) {
