        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

double convert_pressure(unsigned char *data) {
    int raw_pressure = (data[0] << 8) | data[1];
    return raw_pressure * SCALE_FACTOR;
}

