    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", gpiotxt(handle));
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    unsigned char cmd[2] = {CMD_CONT_MEAS >> 8, CMD_CONT_MEAS & 0xFF};
    unsigned char data[9];

