        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %.2f Pa\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, pressure);

