code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5D
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

int main() {
    FILE *log_file;
    int32_t pressure;
    int16_t temperature;
    char timestamp[20];
    struct tm *tm_info;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if ((log_file = fopen("environmental_data.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        int who_am_i;
        int ctrl_reg1;

        // Read WHO_AM_I register
        if (i2cReadDevice(I2C_BUS, I2C_ADDR, WHO_AM_I, 1, &who_am_i) < 0) {
            fprintf(stderr, "Failed to read WHO_AM_I register at %s\n", asctime(localtime_r(&time(NULL), &tm_info)));
            continue;
        }

        if (who_am_i != 0xB1) {
            fprintf(stderr, "WHO_AM_I register does not match expected value (0xB1).\n");
            continue;
        }

        // Configure CTRL_REG1
        ctrl_reg1 = 0xB0;
        if (i2cWriteDevice(I2C_BUS, I2C_ADDR, CTRL_REG1, 1, &ctrl_reg1) < 0) {
            fprintf(stderr, "Failed to write CTRL_REG1 at %s\n", asctime(localtime_r(&time(NULL), &tm_info)));
            continue;
        }

        // Read pressure
        if (i2cReadDevice(I2C_BUS, I2C_ADDR, PRESS_OUT_XL, 3, (char*)&pressure) < 0) {
            fprintf(stderr, "Failed to read pressure at %s\n", asctime(localtime_r(&time(NULL), &tm_info)));
            continue;
        }

        pressure = (pressure << 16) | ((uint32_t)(((char*)&pressure)[1]) << 8) | ((uint32_t)(((char*)&pressure)[2]));
        double pressure_hpa = (double)pressure / 4096.0;

        // Read temperature
        if (i2cReadDevice(I2C_BUS, I2C_ADDR, TEMP_OUT_L, 2, (char*)&temperature) < 0) {
            fprintf(stderr, "Failed to read temperature at %s\n", asctime(localtime_r(&time(NULL), &tm_info)));
            continue;
        }

        temperature = (temperature << 8) | ((uint16_t)(((char*)&temperature)[1]));
        double temperature_celsius = 42.5 + (double)temperature / 480.0;

        // Log the data
        time_t rawtime;
        time(&rawtime);
        tm_info = localtime_r(&rawtime, &tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", timestamp);
        fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure_hpa, temperature_celsius);
        fflush(log_file);

        // Delay for 1 second
        gpioDelay(1000000);
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

