#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 10
#define GPIO_LED 17
#define THRESHOLD 28.0

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    int buffer[BUFFER_SIZE];
    int buffer_index = 0;
    double sum = 0.0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        int temp_raw = i2cReadWordData(I2C_BUS, I2C_ADDR, TEMP_REG);
        if (temp_raw < 0) {
            continue;
        }

        int temp_swapped = ((temp_raw & 0xFF) << 8) | ((temp_raw & 0xFF00) >> 8);
        double temp_celsius = ((double)temp_swapped >> 7) / 2.0;

        sum -= buffer[buffer_index];
        buffer[buffer_index] = temp_celsius;
        sum += temp_celsius;

        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        double average = sum / BUFFER_SIZE;

        if (average > THRESHOLD) {
            gpioWrite(GPIO_LED, 1);
        } else {
            gpioWrite(GPIO_LED, 0);
        }

        sleep(1);
    }

    gpioWrite(GPIO_LED, 0);
    i2cClose(I2C_BUS);
    gpioTerminate();

    return 0;
}

