This C program initializes the pigpio library, opens the I2C bus, and sets up an LED on GPIO 17. It reads the temperature from the STLM75 sensor, processes the raw data, and maintains a running average in a circular buffer. The LED is turned on when the average temperature exceeds 28.0 °C and turned off otherwise. The program handles SIGINT and SIGTERM signals to ensure a clean shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x61
#define MEAS_INTERVAL 2000 // 2 seconds
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Function to calculate CRC-8 checksum
uint8_t calculate_crc8(uint8_t *data, uint8_t length) {
    uint8_t crc = CRC_INIT;
    for (uint8_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(int i2c_handle) {
    uint8_t command = 0x0300;
    uint8_t crc = calculate_crc8(&command, 2);
    uint8_t write_buffer[4] = {command, crc, 0, 0};

    if (i2cWriteDevice(i2c_handle, I2C_ADDR, write_buffer, 4) < 0) {
        fprintf(stderr, "Failed to write to sensor.\n");
        return -1;
    }

    uint8_t read_buffer[18];
    if (i2cReadDevice(i2c_handle, I2C_ADDR, read_buffer, 18) < 0) {
        fprintf(stderr, "Failed to read from sensor.\n");
        return -1;
    }

    // Verify CRC
    uint8_t received_crc = read_buffer[16];
    uint8_t calculated_crc = calculate_crc8(read_buffer, 16);
    if (received_crc != calculated_crc) {
        fprintf(stderr, "CRC mismatch detected.\n");
        return -1;
    }

    // Log data
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(stdout, "%s,%.2f,%.2f,%.2f\n", buffer, 
            (read_buffer[0] << 8) | read_buffer[1], 
            (read_buffer[2] << 8) | read_buffer[3], 
            (read_buffer[4] << 8) | read_buffer[5]);

    fflush(stdout);

    return 0;
}

void handle_signal(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        if (read_sensor_data(i2c_handle) < 0) {
            continue; // Handle error and continue
        }

        usleep(MEAS_INTERVAL * 1000); // Sleep for 2 seconds
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

