#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x21
#define CMD_START 0x36
#define CMD_CONTINUOUS 0x2F
#define NUM_BYTES 9
#define DEFAULT_INTERVAL 1000

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int read_sensor(int interval) {
    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%x\n", I2C_BUS, I2C_ADDR);
        return -1;
    }

    uint8_t cmd[2] = {CMD_START, CMD_CONTINUOUS};
    if (i2c_write_device(i2c_fd, cmd, 2) != 2) {
        fprintf(stderr, "Failed to send command to sensor\n");
        i2c_close(i2c_fd);
        return -1;
    }

    uint8_t data[NUM_BYTES];
    while (!stop_flag) {
        if (i2c_read_device(i2c_fd, data, NUM_BYTES) != NUM_BYTES) {
            fprintf(stderr, "Failed to read data from sensor\n");
            i2c_close(i2c_fd);
            return -1;
        }

        // Verify CRC-8 checksums
        uint8_t pressure_crc = data[2];
        uint8_t temp_crc = data[5];
        uint8_t scale_factor_crc = data[8];

        uint16_t pressure = (data[0] << 8) | data[1];
        uint16_t temperature = (data[3] << 8) | data[4];
        uint16_t scale_factor = (data[6] << 8) | data[7];

        if (pressure_crc != (pressure >> 8) || temp_crc != (temperature >> 8) || scale_factor_crc != (scale_factor >> 8)) {
            fprintf(stderr, "CRC check failed for sensor data\n");
            i2c_close(i2c_fd);
            return -1;
        }

        double pressure_pa = (double)pressure / scale_factor;
        printf("Timestamp: %ld, Pressure: %.2f Pa, Temperature: %d, Scale Factor: %d\n", time(NULL), pressure_pa, temperature, scale_factor);

        usleep(interval * 1000);
    }

    i2c_close(i2c_fd);
    return 0;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int interval = DEFAULT_INTERVAL;
    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid interval value: %s\n", argv[1]);
            return 1;
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (read_sensor(interval) < 0) {
        return 1;
    }

    gpioTerminate();
    return 0;
}

