#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define SDP810_ADDR 0x25
#define CMD_CONT_MEAS 0x3615
#define DATA_LEN 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

void handle_sigint(int signum) {
    printf("\nReceived SIGINT, shutting down...\n");
    close(I2C_HANDLE);
    gpioTerminate();
    exit(0);
}

void handle_sigterm(int signum) {
    printf("\nReceived SIGTERM, shutting down...\n");
    close(I2C_HANDLE);
    gpioTerminate();
    exit(0);
}

int check_crc(unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc & 0xFF) == 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    int I2C_HANDLE = i2cOpen(1, SDP810_ADDR, 0);
    if (I2C_HANDLE < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (1) {
        unsigned char cmd[2] = {CMD_CONT_MEAS >> 8, CMD_CONT_MEAS & 0xFF};
        if (i2cWriteDevice(I2C_HANDLE, cmd, 2) != 2) {
            fprintf(stderr, "Failed to write command to sensor.\n");
            close(I2C_HANDLE);
            gpioTerminate();
            return 1;
        }

        usleep(45000); // Wait at least 45 ms for conversion

        unsigned char data[DATA_LEN];
        if (i2cReadDevice(I2C_HANDLE, data, DATA_LEN) != DATA_LEN) {
            fprintf(stderr, "Failed to read data from sensor.\n");
            close(I2C_HANDLE);
            gpioTerminate();
            return 1;
        }

        if (!check_crc(data, 3)) {
            fprintf(stderr, "CRC check failed for pressure data.\n");
            continue;
        }

        if (!check_crc(data + 3, 3)) {
            fprintf(stderr, "CRC check failed for temperature data.\n");
            continue;
        }

        int16_t raw_pressure = (data[0] << 8) | data[1];
        int16_t raw_temperature = (data[4] << 8) | data[5];
        int16_t scale_factor_pressure = (data[2] << 8) | data[3];
        int16_t scale_factor_temperature = (data[6] << 8) | data[7];

        float pressure = (float)raw_pressure / scale_factor_pressure;
        float temperature = (float)raw_temperature / 200.0;

        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);

        usleep(1000000); // Wait 1 second before next reading
    }

    close(I2C_HANDLE);
    gpioTerminate();
    return 0;
}

