This C program initializes the pigpio library, opens the I2C bus, and sets up signal handlers for SIGINT and SIGTERM. It then enters a loop where it sends the continuous-measurement command to the SDP810 sensor, waits for the conversion, reads the data, checks the CRC-8 for both pressure and temperature data, and logs the converted values to stdout every second. On any error path, it logs an error message and gracefully shuts down by closing the I2C handle and calling `gpioTerminate()`.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMIDITY_REG 0x04
#define READ_DELAY 20000 // 20 ms delay

void handle_signal(int signum) {
    printf("\nReceived signal %d, exiting...\n", signum);
    close(i2c_fd);
    exit(signum);
}

int main() {
    int i2c_fd;
    char i2c_file[20];
    char buffer[4];
    int ret;
    double temperature, humidity;

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    snprintf(i2c_file, sizeof(i2c_file), "/dev/i2c-%d", 1);
    i2c_fd = open(i2c_file, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Configure sensor
    uint8_t config_reg = 0x00;
    config_reg |= (1 << 12); // Enable combined measurement at 14-bit resolution
    ret = write(i2c_fd, &config_reg, 1);
    if (ret != 1) {
        perror("Failed to write to configuration register");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Write to temperature register
        ret = write(i2c_fd, &TEMP_REG, 1);
        if (ret != 1) {
            fprintf(stderr, "Failed to write to temperature register\n");
            continue;
        }

        // Wait for conversion
        usleep(READ_DELAY);

        // Read 4 bytes (2 bytes temperature, 2 bytes humidity)
        ret = read(i2c_fd, buffer, 4);
        if (ret != 4) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }

        // Convert raw values
        uint16_t temp_raw = (buffer[0] << 8) | buffer[1];
        uint16_t humid_raw = (buffer[2] << 8) | buffer[3];

        temperature = (double)temp_raw / 65536.0 * 165.0 - 40.0;
        humidity = (double)humid_raw / 65536.0 * 100.0;

        // Print readings
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C file descriptor
    close(i2c_fd);

    return 0;
}

