#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_ADDR 0x40
#define I2C_BUS 1
#define I2C_TIMEOUT 1000
#define PERIOD 5000 // 5 seconds

void handle_sigint(int signum) {
    printf("\nReceived SIGINT, cleaning up resources...\n");
    gpioTerminate();
    exit(0);
}

void handle_sigterm(int signum) {
    printf("\nReceived SIGTERM, cleaning up resources...\n");
    gpioTerminate();
    exit(0);
}

int read_temperature() {
    uint8_t data[2];
    int result;

    // Start I2C communication
    if (i2cOpen(I2C_BUS, SENSOR_ADDR, I2C_TIMEOUT) < 0) {
        printf("Failed to open I2C bus %d for sensor at address 0x%02X\n", I2C_BUS, SENSOR_ADDR);
        return -1;
    }

    // Send command to read temperature
    if (i2cWriteDevice(I2C_BUS, SENSOR_ADDR, "0x2E", 1) < 0) {
        printf("Failed to write command to sensor\n");
        i2cClose(I2C_BUS, SENSOR_ADDR);
        return -1;
    }

    // Read temperature data
    if (i2cReadDevice(I2C_BUS, SENSOR_ADDR, data, 2) < 0) {
        printf("Failed to read temperature data from sensor\n");
        i2cClose(I2C_BUS, SENSOR_ADDR);
        return -1;
    }

    // Close I2C communication
    i2cClose(I2C_BUS, SENSOR_ADDR);

    // Calculate temperature
    int16_t temperature = ((data[0] << 8) | data[1]) >> 4;

    return temperature;
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, handle_sigint);
