#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63
#define CALIBRATION_CMD 0x50
#define MEASUREMENT_CMD 0x40
#define TEMP_OFFSET 2
#define PRESSURE_OFFSET 6
#define TEMP_MSB 0
#define TEMP_LSB 1
#define PRESSURE_MSB 2
#define PRESSURE_LSB 3
#define PRESSURE_MID 4
#define PRESSURE_LOW 5

// Scaling factors
double scale_factor_lut = 0.0;
double scale_factor_h = 0.0;
double scale_factor_p = 0.0;

// Calibration coefficients
uint8_t calibration_data[8];

void handle_signal(int signum) {
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) >= 0) {
        i2cClose(I2C_BUS, I2C_ADDR);
    }
    gpioTerminate();
    exit(signum);
}

void read_calibration() {
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        exit(1);
    }

    int result = i2cWriteReg(i2c_handle, CALIBRATION_CMD, calibration_data, 8);
    if (result < 0) {
        fprintf(stderr, "Failed to write calibration command\n");
        i2cClose(I2C_BUS, I2C_ADDR);
        exit(1);
    }

    result = i2cReadReg(i2c_handle, CALIBRATION_CMD, calibration_data, 8);
    if (result < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(I2C_BUS, I2C_ADDR);
        exit(1);
    }

    scale_factor_lut = (double)calibration_data[0] / 256.0;
    scale_factor_h = (double)calibration_data[1] / 256.0;
    scale_factor_p = (double)calibration_data[2] / 256.0;

    i2cClose(I2C_BUS, I2C_ADDR);
}

void read_measurement() {
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        exit(1);
    }

    int result = i2cWriteReg(i2c_handle, MEASUREMENT_CMD, NULL, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to write measurement command\n");
        i2cClose(I2C_BUS, I2C_ADDR);
        exit(1);
    }

    uint8_t data[6];
    result = i2cReadReg(i2c_handle, MEASUREMENT_CMD, data, 6);
    if (result < 0) {
        fprintf(stderr, "Failed to read measurement data\n");
        i2cClose(I2C_BUS, I2C_ADDR);
        exit(1);
    }

    if (data[TEMP_MSB] == 0xFF && data[TEMP_LSB] == 0xFF &&
        data[PRESSURE_MSB] == 0xFF && data[PRESSURE_LSB] == 0xFF &&
        data[PRESSURE_MID] == 0xFF && data[PRESSURE_LOW] == 0xFF) {
        fprintf(stderr, "Sensor absent condition detected\n");
        i2cClose(I2C_BUS, I2C_ADDR);
        exit(1);
    }

    double temperature = (double)((data[TEMP_MSB] << 8) | data[TEMP_LSB]) * scale_factor_h;
    double pressure = (double)((data[PRESSURE_MSB] << 24) | (data[PRESSURE_LSB] << 16) | (data[PRESSURE_MID] << 8) | data[PRESSURE_LOW]) * scale_factor_p;

    time_t rawtime;
    struct tm * timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    printf("%04d-%02d-%02dT%02d:%02d:%02d - Temperature: %.2f C, Pressure: %.2f Pa\n",
           timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
           timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
           temperature, pressure);

    i2cClose(I2C_BUS, I2C_ADDR);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    read_calibration();

    while (1) {
        read_measurement();
        sleep(5);
    }

    return 0;
}

