#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>

#include <linux/i2c-dev.h>

#define I2C_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define PRESSURE_REG_MSB 0xAA
#define PRESSURE_REG_LSB 0xAB
#define SCALE_FACTOR 0.1

static volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int read_pressure() {
    int fd;
    char cmd[32];
    char data[2];
    int raw_pressure = 0;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access/talk to slave");
        close(fd);
        return -1;
    }

    sprintf(cmd, "0x%02X", PRESSURE_REG_MSB);
    if (write(fd, cmd, 2) != 2) {
        perror("Failed to write to sensor");
        close(fd);
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Failed to read from sensor");
        close(fd);
        return -1;
    }

    raw_pressure = (data[0] << 8) | data[1];

    close(fd);
    return raw_pressure;
}

int main() {
    struct sigaction sa;
    int pressure;
    time_t now;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!stop_flag) {
        pressure = read_pressure();
        if (pressure >= 0) {
            now = time(NULL);
            printf("%ld: Pressure = %.2f kPa\n", now, pressure * SCALE_FACTOR);
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }
        sleep(1);
    }

    return 0;
}

