#define SDP_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define WAIT_TIME 45
#define DATA_BYTES 9
#define PRESSURE_SCALE 60.0
#define TEMP_SCALE 200.0
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

int i2c_fd;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

unsigned char crc8(unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP_ADDR) < 0) {
        perror("Failed to acquire bus access/talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    unsigned char cmd[2] = {CMD_CONT_MEAS >> 8, CMD_CONT_MEAS & 0xFF};
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Failed to send command");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    usleep(WAIT_TIME * 1000);

    unsigned char data[DATA_BYTES];
    if (read(i2c_fd, data, DATA_BYTES) != DATA_BYTES) {
        perror("Failed to read data");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    unsigned short pressure_raw = (data[0] << 8) | data[1];
    unsigned short temp_raw = (data[2] << 8) | data[3];
    unsigned char pressure_crc = data[4];
    unsigned char temp_crc = data[5];
    unsigned char sensor_crc = data[6];

    if (crc8(data, 4) != pressure_crc || crc8(data + 4, 4) != temp_crc || crc8(data, 7) != sensor_crc) {
        fprintf(stderr, "CRC validation failed\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    double pressure = pressure_raw / PRESSURE_SCALE;
    double temperature = temp_raw / TEMP_SCALE;

    time_t rawtime;
    struct tm * timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    FILE *log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %.2f Pa, %.2f C\n",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
            pressure, temperature);

    fclose(log_file);
    close(i2c_fd);

    return 0;
}

