#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define SDP800_I2C_ADDR 0x25
#define SDP800_CMD_CONT_MEAS 0x36
#define SDP800_CMD_CONT_MEAS_DATA 0x2F
#define SDP800_DATA_LEN 3
#define SDP800_CRC_POLYNOMIAL 0x31
#define SDP800_CRC_INIT 0xFF
#define SDP800_PRESSURE_SCALE 60.0

int main() {
    int file_fd;
    char filename[] = "airflow_log.csv";
    char header[] = "Timestamp,Pressure\n";
    char buffer[SDP800_DATA_LEN];
    unsigned char crc;
    unsigned char data_crc;
    int raw_pressure;
    double pressure;
    struct tm *time_info;
    char timestamp[20];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (access(filename, F_OK) == 0) {
        file_fd = open(filename, O_APPEND | O_WRONLY | O_CREAT, 0644);
    } else {
        file_fd = open(filename, O_WRONLY | O_CREAT, 0644);
        if (write(file_fd, header, strlen(header)) < 0) {
            perror("Failed to write header to file");
            close(file_fd);
            return 1;
        }
    }

    while (1) {
        if (i2cWriteDevice(1, SDP800_I2C_ADDR, &SDP800_CMD_CONT_MEAS, 1) < 0) {
            perror("Failed to write command to SDP800");
            close(file_fd);
            gpioTerminate();
            return 1;
        }

        usleep(8000); // Wait for at least 8 ms

        if (i2cReadDevice(1, SDP800_I2C_ADDR, buffer, SDP800_DATA_LEN) < 0) {
            perror("Failed to read data from SDP800");
            close(file_fd);
            gpioTerminate();
            return 1;
        }

        data_crc = buffer[2];
        crc = 0xFF;
        for (int i = 0; i < 2; i++) {
            crc ^= buffer[i];
            for (int j = 0; j < 8; j++) {
                if (crc & 0x80) {
                    crc = (crc << 1) ^ SDP800_CRC_POLYNOMIAL;
                } else {
                    crc <<= 1;
                }
            }
        }

        if (crc != data_crc) {
            fprintf(stderr, "CRC check failed.\n");
            continue;
        }

        raw_pressure = (buffer[0] << 8) | buffer[1];
        pressure = (double)raw_pressure / SDP800_PRESSURE_SCALE;

        time_info = localtime(&time(NULL));
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        char line[50];
        snprintf(line, sizeof(line), "%s,%f\n", timestamp, pressure);
        if (write(file_fd, line, strlen(line)) < 0) {
            perror("Failed to write to file");
            close(file_fd);
            gpioTerminate();
            return 1;
        }

        fflush(stdout);
        usleep(1000000 - (time(NULL) % 1000)); // Sleep for the remainder of the second
    }

    close(file_fd);
    gpioTerminate();
    return 0;
}

