#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define PRESSURE_REG 0x00
#define SCALE_FACTOR 0.01
#define SAFE_MIN_PRESSURE 200
#define SAFE_MAX_PRESSURE 250
#define LOG_FILE "pressure_log.csv"

void handle_signal(int signum) {
    if (i2cHandle != -1) {
        i2cClose(i2cHandle);
    }
    if (logFile != NULL) {
        fclose(logFile);
    }
    gpioTerminate();
    exit(signum);
}

int main() {
    int i2cHandle = -1;
    FILE *logFile = NULL;
    unsigned int pressure;
    char timestamp[20];
    struct tm *timeinfo;
    time_t rawtime;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Open I2C bus
    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Check if file is newly created
    if (fseek(logFile, 0, SEEK_END) == 0 && ftell(logFile) == 0) {
        fprintf(logFile, "timestamp,pressure_kPa\n");
    }

    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        int retries = 0;
        int read_success = 0;

        while (!read_success && retries < 2) {
            if (i2cReadI2CBlockData(i2cHandle, PRESSURE_REG, 2, (unsigned char *)&pressure) < 0) {
                if (retries < 1) {
                    fprintf(stderr, "Failed to read pressure data. Retrying...\n");
                    i2cClose(i2cHandle);
                    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
                    if (i2cHandle < 0) {
                        fprintf(stderr, "Failed to reopen I2C bus.\n");
                        break;
                    }
                } else {
                    fprintf(stderr, "Failed to read pressure data after retries.\n");
                    break;
                }
            } else {
                read_success = 1;
            }
            retries++;
        }

        if (read_success) {
            // Convert raw value to kPa
            double pressure_kPa = (double)pressure * SCALE_FACTOR;

            // Log the reading
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
            fprintf(logFile, "%s,%f\n", timestamp, pressure_kPa);
            fflush(logFile);

            // Check if pressure is out of safe range
            if (pressure_kPa < SAFE_MIN_PRESSURE || pressure_kPa > SAFE_MAX_PRESSURE) {
                fprintf(stderr, "Warning: Pressure %f kPa is out of safe range (%d-%d kPa).\n", pressure_kPa, SAFE_MIN_PRESSURE, SAFE_MAX_PRESSURE);
            }
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(logFile);
    i2cClose(i2cHandle);
    gpioTerminate();

    return 0;
}

