This C program initializes the pigpio library, opens the I2C bus, and reads the pressure data from the MLX90821 sensor every second. It logs the readings to a CSV file with a UTC timestamp and checks if the pressure is within the safe range. The program handles errors and retries I2C reads, and it gracefully handles SIGINT and SIGTERM signals to ensure proper cleanup.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x27
#define TEMP_OFFSET -40.0
#define TEMP_SCALE 165.0 / 16383.0
#define HUMIDITY_SCALE 100.0 / 16383.0
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1024 * 1024 // 1 MB

void handle_signal(int signum) {
    if (pi != 0) {
        i2cUnexport(I2C_BUS);
        gpioTerminate();
    }
    exit(signum);
}

void log_reading(double temperature, double humidity, time_t timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    struct tm *time_info = localtime(&timestamp);
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", time_info);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp_str, temperature, humidity);

    if (fseek(log_file, 0, SEEK_SET) == 0) {
        fseek(log_file, 0, SEEK_END);
        if (ftell(log_file) > MAX_LOG_SIZE) {
            ftruncate(fileno(log_file), MAX_LOG_SIZE);
        }
    }

    fclose(log_file);
}

int main() {
    int pi = 0;
    int status;
    unsigned char buffer[4];
    double temperature, humidity;
    time_t timestamp;

    signal(SIGINT, handle_signal);

    if ((pi = pigpio_start()) < 0) {
        fprintf(stderr, "pigpio_start failed (%d)\n", pi);
        return 1;
    }

    if ((status = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "i2cOpen failed (%d)\n", status);
        goto cleanup;
    }

    while (1) {
        if (i2cWriteDevice(I2C_ADDR, "\0", 1) < 0) {
            fprintf(stderr, "i2cWriteDevice failed\n");
            goto cleanup;
        }

        usleep(40000); // Wait 40 ms

        if (i2cReadDevice(I2C_ADDR, buffer, 4) != 4) {
            fprintf(stderr, "i2cReadDevice failed\n");
            goto cleanup;
        }

        if ((buffer[0] & 0x80) == 0) {
            fprintf(stderr, "Sensor not ready\n");
            continue;
        }

        if ((buffer[0] & 0x40) != 0) {
            fprintf(stderr, "Bus error\n");
            goto cleanup;
        }

        temperature = ((double)buffer[1] << 8 | buffer[2]) * TEMP_SCALE + TEMP_OFFSET;
        humidity = ((double)buffer[3] << 8 | buffer[2]) * HUMIDITY_SCALE;

        timestamp = time(NULL);
        log_reading(temperature, humidity, timestamp);

        sleep(5); // Sample every 5 seconds
    }

cleanup:
