#define TEMP_OFFSET -40.0
#define TEMP_SCALE 165.0 / 16383.0
#define HUMIDITY_SCALE 100.0 / 16383.0
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1024 * 1024 // 1 MB

