#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define TICK_TIME 3
#define SYNC_TICKS 56
#define NIBBLE_TICKS 12
#define MAX_NIBBLE_TICKS 271
#define CHECKSUM_TICKS 12
#define SCALE 0.001
#define OFFSET -100

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int read_nibble(void) {
    int ticks = 0;
    while (ticks < MAX_NIBBLE_TICKS) {
        if (digitalRead(GPIO_PIN) == 1) {
            ticks += TICK_TIME;
        } else {
            break;
        }
    }
    if (ticks < NIBBLE_TICKS || ticks > MAX_NIBBLE_TICKS) {
        fprintf(stderr, "Bus error: Invalid nibble pulse width\n");
        return -1;
    }
    return ticks / TICK_TIME;
}

int read_pressure(void) {
    int sync_ticks = 0;
    int status_nibble = 0;
    int data_nibbles[3] = {0};
    int checksum_nibble = 0;
    int checksum = 0;
    int raw_value = 0;
    int pressure = 0;

    // Read synchronization pulse
    for (int i = 0; i < SYNC_TICKS; i++) {
        if (digitalRead(GPIO_PIN) == 0) {
            sync_ticks += TICK_TIME;
        } else {
            break;
        }
    }
    if (sync_ticks != SYNC_TICKS * TICK_TIME) {
        fprintf(stderr, "Sensor absent: Timeout on synchronization pulse\n");
        return -1;
    }

    // Read status nibble
    status_nibble = read_nibble();
    if (status_nibble < 0) {
        return -1;
    }

    // Read data nibbles
    for (int i = 0; i < 3; i++) {
        data_nibbles[i] = read_nibble();
        if (data_nibbles[i] < 0) {
            return -1;
        }
    }

    // Read checksum nibble
    checksum_nibble = read_nibble();
    if (checksum_nibble < 0) {
        return -1;
    }

    // Calculate checksum
    checksum = (status_nibble + data_nibbles[0] + data_nibbles[1] + data_nibbles[2]) % 16;
    if (checksum != checksum_nibble) {
        fprintf(stderr, "Bus error: Invalid checksum\n");
        return -1;
    }

    // Convert raw value to pressure
    raw_value = (data_nibbles[0] << 4) | data_nibbles[1];
    pressure = raw_value * SCALE + OFFSET;

    return pressure;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_OFF);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("pressure_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (!stop) {
        int pressure = read_pressure();
        if (pressure >= 0) {
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f Pa\n",
                    timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                    timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, pressure);
        }
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

