#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x00

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int read_temperature(int handle) {
    uint8_t buffer[2];
    int result = i2c_read_device(handle, TEMP_REG, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature from TMP117\n");
        return -1;
    }

    int16_t temp = (buffer[0] | (buffer[1] << 8));
    float temperature = (float)temp * 0.0078125;
    return temperature;
}

int verify_device_id(int handle) {
    uint8_t buffer[2];
    int result = i2c_read_device(handle, DEVICE_ID_REG, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read device ID from TMP117\n");
        return -1;
    }

    uint16_t device_id = (buffer[0] | (buffer[1] << 8));
    if (device_id != 0x0117) {
        fprintf(stderr, "Invalid device ID: expected 0x0117, got 0x%04X\n", device_id);
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (verify_device_id(handle) < 0) {
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    FILE *file = fopen("greenhouse_temps.dat", "ab");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        float temperature = read_temperature(handle);
        if (temperature >= 0) {
            float *temp_ptr = (float *)&temperature;
            fwrite(temp_ptr, sizeof(float), 1, file);
        }
        sleep(60);
    }

    fclose(file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

