#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define MEASUREMENT_CMD 0xFD
#define TEMP_HUM_DATA_LEN 6
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    pigpio_stop();
    fclose(log_file);
    exit(0);
}

unsigned char calculate_crc8(const unsigned char *data, size_t len) {
    unsigned char crc = CRC_INIT_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    FILE *log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        pigpio_stop();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        fclose(log_file);
        pigpio_stop();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        unsigned char cmd[1] = {MEASUREMENT_CMD};
        if (i2cWriteDevice(i2c_handle, cmd, 1) != 1) {
            fprintf(stderr, "Failed to write measurement command to I2C bus.\n");
            handle_sigint(0);
        }

        unsigned char data[TEMP_HUM_DATA_LEN];
        if (i2cReadDevice(i2c_handle, data, TEMP_HUM_DATA_LEN) != TEMP_HUM_DATA_LEN) {
            fprintf(stderr, "Failed to read data from I2C bus.\n");
            handle_sigint(0);
        }

        unsigned char crc_temp = calculate_crc8(data, 2);
        unsigned char crc_hum = calculate_crc8(data + 2, 2);

        if (crc_temp != data[2] || crc_hum != data[4]) {
            fprintf(stderr, "CRC validation failed.\n");
            handle_sigint(0);
        }

        double raw_temp = (data[0] << 8) | data[1];
        double raw_hum = (data[3] << 8) | data[4];

        double temp = -45 + 175 * (raw_temp / 65535.0);
        double humidity = -6 + 125 * (raw_hum / 65535.0);

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s: Temperature = %.2f °C, Humidity = %.2f %%RH\n", timestamp, temp, humidity);
        fflush(log_file);

        sleep(5);
    }

    handle_sigint(0);
    return 0;
}

