#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SHTC3_ADDR 0x70
#define SHTC3_MEASUREMENT_CMD 0x7866
#define SHTC3_DATA_LEN 6
#define SHTC3_TEMP_MSB 0
#define SHTC3_TEMP_LSB 1
#define SHTC3_TEMP_CRC 2
#define SHTC3_HUMIDITY_MSB 3
#define SHTC3_HUMIDITY_LSB 4
#define SHTC3_HUMIDITY_CRC 5
#define SHTC3_CRC_POLY 0x31
#define SHTC3_CRC_INIT 0xFF

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int crc8(uint8_t *data, int len) {
    uint8_t crc = SHTC3_CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHTC3_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

double convert_temp(uint16_t raw) {
    return 175.0 * raw / 65535.0 - 45.0;
}

double convert_humidity(uint16_t raw) {
    return 100.0 * raw / 65535.0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    FILE *log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, SHTC3_ADDR, 0);
    if (i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        fclose(log_file);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        uint8_t data[SHTC3_DATA_LEN];
        int result = i2cWriteReg(i2c_handle, 0, SHTC3_MEASUREMENT_CMD, 2);
        if (result != 2) {
            fprintf(stderr, "Failed to write measurement command to I2C.\n");
            continue;
        }

        usleep(12400); // Wait at least 12.4 ms for conversion

        result = i2cReadReg(i2c_handle, 0, data, SHTC3_DATA_LEN);
        if (result != SHTC3_DATA_LEN) {
            fprintf(stderr, "Failed to read data from I2C.\n");
            continue;
        }

        uint16_t temp_raw = (data[SHTC3_TEMP_MSB] << 8) | data[SHTC3_TEMP_LSB];
        uint16_t humidity_raw = (data[SHTC3_HUMIDITY_MSB] << 8) | data[SHTC3_HUMIDITY_LSB];

        if (crc8(data, SHTC3_DATA_LEN - 1) != data[SHTC3_TEMP_CRC] ||
            crc8(data + 3, SHTC3_DATA_LEN - 3) != data[SHTC3_HUMIDITY_CRC]) {
            fprintf(stderr, "CRC check failed.\n");
            continue;
        }

        double temp = convert_temp(temp_raw);
        double humidity = convert_humidity(humidity_raw);

        if (temp < -40.0 || temp > 125.0 || humidity < 0.0 || humidity > 100.0) {
            fprintf(stderr, "Out-of-range value detected.\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(stdout, "%04d-%02d-%02d %02d:%02d:%02d,%.2fC,%.2f%%\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, temp, humidity);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2fC,%.2f%%\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, temp, humidity);

        fflush(log_file);

        sleep(5); // Wait 5 seconds before next reading
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

