code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define FILE_NAME "mag_temp_log.csv"

void handle_sigint(int signum) {
    if (pi != 0) {
        piStop();
    }
    if (file != NULL) {
        fclose(file);
    }
    exit(0);
}

int main() {
    int pi = 0;
    int handle = -1;
    FILE *file = NULL;
    int raw_value = 0;
    double field_gauss = 0.0;
    double temp_celsius = 0.0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    if ((handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        piStop();
        return 1;
    }

    // Open log file
    if ((file = fopen(FILE_NAME, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(handle);
        piStop();
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Write header if file is newly created
    if (fseek(file, 0, SEEK_END) == 0 && ftell(file) == 0) {
        fprintf(file, "Field Gauss,Temperature Celsius\n");
    }

    while (1) {
        // Read raw value from sensor
        if (i2cReadI2CBlockData(handle, 0x00, 2, &raw_value, 2) < 0) {
            fprintf(file, "NaN,NaN\n");
            continue;
        }

        // Convert raw value to field_gauss and temp_celsius
        field_gauss = raw_value * 0.1;
        temp_celsius = raw_value * 0.01 - 25.0;

        // Log the values
        fprintf(file, "%.2f,%.2f\n", field_gauss, temp_celsius);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    if (file != NULL) {
        fclose(file);
    }
    if (handle != -1) {
        i2cClose(handle);
    }
    piStop();

    return 0;
}

