#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TMP117_ADDR 0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_RESOLUTION 0.0078125

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    int i2c_handle = -1;
    int retries = 0;
    int max_retries = 3;
    int result;
    unsigned char buffer[2];
    double temperature;
    FILE *log_file;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (retries < max_retries) {
        i2c_handle = i2cOpen(1, TMP117_ADDR, 0);
        if (i2c_handle >= 0) {
            break;
        }
        retries++;
        sleep(1);
    }

    if (retries == max_retries) {
        fprintf(stderr, "Failed to open I2C bus after %d retries\n", max_retries);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        result = i2cReadI2CBlockData(i2c_handle, TMP117_REG_TEMP, buffer, 2);
        if (result != 2) {
            fprintf(stderr, "Failed to read temperature from TMP117\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        temperature = (double)((int16_t)buffer[0] << 8 | buffer[1]) * TMP117_RESOLUTION;

        time_t rawtime;
        struct tm *timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S, Temperature: %.2f C\n", timeinfo, temperature);

        fprintf(log_file, "%s", buffer);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

