#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define DHT11_TIMEOUT 1000000 // 1 second timeout in microseconds
#define DHT11_DATA_BITS 40
#define DHT11_CHECKSUM_FAILURE -1
#define DHT11_SENSOR_ABSENT -2

static FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(signum);
}

int read_dht11_data() {
    int status = 0;
    unsigned long start_time, end_time;
    unsigned char data[5];
    int i, j, bit_count, bit_value;

    // Pull GPIO low for 18 ms
    gpioWrite(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, PI_LOW);
    usleep(18000);

    // Release GPIO
    gpioWrite(GPIO_PIN, PI_HIGH);
    usleep(40);

    // Set GPIO to input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Wait for the sensor's response
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == PI_LOW) {
        if (gpioTick() - start_time > DHT11_TIMEOUT) {
            status = DHT11_SENSOR_ABSENT;
            break;
        }
    }

    if (status == 0) {
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == PI_LOW) {
            if (gpioTick() - start_time > DHT11_TIMEOUT) {
                status = DHT11_SENSOR_ABSENT;
                break;
            }
        }

        if (status == 0) {
            start_time = gpioTick();
            while (gpioRead(GPIO_PIN) == PI_HIGH) {
                if (gpioTick() - start_time > DHT11_TIMEOUT) {
                    status = DHT11_SENSOR_ABSENT;
                    break;
                }
            }
        }
    }

    if (status == 0) {
        bit_count = 0;
        for (i = 0; i < 5; i++) {
            for (j = 0; j < 8; j++) {
                start_time = gpioTick();
                while (gpioRead(GPIO_PIN) == PI_LOW) {
                    if (gpioTick() - start_time > DHT11_TIMEOUT) {
                        status = DHT11_SENSOR_ABSENT;
                        break;
                    }
                }

                if (status == 0) {
                    start_time = gpioTick();
                    while (gpioRead(GPIO_PIN) == PI_HIGH) {
                        if (gpioTick() - start_time > DHT11_TIMEOUT) {
                            status = DHT11_SENSOR_ABSENT;
                            break;
                        }
                    }
                }

                if (status == 0) {
                    bit_value = (gpioTick() - start_time) < 70000;
                    data[i] |= bit_value << (7 - j);
                }
            }
        }

        if (status == 0) {
            int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
            if (checksum != data[4]) {
                status = DHT11_CHECKSUM_FAILURE;
            }
        }
    }

    return status;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    log_file = fopen("dht11_readings.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int status = read_dht11_data();

        if (status == 0) {
            char timestamp[20];
            time_t rawtime;
            struct tm * timeinfo;

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

            fprintf(log_file, "%s, Humidity: %d, Temperature: %d\n", timestamp, data[0], data[2]);
        } else {
            fprintf(stderr, "Error reading DHT11: %d\n", status);
        }

        sleep(2);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

