#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define MEASUREMENT_CMD 0x2C06
#define TEMP_OFFSET -45
#define TEMP_SCALE 175
#define HUMIDITY_SCALE 100
#define MAX_RETRIES 3

void handle_signal(int signum) {
    if (pi_i2c_close(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to close I2C bus %d\n", I2C_BUS);
    }
    if (fclose(stdout) != 0) {
        fprintf(stderr, "Failed to close stdout\n");
    }
    if (pi_stop() < 0) {
        fprintf(stderr, "Failed to stop pigpio\n");
    }
    exit(signum);
}

int main(int argc, char *argv[]) {
    int i2c_handle;
    FILE *log_file;
    char timestamp[20];
    double temperature, humidity;
    uint8_t buffer[6];
    uint8_t crc;
    uint8_t raw_temp[2], raw_humidity[2];
    int retry_count;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_handle = pi_i2c_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        return 1;
    }

    log_file = fopen("sht31d_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        retry_count = 0;
        while (retry_count < MAX_RETRIES) {
            if (pi_i2c_write(i2c_handle, &MEASUREMENT_CMD, 2) < 0) {
                fprintf(stderr, "Failed to write measurement command to I2C bus %d\n", I2C_BUS);
                retry_count++;
                sleep(1);
                continue;
            }

            if (pi_i2c_read(i2c_handle, buffer, 6) < 0) {
                fprintf(stderr, "Failed to read from I2C bus %d\n", I2C_BUS);
                retry_count++;
                sleep(1);
                continue;
            }

            raw_temp[0] = buffer[0];
            raw_temp[1] = buffer[1];
            raw_humidity[0] = buffer[2];
            raw_humidity[1] = buffer[3];
            crc = buffer[4];

            if (crc != (buffer[0] ^ buffer[1] ^ buffer[2] ^ buffer[3] ^ 0xFF)) {
                fprintf(stderr, "CRC validation failed\n");
                retry_count++;
                sleep(1);
                continue;
            }

            break;
        }

        if (retry_count == MAX_RETRIES) {
            fprintf(stderr, "Persistent sensor failure\n");
            continue;
        }

        temperature = TEMP_OFFSET + TEMP_SCALE * (double)(((raw_temp[1] << 8) | raw_temp[0]) / 65535.0);
        humidity = HUMIDITY_SCALE * (double)(((raw_humidity[1] << 8) | raw_humidity[0]) / 65535.0);

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", now_tm);

        fprintf(log_file, "%s%.2f,%.2f\n", timestamp, temperature, humidity);
        fflush(log_file);

        sleep(5);
    }

    fclose(log_file);
    pi_i2c_close(I2C_BUS);
    pi_stop();

    return 0;
}

