This C program reads temperature and humidity from an Adafruit SHT31-D sensor using the pigpio library on a Raspberry Pi Zero W. It logs the readings every 5 seconds to `sht31d_data.log` with ISO-8601 timestamps. It handles errors and retries I2C transactions up to 3 times. On persistent sensor failure, it logs the error and continues running. The program gracefully handles SIGINT and SIGTERM signals for shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65
#define DEVICE_ID_REG 0x00
#define RED_REG 0x64
#define GREEN_REG 0x66
#define BLUE_REG 0x68
#define CCT_HEADER "Timestamp,Average_CCT\n"

void handle_signal(int signum) {
    if (pi != 0) {
        piStop();
    }
    if (file != NULL) {
        fclose(file);
    }
    exit(signum);
}

double compute_cct(uint16_t red, uint16_t green, uint16_t blue) {
    double x = (red * 0.64 + green * 0.33 + blue * 0.03) / (red + green + blue);
    double y = (red * 0.30 + green * 0.60 + blue * 0.11) / (red + green + blue);
    double n = (x - 0.3320) / (0.1858 - y);
    return 449.0 * pow(n, 3) + 3525.0 * pow(n, 2) + 6823.3 * n + 5520.33;
}

int main() {
    int pi = 0;
    FILE *file = NULL;
    uint8_t buffer[3];
    uint16_t red, green, blue;
    double cct1, cct2, avg_cct;
    struct tm *timeinfo;
    char timestamp[20];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    pi = pigpio_start();
    if (pi < 0) {
        fprintf(stderr, "pigpio start failed\n");
        return 1;
    }

    file = fopen("cct_log.csv", "a+");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return 1;
    }

    if (fseek(file, 0, SEEK_END) != 0) {
        fprintf(stderr, "Failed to seek to end of file\n");
        fclose(file);
        return 1;
    }

    if (ftell(file) == 0) {
        fprintf(file, CCT_HEADER);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (i2cReadI2CBlockData(pi, I2C_BUS, SENSOR1_ADDR, DEVICE_ID_REG, 1, buffer) < 0) {
            fprintf(stderr, "Failed to read device ID from sensor 1\n");
            continue;
        }
        if (buffer[0] != 0x2A) {
            fprintf(stderr, "Invalid device ID from sensor 1\n");
            continue;
        }

        if (i2cReadI2CBlockData(pi, I2C_BUS, SENSOR1_ADDR, RED_REG, 2, buffer) < 0) {
            fprintf(stderr, "Failed to read red channel from sensor 1\n");
            continue;
        }
        red = (buffer[0] << 8) | buffer[1];

        if (i2cReadI2CBlockData(pi, I2C_BUS, SENSOR1_ADDR, GREEN_REG, 2, buffer) < 0) {
            fprintf(stderr, "Failed to read green channel from sensor 1\n");
            continue;
        }
        green = (buffer[0] << 8) | buffer[1];

        if (i2cReadI2CBlockData(pi, I2C_BUS, SENSOR1_ADDR, BLUE_REG, 2, buffer) < 0) {
            fprintf(stderr, "Failed to read blue channel from sensor 1\n");
