#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMP_REG 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define PMIN_KPA 0
#define PMAX_KPA 800

int main() {
    FILE *log_file;
    int fd;
    char buffer[4];
    unsigned short raw_pressure, raw_temp;
    double pressure_kPa, temp_C;
    struct tm *time_info;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90824_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read pressure
        if (read(fd, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read pressure register\n");
            continue;
        }
        raw_pressure = (buffer[0] << 8) | buffer[1];

        // Read temperature
        if (read(fd, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read temperature register\n");
            continue;
        }
        raw_temp = (buffer[0] << 8) | buffer[1];

        // Convert raw values
        pressure_kPa = (raw_pressure - OUTPUT_MIN) * (PMAX_KPA - PMIN_KPA) / (OUTPUT_MAX - OUTPUT_MIN);
        temp_C = raw_temp * 0.01 - 40;

        // Get current time
        time_info = localtime(&time(NULL));
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

        // Log results
        fprintf(log_file, "%s, Pressure: %.2f kPa, Temperature: %.2f C\n", timestamp, pressure_kPa, temp_C);

        // Sleep for 2 seconds
        sleep(2);
    }

    // Clean up
    fclose(log_file);
    close(fd);
    gpioTerminate();

    return 0;
}

