#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define FAN_GPIO 18
#define HYS_HIGH 28.0
#define HYS_LOW 26.0

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

double read_temperature(int handle) {
    uint8_t buffer[2];
    int result = i2c_read_device(handle, TEMP_REG, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature from sensor.\n");
        return -1.0;
    }

    int temp_value = (buffer[0] << 8) | buffer[1];
    double temperature = (double)temp_value * 0.5;
    return temperature;
}

void control_fan(int handle, double avg_temp) {
    if (avg_temp > HYS_HIGH) {
        if (gpioWrite(handle, FAN_GPIO, PI_ON) < 0) {
            fprintf(stderr, "Failed to turn on fan.\n");
        }
    } else if (avg_temp < HYS_LOW) {
        if (gpioWrite(handle, FAN_GPIO, PI_OFF) < 0) {
            fprintf(stderr, "Failed to turn off fan.\n");
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    double buffer[BUFFER_SIZE];
    int buffer_index = 0;
    double running_avg = 0.0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        double temp = read_temperature(i2c_handle);
        if (temp >= 0.0) {
            buffer[buffer_index] = temp;
            running_avg = 0.0;
            for (int i = 0; i < BUFFER_SIZE; i++) {
                running_avg += buffer[(buffer_index + i) % BUFFER_SIZE];
            }
            running_avg /= BUFFER_SIZE;
            control_fan(i2c_handle, running_avg);
            printf("Temperature: %.1f °C, Running Average: %.1f °C\n", temp, running_avg);
        }

        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        usleep(1000000); // Sleep for 1 second
    }

    control_fan(i2c_handle, 0.0); // Turn off fan on shutdown
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

