#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SDP810_I2C_ADDR 0x25
#define SDP810_CMD_CONT_MEAS 0x362F
#define SDP810_DATA_LEN 9
#define SDP810_PRESSURE_SCALE 60
#define SDP810_TEMP_SCALE 200
#define SDP810_CRC_POLY 0x31
#define SDP810_CRC_INIT 0xFF

static FILE *log_file;
static int i2c_handle;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cUnexport(i2c_handle);
    }
    gpioTerminate();
    exit(signum);
}

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = SDP810_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data() {
    uint8_t data[SDP810_DATA_LEN];
    if (i2cReadDevice(i2c_handle, SDP810_I2C_ADDR, data, SDP810_DATA_LEN) != SDP810_DATA_LEN) {
        fprintf(stderr, "Failed to read sensor data.\n");
        return -1;
    }

    int16_t pressure = (data[0] << 8) | data[1];
    int16_t temperature = (data[2] << 8) | data[3];
    uint8_t status = data[4];
    uint8_t crc = data[5];

    if (crc != crc8(data, SDP810_DATA_LEN - 1)) {
        fprintf(stderr, "CRC mismatch.\n");
        return -1;
    }

    if (status & 0x01) {
        fprintf(stderr, "Sensor absent.\n");
        return -1;
    }

    double pressure_pa = pressure * SDP810_PRESSURE_SCALE;
    double temperature_c = temperature * SDP810_TEMP_SCALE;

    if (pressure_pa > 5.0) {
        fprintf(stderr, "Warning: Pressure exceeds 5.0 Pa.\n");
    }

    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n",
            now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
            now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
            pressure_pa, temperature_c);

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (i2cOpen("/dev/i2c-1", 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        return 1;
    }

    if (i2cWriteDevice(i2c_handle, SDP810_I2C_ADDR, &SDP810_CMD_CONT_MEAS, 2) != 2) {
        fprintf(stderr, "Failed to send continuous measurement command.\n");
        return 1;
    }

    log_file = fopen("airflow.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (read_sensor_data() < 0) {
            continue;
        }
        sleep(1);
    }

    return 0;
}

