#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_PIN 17
#define HYS_BAND 1

static gpiod_chip *chip;
static gpiod_line *led_line;
static int i2c_fd;

void handle_signal(int signum) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_free(led_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    close(i2c_fd);
    exit(signum);
}

int read_temperature() {
    int16_t temp_msb, temp_lsb;
    char buffer[3];

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }

    temp_msb = (int8_t)buffer[0];
    temp_lsb = (int8_t)buffer[1];

    int16_t temp = (temp_msb << 8) | temp_lsb;
    temp >>= 4;

    return temp * 0.0625;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (!(chip = gpiod_chip_open("/dev/gpiochip0"))) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    if (!(led_line = gpiod_line_request_by_name(chip, "gpio%d", LED_PIN, "LED", 0))) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        close(i2c_fd);
        return 1;
    }

    gpiod_line_set_value(led_line, 0);

    while (1) {
        int temperature = read_temperature();
        if (temperature < 0) {
            continue;
        }

        printf("Temperature: %.2f °C\n", temperature);

        if (temperature > 28 + HYS_BAND) {
            gpiod_line_set_value(led_line, 1);
        } else if (temperature < 27 - HYS_BAND) {
            gpiod_line_set_value(led_line, 0);
        }

        sleep(1);
    }

    return 0;
}

