#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define PRESSURE_BYTES 3
#define TEMP_BYTES 3
#define SCALE_FACTOR_BYTES 3
#define TOTAL_BYTES 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

void handle_sigint(int signum) {
    if (pi != 0) {
        i2cUnexport(I2C_BUS, I2C_ADDR);
        gpioTerminate();
    }
    exit(0);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int pi = 0;
    uint8_t buffer[TOTAL_BYTES];
    int ret;

    if ((pi = pigpio_start()) < 0) {
        fprintf(stderr, "pigpio_start failed\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "i2cOpen failed\n");
        goto cleanup;
    }

    signal(SIGINT, handle_sigint);

    FILE *file = fopen("flow_data.txt", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        goto cleanup;
    }

    while (1) {
        if ((ret = i2cWriteDevice(I2C_ADDR, &CMD_CONT_MEAS, 2)) < 0) {
            fprintf(stderr, "i2cWriteDevice failed\n");
            goto cleanup;
        }

        usleep(45000); // Wait at least 45 ms

        if ((ret = i2cReadDevice(I2C_ADDR, buffer, TOTAL_BYTES)) < 0) {
            fprintf(stderr, "i2cReadDevice failed\n");
            goto cleanup;
        }

        uint8_t pressure_crc = calculate_crc8(buffer, PRESSURE_BYTES);
        uint8_t temp_crc = calculate_crc8(buffer + PRESSURE_BYTES, TEMP_BYTES);

        if (pressure_crc != buffer[PRESSURE_BYTES] || temp_crc != buffer[PRESSURE_BYTES + TEMP_BYTES]) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        int16_t pressure = (int16_t)((buffer[0] << 8) | buffer[1]) / ((int16_t)((buffer[4] << 8) | buffer[5]));
        int16_t temperature = (int16_t)((buffer[2] << 8) | buffer[3]) / 200;

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d - Pressure: %d Pa, Temperature: %d C\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
                pressure, temperature);

        fflush(file);
    }

cleanup:
    if (file) {
        fclose(file);
    }
    if (pi != 0) {
        i2cUnexport(I2C_BUS, I2C_ADDR);
        gpioTerminate();
    }
    return 0;
}

