#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define I2C_CMD_RH 0xF5
#define I2C_CMD_TEMP 0xF3
#define I2C_CMD_TEMP_FROM_RH 0xE0
#define I2C_CMD_READ_ID 0xD0

#define MAX_RETRIES 3
#define SLEEP_TIME 20
#define SAMPLE_INTERVAL 60000

void handle_signal(int signum) {
    if (pi != 0) {
        i2cUnexport(I2C_BUS);
        gpioTerminate();
    }
    exit(signum);
}

int i2c_transaction(int cmd, unsigned char *data, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(I2C_BUS, I2C_ADDR, &cmd, 1) == 1 &&
            i2cReadDevice(I2C_BUS, I2C_ADDR, data, len) == len) {
            return 0;
        }
        retries++;
        usleep(100000); // 100 ms sleep
    }
    return -1;
}

int read_sensor_id() {
    unsigned char data[2];
    if (i2c_transaction(I2C_CMD_READ_ID, data, 2) == 0) {
        return (data[0] << 8) | data[1];
    }
    return -1;
}

void read_temperature_humidity() {
    unsigned char data[2];
    if (i2c_transaction(I2C_CMD_RH, data, 2) == 0) {
        int humidity_raw = (data[0] << 8) | data[1];
        double humidity = 125.0 * humidity_raw / 65536.0 - 6.0;
        humidity = (humidity < 0) ? 0 : (humidity > 100) ? 100 : humidity;

        if (i2c_transaction(I2C_CMD_TEMP, data, 2) == 0) {
            int temperature_raw = (data[0] << 8) | data[1];
            double temperature = 175.72 * temperature_raw / 65536.0 - 46.85;

            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", now_tm);

            printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
            fflush(stdout);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return 1;
    }

    if (read_sensor_id() < 0) {
        fprintf(stderr, "Sensor not found at address 0x%02X\n", I2C_ADDR);
        return 1;
    }

    FILE *log_file = fopen("environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_temperature_humidity();
        if (log_file) {
            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
            fflush(log_file);
        }
        sleep(SAMPLE_INTERVAL / 1000);
    }

    if (log_file) {
        fclose(log_file);
    }

    i2cUnexport(I2C_BUS);
    gpioTerminate();

    return 0;
}

