code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_HUMIDITY_REG 0x00
#define TEMP_HUMIDITY_DATA_LEN 4

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    pigpio_stop();
    exit(0);
}

int main() {
    int i2c_handle = -1;
    char filename[] = "enviro_log.txt";
    FILE *log_file = NULL;

    // Initialize pigpio
    if (pigpio_start() < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2c_open(I2C_BUS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        pigpio_stop();
        return 1;
    }

    // Open log file
    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", filename);
        i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Set configuration register for 14-bit resolution
    uint8_t config_data = 0x00; // 14-bit temperature and humidity
    if (i2c_write_device(i2c_handle, I2C_ADDR, &config_data, 1) < 0) {
        fprintf(stderr, "Failed to write to configuration register\n");
        fclose(log_file);
        i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Infinite loop to read temperature and humidity
    while (1) {
        uint8_t data[TEMP_HUMIDITY_DATA_LEN];
        if (i2c_read_device(i2c_handle, I2C_ADDR, data, TEMP_HUMIDITY_DATA_LEN) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }

        // Convert raw values to temperature and humidity
