#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>

#define I2C_ADDR 0x44
#define I2C_DEV "/dev/i2c-1"
#define MEASUREMENT_CMD 0x2C
#define MEASUREMENT_DATA_LEN 3
#define CRC8_POLYNOMIAL 0x31
#define TEMP_CONVERSION_FACTOR 175.0 / 65535.0
#define TEMP_OFFSET -45.0
#define LOG_FILE "temperature_log.txt"
#define LOG_INTERVAL 5000 // 5 seconds

int i2c_fd;

void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int crc8(unsigned char *data, int len) {
    unsigned char crc = 0;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

double read_temperature() {
    unsigned char cmd[2] = {MEASUREMENT_CMD, 0xE0};
    unsigned char data[MEASUREMENT_DATA_LEN];

    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Error writing to I2C device");
        return -1.0;
    }

    usleep(10000); // Wait 10 ms for conversion

    if (read(i2c_fd, data, MEASUREMENT_DATA_LEN) != MEASUREMENT_DATA_LEN) {
        perror("Error reading from I2C device");
        return -1.0;
    }

    unsigned char raw_ticks = (data[0] << 8) | data[1];
    unsigned char crc_received = data[2];
    unsigned char crc_calculated = crc8(data, 2);

    if (crc_received != crc_calculated) {
        fprintf(stderr, "CRC mismatch: received %02X, calculated %02X\n", crc_received, crc_calculated);
        return -1.0;
    }

    double temperature = TEMP_OFFSET + raw_ticks * TEMP_CONVERSION_FACTOR;
    return temperature;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd == -1) {
        perror("Error opening I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        double temperature = read_temperature();
        if (temperature >= 0.0) {
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            fprintf(log_file, "%s %.2f\n", asctime(timeinfo), temperature);
        }
        usleep(LOG_INTERVAL * 1000); // Sleep for 5 seconds
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

