#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SDP810_ADDR 0x25
#define PRESSURE_CMD 0x3615
#define PRESSURE_BYTES 9
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

int main() {
    int i2cHandle;
    FILE *logFile;
    unsigned char buffer[PRESSURE_BYTES];
    unsigned char crc;
    unsigned int pressure, temperature;
    double pressure_Pa, temperature_C;
    time_t timestamp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Open I2C bus 1
    i2cHandle = i2cOpen(1, SDP810_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    logFile = fopen("hvac_pressure_log.txt", "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Send command to sensor
        if (i2cWriteDevice(i2cHandle, &PRESSURE_CMD, 2) != 2) {
            fprintf(stderr, "Failed to write command to sensor.\n");
            continue;
        }

        // Wait at least 50 ms
        usleep(50000);

        // Read 9 bytes from sensor
        if (i2cReadDevice(i2cHandle, buffer, PRESSURE_BYTES) != PRESSURE_BYTES) {
            fprintf(stderr, "Failed to read from sensor.\n");
            continue;
        }

        // Calculate CRC-8 for pressure
        crc = 0xFF;
        for (int i = 0; i < 2; i++) {
            crc ^= buffer[i];
            for (int j = 0; j < 8; j++) {
                if (crc & 0x80) {
                    crc = (crc << 1) ^ CRC_POLY;
                } else {
                    crc <<= 1;
                }
            }
        }
        if (crc != buffer[2]) {
            fprintf(stderr, "CRC error for pressure.\n");
            continue;
        }

        // Calculate CRC-8 for temperature
        crc = 0xFF;
        for (int i = 3; i < 5; i++) {
            crc ^= buffer[i];
            for (int j = 0; j < 8; j++) {
                if (crc & 0x80) {
                    crc = (crc << 1) ^ CRC_POLY;
                } else {
                    crc <<= 1;
                }
            }
        }
        if (crc != buffer[5]) {
            fprintf(stderr, "CRC error for temperature.\n");
            continue;
        }

        // Convert raw pressure and temperature
        pressure = (buffer[0] << 8) | buffer[1];
        temperature = (buffer[3] << 8) | buffer[4];
        pressure_Pa = (double)pressure / (buffer[6] << 8 | buffer[7]);
        temperature_C = (double)temperature / 200.0;

        // Log the reading
        timestamp = time(NULL);
        fprintf(logFile, "%ld,%f,%f\n", timestamp, pressure_Pa, temperature_C);
        fflush(logFile);

        // Sleep for 1 second
        sleep(1);
    }

    // Handle SIGINT (Ctrl+C)
    signal(SIGINT, [](int signum) {
        fclose(logFile);
        i2cClose(i2cHandle);
        gpioTerminate();
        exit(0);
    });

    return 0;
}

