#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x62
#define CMD_START_MEASUREMENT 0x21B1
#define CMD_READ_DATA 0xE000
#define CMD_STOP_MEASUREMENT 0x3F86
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define BUFFER_CAPACITY 100
#define LOG_FILE "/var/log/scd40_error.log"
#define DATA_DIR "/var/log/scd40_data/"

typedef struct {
    unsigned int timestamp;
    unsigned int co2;
    float temperature;
    float humidity;
} Reading;

volatile sig_atomic_t running = 1;

pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t buffer_not_empty = PTHREAD_COND_INITIALIZER;

Reading buffer[BUFFER_CAPACITY];
int buffer_head = 0;
int buffer_tail = 0;

void handle_sigint(int signum) {
    running = 0;
}

void crc8(unsigned char *data, int len, unsigned char *crc) {
    unsigned char i, j;
    *crc = CRC_INITIAL_VALUE;
    for (i = 0; i < len; i++) {
        for (j = 8; j; j--) {
            *crc = (*crc << 1) ^ (((*crc & 0x80) ? CRC_POLYNOMIAL : 0) ^ (data[i] & 0x80));
            data[i] <<= 1;
        }
    }
}

int read_sensor_data(unsigned char *data) {
    int i2c_result = i2c_write_read(I2C_BUS, I2C_ADDR, &CMD_READ_DATA, 2, data, 9);
    if (i2c_result != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", i2c_result);
        return -1;
    }

    unsigned char crc_calculated;
    crc8(data, 7, &crc_calculated);

    if (crc_calculated != data[7]) {
        fprintf(stderr, "CRC check failed for CO2\n");
        return -1;
    }

    crc_calculated = 0xFF;
    crc8(data + 2, 7, &crc_calculated);

    if (crc_calculated != data[9]) {
        fprintf(stderr, "CRC check failed for temperature\n");
        return -1;
    }

    crc_calculated = 0xFF;
    crc8(data + 9, 7, &crc_calculated);

    if (crc_calculated != data[16]) {
        fprintf(stderr, "CRC check failed for humidity\n");
        return -1;
    }

    return 0;
}

void *logging_thread(void *arg) {
    while (running) {
        pthread_mutex_lock(&buffer_mutex);
        while (buffer_tail == buffer_head) {
            pthread_cond_wait(&buffer_not_empty, &buffer_mutex);
        }

        FILE *file = fopen(DATA_DIR "scd40_data_" __TIME__ ".csv", "w");
        if (!file) {
            fprintf(stderr, "Error opening file for logging: %s\n", DATA_DIR "scd40_data_" __TIME__ ".csv");
            pthread_mutex_unlock(&buffer_mutex);
            continue;
        }

        fprintf(file, "Timestamp,CO2,Temperature,Humidity\n");
        for (int i = buffer_tail; i != buffer_head; i = (i + 1) % BUFFER_CAPACITY) {
            fprintf(file, "%u,%u,%.2f,%.2f\n", buffer[i].timestamp, buffer[i].co2, buffer[i].temperature, buffer[i].humidity);
        }
        fclose(file);

        buffer_tail = buffer_head;
        pthread_cond_broadcast(&buffer_not_empty);
        pthread_mutex_unlock(&buffer_mutex);

        sleep(60);
    }

    return NULL;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pigtailError());
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigtailError());
        gpioTerminate();
        return 1;
    }

    if (i2cWrite(I2C_BUS, I2C_ADDR, &CMD_START_MEASUREMENT, 2) != 2) {
        fprintf(stderr, "Error starting measurement: %s\n", pigtailError());
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    sleep(1);

    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        fprintf(stderr, "Error creating logging thread: %s\n", pigtailError());
        i2cWrite(I2C_BUS, I2C_ADDR, &CMD_STOP_MEASUREMENT, 2);
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        unsigned char data[9];
        if (read_sensor_data(data) == 0) {
            unsigned int co2 = (data[0] << 8) | data[1];
            unsigned int temp_raw = (data[2] << 8) | data[3];
            unsigned int hum_raw = (data[4] << 8) | data[5];

            float temperature = -45 + 175 * temp_raw / 65535.0;
            float humidity = 100 * hum_raw / 65535.0;

            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);

            pthread_mutex_lock(&buffer_mutex);
            buffer[buffer_head].timestamp = mktime(now_tm);
            buffer[buffer_head].co2 = co2;
            buffer[buffer_head].temperature = temperature;
            buffer[buffer_head].humidity = humidity;
            buffer_head = (buffer_head + 1) % BUFFER_CAPACITY;
            pthread_cond_signal(&buffer_not_empty);
            pthread_mutex_unlock(&buffer_mutex);
        }

        sleep(5);
    }

    i2cWrite(I2C_BUS, I2C_ADDR, &CMD_STOP_MEASUREMENT, 2);
    i2cClose(I2C_BUS);
    gpioTerminate();

    pthread_join(logging_thread_id, NULL);

