        double pressure_Pa = (double)raw_pressure * scale_factor / 1000.0;
        double temperature_C = -45 + 175.0 * raw_temp / 65535.0;

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
                pressure_Pa, temperature_C);

        fflush(log_file);

        sleep(1); // Log once per second
    }

    handle_sigint(0); // This will be called when SIGINT is received

    return 0;
}

