#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define CALIB_REG 0x05
#define MEASURE_REG 0x00
#define PRESSURE_TEMP_DATA_REG 0x00
#define PRESSURE_TEMP_DATA_LEN 6
#define CALIB_COEFFICIENTS_LEN 4
#define SAMPLE_INTERVAL 5000 // 5 seconds

int main() {
    int i2cHandle;
    int status;
    char buffer[CALIB_COEFFICIENTS_LEN + PRESSURE_TEMP_DATA_LEN];
    int calibCoefficients[CALIB_COEFFICIENTS_LEN];
    int pressureData[2];
    int temperatureData[2];
    int pressure, temperature;
    struct tm *timeinfo;
    FILE *file;
    int exitFlag = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Open I2C bus
    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor identity
    status = i2cReadI2CBlockData(i2cHandle, WHO_AM_I_REG, 1, &buffer[0]);
    if (status < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }
    if (buffer[0] != 0x08) {
        fprintf(stderr, "Invalid WHO_AM_I value.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Read calibration coefficients
    status = i2cReadI2CBlockData(i2cHandle, CALIB_REG, CALIB_COEFFICIENTS_LEN, &buffer[0]);
    if (status < 0) {
        fprintf(stderr, "Failed to read calibration coefficients.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }
    memcpy(calibCoefficients, buffer, CALIB_COEFFICIENTS_LEN * sizeof(int));

    // Open file for logging
    file = fopen("environmental_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for logging.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!exitFlag) {
        // Trigger measurement
        status = i2cWriteI2CBlockData(i2cHandle, MEASURE_REG, 1, &buffer[0]);
        if (status < 0) {
            fprintf(stderr, "Failed to trigger measurement.\n");
            continue;
        }

        // Wait for measurement
        usleep(10000);

        // Read pressure and temperature data
        status = i2cReadI2CBlockData(i2cHandle, PRESSURE_TEMP_DATA_REG, PRESSURE_TEMP_DATA_LEN, &buffer[0]);
        if (status < 0) {
            fprintf(stderr, "Failed to read pressure and temperature data.\n");
            continue;
        }

        // Convert data to hPa and Celsius
        pressureData[0] = (buffer[0] << 8) | buffer[1];
        pressureData[1] = (buffer[2] << 8) | buffer[3];
        temperatureData[0] = (buffer[4] << 8) | buffer[5];

        pressure = (pressureData[0] * calibCoefficients[0] + pressureData[1] * calibCoefficients[1] + calibCoefficients[2]) / 1000;
        temperature = (temperatureData[0] * calibCoefficients[3] + calibCoefficients[4]) / 1000;

        // Log data
        timeinfo = localtime(&time(NULL));
        fprintf(file, "%04d-%02d-%02dT%02d:%02d:%02d, Pressure: %d hPa, Temperature: %d °C\n",
                timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, pressure, temperature);
        fflush(file);

        // Print data to stdout
        printf("Pressure: %d hPa, Temperature: %d °C\n", pressure, temperature);

        // Sleep for 5 seconds
        sleep(SAMPLE_INTERVAL / 1000);

        // Check for SIGINT
        if (exitFlag) {
            break;
        }
    }

    // Cleanup
    fclose(file);
    i2cClose(i2cHandle);
    gpioTerminate();

    return 0;
}

