#define DATA_LENGTH 6
#define PRESSURE_OFFSET 0x00
#define TEMPERATURE_OFFSET 0x02
#define CRC_OFFSET 0x04

static int i2c_fd;
static struct gpiod_line *led_line;

void handle_sigint(int signum) {
    gpiod_line_request_free(led_line);
    close(i2c_fd);
    exit(0);
}

int read_i2c_data(uint8_t *data, uint8_t length) {
    int bytes_read;
    bytes_read = read(i2c_fd, data, length);
    if (bytes_read != length) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

int write_i2c_data(uint8_t *data, uint8_t length) {
    int bytes_written;
    bytes_written = write(i2c_fd, data, length);
    if (bytes_written != length) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int main() {
    struct gpiod_line_request_config config;
    uint8_t data[DATA_LENGTH];
    uint16_t pressure, temperature, crc;
    uint16_t calibration_coeffs[4];
    uint16_t pressure_raw, temperature_raw;
    uint32_t pressure_final, temperature_final;
    int i2c_status;

    signal(SIGINT, handle_sigint);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C device address");
        close(i2c_fd);
        return -1;
    }

    gpiod_line_request_config_init(&config);
    config.consumer = "I2C_Pressure_Sensor";
    config.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    config.flags = GPIOD_LINE_ACTIVE_HIGH;
    config.line_name = "GPIO17";

    led_line = gpiod_line_request_by_name(&config);
    if (led_line == NULL) {
        perror("Error requesting GPIO line");
        close(i2c_fd);
        return -1;
    }

    while (1) {
        uint8_t cmd[2] = {CMD_CALIBRATION, 0x00};
        uint8_t measure_cmd[2] = {CMD_MEASURE, 0x00};

        // Read calibration coefficients
        if (write_i2c_data(cmd, 2) < 0) {
            continue;
        }
        if (read_i2c_data(calibration_coeffs, 8) < 0) {
            continue;
        }

        // Trigger measurement
        if (write_i2c_data(measure_cmd, 2) < 0) {
            continue;
        }

        // Wait for measurement
        usleep(20000);

        // Read data
        if (read_i2c_data(data, DATA_LENGTH) < 0) {
            continue;
        }

        // Extract raw pressure and temperature
        pressure_raw = (data[PRESSURE_OFFSET] << 8) | data[PRESSURE_OFFSET + 1];
        temperature_raw = (data[TEMPERATURE_OFFSET] << 8) | data[TEMPERATURE_OFFSET + 1];
        crc = (data[CRC_OFFSET] << 8) | data[CRC_OFFSET + 1];

        // Verify CRC
        if (crc != 0) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        // Apply conversion formulas
        pressure_final = (pressure_raw * calibration_coeffs[0]) / 65536 + calibration_coeffs[1];
        temperature_final = (temperature_raw * calibration_coeffs[2]) / 65536 + calibration_coeffs[3];

        // Check pressure and blink LED accordingly
        if (pressure_final < 95000) {
            gpiod_line_set_value(led_line, 1);
            usleep(100000);
            gpiod_line_set_value(led_line, 0);
            usleep(100000);
        } else {
            gpiod_line_set_value(led_line, 1);
            usleep(500000);
            gpiod_line_set_value(led_line, 0);
            usleep(500000);
        }

        sleep(1);
    }

    gpiod_line_request_free(led_line);
    close(i2c_fd);

    return 0;
}

