#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MLX90614_ADDR 0x5A
#define MLX90614_AMBIENT_TEMP_REG 0x06
#define MLX90614_OBJECT_TEMP_REG 0x07
#define MLX90614_FAN_GPIO 18
#define MLX90614_FAN_ON_TEMP 30
#define MLX90614_FAN_OFF_TEMP 28
#define MLX90614_RETRY_COUNT 3
#define MLX90614_RETRY_DELAY 10

void handle_signal(int signum) {
    if (pi_i2c_close(handle) < 0) {
        fprintf(stderr, "Failed to close I2C handle.\n");
    }
    pi_set_mode(MLX90614_FAN_GPIO, PI_INPUT);
    pi_stop();
    exit(signum);
}

int read_temperature(int reg, int retry_count) {
    int raw_value = 0;
    int i;

    for (i = 0; i < retry_count; i++) {
        if (pi_i2c_read_i2c_block_data(handle, MLX90614_ADDR, reg, 2, &raw_value) >= 0) {
            return raw_value;
        }
        usleep(MLX90614_RETRY_DELAY * 1000);
    }
    return -1;
}

int main() {
    int handle = -1;
    int ambient_temp = 0;
    int object_temp = 0;
    int fan_state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    handle = pi_i2c_open(1, MLX90614_ADDR);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        pi_stop();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        ambient_temp = read_temperature(MLX90614_AMBIENT_TEMP_REG, MLX90614_RETRY_COUNT);
        object_temp = read_temperature(MLX90614_OBJECT_TEMP_REG, MLX90614_RETRY_COUNT);

        if (ambient_temp >= 0 && object_temp >= 0) {
            double ambient_celsius = ambient_temp * 0.02 - 273.15;
            double object_celsius = object_temp * 0.02 - 273.15;

            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);

            FILE *log_file = fopen("temperature_log.txt", "a");
            if (log_file != NULL) {
                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - Ambient: %.2f°C, Object: %.2f°C\n",
                        now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                        now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
                        ambient_celsius, object_celsius);
                fclose(log_file);
            }

            if (object_celsius > MLX90614_FAN_ON_TEMP) {
                if (fan_state == 0) {
                    pi_set_mode(MLX90614_FAN_GPIO, PI_OUTPUT);
                    pi_write(MLX90614_FAN_GPIO, 1);
                    fan_state = 1;
                }
            } else if (object_celsius < MLX90614_FAN_OFF_TEMP) {
                if (fan_state == 1) {
                    pi_set_mode(MLX90614_FAN_GPIO, PI_OUTPUT);
                    pi_write(MLX90614_FAN_GPIO, 0);
                    fan_state = 0;
                }
            }
        }

        sleep(2);
    }

    if (handle >= 0) {
        pi_i2c_close(handle);
    }

    pi_stop();
    return 0;
}

