This C program initializes the pigpio library, opens the I2C bus, and sets up signal handling for SIGINT and SIGTERM. It continuously reads the ambient and object temperatures from the MLX90614 sensor, logs the readings to `temperature_log.txt`, and controls a cooling fan on GPIO 18 based on the object temperature with hysteresis. The program retries I2C reads up to 3 times with a 10 ms delay between attempts if a read fails. On receiving a SIGINT or SIGTERM, it cleanly closes the I2C handle, turns off the fan, and terminates pigpio.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define MEASUREMENT_CMD 0xFD
#define RETRY_COUNT 3
#define BUFFER_SIZE 6
#define TEMP_OFFSET -45
#define TEMP_SCALE 175
#define HUMIDITY_OFFSET -6
#define HUMIDITY_SCALE 125
#define HUMIDITY_MAX 100

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

double read_temperature_humidity() {
    int retries = 0;
    int status;
    uint8_t buffer[BUFFER_SIZE];

    while (retries < RETRY_COUNT) {
        status = i2c_write_device(I2C_BUS, I2C_ADDR, &MEASUREMENT_CMD, 1);
        if (status != 0) {
            printf("I2C write error: %d\n", status);
            retries++;
            continue;
        }

        usleep(10000); // Wait at least 10 ms

        status = i2c_read_device(I2C_BUS, I2C_ADDR, buffer, BUFFER_SIZE);
        if (status != BUFFER_SIZE) {
            printf("I2C read error: %d\n", status);
            retries++;
            continue;
        }

        uint16_t raw_T = (buffer[0] << 8) | buffer[1];
        uint16_t raw_RH = (buffer[2] << 8) | buffer[3];

        double temperature = TEMP_OFFSET + TEMP_SCALE * (double)raw_T / 65535;
        double humidity = HUMIDITY_OFFSET + HUMIDITY_SCALE * (double)raw_RH / 65535;

        if (humidity < 0) humidity = 0;
        if (humidity > HUMIDITY_MAX) humidity = HUMIDITY_MAX;

        return humidity;
    }

    return -1; // Failed to read after retries
}

void *http_server(void *arg) {
    int server_fd, new_socket, valread;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};
    double humidity = read_temperature_humidity();

    if (humidity < 0) {
        printf("Failed to read sensor data.\n");
        return NULL;
    }

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return NULL;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        return NULL;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(8080);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        return NULL;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        return NULL;
    }

    printf("Server listening on port 8080\n");

    while (!stop) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        valread = read(new_socket, buffer, 1024);
        if (valread == 0) {
            printf("Client disconnected\n");
            break;
        }

        char response[1024];
        sprintf(response, "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<html><body><h1>Temperature and Humidity</h1><p>Humidity: %.2f%%</p></body></html>", humidity);

        send(new_socket, response, strlen(response), 0);
        printf("Response sent\n");

        close(new_socket);
    }

    close(server_fd);
    return NULL;
}

int main() {
    if (gpioInitialise() < 0) {
        printf("pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    pthread_t server_thread;
    if (pthread_create(&server_thread, NULL, http_server, NULL) != 0) {
        printf("Failed to create server thread\n");
        return 1;
    }

    while (!stop) {
        double humidity = read_temperature_humidity();
        if (humidity < 0) {
            printf("Failed to read sensor data.\n");
            continue;
        }

        printf("Humidity: %.2f%%\n", humidity);
        sleep(1);
    }

    stop = 0; // Reset stop flag to avoid race condition
    pthread_join(server_thread, NULL);

    gpioTerminate();
    return 0;
}

