#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG 0x0F
#define TEMP_REG 0x00
#define HUMIDITY_REG 0x02
#define MAX_RETRIES 5
#define TIMEOUT_MS 500

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

int read_sensor_data(int handle) {
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        status = i2cWriteReg(handle, I2C_ADDR, MEASUREMENT_CONFIG, 0x01);
        if (status < 0) {
            printf("Error writing to MEASUREMENT_CONFIG register: %d\n", status);
            sleep(1);
            retries++;
            continue;
        }

        int poll_retries = 0;
        while (poll_retries < MAX_RETRIES) {
            status = i2cReadReg(handle, I2C_ADDR, MEASUREMENT_CONFIG, 1);
            if (status < 0) {
                printf("Error reading MEASUREMENT_CONFIG register: %d\n", status);
                sleep(1);
                poll_retries++;
                continue;
            }

            if ((status & 0x01) == 0) {
                break;
            }

            if (poll_retries >= MAX_RETRIES) {
                printf("Timeout waiting for measurement completion.\n");
                break;
            }

            sleep(1);
            poll_retries++;
        }

        if (poll_retries < MAX_RETRIES) {
            status = i2cReadReg(handle, I2C_ADDR, TEMP_REG, 2);
            if (status < 0) {
                printf("Error reading temperature register: %d\n", status);
                retries++;
                continue;
            }

            status = i2cReadReg(handle, I2C_ADDR, HUMIDITY_REG, 2);
            if (status < 0) {
                printf("Error reading humidity register: %d\n", status);
                retries++;
                continue;
            }

            int temp_raw = (status << 8) | (status & 0xFF);
            int humidity_raw = (status << 8) | (status & 0xFF);

            float temperature = (float)temp_raw / 65536.0 * 165.0 - 40.0;
            float humidity = (float)humidity_raw / 65536.0 * 100.0;

            printf("Temperature: %.2f C, Humidity: %.2f %\n", temperature, humidity);
            return 0;
        }

        retries++;
    }

    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        printf("pigpio initialization failed.\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        printf("Failed to open I2C bus: %d\n", handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        if (read_sensor_data(handle) < 0) {
            printf("Failed to read sensor data.\n");
        }

        sleep(5);
    }

    i2cClose(handle);
    gpioTerminate();

    return 0;
}

