#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define PRESSURE_CMD 0x362F
#define PRESSURE_DATA_LEN 6
#define PRESSURE_DATA_INTERVAL 500000 // 500 ms

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

uint8_t crc8(uint8_t *data, uint8_t len, uint8_t init) {
    uint8_t crc = init;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        uint8_t cmd = PRESSURE_CMD;
        if (i2cWriteDevice(I2C_ADDR, &cmd, 1) < 0) {
            fprintf(stderr, "Failed to write command to sensor.\n");
            break;
        }

        uint8_t data[PRESSURE_DATA_LEN];
        if (i2cReadDevice(I2C_ADDR, data, PRESSURE_DATA_LEN) < 0) {
            fprintf(stderr, "Failed to read data from sensor.\n");
            break;
        }

        uint16_t pressure = (data[0] << 8) | data[1];
        uint16_t temperature = (data[2] << 8) | data[3];

        uint8_t pressure_crc = crc8(data, 2, 0xFF);
        uint8_t temperature_crc = crc8(data + 2, 2, 0xFF);

        if (pressure_crc != data[4] || temperature_crc != data[5]) {
            fprintf(stderr, "CRC check failed for pressure or temperature.\n");
            continue;
        }

        printf("Pressure: %d, Temperature: %d\n", pressure, temperature);

        usleep(PRESSURE_DATA_INTERVAL);
    }

    i2cClose(I2C_ADDR);
    gpioTerminate();

    return 0;
}

