#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define GPIO_PIN 17
#define FILE_PROFILE "profile.txt"
#define FILE_LOG "reflow_log.csv"

static struct spidev *spi;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(void) {
    if (line) {
        gpiod_line_put(line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    if (spi) {
        spidev_close(spi);
    }
    exit(EXIT_FAILURE);
}

void handle_sigterm(int signum) {
    cleanup();
}

int read_temperature() {
    uint8_t data[2];
    int ret;

    ret = spidev_read(spi, SPI_BITS, SPI_MODE, SPI_SPEED, data, 2);
    if (ret < 0) {
        perror("spidev_read");
        cleanup();
    }

    uint16_t temp_raw = (data[1] << 8) | data[0];
    if (temp_raw & 0x4) {
        fprintf(stderr, "Open-circuit detected\n");
        cleanup();
    }

    int temperature = (temp_raw >> 3) * 250 / 4096;
    return temperature;
}

void write_log(int temperature) {
    FILE *log_file = fopen(FILE_LOG, "a");
    if (!log_file) {
        perror("fopen");
        cleanup();
    }

    fprintf(log_file, "%d,%d\n", time(NULL), temperature);
    fclose(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigterm;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);

    spi = spidev_open(SPI_DEVICE, O_RDWR);
    if (spi == NULL) {
        perror("spidev_open");
        cleanup();
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        cleanup();
    }

    line = gpiod_line_request_any(chip, "RELAY", GPIO_LINE_DIRECTION_OUTPUT);
    if (!line) {
        perror("gpiod_line_request_any");
        cleanup();
    }

    FILE *profile_file = fopen(FILE_PROFILE, "r");
    if (!profile_file) {
        perror("fopen");
        cleanup();
    }

    char line[256];
    while (fgets(line, sizeof(line), profile_file)) {
        int time_seconds, target_temp_celsius;
        if (sscanf(line, "%d,%d", &time_seconds, &target_temp_celsius) != 2) {
            fprintf(stderr, "Invalid profile line: %s", line);
            cleanup();
        }

        usleep(time_seconds * 1000000);

        int temperature = read_temperature();
        write_log(temperature);

        // Implement PID control logic here (simplified for brevity)
        double pid_output = 0.5; // Placeholder for PID output
        gpiod_line_set_value(line, pid_output * 255); // Assuming 8-bit PWM
    }

    fclose(profile_file);
    cleanup();

    return 0;
}

