        return 1;
    }

    setpoint = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (gpiod_line_request_by_name(chip, "4", "temp_sensor", GPIOD_LINE_DIRECTION_IN, &temp_sensor_line) < 0) {
