        double derivative = (error - prev_error) / PID_INTERVAL;
        integral += error * PID_INTERVAL;

        double pid_output = Kp * error + Ki * integral + Kd * derivative;

        double duty_cycle = pid_output * 100.0; // Assuming 0-100% duty cycle
        if (duty_cycle < 0.0) {
            duty_cycle = 0.0;
        } else if (duty_cycle > 100.0) {
            duty_cycle = 100.0;
        }

