        usleep(PID_INTERVAL * 1000); // Sleep for 5 seconds
    }

error_exit:
    gpiod_line_request_free(temp_sensor_line);
    gpiod_line_request_free(relay_line);
    gpiod_line_request_free(pwm_line);
    gpiod_chip_put(chip);
    fclose(fopen(LOG_FILE, "a")); // Ensure log file is closed
    return 1;
