#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <pigpio.h>
#include <time.h>

#define HUMIDITY_THRESHOLD_HIGH 60
#define HUMIDITY_THRESHOLD_LOW 55
#define I2C_ADDR 0x38
#define I2C_DEV "/dev/i2c-1"
#define RELAY_GPIO 17
#define RELAY_ACTIVE_HIGH 1
#define RELAY_ACTIVE_LOW 0
#define RETRY_COUNT 3
#define RETRY_DELAY 10
#define POLL_INTERVAL 5000

static int i2c_fd;
static struct gpiod_line *relay_line;

void handle_signal(int signum) {
    if (relay_line) {
        gpiod_line_request_release(relay_line);
        free(relay_line);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int i2c_write(uint8_t reg, uint8_t data) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (write(i2c_fd, &reg, 1) != 1 || write(i2c_fd, &data, 1) != 1) {
            retries--;
            usleep(RETRY_DELAY * 1000);
        } else {
            return 0;
        }
    }
    return -1;
}

int i2c_read(uint8_t reg, uint8_t *data, int len) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (write(i2c_fd, &reg, 1) != 1 || read(i2c_fd, data, len) != len) {
            retries--;
            usleep(RETRY_DELAY * 1000);
        } else {
            return 0;
        }
    }
    return -1;
}

int read_humidity() {
    uint8_t status_byte;
    uint8_t data[6];

    if (i2c_write(0xAC, 0x33) != 0) {
        return -1;
    }

    usleep(80 * 1000);

    if (i2c_read(0xAC, data, 6) != 0) {
        return -1;
    }

    status_byte = data[0];
    if ((status_byte & 0x01) != 0 || (status_byte & 0x02) != 0) {
        return -1;
    }

    int humidity = (data[1] << 8) | data[2];
    return humidity;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request(RELAY_GPIO, "relay", GPIOD_LINE_DIRECTION_OUTPUT, RELAY_ACTIVE_HIGH, &relay_line) < 0) {
        perror("gpiod_line_request");
        close(i2c_fd);
        return 1;
    }

    gpiod_line_set_value(relay_line, RELAY_ACTIVE_LOW);

    if (i2c_write(0xBE, 0x08) != 0 || i2c_write(0xBE, 0x00) != 0) {
        perror("Initialization failed");
        gpiod_line_request_release(relay_line);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        int humidity = read_humidity();
        if (humidity == -1) {
            fprintf(stderr, "Failed to read humidity\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);

        printf("Humidity: %d%% (at %02d:%02d:%02d)\n", humidity, tm->tm_hour, tm->tm_min, tm->tm_sec);

        if (humidity > HUMIDITY_THRESHOLD_HIGH) {
            gpiod_line_set_value(relay_line, RELAY_ACTIVE_HIGH);
        } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
            gpiod_line_set_value(relay_line, RELAY_ACTIVE_LOW);
        }

        sleep(POLL_INTERVAL / 1000);
    }

    return 0;
}

