#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
#include <syslog.h>
#include <signal.h>

#define HTU21D_ADDR 0x40
#define HTU21D_MEAS_HUM 0xF3
#define HTU21D_MEAS_TEMP 0xF4
#define HTU21D_READ_STATUS 0xF3
#define HTU21D_READ_RESULT 0xF6

#define HTTP_PORT 80
#define HTTP_HOST "api.example.com"
#define HTTP_PATH "/humidity"

#define BUFFER_SIZE 128

void handle_signal(int signum) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signum);
    close(i2c_fd);
    close(http_sock);
    exit(signum);
}

int read_sensor(int i2c_fd) {
    char buffer[BUFFER_SIZE];
    int bytes_read;

    // Start humidity measurement
    if (write(i2c_fd, &HTU21D_MEAS_HUM, 1) != 1) {
        syslog(LOG_ERR, "Failed to start humidity measurement");
        return -1;
    }

    // Wait for measurement to complete
    usleep(250000);

    // Read status register
    if (read(i2c_fd, &buffer, 1) != 1) {
        syslog(LOG_ERR, "Failed to read status register");
        return -1;
    }

    // Check if measurement is complete
    if (buffer[0] != 0x00) {
        syslog(LOG_ERR, "Measurement not complete");
        return -1;
    }

    // Read humidity data
    if (read(i2c_fd, &buffer, 2) != 2) {
        syslog(LOG_ERR, "Failed to read humidity data");
        return -1;
    }

    // Convert to 16-bit integer
    int humidity = (buffer[0] << 8) | buffer[1];

    return humidity;
}

int send_http_post(int sock, const char *json) {
    char request[BUFFER_SIZE];
    char response[BUFFER_SIZE];
    int bytes_written, bytes_read;

    // Construct HTTP POST request
    snprintf(request, BUFFER_SIZE, "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s", HTTP_PATH, HTTP_HOST, strlen(json), json);

    // Send request
    if ((bytes_written = write(sock, request, strlen(request))) != strlen(request)) {
        syslog(LOG_ERR, "Failed to send HTTP POST request");
        return -1;
    }

    // Read response
    if ((bytes_read = read(sock, response, BUFFER_SIZE)) <= 0) {
        syslog(LOG_ERR, "Failed to read HTTP response");
        return -1;
    }

    // Log response
    syslog(LOG_INFO, "HTTP Response: %s", response);

    return 0;
}

int main() {
    struct sigaction sa;
    int i2c_fd, http_sock;
    char json[BUFFER_SIZE];
    int humidity;

    // Initialize syslog
    openlog("humidity_sensor", LOG_PID, LOG_USER);

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        return 1;
    }

    // Set I2C device address
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C device address");
        close(i2c_fd);
        return 1;
    }

    // Open HTTP socket
    http_sock = socket(AF_INET, SOCK_STREAM, 0);
    if (http_sock < 0) {
        syslog(LOG_ERR, "Failed to open HTTP socket");
        close(i2c_fd);
        return 1;
    }

    // Connect to HTTP server
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(HTTP_PORT);
    if (inet_pton(AF_INET, HTTP_HOST, &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Failed to resolve HTTP host");
        close(i2c_fd);
        close(http_sock);
        return 1;
    }

    if (connect(http_sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Failed to connect to HTTP server");
        close(i2c_fd);
        close(http_sock);
        return 1;
    }

    // Main loop
    while (1) {
        // Read humidity from sensor
        humidity = read_sensor(i2c_fd);
        if (humidity < 0) {
            syslog(LOG_ERR, "Failed to read humidity from sensor");
            continue;
        }

        // Construct JSON payload
        snprintf(json, BUFFER_SIZE, "{\"humidity\": %d}", humidity);

        // Send HTTP POST request
        if (send_http_post(http_sock, json) < 0) {
            syslog(LOG_ERR, "Failed to send HTTP POST request");
            continue;
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Cleanup
    close(i2c_fd);
    close(http_sock);
    closelog();

    return 0;
}

