#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define TMP117_ADDR 0x48
#define TMP117_REG 0x00
#define AHT20_ADDR 0x38
#define AHT20_INIT_CMD 0xBE
#define AHT20_MEASURE_CMD 0xAC
#define AHT20_RESPONSE_LEN 7
#define PIR_GPIO 17
#define BACKOFF_MS 10
#define MAX_RETRIES 3

static gpiod_line *pir_line;
static int i2c_fd;

void handle_signal(int signum) {
    if (pir_line) {
        gpiod_line_free(pir_line);
    }
    close(i2c_fd);
    exit(signum);
}

int read_tmp117(int retries) {
    int ret = 0;
    for (int i = 0; i < retries; i++) {
        if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
            perror("I2C_SLAVE");
            continue;
        }
        if (write(i2c_fd, &TMP117_REG, 1) != 1) {
            perror("write");
            continue;
        }
        if (read(i2c_fd, &ret, 2) != 2) {
            perror("read");
            continue;
        }
        break;
    }
    if (i == retries) {
        fprintf(stderr, "Failed to read TMP117 after %d retries\n", retries);
    }
    return ret;
}

int read_aht20(int retries) {
    int ret = 0;
    for (int i = 0; i < retries; i++) {
        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
            perror("I2C_SLAVE");
            continue;
        }
        if (write(i2c_fd, &AHT20_INIT_CMD, 3) != 3) {
            perror("write");
            continue;
        }
        if (write(i2c_fd, &AHT20_MEASURE_CMD, 3) != 3) {
            perror("write");
            continue;
        }
        if (read(i2c_fd, &ret, AHT20_RESPONSE_LEN) != AHT20_RESPONSE_LEN) {
            perror("read");
            continue;
        }
        break;
    }
    if (i == retries) {
        fprintf(stderr, "Failed to read AHT20 after %d retries\n", retries);
    }
    return ret;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    pir_line = gpiod_line_request(4, PIR_GPIO, "PIR", GPIOD_LINE_DIRECTION_INPUT);
    if (!pir_line) {
        fprintf(stderr, "Failed to request GPIO line %d\n", PIR_GPIO);
        close(i2c_fd);
        return 1;
    }

    char filename[20];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(filename, sizeof(filename), "log_%Y-%m-%d.csv", tm);

    FILE *log_file = fopen(filename, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", filename);
        gpiod_line_free(pir_line);
        close(i2c_fd);
        return 1;
    }
    fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");

    while (1) {
        int tmp117_temp = read_tmp117(MAX_RETRIES);
        int aht20_data = read_aht20(MAX_RETRIES);
        int pir_value = gpiod_line_get_value(pir_line);

        if (tmp117_temp < 0 || aht20_data < 0) {
            fprintf(stderr, "Sensor read failed\n");
            continue;
        }

        double temperature = (double)tmp117_temp * 0.0078125;
        double humidity = (double)((aht20_data & 0x00FFFFFF) >> 7) * 0.04;

        time_t current_time = time(NULL);
        struct tm *current_tm = localtime(&current_time);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", current_tm);

        fprintf(log_file, "%s,%f,%f,%d\n", timestamp, temperature, humidity, pir_value);

        usleep(1000000); // Sleep for 1 second
    }

    fclose(log_file);
    gpiod_line_free(pir_line);
    close(i2c_fd);

    return 0;
}

