This C program logs temperature from a TMP117 sensor, humidity from an AHT20 sensor, and motion detection from a PIR sensor on GPIO 17 into daily timestamped CSV files. It uses `libgpiod` for GPIO access and the standard Linux I2C interface for the sensors. The program handles I2C errors with retries and a backoff, checks sensor presence at startup, and ensures clean resource release on all exit paths, including signal handling for SIGINT and SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

// GPIO pins
#define RAIN_SENSOR_PIN 17
#define ENA_PIN 22
#define IN1_PIN 23
#define IN2_PIN 24

// Function to handle signals
void handle_signals(int signum) {
    printf("Received signal %d at %s\n", signum, ctime(&time(NULL)));
    // Stop the motor
    gpiod_line_set_value(ena_line, 0);
    gpiod_line_set_value(in1_line, 0);
    gpiod_line_set_value(in2_line, 0);
    // Release GPIO lines
    gpiod_line_request_release(in2_line);
    gpiod_line_request_release(in1_line);
    gpiod_line_request_release(ena_line);
    gpiod_line_request_release(rain_sensor_line);
    // Exit the program
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *rain_sensor_line, *ena_line, *in1_line, *in2_line;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signals);
    signal(SIGTERM, handle_signals);

    // Open the GPIO chip
    ret = gpiod_chip_open(NULL, &chip);
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    ret = gpiod_line_request(chip, RAIN_SENSOR_PIN, "rain_sensor", "Rain sensor", 0, &rain_sensor_line);
    if (ret < 0) {
        perror("Failed to request rain sensor GPIO line");
        goto error_rain_sensor;
    }

    ret = gpiod_line_request(chip, ENA_PIN, "ena", "ENA line", 0, &ena_line);
    if (ret < 0) {
        perror("Failed to request ENA GPIO line");
        goto error_ena;
    }

    ret = gpiod_line_request(chip, IN1_PIN, "in1", "IN1 line", 0, &in1_line);
    if (ret < 0) {
        perror("Failed to request IN1 GPIO line");
        goto error_in1;
    }

    ret = gpiod_line_request(chip, IN2_PIN, "in2", "IN2 line", 0, &in2_line);
    if (ret < 0) {
        perror("Failed to request IN2 GPIO line");
        goto error_in2;
    }

    // Set the direction of the GPIO lines
    gpiod_line_direction_output(rain_sensor_line);
    gpiod_line_direction_output(ena_line);
    gpiod_line_direction_output(in1_line);
    gpiod_line_direction_output(in2_line);

