#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_GPIO 17
#define GREEN_GPIO 22
#define BLUE_GPIO 27

#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE_MAX 255

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

void set_led_color(int red, int green, int blue) {
    if (red < 0) red = 0;
    if (red > PWM_DUTY_CYCLE_MAX) red = PWM_DUTY_CYCLE_MAX;
    if (green < 0) green = 0;
    if (green > PWM_DUTY_CYCLE_MAX) green = PWM_DUTY_CYCLE_MAX;
    if (blue < 0) blue = 0;
    if (blue > PWM_DUTY_CYCLE_MAX) blue = PWM_DUTY_CYCLE_MAX;

    gpioPWM(RED_GPIO, red);
    gpioPWM(GREEN_GPIO, green);
    gpioPWM(BLUE_GPIO, blue);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetMode(RED_GPIO, PI_OUTPUT);
    gpioSetMode(GREEN_GPIO, PI_OUTPUT);
    gpioSetMode(BLUE_GPIO, PI_OUTPUT);

    gpioSetPWMfrequency(RED_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_GPIO, PWM_FREQUENCY);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *stat_file = fopen("/proc/stat", "r");
    if (!stat_file) {
        fprintf(stderr, "Failed to open /proc/stat.\n");
        return 1;
    }

    char line[256];
    unsigned long prev_cpu_idle = 0, prev_cpu_total = 0;
    unsigned long cpu_idle, cpu_total;

    while (!stop_flag) {
        fgets(line, sizeof(line), stat_file);
        if (sscanf(line, "cpu  %lu %lu %lu %lu %lu %lu %lu", &cpu_idle, &cpu_total, NULL, NULL, NULL, NULL, NULL) != 2) {
            fprintf(stderr, "Failed to parse /proc/stat.\n");
            return 1;
        }

        unsigned long cpu_load = (cpu_total - prev_cpu_total) - (cpu_idle - prev_cpu_idle);
        unsigned long total_load = cpu_total - prev_cpu_total;

        if (total_load == 0) {
            continue;
        }

        float load_percentage = (float)cpu_load / total_load * 100.0;

        int red = (int)(load_percentage * 255 / 100);
        int green = 255 - red;
        int blue = 0;

        set_led_color(red, green, blue);

        prev_cpu_idle = cpu_idle;
        prev_cpu_total = cpu_total;

        usleep(500000); // Sleep for 500 ms
    }

    set_led_color(0, 0, 0); // Turn off LED
    fclose(stat_file);
    gpioTerminate();

    return 0;
}

