#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID 0x58
#define BMP280_CAL_ADDR 0x88
#define BMP280_CTRL_MEAS 0xF4
#define BMP280_DATA_ADDR 0xF7
#define BMP280_DATA_LEN 6
#define BMP280_DATA_INTERVAL 5000 // 5 seconds

int sockfd;
int i2c_handle;

void cleanup() {
    if (i2c_handle != -1) {
        i2cUnexport(i2c_handle);
    }
    if (sockfd != -1) {
        close(sockfd);
    }
    if (pi != -1) {
        pigpioStop();
    }
    exit(1);
}

void signal_handler(int signum) {
    cleanup();
}

int read_i2c_register(int handle, uint8_t reg, uint8_t *data, int len) {
    int result = i2cReadDevice(handle, reg, data, len);
    if (result != len) {
        fprintf(stderr, "Error reading from I2C device\n");
        cleanup();
    }
    return result;
}

int write_i2c_register(int handle, uint8_t reg, uint8_t *data, int len) {
    int result = i2cWriteDevice(handle, reg, data, len);
    if (result != len) {
        fprintf(stderr, "Error writing to I2C device\n");
        cleanup();
    }
    return result;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (i2cOpen(1, BMP280_I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        cleanup();
    }

    uint8_t chip_id;
    if (read_i2c_register(i2c_handle, 0xD0, &chip_id, 1) != 1 || chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 sensor not found or invalid chip ID\n");
        cleanup();
    }

    uint8_t calibration_data[24];
    if (read_i2c_register(i2c_handle, BMP280_CAL_ADDR, calibration_data, 24) != 24) {
        fprintf(stderr, "Failed to read calibration data\n");
        cleanup();
    }

    uint8_t ctrl_meas_reg = 0x27; // Forced mode, low power
    if (write_i2c_register(i2c_handle, BMP280_CTRL_MEAS, &ctrl_meas_reg, 1) != 1) {
        fprintf(stderr, "Failed to set measurement mode\n");
        cleanup();
    }

    struct sockaddr_in server_addr;
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Failed to create UDP socket\n");
        cleanup();
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    inet_pton(AF_INET, "192.168.1.100", &server_addr.sin_addr);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        uint8_t data[BMP280_DATA_LEN];
        if (read_i2c_register(i2c_handle, BMP280_DATA_ADDR, data, BMP280_DATA_LEN) != BMP280_DATA_LEN) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        // Apply Bosch 64-bit compensation formulas here (not shown)

        char json_data[100];
        sprintf(json_data, "{\"temperature\":%f,\"pressure\":%f}", temperature, pressure);

        int bytes_sent = sendto(sockfd, json_data, strlen(json_data), 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
        if (bytes_sent < 0) {
            fprintf(stderr, "Failed to send UDP data\n");
            continue;
        }

        sleep(BMP280_DATA_INTERVAL / 1000);
    }

    cleanup();
    return 0;
}

