#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BUFFER_SIZE 20
#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_DUTY_RANGE 255

typedef struct {
    time_t timestamp;
    int temperature;
    int duty_cycle;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_head = 0;

void handle_sigint(int signum) {
    gpioPWM(PWM_PIN, 0);
    spiClose(0);
    printf("Received SIGINT. Stopping PWM and closing SPI.\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Timestamp: %ld, Temperature: %d, Duty Cycle: %d\n",
               log_buffer[i].timestamp, log_buffer[i].temperature, log_buffer[i].duty_cycle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int spi_fd = spiOpen(0, 500000, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel 0.\n");
        gpioTerminate();
        return 1;
    }

    gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);
    gpioSetPWMrange(PWM_PIN, PWM_DUTY_RANGE);

    while (1) {
        uint32_t spi_data[2];
        spi_data[0] = 0x00;
        spi_data[1] = 0x00;

        int result = spiXfer(spi_fd, spi_data, 2);
        if (result != 2) {
            fprintf(stderr, "SPI transfer error.\n");
            continue;
        }

        int32_t temperature = (int32_t)((spi_data[1] & 0x3FFF) * 0.25);
        int fault_bits = spi_data[1] & 0x7000;

        if (fault_bits != 0) {
            fprintf(stderr, "Fault detected: %04X\n", fault_bits);
            continue;
        }

        int duty_cycle = 0;
        if (temperature < 25) {
            duty_cycle = 0;
        } else if (temperature < 40) {
            duty_cycle = (temperature - 25) * (PWM_DUTY_RANGE / 15);
        } else if (temperature < 60) {
            duty_cycle = 50 + (temperature - 40) * (PWM_DUTY_RANGE / 20);
        } else {
            duty_cycle = PWM_DUTY_RANGE;
        }

        LogEntry entry = {time(NULL), temperature, duty_cycle};
        log_buffer[buffer_head] = entry;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;

        gpioPWM(PWM_PIN, duty_cycle);

        sleep(1);
    }

    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

