        calibration_data[3] == 0xAC7 && calibration_data[4] == 0xAC8 && calibration_data[5] == 0xAC9 &&
        calibration_data[6] == 0xACA && calibration_data[7] == 0xACB && calibration_data[8] == 0ACC &&
        calibration_data[9] == 0ACD && calibration_data[10] == 0ACE) {
        fprintf(stderr, "Calibration data verification failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen("altitude_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
