        return -1;
    }

    delay_time = 5 + (4 * (1 << OSS));
    usleep(delay_time * 1000);

    if (readI2CRegister(fd, pressure_reg, 3, &raw_pressure) < 0) {
        return -1;
    }

    // Convert raw temperature and pressure to actual values
    // (This part is omitted for brevity, as it involves complex calculations)

    *temperature = raw_temp;
    *pressure = raw_pressure;

    return 0;
}

int writeI2CRegister(int fd, unsigned char reg, unsigned char length) {
    if (write(fd, &reg, length) != length) {
        return -1;
    }

    return 0;
}

