#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>

#define SPI_DEV_PATH "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS_GPIO 8
#define LOG_FILE "rtd_log.csv"

static int spi_fd;
static struct gpiod_line *cs_line;

void handle_sigint(int signum) {
    gpiod_line_free(cs_line);
    close(spi_fd);
    exit(0);
}

int spi_transfer(uint8_t tx_buf[], uint8_t rx_buf[], size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("SPI transfer failed");
        return -1;
    }

    return 0;
}

int read_temperature() {
    uint8_t tx_buf[2] = {0x00, 0x00};
    uint8_t rx_buf[2];

    if (spi_transfer(tx_buf, rx_buf, 2) < 0) {
        return -1;
    }

    int32_t raw_temp = (rx_buf[0] << 8) | rx_buf[1];

    // Check fault status register
    if (raw_temp & 0x8000) {
        fprintf(stderr, "Fault detected in RTD sensor\n");
        return -1;
    }

    // Calculate temperature using Callendar-Van Dusen equation
    double temp_celsius = (double)raw_temp / 4.0;

    return temp_celsius;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEV_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to configure SPI device");
        close(spi_fd);
        return 1;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    cs_line = gpiod_line_request_by_name(chip, "gpio8", "CS_LINE",
                                         GPIOD_LINE_DIRECTION_OUTPUT,
                                         GPIOD_LINE_ACTIVE_LOW);
    if (!cs_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        close(spi_fd);
        return 1;
    }

    gpiod_line_set_value(cs_line, 1);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_free(cs_line);
        gpiod_chip_put(chip);
        close(spi_fd);
        return 1;
    }

    while (1) {
        gpiod_line_set_value(cs_line, 0);
        int temp = read_temperature();
        gpiod_line_set_value(cs_line, 1);

        if (temp < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s,%.2f\n", timestamp, temp);
        fflush(log_file);

        sleep(5);
    }

    fclose(log_file);
    gpiod_line_free(cs_line);
    gpiod_chip_put(chip);
    close(spi_fd);

    return 0;
}

