#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_CAL_START 0xAA
#define BMP180_REG_PRESSURE 0xF6
#define BMP180_OVERSAMPLING_ULTRA_LOW_POWER 0x34
#define BMP180_CALIB_COEFFICIENTS_COUNT 11
#define BUFFER_SIZE (60 * 1000 / 50) // 60 seconds of 50ms samples
#define PRESSURE_THRESHOLD 5 // 5 hPa deviation threshold

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    int i2cHandle = i2cOpen(1, BMP180_I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 for BMP180.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t calibCoefficients[BMP180_CALIB_COEFFICIENTS_COUNT];
    if (i2cReadByteData(i2cHandle, BMP180_REG_CAL_START, calibCoefficients, BMP180_CALIB_COEFFICIENTS_COUNT) < 0) {
        fprintf(stderr, "Failed to read calibration coefficients from BMP180.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t pressureBuffer[BUFFER_SIZE];
    int bufferIndex = 0;
    double rollingAverage = 0.0;

    for (int i = 0; i < BUFFER_SIZE; i++) {
        pressureBuffer[i] = 0;
    }

    gpioSetTimerFuncEx(50, 0, 0, [](int unused) {
        uint8_t pressureData[3];
        if (i2cWriteByteData(i2cHandle, BMP180_REG_CONTROL, BMP180_OVERSAMPLING_ULTRA_LOW_POWER) < 0) {
            fprintf(stderr, "Failed to set oversampling for BMP180.\n");
            return;
        }

        usleep(5000); // Wait for 5 ms

        if (i2cReadByteData(i2cHandle, BMP180_REG_PRESSURE, pressureData, 3) < 0) {
            fprintf(stderr, "Failed to read pressure data from BMP180.\n");
            return;
        }

        uint16_t pressure = (pressureData[0] << 8) | pressureData[1];

        rollingAverage = (rollingAverage * (BUFFER_SIZE - 1) + pressure) / BUFFER_SIZE;

        if (abs(pressure - rollingAverage) > PRESSURE_THRESHOLD) {
            printf("Alert: Pressure deviation %d hPa from rolling average %.2f hPa at %ld\n", (int)(pressure - rollingAverage), rollingAverage, time(NULL));
            gpioWrite(24, 1); // Trigger alert on GPIO24
        } else {
            gpioWrite(24, 0); // Clear alert on GPIO24
        }

        pressureBuffer[bufferIndex] = pressure;
        bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;
    });

    while (1) {
        if (gpioWaitRead(24) == 1) {
            printf("Received SIGINT, cleaning up...\n");
            break;
        }
    }

    i2cClose(i2cHandle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

