#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define FAN_FREQ 25000
#define FAN_DUTY_MIN 0
#define FAN_DUTY_MAX 255
#define TEMP_MIN 40
#define TEMP_MAX 70
#define LOG_FILE "fan_log.txt"
#define LOG_INTERVAL 5000 // 5 seconds

void handle_signal(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    gpioWrite(FAN_GPIO, 0); // Stop the fan
    fclose(fopen(LOG_FILE, "a")); // Close log file
    gpioTerminate(); // Clean up pigpio
    exit(EXIT_SUCCESS);
}

int main() {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, FAN_FREQ);

    while (1) {
        char temp_str[10];
        FILE *temp_file = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
        if (!temp_file) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        if (fgets(temp_str, sizeof(temp_str), temp_file) == NULL) {
            fprintf(stderr, "Failed to read temperature\n");
            fclose(temp_file);
            continue;
        }

        fclose(temp_file);

        int temp = atoi(temp_str);
        if (temp < TEMP_MIN) {
            temp = TEMP_MIN;
        } else if (temp > TEMP_MAX) {
            temp = TEMP_MAX;
        }

        int duty_cycle = (temp - TEMP_MIN) * (FAN_DUTY_MAX - FAN_DUTY_MIN) / (TEMP_MAX - TEMP_MIN) + FAN_DUTY_MIN;
        duty_cycle = (duty_cycle < FAN_DUTY_MIN) ? FAN_DUTY_MIN : (duty_cycle > FAN_DUTY_MAX) ? FAN_DUTY_MAX : duty_cycle;

        fprintf(log_file, "%ld %d %d\n", time(NULL), temp, duty_cycle);
        fflush(log_file);

        gpioPWM(FAN_GPIO, duty_cycle);

        sleep(LOG_INTERVAL / 1000); // Sleep for 5 seconds
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

