#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <gpiod.h>
#include <pigpio.h>

#define BUFFER_SIZE 60
#define TEMP_REGISTER 0x00
#define I2C_ADDR 0x48
#define I2C_BUS 1
#define GPIO_LED 18
#define DELAY_MS 1000

pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

int i2c_fd;
struct gpiod_line *led_line;

double temperature_buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void *temperature_reader(void *arg) {
    int ret;
    int16_t temp_raw;
    double temp_celsius;

    while (1) {
        ret = i2c_smbus_read_word_data(i2c_fd, TEMP_REGISTER);
        if (ret < 0) {
            fprintf(stderr, "Error reading temperature from sensor.\n");
            continue;
        }

        temp_raw = (int16_t)ret;
        temp_celsius = (double)temp_raw / 256.0;

        pthread_mutex_lock(&buffer_mutex);
        temperature_buffer[buffer_head] = temp_celsius;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        if (buffer_head == buffer_tail) {
            buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        }

        double running_avg = 0.0;
        for (int i = buffer_tail; i != buffer_head; i = (i + 1) % BUFFER_SIZE) {
            running_avg += temperature_buffer[i];
        }
        running_avg /= (buffer_head - buffer_tail);

        if (running_avg > 28.0) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(DELAY_MS * 1000);
    }

    return NULL;
}

int main() {
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d.\n", I2C_BUS);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address.\n");
        return 1;
    }

    if ((led_line = gpiod_line_request(GPIO_LED, "LED", GPIOD_LINE_DIRECTION_OUT)) == NULL) {
        fprintf(stderr, "Failed to request GPIO line %d.\n", GPIO_LED);
        return 1;
    }

    pthread_t reader_thread;
    if (pthread_create(&reader_thread, NULL, temperature_reader, NULL) != 0) {
        fprintf(stderr, "Failed to create thread.\n");
        return 1;
    }

    while (1) {
        sleep(1);
    }

    pthread_cancel(reader_thread);
    pthread_join(reader_thread, NULL);

    gpiod_line_free(led_line);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

