#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <json-c/json.h>

#define TARGET_TEMP 25.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define REF_RESISTANCE 430.0
#define PT100_NOMINAL 100.0
#define A 3.9083e-3
#define B -5.775e-7
#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define SPI_SPEED 500000
#define SPI_MODE 1
#define SPI_CS 0
#define SPI_READ_ADDR 0x01
#define SPI_FAULT_ADDR 0x07
#define SPI_CONFIG_ADDR 0x80
#define SPI_CONFIG_VALUE 0xC1

double calculate_temperature(uint32_t rtd_code) {
    double resistance = (double)rtd_code / 32768.0 * REF_RESISTANCE;
    double temperature = 0.0;
    if (resistance <= PT100_NOMINAL) {
        temperature = (resistance / PT100_NOMINAL - 1) / (A + B * (resistance / PT100_NOMINAL - 1));
    } else {
        double temp_squared = (resistance / PT100_NOMINAL - 1) / (A + B * (resistance / PT100_NOMINAL - 1));
        temperature = 1 / (A + B * temp_squared) - 273.15;
    }
    return temperature;
}

void handle_signal(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    exit(signum);
}

int main(int argc, char *argv[]) {
    json_object *json_config = NULL;
    json_object *target_temp_obj = NULL;
    json_object *kp_obj = NULL;
    json_object *ki_obj = NULL;
    json_object *kd_obj = NULL;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        exit(1);
    }

    json_config = json_tokener_parse_file(argv[1]);
    if (!json_config) {
        fprintf(stderr, "Failed to parse JSON config file\n");
        exit(1);
    }

    target_temp_obj = json_object_object_get(json_config, "target_temp");
    if (!target_temp_obj || !json_object_is_double(target_temp_obj)) {
        fprintf(stderr, "Invalid 'target_temp' in config file\n");
        exit(1);
    }
    TARGET_TEMP = json_object_get_double(target_temp_obj);

    kp_obj = json_object_object_get(json_config, "Kp");
    if (!kp_obj || !json_object_is_double(kp_obj)) {
        fprintf(stderr, "Invalid 'Kp' in config file\n");
        exit(1);
    }
    Kp = json_object_get_double(kp_obj);

    ki_obj = json_object_object_get(json_config, "Ki");
    if (!ki_obj || !json_object_is_double(ki_obj)) {
        fprintf(stderr, "Invalid 'Ki' in config file\n");
        exit(1);
    }
    Ki = json_object_get_double(ki_obj);

    kd_obj = json_object_object_get(json_config, "Kd");
    if (!kd_obj || !json_object_is_double(kd_obj)) {
        fprintf(stderr, "Invalid 'Kd' in config file\n");
        exit(1);
    }
    Kd = json_object_get_double(kd_obj);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    if (spiOpen(SPI_CS, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        exit(1);
    }

    if (spiWrite(SPI_CONFIG_ADDR, &SPI_CONFIG_VALUE, 1) < 0) {
        fprintf(stderr, "Failed to write to MAX31865 configuration register\n");
        exit(1);
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        uint8_t rtd_code_msb = 0;
        uint8_t rtd_code_lsb = 0;
        uint8_t fault_status = 0;

        if (spiRead(SPI_READ_ADDR, &rtd_code_msb, 1) < 0 ||
            spiRead(SPI_FAULT_ADDR, &fault_status, 1) < 0) {
            fprintf(stderr, "Failed to read from MAX31865\n");
            spiClose(SPI_CS);
            gpioTerminate();
            exit(1);
        }

        uint32_t rtd_code = (rtd_code_msb << 8) | rtd_code_lsb;
        if (rtd_code & 0x01) {
            fprintf(stderr, "Fault detected in MAX31865\n");
            spiClose(SPI_CS);
            gpioTerminate();
            exit(1);
        }

        double current_temp = calculate_temperature(rtd_code);
        if (current_temp > 80.0) {
            fprintf(stderr, "Temperature exceeds 80°C, shutting down\n");
            spiClose(SPI_CS);
            gpioTerminate();
            exit(1);
        }

        double error = TARGET_TEMP - current_temp;
        double p_term = Kp * error;
        double i_term = Ki * (error + previous_error);
        double d_term = Kd * (error - previous_error) / 0.1;
        double duty_cycle = p_term + i_term + d_term;

        if (duty_cycle < 0) {
            duty_cycle = 0;
        } else if (duty_cycle > 100) {
            duty_cycle = 100;
        }

        gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);
        gpioSetPWMrange(PWM_PIN, PWM_RANGE);
        gpioPWM(PWM_PIN, duty_cycle);

        previous_error = error;
        usleep(100000);
    }

    spiClose(SPI_CS);
    gpioTerminate();
    return 0;
}

