    if (!ki_obj || !json_object_is_double(ki_obj)) {
        fprintf(stderr, "Invalid 'Ki' in config file\n");
        exit(1);
    }
    Ki = json_object_get_double(ki_obj);

    kd_obj = json_object_object_get(json_config, "Kd");
    if (!kd_obj || !json_object_is_double(kd_obj)) {
        fprintf(stderr, "Invalid 'Kd' in config file\n");
        exit(1);
    }
    Kd = json_object_get_double(kd_obj);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    if (spiOpen(SPI_CS, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        exit(1);
    }

    if (spiWrite(SPI_CONFIG_ADDR, &SPI_CONFIG_VALUE, 1) < 0) {
        fprintf(stderr, "Failed to write to MAX31865 configuration register\n");
        exit(1);
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        uint8_t rtd_code_msb = 0;
        uint8_t rtd_code_lsb = 0;
        uint8_t fault_status = 0;

        if (spiRead(SPI_READ_ADDR, &rtd_code_msb, 1) < 0 ||
            spiRead(SPI_FAULT_ADDR, &fault_status, 1) < 0) {
            fprintf(stderr, "Failed to read from MAX31865\n");
            spiClose(SPI_CS);
            gpioTerminate();
            exit(1);
        }

        uint32_t rtd_code = (rtd_code_msb << 8) | rtd_code_lsb;
        if (rtd_code & 0x01) {
            fprintf(stderr, "Fault detected in MAX31865\n");
            spiClose(SPI_CS);
            gpioTerminate();
            exit(1);
        }

        double current_temp = calculate_temperature(rtd_code);
        if (current_temp > 80.0) {
            fprintf(stderr, "Temperature exceeds 80°C, shutting down\n");
            spiClose(SPI_CS);
            gpioTerminate();
            exit(1);
        }

        double error = TARGET_TEMP - current_temp;
        double p_term = Kp * error;
        double i_term = Ki * (error + previous_error);
        double d_term = Kd * (error - previous_error) / 0.1;
        double duty_cycle = p_term + i_term + d_term;

        if (duty_cycle < 0) {
            duty_cycle = 0;
        } else if (duty_cycle > 100) {
            duty_cycle = 100;
        }

        gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);
        gpioSetPWMrange(PWM_PIN, PWM_RANGE);
        gpioPWM(PWM_PIN, duty_cycle);

        previous_error = error;
        usleep(100000);
    }

    spiClose(SPI_CS);
    gpioTerminate();
    return 0;
}
