#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define BMP180_ADDRESS 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_TEMP 0xF6
#define BMP180_REG_PRESSURE 0xF6
#define BMP180_REG_CAL_START 0xAA
#define BMP180_REG_CAL_END 0xAC
#define BMP180_OSS 0
#define BMP180_TEMP_READING_TIME 5 // ms
#define BMP180_PRESSURE_READING_TIME (5 + (BMP180_OSS * 5)) // ms
#define BUFFER_SIZE 60
#define BUFFER_INDEX_INCREMENT 1
#define BUFFER_INDEX_RESET 0
#define FAN_GPIO 18

typedef struct {
    int calibration[11];
} BMP180_Calibration;

typedef struct {
    double temperature;
    double pressure;
    uint32_t timestamp;
} BMP180_Reading;

BMP180_Calibration calibration;
BMP180_Reading buffer[BUFFER_SIZE];
int buffer_index = BUFFER_INDEX_RESET;

void read_calibration(int handle) {
    int i;
    for (i = 0; i < 11; i++) {
        int reg = BMP180_REG_CAL_START + i;
        int value = i2cRead(handle, reg, 1);
        if (value < 0) {
            fprintf(stderr, "Error reading calibration data from register 0x%02X\n", reg);
            return;
        }
        calibration.calibration[i] = value;
    }
}

void read_temperature(int handle) {
    int reg = BMP180_REG_CONTROL;
    i2cWrite(handle, reg, 0x2E); // Start temperature measurement
    usleep(BMP180_TEMP_READING_TIME * 1000); // Wait for measurement
    int temp_msb = i2cRead(handle, BMP180_REG_TEMP, 1);
    int temp_lsb = i2cRead(handle, BMP180_REG_TEMP + 1, 1);
    int temp_xlsb = i2cRead(handle, BMP180_REG_TEMP + 2, 1);
    if (temp_msb < 0 || temp_lsb < 0 || temp_xlsb < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return;
    }
    int temp_raw = (temp_msb << 16) | (temp_lsb << 8) | temp_xlsb;
    double temp_c = (double)temp_raw / 16384.0 - 273.15;
    buffer[buffer_index].temperature = temp_c;
}

void read_pressure(int handle) {
    int reg = BMP180_REG_CONTROL;
    i2cWrite(handle, reg, 0x34 + (BMP180_OSS << 6)); // Start pressure measurement
    usleep(BMP180_PRESSURE_READING_TIME * 1000); // Wait for measurement
    int pres_msb = i2cRead(handle, BMP180_REG_PRESSURE, 1);
    int pres_lsb = i2cRead(handle, BMP180_REG_PRESSURE + 1, 1);
    int pres_xlsb = i2cRead(handle, BMP180_REG_PRESSURE + 2, 1);
    if (pres_msb < 0 || pres_lsb < 0 || pres_xlsb < 0) {
        fprintf(stderr, "Error reading pressure data\n");
        return;
    }
    int pres_raw = (pres_msb << 16) | (pres_lsb << 8) | pres_xlsb;
    double pres_x1 = ((double)pres_raw / 131072.0 - (double)calibration.calibration[6] / 1024.0) * (double)calibration.calibration[2];
    double pres_x2 = ((double)calibration.calibration[4] * 65536.0) * ((double)calibration.calibration[4] * 0.125) * ((double)pres_x1 * (double)pres_x1 * 0.000000390625);
    double pres_x3 = ((double)calibration.calibration[3] * 524288.0) * ((double)pres_x1 * (double)pres_x1 * 0.0000000009765625);
    double pres_x = (double)pres_x1 + (double)pres_x2 + (double)pres_x3 + ((double)calibration.calibration[1] * 2.0);
    double pres_y = ((double)calibration.calibration[5] * 4096.0) * ((double)pres_x * (double)pres_x * 0.0000000009765625);
    double pres_z = ((double)calibration.calibration[7] * 16.0) * (double)pres_x;
    double pres_d = ((double)calibration.calibration[8] * 128.0) * (double)pres_x * (double)pres_x * 0.0000000000152587890625;
    double pres_p = ((double)(pres_x + pres_y) / (double)(pres_z - pres_d)) * (1.0 + (double)calibration.calibration[9] * 0.00000003125);
    double pres_final = (double)pres_p * (1.0 - (double)calibration.calibration[10] * 0.00000003125);
    buffer[buffer_index].pressure = pres_final * 100.0; // Convert to Pa
}

void timer_callback(int gpio, int level, uint32_t tick) {
    buffer[buffer_index].timestamp = tick;
    read_temperature(1);
    read_pressure(1);
    if (buffer[buffer_index].temperature > 30.0) {
        gpioWrite(FAN_GPIO, PI_ON);
    } else {
        gpioWrite(FAN_GPIO, PI_OFF);
    }
    printf("Timestamp: %u, Temperature: %.2f°C, Pressure: %.2f Pa\n", buffer[buffer_index].timestamp, buffer[buffer_index].temperature, buffer[buffer_index].pressure);
    buffer_index = (buffer_index + BUFFER_INDEX_INCREMENT) % BUFFER_SIZE;
}

void handle_signal(int signum) {
    gpioWrite(FAN_GPIO, PI_OFF);
    i2cClose(1);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    if (i2cOpen(1, BMP180_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }
    read_calibration(1);
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        return 1;
    }
    gpioWrite(FAN_GPIO, PI_OFF);
    if (gpioSetTimerFunc(500, timer_callback) < 0) {
        fprintf(stderr, "Failed to set timer callback\n");
        return 1;
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    while (1) {
        gpioSleep(1000000); // Sleep indefinitely
    }
    return 0;
}

