    if (pres_msb < 0 || pres_lsb < 0 || pres_xlsb < 0) {
        fprintf(stderr, "Error reading pressure data\n");
        return;
    }
    int pres_raw = (pres_msb << 16) | (pres_lsb << 8) | pres_xlsb;
    double pres_x1 = ((double)pres_raw / 131072.0 - (double)calibration.calibration[6] / 1024.0) * (double)calibration.calibration[2];
    double pres_x2 = ((double)calibration.calibration[4] * 65536.0) * ((double)calibration.calibration[4] * 0.125) * ((double)pres_x1 * (double)pres_x1 * 0.000000390625);
    double pres_x3 = ((double)calibration.calibration[3] * 524288.0) * ((double)pres_x1 * (double)pres_x1 * 0.0000000009765625);
    double pres_x = (double)pres_x1 + (double)pres_x2 + (double)pres_x3 + ((double)calibration.calibration[1] * 2.0);
    double pres_y = ((double)calibration.calibration[5] * 4096.0) * ((double)pres_x * (double)pres_x * 0.0000000009765625);
    double pres_z = ((double)calibration.calibration[7] * 16.0) * (double)pres_x;
    double pres_d = ((double)calibration.calibration[8] * 128.0) * (double)pres_x * (double)pres_x * 0.0000000000152587890625;
    double pres_p = ((double)(pres_x + pres_y) / (double)(pres_z - pres_d)) * (1.0 + (double)calibration.calibration[9] * 0.00000003125);
    double pres_final = (double)pres_p * (1.0 - (double)calibration.calibration[10] * 0.00000003125);
    buffer[buffer_index].pressure = pres_final * 100.0; // Convert to Pa
}

void timer_callback(int gpio, int level, uint32_t tick) {
    buffer[buffer_index].timestamp = tick;
    read_temperature(1);
    read_pressure(1);
    if (buffer[buffer_index].temperature > 30.0) {
        gpioWrite(FAN_GPIO, PI_ON);
    } else {
        gpioWrite(FAN_GPIO, PI_OFF);
    }
    printf("Timestamp: %u, Temperature: %.2f°C, Pressure: %.2f Pa\n", buffer[buffer_index].timestamp, buffer[buffer_index].temperature, buffer[buffer_index].pressure);
    buffer_index = (buffer_index + BUFFER_INDEX_INCREMENT) % BUFFER_SIZE;
}

void handle_signal(int signum) {
    gpioWrite(FAN_GPIO, PI_OFF);
    i2cClose(1);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    if (i2cOpen(1, BMP180_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }
    read_calibration(1);
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        return 1;
    }
    gpioWrite(FAN_GPIO, PI_OFF);
    if (gpioSetTimerFunc(500, timer_callback) < 0) {
        fprintf(stderr, "Failed to set timer callback\n");
        return 1;
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    while (1) {
        gpioSleep(1000000); // Sleep indefinitely
    }
    return 0;
}
