    printf("Logging %sabled.\n", logging_enabled ? "en" : "dis");
}

void read_calibration_data(int *ac1, int *ac2, int *ac3, unsigned int *ac4, unsigned int *ac5, unsigned int *ac6, int *b1, int *b2, int *mb, int *mc, int *md) {
    char buffer[256];
    int i;

    for (i = 0; i < 11; i++) {
        switch (i) {
            case 0: *ac1 = read_i2c_byte(BMP180_REG_CAL_AC1); break;
            case 1: *ac2 = read_i2c_byte(BMP180_REG_CAL_AC2); break;
            case 2: *ac3 = read_i2c_byte(BMP180_REG_CAL_AC3); break;
            case 3: *ac4 = read_i2c_word(BMP180_REG_CAL_AC4); break;
            case 4: *ac5 = read_i2c_word(BMP180_REG_CAL_AC5); break;
            case 5: *ac6 = read_i2c_word(BMP180_REG_CAL_AC6); break;
            case 6: *b1 = read_i2c_byte(BMP180_REG_CAL_B1); break;
            case 7: *b2 = read_i2c_byte(BMP180_REG_CAL_B2); break;
            case 8: *mb = read_i2c_byte(BMP180_REG_CAL_MB); break;
            case 9: *mc = read_i2c_byte(BMP180_REG_CAL_MC); break;
            case 10: *md = read_i2c_byte(BMP180_REG_CAL_MD); break;
        }
    }
}

unsigned int read_i2c_byte(unsigned char reg) {
    char buffer[2];
    int bytes_read;

    buffer[0] = reg;
    bytes_read = write(i2c_fd, buffer, 1);
    if (bytes_read != 1) {
        perror("Error writing to I2C device");
        exit(EXIT_FAILURE);
    }

    bytes_read = read(i2c_fd, buffer, 1);
    if (bytes_read != 1) {
        perror("Error reading from I2C device");
        exit(EXIT_FAILURE);
    }

    return (unsigned int)buffer[0];
}

unsigned int read_i2c_word(unsigned char reg) {
    char buffer[2];
    int bytes_read;

    buffer[0] = reg;
    bytes_read = write(i2c_fd, buffer, 1);
    if (bytes_read != 1) {
        perror("Error writing to I2C device");
        exit(EXIT_FAILURE);
    }

    bytes_read = read(i2c_fd, buffer, 2);
    if (bytes_read != 2) {
        perror("Error reading from I2C device");
        exit(EXIT_FAILURE);
    }

    return (unsigned int)((buffer[1] << 8) | buffer[0]);
}

unsigned int read_pressure() {
    char buffer[3];
    int bytes_read;

    buffer[0] = BMP180_REG_CONTROL | BMP180_OVERSAMPLING_CONFIG_1;
    bytes_read = write(i2c_fd, buffer, 1);
    if (bytes_read != 1) {
        perror("Error writing to I2C device");
        exit(EXIT_FAILURE);
    }

    usleep(5 * 1000); // Wait for conversion

    buffer[0] = BMP180_REG_DATA;
    bytes_read = write(i2c_fd, buffer, 1);
    if (bytes_read != 1) {
        perror("Error writing to I2C device");
        exit(EXIT_FAILURE);
    }

    bytes_read = read(i2c_fd, buffer, 3);
    if (bytes_read != 3) {
        perror("Error reading from I2C device");
        exit(EXIT_FAILURE);
    }

    unsigned int msb = buffer[0];
    unsigned int lsb = buffer[1];
    unsigned int xlsb = buffer[2];

    unsigned int raw_pressure = ((msb << 16) | (lsb << 8) | xlsb);

    return raw_pressure;
}

double calculate_pressure(unsigned int raw_pressure, int ac1, int ac2, int ac3, unsigned int ac4, unsigned int ac5, unsigned int ac6, int b1, int b2, int mb, int mc, int md) {
    double x1, x2, x3, b3, b4, b5, b6;

    x1 = ((double)(raw_pressure - ac6)) * ac5 / (1 << 15);
    x2 = ((double)mc * (1 << 11)) / (x1 + md);
    x3 = (double)b1 * ((x2 * (x2 * (double)b2)) / (1 << 12)) / (1 << 14);
    b5 = x1 + x3;
    b6 = ((double)ac2 * (1 << 11)) / (b5 + ac4);
    b3 = ((double)(1 << 16) * (b2 - b6 * (b2 - (double)ac2)) / (1 << 12)) / (1 << 14);
    b4 = ((double)ac4 * (unsigned long long)(b6 * (b6 * (double)b3) / (1 << 13)) / (1 << 16)) / (1 << 14);
    b7 = ((unsigned long long)raw_pressure - b5) * (50000 >> 8);
    if (b7 < 0x80000000)
        pressure = (b7 < 0) ? (b7 * 2) / (b4 + b7) : (b7 / (b4 + b7)) * 2;
    else
        pressure = (b7 / (b4 + b7)) * 2;

    x1 = (pressure / (1 << 8)) * (pressure / (1 << 8));
    x1 = (x1 * 3038) / (1 << 16);
    x2 = (-7357 * pressure) / (1 << 16);
    pressure += (x1 + x2 + 3791) / (1 << 4);

    return pressure;
}

int main() {
    int ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md;
    unsigned int raw_pressure;
    double pressure;
    struct timespec ts;
    struct sigaction sa;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if ((i2c_fd = open(BMP180_I2C_FILE, O_RDWR)) < 0) {
        perror("Error opening I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Error setting I2C device address");
        return EXIT_FAILURE;
    }

    read_calibration_data(&ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md);

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        if (logging_enabled) {
            raw_pressure = read_pressure();
            pressure = calculate_pressure(raw_pressure, ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md);

            ts.tv_sec = time(NULL);
            ts.tv_nsec = 0;

            FILE *file = fopen("pressure_log.txt", "a");
            if (file == NULL) {
                perror("Error opening log file");
                continue;
            }

            fprintf(file, "%ld.%09ld: %.2f Pa\n", ts.tv_sec, ts.tv_nsec, pressure);
            fclose(file);
        }

        if (logging_enabled) {
            nanosleep(&ts, NULL);
        } else {
            usleep(200 * 1000); // Debounce delay
        }

        if (gpioTick(27) == 0) {
            toggle_logging();
        }
    }

    return EXIT_SUCCESS;
}

