#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TARGET_TEMP 25.0
#define MAX_DUTY_CYCLE 80
#define SPI_SPEED 2000000
#define SPI_CHANNEL 0
#define GPIO_HEATER 17
#define GPIO_CS 8
#define GPIO_MISO 9
#define GPIO_MOSI 10
#define GPIO_SCLK 11

double temperature = 0.0;
double setpoint = TARGET_TEMP;
double integral = 0.0;
double last_error = 0.0;
double Kp = 1.0;
double Ki = 0.1;

void spi_read_temperature() {
    int spi_fd = spi_open(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        exit(EXIT_FAILURE);
    }

    uint8_t data[4];
    if (spi_read(spi_fd, data, 4) != 4) {
        fprintf(stderr, "Failed to read temperature data\n");
        spi_close(spi_fd);
        return;
    }

    temperature = (double)data[0] * 256 + (double)data[1];
    temperature -= 273.15; // Convert from Kelvin to Celsius

    spi_close(spi_fd);
}

void handle_signal(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    gpioWrite(GPIO_HEATER, PI_OUTPUT_LOW);
    gpioTerminate();

    exit(EXIT_SUCCESS);
}

void log_data(double temperature, double duty_cycle) {
    FILE *log_file = fopen("heater_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d,%.2f,%.2f\n",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
            temperature, duty_cycle);

    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_HEATER, PI_OUTPUT);
    gpioWrite(GPIO_HEATER, PI_OUTPUT_LOW);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        spi_read_temperature();

        if (temperature < 0.0 || temperature > 100.0) {
            fprintf(stderr, "Invalid temperature reading: %.2f\n", temperature);
            continue;
        }

        double error = setpoint - temperature;
        integral += error * 0.1; // Assuming a 100ms loop

        double duty_cycle = Kp * error + Ki * integral;
        if (duty_cycle > MAX_DUTY_CYCLE) {
            duty_cycle = MAX_DUTY_CYCLE;
        }

        if (duty_cycle < 0.0) {
            duty_cycle = 0.0;
        }

        gpioSetPWMfrequency(GPIO_HEATER, 1000); // 1kHz PWM frequency
        gpioSetPWMrange(GPIO_HEATER, 100); // 0-100% duty cycle
        gpioPWM(GPIO_HEATER, (int)(duty_cycle * 100 / 100.0));

        log_data(temperature, duty_cycle);

        sleep(1); // 1 second loop
    }

    return 0;
}

