#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_PIN 4
#define MAX_RETRIES 3
#define URL "http://yourserver.com/api/humidity"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int read_sensor(void) {
    int retries = 0;
    int result = -1;

    while (!stop_flag && retries < MAX_RETRIES) {
        if (result == -1) {
            result = read_dht22(DHT22_PIN);
        }

        if (result == -1) {
            printf("Error reading sensor, retrying... (%d/%d)\n", retries + 1, MAX_RETRIES);
            sleep(1);
            retries++;
        } else {
            break;
        }
    }

    return result;
}

int read_dht22(int pin) {
    int data[5];
    int checksum = 0;
    int i;

    // Start signal
    gpioWrite(pin, PI_OUTPUT);
    gpioLow(pin);
    usleep(1000);
    gpioHigh(pin);
    usleep(20);
    gpioSetMode(pin, PI_INPUT);

    // Read 40 bits
    for (i = 0; i < 40; i++) {
        int bit = 0;
        int count = 0;

        while (gpioRead(pin) == 0) {
            count++;
            if (count > 10000) {
                return -1; // Timeout
            }
        }

        while (gpioRead(pin) == 1) {
            count++;
            if (count > 10000) {
                return -1; // Timeout
            }
        }

        if (count > 80) {
            bit = 1;
        }

        data[i / 8] <<= 1;
        data[i / 8] |= bit;
    }

    // Validate checksum
    for (i = 0; i < 4; i++) {
        checksum += data[i];
    }

    if (data[4] != (checksum & 0xFF)) {
        return -1; // Checksum error
    }

    // Parse data
    int humidity = (data[0] << 8) | data[1];
    int temperature = (data[2] << 8) | data[3];

    printf("Humidity: %d, Temperature: %d\n", humidity, temperature);

    // Send HTTP POST request
    CURL *curl;
    CURLcode res;
    char payload[100];
    sprintf(payload, "{\"humidity\": %d, \"temperature\": %d}", humidity, temperature);

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, URL);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
        res = curl_easy_perform(curl);
        curl_easy_cleanup(curl);

        if (res != CURLE_OK) {
            printf("Error sending HTTP POST request: %s\n", curl_easy_strerror(res));
            return -1;
        }
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        if (read_sensor() == -1) {
            printf("Failed to read sensor data.\n");
        }
        sleep(5); // Read every 5 seconds
    }

    gpioTerminate();
    return 0;
}

