#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CAL1 0xAA
#define BMP180_REG_CAL2 0xAC
#define BMP180_REG_CAL3 0xAE
#define BMP180_REG_CAL4 0xB0
#define BMP180_REG_CAL5 0xB2
#define BMP180_REG_CAL6 0xB4
#define BMP180_REG_CAL7 0xB6
#define BMP180_REG_P_MSB 0xF6
#define BMP180_REG_P_LSB 0xF7
#define BMP180_REG_P_XLSB 0xF8
#define BMP180_REG_CONTROL 0xF4
#define BMP180_OSS_3 0x03
#define BMP180_CONVERSION_DELAY 26

int logging_enabled = 0;

void bmp180_read_calibration(int *cal_data) {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 7; i++) {
        int reg = BMP180_REG_CAL1 + i;
        if (read(i2c_fd, &cal_data[i], 1) != 1) {
            perror("Failed to read calibration data");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }
    }

    close(i2c_fd);
}

int bmp180_read_pressure(int *pressure) {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        return -1;
    }

    if (write(i2c_fd, &BMP180_REG_CONTROL, 1) != 1) {
        perror("Failed to write control register");
        close(i2c_fd);
        return -1;
    }

    usleep(BMP180_CONVERSION_DELAY * 1000);

    if (write(i2c_fd, &BMP180_REG_P_MSB, 1) != 1) {
        perror("Failed to read pressure MSB");
        close(i2c_fd);
        return -1;
    }

    if (read(i2c_fd, pressure, 3) != 3) {
        perror("Failed to read pressure data");
        close(i2c_fd);
        return -1;
    }

    close(i2c_fd);

    *pressure = (*pressure << 8) | (*pressure >> 8);
    return 0;
}

void bmp180_compensate(int cal_data[7], int raw_pressure, int *compensated_pressure) {
    int x1, x2, x3, b3, b4, b5, b6, b7, p;

    x1 = ((raw_pressure >> 3) - ((int32_t)cal_data[3] << 1)) * ((int32_t)cal_data[1]) >> 14;
    x2 = ((int32_t)cal_data[2] >> 8) * ((raw_pressure >> 4) - ((int32_t)cal_data[3] << 3)) >> 13;
    x3 = ((int32_t)cal_data[2] >> 8) * ((raw_pressure >> 4) - ((int32_t)cal_data[3] << 3)) >> 13;
    b3 = (((int32_t)cal_data[1] * (x1 + x2)) >> 15) + ((int32_t)cal_data[4] << 3);
    b4 = ((int32_t)cal_data[6] << 7) - b3;
    b5 = ((int32_t)cal_data[5] << 1) + ((int32_t)cal_data[7] >> 7);
    b6 = b5 - ((int32_t)cal_data[4] << 1);
    b7 = ((int32_t)cal_data[6] << 14) - b6 * ((int32_t)cal_data[6] >> 6);
    p = (b7 >> 15) * 2;

    if (b7 < 0x80000000) {
        p = (p << 1) + ((b7 & 0x7FFF) * 3038);
    } else {
        p = (p << 1) - ((0x80000000 - b7) * 3038);
    }

    *compensated_pressure = (p + 0x8000) >> 15;
}

void bmp180_isr(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    if (level == 0 && (tick - last_tick) >= 200000) {
        last_tick = tick;
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
    }
}

int main() {
    int cal_data[7];
    int raw_pressure;
    int compensated_pressure;
    int i2c_fd;
    int status;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    bmp180_read_calibration(cal_data);

    if (gpioSetMode(4, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO4 as input\n");
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(4, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO4 pull-up\n");
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(4, PI_ISR_FALLING_EDGE, bmp180_isr, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO4 ISR\n");
        return EXIT_FAILURE;
    }

    while (1) {
        if (logging_enabled) {
            if (bmp180_read_pressure(&raw_pressure) == 0) {
                bmp180_compensate(cal_data, raw_pressure, &compensated_pressure);

                time_t now = time(NULL);
                struct tm *now_tm = localtime(&now);

                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

                FILE *log_file = fopen("pressure_log.txt", "a");
                if (log_file == NULL) {
                    perror("Failed to open log file");
                    continue;
                }

                fprintf(log_file, "%s %d\n", timestamp, compensated_pressure);
                fclose(log_file);
            }
        }

        usleep(2000000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

