#define DEFAULT_SERVER_URL "http://your-server.com/api/humidity"
#define MAX_RETRIES 3
#define BACKOFF_TIME 2000 // 2 seconds

static char *server_url = DEFAULT_SERVER_URL;

void handle_sigint(int signum) {
    syslog(LOG_INFO, "Received SIGINT, shutting down...");
    gpioTerminate();
    curl_global_cleanup();
    exit(0);
}

void handle_sigterm(int signum) {
    syslog(LOG_INFO, "Received SIGTERM, shutting down...");
    gpioTerminate();
    curl_global_cleanup();
    exit(0);
}

int read_humidity() {
    int humidity = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int data_bits[40];
        int checksum = 0;

        // Start signal
        gpioWrite(4, PI_OUTPUT);
        usleep(1000);
        gpioWrite(4, PI_LOW);
        usleep(20000);
        gpioWrite(4, PI_HIGH);
        usleep(40000);
        gpioWrite(4, PI_LOW);

        // Read 40 bits
        for (int i = 0; i < 40; i++) {
            int start_time = gpioTick();
            while (gpioRead(4) == PI_LOW) {
                if (gpioTickDiff(start_time) > 1000000) {
                    syslog(LOG_ERR, "Timeout reading humidity data");
                    return -1;
                }
            }
            int end_time = gpioTick();
            if (gpioTickDiff(start_time) < 20000) {
                data_bits[i] = 0;
            } else {
                data_bits[i] = 1;
            }
        }

        // Calculate checksum
        for (int i = 0; i < 40; i += 8) {
            checksum += data_bits[i];
            checksum += data_bits[i + 1];
            checksum += data_bits[i + 2];
            checksum += data_bits[i + 3];
            checksum += data_bits[i + 4];
            checksum += data_bits[i + 5];
            checksum += data_bits[i + 6];
            checksum += data_bits[i + 7];
        }
        checksum &= 0xFF;

        // Validate checksum
        if (data_bits[39] == (checksum & 0xFF)) {
            humidity = (data_bits[0] << 8) | data_bits[1];
            return humidity;
        }

        syslog(LOG_INFO, "Checksum failed, retrying...");
        retries++;
        sleep(BACKOFF_TIME / 1000);
    }

    syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
    return -1;
}

void post_humidity(int humidity) {
    CURL *curl;
    CURLcode res;
    char payload[100];
    char *json_payload = "{\"humidity\":%d}";

    sprintf(payload, json_payload, humidity);

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, server_url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, "Content-Type: application/json");

        int retries = 0;
        while (retries < MAX_RETRIES) {
            res = curl_easy_perform(curl);
            if (res == CURLE_OK) {
                int response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    break;
                }
                syslog(LOG_ERR, "HTTP error %d, retrying...", response_code);
            } else {
                syslog(LOG_ERR, "Network error %d, retrying...", res);
            }
            retries++;
            sleep(BACKOFF_TIME / 1000);
        }

        if (retries == MAX_RETRIES) {
            syslog(LOG_ERR, "Failed to post humidity after %d retries", MAX_RETRIES);
        }

        curl_easy_cleanup(curl);
    } else {
        syslog(LOG_ERR, "Failed to initialize libcurl");
    }
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = handle_sigterm;
    sigaction(SIGTERM, &sa, NULL);

    if (argc > 1 && strcmp(argv[1], "-s") == 0) {
        if (argc > 2) {
            server_url = argv[2];
        } else {
            syslog(LOG_ERR, "Missing URL after -s option");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    gpioSetMode(4, PI_INPUT);

    while (1) {
        int humidity = read_humidity();
        if (humidity >= 0) {
            post_humidity(humidity);
        }
        sleep(10);
    }

    return 0;
}

