void log_fan_state_change(int new_state) {
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    if (new_state != last_fan_state) {
        snprintf(buffer, sizeof(buffer), "Fan state changed to %d at %s", new_state, asctime(timeinfo));
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file != NULL) {
            fprintf(log_file, "%s", buffer);
            fclose(log_file);
        } else {
            perror("Failed to open log file");
        }
        last_fan_state = new_state;
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        int fd = open(FAN_STATE_FILE, O_WRONLY);
        if (fd != -1) {
            char state_str[10];
            snprintf(state_str, sizeof(state_str), "%d", 0);
            write(fd, state_str, strlen(state_str));
            close(fd);
            log_fan_state_change(0);
            printf("Received signal %d, shutting down fan and exiting.\n", signum);
        } else {
            perror("Failed to open fan state file for shutdown");
        }
        exit(0);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int max_state_fd = open(MAX_STATE_FILE, O_RDONLY);
    if (max_state_fd == -1) {
        perror("Failed to open max state file");
        return 1;
    }

    char max_state_str[10];
    ssize_t bytes_read = read(max_state_fd, max_state_str, sizeof(max_state_str) - 1);
    if (bytes_read == -1) {
        perror("Failed to read max state");
        close(max_state_fd);
        return 1;
    }
    max_state_str[bytes_read] = '\0';
    max_state = atoi(max_state_str);
    close(max_state_fd);

    while (1) {
        int temp_fd = open(TEMP_FILE, O_RDONLY);
        if (temp_fd == -1) {
            perror("Failed to open temperature file");
            sleep(5);
            continue;
        }

        char temp_str[10];
        bytes_read = read(temp_fd, temp_str, sizeof(temp_str) - 1);
        if (bytes_read == -1) {
            perror("Failed to read temperature");
            close(temp_fd);
            sleep(5);
            continue;
        }
        temp_str[bytes_read] = '\0';
        int temp = atoi(temp_str);
        close(temp_fd);

        int new_state = 0;
        if (temp >= 6500) {
            new_state = 3;
        } else if (temp >= 5500) {
            new_state = 2;
        } else if (temp >= 4500) {
            new_state = 1;
        }

        if (new_state > max_state) {
            new_state = max_state;
        }

        if (new_state != fan_state) {
            int fan_state_fd = open(FAN_STATE_FILE, O_WRONLY);
            if (fan_state_fd == -1) {
                perror("Failed to open fan state file");
                sleep(5);
                continue;
            }

            char state_str[10];
            snprintf(state_str, sizeof(state_str), "%d", new_state);
            write(fan_state_fd, state_str, strlen(state_str));
            close(fan_state_fd);

            fan_state = new_state;
            log_fan_state_change(fan_state);
        }

        sleep(5);
    }

    return 0;
}

