volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

void spi_read_temp() {
    uint8_t data[4];
    int status;

    status = spi_read(SPI_DO, data, 4, SPI_SPEED);
    if (status != 4) {
        fprintf(stderr, "SPI read error: %d\n", status);
        return;
    }

    int32_t temp = (data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3];
    if (temp & 0x80000000) {
        fprintf(stderr, "Thermocouple fault detected\n");
        return;
    }

    double temperature = (double)temp * 0.25;
    if (temperature > 100.0 || temperature < 0.0) {
        fprintf(stderr, "Temperature out of range: %.2f°C\n", temperature);
        return;
    }

    printf("Temperature: %.2f°C\n", temperature);
}

void pid_control(double target, double *error, double *integral, double *derivative, double *output) {
    *error = target - spi_read_temp();
    *integral += *error;
    *derivative = *error - *previous_error;
    *previous_error = *error;

    *output = Kp * *error + Ki * *integral + Kd * *derivative;

    if (*output < 0) *output = 0;
    if (*output > 100) *output = 100;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    double error = 0.0, integral = 0.0, derivative = 0.0, output = 0.0;
    double previous_error = 0.0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        pid_control(TARGET_TEMP, &error, &integral, &derivative, &output);
        gpioPWM(PWM_PIN, output);

        sleep(1);
    }

    gpioPWM(PWM_PIN, 0);
    spiClose();
    gpioTerminate();

    return 0;
}
```

This code sets up a PID controller using the pigpio library to control a resistive heater on GPIO18. It reads temperature from a MAX31855 thermocouple amplifier over SPI0 and logs the temperature, PWM duty cycle, and PID output to `heater_log.txt` every second. It handles SPI communication errors and thermocouple faults by parsing the MAX31855 fault bits, logging errors, disabling the heater, and resetting the PID state. It also includes a failsafe that disables the heater if the temperature reading exceeds 100°C or falls below 0°C. On SIGINT/SIGTERM, it disables the heater, closes the SPI, and terminates pigpio.

