#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define MEASUREMENT_CMD 0x3608
#define DATA_BYTES 3
#define CRC_OFFSET 1
#define FLOW_RATE_SCALE 0.01

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int read_sensor(int sensor_addr) {
    int i2c_handle = i2cOpen(I2C_BUS, sensor_addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus for sensor at address 0x%02X\n", sensor_addr);
        return -1;
    }

    int retries = 3;
    while (retries > 0) {
        int data[DATA_BYTES];
        int result = i2cRead(i2c_handle, MEASUREMENT_CMD, data, DATA_BYTES);
        if (result == DATA_BYTES) {
            int crc = data[CRC_OFFSET];
            int calculated_crc = 0;
            for (int i = 0; i < CRC_OFFSET; i++) {
                calculated_crc = (calculated_crc << 1) ^ ((calculated_crc & 0x80) ? 0x07 : 0);
                calculated_crc ^= data[i];
            }
            if (crc == calculated_crc) {
                i2cClose(i2c_handle);
                return data[0] * data[1] * FLOW_RATE_SCALE;
            }
        }
        retries--;
        if (retries > 0) {
            sleep(1);
        }
    }
    i2cClose(i2c_handle);
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("flow_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (!stop_flag) {
        time_t rawtime;
        struct tm *timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S,", log_file);

        double flow1 = read_sensor(SENSOR1_ADDR);
        double flow2 = read_sensor(SENSOR2_ADDR);

        if (flow1 >= 0 && flow2 >= 0) {
            fprintf(log_file, "%.2f,%.2f\n", flow1, flow2);
        }

        sleep(1);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

