#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define CHANNEL_A 17
#define CHANNEL_B 18
#define FILE_NAME "encoder_log.txt"

typedef enum {
    STATE_00,
    STATE_01,
    STATE_10,
    STATE_11
} EncoderState;

EncoderState current_state = STATE_00;
int last_state = 0;
int pulses = 0;
double angle = 0.0;

void handle_interrupt(int gpio, int level, uint32_t tick) {
    EncoderState new_state = (level & (1 << CHANNEL_A)) ? (level & (1 << CHANNEL_B)) ? STATE_11 : STATE_10 : (level & (1 << CHANNEL_B)) ? STATE_01 : STATE_00;

    if (new_state != current_state) {
        current_state = new_state;

        if (current_state == STATE_01 && last_state == STATE_00) {
            pulses++;
            angle = (pulses % 360) * (360.0 / 360.0);
        } else if (current_state == STATE_10 && last_state == STATE_11) {
            pulses--;
            angle = (pulses % 360) * (360.0 / 360.0);
        }

        last_state = current_state;

        FILE *file = fopen(FILE_NAME, "a");
        if (file == NULL) {
            fprintf(stderr, "Failed to open file for logging.\n");
            return;
        }

        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        fprintf(file, "%s %.2f\n", asctime(timeinfo), angle);
        fclose(file);
    }
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(CHANNEL_A, PI_INPUT) < 0 || gpioSetMode(CHANNEL_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(CHANNEL_A, PI_PUD_UP) < 0 || gpioSetPullUpDown(CHANNEL_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistors.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(CHANNEL_A, EITHER_EDGE, handle_interrupt) < 0 ||
        gpioSetISRFunc(CHANNEL_B, EITHER_EDGE, handle_interrupt) < 0) {
        fprintf(stderr, "Failed to set interrupt service routines.\n");
        gpioTerminate();
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to stop.\n");

    while (1) {
        gpioSleep(1000000); // Sleep for 1 second
    }

    gpioTerminate();
    return 0;
}

