#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define FIFO_DATA_REG 0x60
#define LED_GPIO 17
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"

static gpiod_line *led_line;
static int i2c_fd;

void handle_signal(int signum) {
    gpiod_line_free(led_line);
    close(i2c_fd);
    fclose(stdout);
    exit(signum);
}

int read_i2c_data(uint8_t reg, uint16_t *data) {
    uint8_t buffer[2];
    int bytes_read;

    bytes_read = read(i2c_fd, buffer, 2);
    if (bytes_read != 2) {
        perror("I2C read error");
        return -1;
    }

    *data = (buffer[0] << 8) | buffer[1];
    return 0;
}

int main() {
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];
    uint16_t red_data, ir_data;
    FILE *log_file;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    led_line = gpiod_line_request(chip, LED_GPIO, "LED", 0, GPIOD_LINE_DIRECTION_OUTPUT);
    if (!led_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_free(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        gpiod_line_free(led_line);
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_free(led_line);
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        if (read_i2c_data(FIFO_DATA_REG, &red_data) < 0 || read_i2c_data(FIFO_DATA_REG + 2, &ir_data) < 0) {
            perror("Failed to read sensor data");
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s,%d,%d\n", timestamp, red_data, ir_data);
        fflush(log_file);

        if (ir_data > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(100000); // 100 ms
    }

    fclose(log_file);
    gpiod_line_free(led_line);
    close(i2c_fd);
    gpiod_chip_close(chip);

    return 0;
}

