#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

void *isr_thread(void *arg) {
    while (1) {
        gpio_event_t *event = malloc(sizeof(gpio_event_t));
        if (event == NULL) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }

        if (gpioInitialise() < 0) {
            perror("gpioInitialise");
            exit(EXIT_FAILURE);
        }

        if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
            perror("gpioSetMode");
            exit(EXIT_FAILURE);
        }

        if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
            perror("gpioSetPullUpDown");
            exit(EXIT_FAILURE);
        }

        if (gpioSetISRFunc(GPIO_PIN, PI_RISING_EDGE, &event, 0) < 0) {
            perror("gpioSetISRFunc");
            exit(EXIT_FAILURE);
        }

        while (1) {
            if (event->level == PI_ON) {
                pthread_mutex_lock(&pulse_mutex);
                pulse_count++;
                pthread_mutex_unlock(&pulse_mutex);
            }
        }

        free(event);
    }

    return NULL;
}

void sig_handler(int signum) {
    if (gpioTerminate() < 0) {
        perror("gpioTerminate");
    }

    if (pthread_mutex_destroy(&pulse_mutex) != 0) {
        perror("pthread_mutex_destroy");
    }

    exit(EXIT_SUCCESS);
}

int main() {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    pthread_t isr_thread_id;
    if (pthread_create(&isr_thread_id, NULL, isr_thread, NULL) != 0) {
        perror("pthread_create");
        exit(EXIT_FAILURE);
    }

    while (1) {
        struct timespec start, end;
        clock_gettime(CLOCK_REALTIME, &start);

        pthread_mutex_lock(&pulse_mutex);
        int count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        clock_gettime(CLOCK_REALTIME, &end);

        double elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
        double rpm = (count / elapsed_time) * 60;

        fprintf(log_file, "%f RPM\n", rpm);
        fflush(log_file);

        if (count == 0) {
            fprintf(log_file, "0.00 RPM\n");
            fflush(log_file);
        }

        sleep(1);
    }

    fclose(log_file);
    pthread_join(isr_thread_id, NULL);

    return EXIT_SUCCESS;
}

