#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x39
#define PART_ID_REG 0x00
#define FIFO_DATA_REG 0x04
#define FIFO_DATA_REG_SIZE 0x02
#define LED_GPIO 17
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"

static gpiod_chip *chip;
static gpiod_line *led_line;

static void cleanup(void) {
    if (led_line) {
        gpiod_line_free(led_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    fclose(stdout);
    fclose(stderr);
}

static void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

static int read_i2c_register(int addr, uint8_t reg, uint8_t *data, size_t len) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire I2C bus");
        close(fd);
        return -1;
    }

    ssize_t bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        perror("Failed to read from I2C device");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static int read_sensor_data(uint16_t *red, uint16_t *ir) {
    uint8_t data[FIFO_DATA_REG_SIZE];
    if (read_i2c_register(I2C_ADDR, FIFO_DATA_REG, data, FIFO_DATA_REG_SIZE)) {
        return -1;
    }

    *red = (data[0] << 8) | data[1];
    *ir = (data[2] << 8) | data[3];
    return 0;
}

static void log_data(uint16_t red, uint16_t ir) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Red: %d, IR: %d\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, red, ir);
    fclose(log_file);
}

int main(void) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    led_line = gpiod_line_request_any(chip, "LED", LED_GPIO,
                                      GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!led_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return 1;
    }

    uint8_t part_id;
    if (read_i2c_register(I2C_ADDR, PART_ID_REG, &part_id, 1)) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        gpiod_line_free(led_line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (part_id != 0x14) {
        fprintf(stderr, "Invalid PART_ID, expected 0x14, got 0x%02x\n", part_id);
        gpiod_line_free(led_line);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        uint16_t red, ir;
        if (read_sensor_data(&red, &ir)) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        log_data(red, ir);

        if (ir > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(100000); // 100 ms
    }

    cleanup();
    return 0;
}

