#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>

#define GPIO_OUT 18
#define GPIO_IN 17
#define GAIN_LOW 0
#define GAIN_HIGH 1

static gpiod_chip *chip;
static gpiod_line *gain_line;
static gpiod_line *in_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (in_line) {
        gpiod_line_free(in_line);
    }
    if (gain_line) {
        gpiod_line_free(gain_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    printf("Starting MAX9814 audio peak detection...\n");

    log_file = fopen("audio_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return 1;
    }

    gain_line = gpiod_line_request_any(chip, "gain", GPIO_OUT, "MAX9814 gain control", 0);
    if (!gain_line) {
        perror("Failed to request GPIO line for gain control");
        gpiod_chip_put(chip);
        fclose(log_file);
        return 1;
    }

    if (gpiod_line_direction_set(gain_line, GPIO_OUT) < 0) {
        perror("Failed to set direction for gain control line");
        gpiod_line_free(gain_line);
        gpiod_chip_put(chip);
        fclose(log_file);
        return 1;
    }

    if (gpiod_line_set_value(gain_line, GAIN_LOW) < 0) {
        perror("Failed to set gain to 60dB");
        gpiod_line_free(gain_line);
        gpiod_chip_put(chip);
        fclose(log_file);
        return 1;
    }

    in_line = gpiod_line_request_any(chip, "in", GPIO_IN, "MAX9814 input", 0);
    if (!in_line) {
        perror("Failed to request GPIO line for input");
        gpiod_line_free(gain_line);
        gpiod_chip_put(chip);
        fclose(log_file);
        return 1;
    }

    if (gpiod_line_direction_set(in_line, GPIO_IN) < 0) {
        perror("Failed to set direction for input line");
        gpiod_line_free(in_line);
        gpiod_line_free(gain_line);
        gpiod_chip_put(chip);
        fclose(log_file);
        return 1;
    }

    uint32_t last_value = 0;
    while (1) {
        uint32_t current_value = gpiod_line_get_value(in_line);
        if (current_value != last_value) {
            last_value = current_value;
            if (current_value == 1) {
                time_t rawtime;
                struct tm *timeinfo;
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d 1\n",
                        timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                        timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
                fflush(log_file);
            }
        }
        usleep(10000); // 10 ms interval
    }

    return 0;
}

