#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x36
#define I2C_CMD 0x3608
#define I2C_DATA_LEN 3
#define FLOW_RATE_CONVERSION 1000.0
#define LOG_FILE "flow_log.csv"

// CRC-8 function for Sensirion SLF3S-4000B
uint8_t crc8(uint8_t *data, uint8_t len) {
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    fclose(log_file);
    pigpio_stop();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        pigpio_stop();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        fclose(log_file);
        pigpio_stop();
        return 1;
    }

    if (i2cWriteDevice(i2c_handle, (uint8_t *)&I2C_CMD, 2) != 2) {
        fprintf(stderr, "Failed to write command to sensor.\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        pigpio_stop();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        uint8_t data[I2C_DATA_LEN];
        if (i2cReadDevice(i2c_handle, data, I2C_DATA_LEN) != I2C_DATA_LEN) {
            fprintf(stderr, "Failed to read from sensor.\n");
            continue;
        }

        uint16_t raw_flow = (data[0] << 8) | data[1];
        uint8_t calculated_crc = crc8(data, 2);
        if (calculated_crc != data[2]) {
            fprintf(stderr, "CRC check failed.\n");
            continue;
        }

        double flow_rate = (double)raw_flow / FLOW_RATE_CONVERSION;
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        char log_line[100];
        sprintf(log_line, "%04d-%02d-%02d %02d:%02d:%02d,%f\n",
                timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, flow_rate);

        if (fputs(log_line, log_file) == EOF) {
            fprintf(stderr, "Failed to write to log file.\n");
        }
        fflush(log_file);

        usleep(1000000); // Sleep for 1 second
    }

    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    fclose(log_file);
    pigpio_stop();

    return 0;
}

