#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define REG_START 0x00
#define REG_END 0x06
#define TVOC_OFFSET 1
#define eCO2_OFFSET 5
#define TVOC_SCALE 10.0
#define eCO2_SCALE 50.0
#define IAQ_MAX 100
#define IAQ_MIN 0

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    pigpio_stop();
    exit(0);
}

int main() {
    int i2c_handle = -1;
    FILE *log_file = NULL;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        pigpioStop();
        return 1;
    }

    log_file = fopen("air_quality_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_handle);
        pigpioStop();
        return 1;
    }

    fprintf(log_file, "Timestamp,IAQ,TVOC,eCO2\n");

    signal(SIGINT, handle_sigint);

    while (1) {
        uint8_t buffer[7];
        int bytes_read = i2cRead(i2c_handle, REG_START, buffer, 7);

        if (bytes_read != 7) {
            fprintf(stderr, "Failed to read sensor data.\n");
            continue;
        }

        uint16_t tvoc = (buffer[TVOC_OFFSET] << 8) | buffer[TVOC_OFFSET + 1];
        uint16_t eco2 = (buffer[eCO2_OFFSET] << 8) | buffer[eCO2_OFFSET + 1];

        double iaq = 100 - (tvoc / TVOC_SCALE) - ((eco2 - 400) / eCO2_SCALE);
        iaq = iaq < IAQ_MIN ? IAQ_MIN : (iaq > IAQ_MAX ? IAQ_MAX : iaq);

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s,%f,%d,%d\n", timestamp, iaq, tvoc, eco2);

        fflush(log_file);
        usleep(5000000); // Sleep for 5 seconds
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }

    pigpioStop();

    return 0;
}

