#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

static gpiod_chip *chip;
static gpiod_line *line;

void cleanup(void) {
    if (line) {
        gpiod_line_free(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

int main(void) {
    struct timespec start_time;
    struct timespec current_time;
    int touched = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_line_request(chip, "17", "ttp223_tamper", GPIOD_LINE_DIRECTION_INPUT, 0);
    if (!line) {
        fprintf(stderr, "Failed to request line 17: %s\n", strerror(errno));
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read sensor value: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (value == 1) {
            if (!touched) {
                touched = 1;
                clock_gettime(CLOCK_MONOTONIC, &start_time);
            }
        } else {
            touched = 0;
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (touched && (current_time.tv_sec - start_time.tv_sec >= 5)) {
            printf("Intrusion alert!\n");
            touched = 0;
        }

        usleep(100000); // Sleep for 100 ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

