    }
    exit(EXIT_FAILURE);
}

void handle_sigint(int signum) {
    cleanup();
}

int main() {
    struct gpiod_line_request_flags flags = GPIOD_LINE_REQUEST_OUTPUT;
    struct gpiod_line_request request = {
        .name = "INMP441_L_SELECT",
        .consumer = "audio_capture",
        .flags = flags,
    };

    struct gpiod_line_value value = {
        .value = 0,
    };

    struct snd_pcm_hw_params hw_params;
    struct snd_pcm_sw_params sw_params;
    unsigned char buffer[BUFFER_SIZE];
    FILE *file;

    // Initialize ALSA PCM
    if (snd_pcm_open(&pcm_handle, PCM_DEVICE, SND_PCM_STREAM_CAPTURE, 0) < 0) {
        perror("Failed to open PCM device");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    gpiod_chip = gpiod_chip_open_by_name("gpio");
    if (!gpiod_chip) {
        perror("Failed to open GPIO chip");
        cleanup();
    }

    gpiod_line = gpiod_line_request_by_name(gpiod_chip, "gpio%d", GPIO_PIN, &request);
    if (!gpiod_line) {
        perror("Failed to request GPIO line");
        cleanup();
    }

    // Set GPIO to select left channel
    if (gpiod_line_set_value(gpiod_line, &value) < 0) {
        perror("Failed to set GPIO value");
        cleanup();
    }

    // Configure PCM
    if (snd_pcm_hw_params_any(pcm_handle, &hw_params) < 0) {
        perror("Failed to initialize hardware parameters");
        cleanup();
    }

    if (snd_pcm_hw_params_set_access(pcm_handle, &hw_params, SND_PCM_ACCESS_RW_INTERLEAVED) < 0) {
        perror("Failed to set access type");
        cleanup();
    }

    if (snd_pcm_hw_params_set_format(pcm_handle, &hw_params, SND_PCM_FORMAT_S32_LE) < 0) {
        perror("Failed to set format");
        cleanup();
    }

    if (snd_pcm_hw_params_set_rate_near(pcm_handle, &hw_params, 48000, NULL) < 0) {
        perror("Failed to set sample rate");
        cleanup();
    }

    if (snd_pcm_hw_params(pcm_handle, &hw_params) < 0) {
        perror("Failed to set hardware parameters");
        cleanup();
    }

    // Open file for writing
    file = fopen("audio_capture.pcm", "wb");
    if (!file) {
        perror("Failed to open file for writing");
        cleanup();
    }

    // Register signal handler
    signal(SIGINT, handle_sigint);

    // Start capturing audio data
    while (1) {
        ssize_t frames_read = snd_pcm_readi(pcm_handle, buffer, BUFFER_SIZE);
        if (frames_read < 0) {
            perror("Failed to read from PCM device");
            cleanup();
        }

        for (size_t i = 0; i < frames_read; i++) {
            int32_t sample = buffer[i];
            int16_t pcm_sample = (int16_t)((sample >> 8) & 0x00FFFFFF);
            fwrite(&pcm_sample, sizeof(pcm_sample), 1, file);
        }
    }

    fclose(file);
    cleanup();

    return EXIT_SUCCESS;
}
