#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQ 100
#define DEBOUNCE_TIME 50
#define MAX_DUTY_CYCLE 80
#define LOG_FILE "flame_log.txt"

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

double exponential_curve(double duration) {
    return (MAX_DUTY_CYCLE / 100.0) * (1 - exp(-duration / 100.0));
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for flame sensor pin.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for fan pin.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for fan pin.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "System started at %s\n", ctime(&time(NULL)));
    fclose(log_file);

    int last_state = -1;
    double flame_start_time = 0.0;
    double duty_cycle = 0.0;

    while (!stop) {
        int current_state = gpioRead(FLAME_SENSOR_PIN);

        if (current_state < 0) {
            fprintf(stderr, "Failed to read flame sensor pin.\n");
            continue;
        }

        if (current_state != last_state) {
            if (current_state == 0) { // Flame detected
                flame_start_time = (double)pigpio_time_now();
                duty_cycle = exponential_curve(0.0);
                if (gpioPWM(FAN_PIN, duty_cycle * 100) < 0) {
                    fprintf(stderr, "Failed to set PWM duty cycle.\n");
                }
                fprintf(log_file, "Flame detected at %s\n", ctime(&time(NULL)));
            } else { // Flame ended
                if (duty_cycle > 0.0) {
                    double flame_duration = (double)pigpio_time_now() - flame_start_time;
                    duty_cycle = exponential_curve(flame_duration);
                    if (gpioPWM(FAN_PIN, duty_cycle * 100) < 0) {
                        fprintf(stderr, "Failed to set PWM duty cycle.\n");
                    }
                    fprintf(log_file, "Flame ended at %s\n", ctime(&time(NULL)));
                }
                duty_cycle = 0.0;
            }
            last_state = current_state;
        }

        usleep(DEBOUNCE_TIME * 1000);
    }

    if (gpioPWM(FAN_PIN, 0) < 0) {
        fprintf(stderr, "Failed to stop PWM.\n");
    }

    fclose(log_file);
    fprintf(log_file, "System shutdown at %s\n", ctime(&time(NULL)));
    fclose(log_file);

    gpioTerminate();
    return EXIT_SUCCESS;
}

