#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MAGIC_NUMBER 0x52444144
#define FRAME_SIZE 32768
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GPIO_TRIGGER 23
#define GPIO_DATA_READY 24

typedef struct {
    double start_frequency;
    double end_frequency;
    int chirps;
    int samples;
    double frame_period;
} Config;

void handle_signal(int signum) {
    if (spi != -1) {
        spiClose(spi);
    }
    if (gpio != -1) {
        gpioTerminate();
    }
    if (file != NULL) {
        fclose(file);
    }
    exit(signum);
}

int main() {
    int spi, gpio;
    FILE *file;
    Config config = {77.0, 79.0, 64, 256, 0.1};
    char buffer[FRAME_SIZE];
    uint32_t timestamp;
    uint32_t frame_number = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    spi = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    file = fopen("heatmap_data.bin", "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    if (fwrite(&MAGIC_NUMBER, sizeof(uint32_t), 1, file) != 1 ||
        fwrite(&config, sizeof(Config), 1, file) != 1) {
        fprintf(stderr, "Failed to write log file header\n");
        fclose(file);
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (gpioWrite(GPIO_TRIGGER, 1) < 0) {
            fprintf(stderr, "Failed to assert GPIO trigger\n");
            break;
        }

        while (gpioRead(GPIO_DATA_READY) == 0) {
            usleep(1000); // Wait for data-ready interrupt
        }

        if (spiXfer(spi, buffer, buffer, FRAME_SIZE) != FRAME_SIZE) {
            fprintf(stderr, "Failed to read heatmap data\n");
            break;
        }

        timestamp = time(NULL);
        if (fwrite(&timestamp, sizeof(uint32_t), 1, file) != 1 ||
            fwrite(&frame_number, sizeof(uint32_t), 1, file) != 1 ||
            fwrite(buffer, FRAME_SIZE, 1, file) != 1) {
            fprintf(stderr, "Failed to write frame data\n");
            break;
        }

        frame_number++;
    }

    fclose(file);
    spiClose(spi);
    gpioTerminate();

    return 0;
}

