#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define FLAME_SENSOR_GPIO 20
#define LOG_FILE "flame_log.txt"

static gpiod_chip *chip;
static gpiod_line *line;
static FILE *log_file;

static int last_state = -1;

void handle_signal(int signum) {
    if (line) {
        gpiod_line_request_free(line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

void log_state_change(int state) {
    char timestamp[20];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (state == 1) {
        fprintf(log_file, "%s: Flame detected\n", timestamp);
    } else {
        fprintf(log_file, "%s: Flame cleared\n", timestamp);
    }
    fflush(log_file);
}

int main() {
    int state;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if ((line = gpiod_line_request_by_name(chip, "20", "Flame Sensor", 0)) == NULL) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        gpiod_line_request_free(line);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_direction_set(line, GPIOD_LINE_DIRECTION_INPUT);

    while (1) {
        if (gpiod_line_get_value(line) != last_state) {
            state = gpiod_line_get_value(line);
            log_state_change(state);
            last_state = state;
        }
        usleep(100 * 1000); // Sleep for 100 milliseconds
    }

    return EXIT_SUCCESS;
}

