#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define OPT3001_REG_RESULT 0x00
#define OPT3001_REG_CONFIG 0x01
#define OPT3001_CONFIG_CONT_MODE 0x01
#define OPT3001_CONFIG_CONVERT_TIME_100MS 0x02
#define OPT3001_CONFIG_AUTO_FSR 0x04

static FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (pi >= 0) {
        gpioTerminate();
    }
    exit(signum);
}

int main(int argc, char **argv) {
    int pi = -1;
    int i2c_handle = -1;
    unsigned char config_byte = OPT3001_CONFIG_CONT_MODE | OPT3001_CONFIG_CONVERT_TIME_100MS | OPT3001_CONFIG_AUTO_FSR;
    unsigned char result[2];
    unsigned int mantissa;
    unsigned int exponent;
    double lux;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    pi = pigpio_start();
    if (pi < 0) {
        fprintf(stderr, "pigpio start failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(pi, 1, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        return 1;
    }

    if (i2cWriteDevice(i2c_handle, OPT3001_ADDR, &config_byte, 1) < 0) {
        fprintf(stderr, "Failed to write configuration to OPT3001\n");
        return 1;
    }

    log_file = fopen("light_data.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (i2cReadDevice(i2c_handle, OPT3001_ADDR, result, 2) < 0) {
            fprintf(stderr, "Failed to read from OPT3001\n");
            continue;
        }

        mantissa = (result[0] & 0x0F) << 8 | result[1];
        exponent = (result[0] & 0xF0) >> 4;
        lux = 0.01 * pow(2, exponent) * mantissa;

        struct tm *time_info;
        time_t rawtime;
        time(&rawtime);
        time_info = localtime(&rawtime);

        fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d.%06ldZ %.2f\n",
                time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
                time_info->tm_hour, time_info->tm_min, time_info->tm_sec,
                (long)time_info->tm_usec, lux);

        fflush(log_file);

        usleep(100000); // 100 ms delay
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}
