#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        stop_flag = 1;
    }
}

int main() {
    struct gpiod_line_request_config *req_config = NULL;
    struct gpiod_line_settings *line_settings = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int line_value = 0;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open the GPIO chip
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpiod_cleanup();
        return 1;
    }

    // Request configuration for the line
    req_config = gpiod_line_request_config_new();
    if (!req_config) {
        fprintf(stderr, "Failed to allocate line request config\n");
        gpiod_chip_close(chip);
        gpiod_cleanup();
        return 1;
    }

    // Set the line request configuration
    gpiod_line_request_config_set_consumer(req_config, "Flame Detector");
    gpiod_line_request_config_set_request_type(req_config, GPIOD_LINE_REQUEST_INPUT);
    gpiod_line_request_config_set_line_consumer(req_config, "Flame Detector");
    gpiod_line_request_config_set_line_type(req_config, GPIOD_LINE_TYPE_LINE);
    gpiod_line_request_config_set_line_consumer_type(req_config, GPIOD_LINE_CONSUMER_TYPE_ACTIVE_LOW);
    gpiod_line_request_config_set_line_consumer_bias(req_config, GPIOD_LINE_CONSUMER_BIAS_PULL_UP);

    // Request the line
    if (gpiod_chip_request_lines(chip, 1, &req_config, &line) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_line_request_config_free(req_config);
        gpiod_chip_close(chip);
        gpiod_cleanup();
        return 1;
    }

    // Set the line settings
    line_settings = gpiod_line_settings_new();
    if (!line_settings) {
        fprintf(stderr, "Failed to allocate line settings\n");
        gpiod_line_request_free(line);
        gpiod_line_request_config_free(req_config);
        gpiod_chip_close(chip);
        gpiod_cleanup();
        return 1;
    }

    // Main loop
    while (!stop_flag) {
        if (gpiod_line_request_get_value(line, &line_value) < 0) {
            fprintf(stderr, "Failed to get line value\n");
            gpiod_line_settings_free(line_settings);
            gpiod_line_request_free(line);
            gpiod_line_request_config_free(req_config);
            gpiod_chip_close(chip);
            gpiod_cleanup();
            return 1;
        }

        time_t rawtime;
        struct tm * timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (line_value == 0) {
            printf("%s Flame Detected: YES\n", buffer);
        } else {
            printf("%s Flame Detected: NO\n", buffer);
        }

        sleep(1);
    }

    // Cleanup
    gpiod_line_settings_free(line_settings);
    gpiod_line_request_free(line);
    gpiod_line_request_config_free(req_config);
    gpiod_chip_close(chip);
    gpiod_cleanup();

    return 0;
}

