#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio for cleanup.\n");
        exit(EXIT_FAILURE);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    int left_pin = 17;
    int center_pin = 18;
    int right_pin = 27;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    // Set GPIO modes
    if (gpioSetMode(left_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for left pin.\n");
        goto cleanup;
    }
    if (gpioSetMode(center_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for center pin.\n");
        goto cleanup;
    }
    if (gpioSetMode(right_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for right pin.\n");
        goto cleanup;
    }

    // Main loop
    while (1) {
        int left_value = gpioRead(left_pin);
        int center_value = gpioRead(center_pin);
        int right_value = gpioRead(right_pin);

        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Sleep for 50 ms
        usleep(50000);
    }

cleanup:
    // Cleanup and terminate pigpio
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

