#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PINS {2, 3, 4, 5, 6, 7, 8, 9}
#define NUM_PINS 8
#define DELAY_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_PINS];

void handle_sigint(int signum) {
    for (int i = 0; i < NUM_PINS; i++) {
        gpiod_line_request_release(lines[i]);
    }
    gpiod_chip_put(chip);
    exit(0);
}

int main() {
    struct gpiod_line_request_flags flags = GPIOD_LINE_REQUEST_ACTIVE_LOW;
    struct gpiod_line_consumer consumer = {
        .type = GPIOD_LINE_CONSUMER_USER,
        .consumer = "touch_sensor_reader"
    };

    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_line_request_by_name(chip, "gpio%d", GPIO_PINS[i], &consumer, &flags);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_PINS[i]);
            for (int j = 0; j < i; j++) {
                gpiod_line_request_release(lines[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        for (int i = 0; i < NUM_PINS; i++) {
            int value;
            if (gpiod_line_get_value(lines[i], &value) < 0) {
                fprintf(stderr, "Failed to read GPIO line %d\n", GPIO_PINS[i]);
                for (int j = 0; j < NUM_PINS; j++) {
                    gpiod_line_request_release(lines[j]);
                }
                gpiod_chip_put(chip);
                return 1;
            }
            printf("GPIO %d: %d\n", GPIO_PINS[i], value);
        }
        usleep(DELAY_MS * 1000);
    }

    for (int i = 0; i < NUM_PINS; i++) {
        gpiod_line_request_release(lines[i]);
    }
    gpiod_chip_put(chip);

    return 0;
}

