This C program uses the libgpiod library to read the state of an 8-channel TTP226 touch sensor connected to GPIO pins 2 through 9 on a Raspberry Pi Zero W. It requests each GPIO line, reads the state every 100 ms, and logs the state to the console. It handles errors by checking the return values of libgpiod calls and prints descriptive error messages to stderr. The program also gracefully handles SIGINT (Ctrl+C) by releasing all resources before exiting.

code:
#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define CHANNEL_PINS[NUM_CHANNELS] {2, 3, 4, 5, 6, 7, 8, 9}

void handle_signal(int signum) {
    printf("\nReceived signal %d, terminating...\n", signum);
    gpioTerminate();
    exit(signum);
}

int main(int argc, char *argv[]) {
    int i;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Configure GPIO pins as inputs with pull-down resistors
    for (i = 0; i < NUM_CHANNELS; i++) {
        status = gpioSetMode(CHANNEL_PINS[i], PI_INPUT);
        if (status < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", CHANNEL_PINS[i]);
            goto cleanup;
        }

        status = gpioSetPullUpDown(CHANNEL_PINS[i], PI_PUD_DOWN);
        if (status < 0) {
            fprintf(stderr, "Failed to set GPIO %d pull-down resistor\n", CHANNEL_PINS[i]);
            goto cleanup;
        }
    }

    // Main loop to read and log sensor states
    while (1) {
        printf("[");
        time_t now = time(NULL);
        printf("%ld ms] ", (now * 1000) % 1000);

        for (i = 0; i < NUM_CHANNELS; i++) {
            printf("CH%d=%d ", i + 1, gpioRead(CHANNEL_PINS[i]));
        }
        printf("\n");

        gpioDelay(100000); // 100 ms delay
    }

cleanup:
    gpioTerminate();
    return 1;
}

