#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_LINES 8
#define POLL_INTERVAL 50 // ms

static struct gpiod_line *lines[GPIO_LINES];
static struct gpiod_chip *chip;

void handle_sigint(int signum) {
    for (int i = 0; i < GPIO_LINES; i++) {
        gpiod_line_request_free(lines[i]);
    }
    gpiod_chip_put(chip);
    exit(0);
}

int main() {
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the GPIO chip
    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO lines
    for (int i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_line_request_by_name(chip, "gpio%d", i + 2, "touch_sensor", 0);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request GPIO line %d\n", i + 2);
            for (int j = 0; j < i; j++) {
                gpiod_line_request_free(lines[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }

        // Configure as input with bias disabled
        if (gpiod_line_direction_set(lines[i], GPIO_LINE_DIRECTION_IN) < 0 ||
            gpiod_line_bias_set(lines[i], GPIO_LINE_ACTIVE_LOW) < 0) {
            fprintf(stderr, "Failed to configure GPIO line %d\n", i + 2);
            for (int j = 0; j < i; j++) {
                gpiod_line_request_free(lines[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        time(&ts.tv_sec);
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);

        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        printf("%s,", timestamp);
        for (int i = 0; i < GPIO_LINES; i++) {
            int state = gpiod_line_get_value(lines[i]);
            printf("%d,", state);
        }
        printf("\n");

        usleep(POLL_INTERVAL * 1000); // Convert ms to us
    }

    // Cleanup
    for (int i = 0; i < GPIO_LINES; i++) {
        gpiod_line_request_free(lines[i]);
    }
    gpiod_chip_put(chip);

    return 0;
}

