#include <stdio.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    printf("Starting tilt sensor polling...\n");

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(4, PI_INPUT);
    gpioSetPullUpDown(4, PI_PUD_UP);

    int previous_state = -1;
    struct timespec ts;

    while (!stop) {
        clock_gettime(CLOCK_REALTIME, &ts);

        int current_state = gpioRead(4);

        if (current_state == -1) {
            fprintf(stderr, "Failed to read GPIO state.\n");
            continue;
        }

        if (previous_state != current_state) {
            previous_state = current_state;

            if (current_state == 0) {
                printf("Tilted at %ld.%09ld\n", (long)ts.tv_sec, (long)ts.tv_nsec);
            } else {
                printf("Not Tilted at %ld.%09ld\n", (long)ts.tv_sec, (long)ts.tv_nsec);
            }

            fflush(stdout);
        }

        usleep(100000); // Sleep for 100 ms
    }

    printf("Exiting...\n");
    fflush(stdout);

    gpioTerminate();

    return 0;
}

