#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x60
#define PART_ID 0x45
#define HW_KEY 0x17
#define CHLIST 0x01
#define ALS_FORCE 0x06

FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (pi < 0) {
        gpioTerminate();
    }
    exit(signum);
}

void write_register(int reg, uint8_t value) {
    if (i2cWriteReg(pi, I2C_BUS, SENSOR_ADDR, reg, &value, 1) < 0) {
        fprintf(stderr, "Failed to write to register 0x%02X\n", reg);
        exit(1);
    }
}

void read_register(int reg, uint8_t *data, int length) {
    if (i2cReadReg(pi, I2C_BUS, SENSOR_ADDR, reg, data, length) < 0) {
        fprintf(stderr, "Failed to read from register 0x%02X\n", reg);
        exit(1);
    }
}

void initialize_sensor() {
    uint8_t part_id;

    if (i2cOpen(pi, I2C_BUS, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        exit(1);
    }

    read_register(0x00, &part_id, 1);
    if (part_id != PART_ID) {
        fprintf(stderr, "Sensor not found or incorrect PART ID (expected 0x%02X, got 0x%02X)\n", PART_ID, part_id);
        exit(1);
    }

    write_register(0x00, HW_KEY);
    write_register(0x01, CHLIST);
}

void read_sensor_data() {
    uint8_t data[2];
    uint16_t uv_index, als_visible;

    read_register(0x0C, data, 2);
    uv_index = (data[0] << 8) | data[1];

    read_register(0x0E, data, 2);
    als_visible = (data[0] << 8) | data[1];

    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %d, %d\n",
            now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
            now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
            uv_index, als_visible);

    printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d, UV Index: %d, Visible ALS: %d\n",
           now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
           now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
           uv_index, als_visible);
}

int main() {
    int pi = pigpio_start();
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen("uv_als_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    initialize_sensor();

    while (1) {
        read_sensor_data();
        usleep(1000000); // Sleep for 1 second
    }

    return 0;
}

