#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_ADDR1 0x36
#define I2C_ADDR2 0x37
#define I2C_CMD_REG 0x08
#define I2C_DATA_REG 0x00
#define SCALE_FACTOR 0.036
#define ALARM_GPIO 17
#define LOG_FILE "flow_log.txt"

static int i2c_fd1, i2c_fd2;
static struct gpiod_line *alarm_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, 0);
        gpiod_line_free(alarm_line);
    }
    if (i2c_fd1 >= 0) {
        close(i2c_fd1);
    }
    if (i2c_fd2 >= 0) {
        close(i2c_fd2);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    int i2c_err;
    int flow1, flow2;
    float avg_flow;
    uint8_t data[9];
    uint8_t crc;
    uint8_t crc_calc;
    uint16_t flow_raw;

    // Initialize I2C
    i2c_fd1 = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd1 < 0) {
        perror("Failed to open I2C device 1");
        return 1;
    }
    if (ioctl(i2c_fd1, I2C_SLAVE, I2C_ADDR1) < 0) {
        perror("Failed to set I2C address 1");
        close(i2c_fd1);
        return 1;
    }

    i2c_fd2 = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd2 < 0) {
        perror("Failed to open I2C device 2");
        close(i2c_fd1);
        return 1;
    }
    if (ioctl(i2c_fd2, I2C_SLAVE, I2C_ADDR2) < 0) {
        perror("Failed to set I2C address 2");
        close(i2c_fd1);
        close(i2c_fd2);
        return 1;
    }

    // Initialize GPIO
    alarm_line = gpiod_line_request(ALARM_GPIO, "Alarm", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!alarm_line) {
        perror("Failed to request GPIO line");
        close(i2c_fd1);
        close(i2c_fd2);
        return 1;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_free(alarm_line);
        close(i2c_fd1);
        close(i2c_fd2);
        return 1;
    }

    // Initialize sensors
    i2c_write(i2c_fd1, &0x36, 1);
    i2c_write(i2c_fd2, &0x36, 1);
    usleep(100000);

    // Signal handling
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        flow1 = 0;
        flow2 = 0;

        // Read sensor 1
        i2c_err = i2c_read(i2c_fd1, data, 9);
        if (i2c_err == 9) {
            flow_raw = (data[2] << 8) | data[3];
            crc_calc = 0xFF;
            for (int i = 0; i < 8; i++) {
                crc_calc = crc_calc ^ data[i];
                for (int j = 0; j < 8; j++) {
                    if (crc_calc & 0x80) {
                        crc_calc = (crc_calc << 1) ^ 0x31;
                    } else {
                        crc_calc <<= 1;
                    }
                }
            }
            if (crc_calc == data[8]) {
                flow1 = flow_raw * SCALE_FACTOR;
            } else {
                fprintf(stderr, "CRC error on sensor 1\n");
            }
        } else {
            fprintf(stderr, "I2C error on sensor 1\n");
        }

        // Read sensor 2
        i2c_err = i2c_read(i2c_fd2, data, 9);
        if (i2c_err == 9) {
            flow_raw = (data[2] << 8) | data[3];
            crc_calc = 0xFF;
            for (int i = 0; i < 8; i++) {
                crc_calc = crc_calc ^ data[i];
                for (int j = 0; j < 8; j++) {
                    if (crc_calc & 0x80) {
                        crc_calc = (crc_calc << 1) ^ 0x31;
                    } else {
                        crc_calc <<= 1;
                    }
                }
            }
            if (crc_calc == data[8]) {
                flow2 = flow_raw * SCALE_FACTOR;
            } else {
                fprintf(stderr, "CRC error on sensor 2\n");
            }
        } else {
            fprintf(stderr, "I2C error on sensor 2\n");
        }

        // Calculate average flow rate
        avg_flow = (flow1 + flow2) / 2.0;

        // Log average flow rate
        fprintf(log_file, "%.2f\n", avg_flow);

        // Drive alarm GPIO
        if (avg_flow < 0.5) {
            gpiod_line_set_value(alarm_line, 1);
        } else {
            gpiod_line_set_value(alarm_line, 0);
        }

        // Sleep for 1 second
        sleep(1);
    }

