    int timestamp;
    int reading;
} SensorData;

SensorData buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void handle_sigint(int signum) {
    printf("\nSIGINT received, printing buffer contents...\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Timestamp: %d, Reading: %d\n", buffer[i].timestamp, buffer[i].reading);
    }
    printf("\nExiting cleanly...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(4, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 4 as input.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(4, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to enable pull-up resistor on GPIO 4.\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        int reading = gpioRead(4);

        if (reading == 0) {
            buffer[buffer_head].timestamp = time(NULL);
            buffer[buffer_head].reading = reading;
            printf("Obstacle detected at timestamp: %d\n", buffer[buffer_head].timestamp);
            buffer_head = (buffer_head + 1) % BUFFER_SIZE;
            if (buffer_head == buffer_tail) {
                buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
            }
        }

        usleep(POLL_INTERVAL * 1000); // Convert ms to us
    }

    return 0;
}

