#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x55
#define MODE_CONTROL 0x1D
#define OPERATING_STATUS 0x1B
#define X_LSB 0x2A
#define X_MSB 0x2B
#define Y_LSB 0x2C
#define Y_MSB 0x2D
#define Z_LSB 0x2E
#define Z_MSB 0x2F
#define SCALE_FACTOR 0.0009765625
#define CSV_FILE "fan_health.csv"

int i2c_fd;
FILE *csv_file;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    exit(signum);
}

int i2c_write(uint8_t reg, uint8_t value) {
    int ret;
    uint8_t buf[2] = {reg, value};
    ret = write(i2c_fd, buf, 2);
    if (ret != 2) {
        perror("i2c_write");
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t reg, uint8_t *data, int length) {
    int ret;
    uint8_t buf[length + 1];
    buf[0] = reg;
    ret = write(i2c_fd, buf, length + 1);
    if (ret != length + 1) {
        perror("i2c_read");
        return -1;
    }
    ret = read(i2c_fd, data, length);
    if (ret != length) {
        perror("i2c_read");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write(MODE_CONTROL, 0x10) == -1) {
        close(i2c_fd);
        return 1;
    }

    uint8_t status;
    struct timespec timeout = {0, 100000000}; // 1 second
    while (1) {
        if (i2c_read(OPERATING_STATUS, &status, 1) == -1) {
            continue;
        }
        if (status & 0x01) {
            break;
        }
        nanosleep(&timeout, NULL);
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Sensor did not become active within 1 second.\n");
        close(i2c_fd);
        return 1;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        return 1;
    }

    if (fseek(csv_file, 0, SEEK_END) == -1) {
        perror("fseek");
        fclose(csv_file);
        close(i2c_fd);
        return 1;
    }

    char header[] = "Timestamp,X,Y,Z\n";
    if (ftell(csv_file) == 0) {
        fwrite(header, sizeof(header), 1, csv_file);
    }

    while (1) {
        uint8_t x_data[2], y_data[2], z_data[2];
        if (i2c_read(X_LSB, x_data, 2) == -1 ||
            i2c_read(Y_LSB, y_data, 2) == -1 ||
            i2c_read(Z_LSB, z_data, 2) == -1) {
            continue;
        }

        int16_t x = (int16_t)((x_data[1] << 8) | x_data[0]);
        int16_t y = (int16_t)((y_data[1] << 8) | y_data[0]);
        int16_t z = (int16_t)((z_data[1] << 8) | z_data[0]);

        double x_g = x * SCALE_FACTOR;
        double y_g = y * SCALE_FACTOR;
        double z_g = z * SCALE_FACTOR;

        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        char line[100];
        snprintf(line, sizeof(line), "%s,%f,%f,%f\n", timestamp, x_g, y_g, z_g);
        fwrite(line, sizeof(line), 1, csv_file);

        fflush(csv_file);
        usleep(500000); // 500 ms
    }

    fclose(csv_file);
    close(i2c_fd);
    return 0;
}

