        fprintf(stderr, "Failed to set GPIO mode for Sensor 1\n");
        goto cleanup;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for Sensor 2\n");
        goto cleanup;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED\n");
        goto cleanup;
    }

    while (!stop) {
        if (gpioRead(SENSOR1_PIN) == 0 || gpioRead(SENSOR2_PIN) == 0) {
            if (gpioWrite(LED_PIN, PI_ON) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
