#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x0E
#define MAG_DEVICE_ID 0x8D
#define MAG_REG_DEVICE_ID 0x00
#define MAG_REG_CTRL 0x01
#define MAG_REG_DATA_X 0x02
#define MAG_REG_DATA_Y 0x04
#define MAG_REG_DATA_Z 0x06
#define MAG_CTRL_CONT_MODE 0x01
#define MAG_CTRL_ALL_AXES 0x03
#define MAG_CTRL_RANGE_50MT 0x00
#define MAG_LSB_SCALE_50MT 0.01

void handle_signal(int signum) {
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) >= 0) {
        i2cClose(I2C_BUS, I2C_ADDR);
    }
    if (fclose(stdout) != 0) {
        fprintf(stderr, "Error closing stdout\n");
    }
    if (fclose(stderr) != 0) {
        fprintf(stderr, "Error closing stderr\n");
    }
    gpioTerminate();
    exit(signum);
}

int main() {
    FILE *file = fopen("magnetic_log.csv", "a");
    if (file == NULL) {
        perror("Error opening file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    uint8_t device_id;
    if (i2cRead(I2C_BUS, I2C_ADDR, MAG_REG_DEVICE_ID, &device_id, 1) < 0) {
        fprintf(stderr, "Error reading device ID\n");
        return 1;
    }

    if (device_id != MAG_DEVICE_ID) {
        fprintf(stderr, "Invalid device ID: expected 0x%02X, got 0x%02X\n", MAG_DEVICE_ID, device_id);
        return 1;
    }

    uint8_t ctrl_reg = MAG_CTRL_CONT_MODE | MAG_CTRL_ALL_AXES | MAG_CTRL_RANGE_50MT;
    if (i2cWrite(I2C_BUS, I2C_ADDR, MAG_REG_CTRL, &ctrl_reg, 1) < 0) {
        fprintf(stderr, "Error writing control register\n");
        return 1;
    }

    if (fseek(file, 0, SEEK_SET) != 0) {
        perror("Error seeking to start of file");
        return 1;
    }

    if (ftell(file) == 0) {
        fprintf(file, "Timestamp,X,Y,Z\n");
    }

    struct timespec ts;
    struct tm *tm;
    char timestamp[20];
    int16_t x, y, z;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (i2cRead(I2C_BUS, I2C_ADDR, MAG_REG_DATA_X, &x, 2) < 0) {
            fprintf(stderr, "Error reading X data\n");
            continue;
        }

        if (i2cRead(I2C_BUS, I2C_ADDR, MAG_REG_DATA_Y, &y, 2) < 0) {
            fprintf(stderr, "Error reading Y data\n");
            continue;
        }

        if (i2cRead(I2C_BUS, I2C_ADDR, MAG_REG_DATA_Z, &z, 2) < 0) {
            fprintf(stderr, "Error reading Z data\n");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        fprintf(file, "%s,%f,%f,%f\n", timestamp, (float)x * MAG_LSB_SCALE_50MT, (float)y * MAG_LSB_SCALE_50MT, (float)z * MAG_LSB_SCALE_50MT);
        fflush(file);

        nanosleep(&ts, NULL);
    }

    fclose(file);
    return 0;
}

