#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define RETRY_INTERVAL 60

void handle_signal(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioGetErrorStr(pigpioGetError()));
    }
    gpioTerminate();
    exit(signum);
}

void log_error(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d ERROR: %s\n",
            now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
            now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, message);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioGetErrorStr(pigpioGetError()));
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        log_error("Failed to set GPIO mode");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
        log_error("Failed to set pull-down resistor");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            log_error("Failed to read GPIO level");
            sleep(RETRY_INTERVAL);
            continue;
        }

        if (level == 1) {
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            printf("%04d-%02d-%02d %02d:%02d:%02d ALERT: Water detected\n",
                   now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                   now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec);

            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("Failed to open log file");
                continue;
            }
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d ALERT: Water detected\n",
                    now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                    now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec);
            fclose(log_file);
        }

        sleep(2);
    }

    return 0;
}

