        fprintf(stderr, "Failed to set GPIO mode\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(GPIO_PIN, handle_interrupt) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetWatchdog(GPIO_PIN, 1000) < 0) {
        fprintf(stderr, "Failed to set watchdog timer\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        time(&rawtime);
        time_info = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S ", time_info);

        rpm = pulse_count * 60;
        pulse_count = 0;

        fprintf(log_file, "%s%d\n", timestamp, rpm);
        fflush(log_file);

        printf("%s%d\n", timestamp, rpm);

        sleep(1);
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
