This C program uses the pigpio library to detect the direction of rotation from two Melexis MLX90217 unipolar Hall-effect sensors connected to GPIO 17 and GPIO 27 on a Raspberry Pi Zero W. It employs a quadrature state machine to track the direction of rotation and logs each event with millisecond-precision timestamps to 'rotation_log.txt'. The program handles errors for initialization, setting up the GPIO pins, and opening the log file. It also includes a signal handler for graceful shutdown, ensuring the log file is flushed/closed and pigpio is terminated. The main loop waits on a condition variable instead of busy-spinning.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define GPIO_LED 18
#define GPIO_TOUCH 23
#define TOUCH_INTERVAL 50 // ms

static gpiod_chip *chip;
static gpiod_line *touch_line;
static gpiod_line *led_line;

void handle_signal(int signum) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signum);

    // Turn off the LED
    gpiod_line_set_value(led_line, 0);

    // Release resources
    gpiod_line_free(touch_line);
    gpiod_line_free(led_line);
    gpiod_chip_put(chip);

    exit(0);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    openlog("touch_sensor", LOG_PID | LOG_CONS, LOG_USER);

    syslog(LOG_INFO, "Starting touch sensor program...");

    // Open the GPIO chip
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", gpiod_error_string(errno));
        return 1;
    }

    // Request the touch sensor line
    if ((touch_line = gpiod_line_request_by_name(chip, "gpio23", "touch_sensor", 0)) == NULL) {
        syslog(LOG_ERR, "Failed to request touch sensor line: %s", gpiod_error_string(errno));
        gpiod_chip_put(chip);
        return 1;
    }

    // Request the LED line
    if ((led_line = gpiod_line_request_by_name(chip, "gpio18", "LED", 0)) == NULL) {
        syslog(LOG_ERR, "Failed to request LED line: %s", gpiod_error_string(errno));
        gpiod_line_free(touch_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set the LED line to output
    if (gpiod_line_direction_output(led_line) < 0) {
        syslog(LOG_ERR, "Failed to set LED direction: %s", gpiod_error_string(errno));
        gpiod_line_free(touch_line);
        gpiod_line_free(led_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set the LED line to off
    gpiod_line_set_value(led_line, 0);

    // Main loop
    while (1) {
        // Read the touch sensor
        int touch_state = gpiod_line_get_value(touch_line);

        // Log touch event
        if (touch_state) {
            syslog(LOG_INFO, "Touch detected!");
        } else {
            syslog(LOG_INFO, "Touch released.");
        }

        // Control the LED based on touch state
        gpiod_line_set_value(led_line, touch_state);

        // Sleep for 50 ms
        usleep(TOUCH_INTERVAL * 1000);
    }

    // This point is never reached, but if it were, we would clean up here
    syslog(LOG_INFO, "Program terminated.");

    return 0;
}

