#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

static gpiod_chip *chip;
static gpiod_line *touch_line;
static gpiod_line *led_line;

void cleanup(int signum) {
    if (touch_line) {
        gpiod_line_free(touch_line);
        touch_line = NULL;
    }

    if (led_line) {
        gpiod_line_free(led_line);
        led_line = NULL;
    }

    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }

    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request touch line (GPIO 17)
    touch_line = gpiod_line_request(chip, 17, "touch_sensor", 0);
    if (!touch_line) {
        fprintf(stderr, "Failed to request touch line\n");
        goto cleanup;
    }

    // Set touch line to input
    ret = gpiod_line_direction_input(touch_line);
    if (ret) {
        fprintf(stderr, "Failed to set touch line direction to input\n");
        goto cleanup;
    }

    // Request LED line (GPIO 18)
    led_line = gpiod_line_request(chip, 18, "led", 0);
    if (!led_line) {
        fprintf(stderr, "Failed to request LED line\n");
        goto cleanup;
    }

    // Set LED line to output and drive LOW
    ret = gpiod_line_direction_output(led_line);
    if (ret) {
        fprintf(stderr, "Failed to set LED line direction to output\n");
        goto cleanup;
    }

    ret = gpiod_line_set_value(led_line, 0);
    if (ret) {
        fprintf(stderr, "Failed to set LED line value to LOW\n");
        goto cleanup;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        gpiod_event *event;
        ret = gpiod_event_wait(touch_line, &event, 50);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for touch event\n");
            goto cleanup;
        }

        if (event->value == 1) {
            // Rising edge detected, toggle LED
            int current_value = gpiod_line_get_value(led_line);
            ret = gpiod_line_set_value(led_line, !current_value);
            if (ret) {
                fprintf(stderr, "Failed to set LED line value\n");
                goto cleanup;
            }
        }

        gpiod_event_free(event);
    }

cleanup:
    cleanup(0);

    return 0;
}

