#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_ENTRIES 100
#define DEBOUNCE_MS 50

typedef struct {
    int sensor_pin;
    int led_pin;
    int state;
    time_t timestamp;
} TouchEvent;

TouchEvent log_buffer[NUM_ENTRIES];
int buffer_head = 0;
int buffer_tail = 0;
int overflow_count = 0;

void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    TouchEvent event = {sensor_pin, -1, state, now};

    if (buffer_head == buffer_tail) {
        overflow_count++;
    }

    log_buffer[buffer_head] = event;
    buffer_head = (buffer_head + 1) % NUM_ENTRIES;
}

void print_log_buffer() {
    printf("Log Buffer Contents:\n");
    int i = buffer_tail;
    while (i != buffer_head) {
        printf("Sensor %d: State %d, Timestamp %ld\n", log_buffer[i].sensor_pin, log_buffer[i].state, log_buffer[i].timestamp);
        i = (i + 1) % NUM_ENTRIES;
    }
    printf("Overflow Count: %d\n", overflow_count);
}

void handle_signal(int signum) {
    gpioWrite(27, 0);
    gpioWrite(22, 0);
    print_log_buffer();
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(4, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 4 as input\n");
        goto cleanup;
    }

    if (gpioSetMode(17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as input\n");
        goto cleanup;
    }

    if (gpioSetMode(27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 27 as output\n");
        goto cleanup;
    }

    if (gpioSetMode(22, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 22 as output\n");
        goto cleanup;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int sensor1 = gpioRead(4);
        int sensor2 = gpioRead(17);

        if (sensor1 != 0 && log_buffer[buffer_tail].state == 0) {
            log_event(4, 1);
            gpioWrite(27, 1);
        } else if (sensor1 == 0 && log_buffer[buffer_tail].state == 1) {
            log_event(4, 0);
            gpioWrite(27, 0);
        }

        if (sensor2 != 0 && log_buffer[buffer_tail].state == 0) {
            log_event(17, 1);
            gpioWrite(22, 1);
        } else if (sensor2 == 0 && log_buffer[buffer_tail].state == 1) {
            log_event(17, 0);
            gpioWrite(22, 0);
        }

        buffer_tail = (buffer_tail + 1) % NUM_ENTRIES;
        usleep(DEBOUNCE_MS * 1000);
    }

cleanup:
    gpioTerminate();
    return 1;
}

