#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL 500

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int previous_state = 1; // Assume initial state is dry

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state != previous_state) {
            char message[64];
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);

            if (current_state == 0) {
                snprintf(message, sizeof(message), "Rain Detected at %02d:%02d:%02d\n",
                         now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec);
            } else {
                snprintf(message, sizeof(message), "No Rain at %02d:%02d:%02d\n",
                         now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec);
            }

            if (fputs(message, log_file) == EOF) {
                fprintf(stderr, "Failed to write to log file\n");
            }

            previous_state = current_state;
        }

        if (stop) {
            break;
        }

        usleep(POLL_INTERVAL * 1000); // Sleep for 500 ms
    }

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

