#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04

#define LOG_FILE "biometric_log.txt"

void handle_sigint(int signum) {
    printf("\nReceived SIGINT, shutting down...\n");
    fclose(log_file);
    i2c_close(i2c_handle);
    pigpio_stop();
    exit(0);
}

int main() {
    int i2c_handle = -1;
    FILE *log_file = NULL;

    // Initialize pigpio
    if (pigpio_start() < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2c_open(I2C_BUS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        pigpio_stop();
        return 1;
    }

    // Verify sensor presence
    uint8_t part_id;
    if (i2c_read_byte_data(i2c_handle, I2C_ADDR, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID from sensor\n");
        i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }
    printf("Sensor PART_ID: 0x%02X\n", part_id);

    // Configure sensor for continuous measurement
    uint8_t config_data = 0x01; // Example configuration, adjust as needed
    if (i2c_write_byte_data(i2c_handle, I2C_ADDR, CONFIG_REG, config_data) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Register signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        uint16_t heart_rate = 0;
        uint8_t spo2 = 0;

        // Read heart rate
        if (i2c_read_word_data(i2c_handle, I2C_ADDR, HEART_RATE_REG, &heart_rate) < 0) {
            fprintf(stderr, "Failed to read heart rate\n");
            continue;
        }

        // Read SpO2
        if (i2c_read_byte_data(i2c_handle, I2C_ADDR, SPO2_REG, &spo2) < 0) {
            fprintf(stderr, "Failed to read SpO2\n");
            continue;
        }

        // Log data
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
        fprintf(log_file, "%s, Heart Rate: %u BPM, SpO2: %u%%\n", timestamp, heart_rate, spo2);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    fclose(log_file);
    i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

