#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define LOG_FILE "bridge_integrity.log"
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define ALARM_PIN 27
#define DELAY_MS 100
#define THRESHOLD_TIME 2000 // 2 seconds

volatile sig_atomic_t alarm_active = 0;
volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        exit_flag = 1;
    }
}

void log_event(const char *event, int sensor_pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }

    fprintf(log_file, "%s - %s - Sensor %d\n", buffer, event, sensor_pin);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);

    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, PI_LOW);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!exit_flag) {
        int sensor1_state = gpioRead(SENSOR1_PIN);
        int sensor2_state = gpioRead(SENSOR2_PIN);

        if (sensor1_state == PI_HIGH && !alarm_active) {
            alarm_active = 1;
            log_event("Tilt Start", SENSOR1_PIN);
            gpioWrite(ALARM_PIN, PI_HIGH);
        } else if (sensor2_state == PI_HIGH && !alarm_active) {
            alarm_active = 1;
            log_event("Tilt Start", SENSOR2_PIN);
            gpioWrite(ALARM_PIN, PI_HIGH);
        }

        if (alarm_active) {
            if (sensor1_state == PI_LOW && sensor2_state == PI_LOW) {
                alarm_active = 0;
                log_event("Tilt End", 0);
                gpioWrite(ALARM_PIN, PI_LOW);
            }
        }

        gpioDelay(DELAY_MS);
    }

    if (alarm_active) {
        log_event("Tilt End", 0);
        gpioWrite(ALARM_PIN, PI_LOW);
    }

    gpioTerminate();
    return 0;
}

