    if (i2cReadI2CBlockData(i2c_handle, CTRL1, 1, &ctrl1_reg, 1) < 0) {
        handle_error("Failed to read CTRL1 register");
    }
    if (i2cWriteI2CBlockData(i2c_handle, CTRL1, 1, &ctrl1_reg, 1) < 0) {
        handle_error("Failed to write CTRL1 register");
    }
}

void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

double compute_vibration_magnitude(uint8_t *data) {
    double x = ((double)data[0] | ((double)data[1] << 8)) / 16.0;
    double y = ((double)data[2] | ((double)data[3] << 8)) / 16.0;
    double z = ((double)data[4] | ((double)data[5] << 8)) / 16.0;
    return sqrt(x * x + y * y + z * z);
}

int main() {
    init_pigpio();
    init_i2c();

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        handle_error("Failed to open log file");
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    while (1) {
        uint8_t data[ACCEL_DATA_LEN];
        int retries = 3;
        int success = 0;

        while (retries > 0) {
            if (i2cReadI2CBlockData(i2c_handle, ACCEL_REG, ACCEL_DATA_LEN, data, ACCEL_DATA_LEN) >= 0) {
                success = 1;
                break;
            }
            retries--;
            usleep(100000); // 100 ms sleep
        }

        if (!success) {
