#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_OUT_PINS {4, 17, 27, 22}
#define GPIO_LED 18
#define POLL_INTERVAL 50 // ms

static gpiod_chip *chip;
static gpiod_line *lines[4];
static gpiod_line *led_line;

void cleanup(int signum) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_request_free(lines[i]);
    }
    gpiod_line_request_free(led_line);
    gpiod_chip_put(chip);
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_line_request_by_name(chip, "gpio%d", GPIO_OUT_PINS[i], "obstacle_sensor", 0);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_OUT_PINS[i]);
            cleanup(0);
        }
        gpiod_line_direction_set(lines[i], GPIO_LINE_DIRECTION_IN);
    }

    led_line = gpiod_line_request_by_name(chip, "gpio%d", GPIO_LED, "led", GPIO_LINE_REQUEST_ACTIVE_LOW);
    if (!led_line) {
        fprintf(stderr, "Failed to request LED GPIO line\n");
        cleanup(0);
    }
    gpiod_line_direction_set(led_line, GPIO_LINE_DIRECTION_OUT);

    while (1) {
        int object_detected = 0;
        for (int i = 0; i < 4; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value == 0) {
                object_detected = 1;
                break;
            }
        }

        gpiod_line_set_value(led_line, object_detected);

        usleep(POLL_INTERVAL * 1000); // Convert ms to us
    }

    cleanup(0);
    return 0;
}

