#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <syslog.h>

#define NUM_SENSORS 5
#define DEBOUNCE_TIME 50 // ms

volatile sig_atomic_t shutdown_flag = 0;

void handle_signal(int signum) {
    shutdown_flag = 1;
}

void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
}

void log_info(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_SENSORS];
    int i, ret;
    FILE *log_file;
    struct flock lock;

    // Initialize syslog
    openlog("flame_monitor", LOG_PID, LOG_USER);
    log_info("Starting flame monitor");

    // Open the GPIO chip
    if ((ret = gpiod_chip_open("/dev/gpiochip0", &chip)) < 0) {
        log_error("Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    // Request lines
    for (i = 0; i < NUM_SENSORS; i++) {
        int pin = (i == 0) ? 2 : ((i == 1) ? 3 : ((i == 2) ? 4 : ((i == 3) ? 17 : 27)));
        if ((ret = gpiod_line_request(chip, pin, "flame_sensor", &lines[i], GPIOD_LINE_DIRECTION_IN)) < 0) {
            log_error("Failed to request GPIO line %d", pin);
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
    }

    // Open log file
    if ((log_file = fopen("/var/log/flame_events.log", "a")) == NULL) {
        log_error("Failed to open log file");
        for (i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    // Set file lock
    lock.l_type = F_WRLCK;
    lock.l_whence = SEEK_SET;
    lock.l_start = 0;
    lock.l_len = 0;
    if (fcntl(fileno(log_file), F_SETLK, &lock) == -1) {
        log_error("Failed to lock log file");
        fclose(log_file);
        for (i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (!shutdown_flag) {
        for (i = 0; i < NUM_SENSORS; i++) {
            int old_value, new_value;
            if ((ret = gpiod_line_get_value(lines[i], &old_value)) < 0) {
                log_error("Failed to read GPIO line %d", lines[i]->line);
                continue;
            }

            usleep(DEBOUNCE_TIME * 1000); // Debounce
            if ((ret = gpiod_line_get_value(lines[i], &new_value)) < 0) {
                log_error("Failed to read GPIO line %d", lines[i]->line);
                continue;
            }

            if (old_value == 1 && new_value == 0) {
                char timestamp[32];
                time_t now = time(NULL);
                struct tm *tm_info = gmtime(&now);
                strftime(timestamp, sizeof(timestamp), "%FT%T", tm_info);

                fprintf(log_file, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, i, lines[i]->line);
                fflush(log_file);
            }
        }

        sleep(1); // Poll once per second
    }

    // Cleanup
    for (i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    fclose(log_file);
    flock(fileno(log_file), F_UNLCK);
    closelog();

    return EXIT_SUCCESS;
}

