#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define NUM_PINS 8
#define PIN_MAP[0] 5
#define PIN_MAP[1] 6
#define PIN_MAP[2] 13
#define PIN_MAP[3] 19
#define PIN_MAP[4] 26
#define PIN_MAP[5] 12
#define PIN_MAP[6] 16
#define PIN_MAP[7] 20

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_PINS];
static int last_states[NUM_PINS];

void cleanup(void) {
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_request_free(lines[i]);
        }
    }
    gpiod_chip_put(chip);
    exit(1);
}

void handle_sigint(int signum) {
    cleanup();
}

int main(int argc, char *argv[]) {
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("gpiod_chip_open");
        exit(1);
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_by_name(chip, PIN_MAP[i], "touch_sensor",
                                      GPIOD_LINE_DIRECTION_IN, 0, &lines[i]) < 0) {
            perror("gpiod_line_request_by_name");
            cleanup();
        }
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        int states[NUM_PINS];

        for (int i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_get_value(lines[i], &states[i]) < 0) {
                perror("gpiod_line_get_value");
                cleanup();
            }
        }

        for (int i = 0; i < NUM_PINS; i++) {
            if (states[i] != last_states[i]) {
                clock_gettime(CLOCK_REALTIME, &ts);
                tm = localtime(&ts.tv_sec);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
                printf("%s touch %d (BCM %d)\n", timestamp, i, PIN_MAP[i]);
                last_states[i] = states[i];
            }
        }

        usleep(50000); // 50 milliseconds
    }

    cleanup();
    return 0;
}

