#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_REG 0x04
#define LUX_SCALE 0.0576
#define PWM_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100

FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to terminate pigpio.\n");
    }
    exit(signum);
}

int main() {
    int i2c_fd = -1;
    int raw_lux = 0;
    int brightness = 0;
    int error_code = 0;
    char timestamp[32];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        goto cleanup_pigpio;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address.\n");
        goto cleanup_i2c;
    }

    uint8_t config_data[2] = {0x00, 0x00};
    if (write(i2c_fd, config_data, 2) != 2) {
        fprintf(stderr, "Failed to write sensor configuration.\n");
        goto cleanup_i2c;
    }

    if ((log_file = fopen("grow_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        goto cleanup_i2c;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (read(i2c_fd, &raw_lux, 2) != 2) {
            fprintf(stderr, "Failed to read ALS value.\n");
            error_code = -1;
            goto log_and_sleep;
        }

        raw_lux = (raw_lux << 8) | (raw_lux & 0xFF);
        double lux = raw_lux * LUX_SCALE;

        if (lux < 100) {
            brightness = PWM_RANGE;
        } else if (lux < 500) {
            brightness = PWM_RANGE * 3 / 4;
        } else if (lux < 1000) {
            brightness = PWM_RANGE / 2;
        } else {
            brightness = PWM_RANGE / 4;
        }

        if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) < 0) {
            fprintf(stderr, "Failed to set PWM frequency.\n");
            error_code = -1;
            goto log_and_sleep;
        }

        if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
            fprintf(stderr, "Failed to set PWM range.\n");
            error_code = -1;
            goto log_and_sleep;
        }

        if (gpioPWM(PWM_GPIO, brightness) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle.\n");
            error_code = -1;
            goto log_and_sleep;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s, Lux: %.2f, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
        fflush(log_file);

        error_code = 0;

log_and_sleep:
        sleep(1);
    }

cleanup_i2c:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

cleanup_pigpio:
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to terminate pigpio.\n");
    }

    return 0;
}

