#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define GPIO_BASE 2
#define GPIO_LED 17
#define DEBOUNCE_MS 50

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

void log_touch(int channel) {
    FILE *file = fopen("touch_log.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open touch_log.txt for writing.\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S - Channel %d Touched\n", timeinfo);
    fprintf(file, buffer, channel + 1);

    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(GPIO_BASE + i, PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input.\n", GPIO_BASE + i);
            return 1;
        }
        if (gpioSetPullUpDown(GPIO_BASE + i, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to set GPIO %d pull-down resistor.\n", GPIO_BASE + i);
            return 1;
        }
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", GPIO_LED);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state[NUM_CHANNELS] = {0};
    int current_state[NUM_CHANNELS] = {0};

    while (!stop) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            current_state[i] = gpioRead(GPIO_BASE + i);

            if (current_state[i] != last_state[i]) {
                if (current_state[i]) {
                    log_touch(i);
                    gpioWrite(GPIO_LED, PI_ON);
                } else {
                    gpioWrite(GPIO_LED, PI_OFF);
                }

                last_state[i] = current_state[i];
            }
        }

        usleep(DEBOUNCE_MS * 1000);
    }

    gpioWrite(GPIO_LED, PI_OFF);
    gpioTerminate();

    return 0;
}

