#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810
#define CONVERSION_TIME 100000 // 100 ms in microseconds

void handle_sigint(int signum) {
    printf("\nSIGINT received, shutting down...\n");
    close(i2cHandle);
    gpioTerminate();
    exit(0);
}

int main() {
    FILE *logFile;
    int i2cHandle;
    unsigned int lux;
    unsigned short result;
    unsigned char exponent;
    unsigned short mantissa;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2cHandle = i2cOpen(1, OPT3001_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    unsigned int config_word_be = (CONFIG_WORD >> 8) | ((CONFIG_WORD & 0xFF) << 8);
    if (i2cWriteWordData(i2cHandle, CONFIG_REG, config_word_be) < 0) {
        fprintf(stderr, "Failed to write configuration to sensor.\n");
        close(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Wait for conversion
    usleep(CONVERSION_TIME);

    // Open log file
    logFile = fopen("light_data.txt", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        close(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read result
        result = i2cReadWordData(i2cHandle, RESULT_REG);
        if (result < 0) {
            fprintf(stderr, "Failed to read result from sensor.\n");
            continue;
        }

        // Byte-swap result
        result = (result >> 8) | ((result & 0xFF) << 8);

        // Extract exponent and mantissa
        exponent = (result >> 12) & 0xF;
        mantissa = result & 0xFFF;

        // Calculate lux
        lux = mantissa * 0.01 * (1 << exponent);

        // Log and print lux value
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        fprintf(logFile, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, lux);
        fflush(logFile);
        printf("Lux: %.2f\n", lux);

        // Wait for 1 second
        sleep(1);
    }

    // Close log file and I2C handle on exit
    fclose(logFile);
    close(i2cHandle);
    gpioTerminate();

    return 0;
}

