#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAMESENSOR_GPIO 4
#define ALERT_GPIO 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL 500

volatile sig_atomic_t stop = 0;

void cleanup(int signum) {
    stop = 1;
    if (pi_stop() < 0) {
        fprintf(stderr, "Failed to stop pigpio.\n");
    }
    if (fclose(fopen(LOG_FILE, "a")) != 0) {
        fprintf(stderr, "Failed to close log file.\n");
    }
    exit(1);
}

int main() {
    FILE *log_file;
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    if (pi_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        fclose(log_file);
        return 1;
    }

    if (pi_set_mode(FLAMESENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set sensor GPIO mode.\n");
        pi_stop();
        fclose(log_file);
        return 1;
    }

    if (pi_set_mode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set alert GPIO mode.\n");
        pi_stop();
        fclose(log_file);
        return 1;
    }

    signal(SIGINT, cleanup);

    while (!stop) {
        int sensor_value = pi_read(FLAMESENSOR_GPIO);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value.\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        if (fprintf(log_file, "%s Sensor: %d\n", timestamp, sensor_value) < 0) {
            fprintf(stderr, "Failed to write to log file.\n");
        }

        if (sensor_value == 0) {
            if (pi_write(ALERT_GPIO, 1) < 0) {
                fprintf(stderr, "Failed to set alert GPIO HIGH.\n");
            }
            sleep(1);
            if (pi_write(ALERT_GPIO, 0) < 0) {
                fprintf(stderr, "Failed to set alert GPIO LOW.\n");
            }
        }

        sleep(POLL_INTERVAL / 1000);
    }

    fclose(log_file);
    pi_stop();
    return 0;
}

