#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x08
#define COMMAND 0x36
#define DATA_LENGTH 3
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0

int i2c_handle;
FILE *log_file;

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (pi_stop() < 0) {
        fprintf(stderr, "Failed to stop pigpio.\n");
    }
    exit(0);
}

unsigned char crc8(unsigned char *data, int length) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        return 1;
    }

    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    if (fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n") < 0) {
        fprintf(stderr, "Failed to write header to log file.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        if (i2cWriteDevice(i2c_handle, &COMMAND, 1) < 0) {
            fprintf(stderr, "Failed to write command to sensor.\n");
            continue;
        }

        unsigned char data[DATA_LENGTH];
        if (i2cReadDevice(i2c_handle, data, DATA_LENGTH) != DATA_LENGTH) {
            fprintf(stderr, "Failed to read data from sensor.\n");
            continue;
        }

        unsigned short raw_flow = (data[0] << 8) | data[1];
        unsigned char sensor_crc = data[2];
        unsigned char computed_crc = crc8(data, DATA_LENGTH - 1);

        if (sensor_crc != computed_crc) {
            fprintf(log_file, "%ld,%f,ERROR\n", time(NULL), 0.0);
            fprintf(stderr, "CRC check failed.\n");
            continue;
        }

        double flow_rate = (double)raw_flow / 90.0;
        if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
            fprintf(log_file, "%ld,%f,INVALID\n", time(NULL), flow_rate);
            fprintf(stderr, "Flow rate out of range.\n");
            continue;
        }

        fprintf(log_file, "%ld,%f,OK\n", time(NULL), flow_rate);
    }

    handle_sigint(0); // Graceful shutdown on exit

    return 0;
}

