        fflush(log_file);
        usleep(POLL_INTERVAL * 1000); // Convert milliseconds to microseconds
    }

    // Clean up
    if (lines_initialized) {
        for (int i = 0; i < 3; i++) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_put(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

