#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_GPIO 4
#define FLAME_EVENTS_FILE "flame_events.txt"

static void handle_event(struct gpiod_line *line, struct gpiod_event *event) {
    time_t now = time(NULL);
    char timestamp[20];
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("Flame detected at %s\n", timestamp);

    FILE *file = fopen(FLAME_EVENTS_FILE, "a");
    if (file == NULL) {
        perror("Failed to open flame events file");
        return;
    }

    fprintf(file, "Flame detected at %s\n", timestamp);
    fclose(file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_event_request *req;

    // Initialize libgpiod
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    if (gpiod_line_request_by_name(chip, "gpio%d", FLAME_SENSOR_GPIO, "FlameSensor", &line) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the line to input
    if (gpiod_line_direction_input(line) < 0) {
        perror("Failed to set line direction to input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the line to active-low
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the event
    req = gpiod_line_request_event(line, "FlameSensorEvent", handle_event, NULL, 0);
    if (req == NULL) {
        perror("Failed to request event");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the event to trigger on falling edge
    if (gpiod_event_request_set_debounce(req, 0) < 0) {
        perror("Failed to set debounce");
        gpiod_event_request_free(req);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started...\n");

    // Main loop
    while (1) {
        gpiod_event_wait(req);
    }

    // Clean up
    gpiod_event_request_free(req);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

