#include <signal.h>
#include <gpiod.h>
#include <time.h>

static gpiod_line *touch_line;
static gpiod_line *led_line;
static FILE *log_file;

void cleanup(void) {
    if (touch_line) {
        gpiod_line_free(touch_line);
        touch_line = NULL;
    }
    if (led_line) {
        gpiod_line_free(led_line);
        led_line = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

int main(void) {
    gpiod_chip *chip;
    gpiod_line_request_flags flags = GPIOD_LINE_REQUEST_ACTIVE_HIGH;
    gpiod_line_event_flags event_flags = GPIOD_LINE_EVENT_RISING_EDGE;
    struct timespec poll_timeout = { .tv_sec = 1 };
    char log_filename[] = "touch_log.txt";
    char log_line[128];
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    touch_line = gpiod_line_request_by_name(chip, "23", "touch", flags);
    if (!touch_line) {
        fprintf(stderr, "Failed to request touch line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led_line = gpiod_line_request_by_name(chip, "24", "led", GPIOD_LINE_REQUEST_ACTIVE_HIGH | GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (!led_line) {
        fprintf(stderr, "Failed to request LED line\n");
        gpiod_line_free(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(log_filename, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_free(led_line);
        gpiod_line_free(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_event_add(touch_line, event_flags, NULL, NULL);

    while (1) {
        ret = gpiod_line_event_wait(touch_line, &poll_timeout);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for touch event: %s\n", gpiod_line_event_strerror(ret));
            break;
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(log_line, sizeof(log_line), "%FT%T%z\n", tm);
        fprintf(log_file, "%sTouch detected, toggling LED\n", log_line);

        gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
    }

    cleanup();
    return EXIT_SUCCESS;
}

