#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAMESENSOR_PIN 17
#define BUZZER_PIN 18
#define POLL_INTERVAL 500
#define BUZZER_ACTIVATION_TIME 2000
#define SLICE_INTERVAL 100

static gpiod_chip *chip;
static gpiod_line *flame_sensor_line;
static gpiod_line *buzzer_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - %s\n",
            now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
            now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, event);
    fflush(log_file);
}

int main() {
    int ret;
    unsigned long old_value = 0;
    unsigned long new_value;

    // Initialize signal handling
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request the flame sensor line as input
    flame_sensor_line = gpiod_chip_get_line(chip, FLAMESENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Failed to get flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_input(flame_sensor_line, "flame_sensor");
    if (ret) {
        fprintf(stderr, "Failed to request flame sensor line as input: %s\n", strerror(errno));
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the buzzer line as output
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line: %s\n", strerror(errno));
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(buzzer_line, "buzzer");
    if (ret) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    log_file = fopen("alert_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Log system startup
    log_event("System started");

    // Main loop
    while (1) {
        new_value = gpiod_line_get_value(flame_sensor_line);
        if (new_value != old_value) {
            if (new_value == 0) { // Flame detected (active-low)
                log_event("Flame detected");
                gpiod_line_set_value(buzzer_line, 1); // Activate buzzer
                for (int i = 0; i < BUZZER_ACTIVATION_TIME / SLICE_INTERVAL; i++) {
                    usleep(SLICE_INTERVAL * 1000); // Sleep for 100 ms
                    if (signal(SIGINT, SIG_DFL) == SIG_ERR || signal(SIGTERM, SIG_DFL) == SIG_ERR) {
                        handle_signal(SIGINT);
                    }
                }
                gpiod_line_set_value(buzzer_line, 0); // Deactivate buzzer
            }
            old_value = new_value;
        }
        usleep(POLL_INTERVAL * 1000); // Sleep for 500 ms
        if (signal(SIGINT, SIG_DFL) == SIG_ERR || signal(SIGTERM, SIG_DFL) == SIG_ERR) {
            handle_signal(SIGINT);
        }
    }

    // Clean shutdown
    log_event("System stopped");
    fclose(log_file);
    gpiod_line_release(flame_sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    return 0;
}

