#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_TOUCH 4
#define GPIO_LED 17
#define DEBOUNCE_MS 200
#define LOG_FILE "touch_log.txt"

volatile sig_atomic_t shutdown = 0;

void handle_signal(int signum) {
    shutdown = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_TOUCH, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input.\n", GPIO_TOUCH);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output.\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 10 * 1000 * 1000; // 10 ms

    int last_touch = 0;
    int last_touch_time = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!shutdown) {
        int current_touch = gpioRead(GPIO_TOUCH);

        if (current_touch != last_touch) {
            if (current_touch == 1 && (time(NULL) - last_touch_time) > DEBOUNCE_MS / 1000) {
                last_touch_time = time(NULL);
                last_touch = current_touch;

                if (gpioWrite(GPIO_LED, !gpioRead(GPIO_LED)) < 0) {
                    fprintf(stderr, "Failed to toggle LED.\n");
                }

                char timestamp[20];
                time_t now = time(NULL);
                struct tm *now_tm = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%FT%T", now_tm);

                if (fprintf(log_file, "%s\n", timestamp) < 0) {
                    fprintf(stderr, "Failed to write to log file.\n");
                }
            }
        }

        nanosleep(&ts, NULL);
    }

    if (gpioWrite(GPIO_LED, 0) < 0) {
        fprintf(stderr, "Failed to turn off LED.\n");
    }

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

