#define NUM_SENSORS 3
#define GPIO_PINS[NUM_SENSORS] {4, 17, 27}
#define LOG_FILE "magnet_log.txt"

volatile sig_atomic_t shutdown = 0;

void handle_signal(int signum) {
    shutdown = 1;
}

void log_state_change(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s Sensor%d: %s\n", buffer, sensor_id + 1, state ? "magnet-removed" : "magnet-present");
