#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x02
#define AVG_REG 0x04
#define ENABLE_REG 0x05
#define HR_REG 0x2A
#define AVG_SAMPLES 5

int main() {
    int i2cHandle = -1;
    int partId, hwRev;
    int ledCurrent = 0x3F;
    int avg = 0x04;
    int enable = 0x01;
    int rawHR, filteredHR;
    int samples[AVG_SAMPLES] = {0};
    int sampleIndex = 0;
    FILE *logFile = NULL;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    partId = i2cReadByte(i2cHandle, PART_ID_REG);
    if (partId != 0x02) {
        fprintf(stderr, "Invalid PART_ID register value.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    hwRev = i2cReadByte(i2cHandle, HW_REV_REG);
    if (hwRev != 0x01) {
        fprintf(stderr, "Invalid HW_REV register value.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2cHandle, LED_CURRENT_REG, ledCurrent) < 0) {
        fprintf(stderr, "Failed to write LED current register.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2cHandle, AVG_REG, avg) < 0) {
        fprintf(stderr, "Failed to write averaging register.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2cHandle, ENABLE_REG, enable) < 0) {
        fprintf(stderr, "Failed to write enable register.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    logFile = fopen("heart_rate.csv", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    while (1) {
        rawHR = i2cReadWordData(i2cHandle, HR_REG);
        if (rawHR < 0) {
            fprintf(stderr, "Failed to read heart rate register.\n");
            continue;
        }

        filteredHR = (samples[sampleIndex] * (AVG_SAMPLES - 1) + rawHR) / AVG_SAMPLES;
        samples[sampleIndex] = rawHR;
        sampleIndex = (sampleIndex + 1) % AVG_SAMPLES;

        if (filteredHR >= 30 && filteredHR <= 220) {
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            char timestamp[20];
            sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d,",
                    now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                    now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec);
            fprintf(logFile, "%s%d\n", timestamp, filteredHR);
            fflush(logFile);
        }

        sleep(1);
    }

    fclose(logFile);
    i2cClose(i2cHandle);
    gpioTerminate();
    return 0;
}

