#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

static gpiod_chip *chip;
static gpiod_line *line;
static FILE *log_file;

void handle_signal(int signum) {
    if (line) {
        gpiod_line_request_release(line);
        gpiod_chip_put(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_line_request_by_name(chip, "17", "flame_sensor", 0, GPIOD_LINE_DIRECTION_INPUT);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_function(line, GPIOD_LINE_FUNCTION_INPUT) == -1) {
        fprintf(stderr, "Failed to set line function\n");
        gpiod_line_request_release(line);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_edge(line, GPIOD_LINE_EDGE_RISING) == -1) {
        fprintf(stderr, "Failed to set line edge\n");
        gpiod_line_request_release(line);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_debounce(line, 100) == -1) {
        fprintf(stderr, "Failed to set line debounce\n");
        gpiod_line_request_release(line);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_request_release(line);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int value = gpiod_line_get_value(line);
        if (value == 0) {
            printf("FLAME DETECTED\n");
            time_t now = time(NULL);
            fprintf(log_file, "%s FLAME DETECTED\n", ctime(&now));
            fflush(log_file);
        }
        usleep(100000); // Sleep for 100 ms
    }

    return EXIT_SUCCESS;
}

