#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define NUM_CHANNELS 8
#define GPIO_OUT_BASE 17
#define GPIO_OUT_MASK 0xFF
#define STABILIZATION_DELAY 200
#define POLL_INTERVAL 10

static gpiod_chip *chip;
static gpiod_line *lines[NUM_CHANNELS];
static gpiod_line *output_lines[NUM_CHANNELS];
static int prev_states[NUM_CHANNELS];
static int counter = 0;

void handle_signal(int signum) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_request_set_value(output_lines[i], 0);
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_request_release(lines[i]);
    }
    gpiod_chip_release(chip);
    exit(0);
}

void log_touch_event(const char *filename, int channel, int counter) {
    FILE *log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", filename);
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ, Channel: %d, Counter: %d\n",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
            channel, counter);

    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0", 0);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_line_request(chip, 5 + i, "input", 0);
        if (lines[i] == NULL) {
            for (int j = 0; j < i; j++) {
                gpiod_line_request_release(lines[j]);
            }
            gpiod_chip_release(chip);
            fprintf(stderr, "Failed to request GPIO line %d: %s\n", 5 + i,
                    strerror(errno));
            return 1;
        }

        output_lines[i] = gpiod_line_request(chip, GPIO_OUT_BASE + i, "output", 0);
        if (output_lines[i] == NULL) {
            for (int j = 0; j < i; j++) {
                gpiod_line_request_release(lines[j]);
            }
            gpiod_chip_release(chip);
            fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_OUT_BASE + i,
                    strerror(errno));
            return 1;
        }

        gpiod_line_request_set_value(output_lines[i], 0);
        prev_states[i] = 0;
    }

    sleep(STABILIZATION_DELAY / 1000);

    while (1) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int current_state = gpiod_line_request_get_value(lines[i]);
            if (current_state == -1) {
                fprintf(stderr, "Failed to read GPIO line %d: %s\n", 5 + i,
                        strerror(errno));
                continue;
            }

            if (current_state != prev_states[i]) {
                if (current_state == 1) {
                    counter = (counter + 1) & GPIO_OUT_MASK;
                    log_touch_event("touch_log.txt", i + 1, counter);
                    printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
                }
                prev_states[i] = current_state;
            }
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (gpiod_line_request_set_value(output_lines[i], counter & (1 << i)) == -1) {
                fprintf(stderr, "Failed to set GPIO line %d: %s\n", GPIO_OUT_BASE + i,
                        strerror(errno));
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_request_release(lines[i]);
        gpiod_line_request_release(output_lines[i]);
    }
    gpiod_chip_release(chip);

    return 0;
}

