#define POLL_INTERVAL 100 // ms

gpiod_line *lines[NUM_PINS];
FILE *csv_file;

void handle_signal(int signum) {
    for (int i = 0; i < NUM_PINS; i++) {
        gpiod_line_free(lines[i]);
    }
    fclose(csv_file);
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    csv_file = fopen("tracking_log.csv", "a");
    if (csv_file == NULL) {
        perror("fopen");
        return 1;
    }

    if (gpiod_chip_open("/dev/gpiochip0", &lines[0]->chip) < 0) {
        perror("gpiod_chip_open");
        return 1;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_input(lines[i]->chip, GPIO_PINS[i], "Sensor %d", &lines[i]->line) < 0) {
            perror("gpiod_line_request_input");
            return 1;
        }
    }

    if (fputs("timestamp,sensor1,sensor2,sensor3,sensor4\n", csv_file) == EOF) {
        perror("fputs");
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        char line[100];
        sprintf(line, "%s,", timestamp);

        for (int i = 0; i < NUM_PINS; i++) {
            int value;
            if (gpiod_line_get_value(lines[i]->line, &value) < 0) {
                perror("gpiod_line_get_value");
                continue;
            }
            sprintf(line + strlen(line), "%d,", value);
        }

        line[strlen(line) - 1] = '\0'; // Remove trailing comma

        if (fputs(line, csv_file) == EOF) {
            perror("fputs");
            return 1;
        }

        if (fflush(csv_file) == EOF) {
            perror("fflush");
            return 1;
        }

        usleep(POLL_INTERVAL * 1000); // Convert ms to us
    }

    return 0;
}

