#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 100
#define LOG_FILE "/var/log/tilt_events.log"

gpiod_chip *chip;
gpiod_line *line17, *line18;
FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }

    if (line17) {
        gpiod_line_free(line17);
    }

    if (line18) {
        gpiod_line_free(line18);
    }

    if (chip) {
        gpiod_chip_put(chip);
    }

    exit(signum == SIGINT ? 0 : 1);
}

void log_event(int sensor, int value) {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", now_tm);

    if (fprintf(log_file, "%sSensor %d tilted\n", timestamp, sensor) < 0) {
        perror("Failed to write to log file");
    }
}

int main() {
    int ret;
    unsigned long last_read_time = 0;
    int last_value17 = 1, last_value18 = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line17 = gpiod_line_request(chip, 17, "tilt_sensor17", 0, GPIOD_LINE_DIRECTION_INPUT, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_TYPE_LINE, 0);
    if (!line17) {
        fprintf(stderr, "Failed to request GPIO line 17\n");
        gpiod_chip_put(chip);
        return 1;
    }

    line18 = gpiod_line_request(chip, 18, "tilt_sensor18", 0, GPIOD_LINE_DIRECTION_INPUT, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_TYPE_LINE, 0);
    if (!line18) {
        fprintf(stderr, "Failed to request GPIO line 18\n");
        gpiod_line_free(line17);
        gpiod_chip_put(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_free(line18);
        gpiod_line_free(line17);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        unsigned long current_time = gpiod_line_get_value(line17);
        if (current_time != last_value17 && (current_time == 0 || (current_time - last_read_time) > DEBOUNCE_MS)) {
            log_event(1, current_time);
            last_value17 = current_time;
            last_read_time = current_time;
        }

        current_time = gpiod_line_get_value(line18);
        if (current_time != last_value18 && (current_time == 0 || (current_time - last_read_time) > DEBOUNCE_MS)) {
            log_event(2, current_time);
            last_value18 = current_time;
            last_read_time = current_time;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return 0;
}

