#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 27
#define GPIO_LED 22
#define POLL_INTERVAL 100 // ms

static gpiod_chip *chip;
static gpiod_line *sensor1, *sensor2, *led;
static FILE *log_file;

void handle_sigint(int signum) {
    if (led) {
        gpiod_line_set_value(led, 0);
        gpiod_line_free(led);
    }
    if (sensor1) {
        gpiod_line_free(sensor1);
    }
    if (sensor2) {
        gpiod_line_free(sensor2);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct timespec ts;
    char timestamp[32];
    int sensor1_value, sensor2_value, led_state;

    // Register signal handler
    signal(SIGINT, handle_sigint);

    // Open GPIO chip
    if (!(chip = gpiod_chip_open("gpiochip0"))) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Open sensor lines
    if (!(sensor1 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_SENSOR1, "sensor1", 0, 0))) {
        fprintf(stderr, "Failed to request sensor1 line\n");
        goto error_sensor1;
    }
    if (!(sensor2 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_SENSOR2, "sensor2", 0, 0))) {
        fprintf(stderr, "Failed to request sensor2 line\n");
        goto error_sensor2;
    }

    // Open LED line
    if (!(led = gpiod_line_request_by_name(chip, "gpio%d", GPIO_LED, "led", 0, 0))) {
        fprintf(stderr, "Failed to request LED line\n");
        goto error_led;
    }

    // Open log file
    if (!(log_file = fopen("obstacle_log.csv", "w"))) {
        fprintf(stderr, "Failed to open log file\n");
        goto error_log;
    }

    // Set up timestamp
    ts.tv_sec = time(NULL);
    ts.tv_nsec = 0;

    while (1) {
        // Read sensor values
        sensor1_value = gpiod_line_get_value(sensor1);
        sensor2_value = gpiod_line_get_value(sensor2);

        // Determine LED state
        led_state = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
        gpiod_line_set_value(led, led_state);

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", gmtime(&ts.tv_sec));

        // Write to log file
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state);
        fflush(log_file);

        // Sleep for 100 ms
        usleep(POLL_INTERVAL * 1000);
    }

error_log:
    gpiod_line_free(led);
error_led:
    gpiod_line_free(sensor2);
error_sensor2:
    gpiod_line_free(sensor1);
error_sensor1:
    gpiod_chip_put(chip);
    return 1;
}

