This C program reads digital reflectance data from two TCRT5000 IR obstacle-avoidance sensor modules on GPIO17 and GPIO27, drives an LED on GPIO22 high when both sensors read 0, polls the sensors every 100 ms, and logs each sample to a comma-separated file 'obstacle_log.csv'. It checks every libgpiod call, handles the case where `gpiochip0` is unavailable, verifies the log file opens successfully, and handles SIGINT (Ctrl+C) for graceful shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop_sampling = 0;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        stop_sampling = 1;
    }
}

int main() {
    int sample_period = 125; // 125 microseconds
    int mic_pin = 4; // GPIO4
    int led_pin = 17; // GPIO17

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (gpioSetMode(mic_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", mic_pin);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(led_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", led_pin);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Start sampling
    while (!stop_sampling) {
        if (gpioRead(mic_pin) == 1) {
            printf("%ld\n", gpioTick());
            if (gpioWrite(led_pin, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
            }
            gpioDelay(100000); // 100 ms delay
            if (gpioWrite(led_pin, 0) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
            }
        }
        gpioDelay(sample_period);
    }

    // Clean shutdown
    if (gpioWrite(led_pin, 0) < 0) {
        fprintf(stderr, "Failed to turn off LED during shutdown\n");
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

