    if (signum == SIGINT) {
        stop_sampling = 1;
    }
}

int main() {
    int sample_period = 125; // 125 microseconds
    int mic_pin = 4; // GPIO4
    int led_pin = 17; // GPIO17

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (gpioSetMode(mic_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", mic_pin);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(led_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", led_pin);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Start sampling
    while (!stop_sampling) {
        if (gpioRead(mic_pin) == 1) {
            printf("%ld\n", gpioTick());
            if (gpioWrite(led_pin, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
            }
            gpioDelay(100000); // 100 ms delay
            if (gpioWrite(led_pin, 0) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
            }
        }
        gpioDelay(sample_period);
    }

    // Clean shutdown
    if (gpioWrite(led_pin, 0) < 0) {
        fprintf(stderr, "Failed to turn off LED during shutdown\n");
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}
```

This C program initializes the pigpio library, sets up GPIO4 as an input for the microphone and GPIO17 as an output for the LED. It then enters a loop where it samples the microphone input every 125 microseconds. If a HIGH reading is detected, it prints a timestamp and turns the LED on for 100 milliseconds. The program handles SIGINT to stop sampling and ensures the LED is turned off before terminating.

