#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x49
#define ALS_LSB 0x24
#define ALS_MSB 0x25
#define INTERVAL 100 // 100 ms

int i2c_fd;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(1);
}

void handle_sigint(int signum) {
    cleanup();
}

int main() {
    struct i2c_rdwr_ioctl_data msg;
    struct i2c_msg msg_array[2];

    // Register signal handler for Ctrl+C
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup();
    }

    // Set I2C device address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
    }

    while (1) {
        // Prepare read message
        msg_array[0].addr = SENSOR_ADDR;
        msg_array[0].flags = 0;
        msg_array[0].len = 1;
        msg_array[0].buf = &ALS_LSB;

        msg_array[1].addr = SENSOR_ADDR;
        msg_array[1].flags = 0;
        msg_array[1].len = 1;
        msg_array[1].buf = &ALS_MSB;

        msg.msgs = msg_array;
        msg.nmsgs = 2;

        // Perform I2C read
        if (ioctl(i2c_fd, I2C_RDWR, &msg) < 0) {
            perror("Failed to read from sensor");
            cleanup();
        }

        // Combine LSB and MSB into 16-bit value
        uint16_t als_value = (msg_array[1].buf[0] << 8) | msg_array[0].buf[0];

        // Log the raw sensor value
        printf("ALS Visible Data: %u\n", als_value);

        // Sleep for 100 ms
        usleep(INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

