static gpiod_chip *chip;
static gpiod_line *lines[3];

void cleanup(int signum) {
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_free(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        int line_num = 2 + i; // GPIO 2, 3, 4
        gpiod_line *line = gpiod_line_get(chip, line_num);
        if (!line) {
            fprintf(stderr, "Failed to get line %d\n", line_num);
            cleanup(0);
        }

        if (gpiod_line_request(line, "sensor_line", GPIOD_LINE_DIRECTION_INPUT, 0, 0, 0) < 0) {
            fprintf(stderr, "Failed to request line %d\n", line_num);
            gpiod_line_free(line);
            cleanup(0);
        }

        lines[i] = line;
    }

    while (1) {
        for (int i = 0; i < 3; i++) {
            int value = gpiod_line_get_value(lines[i]);
            printf("L:%d M:%d R:%d\n", i == 0 ? value : 0, i == 1 ? value : 0, i == 2 ? value : 0);
        }
        usleep(100000); // 100 ms
    }

    cleanup(0); // This line is never reached, but required for completeness
    return 0;
}

