#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

// GPIO line numbers
const int GPIO_LINES[] = {5, 6, 13, 19, 26, 12, 16, 20};

// Global variables for libgpiod resources
struct gpiod_chip *chip;
struct gpiod_line *lines[8];

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    for (int i = 0; i < 8; i++) {
        gpiod_line_put(lines[i]);
    }
    gpiod_chip_put(chip);
    exit(signum);
}

int main() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open gpiochip0
    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    // Request all 8 lines as inputs
    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_line_request(chip, GPIO_LINES[i], "touch_sensor", 0, GPIOD_LINE_DIRECTION_INPUT);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_LINES[i]);
            for (int j = 0; j < i; j++) {
                gpiod_line_put(lines[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }
    }

    // Poll every 200 ms and log each channel's state
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("%ld.%09ld] ", ts.tv_sec, ts.tv_nsec / 1000000);
        for (int i = 0; i < 8; i++) {
            int value = gpiod_line_get_value(lines[i]);
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");
        fflush(stdout);
        usleep(200000); // 200 ms
    }

    // Cleanup on exit (should never reach here)
    for (int i = 0; i < 8; i++) {
        gpiod_line_put(lines[i]);
    }
    gpiod_chip_put(chip);

    return 0;
}

