#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define NUM_STEPS 50
#define FADE_TIME 5000 // 5 seconds
#define PWM_FREQ 1000
#define PWM_RANGE 255

void sig_handler(int signum) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signum);
    for (int i = 0; i < 3; i++) {
        if (gpioPWM(i + 17, 0) < 0) {
            syslog(LOG_ERR, "Failed to set PWM to 0 on GPIO%d", i + 17);
        }
    }
    gpioTerminate();
    exit(signum);
}

void fade_color(int r, int g, int b) {
    int start_time = time(NULL);
    int elapsed_time;
    int step_time = FADE_TIME / NUM_STEPS;

    for (int step = 0; step <= NUM_STEPS; step++) {
        elapsed_time = time(NULL) - start_time;
        if (elapsed_time >= FADE_TIME) {
            break;
        }

        int r_val = (int)((double)r * (step / (double)NUM_STEPS));
        int g_val = (int)((double)g * (step / (double)NUM_STEPS));
        int b_val = (int)((double)b * (step / (double)NUM_STEPS));

        if (gpioPWM(17, 255 - r_val) < 0) {
            syslog(LOG_ERR, "Failed to set PWM on GPIO17");
        }
        if (gpioPWM(18, 255 - g_val) < 0) {
            syslog(LOG_ERR, "Failed to set PWM on GPIO18");
        }
        if (gpioPWM(27, 255 - b_val) < 0) {
            syslog(LOG_ERR, "Failed to set PWM on GPIO27");
        }

        usleep(step_time * 1000);
    }
}

int main() {
