#define TCS34725_CONTROL 0x03
#define TCS34725_ID 0x12
#define TCS34725_CLEAR 0x14
#define TCS34725_RED 0x16
#define TCS34725_GREEN 0x18
#define TCS34725_BLUE 0x1A

#define GPIO_LINE 17
#define GPIO_DIRECTION_OUT 1
#define GPIO_VALUE_HIGH 1
#define GPIO_VALUE_LOW 0

#define CALIBRATION_RED_OFFSET 100
#define CALIBRATION_GREEN_OFFSET 100
#define CALIBRATION_BLUE_OFFSET 100
#define CALIBRATION_CLEAR_OFFSET 100

#define RED_THRESHOLD 200

static gpiod_line *gpiod_line_gpio17;
static int i2c_fd;

void cleanup(int signum) {
    if (gpiod_line_gpio17) {
        gpiod_line_put(gpiod_line_gpio17);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

int main() {
    struct gpiod_line_request req;
    struct gpiod_line_request_flags flags;
    struct gpiod_line_value value;
    unsigned char data[4];
    unsigned short clear, red, green, blue;
    unsigned short calibrated_clear, calibrated_red, calibrated_green, calibrated_blue;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    gpiod_line_gpio17 = gpiod_line_request_by_name("gpio%d", GPIO_LINE, &req, &flags);
    if (!gpiod_line_gpio17) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_direction_set(gpiod_line_gpio17, GPIO_DIRECTION_OUT);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_put(gpiod_line_gpio17);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_put(gpiod_line_gpio17);
        exit(EXIT_FAILURE);
    }

    // Initialize sensor
    if (write(i2c_fd, &TCS34725_PON, 1) != 1) {
        perror("Failed to power on sensor");
        close(i2c_fd);
        gpiod_line_put(gpiod_line_gpio17);
        exit(EXIT_FAILURE);
    }
    usleep(100000); // Wait for sensor to power up

    if (write(i2c_fd, &TCS34725_AEN, 1) != 1) {
        perror("Failed to enable RGBC");
        close(i2c_fd);
        gpiod_line_put(gpiod_line_gpio17);
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, &TCS34725_ATIME, 1) != 1) {
        perror("Failed to set integration time");
        close(i2c_fd);
        gpiod_line_put(gpiod_line_gpio17);
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, &TCS34725_CONTROL, 1) != 1) {
        perror("Failed to set control register");
        close(i2c_fd);
        gpiod_line_put(gpiod_line_gpio17);
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, &data, 1) != 1 || data[0] != TCS34725_ID) {
        perror("Failed to verify sensor ID");
        close(i2c_fd);
        gpiod_line_put(gpiod_line_gpio17);
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (read(i2c_fd, data, 8) != 8) {
            perror("Failed to read sensor data");
            close(i2c_fd);
            gpiod_line_put(gpiod_line_gpio17);
            exit(EXIT_FAILURE);
        }

        clear = (data[0] << 8) | data[1];
        red = (data[2] << 8) | data[3];
        green = (data[4] << 8) | data[5];
        blue = (data[6] << 8) | data[7];

        calibrated_clear = clear - CALIBRATION_CLEAR_OFFSET;
        calibrated_red = red - CALIBRATION_RED_OFFSET;
        calibrated_green = green - CALIBRATION_GREEN_OFFSET;
        calibrated_blue = blue - CALIBRATION_BLUE_OFFSET;

        printf("Calibrated RGB: %hu %hu %hu %hu\n", calibrated_red, calibrated_green, calibrated_blue, calibrated_clear);

        if (calibrated_red > RED_THRESHOLD) {
            gpiod_line_value_set(gpiod_line_gpio17, GPIO_VALUE_HIGH);
        } else {
            gpiod_line_value_set(gpiod_line_gpio17, GPIO_VALUE_LOW);
        }

        usleep(200000); // Poll every 200 ms
    }

    cleanup(0);
    return 0;
}

