#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_ADDR 0x23
#define LUX_SCALE 1.2
#define MAX_BRIGHTNESS 255

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int read_light_sensor() {
    int msb, lsb;
    int lux;

    if (i2c_write_device(I2C_ADDR, 0x10, 1) != 1) {
        fprintf(stderr, "Failed to set BH1750 to continuous mode.\n");
        return -1;
    }

    usleep(180000); // Wait approximately 180 ms

    if (i2c_read_device(I2C_ADDR, &msb, 2) != 2) {
        fprintf(stderr, "Failed to read BH1750 data.\n");
        return -1;
    }

    lux = ((msb << 8) | lsb) / LUX_SCALE;

    return lux;
}

void set_brightness(int brightness) {
    int duty_cycle = (brightness * 1000) / MAX_BRIGHTNESS;
    int wave_id = wave_create();

    if (wave_id < 0) {
        fprintf(stderr, "Failed to create wave.\n");
        return;
    }

    wave_add_generic(1, &duty_cycle, 1);
    wave_send_repeat(wave_id);

    if (wave_id < 0) {
        fprintf(stderr, "Failed to send wave.\n");
        wave_delete(wave_id);
        return;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO18 as output.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        int lux = read_light_sensor();

        if (lux < 0) {
            continue;
        }

        int brightness = (int) (MAX_BRIGHTNESS * log(lux + 1) / log(1000 + 1));
        set_brightness(brightness);

        usleep(100000); // Sleep for 100 ms
    }

    wave_clear();
    gpioTerminate();

    return 0;
}

