    uint8_t data[2];

    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Error writing to BH1750");
        return -1;
    }

    usleep(BH1750_CONVERSION_TIME * 1000);

    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from BH1750");
        return -1;
    }

    uint16_t raw = (data[0] << 8) | data[1];
    int lux = raw / 1.2;

    if (lux < 10) {
        lux = 10;
    } else if (lux > 300) {
        lux = 300;
    }

    return lux;
}

void send_apa102_frame(uint8_t brightness) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long) &brightness,
        .rx_buf = 0,
        .len = 4,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    for (int i = 0; i < NUM_LEDS; i++) {
        uint32_t led_frame = (0xE0 | brightness) << 24 | 0x00 << 16 | 0x00 << 8 | 0x00;
        tr.tx_buf = (unsigned long) &led_frame;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
            perror("Error sending APA102 frame");
            return;
        }
    }

    uint32_t end_frame = 0xFF << 24 | 0xFF << 16 | 0xFF << 8 | 0xFF;
    tr.tx_buf = (unsigned long) &end_frame;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending APA102 end frame");
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        int lux = read_bh1750_lux();
        if (lux < 0) {
            continue;
        }

        uint8_t brightness = (uint8_t)(lux * LUX_TO_BRIGHTNESS_SCALE);
        send_apa102_frame(brightness);

        sleep(1);
    }

    handle_sigint(0);
    return 0;
}
```

This C program reads ambient light from a BH1750 I2C sensor and adjusts the brightness of an APA102 LED strip via SPI proportionally to the measured lux. It uses the Linux I2C and SPI character devices directly, initializes the BH1750 in One-Time High-Resolution mode, waits for the conversion to complete, reads the 2-byte result, converts to lux, maps the lux range to the APA102's 5-bit global brightness, and sends an APA102 frame. It handles SIGINT gracefully by turning off the LEDs and closing all file descriptors. Robust error handling is implemented for all I/O operations, sensor-absent scenarios, and bus errors.

