#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_ADDR_LOW 0x23
#define I2C_ADDR_HIGH 0x5C
#define I2C_BUS 1
#define SPI_CHANNEL 0
#define SPI_MOSI 10
#define SPI_SCLK 11
#define LUX_READ_CMD 0x21
#define LUX_READ_DATA_LEN 2
#define LUX_READ_WAIT_MS 180
#define BRIGHTNESS_MAX 31
#define BRIGHTNESS_MIN 0
#define BRIGHTNESS_STEP 1
#define FADE_TIME_MS 500
#define FADE_DELAY_MS 100

int g_piHandle = 0;
int g_i2cHandle = 0;
int g_spiHandle = 0;
int g_brightness = 0;

void handle_signal(int signum) {
    if (g_spiHandle != 0) {
        spiStop(g_spiHandle);
        spiClose(g_spiHandle);
    }
    if (g_i2cHandle != 0) {
        i2cUnexport(g_i2cHandle);
    }
    if (g_piHandle != 0) {
        pigpioStop();
    }
    exit(signum);
}

int read_lux(int addr) {
    int lux = 0;
    uint8_t data[LUX_READ_DATA_LEN];

    if (i2cRead(g_i2cHandle, addr, LUX_READ_DATA_LEN, data) == LUX_READ_DATA_LEN) {
        lux = (data[0] << 8) | data[1];
    }

    return lux;
}

void set_brightness(int brightness) {
    uint8_t brightness_byte = (brightness & 0x1F) << 4;
    uint8_t data[2] = {brightness_byte, 0};

    spiWrite(g_spiHandle, data, 2);
}

void fade_brightness(int target_brightness) {
    int step = (target_brightness > g_brightness) ? BRIGHTNESS_STEP : -BRIGHTNESS_STEP;
    int current_brightness = g_brightness;

    while (current_brightness != target_brightness) {
        current_brightness += step;
        set_brightness(current_brightness);
        usleep(FADE_TIME_MS * 1000 / BRIGHTNESS_MAX);
    }

    g_brightness = target_brightness;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    g_piHandle = pigpioOpen(0, 0, 0);
    if (g_piHandle < 0) {
        fprintf(stderr, "Failed to open pigpio\n");
        return 1;
    }

    g_i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR_LOW, 0);
    if (g_i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C at address 0x%02X\n", I2C_ADDR_LOW);
    }

    g_i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR_HIGH, 0);
    if (g_i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C at address 0x%02X\n", I2C_ADDR_HIGH);
    }

    g_spiHandle = spiOpen(SPI_CHANNEL, SPI_MOSI, SPI_SCLK, 0);
    if (g_spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        return 1;
    }

    signal(SIGINT, handle_signal);

    while (1) {
        int lux_sum = 0;
        int sensor_count = 0;

        if (g_i2cHandle != 0) {
            i2cWriteReg(g_i2cHandle, I2C_ADDR_LOW, LUX_READ_CMD, 0);
            usleep(LUX_READ_WAIT_MS * 1000);
            lux_sum += read_lux(I2C_ADDR_LOW);
            sensor_count++;
        }

        if (g_i2cHandle != 0) {
            i2cWriteReg(g_i2cHandle, I2C_ADDR_HIGH, LUX_READ_CMD, 0);
            usleep(LUX_READ_WAIT_MS * 1000);
            lux_sum += read_lux(I2C_ADDR_HIGH);
            sensor_count++;
        }

        if (sensor_count > 0) {
            int avg_lux = lux_sum / sensor_count;
            int target_brightness = (BRIGHTNESS_MAX - BRIGHTNESS_MIN) * (BRIGHTNESS_MAX - avg_lux) / (BRIGHTNESS_MAX - BRIGHTNESS_MIN);
            fade_brightness(target_brightness);
        }

        usleep(FADE_DELAY_MS * 1000);
    }

    return 0;
}

