#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_DATA_REG 0x04
#define MAX_RETRIES 3
#define RETRY_DELAY 100
#define INTEGRATION_TIME 100
#define GAIN 1.0 / 8.0
#define LUX_SCALE 0.0288
#define LUX_MAX 120000
#define GAMMA 2.2

gpiod_chip *chip;
gpiod_line *line;

void cleanup(int signum) {
    gpiod_line_request_free(line);
    gpiod_chip_put(chip);
    close(open(I2C_BUS, O_RDWR));
    exit(signum);
}

int read_i2c_register(int fd, uint8_t reg, uint16_t *value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_smbus_read_word_data(fd, reg) == 0) {
            *value = i2c_smbus_read_word_data(fd, reg);
            return 0;
        }
        retries++;
        usleep(RETRY_DELAY * 1000);
    }
    return -1;
}

int main() {
    int fd;
    uint16_t raw_value;
    double lux;
    int brightness;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        exit(EXIT_FAILURE);
    }

    if (read_i2c_register(fd, CONFIG_REG, &raw_value) < 0) {
        perror("Failed to read configuration register");
        exit(EXIT_FAILURE);
    }

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if ((line = gpiod_line_request_by_name(chip, "gpio18", "ws2812b_control", GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (read_i2c_register(fd, ALS_DATA_REG, &raw_value) < 0) {
            perror("Failed to read ALS data");
            continue;
        }

        lux = raw_value * LUX_SCALE;
        brightness = (int)(255 * pow(lux / LUX_MAX, 1.0 / GAMMA));

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Bit-banging GPIO for WS2812B (not feasible, so using threshold-based control)
        if (brightness > 128) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        usleep(200 * 1000);
    }

    return 0;
}

