#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define BLINK_INTERVAL 500
#define FLAME_DETECT_INTERVAL 100
#define FLAME_CHECK_INTERVAL 50
#define ERROR_BLINK_INTERVAL 100
#define ERROR_BEEP_PATTERN {200, 200, 600, 200}
#define ERROR_BEEP_REPEAT 3

gpiod_line *flame_sensor_line;
gpiod_line *buzzer_line;
gpiod_line *led_line;

void handle_signal(int signum) {
    gpiod_line_free(flame_sensor_line);
    gpiod_line_free(buzzer_line);
    gpiod_line_free(led_line);
    exit(signum);
}

void blink_led(int on_time, int off_time) {
    gpiod_line_set_value(led_line, 1);
    usleep(on_time * 1000);
    gpiod_line_set_value(led_line, 0);
    usleep(off_time * 1000);
}

void error_signal() {
    for (int i = 0; i < 5; i++) {
        blink_led(ERROR_BLINK_INTERVAL, ERROR_BLINK_INTERVAL);
    }
    for (int j = 0; j < ERROR_BEEP_REPEAT; j++) {
        for (int k = 0; k < 4; k++) {
            usleep(ERROR_BEEP_PATTERN[k] * 1000);
        }
    }
}

int main() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    flame_sensor_line = gpiod_line_request_by_name("gpio4", "flame_sensor", 0);
    if (!flame_sensor_line) {
        perror("Failed to request flame sensor line");
        exit(1);
    }

    buzzer_line = gpiod_line_request_by_name("gpio17", "buzzer", 0);
    if (!buzzer_line) {
        perror("Failed to request buzzer line");
        gpiod_line_free(flame_sensor_line);
        exit(1);
    }

    led_line = gpiod_line_request_by_name("gpio18", "led", 0);
    if (!led_line) {
        perror("Failed to request LED line");
        gpiod_line_free(flame_sensor_line);
        gpiod_line_free(buzzer_line);
        exit(1);
    }

    gpiod_line_set_consumer(flame_sensor_line, "flame_sensor_consumer");
    gpiod_line_set_consumer(buzzer_line, "buzzer_consumer");
    gpiod_line_set_consumer(led_line, "led_consumer");

    gpiod_line_direction(flame_sensor_line, GPIO_DIRECTION_IN);
    gpiod_line_direction(buzzer_line, GPIO_DIRECTION_OUT);
    gpiod_line_direction(led_line, GPIO_DIRECTION_OUT);

    gpiod_line_set_value(led_line, 0);
    gpiod_line_set_value(buzzer_line, 0);

    // Self-test
    printf("Self-test started at %ld.%09ld\n", (long)ts.tv_sec, (long)ts.tv_nsec);
    blink_led(BLINK_INTERVAL, BLINK_INTERVAL);
    blink_led(BLINK_INTERVAL, BLINK_INTERVAL);

    int flame_detected = 0;
    for (int i = 0; i < 5; i++) {
        gpiod_line_get_value(flame_sensor_line, &flame_detected);
        if (flame_detected) {
            break;
        }
        usleep(FLAME_DETECT_INTERVAL * 1000);
    }

    if (flame_detected == 0) {
        printf("Sensor fault detected at %ld.%09ld\n", (long)ts.tv_sec, (long)ts.tv_nsec);
        error_signal();
        exit(1);
    }

    printf("Self-test passed at %ld.%09ld\n", (long)ts.tv_sec, (long)ts.tv_nsec);

    signal(SIGINT, handle_signal);

    while (1) {
        gpiod_line_get_value(flame_sensor_line, &flame_detected);
        if (flame_detected == 0) {
            gpiod_line_set_value(buzzer_line, 1);
            gpiod_line_set_value(led_line, 1);
            printf("Flame detected at %ld.%09ld\n", (long)ts.tv_sec, (long)ts.tv_nsec);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
            gpiod_line_set_value(led_line, 0);
            printf("Flame gone at %ld.%09ld\n", (long)ts.tv_sec, (long)ts.tv_nsec);
        }
        usleep(FLAME_CHECK_INTERVAL * 1000);
    }

    gpiod_line_free(flame_sensor_line);
    gpiod_line_free(buzzer_line);
    gpiod_line_free(led_line);

    return 0;
}

