#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x23
#define BUFFER_SIZE 60
#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio/gpio%d"

int i2c_fd;
int lux_buffer[BUFFER_SIZE];
int buffer_index = 0;

void handle_signal(int signum) {
    printf("Exiting...\n");
    close(i2c_fd);
    system(sprintf(getenv("HOME"), "echo %d > /sys/class/gpio/unexport", GPIO_PIN));
    exit(0);
}

int read_lux() {
    uint8_t cmd[2] = {0x10, 0x00};
    uint8_t data[2];
    int ret;

    ret = write(i2c_fd, cmd, 2);
    if (ret != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    ret = read(i2c_fd, data, 2);
    if (ret != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    uint16_t raw = (data[0] << 8) | data[1];
    return raw / 1.2;
}

double calculate_average_lux() {
    int sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += lux_buffer[i];
    }
    return (double)sum / BUFFER_SIZE;
}

void blink_led(double rate) {
    int period = (int)(1.0 / rate);
    if (period < 1) period = 1;

    for (int i = 0; i < 2 * period; i++) {
        char on_off[10];
        sprintf(on_off, GPIO_PATH, GPIO_PIN);
        sprintf(getenv("HOME"), "%s/value", on_off);

        if (i < period) {
            system("echo 1 > /sys/class/gpio/export");
            system(sprintf(getenv("HOME"), "%s/value", on_off));
        } else {
            system("echo 0 > /sys/class/gpio/export");
            system(sprintf(getenv("HOME"), "%s/value", on_off));
        }

        usleep(1000000 / (2 * rate));
    }
}

int main() {
    signal(SIGINT, handle_signal);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C address");
        return 1;
    }

    system(sprintf(getenv("HOME"), "echo %d > /sys/class/gpio/export", GPIO_PIN));
    char on_off[10];
    sprintf(on_off, GPIO_PATH, GPIO_PIN);
    system("echo 0 > /sys/class/gpio/export");
    system(sprintf(getenv("HOME"), "%s/value", on_off));

    while (1) {
        int lux = read_lux();
        if (lux >= 0) {
            lux_buffer[buffer_index] = lux;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            double avg_lux = calculate_average_lux();
            double rate = 0.5 + (avg_lux / 1000) * 4.5;
            rate = fmin(rate, 5.0);
            rate = fmax(rate, 0.5);

            blink_led(rate);
        }

        sleep(1);
    }

    return 0;
}

