#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define SEGMENT_5 0b00100111

static void shift_out(struct gpiod_line *data, struct gpiod_line *clock, struct gpiod_line *latch, uint8_t value) {
    for (int i = 0; i < 8; i++) {
        gpiod_line_set_value(data, (value >> i) & 1);
        gpiod_line_set_value(clock, 1);
        usleep(100); // Adjust timing as needed
        gpiod_line_set_value(clock, 0);
    }
    gpiod_line_set_value(latch, 1);
    usleep(100); // Adjust timing as needed
    gpiod_line_set_value(latch, 0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *data, *clock, *latch;

    // Initialize libgpiod
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    if (gpiod_line_request_by_name(chip, "gpio%d", DATA_PIN, "data", &data) < 0) {
        perror("gpiod_line_request_by_name (data)");
        goto cleanup;
    }
    if (gpiod_line_request_by_name(chip, "gpio%d", CLOCK_PIN, "clock", &clock) < 0) {
        perror("gpiod_line_request_by_name (clock)");
        goto cleanup_data;
    }
    if (gpiod_line_request_by_name(chip, "gpio%d", LATCH_PIN, "latch", &latch) < 0) {
        perror("gpiod_line_request_by_name (latch)");
        goto cleanup_clock;
    }

    // Set lines as outputs
    if (gpiod_line_direction_output(data) < 0) {
        perror("gpiod_line_direction_output (data)");
        goto cleanup_latch;
    }
    if (gpiod_line_direction_output(clock) < 0) {
        perror("gpiod_line_direction_output (clock)");
        goto cleanup_data;
    }
    if (gpiod_line_direction_output(latch) < 0) {
        perror("gpiod_line_direction_output (latch)");
        goto cleanup_clock;
    }

    // Blink '5' indefinitely
    while (1) {
        shift_out(data, clock, latch, SEGMENT_5);
        usleep(500000); // 500 ms on
        shift_out(data, clock, latch, 0); // Turn off
        usleep(500000); // 500 ms off
    }

cleanup_latch:
    gpiod_line_free(latch);
cleanup_clock:
    gpiod_line_free(clock);
cleanup_data:
    gpiod_line_free(data);
cleanup:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

