#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

static gpiod_chip *chip;
static gpiod_line *led_line;
static gpiod_line *button_line;
static gpiod_event *button_event;

void cleanup(void) {
    if (button_event) {
        gpiod_event_free(button_event);
    }
    if (button_line) {
        gpiod_line_free(button_line);
    }
    if (led_line) {
        gpiod_line_free(led_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(0);
}

void handle_sigint(int signum) {
    cleanup();
}

int main(void) {
    int ret;

    // Register signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open GPIO chip 0
    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Request LED line (BCM GPIO17, physical pin 11) as output initially low
    led_line = gpiod_line_request(chip, 17, "blink_led", 0, GPIOD_LINE_DIRECTION_OUTPUT);
    if (!led_line) {
        perror("gpiod_line_request (LED)");
        cleanup();
    }
    ret = gpiod_line_set_value(led_line, 0);
    if (ret) {
        perror("gpiod_line_set_value (LED)");
        cleanup();
    }

    // Request button line (BCM GPIO18, physical pin 12) as input with internal pull-up and falling-edge event detection
    button_line = gpiod_line_request(chip, 18, "blink_button", 0, GPIOD_LINE_DIRECTION_INPUT);
    if (!button_line) {
        perror("gpiod_line_request (button)");
        cleanup();
    }
    ret = gpiod_line_set_debounce(button_line, 1000); // 1 ms debounce
    if (ret) {
        perror("gpiod_line_set_debounce (button)");
        cleanup();
    }
    ret = gpiod_line_set_value(button_line, 1); // Set pull-up
    if (ret) {
        perror("gpiod_line_set_value (button)");
        cleanup();
    }
    ret = gpiod_line_set_edge(button_line, GPIOD_LINE_BOTH_EDGES);
    if (ret) {
        perror("gpiod_line_set_edge (button)");
        cleanup();
    }

    // Request event on button line
    button_event = gpiod_event_request(button_line, "blink_button_event", 1000); // 1 second timeout
    if (!button_event) {
        perror("gpiod_event_request");
        cleanup();
    }

    // Main loop: toggle LED and monitor button events
    while (1) {
        gpiod_line_set_value(led_line, 1); // Turn LED on
        sleep(1);

        ret = gpiod_event_wait(button_event, 1000); // Wait for 1 second
        if (ret < 0) {
            perror("gpiod_event_wait");
            cleanup();
        } else if (ret > 0) {
            // Button pressed (falling edge detected)
            gpiod_line_set_value(led_line, 0); // Turn LED off
            printf("Button pressed, stopping LED blinking.\n");
            cleanup();
        }

        gpiod_line_set_value(led_line, 0); // Turn LED off
        sleep(1);

        ret = gpiod_event_wait(button_event, 1000); // Wait for 1 second
        if (ret < 0) {
            perror("gpiod_event_wait");
            cleanup();
        } else if (ret > 0) {
            // Button pressed (falling edge detected)
            gpiod_line_set_value(led_line, 0); // Turn LED off
            printf("Button pressed, stopping LED blinking.\n");
            cleanup();
        }
    }

    cleanup();
    return 0;
}

