#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    int gpio = 5; // GPIO5 (physical pin 29)

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    // Set GPIO5 as output
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO5 as output.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (!stop) {
        // Turn LED on
        if (gpioWrite(gpio, 1) < 0) {
            fprintf(stderr, "Failed to turn LED on.\n");
            stop = 1;
        } else {
            printf("LED ON\n");
            fflush(stdout);
        }

        // Wait 750 ms
        gpioDelay(750000);

        // Turn LED off
