#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <sys/time.h>

#define PWM_FREQ 100 // Hz
#define PWM_PERIOD (1000000 / PWM_FREQ) // microseconds
#define PWM_DUTY_MAX 100 // %

static gpiod_chip *chip;
static gpiod_line *red_line, *green_line, *blue_line;

void cleanup(int signum) {
    if (red_line) {
        gpiod_line_release(red_line);
        gpiod_line_unref(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
        gpiod_line_unref(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
        gpiod_line_unref(blue_line);
    }
    if (chip) {
        gpiod_chip_unref(chip);
    }
    exit(signum);
}

int main() {
    struct timespec sleep_time;
    int red_duty, green_duty, blue_duty;

    // Seed the random number generator
    srand(time(NULL));

    // Open the GPIO chip
    if (!(chip = gpiod_chip_open_by_number(0))) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO lines
    if (!(red_line = gpiod_chip_get_line(chip, 24))) {
        fprintf(stderr, "Failed to get GPIO line for Red\n");
        goto cleanup_red;
    }
    if (gpiod_line_request_output(red_line, "Red LED", 0) < 0) {
        fprintf(stderr, "Failed to request Red GPIO as output\n");
        goto cleanup_red;
    }

    if (!(green_line = gpiod_chip_get_line(chip, 23))) {
        fprintf(stderr, "Failed to get GPIO line for Green\n");
        goto cleanup_green;
    }
    if (gpiod_line_request_output(green_line, "Green LED", 0) < 0) {
        fprintf(stderr, "Failed to request Green GPIO as output\n");
        goto cleanup_green;
    }

    if (!(blue_line = gpiod_chip_get_line(chip, 18))) {
        fprintf(stderr, "Failed to get GPIO line for Blue\n");
        goto cleanup_blue;
    }
    if (gpiod_line_request_output(blue_line, "Blue LED", 0) < 0) {
        fprintf(stderr, "Failed to request Blue GPIO as output\n");
        goto cleanup_blue;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        // Generate random duty cycles
        red_duty = rand() % (PWM_DUTY_MAX + 1);
        green_duty = rand() % (PWM_DUTY_MAX + 1);
        blue_duty = rand() % (PWM_DUTY_MAX + 1);

        // Calculate sleep time for each color
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = (red_duty * PWM_PERIOD * 1000) / PWM_DUTY_MAX;

        // Set PWM duty cycle for Red
        gpiod_line_set_value(red_line, 1);
        nanosleep(&sleep_time, NULL);
        gpiod_line_set_value(red_line, 0);

        // Set PWM duty cycle for Green
        sleep_time.tv_nsec = (green_duty * PWM_PERIOD * 1000) / PWM_DUTY_MAX;
        gpiod_line_set_value(green_line, 1);
        nanosleep(&sleep_time, NULL);
        gpiod_line_set_value(green_line, 0);

        // Set PWM duty cycle for Blue
        sleep_time.tv_nsec = (blue_duty * PWM_PERIOD * 1000) / PWM_DUTY_MAX;
        gpiod_line_set_value(blue_line, 1);
        nanosleep(&sleep_time, NULL);
        gpiod_line_set_value(blue_line, 0);

        // Wait 100 ms before changing colors again
        sleep(1);
    }

cleanup_blue:
    gpiod_line_release(blue_line);
    gpiod_line_unref(blue_line);

cleanup_green:
    gpiod_line_release(green_line);
    gpiod_line_unref(green_line);

cleanup_red:
    gpiod_line_release(red_line);
    gpiod_line_unref(red_line);

    gpiod_chip_unref(chip);

    return 0;
}

