#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_ADDR 0x19
#define I2C_BUS 1
#define I2C_CTRL_REG1_A 0x20
#define I2C_CTRL_REG4_A 0x23
#define I2C_OUT_X_L_A 0x28
#define I2C_OUT_Y_L_A 0x2A
#define I2C_OUT_Z_L_A 0x2C
#define G_THRESHOLD 2.0
#define GPIO_PIN 17
#define LOG_FILE "impact_log.txt"

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int i2c_write(int handle, uint8_t reg, uint8_t value) {
    int ret = i2c_write_device(handle, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C register\n");
        return -1;
    }
    ret = i2c_write_device(handle, &value, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C register\n");
        return -1;
    }
    return 0;
}

int i2c_read(int handle, uint8_t reg, uint8_t *data, int length) {
    int ret = i2c_write_device(handle, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C register\n");
        return -1;
    }
    ret = i2c_read_device(handle, data, length);
    if (ret != length) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }
    return 0;
}

double calculate_g_force(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z) / 16384.0;
}

int main(int argc, char *argv[]) {
    double threshold = G_THRESHOLD;
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint8_t ctrl_reg1_a = 0x27;
    uint8_t ctrl_reg4_a = 0x00;

    if (i2c_write(handle, I2C_CTRL_REG1_A, ctrl_reg1_a) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1_A\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    if (i2c_write(handle, I2C_CTRL_REG4_A, ctrl_reg4_a) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4_A\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        uint8_t data[6];
        if (i2c_read(handle, I2C_OUT_X_L_A | 0x80, data, 6) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        double g_force = calculate_g_force(x, y, z);

        if (g_force > threshold) {
            gpioWrite(GPIO_PIN, PI_HIGH);
            usleep(50000);
            gpioWrite(GPIO_PIN, PI_LOW);

            time_t now = time(NULL);
            fprintf(log_file, "%s: G-force %.2f\n", ctime(&now), g_force);
        }

        usleep(100000); // 10 Hz polling
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

