#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

#define FXOS8700CQ_I2C_ADDR 0x1F
#define FXOS8700CQ_I2C_BUS 1
#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_XYZ_DATA_CFG 0x0E
#define FXOS8700CQ_OUT_X_MSB 0x01
#define FXOS8700CQ_WHO_AM_I_VALUE 0xC7
#define SENSITIVITY 4096.0
#define GRAVITY 9.81
#define IMPACT_THRESHOLD (2 * GRAVITY)
#define SAMPLE_INTERVAL 50

void log_impact(const char *timestamp, double x, double y, double z, double magnitude) {
    FILE *log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s,%f,%f,%f,%f\n", timestamp, x, y, z, magnitude);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(FXOS8700CQ_I2C_BUS, FXOS8700CQ_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    uint8_t who_am_i;
    if (i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_WHO_AM_I, 1, &who_am_i, 1) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != FXOS8700CQ_WHO_AM_I_VALUE) {
        fprintf(stderr, "Invalid WHO_AM_I value, expected 0xC7, got 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    uint8_t config = 0x00; // ±2g mode
    if (i2cWriteI2CBlockData(i2c_handle, FXOS8700CQ_XYZ_DATA_CFG, 1, &config) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    config = 0x01; // Active mode, 200 Hz ODR
    if (i2cWriteI2CBlockData(i2c_handle, FXOS8700CQ_CTRL_REG1, 1, &config) < 0) {
        fprintf(stderr, "Failed to activate sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct timespec start_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    while (1) {
        uint8_t data[6];
        if (i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, 6, data, 6) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        double x = ((data[0] << 8) | data[1]) >> 2;
        double y = ((data[2] << 8) | data[3]) >> 2;
        double z = ((data[4] << 8) | data[5]) >> 2;

        double magnitude = sqrt(x * x + y * y + z * z);
        magnitude *= SENSITIVITY * GRAVITY;

        if (magnitude > IMPACT_THRESHOLD) {
            struct tm *time_info;
            time_t current_time = time(NULL);
            time_info = localtime(&current_time);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
            log_impact(timestamp, x, y, z, magnitude);
        }

        nanosleep(&start_time, NULL);
        start_time.tv_sec += SAMPLE_INTERVAL / 1000;
        start_time.tv_nsec += (SAMPLE_INTERVAL % 1000) * 1000000;
        if (start_time.tv_nsec >= 1000000000) {
            start_time.tv_sec++;
            start_time.tv_nsec -= 1000000000;
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

