This C program initializes the Adafruit FXOS8700CQ 6-axis accelerometer/magnetometer on a Raspberry Pi Zero W using the pigpio library. It verifies the sensor by reading the WHO_AM_I register, initializes the sensor for ±2g mode, and then continuously samples the acceleration data. If the computed magnitude exceeds the 2g threshold (19.62 m/s^2), it logs the timestamp, x, y, z, and magnitude to 'impact_log.txt'. The program samples every 50 ms and handles errors gracefully, closing the I2C handle and terminating pigpio on SIGINT (Ctrl+C).

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>

#define I2C_DEV "/dev/i2c-1"
#define GYRO_ADDR 0x69
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SENSITIVITY 0.00875
#define NUM_CALIBRATION_SAMPLES 100
#define LOG_FILE "gyro_log.txt"
#define LOG_INTERVAL_MS 50

int i2c_fd;
FILE *log_file;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int read_i2c_register(uint8_t reg, uint8_t *data, size_t len) {
    int ret;
    uint8_t cmd[len + 1];

    cmd[0] = reg;
    memcpy(cmd + 1, data, len);

    ret = write(i2c_fd, cmd, len + 1);
    if (ret != len + 1) {
        perror("write");
        return -1;
    }

    ret = read(i2c_fd, data, len);
    if (ret != len) {
        perror("read");
        return -1;
    }

    return 0;
}

int write_i2c_register(uint8_t reg, const uint8_t *data, size_t len) {
    int ret;
    uint8_t cmd[len + 1];

    cmd[0] = reg;
    memcpy(cmd + 1, data, len);

    ret = write(i2c_fd, cmd, len + 1);
    if (ret != len + 1) {
        perror("write");
        return -1;
    }

    return 0;
}

int main() {
    uint8_t who_am_i;
    uint8_t ctrl_reg1 = 0x0F;
    uint8_t ctrl_reg4 = 0x00;
    int ret;
    uint8_t data[6];
    int32_t x, y, z;
    double x_offset, y_offset, z_offset;
    struct timespec ts;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR);
    if (ret < 0) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    ret = read_i2c_register(WHO_AM_I, &who_am_i, 1);
    if (ret < 0 || who_am_i != 0xD3) {
        fprintf(stderr, "GY-50 L3G4200D not found or I2C error\n");
        close(i2c_fd);
        return 1;
    }

    ret = write_i2c_register(CTRL_REG1, &ctrl_reg1, 1);
    if (ret < 0) {
        perror("write");
        close(i2c_fd);
        return 1;
    }

    ret = write_i2c_register(CTRL_REG4, &ctrl_reg4, 1);
    if (ret < 0) {
        perror("write");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        close(i2c_fd);
        return 1;
    }

    // Perform calibration
    for (int i = 0; i < NUM_CALIBRATION_SAMPLES; i++) {
        ret = read_i2c_register(OUT_X_L, data, 6);
        if (ret < 0) {
            perror("read");
            fclose(log_file);
            close(i2c_fd);
            return 1;
        }

        x = (int16_t)((data[1] << 8) | data[0]);
        y = (int16_t)((data[3] << 8) | data[2]);
        z = (int16_t)((data[5] << 8) | data[4]);

        x_offset += x;
        y_offset += y;
        z_offset += z;
    }

    x_offset /= NUM_CALIBRATION_SAMPLES;
    y_offset /= NUM_CALIBRATION_SAMPLES;
    z_offset /= NUM_CALIBRATION_SAMPLES;

    while (1) {
        ret = read_i2c_register(OUT_X_L, data, 6);
        if (ret < 0) {
            perror("read");
            fclose(log_file);
            close(i2c_fd);
            return 1;
        }

        x = (int16_t)((data[1] << 8) | data[0]);
        y = (int16_t)((data[3] << 8) | data[2]);
        z = (int16_t)((data[5] << 8) | data[4]);

        x -= x_offset;
        y -= y_offset;
        z -= z_offset;

