#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define I2C_DEVID 0x00
#define I2C_DATA_REG 0x32
#define I2C_DATA_LEN 6
#define LED_GPIO 17
#define MAX_ACCEL 2.0
#define LOG_FILE "accel_log.txt"

void handle_signal(int signum) {
    if (pi != 0) {
        piStop();
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

void write_i2c_register(int reg, uint8_t value) {
    if (i2cWriteReg(pi, I2C_BUS, I2C_ADDR, reg, value) < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", reg);
        exit(1);
    }
}

void read_i2c_data(uint8_t *data) {
    if (i2cReadReg(pi, I2C_BUS, I2C_ADDR, I2C_DATA_REG, I2C_DATA_LEN, data) < 0) {
        fprintf(stderr, "Failed to read I2C data\n");
        return;
    }
}

int main() {
    int pi = 0;
    FILE *log_file = NULL;
    uint8_t data[I2C_DATA_LEN];
    double x, y, z;
    struct timespec ts;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    pi = pigpio_start();
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Configure ADXL345
    write_i2c_register(0x2D, 0x0B); // Set to full-resolution, ±2g range
    uint8_t devid;
    if (i2cReadReg(pi, I2C_BUS, I2C_ADDR, I2C_DEVID, 1, &devid) < 0 || devid != 0xE5) {
        fprintf(stderr, "Failed to verify ADXL345 DEVID register\n");
        return 1;
    }

    // Set LED GPIO
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_i2c_data(data);

        x = (double)data[0] * 256 + data[1];
        y = (double)data[2] * 256 + data[3];
        z = (double)data[4] * 256 + data[5];

        x /= 256.0;
        y /= 256.0;
        z /= 256.0;

        if (abs(x) > MAX_ACCEL || abs(y) > MAX_ACCEL || abs(z) > MAX_ACCEL) {
            if (gpioWrite(LED_GPIO, PI_ON) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
            }
        } else {
            if (gpioWrite(LED_GPIO, PI_OFF) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
            }
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%.3f,%.3f,%.3f\n", (long)ts.tv_sec, (long)ts.tv_nsec, x, y, z);

        usleep(100000); // 100 ms delay
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (pi != 0) {
        piStop();
    }

    return 0;
}

