#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CONTROL_REG 0x00
#define ENABLE_MEASUREMENT 0x80
#define SAMPLE_INTERVAL 10000 // 10 ms

FILE *log_file;

void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (pi >= 0) {
        pigpio_stop();
    }
    exit(0);
}

int read_sensor_data(int sensor_addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, sensor_addr) < 0) {
        perror("Failed to acquire bus access/talk to slave");
        close(fd);
        return -1;
    }

    uint8_t control_byte = ENABLE_MEASUREMENT;
