        usleep(40000); // Stall for 40 microseconds
        if (spiXfer(spiHandle, &accel_z_reg, 2, accel_z_data) < 0) {
            fprintf(stderr, "Error reading accelerometer Z data\n");
            continue;
        }

        uint64_t timestamp = time(NULL) * 1000 + usleep(0);

        fprintf(csvFile, "%llu,%f,%f,%f,%f,%f,%f\n", timestamp,
                (float)gyro_x_data[1] * GYRO_SENSITIVITY,
