#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_GPIO 8
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_BUF_SIZE 2
#define SPI_TIMEOUT 1000
#define GYRO_SCALE 0.02
#define ACCL_SCALE 0.00025
#define LOG_INTERVAL 100

struct spi_ioc_transfer spi_transfer;
struct gpiod_chip *chip;
struct gpiod_line *cs_line;

void spi_transfer_init(uint8_t reg_addr) {
    spi_transfer.tx_buf = (unsigned long) &reg_addr;
    spi_transfer.rx_buf = (unsigned long) &reg_addr;
    spi_transfer.len = 2;
    spi_transfer.delay_usecs = 0;
    spi_transfer.speed_hz = SPI_SPEED;
    spi_transfer.bits_per_word = 16;
    spi_transfer.cs_change = 1;
}

int spi_transfer_read(uint8_t reg_addr, uint16_t *data) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &spi_transfer.bits_per_word) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &spi_transfer.bits_per_word) < 0) {
        perror("Failed to read bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_transfer.speed_hz) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &spi_transfer.speed_hz) < 0) {
        perror("Failed to read SPI speed");
        close(fd);
        return -1;
    }

    spi_transfer_init(reg_addr);

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
        perror("Failed SPI transfer");
        close(fd);
        return -1;
    }

    *data = (uint16_t) spi_transfer.rx_buf;
    close(fd);
    return 0;
}

void setup_gpiod() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    cs_line = gpiod_line_request_any(chip, "CS", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!cs_line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_value(cs_line, 1)) {
        fprintf(stderr, "Failed to set GPIO line value\n");
        gpiod_line_release(cs_line);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpiod() {
    gpiod_line_release(cs_line);
    gpiod_chip_put(chip);
}

void handle_signal(int signum) {
    cleanup_gpiod();
    exit(EXIT_SUCCESS);
}

int main() {
    setup_gpiod();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        uint16_t gyro_x, gyro_y, gyro_z, acc_x, acc_y, acc_z;

        if (spi_transfer_read(0x04, &gyro_x) < 0 ||
            spi_transfer_read(0x06, &gyro_y) < 0 ||
            spi_transfer_read(0x08, &gyro_z) < 0 ||
            spi_transfer_read(0x0A, &acc_x) < 0 ||
            spi_transfer_read(0x0C, &acc_y) < 0 ||
            spi_transfer_read(0x0E, &acc_z) < 0) {
            fprintf(stderr, "Failed to read IMU data\n");
            cleanup_gpiod();
            exit(EXIT_FAILURE);
        }

        printf("Gyro X: %.2f, Y: %.2f, Z: %.2f\n", gyro_x * GYRO_SCALE, gyro_y * GYRO_SCALE, gyro_z * GYRO_SCALE);
        printf("Accel X: %.4f, Y: %.4f, Z: %.4f\n", acc_x * ACCL_SCALE, acc_y * ACCL_SCALE, acc_z * ACCL_SCALE);

        usleep(LOG_INTERVAL * 1000);
    }

    cleanup_gpiod();
    return 0;
}

