        fprintf(stderr, "Failed to set GPIO line value\n");
        gpiod_line_release(cs_line);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpiod() {
    gpiod_line_release(cs_line);
    gpiod_chip_put(chip);
}

void handle_signal(int signum) {
    cleanup_gpiod();
    exit(EXIT_SUCCESS);
}

int main() {
    setup_gpiod();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        uint16_t gyro_x, gyro_y, gyro_z, acc_x, acc_y, acc_z;

        if (spi_transfer_read(0x04, &gyro_x) < 0 ||
            spi_transfer_read(0x06, &gyro_y) < 0 ||
            spi_transfer_read(0x08, &gyro_z) < 0 ||
            spi_transfer_read(0x0A, &acc_x) < 0 ||
            spi_transfer_read(0x0C, &acc_y) < 0 ||
            spi_transfer_read(0x0E, &acc_z) < 0) {
            fprintf(stderr, "Failed to read IMU data\n");
            cleanup_gpiod();
            exit(EXIT_FAILURE);
        }

        printf("Gyro X: %.2f, Y: %.2f, Z: %.2f\n", gyro_x * GYRO_SCALE, gyro_y * GYRO_SCALE, gyro_z * GYRO_SCALE);
        printf("Accel X: %.4f, Y: %.4f, Z: %.4f\n", acc_x * ACCL_SCALE, acc_y * ACCL_SCALE, acc_z * ACCL_SCALE);

        usleep(LOG_INTERVAL * 1000);
    }

    cleanup_gpiod();
    return 0;
}
