        uint16_t dummy = 0x0000;

        if (spi_write_read(spi_handle, &reg_addr_read, 2, &data[i * 2], 2) != 2) {
            fprintf(stderr, "SPI transfer error for register 0x%04X\n", reg_addr[i]);
            return;
        }

        if (spi_write_read(spi_handle, &dummy, 2, &data[i * 2 + 1], 2) != 2) {
            fprintf(stderr, "SPI transfer error for dummy register 0x%04X\n", reg_addr[i]);
            return;
        }

        usleep(40000); // Stall time
    }

    for (int i = 0; i < 3; i++) {
        uint16_t gyro_data = (data[i * 2] << 8) | data[i * 2 + 1];
        uint16_t accel_data = (data[i * 2 + 3] << 8) | data[i * 2 + 4];

        printf("Gyro %c: %.2f deg/sec\tAccel %c: %.4f g\n", "XYZ"[i], gyro_data * GYRO_SCALING, "XYZ"[i], accel_data * ACCEL_SCALING);
    }
}

