    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!stop) {
        read_imu_data(spi_handle);
        usleep(READ_INTERVAL);
    }

    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

