#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define IMU_ADDR 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_DATA_XOUT_H 0x3B
#define GYRO_DATA_XOUT_H 0x43

int i2c_fd;

void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int read_i2c_register(uint8_t reg, uint8_t *data, size_t length) {
    int retries = 3;
    while (retries > 0) {
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            return -1;
        }
        if (read(i2c_fd, data, length) != length) {
            if (retries > 1) {
                printf("Read failed, retrying... (%d retries left)\n", retries - 1);
                sleep(1);
                retries--;
            } else {
                perror("Failed to read data");
                return -1;
            }
        } else {
            return 0;
        }
    }
    return -1;
}

int write_i2c_register(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, IMU_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    uint8_t who_am_i;
    if (read_i2c_register(WHO_AM_I, &who_am_i, 1) < 0 || who_am_i != 0x86) {
        printf("Sensor not found or incorrect WHO_AM_I value\n");
        close(i2c_fd);
        return 1;
    }

    if (write_i2c_register(PWR_MGMT_1, 0x00) < 0) {
        perror("Failed to wake up sensor");
        close(i2c_fd);
        return 1;
    }

    if (write_i2c_register(ACCEL_CONFIG, 0x00) < 0 || write_i2c_register(GYRO_CONFIG, 0x00) < 0) {
        perror("Failed to set sensor configuration");
        close(i2c_fd);
        return 1;
    }

    uint8_t accel_data[6];
    uint8_t gyro_data[6];

    while (1) {
        if (read_i2c_register(ACCEL_DATA_XOUT_H, accel_data, 6) < 0 || read_i2c_register(GYRO_DATA_XOUT_H, gyro_data, 6) < 0) {
            perror("Failed to read sensor data");
            break;
        }

        int16_t accel_x = (int16_t)((accel_data[0] << 8) | accel_data[1]);
        int16_t accel_y = (int16_t)((accel_data[2] << 8) | accel_data[3]);
        int16_t accel_z = (int16_t)((accel_data[4] << 8) | accel_data[5]);

        int16_t gyro_x = (int16_t)((gyro_data[0] << 8) | gyro_data[1]);
        int16_t gyro_y = (int16_t)((gyro_data[2] << 8) | gyro_data[3]);
        int16_t gyro_z = (int16_t)((gyro_data[4] << 8) | gyro_data[5]);

        printf("Accel: (%d, %d, %d) Gyro: (%d, %d, %d)\n", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        usleep(50000); // 50 ms delay
    }

    close(i2c_fd);
    return 0;
}

