code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define WHO_AM_I 0x75
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_DATA_START 0x3B
#define GYRO_DATA_START 0x43
#define ACCEL_DATA_LEN 6
#define GYRO_DATA_LEN 6
#define LOG_FILE "imu_log.csv"
#define INTERVAL 100 // 100 ms

FILE *log_file;

void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (pi >= 0) {
        gpioTerminate();
    }
    exit(0);
}

int main() {
    int pi = -1;
    int i2c_handle = -1;
    uint8_t who_am_i_value = 0;
    uint8_t accel_config = 0x00;
    uint8_t gyro_config = 0x00;
    uint8_t accel_data[ACCEL_DATA_LEN];
    uint8_t gyro_data[GYRO_DATA_LEN];
    struct timespec ts;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    pi = pigpioOpen(NULL, 0, 0);
    if (pi < 0) {
        fprintf(stderr, "Failed to open pigpio\n");
        return 1;
    }

    i2c_handle = i2cOpen(pi, I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Wake up the device
    if (i2cWriteReg(i2c_handle, 0x6B, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up the device\n");
        return 1;
    }

    // Set accelerometer and gyroscope configurations
    if (i2cWriteReg(i2c_handle, ACCEL_CONFIG, accel_config) < 0 ||
        i2cWriteReg(i2c_handle, GYRO_CONFIG, gyro_config) < 0) {
        fprintf(stderr, "Failed to set accelerometer or gyroscope configuration\n");
        return 1;
    }

    // Verify the sensor is present
    if (i2cReadI2CBlockData(i2c_handle, WHO_AM_I, 1, &who_am_i_value) < 0 ||
        who_am_i_value != 0x12) {
        fprintf(stderr, "Failed to verify sensor presence\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");

    signal(SIGINT, handle_sigint);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);

        if (i2cReadI2CBlockData(i2c_handle, ACCEL_DATA_START, ACCEL_DATA_LEN, accel_data) < 0 ||
            i2cReadI2CBlockData(i2c_handle, GYRO_DATA_START, GYRO_DATA_LEN, gyro_data) < 0) {
            fprintf(stderr, "Failed to read accelerometer or gyroscope data\n");
            continue;
        }

        fprintf(log_file, "%ld,%d,%d,%d,%d,%d,%d\n", ts.tv_sec, accel_data[0], accel_data[1], accel_data[2], gyro_data[0], gyro_data[1], gyro_data[2]);

        usleep(INTERVAL * 1000); // Sleep for 100 ms
    }

    if (log_file) {
        fclose(log_file);
    }

    if (pi >= 0) {
        gpioTerminate();
    }

    return 0;
}

