    close(i2c_fd);
    exit(signum);
}

int read_i2c_register(uint8_t reg) {
    uint8_t data;
    int ret = read(i2c_fd, &data, 1);
    if (ret != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return data;
}

int write_i2c_register(uint8_t reg, uint8_t value) {
    int ret = write(i2c_fd, &value, 1);
    if (ret != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpiod_chip *chip;
    gpiod_line_consumer *consumer;
    gpiod_line_request_flags flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Error opening GPIO chip");
        return 1;
    }

    if (gpiod_line_request_by_name(chip, "gpio%d", LED_GPIO, "led", &consumer, &flags) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    led_line = gpiod_line_get(consumer);
    if (!led_line) {
        perror("Error getting GPIO line");
        gpiod_line_consumer_free(consumer);
        gpiod_chip_close(chip);
        return 1;
    }

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        gpiod_line_free(led_line);
        gpiod_line_consumer_free(consumer);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C device address");
        close(i2c_fd);
        gpiod_line_free(led_line);
        gpiod_line_consumer_free(consumer);
        gpiod_chip_close(chip);
        return 1;
    }

    uint8_t who_am_i = read_i2c_register(WHO_AM_I);
    if (who_am_i != 0x1A) {
        fprintf(stderr, "Invalid sensor detected, WHO_AM_I = 0x%02X\n", who_am_i);
        close(i2c_fd);
        gpiod_line_free(led_line);
        gpiod_line_consumer_free(consumer);
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        close(i2c_fd);
        gpiod_line_free(led_line);
        gpiod_line_consumer_free(consumer);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        uint16_t x = read_i2c_register(ACCEL_X) << 8 | read_i2c_register(ACCEL_X + 1);
        uint16_t y = read_i2c_register(ACCEL_Y) << 8 | read_i2c_register(ACCEL_Y + 1);
        uint16_t z = read_i2c_register(ACCEL_Z) << 8 | read_i2c_register(ACCEL_Z + 1);

        double magnitude = sqrt(x * x + y * y + z * z);

        if (magnitude > THRESHOLD) {
            gpiod_line_set_value(led_line, LED_HIGH);
            fprintf(log_file, "%ld: Impact detected (magnitude = %.2f g)\n", time(NULL), magnitude / 1024.0);
            fflush(log_file);
            usleep(500000); // 500 ms
            gpiod_line_set_value(led_line, LED_LOW);
        }

        usleep(100000); // 100 ms
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_line_free(led_line);
    gpiod_line_consumer_free(consumer);
    gpiod_chip_close(chip);

    return 0;
