#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define MAG_ADDR 0x35
#define MAG_REG_X 0x10
#define MAG_REG_Y 0x11
#define MAG_REG_Z 0x12
#define LOG_FILE "magnetic_field_log.csv"

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_fd >= 0) {
        fclose(log_file);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    char buffer[3 * 2]; // 3 registers, 2 bytes each
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[20];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, MAG_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Write CSV header if file does not exist
    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    while (1) {
        // Read X, Y, Z registers
        if (read(i2c_fd, buffer, 6) != 6) {
            perror("Failed to read from I2C device");
            continue;
        }

        // Convert timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Write data to log file
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, (buffer[1] << 8) | buffer[0], (buffer[3] << 8) | buffer[2], (buffer[5] << 8) | buffer[4]);

        // Sleep for 1 second
        sleep(1);
    }

    // Close resources
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

