code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <gpiod.h>

#define I2C_ADDR 0x53
#define I2C_DEV "/dev/i2c-1"
#define GPIO_LINE 17
#define EVENT_FILE "/sys/class/gpio/gpio17/value"
#define FREEFALL_LOG "freefall_log.csv"

#define THRESH_FF 0x0A
#define TIME_FF 0x20
#define INT_ENABLE 0x2E
#define INT_MAP 0x2F
#define POWER_CTL 0x2D
#define INT_SOURCE 0x30
#define DATAX0 0x32

#define FREEFALL_THRESHOLD 300
#define FREEFALL_TIME 100

int i2c_fd;
struct gpiod_line *gpiod_line;
FILE *log_file;

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void init_i2c() {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        handle_error("Failed to open I2C device");
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        handle_error("Failed to set I2C slave address");
    }

    uint8_t device_id;
    if (read_i2c_reg(0x00, &device_id, 1) < 0 || device_id != 0xE5) {
        handle_error("Failed to read device ID or invalid device ID");
    }
}

void init_gpiod() {
    gpiod_line = gpiod_line_request(GPIO_LINE, "Freefall Interrupt", 0);
    if (!gpiod_line) {
        handle_error("Failed to request GPIO line");
    }

    if (gpiod_line_direction_set(gpiod_line, GPIOD_LINE_DIRECTION_IN) < 0) {
        handle_error("Failed to set GPIO direction");
    }

    if (gpiod_line_edge_set(gpiod_line, GPIOD_LINE_BOTH_EDGES) < 0) {
        handle_error("Failed to set GPIO edge");
    }

    if (gpiod_line_event_fd_set(gpiod_line, EVENT_FILE) < 0) {
        handle_error("Failed to set GPIO event file descriptor");
    }
}

void init_log_file() {
    log_file = fopen(FREEFALL_LOG, "a");
    if (!log_file) {
        handle_error("Failed to open log file");
    }

    if (fseek(log_file, 0, SEEK_END) < 0) {
        handle_error("Failed to seek to end of log file");
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
}

int read_i2c_reg(uint8_t reg, uint8_t *data, uint16_t len) {
    int bytes_read = write(i2c_fd, &reg, 1);
    if (bytes_read < 0) {
        handle_error("Failed to write register address");
    }

    bytes_read = read(i2c_fd, data, len);
    if (bytes_read < 0) {
        handle_error("Failed to read data");
    }

    return bytes_read;
}

void configure_sensor() {
    uint8_t data[6];

    // Put sensor in standby
    write_i2c_reg(POWER_CTL, 0x00);

    // Set freefall threshold and time
    write_i2c_reg(THRESH_FF, FREEFALL_THRESHOLD);
    write_i2c_reg(TIME_FF, FREEFALL_TIME);

    // Enable freefall interrupt
    uint8_t int_enable = 0x00;
    read_i2c_reg(INT_ENABLE, &int_enable, 1);
    int_enable |= (1 << 2);
    write_i2c_reg(INT_ENABLE, int_enable);

    // Map freefall interrupt to INT1
    write_i2c_reg(INT_MAP, 0x00);

    // Enter measurement mode
    write_i2c_reg(POWER_CTL, 0x08);
}

void write_i2c_reg(uint8_t reg, uint8_t value) {
    uint8_t data = value;
    int bytes_written = write(i2c_fd, &reg, 1);
    if (bytes_written < 0) {
        handle_error("Failed to write register address");
    }

    bytes_written = write(i2c_fd, &data, 1);
    if (bytes_written < 0) {
        handle_error("Failed to write data");
    }
}

void handle_interrupt() {
    uint8_t int_source;
    if (read_i2c_reg(INT_SOURCE, &int_source, 1) < 0) {
        handle_error("Failed to read INT_SOURCE");
    }

    if (int_source & (1 << 2)) {
        uint8_t data[6];
        if (read_i2c_reg(DATAX0, data, 6) < 0) {
            handle_error("Failed to read acceleration data");
        }

        struct tm *time_info;
        time_t rawtime;
        time(&rawtime);
        time_info = localtime(&rawtime);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d.%03d,%d,%d,%d\n",
                time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
                time_info->tm_hour, time_info->tm_min, time_info->tm_sec,
                time_info->tm_usec / 1000, data[0], data[1], data[2]);

        fflush(log_file);
    }
}

void cleanup() {
    if (gpiod_line) {
        gpiod_line_release(gpiod_line);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    init_i2c();
    init_gpiod();
    init_log_file();

    configure_sensor();

    int event_fd = gpiod_line_event_fd_get(gpiod_line);
    if (event_fd < 0) {
        handle_error("Failed to get GPIO event file descriptor");
    }

    while (1) {
        int bytes_read = read(event_fd, NULL, 0);
        if (bytes_read < 0) {
            handle_error("Failed to read from GPIO event file descriptor");
        }

        handle_interrupt();
    }

    cleanup();
    return 0;
}

