    read_i2c_reg(INT_ENABLE, &int_enable, 1);
    int_enable |= (1 << 2);
    write_i2c_reg(INT_ENABLE, int_enable);

    // Map freefall interrupt to INT1
    write_i2c_reg(INT_MAP, 0x00);

    // Enter measurement mode
    write_i2c_reg(POWER_CTL, 0x08);
}

void write_i2c_reg(uint8_t reg, uint8_t value) {
    uint8_t data = value;
    int bytes_written = write(i2c_fd, &reg, 1);
    if (bytes_written < 0) {
        handle_error("Failed to write register address");
    }

    bytes_written = write(i2c_fd, &data, 1);
    if (bytes_written < 0) {
        handle_error("Failed to write data");
    }
}

void handle_interrupt() {
    uint8_t int_source;
    if (read_i2c_reg(INT_SOURCE, &int_source, 1) < 0) {
        handle_error("Failed to read INT_SOURCE");
    }

    if (int_source & (1 << 2)) {
        uint8_t data[6];
        if (read_i2c_reg(DATAX0, data, 6) < 0) {
            handle_error("Failed to read acceleration data");
        }

        struct tm *time_info;
        time_t rawtime;
        time(&rawtime);
        time_info = localtime(&rawtime);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d.%03d,%d,%d,%d\n",
                time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
                time_info->tm_hour, time_info->tm_min, time_info->tm_sec,
                time_info->tm_usec / 1000, data[0], data[1], data[2]);

        fflush(log_file);
    }
}

void cleanup() {
    if (gpiod_line) {
        gpiod_line_release(gpiod_line);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    init_i2c();
    init_gpiod();
    init_log_file();

    configure_sensor();

    int event_fd = gpiod_line_event_fd_get(gpiod_line);
    if (event_fd < 0) {
        handle_error("Failed to get GPIO event file descriptor");
    }

    while (1) {
        int bytes_read = read(event_fd, NULL, 0);
        if (bytes_read < 0) {
            handle_error("Failed to read from GPIO event file descriptor");
        }

        handle_interrupt();
    }

    cleanup();
    return 0;
}
