#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define LSM6DSR_ADDRESS 0x6A
#define WHO_AM_I 0x0F
#define CTRL_REG1_XM 0x20
#define CTRL_REG4_XL 0x1E
#define CTRL_REG5_XL 0x1F
#define CTRL_REG6_XL 0x21
#define CTRL_REG1_YG 0x22
#define CTRL_REG4_YG 0x1E
#define CTRL_REG5_YG 0x1F
#define CTRL_REG6_YG 0x21
#define OUT_X_L_XL 0x28
#define OUT_Y_L_XL 0x2A
#define OUT_Z_L_XL 0x2C
#define OUT_X_L_YG 0x28
#define OUT_Y_L_YG 0x2A
#define OUT_Z_L_YG 0x2C

#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define WINDOW_SIZE 1000 // 1 second window at 104 Hz

int g_piHandle = 0;
int g_i2cHandle = 0;

void handle_sigint(int signum) {
    if (g_i2cHandle != 0) {
        i2cUnexport(g_i2cHandle);
    }
    if (g_piHandle != 0) {
        gpioTerminate();
    }
    exit(0);
}

void configure_sensor() {
    uint8_t who_am_i_data[1];
    if (i2cReadDevice(g_i2cHandle, WHO_AM_I, who_am_i_data, 1) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        exit(1);
    }
    if (who_am_i_data[0] != 0x6A) {
        fprintf(stderr, "LSM6DSR not found at expected address.\n");
        exit(1);
    }

    uint8_t config_data[4] = {0x00, 0x00, 0x00, 0x00};

    // Configure accelerometer
    config_data[0] = 0x00; // CTRL_REG1_XM
    config_data[1] = 0x00; // CTRL_REG4_XL
    config_data[2] = 0x00; // CTRL_REG5_XL
    config_data[3] = 0x00; // CTRL_REG6_XL
    i2cWriteDevice(g_i2cHandle, CTRL_REG1_XM, config_data, 4);

    // Configure gyroscope
    config_data[0] = 0x00; // CTRL_REG1_YG
    config_data[1] = 0x00; // CTRL_REG4_YG
    config_data[2] = 0x00; // CTRL_REG5_YG
    config_data[3] = 0x00; // CTRL_REG6_YG
    i2cWriteDevice(g_i2cHandle, CTRL_REG1_YG, config_data, 4);
}

void read_sensor_data(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z) {
    uint8_t data[6];
    if (i2cReadDevice(g_i2cHandle, OUT_X_L_XL, data, 6) != 0) {
        fprintf(stderr, "Failed to read accelerometer data.\n");
        exit(1);
    }

    *accel_x = ((data[1] << 8) | data[0]) / 16384.0;
    *accel_y = ((data[3] << 8) | data[2]) / 16384.0;
    *accel_z = ((data[5] << 8) | data[4]) / 16384.0;

    if (i2cReadDevice(g_i2cHandle, OUT_X_L_YG, data, 6) != 0) {
        fprintf(stderr, "Failed to read gyroscope data.\n");
        exit(1);
    }

    *gyro_x = ((data[1] << 8) | data[0]) / 131.0;
    *gyro_y = ((data[3] << 8) | data[2]) / 131.0;
    *gyro_z = ((data[5] << 8) | data[4]) / 131.0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (i2cOpen(1, LSM6DSR_ADDRESS, &g_i2cHandle) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        return 1;
    }

    configure_sensor();

    FILE *log_file = fopen("motion_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    struct timespec start_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float prev_accel_mag = 0.0;
    int state = 0; // IDLE

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        read_sensor_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z);

        float current_accel_mag = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);

        if (state == 0 && current_accel_mag < FREEFALL_THRESHOLD) {
            state = 1; // FREEFALL
        } else if (state == 1 && current_accel_mag > IMPACT_THRESHOLD) {
            state = 2; // IMPACT
        }

        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        fprintf(log_file, "%f,%f,%f,%f,%f,%f,%d\n", elapsed_time, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, state);

        usleep(9615); // 104 Hz ODR = 9615 us
    }

    fclose(log_file);
    i2cUnexport(g_i2cHandle);
    gpioTerminate();

    return 0;
}

