#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define X_GYRO_OUT 0x14
#define WHO_AM_I 0x00
#define EXPECTED_WHO_AM_I 0x3F5A
#define SCALE_FACTOR 0.0305
#define LOG_FILE "gyro_log.csv"

FILE *log_file;

void handle_sigint(int signum) {
    if (spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE) >= 0) {
        spi_close(SPI_CHANNEL);
    }
    if (pi_stop() == 0) {
        printf("Terminated pigpio successfully.\n");
    } else {
        printf("Failed to terminate pigpio.\n");
    }
    if (fclose(log_file) != 0) {
        printf("Failed to close log file.\n");
    } else {
        printf("Closed log file successfully.\n");
    }
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio.\n");
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        printf("Failed to open log file.\n");
        return 1;
    }

    fprintf(log_file, "Timestamp,Angular Rate (deg/sec)\n");

    if (spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        printf("Failed to open SPI channel.\n");
        return 1;
    }

    uint8_t who_am_i_reg[2] = {WHO_AM_I, 0};
    uint8_t who_am_i_response[2];

    if (spi_read(SPI_CHANNEL, who_am_i_reg, who_am_i_response, 2) < 0) {
        printf("Failed to read WHO_AM_I register.\n");
        spi_close(SPI_CHANNEL);
        return 1;
    }

    uint16_t who_am_i_value = (who_am_i_response[0] << 8) | who_am_i_response[1];

    if (who_am_i_value != EXPECTED_WHO_AM_I) {
        printf("Unexpected WHO_AM_I value: 0x%04X (expected 0x%04X).\n", who_am_i_value, EXPECTED_WHO_AM_I);
        spi_close(SPI_CHANNEL);
        return 1;
    }

    printf("Connected to ADIS16266 gyroscope.\n");

    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        uint8_t x_gyro_out_reg[2] = {X_GYRO_OUT | 0x80, 0};
        uint8_t x_gyro_out_response[2];

        if (spi_read(SPI_CHANNEL, x_gyro_out_reg, x_gyro_out_response, 2) < 0) {
            printf("Failed to read X_GYRO_OUT register.\n");
            spi_close(SPI_CHANNEL);
            return 1;
        }

        uint16_t x_gyro_out_value = (x_gyro_out_response[0] << 8) | x_gyro_out_response[1];
        double angular_rate = x_gyro_out_value * SCALE_FACTOR;

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.6f\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, angular_rate);

        fflush(log_file);

        usleep(10000); // 10 ms delay
    }

    spi_close(SPI_CHANNEL);
    fclose(log_file);
    pi_stop();

    return 0;
}

