#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define GYRO_ADDR 0x69
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    FILE *log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,X,Y,Z\n");

    int i2c_handle = i2cOpen(1, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    int retries = 3;
    int who_am_i_value;
    while (retries > 0) {
        if (i2cWriteReg(i2c_handle, CTRL_REG1, 0x0F) < 0) {
            fprintf(stderr, "Failed to write CTRL_REG1\n");
            i2cClose(i2c_handle);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        if (i2cWriteReg(i2c_handle, CTRL_REG4, 0x00) < 0) {
            fprintf(stderr, "Failed to write CTRL_REG4\n");
            i2cClose(i2c_handle);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        if (i2cReadReg(i2c_handle, WHO_AM_I, &who_am_i_value, 1) < 0) {
            fprintf(stderr, "Failed to read WHO_AM_I\n");
            i2cClose(i2c_handle);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        if (who_am_i_value == 0xD3) {
            break;
        }

