#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int main() {
    FILE *log_file;
    int sensor_value;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    // Set GPIO17 as input with pull-up resistor
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0 ||
        gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to configure GPIO17.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    while (!stop_flag) {
        // Read sensor value
        sensor_value = gpioRead(FLAME_SENSOR_GPIO);
        if (sensor_value == PI_BAD_GPIO) {
            fprintf(log_file, "%s - Error reading sensor.\n", ctime(&time(NULL)));
            fflush(log_file);
            continue;
        }

        // Log sensor value
        fprintf(log_file, "%s - Flame detected: %s\n", ctime(&time(NULL)), sensor_value ? "NO" : "YES");
        fflush(log_file);

        // Check for flame detection
        if (sensor_value == 0) {
            printf("FLAME DETECTED!\n");
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

