#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <signal.h>

#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x53
#define X_LSB 0x28
#define X_MSB 0x29
#define Y_LSB 0x2A
#define Y_MSB 0x2B
#define Z_LSB 0x2C
#define Z_MSB 0x2D
#define SAMPLE_INTERVAL 100 // in milliseconds

int i2c_fd;
FILE *csv_file;

void handle_sigint(int signum) {
    if (csv_file) {
        fclose(csv_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int read_sensor_data() {
    char buffer[6];
    int bytes_read;

    bytes_read = read(i2c_fd, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read sensor data: %d bytes read instead of 6\n", bytes_read);
        return -1;
    }

    if (buffer[0] == 0xFF || buffer[1] == 0xFF || buffer[2] == 0xFF || buffer[3] == 0xFF || buffer[4] == 0xFF || buffer[5] == 0xFF) {
        fprintf(stderr, "Sensor absent detected (0xFF read)\n");
        return -1;
    }

    int16_t x = (buffer[1] << 8) | buffer[0];
    int16_t y = (buffer[3] << 8) | buffer[2];
    int16_t z = (buffer[5] << 8) | buffer[4];

    fprintf(csv_file, "%s,%d,%d,%d\n", asctime(gmtime(&time(NULL))), x, y, z);

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    csv_file = fopen("vibration_log.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    fprintf(csv_file, "Timestamp,X,Y,Z\n");

    while (1) {
        if (read_sensor_data() == 0) {
            usleep(SAMPLE_INTERVAL * 1000); // Sleep for 100 ms
        }
    }

    fclose(csv_file);
    close(i2c_fd);

    return 0;
}

