#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_PIN_1 17
#define GPIO_PIN_2 27
#define LOG_FILE "conveyor_log.txt"
#define INTERVAL 50 // milliseconds

static gpiod_chip *chip;
static gpiod_line *line1, *line2;
static FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (line1) {
        gpiod_line_request_release(line1);
    }
    if (line2) {
        gpiod_line_request_release(line2);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct timespec ts;
    struct tm *tm;
    char timestamp[32];
    int state1, state2;

    // Open the GPIO chip
    if (!(chip = gpiod_chip_open("/dev/gpiochip0"))) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO lines
    if (!(line1 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_PIN_1, "Sensor1", 0, GPIOD_LINE_DIRECTION_IN))) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_PIN_1);
        goto error_line1;
    }

    if (!(line2 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_PIN_2, "Sensor2", 0, GPIOD_LINE_DIRECTION_IN))) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_PIN_2);
        goto error_line2;
    }

    // Set internal pull-up resistors
    if (gpiod_line_set_bias(line1, GPIOD_LINE_ACTIVE_HIGH)) {
        fprintf(stderr, "Failed to set bias for line %d\n", GPIO_PIN_1);
        goto error_bias1;
    }

    if (gpiod_line_set_bias(line2, GPIOD_LINE_ACTIVE_HIGH)) {
        fprintf(stderr, "Failed to set bias for line %d\n", GPIO_PIN_2);
        goto error_bias2;
    }

    // Open log file
    if (!(log_file = fopen(LOG_FILE, "w"))) {
        perror("Failed to open log file");
        goto error_log;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Read sensor states
        if (gpiod_line_get_value(line1, &state1) || gpiod_line_get_value(line2, &state2)) {
            fprintf(stderr, "Failed to read GPIO line\n");
            continue;
        }

        // Log sensor states
        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s.%03ld: Sensor1=%d, Sensor2=%d\n", timestamp, ts.tv_nsec / 1000000, state1, state2);

        // Check if both sensors are triggered
        if (state1 && state2) {
            printf("Both sensors triggered, halting conveyor...\n");
        }

        // Sleep for 50 ms
        usleep(INTERVAL * 1000);
    }

    // Cleanup on exit
    fclose(log_file);
    gpiod_line_request_release(line1);
    gpiod_line_request_release(line2);
    gpiod_chip_put(chip);

    return 0;

error_bias2:
    gpiod_line_request_release(line1);
error_bias1:
    gpiod_line_request_release(line2);
error_line2:
    gpiod_line_request_release(line1);
error_line1:
    gpiod_chip_put(chip);
error_log:
    return 1;
}

