        close(i2c_fd);
        return 1;
    }

    uint8_t who_am_i;
    if (read_i2c_reg(WHO_AM_I, &who_am_i, 1) < 0) {
        perror("Failed to read WHO_AM_I register");
        close(i2c_fd);
        return 1;
    }

