    ctrl_reg1 |= DATA_RATE_100HZ << 3; // Set data rate to 100 Hz
    if (write_i2c_reg(CTRL_REG1, &ctrl_reg1, 1) < 0) {
        perror("Failed to write CTRL_REG1 register");
        close(i2c_fd);
        return 1;
    }

