#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_ADDR 0x1E
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x24
#define CTRL_REG3 0x25
#define MAG_DATA 0x28
#define MAG_DATA_LEN 6
#define SENSITIVITY 0.146 // mG/LSB
#define THRESHOLD 800 // mG

int i2c_fd;
int init_attempts = 0;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(signum);
}

int i2c_write(uint8_t reg, uint8_t *data, size_t len) {
    int ret;
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    ret = write(i2c_fd, buf, len + 1);
    if (ret != len + 1) {
        perror("i2c_write");
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t reg, uint8_t *data, size_t len) {
    int ret;
    uint8_t buf[len + 1];
    buf[0] = reg;
    ret = write(i2c_fd, buf, len + 1);
    if (ret != len + 1) {
        perror("i2c_write");
        return -1;
    }
    ret = read(i2c_fd, data, len);
    if (ret != len) {
        perror("i2c_read");
        return -1;
    }
    return 0;
}

int init_sensor() {
    uint8_t who_am_i;
    uint8_t config_data[3] = {0x70, 0x0C, 0x00};

    if (i2c_write(CTRL_REG1, config_data, 3) < 0) {
        return -1;
    }

    if (i2c_read(WHO_AM_I, &who_am_i, 1) < 0) {
        return -1;
    }

    if (who_am_i != 0x3D) {
        fprintf(stderr, "LIS3MDL not found at 0x%02X\n", I2C_ADDR);
        return -1;
    }

    return 0;
}

int main() {
    char filename[] = "magnetic_log.txt";
    FILE *log_file = fopen(filename, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (init_attempts < 3) {
        if (init_sensor() == 0) {
            break;
        }
        init_attempts++;
        sleep(1);
    }

    if (init_attempts == 3) {
        fprintf(stderr, "Failed to initialize LIS3MDL after 3 attempts\n");
        return 1;
    }

    while (1) {
        uint8_t mag_data[MAG_DATA_LEN];
        if (i2c_read(MAG_DATA, mag_data, MAG_DATA_LEN) < 0) {
            continue;
        }

        int16_t x = (int16_t)((mag_data[0] << 8) | mag_data[1]);
        int16_t y = (int16_t)((mag_data[2] << 8) | mag_data[3]);
        int16_t z = (int16_t)((mag_data[4] << 8) | mag_data[5]);

        double mag_x = x * SENSITIVITY;
        double mag_y = y * SENSITIVITY;
        double mag_z = z * SENSITIVITY;

        double total_magnitude = sqrt(mag_x * mag_x + mag_y * mag_y + mag_z * mag_z);

        if (total_magnitude > THRESHOLD) {
            fprintf(stderr, "Threshold exceeded: %.2f mG\n", total_magnitude);
        }

        fprintf(log_file, "%.2f,%.2f,%.2f\n", mag_x, mag_y, mag_z);
        fflush(log_file);

        usleep(100000); // 100 ms delay for 10 Hz
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

