#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADXL354B_ADDR 0x53
#define ADXL354B_PARTID 0x01
#define ADXL354B_RESET 0x1F
#define ADXL354B_POWER_CTL 0x2D
#define ADXL354B_STATUS 0x04
#define ADXL354B_XDATA 0x08
#define ADXL354B_YDATA 0x0B
#define ADXL354B_ZDATA 0x0E
#define ADXL354B_PARTID_EXPECTED 0x1D
#define LOG_INTERVAL 100 // ms
#define SPI_READ_MASK 0x80
#define SPI_MULTI_BYTE_MASK 0x40

FILE *log_file;

void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (spiHandle != -1) {
        spiStop(spiHandle);
    }
    if (piHandle != -1) {
        gpioTerminate();
    }
    exit(0);
}

int read_sensor_data(int *x, int *y, int *z) {
    uint8_t buffer[6];
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        if (spiRead(spiHandle, ADXL354B_ADDR | SPI_READ_MASK | SPI_MULTI_BYTE_MASK, 6, buffer) == 6) {
            *x = ((buffer[0] << 8) | buffer[1]) & 0x000FFFFF;
            *y = ((buffer[2] << 8) | buffer[3]) & 0x000FFFFF;
            *z = ((buffer[4] << 8) | buffer[5]) & 0x000FFFFF;
            result = 0;
            break;
        }
        retries--;
    }

    return result;
}

int main() {
    int x, y, z;
    int partid;
    int spiHandle = -1;
    int piHandle = -1;

    if ((piHandle = pigpio_start()) < 0) {
        fprintf(stderr, "pigpio_start failed\n");
        return 1;
    }

    if ((spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "spiOpen failed\n");
        goto cleanup;
    }

    // Device reset sequence
    spiWrite(spiHandle, ADXL354B_ADDR | 0x52, 1);
    usleep(1000);
    spiWrite(spiHandle, ADXL354B_ADDR | 0x2D | 0x01, 1);
    usleep(1000);

    // Check sensor presence
    spiWrite(spiHandle, ADXL354B_ADDR | SPI_READ_MASK, 1);
    spiRead(spiHandle, ADXL354B_ADDR, 1, &partid);
    if (partid != ADXL354B_PARTID_EXPECTED) {
        fprintf(stderr, "Sensor not detected or incorrect part ID\n");
        goto cleanup;
    }

    // Open log file
    if ((log_file = fopen("vibration_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        if (read_sensor_data(&x, &y, &z) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld: X=%d, Y=%d, Z=%d\n", ts.tv_sec, ts.tv_nsec / 1000, x, y, z);
        }
        usleep(LOG_INTERVAL * 1000);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (spiHandle != -1) {
        spiStop(spiHandle);
    }
    if (piHandle != -1) {
        gpioTerminate();
    }
    return 0;
}

