#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define GYRO_ADDR_X 0x04
#define GYRO_ADDR_Y 0x06
#define GYRO_ADDR_Z 0x08
#define ACCL_ADDR_X 0x0A
#define ACCL_ADDR_Y 0x0C
#define ACCL_ADDR_Z 0x0E
#define GYRO_SCALE 0.05
#define ACCL_SCALE 0.0025
#define LOG_FILE "imu_log.csv"

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int spi_read(int spi_handle, uint8_t address, uint8_t *data) {
    uint8_t buffer[3];
    buffer[0] = (address << 1) | 1; // Set MSB and send dummy byte
    buffer[1] = 0;

    int result = spiXfer(spi_handle, buffer, 2, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from SPI: %d\n", result);
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    signal(SIGINT, handle_sigint);

    while (!stop) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        double timestamp = ts.tv_sec + ts.tv_nsec * 1e-9;

        uint8_t gyro_x[2], gyro_y[2], gyro_z[2];
        uint8_t acc_x[2], acc_y[2], acc_z[2];

        if (spi_read(spi_handle, GYRO_ADDR_X, gyro_x) == 0 &&
            spi_read(spi_handle, GYRO_ADDR_Y, gyro_y) == 0 &&
            spi_read(spi_handle, GYRO_ADDR_Z, gyro_z) == 0 &&
            spi_read(spi_handle, ACCL_ADDR_X, acc_x) == 0 &&
            spi_read(spi_handle, ACCL_ADDR_Y, acc_y) == 0 &&
            spi_read(spi_handle, ACCL_ADDR_Z, acc_z) == 0) {

            double x_gyro = (gyro_x[0] << 8 | gyro_x[1]) * GYRO_SCALE;
            double y_gyro = (gyro_y[0] << 8 | gyro_y[1]) * GYRO_SCALE;
            double z_gyro = (gyro_z[0] << 8 | gyro_z[1]) * GYRO_SCALE;

            double x_accel = (acc_x[0] << 8 | acc_x[1]) * ACCL_SCALE;
            double y_accel = (acc_y[0] << 8 | acc_y[1]) * ACCL_SCALE;
            double z_accel = (acc_z[0] << 8 | acc_z[1]) * ACCL_SCALE;

            fprintf(log_file, "%f,%f,%f,%f,%f,%f,%f\n", timestamp, x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel);
        }

        usleep(10000); // 10 ms delay
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

