This C program uses the libgpiod library to read an E18-D80NK IR obstacle sensor connected to GPIO17 on a Raspberry Pi 5. It opens the gpiochip device for GPIO17, requests the line for input direction, and polls the sensor every 1 second. When an obstacle is detected (line reads LOW), it triggers a simulated "self-parking" sequence logged to the console with timestamps. It checks all libgpiod calls, handles the case where the gpiochip or line is unavailable, and exits gracefully. It also handles SIGINT (Ctrl+C) for clean shutdown, releasing the GPIO line and closing the chip on all exit paths.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_CHIP_NAME "gpio"
#define GPIO_LINE_1 17
#define GPIO_LINE_2 27
#define POLL_INTERVAL 100 // ms

static gpiod_chip *chip;
static gpiod_line *lines[2];
static gpiod_line_req *line_reqs[2];

void cleanup(void) {
    for (int i = 0; i < 2; i++) {
        gpiod_line_req_release(line_reqs[i]);
        gpiod_line_free(lines[i]);
    }
    gpiod_chip_put(chip);
    exit(0);
}

void handle_sigint(int signum) {
    cleanup();
}

int main(int argc, char *argv[]) {
    struct timespec ts;
    struct timespec interval = { .tv_sec = 0, .tv_nsec = POLL_INTERVAL * 1000000 };

    signal(SIGINT, handle_sigint);

    if (gpiod_chip_open(GPIO_CHIP_NAME, &chip) < 0) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 2; i++) {
        if (gpiod_line_request(chip, i + GPIO_LINE_1, "sensor", "input", &line_reqs[i]) < 0) {
            perror("gpiod_line_request");
            cleanup();
        }

        if (gpiod_line_get_line(line_reqs[i], &lines[i]) < 0) {
            perror("gpiod_line_get_line");
            cleanup();
        }
    }

    while (1) {
        gpiod_line_req_get_values(line_reqs[0], line_reqs[1], &ts);

        printf("Timestamp: %ld.%09ld - Sensor 1: %d, Sensor 2: %d\n",
               ts.tv_sec, ts.tv_nsec / 1000000,
               gpiod_line_req_get_value(line_reqs[0]),
               gpiod_line_req_get_value(line_reqs[1]));

        nanosleep(&interval, NULL);
    }

    cleanup();

    return 0;
}

