#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>

#define CS_PIN 8
#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SCALE_FACTOR 0.02

static gpiod_line *cs_line;
static struct spi_ioc_transfer spi_transfer[2];

void cleanup(void) {
    if (cs_line) {
        gpiod_line_free(cs_line);
    }
    close(open(SPI_DEV, O_RDWR));
    exit(EXIT_FAILURE);
}

void handle_sigint(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct spi_ioc_transfer *transfers = spi_transfer;
    int fd;
    int ret;

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open SPI device
    fd = open(SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode and speed
    ret = ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        cleanup();
    }

    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        cleanup();
    }

    // Initialize libgpiod for CS line
    cs_line = gpiod_line_request(CS_PIN, "CS_LINE", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!cs_line) {
        perror("Failed to request GPIO line");
        cleanup();
    }

    // Enable data ready mode by writing to MSC_CTRL register
    spi_transfer[0].tx_buf = (unsigned long)0x24;
    spi_transfer[0].len = 1;
    spi_transfer[0].delay_usecs = 0;
    spi_transfer[0].speed_hz = SPI_SPEED;
    spi_transfer[0].bits_per_word = 8;

    spi_transfer[1].tx_buf = (unsigned long)0x00;
    spi_transfer[1].len = 2;
    spi_transfer[1].delay_usecs = 0;
    spi_transfer[1].speed_hz = SPI_SPEED;
    spi_transfer[1].bits_per_word = 8;

    while (1) {
        // Select the CS line
        gpiod_line_set_value(cs_line, 0);

        // Write to MSC_CTRL register
        ret = ioctl(fd, SPI_IOC_MESSAGE(1), transfers);
        if (ret < 1) {
            perror("Failed to write to MSC_CTRL register");
            cleanup();
        }

        // Read X, Y, and Z angular rate output registers
        transfers[0].tx_buf = (unsigned long)0x04;
        transfers[1].tx_buf = (unsigned long)0x06;
        transfers[2].tx_buf = (unsigned long)0x08;

        ret = ioctl(fd, SPI_IOC_MESSAGE(3), transfers);
        if (ret < 3) {
            perror("Failed to read angular rate registers");
            cleanup();
        }

        // Convert raw 16-bit signed values to angular rates
        int16_t x_rate = (int16_t)((transfers[0].rx_buf << 8) | transfers[0].rx_buf[1]);
        int16_t y_rate = (int16_t)((transfers[1].rx_buf << 8) | transfers[1].rx_buf[1]);
        int16_t z_rate = (int16_t)((transfers[2].rx_buf << 8) | transfers[2].rx_buf[1]);

        printf("X: %f deg/sec, Y: %f deg/sec, Z: %f deg/sec\n", x_rate * SCALE_FACTOR, y_rate * SCALE_FACTOR, z_rate * SCALE_FACTOR);

        // De-select the CS line
        gpiod_line_set_value(cs_line, 1);

        // Sleep for 100 ms
        usleep(100000);
    }

    cleanup();
    return 0;
}

