        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    status = i2cWriteByteData(i2cHandle, CTRL2_G, 0x42);
    if (status < 0) {
        fprintf(stderr, "Failed to write CTRL2_G\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!stop) {
        uint8_t data[12];
        status = i2cReadI2CBlockData(i2cHandle, OUTX_L_G, 12, data);
        if (status < 0) {
            fprintf(stderr, "Failed to read data\n");
            i2cClose(i2cHandle);
            gpioTerminate();
            return 1;
        }

        float gyroX = (data[0] | (data[1] << 8)) * GYRO_SENSITIVITY;
        float gyroY = (data[2] | (data[3] << 8)) * GYRO_SENSITIVITY;
