        float accelY = (data[8] | (data[9] << 8)) * ACCEL_SENSITIVITY;
        float accelZ = (data[10] | (data[11] << 8)) * ACCEL_SENSITIVITY;

        printf("Gyro: %.2f %.2f %.2f, Accel: %.2f %.2f %.2f\n",
               gyroX, gyroY, gyroZ, accelX, accelY, accelZ);

        usleep(100000); // Sleep for 100 ms
    }

    // Clean shutdown
    i2cClose(i2cHandle);
    gpioTerminate();

    return 0;
}

