    int16_t mag_y = (data[8] << 8) | data[9];
    int16_t mag_z = (data[10] << 8) | data[11];

    printf("Accelerometer: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
    printf("Magnetometer: X=%d, Y=%d, Z=%d\n", mag_x, mag_y, mag_z);

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int handle = i2cOpen(FXOS8700_I2C_BUS, FXOS8700_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d for address 0x%X\n", FXOS8700_I2C_BUS, FXOS8700_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (i2cReadDevice(handle, FXOS8700_WHO_AM_I, &who_am_i, 1) != 1 || who_am_i != 0xC7) {
        fprintf(stderr, "FXOS8700 not found at address 0x%X\n", FXOS8700_I2C_ADDR);
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    // Configure CTRL_REG1
    uint8_t ctrl_reg1 = 0x00;
    i2cWriteDevice(handle, FXOS8700_CTRL_REG1, &ctrl_reg1, 1);

    // Configure CTRL_REG2
    uint8_t ctrl_reg2 = 0x00;
    i2cWriteDevice(handle, FXOS8700_CTRL_REG2, &ctrl_reg2, 1);

    // Configure M_CTRL_REG1
    uint8_t m_ctrl_reg1 = 0x00;
    i2cWriteDevice(handle, FXOS8700_M_CTRL_REG1, &m_ctrl_reg1, 1);

    // Configure M_CTRL_REG2
    uint8_t m_ctrl_reg2 = 0x00;
    i2cWriteDevice(handle, FXOS8700_M_CTRL_REG2, &m_ctrl_reg2, 1);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        if (read_sensor_data(handle) < 0) {
            stop_flag = 1;
        }
        gpioDelay(100000); // 100 ms delay
    }

    i2cClose(handle);
    gpioTerminate();

    return 0;
}

