#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <time.h>
#include <signal.h>

#define I2C_ADDR 0x53
#define I2C_DEV "/dev/i2c-1"
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"

int i2c_fd;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

int read_accelerometer_data(short *x, short *y, short *z) {
    char buffer[6];
    int bytes_read;

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C device address");
        return -1;
    }

    bytes_read = read(i2c_fd, buffer, 6);
    if (bytes_read != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }

    *x = (short)((buffer[0] << 8) | buffer[1]);
    *y = (short)((buffer[2] << 8) | buffer[3]);
    *z = (short)((buffer[4] << 8) | buffer[5]);

    return 0;
}

double calculate_tilt_angle(short x, short y, short z) {
    double tilt_x = atan2(x, sqrt(y * y + z * z)) * 180.0 / M_PI;
    double tilt_y = atan2(y, sqrt(x * x + z * z)) * 180.0 / M_PI;
    double tilt_z = atan2(z, sqrt(x * x + y * y)) * 180.0 / M_PI;

    return fmax(fmax(tilt_x, tilt_y), tilt_z);
}

int main() {
    struct sigaction sa;
    short x, y, z;
    double tilt_angle;
    time_t timestamp;
    FILE *log_file;

    signal(SIGINT, handle_sigint);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        if (read_accelerometer_data(&x, &y, &z) < 0) {
            continue;
        }

        tilt_angle = calculate_tilt_angle(x, y, z);

        if (tilt_angle > TILT_THRESHOLD) {
            timestamp = time(NULL);
            log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("Failed to open log file");
                continue;
            }

            fprintf(log_file, "%ld: Tilt angle %.2f degrees exceeded threshold\n", (long)timestamp, tilt_angle);
            fclose(log_file);
        }

        usleep(100000); // Sleep for 100 ms
    }

    close(i2c_fd);
    return 0;
}

