#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define MONITOR_INTERVAL 1000 // 1 ms
#define ALERT_WINDOW 5000 // 5 seconds
#define ALERT_PAUSE 1000 // 1 second

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold;
    if (sscanf(argv[1], "%d", &threshold) != 1 || threshold <= 0) {
        fprintf(stderr, "Invalid threshold. Please provide a positive integer.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_OFF);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        int high_count = 0;
        struct timespec start, end;
        clock_gettime(CLOCK_REALTIME, &start);

        for (int i = 0; i < ALERT_WINDOW / MONITOR_INTERVAL; i++) {
