#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_A 17
#define GPIO_B 27
#define CODE_MIN 100000
#define CODE_MAX 999999

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    exit_flag = 1;
}

void log_access(const char* code) {
    FILE* log_file = fopen("access_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open access log file");
        exit(1);
    }

    time_t rawtime;
    struct tm* timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S,", timeinfo);
    fprintf(log_file, "%s%s\n", buffer, code);

    fclose(log_file);
}

int main() {
    struct gpiod_chip* chip;
    struct gpiod_line* line_a, *line_b;
    int code;
    char input[7];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    srand(time(NULL));
    code = CODE_MIN + rand() % (CODE_MAX - CODE_MIN + 1);
    printf("Generated code: %d\n", code);

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    if (gpiod_line_request_by_name(chip, "gpio%d", GPIO_A, "Door A", 0, &line_a) < 0) {
        perror("Failed to request GPIO line for Door A");
        exit(1);
    }

    if (gpiod_line_request_by_name(chip, "gpio%d", GPIO_B, "Door B", 0, &line_b) < 0) {
        perror("Failed to request GPIO line for Door B");
        exit(1);
    }

    if (gpiod_line_direction_set(line_a, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        perror("Failed to set direction for Door A");
        exit(1);
    }

    if (gpiod_line_direction_set(line_b, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        perror("Failed to set direction for Door B");
        exit(1);
    }

    gpiod_line_value_set(line_a, 0);
    gpiod_line_value_set(line_b, 0);

    while (!exit_flag) {
        printf("Enter code: ");
        if (fgets(input, sizeof(input), stdin) != NULL) {
            if (sscanf(input, "%d", &code) == 1) {
                if (code == (CODE_MIN + rand() % (CODE_MAX - CODE_MIN + 1))) {
                    gpiod_line_value_set(line_a, 1);
                    sleep(5);
                    gpiod_line_value_set(line_a, 0);
                    log_access(input);
                    printf("Access granted\n");
                } else {
                    printf("Access denied\n");
                }
            } else {
                printf("Invalid input, please enter a 6-digit number.\n");
                while (getchar() != '\n'); // Clear the input buffer
            }
        }
    }

    gpiod_line_free(line_a);
    gpiod_line_free(line_b);
    gpiod_chip_put(chip);

    return 0;
}

