#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define ONE_TIME_HIGH_RES_MODE 0x21
#define MAX_CONVERSION_TIME 180
#define LUX_CALCULATION_FACTOR 1.2
#define LOG_FILE "light_log.txt"

int i2c_fd;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int read_lux() {
    unsigned char data[2];
    int ret;

    // Write the One-Time High-Resolution Mode command
    ret = write(i2c_fd, &ONE_TIME_HIGH_RES_MODE, 1);
    if (ret != 1) {
        perror("Failed to write to BH1750");
        return -1;
    }

    // Wait for the maximum conversion time
    usleep(MAX_CONVERSION_TIME * 1000);

    // Read 2 bytes of data
    ret = read(i2c_fd, data, 2);
    if (ret != 2) {
        perror("Failed to read from BH1750");
        return -1;
    }

    // Calculate the illuminance in lux
    int raw_value = (data[0] << 8) | data[1];
    int lux_value = (raw_value * 5) / 6;

    return lux_value;
}

int main() {
    struct sigaction sa;
    struct timespec sleep_duration = { .tv_sec = 0, .tv_nsec = 5000000000 }; // 5 seconds

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set up signal handling for SIGINT
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int lux_value = read_lux();
        if (lux_value >= 0) {
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            fprintf(log_file, "Timestamp: %04d-%02d-%02d %02d:%02d:%02d, Lux: %d\n",
                    now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                    now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, lux_value);
            fflush(log_file);
        }

        // Sleep for 5 seconds
        nanosleep(&sleep_duration, NULL);
    }

    // Close the log file and I2C bus
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

