#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x5A
#define PORT 12345
#define SECRET "MySecretKey"
#define LOG_FILE "frequency_log.txt"
#define PWM_GPIO 18
#define SAMPLE_INTERVAL 20 // ms
#define PLAYBACK_TIME 5000 // ms

int sockfd;
int i2c_fd;

void handle_sigint(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpioTerminate();
    close(i2c_fd);
    close(sockfd);
    exit(EXIT_SUCCESS);
}

void play_tone(int freq) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return;
    }
    gpioSetPWMfrequency(PWM_GPIO, freq);
    gpioPWM(PWM_GPIO, 50); // Duty cycle 50%
    usleep(PLAYBACK_TIME * 1000); // Sleep for 5 seconds
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();
}

int main() {
    struct sockaddr_in server_addr;
    struct sockaddr_in client_addr;
    socklen_t addr_len = sizeof(client_addr);
    char buffer[1024];
    char *secret_start = "MOTION_DETECTED:";
    char *secret = SECRET;
    int bytes_read;
    int freq;
    FILE *log_file;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        return EXIT_FAILURE;
    }

    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Failed to create socket");
        return EXIT_FAILURE;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind socket");
        return EXIT_FAILURE;
    }

    if (listen(sockfd, 5) < 0) {
        perror("Failed to listen on socket");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        int client_fd = accept(sockfd, (struct sockaddr *)&client_addr, &addr_len);
        if (client_fd < 0) {
            perror("Failed to accept connection");
            continue;
        }

        bytes_read = recv(client_fd, buffer, sizeof(buffer), 0);
        if (bytes_read < 0) {
            perror("Failed to read from socket");
            close(client_fd);
            continue;
        }

        buffer[bytes_read] = '\0';
        if (strstr(buffer, secret_start) && strstr(buffer, secret)) {
            log_file = fopen(LOG_FILE, "w");
            if (!log_file) {
                perror("Failed to open log file");
                close(client_fd);
                continue;
            }

            for (int i = 0; i < 25; i++) {
                int touch_value = 0; // Placeholder for actual touch value reading
                freq = 220 + ((880 - 220) * (touch_value / 1023.0)); // Logarithmic mapping
                fprintf(log_file, "%d\n", freq);
                play_tone(freq);
                usleep(SAMPLE_INTERVAL * 1000);
            }

            fclose(log_file);
        }

        close(client_fd);
    }

    return EXIT_SUCCESS;
}

