    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        uint8_t data[MAG_DATA_LEN];
        ret = read(i2c_fd, data, MAG_DATA_LEN);
        if (ret != MAG_DATA_LEN) {
            perror("Failed to read from magnetometer");
            continue;
