        pwm_value = (magnitude * pwm_max) / 32768; // Assuming 16-bit sensor data
        if (pwm_value > pwm_max) {
            pwm_value = pwm_max;
        }
        gpiod_line_set_value(gpiod_line, pwm_value);

        usleep(100000); // 100 ms sleep
    }

    cleanup(0); // Should never reach here
    return 0;
