#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define SAMPLE_WINDOW 100
#define INTERVAL_MS 500

int main(int argc, char *argv[]) {
    int i2c_handle;
    int raw_samples[3 * SAMPLE_WINDOW];
    int sample_index = 0;
    int x_offset = 0, y_offset = 0, z_offset = 0;
    double x_avg = 0, y_avg = 0, z_avg = 0;
    uint8_t config_a = 0x70;
    uint8_t config_b = 0x20;
    uint8_t mode = 0x00;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure the HMC5883L
    if (i2cWriteReg(i2c_handle, 0x00, &config_a, 1) < 0 ||
        i2cWriteReg(i2c_handle, 0x01, &config_b, 1) < 0 ||
        i2cWriteReg(i2c_handle, 0x02, &mode, 1)) {
        fprintf(stderr, "Failed to configure HMC5883L.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        uint8_t data[6];
        if (i2cReadReg(i2c_handle, 0x03, data, 6) < 0) {
            fprintf(stderr, "Failed to read from HMC5883L.\n");
            continue;
        }

        int x = (data[0] << 8) | data[1];
        int y = (data[2] << 8) | data[3];
        int z = (data[4] << 8) | data[5];

        raw_samples[sample_index++] = x;
        raw_samples[sample_index++] = y;
        raw_samples[sample_index++] = z;

        if (sample_index >= SAMPLE_WINDOW) {
            sample_index = 0;

            for (int i = 0; i < SAMPLE_WINDOW; i++) {
                x_avg += raw_samples[i * 3];
                y_avg += raw_samples[i * 3 + 1];
                z_avg += raw_samples[i * 3 + 2];
            }

            x_offset = (int)(x_avg / SAMPLE_WINDOW);
            y_offset = (int)(y_avg / SAMPLE_WINDOW);
            z_offset = (int)(z_avg / SAMPLE_WINDOW);

            x_avg = 0;
            y_avg = 0;
            z_avg = 0;

            printf("X: %d, Y: %d, Z: %d\n", x - x_offset, y - y_offset, z - z_offset);
        }

        usleep(INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

void cleanup(int signum) {
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

