#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x1D
#define I2C_DEV "/dev/i2c-1"
#define I2C_WHO_AM_I 0x0F
#define I2C_CTRL_REG1 0x20
#define I2C_CTRL_REG4 0x23
#define I2C_INT1_CFG 0x2F
#define I2C_OUT_X_L_A 0x28
#define I2C_BUFFER_SIZE 64
#define I2C_SAMPLE_INTERVAL 10000 // 10 ms
#define I2C_THRESHOLD 2000 // 2000 mg

struct sample {
    int x, y, z;
};

struct sample buffer[I2C_BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

gpiod_chip *chip;
gpiod_line *line;

void handle_interrupt(int signum) {
    printf("Interrupt detected at %ld\n", (long)time(NULL));
    for (int i = 0; i < 10; ++i) {
        int idx = (buffer_tail + i) % I2C_BUFFER_SIZE;
        printf("Sample %d: x=%d, y=%d, z=%d\n", idx, buffer[idx].x, buffer[idx].y, buffer[idx].z);
    }
}

void cleanup() {
    gpiod_line_request_free(line);
    gpiod_chip_put(chip);
    close(i2c_fd);
    exit(0);
}

int main() {
    FILE *i2c_file = fopen(I2C_DEV, "r+");
    if (!i2c_file) {
        perror("Failed to open I2C device");
        return 1;
    }

    int i2c_fd = fileno(i2c_file);
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        fclose(i2c_file);
        return 1;
    }

    if (i2c_smbus_read_byte_data(i2c_fd, I2C_WHO_AM_I) != 0x49) {
        fprintf(stderr, "Invalid WHO_AM_I register value\n");
        fclose(i2c_file);
        return 1;
    }

    if (i2c_smbus_write_byte_data(i2c_fd, I2C_CTRL_REG1, 0x57) < 0) {
        perror("Failed to write CTRL_REG1");
        fclose(i2c_file);
        return 1;
    }

    if (i2c_smbus_write_byte_data(i2c_fd, I2C_CTRL_REG4, 0x00) < 0) {
        perror("Failed to write CTRL_REG4");
        fclose(i2c_file);
        return 1;
    }

    if (i2c_smbus_write_byte_data(i2c_fd, I2C_INT1_CFG, 0x2A) < 0) {
        perror("Failed to write INT1_CFG");
        fclose(i2c_file);
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(i2c_file);
        return 1;
    }

    line = gpiod_line_request_by_name(chip, "gpio23", "lsm303d_monitor", 0, GPIOD_LINE_DIRECTION_IN);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        fclose(i2c_file);
        return 1;
    }

    gpiod_line_request_set_debounce(line, 100000); // 100 ms debounce
    gpiod_line_request_set_consumer(line, "lsm303d_monitor");

    signal(SIGINT, handle_interrupt);

    while (1) {
        struct sample sample;
        if (i2c_smbus_read_i2c_block_data(i2c_fd, I2C_OUT_X_L_A | 0x80, 6, (char*)&sample) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }

        sample.x = (sample.x << 8) | sample.x;
        sample.y = (sample.y << 8) | sample.y;
        sample.z = (sample.z << 8) | sample.z;

        buffer[buffer_head] = sample;
        buffer_head = (buffer_head + 1) % I2C_BUFFER_SIZE;

        if (buffer_head == buffer_tail) {
            buffer_tail = (buffer_tail + 1) % I2C_BUFFER_SIZE;
        }

        usleep(I2C_SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

