#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

static struct gpiod_line *line1, *line2;

void cleanup(int signum) {
    if (line1) {
        gpiod_line_set_value(line1, 0);
        gpiod_line_free(line1);
    }
    if (line2) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_free(line2);
    }
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

int main() {
    struct gpiod_chip *chip;
