#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <pigpio.h>

#define EXPECTED_CODE "123456"
#define BUFFER_SIZE 10
#define TIMEOUT_MS 5000

volatile sig_atomic_t shutdown = 0;

void handle_signal(int signum) {
    shutdown = 1;
}

int read_serial_code(int fd, char *buffer, int timeout_ms) {
    struct termios options;
    tcgetattr(fd, &options);
    options.c_cc[VTIME] = (timeout_ms / 100) % 10;
    options.c_cc[VMIN] = 0;
    tcsetattr(fd, TCSANOW, &options);

    int bytes_read = 0;
    while (!shutdown && bytes_read < 6) {
        int n = read(fd, buffer + bytes_read, 1);
        if (n < 0) {
            perror("read");
            return -1;
        } else if (n == 0) {
            break;
        }

        if (buffer[bytes_read] >= '0' && buffer[bytes_read] <= '9') {
            bytes_read++;
        } else {
            bytes_read = 0;
        }
    }

    tcsetattr(fd, TCSANOW, &options);
    return bytes_read;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(17, PI_OUTPUT);
    gpioWrite(17, PI_LOW);
    gpioSetMode(27, PI_OUTPUT);
    gpioWrite(27, PI_LOW);

    int primary_fd = open("/dev/serial0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (primary_fd == -1) {
        fprintf(stderr, "Failed to open primary serial port\n");
        gpioTerminate();
        return 1;
    }

    int secondary_fd = open("/dev/serial1", O_RDWR | O_NOCTTY | O_NDELAY);
    if (secondary_fd == -1) {
        fprintf(stderr, "Failed to open secondary serial port\n");
        close(primary_fd);
        gpioTerminate();
        return 1;
    }

    struct termios options;
    tcgetattr(primary_fd, &options);
    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    tcsetattr(primary_fd, TCSANOW, &options);

    tcgetattr(secondary_fd, &options);
    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    tcsetattr(secondary_fd, TCSANOW, &options);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    char primary_code[BUFFER_SIZE + 1];
    char secondary_code[BUFFER_SIZE + 1];

    while (!shutdown) {
        memset(primary_code, 0, sizeof(primary_code));
        memset(secondary_code, 0, sizeof(secondary_code));

        int primary_read = read_serial_code(primary_fd, primary_code, TIMEOUT_MS);
        int secondary_read = read_serial_code(secondary_fd, secondary_code, TIMEOUT_MS);

        if (primary_read == 6 && secondary_read == 6) {
            if (memcmp(primary_code, EXPECTED_CODE, 6) == 0 && memcmp(secondary_code, EXPECTED_CODE, 6) == 0) {
                gpioWrite(17, PI_HIGH);
                gpioWrite(27, PI_HIGH);
                sleep(2);
                gpioWrite(17, PI_LOW);
                gpioWrite(27, PI_LOW);
            }
        }
    }

    close(primary_fd);
    close(secondary_fd);
    gpioTerminate();

    return 0;
}

