#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>

#define GPIO_PIR 4
#define GPIO_RELAY 17
#define STRIKE_DURATION 1000 // milliseconds
#define FAILSAFE_TIMEOUT 10000 // milliseconds
#define POLL_INTERVAL 50 // milliseconds

static void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
}

static void log_info(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
}

static void log_warning(const char *msg) {
    syslog(LOG_WARNING, "%s", msg);
}

static void handle_signal(int signum) {
    log_info("Received signal %d, initiating clean shutdown...", signum);
    gpiod_line_set_value(gpiod_line, 0);
    gpiod_line_free(gpiod_line);
    gpiod_chip_put(gpiod_chip);
    closelog();
    exit(signum);
}

int main() {
    struct gpiod_chip *gpiod_chip = NULL;
    struct gpiod_line *gpiod_line = NULL;
    int pir_value = 0;
    int last_pir_value = 0;
    int strike_start_time = 0;
    int fail_safe_start_time = 0;

    openlog("door_strike", LOG_PID, LOG_USER);

    gpiod_chip = gpiod_chip_open("gpiochip0");
    if (!gpiod_chip) {
        log_error("Failed to open gpiochip0");
        return 1;
    }

    gpiod_line = gpiod_line_request(gpiod_chip, GPIO_PIR, "PIR", "PIR sensor", 0);
    if (!gpiod_line) {
        log_error("Failed to request GPIO line for PIR");
        goto error_exit;
    }

    gpiod_line = gpiod_line_request(gpiod_chip, GPIO_RELAY, "RELAY", "Relay control", 0);
    if (!gpiod_line) {
        log_error("Failed to request GPIO line for RELAY");
        goto error_exit;
    }

    gpiod_line_direction_output(gpiod_line);
    gpiod_line_set_value(gpiod_line, 0);

    gpiod_line = gpiod_line_request(gpiod_chip, GPIO_PIR, "PIR", "PIR sensor", GPIOD_LINE_ACTIVE_LOW);
    if (!gpiod_line) {
        log_error("Failed to request GPIO line for PIR");
        goto error_exit;
    }

    gpiod_line_direction_input(gpiod_line);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        gpiod_line_get_value(gpiod_line, &pir_value);

        if (pir_value != last_pir_value) {
            if (pir_value) {
                log_info("Motion detected");
                strike_start_time = time(NULL);
                fail_safe_start_time = strike_start_time;
                gpiod_line_set_value(gpiod_line, 1);
                log_info("Relay energized");
            } else {
                if (time(NULL) - strike_start_time >= STRIKE_DURATION / 1000) {
                    gpiod_line_set_value(gpiod_line, 0);
                    log_info("Strike duration elapsed, relay de-energized");
                }
                if (time(NULL) - fail_safe_start_time >= FAILSAFE_TIMEOUT / 1000) {
                    log_warning("PIR sensor HIGH for more than 10 seconds, potential malfunction");
                    gpiod_line_set_value(gpiod_line, 0);
                    log_info("Relay de-energized due to failsafe");
                }
            }
            last_pir_value = pir_value;
        }

        usleep(POLL_INTERVAL * 1000);
    }

error_exit:
    if (gpiod_line) {
        gpiod_line_free(gpiod_line);
    }
    if (gpiod_chip) {
        gpiod_chip_put(gpiod_chip);
    }
    closelog();
    return 1;
}

