#define RELAY_PINS {4, 17, 27, 22}
#define NUM_RELAYS 4
#define TIMER_INTERVAL 60 // seconds
#define RELAY_ON_TIME 300 // seconds
#define PAUSE_TIME 60 // seconds

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

void relay_action(int timer, int level, void *userdata) {
    static int relay_index = 0;
    static int state = 0; // 0: pause, 1: activate, 2: deactivate
    static int relay_on_count = 0;

    if (stop_flag) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (gpioWrite(RELAY_PINS[i], PI_ON) < 0) {
                syslog(LOG_ERR, "Failed to deactivate relay %d", RELAY_PINS[i]);
            }
        }
        gpioTerminate();
        closelog();
        exit(1);
    }

    if (state == 0) { // Pause
        relay_on_count = 0;
        state = 1; // Switch to activate
    } else if (state == 1) { // Activate
        if (gpioWrite(RELAY_PINS[relay_index], PI_OFF) < 0) {
            syslog(LOG_ERR, "Failed to activate relay %d", RELAY_PINS[relay_index]);
        } else {
            syslog(LOG_INFO, "Activated relay %d at %ld", RELAY_PINS[relay_index], time(NULL));
        }
        relay_on_count++;
        if (relay_on_count >= RELAY_ON_TIME / TIMER_INTERVAL) {
            relay_on_count = 0;
            state = 2; // Switch to deactivate
        }
    } else if (state == 2) { // Deactivate
        if (gpioWrite(RELAY_PINS[relay_index], PI_ON) < 0) {
            syslog(LOG_ERR, "Failed to deactivate relay %d", RELAY_PINS[relay_index]);
        } else {
            syslog(LOG_INFO, "Deactivated relay %d at %ld", RELAY_PINS[relay_index], time(NULL));
        }
        relay_index = (relay_index + 1) % NUM_RELAYS;
        state = 0; // Switch to pause
    }
}

int main() {
