#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <time.h>

#define I2C_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"
#define BUFFER_SIZE 100
#define BUFFER_LEN (BUFFER_SIZE * sizeof(float[3]))
#define ACCEL_XOUT_H 0x3B
#define ACCEL_CONFIG 0x1C
#define PWR_MGMT_1 0x6B

static int i2c_fd;
static int sysfs_fd;
static float *buffer;
static struct itimerval timer;

void read_accelerometer() {
    char data[6];
    int bytes_read = read(i2c_fd, data, 6);
    if (bytes_read != 6) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }

    float x = (data[0] << 8) | data[1];
    float y = (data[2] << 8) | data[3];
    float z = (data[4] << 8) | data[5];

    x /= 16384.0;
    y /= 16384.0;
    z /= 16384.0;

    memcpy(buffer, &x, sizeof(float));
    memcpy(buffer + 1, &y, sizeof(float));
    memcpy(buffer + 2, &z, sizeof(float));
}

void timer_handler(int signum) {
    read_accelerometer();
}

void cleanup() {
    close(i2c_fd);
    close(sysfs_fd);
    munmap(buffer, BUFFER_LEN);
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_usec = 0;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = 0;
    signal(SIGINT, SIG_DFL);
    signal(SIGTERM, SIG_DFL);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C device address");
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, "\x00", 1) != 1) {
        perror("Failed to wake up the sensor");
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, "\x00", 1) != 1) {
        perror("Failed to set accelerometer range");
        exit(EXIT_FAILURE);
    }

    buffer = mmap(NULL, BUFFER_LEN, PROT_READ | PROT_WRITE, MAP_SHARED, -1, 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to map memory");
        exit(EXIT_FAILURE);
    }

    timer.it_value.tv_sec = 0;
    timer.it_value.tv_usec = 10000; // 100 Hz
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = 10000;

    if (setitimer(ITIMER_REAL, &timer, NULL) < 0) {
        perror("Failed to set timer");
        exit(EXIT_FAILURE);
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGALRM;
    sev.sigev_value.sival_ptr = &timer;

    if (sigqueue(getpid(), SIGALRM, sev) < 0) {
        perror("Failed to queue signal");
        exit(EXIT_FAILURE);
    }

    while (1) {
        pause();
    }

    return 0;
}

