#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PINS {18, 23, 24, 25}
#define INTERVALS {2, 3, 5, 7}

gpiod_chip *chip;
gpiod_line *lines[4];

void handle_signal(int signum) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_request_free(lines[i]);
    }
    gpiod_chip_put(chip);
    exit(signum);
}

void toggle_relays(void) {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        for (int i = 0; i < 4; i++) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            if (end.tv_sec - start.tv_sec >= INTERVALS[i]) {
                gpiod_line_set_value(lines[i], !gpiod_line_get_value(lines[i]));
                start = end;
            }
        }
        usleep(10000); // Sleep for 10ms to avoid busy-waiting
    }
}

int main(void) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_by_name(chip, "gpio%d", GPIO_PINS[i], "toggle_relay", 0, &lines[i]) < 0) {
            perror("Failed to request GPIO line");
            for (int j = 0; j < i; j++) {
                gpiod_line_request_free(lines[j]);
            }
            gpiod_chip_put(chip);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_direction_output(lines[i]) < 0) {
            perror("Failed to set GPIO direction to output");
            for (int j = 0; j < i; j++) {
                gpiod_line_request_free(lines[j]);
            }
            gpiod_chip_put(chip);
            exit(EXIT_FAILURE);
        }
    }

    toggle_relays();

    return 0;
}

