#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_SOUND_SENSOR 17
#define GPIO_RELAY 27
#define DEBOUNCE_INTERVAL 3000 // 3 seconds
#define POLL_INTERVAL 100 // 100 ms

volatile sig_atomic_t shutdown = 0;

void handle_signal(int signum) {
    shutdown = 1;
}

void log_timestamp(const char *filename) {
    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for logging.\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(file, "%s\n", buffer);

    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetMode(GPIO_SOUND_SENSOR, PI_INPUT);
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state = 0;
    time_t last_trigger_time = 0;

    while (!shutdown) {
        int current_state = gpioRead(GPIO_SOUND_SENSOR);

        if (current_state != last_state) {
            if (current_state == 1) {
                if (time(NULL) - last_trigger_time >= DEBOUNCE_INTERVAL) {
                    last_trigger_time = time(NULL);
                    log_timestamp("alarm_log.txt");
                    gpioWrite(GPIO_RELAY, PI_ON);
                }
            } else {
                gpioWrite(GPIO_RELAY, PI_OFF);
            }
        }

        last_state = current_state;

        if (!shutdown) {
            usleep(POLL_INTERVAL * 1000);
        }
    }

    gpioWrite(GPIO_RELAY, PI_OFF);
    gpioTerminate();

    return 0;
}

