#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define DEFAULT_ADDR 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define BUFFER_SIZE 100
#define THRESHOLD 50.0

typedef struct {
    float x, y, z;
} GyroData;

GyroData buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_count = 0;

void read_gyro_data(int fd) {
    unsigned char data[6];
    if (read(fd, data, 6) != 6) {
        perror("Failed to read gyroscope data");
        return;
    }

    GyroData gyro;
    gyro.x = (data[0] << 8) | data[1];
    gyro.y = (data[2] << 8) | data[3];
    gyro.z = (data[4] << 8) | data[5];

    float magnitude = sqrt(gyro.x * gyro.x + gyro.y * gyro.y + gyro.z * gyro.z);
    magnitude *= 131.0 / 32768.0; // Convert to degrees/second

    if (magnitude > THRESHOLD) {
        printf("Angular velocity exceeded threshold: %.2f deg/s\n", magnitude);
    }

    buffer[buffer_head] = gyro;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    buffer_count = (buffer_count < BUFFER_SIZE) ? buffer_count + 1 : BUFFER_SIZE;
}

void init_sensor(int fd) {
    // Wake up the sensor
    unsigned char wake_up = 0x00;
    if (write(fd, &wake_up, 1) != 1) {
        perror("Failed to wake up sensor");
        return;
    }

    // Verify the device
    unsigned char who_am_i;
    if (read(fd, &who_am_i, 1) != 1 || who_am_i != DEFAULT_ADDR) {
        perror("Failed to verify sensor");
        return;
    }
}

void cleanup() {
    printf("Cleaning up...\n");
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

int main() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, DEFAULT_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(fd);
        return 1;
    }

    init_sensor(fd);

    signal(SIGINT, handle_sigint);

    while (1) {
        read_gyro_data(fd);
        usleep(100000); // Sleep for 100ms
    }

    close(fd);
    return 0;
}

