#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SERIAL_PORT "/dev/serial0"
#define BAUD_RATE 9600
#define TXD_GPIO 14
#define RXD_GPIO 15
#define READ_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define READ_COMMAND_LEN 9
#define READ_TIMEOUT 1000000 // 1 second in microseconds
#define LOG_INTERVAL 5000000 // 5 seconds in microseconds

FILE *co2_log_file;
FILE *co2_error_file;

void handle_signal(int signum) {
    if (co2_log_file) {
        fclose(co2_log_file);
    }
    if (co2_error_file) {
        fclose(co2_error_file);
    }
    if (pi >= 0) {
        pigpio_stop();
    }
    exit(signum);
}

int main() {
    int pi = pigpio_start();
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio: %s\n", pigpio_perror(pi));
        return 1;
    }

    int ser = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (ser < 0) {
        fprintf(stderr, "Failed to open serial port: %s\n", pigpio_perror(ser));
        pigpio_stop();
        return 1;
    }

    co2_log_file = fopen("co2_log.json", "w");
    if (!co2_log_file) {
        fprintf(stderr, "Failed to open co2_log.json: %s\n", strerror(errno));
        serClose(ser);
        pigpio_stop();
        return 1;
    }

    co2_error_file = fopen("co2_error.log", "w");
    if (!co2_error_file) {
        fprintf(stderr, "Failed to open co2_error.log: %s\n", strerror(errno));
        fclose(co2_log_file);
        serClose(ser);
        pigpio_stop();
        return 1;
    }

    struct timespec start_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    while (1) {
        if (serWrite(ser, READ_COMMAND, READ_COMMAND_LEN) != READ_COMMAND_LEN) {
            fprintf(stderr, "Failed to write to serial port: %s\n", pigpio_perror(ser));
            continue;
        }

        struct timespec read_start;
        clock_gettime(CLOCK_REALTIME, &read_start);

        uint8_t response[READ_COMMAND_LEN];
        int bytes_read = 0;
        while (bytes_read < READ_COMMAND_LEN) {
            if (serDataAvailable(ser, READ_TIMEOUT) > 0) {
                int read_now = serRead(ser, response + bytes_read, READ_COMMAND_LEN - bytes_read);
                if (read_now < 0) {
                    fprintf(stderr, "Failed to read from serial port: %s\n", pigpio_perror(ser));
                    break;
                }
                bytes_read += read_now;
            }

            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            if (now.tv_sec * 1000000 + now.tv_nsec / 1000 - read_start.tv_sec * 1000000 - read_start.tv_nsec / 1000 > READ_TIMEOUT) {
                fprintf(stderr, "Timeout reading from serial port\n");
                break;
            }
        }

        if (bytes_read != READ_COMMAND_LEN) {
            continue;
        }

        uint8_t checksum = 0;
        for (int i = 1; i < 8; i++) {
            checksum += response[i];
        }
        checksum = ~checksum + 1;
        if (checksum != response[7]) {
            fprintf(co2_error_file, "%ld: Invalid checksum\n", (long)clock_gettime(CLOCK_REALTIME, NULL).tv_sec * 1000000 + (long)clock_gettime(CLOCK_REALTIME, NULL).tv_nsec / 1000);
            continue;
        }

        uint16_t co2_ppm = (response[2] << 8) | response[3];
        fprintf(co2_log_file, "{\"timestamp\":%ld,\"ppm\":%d,\"error\":false}\n", (long)clock_gettime(CLOCK_REALTIME, NULL).tv_sec * 1000000 + (long)clock_gettime(CLOCK_REALTIME, NULL).tv_nsec / 1000, co2_ppm);
        fflush(co2_log_file);
        printf("{\"timestamp\":%ld,\"ppm\":%d,\"error\":false}\n", (long)clock_gettime(CLOCK_REALTIME, NULL).tv_sec * 1000000 + (long)clock_gettime(CLOCK_REALTIME, NULL).tv_nsec / 1000, co2_ppm);

        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        if (now.tv_sec * 1000000 + now.tv_nsec / 1000 - start_time.tv_sec * 1000000 - start_time.tv_nsec / 1000 > LOG_INTERVAL) {
            start_time = now;
        }
    }

    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    return 0;
}

