#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_REG 0x03
#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define OFFSET_X 100
#define OFFSET_Y -50
#define DEVIATION_THRESHOLD 10.0
#define SAMPLE_INTERVAL 100000 // 100 ms

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

double calculate_heading(int x, int y) {
    double heading = atan2(y, x) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }
    return heading;
}

void read_heading() {
    int x, y, z;
    uint8_t data[6];
    int i2c_result;

    i2c_result = i2c_read_i2c_block_data(I2C_BUS, I2C_ADDR, DATA_REG, 6, data);
    if (i2c_result != 6) {
        fprintf(stderr, "Error reading data from HMC5883L: %d\n", i2c_result);
        return;
    }

    x = (data[0] << 8) | data[1];
    z = (data[2] << 8) | data[3];
    y = (data[4] << 8) | data[5];

    x -= OFFSET_X;
    y -= OFFSET_Y;

    double heading = calculate_heading(x, y);

    printf("Compensated Heading: %.2f degrees\n", heading);

    if (abs(heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
        gpioWrite(17, 1);
    } else {
        gpioWrite(17, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(17, PI_OUTPUT);

    uint8_t config_a = 0x70;
    uint8_t config_b = 0x20;
    uint8_t mode = 0x00;

    int i2c_result;

    i2c_result = i2c_write_i2c_block_data(I2C_BUS, I2C_ADDR, CONFIG_A, &config_a, 1);
    if (i2c_result != 1) {
        fprintf(stderr, "Error writing CONFIG_A: %d\n", i2c_result);
        goto cleanup;
    }

    i2c_result = i2c_write_i2c_block_data(I2C_BUS, I2C_ADDR, CONFIG_B, &config_b, 1);
    if (i2c_result != 1) {
        fprintf(stderr, "Error writing CONFIG_B: %d\n", i2c_result);
        goto cleanup;
    }

    i2c_result = i2c_write_i2c_block_data(I2C_BUS, I2C_ADDR, MODE, &mode, 1);
    if (i2c_result != 1) {
        fprintf(stderr, "Error writing MODE: %d\n", i2c_result);
        goto cleanup;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        read_heading();
        usleep(SAMPLE_INTERVAL);
    }

cleanup:
    gpioTerminate();
    return 0;
}

