        write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES, 1) != 1 ||
        write(i2c_fd, &BH1750_DATA_REG, 1) != 1 ||
        read(i2c_fd, buffer, 2) != 2) {
        perror("I2C read error");
        return -1;
    }

    raw_lux = (buffer[0] << 8) | buffer[1];
    return raw_lux / LUX_DIVISOR;
}

void control_relays(int lux) {
    gpiod_line_set_value(red_line, lux < 50);
    gpiod_line_set_value(green_line, (lux >= 50) && (lux < 150));
    gpiod_line_set_value(blue_line, (lux >= 150) && (lux < 300));
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    red_line = gpiod_line_request_by_name(chip, "gpio17", "red_relay", 0);
    if (!red_line) {
        perror("Failed to request GPIO17");
        goto error_red;
    }

    green_line = gpiod_line_request_by_name(chip, "gpio27", "green_relay", 0);
    if (!green_line) {
        perror("Failed to request GPIO27");
        goto error_green;
    }

    blue_line = gpiod_line_request_by_name(chip, "gpio22", "blue_relay", 0);
    if (!blue_line) {
        perror("Failed to request GPIO22");
        goto error_blue;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto error_i2c;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        goto error_ioctl;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto error_log;
    }

    while (1) {
        int lux = read_lux();
        if (lux < 0) {
            perror("Failed to read lux value");
            continue;
        }

        control_relays(lux);

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %d lux %d %d %d\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec, lux,
                gpiod_line_get_value(red_line),
                gpiod_line_get_value(green_line),
                gpiod_line_get_value(blue_line));

        fflush(log_file);
        usleep(1000000); // Sleep for 1 second
    }

error_log:
    close(i2c_fd);
error_ioctl:
    gpiod_line_free(blue_line);
error_blue:
    gpiod_line_free(green_line);
error_green:
    gpiod_line_free(red_line);
error_red:
    gpiod_chip_put(chip);
    remove(LOG_FILE);
    return 1;
}
