#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SCHEDULE_FILE "lighting_schedule.txt"
#define NUM_RELAYS 4
#define RELAY_PINS[NUM_RELAYS] {4, 17, 27, 22}
#define PWM_FREQ 100
#define PWM_DUTY_RANGE 100
#define TRANSITION_TIME 1800

typedef struct {
    int hour;
    int minute;
    int second;
    int relay;
    int state;
} ScheduleEntry;

ScheduleEntry schedule[100]; // Assuming a maximum of 100 entries
int schedule_size = 0;

void handle_signal(int signum) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(RELAY_PINS[i], 0);
    }
    gpioTerminate();
    exit(signum);
}

void read_schedule() {
    FILE *file = fopen(SCHEDULE_FILE, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening schedule file.\n");
        return;
    }

    while (fscanf(file, "%d:%d:%d,%d,%s", &schedule[schedule_size].hour, &schedule[schedule_size].minute, &schedule[schedule_size].second, &schedule[schedule_size].relay, schedule[schedule_size].state + 1) == 4) {
        schedule[schedule_size].state = (schedule[schedule_size].state + 1) - '0';
        schedule_size++;
    }

    fclose(file);
}

void check_schedule() {
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);

    for (int i = 0; i < schedule_size; i++) {
        if (now_tm->tm_hour == schedule[i].hour && now_tm->tm_min == schedule[i].minute && now_tm->tm_sec == schedule[i].second) {
            int relay = schedule[i].relay - 1;
            int target_duty = schedule[i].state * PWM_DUTY_RANGE;

            if (gpioRead(RELAY_PINS[relay]) != schedule[i].state) {
                int current_duty = gpioReadPWM(RELAY_PINS[relay]);
                int step = (target_duty - current_duty) / TRANSITION_TIME;

                for (int t = 0; t <= TRANSITION_TIME; t++) {
                    int duty = current_duty + step * t;
                    gpioPWM(RELAY_PINS[relay], duty);
                    usleep(TRANSITION_TIME / 1000);
                }
            }
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    read_schedule();

    while (1) {
        check_schedule();
        usleep(1000000); // Sleep for 1 second
    }

    return 0;
}
```

This C program uses the pigpio library to control four relay-controlled lamp actuators on GPIO4, GPIO17, GPIO27, and GPIO22. It reads a 24-hour schedule from `lighting_schedule.txt` and smoothly fades the lamp's brightness using PWM over a 1800-second (30-minute) transition when the current time matches an entry. It handles file read errors, GPIO initialization failures, and invalid schedule entries gracefully. It also uses signal handling to turn off all relays and release GPIO resources cleanly on exit.

