#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 30
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define MEASUREMENT_RATE 50
#define MIN_INTERVAL (1000000 / MEASUREMENT_RATE)

void handle_interrupt(int signum) {
    if (signum == SIGINT) {
        gpioPWM(BUZZER_PIN, 0);
        gpioTerminate();
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_interrupt);

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode.\n");
        goto cleanup;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode.\n");
        goto cleanup;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN mode.\n");
        goto cleanup;
    }

    while (1) {
        gpioWrite(TRIGGER_PIN, PI_LOW);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        int start_tick = gpioTick();
        int echo_pin_state = PI_TIMEOUT;

        while (echo_pin_state == PI_TIMEOUT) {
            echo_pin_state = gpioRead(ECHO_PIN);
            if (echo_pin_state == PI_TIMEOUT) {
                fprintf(stderr, "Echo timeout.\n");
                continue;
            }
        }

        int end_tick = gpioTick();
        int pulse_width = end_tick - start_tick;

        if (pulse_width <= 0) {
            fprintf(stderr, "Invalid pulse width.\n");
            continue;
        }

        double distance = (double)pulse_width / 58.0; // cm

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Distance out of range.\n");
            continue;
        }

        double frequency = MIN_FREQUENCY + ((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_FREQUENCY - MIN_FREQUENCY);
        frequency = fmax(fmin(frequency, MAX_FREQUENCY), MIN_FREQUENCY);

        gpioPWM(BUZZER_PIN, (int)frequency);

        gpioDelay(MIN_INTERVAL - (int)pulse_width * 10000); // Delay to maintain measurement rate
    }

cleanup:
    gpioTerminate();
    return 0;
}

