#define LED_GREEN 22
#define LED_BLUE 27

volatile sig_atomic_t stop = 0;

void cleanup(int signum) {
    stop = 1;
    gpioPWM(LED_RED, 0);
    gpioPWM(LED_GREEN, 0);
    gpioPWM(LED_BLUE, 0);
    gpioTerminate();
    exit(0);
}

void handle_signal(int signum) {
    cleanup(signum);
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handle_signal);

    if (gpioSetMode(LED_RED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED_RED\n");
        goto cleanup;
    }

    if (gpioSetMode(LED_GREEN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED_GREEN\n");
        goto cleanup;
    }

    if (gpioSetMode(LED_BLUE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED_BLUE\n");
        goto cleanup;
    }

    srand(time(NULL));

    while (!stop) {
        double proximity = (double)rand() / RAND_MAX; // Simulated proximity value

        int red_duty = (int)(255 * proximity);
        int green_duty = (int)(255 * (1 - proximity));
        int blue_duty = 0;

        if (gpioPWM(LED_RED, red_duty) < 0) {
            fprintf(stderr, "Failed to set PWM for LED_RED\n");
            goto cleanup;
        }

        if (gpioPWM(LED_GREEN, green_duty) < 0) {
            fprintf(stderr, "Failed to set PWM for LED_GREEN\n");
            goto cleanup;
        }

        if (gpioPWM(LED_BLUE, blue_duty) < 0) {
            fprintf(stderr, "Failed to set PWM for LED_BLUE\n");
            goto cleanup;
        }

        sleep(1); // Adjust sleep time as needed
    }

cleanup:
    cleanup(0);

    return 0;
}

