#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x68
#define GYRO_REG_START 0x43
#define GYRO_DATA_LEN 6
#define SENSITIVITY 131.0
#define LOG_FILE "gyro_log.txt"

void handle_signal(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    close(i2c_fd);
    exit(signum);
}

int main() {
    int i2c_fd = -1;
    char filename[100];
    FILE *log_file = NULL;
    struct timespec ts;
    unsigned char data[GYRO_DATA_LEN];
    double x, y, z;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Wake the sensor
    if (write(i2c_fd, "\x6B\x00", 2) != 2) {
        perror("Failed to wake sensor");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    sprintf(filename, "%s", LOG_FILE);
    log_file = fopen(filename, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read(i2c_fd, data, GYRO_DATA_LEN) != GYRO_DATA_LEN) {
            perror("Failed to read gyroscope data");
            fclose(log_file);
            close(i2c_fd);
            return 1;
        }

        // Convert data to degrees/second
        x = ((double)((int16_t)(data[0] << 8 | data[1]))) / SENSITIVITY;
        y = ((double)((int16_t)(data[2] << 8 | data[3]))) / SENSITIVITY;
        z = ((double)((int16_t)(data[4] << 8 | data[5]))) / SENSITIVITY;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Log data
        fprintf(log_file, "%ld.%09ld: %.2f %.2f %.2f\n", (long)ts.tv_sec, (long)ts.tv_nsec, x, y, z);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close log file and I2C device
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

