#include <pigpio.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define PWM_FREQ 440 // Hz (A4 note)
#define DEBOUNCE_TIME 50 // ms

volatile sig_atomic_t stop_requested = 0;

void handle_button_interrupt(int gpio, int level, uint32_t tick) {
    if (level == 0 && !stop_requested) {
        stop_requested = 1;
    }
}

void cleanup(int signum) {
    stop_requested = 1;
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    uint32_t last_press_time = 0;
    uint32_t melody[] = {440, 523, 659, 784, 988, 1175, 1319, 1470}; // A4, C5, E5, G5, A5, C6, E6, G6
    int melody_length = sizeof(melody) / sizeof(melody[0]);

    if (gpioSetISRFuncEx(BUTTON_PIN, handle_button_interrupt, 0, 0) < 0) {
        fprintf(stderr, "Failed to set interrupt function for button\n");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (!stop_requested) {
        if (stop_requested) {
            gpioSetPWMfrequency(BUZZER_PIN, 0);
            stop_requested = 0;
        } else {
            if (gpioTickDiff(last_press_time) >= DEBOUNCE_TIME) {
                for (int i = 0; i < melody_length; i++) {
                    if (stop_requested) {
                        break;
                    }
                    gpioSetPWMfrequency(BUZZER_PIN, melody[i]);
                    gpioSetPWMdutycycle(BUZZER_PIN, 50);
                    usleep(1000000 / melody[i]); // Sleep for one period of the note
                }
                last_press_time = gpioTick();
            }
        }
    }

    return 0;
}

