#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <time.h>

#define LSM303DLHC_ADDR 0x1E
#define MR_REG_M 0x02
#define CRA_REG_M 0x00
#define DATA_REG_START 0x03
#define DATA_REG_END 0x08
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20
#define CSV_FILE "mag_log.csv"

static int i2c_fd;
static int compass_directions[8][2] = {{0, 45}, {45, 90}, {90, 135}, {135, 180}, {180, 225}, {225, 270}, {270, 315}, {315, 360}};

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

int read_i2c_data(int reg, uint8_t *data, int length) {
    int ret;
    uint8_t buf[length];

    ret = ioctl(i2c_fd, I2C_SLAVE, LSM303DLHC_ADDR);
    if (ret < 0) {
        perror("I2C_SLAVE");
        return -1;
    }

    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return -1;
    }

    ret = read(i2c_fd, buf, length);
    if (ret != length) {
        perror("read");
        return -1;
    }

    memcpy(data, buf, length);
    return 0;
}

int main() {
    uint8_t data[6];
    int ret;
    float x, y, z, heading;
    char timestamp[20];
    char direction[10];
    FILE *csv_file;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    ret = write(i2c_fd, &CRA_REG_M, 1);
    if (ret != 1) {
        perror("write");
        goto cleanup;
    }

    ret = write(i2c_fd, &0x14, 1);
    if (ret != 1) {
        perror("write");
        goto cleanup;
    }

    ret = write(i2c_fd, &MR_REG_M, 1);
    if (ret != 1) {
        perror("write");
        goto cleanup;
    }

    ret = write(i2c_fd, &0x00, 1);
    if (ret != 1) {
        perror("write");
        goto cleanup;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("fopen");
        goto cleanup;
    }

    if (fseek(csv_file, 0, SEEK_END) != 0) {
        perror("fseek");
        goto cleanup;
    }

    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }

    while (1) {
        if (read_i2c_data(DATA_REG_START, data, 6) < 0) {
            fprintf(stderr, "Failed to read data from magnetometer\n");
            continue;
        }

        x = ((int16_t)data[0] << 8) | data[1];
        y = ((int16_t)data[4] << 8) | data[5];
        z = ((int16_t)data[2] << 8) | data[3];

        x -= X_OFFSET;
        y -= Y_OFFSET;
        z -= Z_OFFSET;

        heading = atan2f(y, x) * 180.0 / M_PI;
        if (heading < 0) {
            heading += 360.0;
        }

        for (int i = 0; i < 8; i++) {
            if (heading >= compass_directions[i][0] && heading < compass_directions[i][1]) {
                strcpy(direction, "N");
                if (i == 1) strcpy(direction, "NE");
                if (i == 2) strcpy(direction, "E");
                if (i == 3) strcpy(direction, "SE");
                if (i == 4) strcpy(direction, "S");
                if (i == 5) strcpy(direction, "SW");
                if (i == 6) strcpy(direction, "W");
                if (i == 7) strcpy(direction, "NW");
                break;
            }
        }

        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(csv_file, "%s,%f,%f,%f,%f\n", timestamp, x, y, z, heading);

        fflush(csv_file);
        sleep(1);
    }

cleanup:
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

