#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_RELAY 17
#define GPIO_TOUCH 4
#define DEBOUNCE_TIME 200000 // 200 ms in microseconds

static int relay_state = 0; // 0: OFF, 1: ON
static time_t last_touch_time = 0;

void touch_callback(int gpio, int level, uint32_t tick) {
    time_t current_time = time(NULL);

    if (current_time - last_touch_time >= DEBOUNCE_TIME / 1000000) {
        last_touch_time = current_time;

        if (level == 1) { // Touch detected
            relay_state = !relay_state; // Toggle relay state
            gpioWrite(GPIO_RELAY, relay_state);

            char timestamp[20];
            struct tm *time_info;
            time_t rawtime = time(NULL);
            time_info = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", time_info);

            FILE *log_file = fopen("relay_log.json", "a");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open relay_log.json for appending.\n");
                exit(EXIT_FAILURE);
            }

            fprintf(log_file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, relay_state ? "ON" : "OFF");
            fclose(log_file);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_TOUCH, PI_INPUT);
    gpioSetPullUpDown(GPIO_TOUCH, PI_PUD_DOWN);

    if (gpioSetISRFunc(GPIO_TOUCH, EITHER_EDGE, touch_callback, 0) < 0) {
        fprintf(stderr, "Failed to set ISR function for GPIO_TOUCH.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Press Ctrl+C to exit.\n");

    while (1) {
        if (gpioTick() % 1000 == 0) { // Every second
            printf("Relay state: %s\n", relay_state ? "ON" : "OFF");
        }
    }

    return EXIT_SUCCESS;
}

