#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpio"
#define GPIO_LINE_COUNT 4
#define GPIO_LINES[] {17, 23, 24, 25}
#define MOISTURE_THRESHOLD 30
#define RELAY_ACTIVATION_TIME 5
#define RELAY_DEACTIVATION_TIME 1
#define LOG_FILE "irrigation_log.txt"

gpiod_chip *chip;
gpiod_line *lines[GPIO_LINE_COUNT];

void handle_signal(int signum) {
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_set_value(lines[i], 1);
    }
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_put(chip);
    fclose(stdout);
    fclose(stderr);
    exit(signum);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open(GPIO_CHIP_NAME, 0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_put(chip);
        return 1;
    }

    srand(time(NULL));

    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        lines[i] = gpiod_line_request(chip, GPIO_LINES[i], "Relay", 0, GPIOD_LINE_DIRECTION_OUTPUT, 1);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_LINES[i]);
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_put(chip);
            fclose(log_file);
            return 1;
        }
    }

    while (1) {
        int moisture = rand() % 101;
        if (moisture < MOISTURE_THRESHOLD) {
            for (int i = 0; i < GPIO_LINE_COUNT; i++) {
                gpiod_line_set_value(lines[i], 0);
                fprintf(log_file, "%s\tRelay %d\tMoisture: %d\n", ctime(&time(NULL)), i + 1, moisture);
                fflush(log_file);
                sleep(RELAY_ACTIVATION_TIME);
                gpiod_line_set_value(lines[i], 1);
                sleep(RELAY_DEACTIVATION_TIME);
            }
        }
        sleep(10);
    }

    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_put(chip);
    fclose(log_file);

    return 0;
}

