                fprintf(log_file, "%s\tRelay %d\tMoisture: %d\n", ctime(&time(NULL)), i + 1, moisture);
                fflush(log_file);
                sleep(RELAY_ACTIVATION_TIME);
                gpiod_line_set_value(lines[i], 1);
                sleep(RELAY_DEACTIVATION_TIME);
            }
        }
        sleep(10);
    }

    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_put(chip);
    fclose(log_file);

    return 0;
}
