#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define SENSITIVITY 131.0
#define SAMPLE_RATE 1000000 / 10 // 10 Hz

int i2c_fd;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to acquire bus access/talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake the sensor
    uint8_t power_mgmt_1 = 0x00;
    if (write(i2c_fd, &power_mgmt_1, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1");
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint8_t data[6];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read gyroscope data");
            fclose(log_file);
            close(i2c_fd);
            return 1;
        }

        uint16_t x = (data[0] << 8) | data[1];
        uint16_t y = (data[2] << 8) | data[3];
        uint16_t z = (data[4] << 8) | data[5];

        double x_deg_per_sec = (double)x / SENSITIVITY;
        double y_deg_per_sec = (double)y / SENSITIVITY;
        double z_deg_per_sec = (double)z / SENSITIVITY;

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %f, %f, %f\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
                x_deg_per_sec, y_deg_per_sec, z_deg_per_sec);

        fflush(log_file);
        usleep(SAMPLE_RATE);
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

