#define LOCK_BUTTON_PIN 24
#define UNLOCK_BUTTON_PIN 23
#define STEP_DELAY_MS 3
#define FULL_STEP_COUNT 512

void rotate_clockwise() {
    for (int i = 0; i < FULL_STEP_COUNT; i++) {
        gpioWrite(4, 1);
        gpioWrite(17, 0);
        gpioWrite(27, 1);
        gpioWrite(22, 0);
        usleep(STEP_DELAY_MS * 1000);

        gpioWrite(4, 0);
        gpioWrite(17, 1);
        gpioWrite(27, 0);
