        gpioWrite(22, 0);
        usleep(STEP_DELAY_MS * 1000);

        gpioWrite(4, 0);
        gpioWrite(17, 1);
        gpioWrite(27, 0);
        gpioWrite(22, 1);
        usleep(STEP_DELAY_MS * 1000);
    }

    printf("Lock engaged (clockwise rotation)\n");
}

void rotate_counter_clockwise() {
    for (int i = 0; i < FULL_STEP_COUNT; i++) {
        gpioWrite(4, 0);
        gpioWrite(17, 1);
        gpioWrite(27, 0);
        gpioWrite(22, 1);
        usleep(STEP_DELAY_MS * 1000);

        gpioWrite(4, 1);
        gpioWrite(17, 0);
        gpioWrite(27, 1);
        gpioWrite(22, 0);
        usleep(STEP_DELAY_MS * 1000);

        gpioWrite(4, 0);
        gpioWrite(17, 1);
        gpioWrite(27, 0);
        gpioWrite(22, 1);
        usleep(STEP_DELAY_MS * 1000);

        gpioWrite(4, 1);
        gpioWrite(17, 0);
        gpioWrite(27, 1);
        gpioWrite(22, 0);
        usleep(STEP_DELAY_MS * 1000);
    }

    printf("Unlock engaged (counter-clockwise rotation)\n");
}

void handle_signal(int signum) {
    printf("Received SIGINT, de-energizing coils and terminating.\n");
    gpioWrite(4, 0);
    gpioWrite(17, 0);
    gpioWrite(27, 0);
    gpioWrite(22, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);

    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    gpioSetMode(4, PI_OUTPUT);
    gpioSetMode(17, PI_OUTPUT);
    gpioSetMode(27, PI_OUTPUT);
    gpioSetMode(22, PI_OUTPUT);

    signal(SIGINT, handle_signal);

    while (1) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            rotate_clockwise();
            usleep(500000); // Debounce delay
        }

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            rotate_counter_clockwise();
            usleep(500000); // Debounce delay
        }

        gpioWrite(4, 0);
        gpioWrite(17, 0);
        gpioWrite(27, 0);
        gpioWrite(22, 0);
    }

    return 0;
}

