#define MIN_GUARD_MS 60
#define TIMEOUT_MS 50
#define SPEED_OF_SOUND_CM_PER_US 0.01715

static gpiod_chip *chip;
static gpiod_line *trigger_line;
static gpiod_line *echo_line;
static FILE *log_file;

void cleanup(void) {
    if (trigger_line) {
        gpiod_line_free(trigger_line);
        trigger_line = NULL;
    }
    if (echo_line) {
        gpiod_line_free(echo_line);
        echo_line = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int main(void) {
    char filename[] = "distance_log.txt";
    log_file = fopen(filename, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    trigger_line = gpiod_line_request_any(chip, "trigger", GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!trigger_line) {
        fprintf(stderr, "Failed to request trigger GPIO line\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    echo_line = gpiod_line_request_any(chip, "echo", GPIOD_LINE_DIRECTION_INPUT, 0);
    if (!echo_line) {
        fprintf(stderr, "Failed to request echo GPIO line\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(trigger_line, 0);

    while (1) {
        gpiod_line_set_value(trigger_line, 1);
        usleep(10000); // 10 microsecond pulse
        gpiod_line_set_value(trigger_line, 0);

        unsigned long start_time = gpiod_line_get_value(echo_line);
        unsigned long end_time = start_time;
        unsigned long timeout_start = start_time + TIMEOUT_MS * 1000;

        while (gpiod_line_get_value(echo_line) == 0 && start_time < timeout_start) {
            start_time = gpiod_line_get_value(echo_line);
            usleep(1000); // 1 ms sleep
        }

        if (start_time >= timeout_start) {
            fprintf(log_file, "-1\n");
            fprintf(stderr, "Timeout occurred while waiting for echo rising edge\n");
            continue;
        }

        while (gpiod_line_get_value(echo_line) == 1 && end_time < timeout_start) {
            end_time = gpiod_line_get_value(echo_line);
            usleep(1000); // 1 ms sleep
        }

        if (end_time >= timeout_start) {
            fprintf(log_file, "-1\n");
            fprintf(stderr, "Timeout occurred while waiting for echo falling edge\n");
            continue;
        }

        unsigned long duration_us = end_time - start_time;
        double distance_cm = duration_us * SPEED_OF_SOUND_CM_PER_US;
        fprintf(log_file, "%.2f\n", distance_cm);

        usleep(MIN_GUARD_MS * 1000); // 60 ms guard
    }

    cleanup();
    fclose(log_file);
    return 0;
}
