#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_ADDR 0x68
#define I2C_DEV "/dev/i2c-1"

#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_DATA 0x43

#define FULL_SCALE_250DPS 0x00

#define LSB_PER_DPS 131.0

static int i2c_fd;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the sensor from sleep
    uint8_t pwr_mgmt_1 = 0x00;
    if (write(i2c_fd, &pwr_mgmt_1, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1 register");
        close(i2c_fd);
        return 1;
    }

    // Set gyroscope full-scale range to ±250 dps
    uint8_t gyro_config = FULL_SCALE_250DPS;
    if (write(i2c_fd, &gyro_config, 1) != 1) {
        perror("Failed to write to GYRO_CONFIG register");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint8_t data[6];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read gyroscope data");
            close(i2c_fd);
            return 1;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        double x_dps = (double)x / LSB_PER_DPS;
        double y_dps = (double)y / LSB_PER_DPS;
        double z_dps = (double)z / LSB_PER_DPS;

        printf("Gyro: x=%f, y=%f, z=%f (dps)\n", x_dps, y_dps, z_dps);

        usleep(100000); // Sleep for 100 ms
    }

    close(i2c_fd);
    return 0;
}

