#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_1 17
#define GPIO_LINE_2 18
#define GPIO_LINE_3 27
#define GPIO_LINE_4 22
#define POLL_INTERVAL 60
#define WATERING_INTERVAL 86400
#define WATERING_DURATION 5

static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];

void handle_signal(int signum) {
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_free(lines[i]);
        }
    }
    gpiod_chip_put(chip);
    exit(signum);
}

int main() {
    struct gpiod_line_request_flags flags = GPIOD_LINE_REQUEST_ACTIVE_LOW;
    struct gpiod_line_request req;
    struct gpiod_line_consumer consumer;
    struct gpiod_line_consumer_type consumer_type = GPIOD_LINE_CONSUMER_TYPE_USER;
    struct gpiod_line_consumer_user_data *consumer_data = NULL;
    struct gpiod_line_consumer_user_data_init init = {
        .type = consumer_type,
        .data = &consumer_data,
    };

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open(GPIO_CHIP, 0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        req.consumer = &init;
        req.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        req.flags = flags;
        req.consumer_user_data = &consumer_data;

        lines[i] = gpiod_line_request_by_index(chip, i, &req);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request GPIO line %d\n", i);
            for (int j = 0; j < i; j++) {
                gpiod_line_free(lines[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }

        gpiod_line_set_value(lines[i], 1); // Set to HIGH (inactive)
    }

    FILE *log_file = fopen("watering_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        for (int i = 0; i < 4; i++) {
            gpiod_line_free(lines[i]);
        }
        gpiod_chip_put(chip);
        return 1;
    }

    time_t start_time = time(NULL);
    struct tm *start_tm = localtime(&start_time);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d\n",
            start_tm->tm_year + 1900, start_tm->tm_mon + 1, start_tm->tm_mday,
            start_tm->tm_hour, start_tm->tm_min, start_tm->tm_sec);
    fclose(log_file);

    while (1) {
        time_t current_time = time(NULL);
        if (difftime(current_time, start_time) >= WATERING_INTERVAL) {
            for (int i = 0; i < 4; i++) {
                gpiod_line_set_value(lines[i], 0); // Set to LOW (active)
                sleep(WATERING_DURATION);
                gpiod_line_set_value(lines[i], 1); // Set back to HIGH (inactive)
            }
            start_time = current_time;

            log_file = fopen("watering_log.txt", "a");
            if (!log_file) {
                fprintf(stderr, "Failed to open log file\n");
                for (int i = 0; i < 4; i++) {
                    gpiod_line_free(lines[i]);
                }
                gpiod_chip_put(chip);
                return 1;
            }

            struct tm *current_tm = localtime(&current_time);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d\n",
                    current_tm->tm_year + 1900, current_tm->tm_mon + 1, current_tm->tm_mday,
                    current_tm->tm_hour, current_tm->tm_min, current_tm->tm_sec);
            fclose(log_file);
        }

        sleep(POLL_INTERVAL);
    }

    for (int i = 0; i < 4; i++) {
        gpiod_line_free(lines[i]);
    }
    gpiod_chip_put(chip);

    return 0;
}

