This C program uses the libgpiod v1 API to control four 5V relay modules on specified GPIO lines on a Raspberry Pi 4 Model B. It initializes the GPIO lines as outputs with active-low semantics, sets them to HIGH (inactive) at startup, and logs the start time of each watering cycle. The main loop activates each relay sequentially for 5 seconds every 24 hours, with a 60-second polling interval. It handles errors for libgpiod calls and file I/O operations, and installs a SIGINT/SIGTERM handler to release GPIO lines and close the chip on clean exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define RELAY_PINS[NUM_RELAYS] {17, 18, 27, 22}
#define PWM_FREQ 1000
#define MAX_DUTY_CYCLE 255
#define STEP_TIME 1000 // 1 second
#define LOG_FILE "smart_lighting.log"

volatile sig_atomic_t stop_flag = 0;

void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", buffer, event);
}

void handle_signal(int signum) {
    stop_flag = 1;
}

void setup_signal_handlers() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

void setup_gpios() {
    int i;
    for (i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(RELAY_PINS[i], PI_OUTPUT) < 0) {
            log_event("Failed to set GPIO mode for relay pin");
            exit(EXIT_FAILURE);
        }
    }
}

void setup_pwm() {
    int i;
    for (i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetPWMfrequency(RELAY_PINS[i], PWM_FREQ) < 0) {
            log_event("Failed to set PWM frequency for relay pin");
            exit(EXIT_FAILURE);
        }
        if (gpioPWM(RELAY_PINS[i], 0) < 0) {
            log_event("Failed to set initial PWM duty cycle for relay pin");
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_gpios() {
    int i;
    for (i = 0; i < NUM_RELAYS; i++) {
        if (gpioPWM(RELAY_PINS[i], 0) < 0) {
            log_event("Failed to set PWM duty cycle to 0 for relay pin");
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_event("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    setup_signal_handlers();
    setup_gpios();
    setup_pwm();

    int duty_cycle = 0;
    while (!stop_flag) {
        int i;
        for (i = 0; i < NUM_RELAYS; i++) {
            if (gpioPWM(RELAY_PINS[i], duty_cycle) < 0) {
                log_event("Failed to set PWM duty cycle for relay pin");
            }
        }
        duty_cycle = (duty_cycle + 1) % (MAX_DUTY_CYCLE + 1);
        sleep(STEP_TIME / 1000);
    }

    cleanup_gpios();
    gpioTerminate();

    return 0;
}

