#define I2C_BUS 1
#define I2C_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B

#define MAX_RETRIES 3
#define BUFFER_SIZE 100

typedef struct {
    int timestamp;
    float x, y, z;
} GyroData;

GyroData buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void handle_signal(int signum) {
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to re-open I2C bus after signal.\n");
    }
    gpioWrite(17, 0);
    gpioTerminate();
    exit(signum);
}

void init_sensor() {
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        exit(1);
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteReg(I2C_BUS, I2C_ADDR, PWR_MGMT_1, 0x00) < 0) {
            fprintf(stderr, "Failed to write to PWR_MGMT_1 register.\n");
            retries++;
            continue;
        }

        if (i2cReadReg(I2C_BUS, I2C_ADDR, SMPLRT_DIV, 1) < 0) {
            fprintf(stderr, "Failed to write to SMPLRT_DIV register.\n");
            retries++;
            continue;
        }

        if (i2cWriteReg(I2C_BUS, I2C_ADDR, SMPLRT_DIV, 0x07) < 0) {
            fprintf(stderr, "Failed to write to SMPLRT_DIV register.\n");
            retries++;
            continue;
        }

        if (i2cWriteReg(I2C_BUS, I2C_ADDR, GYRO_CONFIG, 0x00) < 0) {
            fprintf(stderr, "Failed to write to GYRO_CONFIG register.\n");
            retries++;
            continue;
        }

        if (i2cReadReg(I2C_BUS, I2C_ADDR, WHO_AM_I, 1) != 0x68) {
            fprintf(stderr, "Failed to verify WHO_AM_I register.\n");
            retries++;
            continue;
        }

        break;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize sensor after %d retries.\n", MAX_RETRIES);
        exit(1);
    }
}

void read_gyro_data() {
    int data[6];
    if (i2cReadReg(I2C_BUS, I2C_ADDR, GYRO_XOUT_H, 6) < 0) {
        fprintf(stderr, "Failed to read gyroscope data.\n");
        return;
    }

    float x = ((data[0] << 8) | data[1]) * 131.0f;
    float y = ((data[2] << 8) | data[3]) * 131.0f;
    float z = ((data[4] << 8) | data[5]) * 131.0f;

    buffer[buffer_head].timestamp = time(NULL);
    buffer[buffer_head].x = x;
    buffer[buffer_head].y = y;
    buffer[buffer_head].z = z;

    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    if (buffer_head == buffer_tail) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    }

    int led_state = (abs(x) > 250 || abs(y) > 250 || abs(z) > 250) ? 1 : 0;
    if (led_state != gpioRead(17)) {
        gpioWrite(17, led_state);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as output.\n");
        return 1;
    }

    init_sensor();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_gyro_data();
        usleep(50000); // 50 ms delay for 20 Hz sampling
    }

    return 0;
}

