#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>

#define SPI_DEV "/dev/spidev0.0"
#define CS_LINE "/dev/gpiochip0"
#define CS_LINE_OFFSET 8
#define GYRO_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define GYRO_ZOUT_L 0x48
#define SCALE_FACTOR 131.0
#define BUFFER_SIZE 6
#define MAX_RETRIES 3

int spi_fd;
struct gpiod_line *cs_line;
FILE *log_file;

int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    int ret = 0;
    for (int i = 0; i < MAX_RETRIES; i++) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret < 1) {
            if (i == MAX_RETRIES - 1) {
                fprintf(stderr, "SPI transfer failed: %d\n", ret);
            }
            usleep(10000); // 10 ms delay
        } else {
            break;
        }
    }
    return ret;
}

void read_gyro_data(uint8_t *data) {
    uint8_t tx_buf[1] = {GYRO_XOUT_H};
    spi_transfer(tx_buf, data, BUFFER_SIZE);
}

void convert_to_dps(int16_t *data) {
    for (int i = 0; i < 3; i++) {
        data[i] = (int16_t)((data[i] << 8) | data[i + 1]);
        data[i] = (int16_t)((data[i] * SCALE_FACTOR) / 32768.0);
    }
}

void log_data(const char *timestamp, int16_t *data) {
    char buffer[100];
    snprintf(buffer, sizeof(buffer), "%s,%d,%d,%d\n", timestamp, data[0], data[1], data[2]);
    if (fputs(buffer, log_file) == EOF) {
        perror("Failed to write to log file");
    }
}

void cleanup() {
    gpiod_line_free(cs_line);
    close(spi_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    int spi_ret;
    int cs_ret;

    // Open SPI device
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Configure SPI
    spi_ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &0);
    if (spi_ret < 0) {
        perror("Failed to set SPI mode");
        goto spi_cleanup;
    }
    spi_ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8);
    if (spi_ret < 0) {
        perror("Failed to set bits per word");
        goto spi_cleanup;
    }
    spi_ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &1000000);
    if (spi_ret < 0) {
        perror("Failed to set SPI speed");
        goto spi_cleanup;
    }

    // Open GPIO chip and line
    cs_line = gpiod_line_request(CS_LINE, CS_LINE_OFFSET, "CS_LINE", 0);
    if (!cs_line) {
        perror("Failed to request GPIO line");
        goto spi_cleanup;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cs_cleanup;
    }

    // Main loop
    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%N", gmtime(&ts.tv_sec));

        // Assert chip select
        cs_ret = gpiod_line_set_value(cs_line, 0);
        if (cs_ret < 0) {
            perror("Failed to set GPIO line value");
            goto log_cleanup;
        }

        uint8_t data[BUFFER_SIZE];
        read_gyro_data(data);

        // Deassert chip select
        cs_ret = gpiod_line_set_value(cs_line, 1);
        if (cs_ret < 0) {
            perror("Failed to set GPIO line value");
            goto log_cleanup;
        }

        int16_t gyro_data[3];
        memcpy(gyro_data, data, sizeof(gyro_data));
        convert_to_dps(gyro_data);

        log_data(timestamp, gyro_data);

        usleep(10000); // 10 ms delay
    }

log_cleanup:
    fclose(log_file);
cs_cleanup:
    gpiod_line_free(cs_line);
spi_cleanup:
    close(spi_fd);
    return 1;
}

