#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <spidev.h>

#define BUFFER_SIZE 64
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define SPI_DEV "/dev/spidev0.0"
#define GPIO_CE0 8
#define GPIO_LED 17

struct reading {
    time_t timestamp;
    int16_t x, y, z;
};

struct reading buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

gpiod_chip *chip;
gpiod_line *ce0_line;

spidev_dev *spi;

void handle_sigint(int signum) {
    printf("SIGINT received, printing buffer and exiting...\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%ld,%d,%d,%d\n", buffer[i].timestamp, buffer[i].x, buffer[i].y, buffer[i].z);
    }
    gpiod_line_free(ce0_line);
    gpiod_chip_put(chip);
    spidev_close(spi);
    exit(0);
}

void blink_led(int on_ms, int off_ms) {
    gpiod_line_set_value(ce0_line, 1); // Turn on LED
    usleep(on_ms * 1000);
    gpiod_line_set_value(ce0_line, 0); // Turn off LED
    usleep(off_ms * 1000);
}

int read_sensor() {
    uint8_t data[3];
    int ret;

    ret = spidev_read(spi, data, 3, SPI_SPEED, SPI_MODE);
    if (ret != 3) {
        fprintf(stderr, "Error reading from SPI: %d\n", ret);
        return -1;
    }

    buffer[buffer_head].x = (data[0] << 8) | data[1];
    buffer[buffer_head].y = (data[2] << 8) | data[3];
    buffer[buffer_head].z = (data[4] << 8) | data[5];

    buffer[buffer_head].timestamp = time(NULL);

    if (buffer[buffer_head].x > 200 || buffer[buffer_head].x < -200 ||
        buffer[buffer_head].y > 200 || buffer[buffer_head].y < -200 ||
        buffer[buffer_head].z > 200 || buffer[buffer_head].z < -200) {
        blink_led(500, 500);
    }

    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_head == buffer_tail) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    ce0_line = gpiod_line_request_any(chip, "CE0", GPIO_CE0, "MPU-6050 CS", 0);
    if (!ce0_line) {
        fprintf(stderr, "Failed to request GPIO line for CE0\n");
        gpiod_chip_put(chip);
        return 1;
    }

    spi = spidev_open(SPI_DEV, 0);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_line_free(ce0_line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (spidev_write(spi, "\x00", 1, SPI_SPEED, SPI_MODE) != 1) {
        fprintf(stderr, "Failed to write to SPI\n");
        spidev_close(spi);
        gpiod_line_free(ce0_line);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        gpiod_line_set_value(ce0_line, 1); // Assert CE0
        if (read_sensor() < 0) {
            break;
        }
        gpiod_line_set_value(ce0_line, 0); // Deassert CE0
        usleep(100000); // 100 ms delay
    }

    return 0;
}

