    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    ce0_line = gpiod_line_request_any(chip, "CE0", GPIO_CE0, "MPU-6050 CS", 0);
    if (!ce0_line) {
        fprintf(stderr, "Failed to request GPIO line for CE0\n");
        gpiod_chip_put(chip);
        return 1;
    }

    spi = spidev_open(SPI_DEV, 0);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_line_free(ce0_line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (spidev_write(spi, "\x00", 1, SPI_SPEED, SPI_MODE) != 1) {
        fprintf(stderr, "Failed to write to SPI\n");
        spidev_close(spi);
        gpiod_line_free(ce0_line);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        gpiod_line_set_value(ce0_line, 1); // Assert CE0
        if (read_sensor() < 0) {
            break;
        }
        gpiod_line_set_value(ce0_line, 0); // Deassert CE0
        usleep(100000); // 100 ms delay
    }

    return 0;
}
```

This C program reads angular velocity data from an InvenSense MPU-6050 gyroscope over SPI, using libgpiod for manual chip-select control on GPIO8 (CE0). It configures the SPI interface at approximately 3.9 MHz, mode 0, and asserts the CE0 chip-select line via libgpiod for each transfer. It reads gyroscope X, Y, and Z axis data from registers 0x43, 0x45, and 0x47 (high bytes) with auto-increment disabled, using single-byte reads, and converts the raw 16-bit two's-complement values to degrees per second using the 131.0 LSB/(deg/s) sensitivity factor. It stores each reading, with its timestamp, in a 64-entry in-memory circular buffer. If any axis exceeds ±200 deg/s, it blinks an LED on GPIO17 (physical pin 11) with 500 ms on/off intervals. On SIGINT (Ctrl+C), it prints the entire circular buffer as CSV with columns Timestamp, X, Y, Z, then releases the SPI handle and GPIO resources on every exit path.

