#define ACCEL_CONFIG 0x1C
#define ACCEL_DATA_XOUT_H 0x3B
#define ACCEL_DATA_XOUT_L 0x3C
#define ACCEL_DATA_YOUT_H 0x3D
#define ACCEL_DATA_YOUT_L 0x3E
#define ACCEL_DATA_ZOUT_H 0x3F
#define ACCEL_DATA_ZOUT_L 0x40
#define LED_PIN 21
#define LOG_FILE "tilt_log.txt"

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

void write_register(int handle, int reg, int value) {
    if (i2c_write_device(handle, &reg, 1) < 0) {
        fprintf(stderr, "Failed to write register address\n");
        return;
    }
    if (i2c_write_device(handle, &value, 1) < 0) {
        fprintf(stderr, "Failed to write register value\n");
        return;
    }
}

void read_registers(int handle, int reg, uint8_t *data, int len) {
    if (i2c_read_device(handle, &reg, 1) < 0) {
        fprintf(stderr, "Failed to read register address\n");
        return;
    }
    if (i2c_read_device(handle, data, len) < 0) {
        fprintf(stderr, "Failed to read register data\n");
        return;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    write_register(handle, PWR_MGMT_1, 0x00); // Wake sensor
    write_register(handle, ACCEL_CONFIG, 0x00); // Set accelerometer full-scale range to ±2g

    signal(SIGINT, handle_sigint);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        uint8_t data[6];
        read_registers(handle, ACCEL_DATA_XOUT_H, data, 6);

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        double roll = atan2(y, z) * 180.0 / M_PI;
        double pitch = atan2(-x, sqrt(y * y + z * z)) * 180.0 / M_PI;

        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

        if (abs(roll) > 45 || abs(pitch) > 45) {
            gpioWrite(LED_PIN, PI_ON);
        } else {
            gpioWrite(LED_PIN, PI_OFF);
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, roll, pitch);

        usleep(100000); // 100 ms delay
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

