#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <gpiod.h>

#define I2C_ADDR 0x5A
#define I2C_DEV "/dev/i2c-1"
#define GPIO_LINE "gpio17"
#define LOG_FILE "biometric_log.txt"
#define RETRIES 3
#define DELAY_BETWEEN_ATTEMPTS 10

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    int retries = 0;
    while (retries < RETRIES) {
        if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
            perror("I2C_SLAVE");
            return -1;
        }
        if (write(fd, &reg, 1) != 1) {
            perror("write");
            return -1;
        }
        if (read(fd, data, len) != len) {
            perror("read");
            return -1;
        }
        return 0;
    }
    return -1;
}

int main() {
    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    struct gpiod_line *line;
    if (gpiod_line_open(GPIO_LINE, &line) < 0) {
        perror("gpiod_line_open");
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_close(line);
        close(i2c_fd);
        return 1;
    }

    uint8_t ambient_light[2];
    uint8_t proximity[2];

    while (1) {
        if (i2c_read(i2c_fd, 0x20, ambient_light, 2) < 0 ||
            i2c_read(i2c_fd, 0x22, proximity, 2) < 0) {
            perror("i2c_read");
            continue;
        }

        uint16_t ambient_light_value = (ambient_light[1] << 8) | ambient_light[0];
        uint16_t proximity_value = (proximity[1] << 8) | proximity[0];

        struct tm *time_info = localtime(&time(NULL));
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", time_info);

        fprintf(log_file, "%sAmbientLight:%04X,Proximity:%04X\n", timestamp, ambient_light_value, proximity_value);

        if (proximity_value > 100) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        usleep(100000); // 100 ms delay
    }

    fclose(log_file);
    gpiod_line_close(line);
    close(i2c_fd);

    return 0;
}

