#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GYRO_ADDR_X 0x02
#define GYRO_ADDR_Y 0x04
#define GYRO_READ_BIT 0x80
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_TIMEOUT 1000
#define MAX_RETRIES 3

int spi_fd = -1;
FILE *file = NULL;

void handle_sigint(int signum) {
    if (spi_fd != -1) {
        spiClose(spi_fd);
    }
    if (file != NULL) {
        fclose(file);
    }
    gpioTerminate();
    exit(0);
}

int read_gyro_data(int axis_addr, int *data) {
    uint8_t buffer[2];
    buffer[0] = axis_addr | GYRO_READ_BIT;
    buffer[1] = 0;

    if (spiXfer(spi_fd, buffer, 2, buffer, 2, SPI_TIMEOUT) != 2) {
        return -1;
    }

    *data = (buffer[0] << 8) | buffer[1];
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    file = fopen("gyro_data.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    fprintf(file, "timestamp,X rate,Y rate\n");

    struct timespec ts;
    int retries = 0;
    int x_rate, y_rate;

    signal(SIGINT, handle_sigint);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);

        if (read_gyro_data(GYRO_ADDR_X, &x_rate) < 0) {
            if (retries < MAX_RETRIES) {
                retries++;
                continue;
            } else {
                fprintf(stderr, "Failed to read X axis data after %d retries\n", MAX_RETRIES);
                break;
            }
        }

        if (read_gyro_data(GYRO_ADDR_Y, &y_rate) < 0) {
            if (retries < MAX_RETRIES) {
                retries++;
                continue;
            } else {
                fprintf(stderr, "Failed to read Y axis data after %d retries\n", MAX_RETRIES);
                break;
            }
        }

        retries = 0;

        fprintf(file, "%ld.%06ld,%d,%d\n", (long)ts.tv_sec, (long)ts.tv_nsec / 1000, x_rate, y_rate);

        usleep(10000); // 10 ms delay
    }

    fclose(file);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

