#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define ALERT_PIN 17
#define SENSOR1_PIN 23
##define SENSOR2_PIN 24
#define LOG_FILE "seismic_events.txt"
#define ALERT_DURATION 2000 // 2 seconds
#define DETECTION_THRESHOLD 500 // 500 milliseconds

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s - %s\n", buffer, message);
    fclose(log_file);
}

void sensor_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        static uint32_t last_high_tick = 0;
        static uint32_t high_count = 0;

        if (stop) {
            return;
        }

        if (tick - last_high_tick >= DETECTION_THRESHOLD) {
            high_count = 0;
        }

        last_high_tick = tick;
        high_count++;

        if (high_count >= 2) {
            log_event("Seismic event detected!");
            gpioWrite(ALERT_PIN, 1);
            usleep(ALERT_DURATION * 1000); // Sleep for 2 seconds
            gpioWrite(ALERT_PIN, 0);
        }
    }
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0);

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    if (gpioSetAlertFunc(SENSOR1_PIN, sensor_callback) < 0 ||
        gpioSetAlertFunc(SENSOR2_PIN, sensor_callback) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        usleep(100000); // Sleep for 100 milliseconds
    }

    gpioTerminate();
    return 0;
}
```

This C program uses the pigpio library to monitor two tilt sensors connected to GPIO23 and GPIO24 on a Raspberry Pi 3 Model B+. It sets up edge-triggered callbacks for both rising and falling edges on each sensor. When both sensors read HIGH for at least 500 milliseconds, it triggers an alert by setting GPIO17 HIGH for 2 seconds. The program logs each seismic event to `seismic_events.txt` with an ISO-8601-style timestamp and handles SIGINT/SIGTERM signals to clean up and terminate gracefully.

