#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define THRESHOLD 20.0
#define SPI_CLK 1000000
#define SPI_MODE 0
#define SPI_CE GPIO_8
#define SPI_SCLK GPIO_11
#define SPI_MOSI GPIO_10
#define SPI_MISO GPIO_9
#define LED GPIO_17

typedef struct {
    double rate;
    struct timespec timestamp;
} GyroReading;

GyroReading buffer[BUFFER_SIZE];
int head = 0;
int tail = 0;

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    spi_close(spi_handle);
    gpio_write(LED, 0);
    pigpio_stop();
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, cleaning up...\n");
    spi_close(spi_handle);
    gpio_write(LED, 0);
    pigpio_stop();
    exit(0);
}

double read_gyro_rate() {
    uint8_t addr[2] = {0x02 | 0x80, 0x03 | 0x80};
    uint8_t data[2];
    int ret;

    ret = spi_read(spi_handle, addr, data, 2);
    if (ret != 2) {
        printf("Error reading from SPI: %d\n", ret);
        return 0.0;
    }

    int16_t rate_x = (data[0] << 8) | data[1];
    return (double)rate_x / 200.0;
}

void update_buffer(double rate) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    buffer[head].rate = rate;
    buffer[head].timestamp = now;

    head = (head + 1) % BUFFER_SIZE;
    if (head == tail) {
        tail = (tail + 1) % BUFFER_SIZE;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(LED, PI_OUTPUT) < 0) {
        printf("Failed to set LED GPIO mode\n");
        return 1;
    }

    spi_handle = spi_open(SPI_CE, SPI_CLK, SPI_MODE, 0);
    if (spi_handle < 0) {
        printf("Failed to open SPI\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        double rate = read_gyro_rate();
        update_buffer(rate);

        if (abs(rate) > THRESHOLD) {
            if (gpio_write(LED, 1) < 0) {
                printf("Failed to turn on LED\n");
            }
        } else {
            if (gpio_write(LED, 0) < 0) {
                printf("Failed to turn off LED\n");
            }
        }

        sleep(1);
    }

    spi_close(spi_handle);
    gpio_write(LED, 0);
    pigpio_stop();

    return 0;
}

