#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_LAMPS 3
#define GPIO_PINS[NUM_LAMPS] {17, 18, 27}
#define PWM_FREQUENCY 100
#define PWM_RANGE 255

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

void fade_lamp(int lamp_index, int duration) {
    int start_duty = PWM_RANGE;
    int end_duty = 0;
    int step = (start_duty - end_duty) / duration;

    printf("Fading lamp %d...\n", lamp_index + 1);

    for (int i = 0; i <= duration; i++) {
        if (stop) {
            printf("Terminated. Stopping lamp %d.\n", lamp_index + 1);
            break;
        }

        int duty = start_duty - (i * step);
        gpioPWM(GPIO_PINS[lamp_index], duty);

        usleep(1000000 / PWM_FREQUENCY); // Sleep for 1/PWM_FREQUENCY seconds
    }

    printf("Lamp %d faded to off.\n", lamp_index + 1);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_in_seconds>\n", argv[0]);
        return 1;
    }

    int duration = atoi(argv[1]);
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration. Must be between 1 and 3600 seconds.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    printf("Starting sunset simulator with duration %d seconds.\n", duration);

    for (int i = 0; i < NUM_LAMPS; i++) {
        if (stop) {
            printf("Terminated. Stopping all lamps.\n");
            break;
        }

        gpioSetMode(GPIO_PINS[i], PI_OUTPUT);
        gpioSetPWMfrequency(GPIO_PINS[i], PWM_FREQUENCY);
        gpioSetPWMrange(GPIO_PINS[i], PWM_RANGE);
        gpioPWM(GPIO_PINS[i], PWM_RANGE);

        fade_lamp(i, duration);
    }

    for (int i = 0; i < NUM_LAMPS; i++) {
        gpioPWM(GPIO_PINS[i], 0);
    }

    printf("Sunset simulator completed.\n");

    gpioTerminate();
    return 0;
}

