#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_GPIO 17
#define YELLOW_GPIO 22
#define GREEN_GPIO 23
#define YELLOW_GPIO_2 24

static gpiod_chip *chip;
static gpiod_line *red_line, *yellow_line, *green_line, *yellow_line_2;

void signal_handler(int signum) {
    if (red_line) {
        gpiod_line_request_release(red_line);
        gpiod_line_free(red_line);
    }
    if (yellow_line) {
        gpiod_line_request_release(yellow_line);
        gpiod_line_free(yellow_line);
    }
    if (green_line) {
        gpiod_line_request_release(green_line);
        gpiod_line_free(green_line);
    }
    if (yellow_line_2) {
        gpiod_line_request_release(yellow_line_2);
        gpiod_line_free(yellow_line_2);
    }
    gpiod_chip_put(chip);
    exit(signum);
}

int main() {
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO lines
    red_line = gpiod_line_request(chip, RED_GPIO, "red_light", 0);
    if (!red_line) {
        fprintf(stderr, "Failed to request GPIO line for red light\n");
        goto error_red;
    }

    yellow_line = gpiod_line_request(chip, YELLOW_GPIO, "yellow_light", 0);
    if (!yellow_line) {
        fprintf(stderr, "Failed to request GPIO line for yellow light\n");
        goto error_yellow;
    }

    green_line = gpiod_line_request(chip, GREEN_GPIO, "green_light", 0);
    if (!green_line) {
        fprintf(stderr, "Failed to request GPIO line for green light\n");
        goto error_green;
    }

    yellow_line_2 = gpiod_line_request(chip, YELLOW_GPIO_2, "yellow_light_2", 0);
    if (!yellow_line_2) {
        fprintf(stderr, "Failed to request GPIO line for yellow light 2\n");
        goto error_yellow_2;
    }

    // Set initial state
    gpiod_line_set_value(red_line, 1);
    gpiod_line_set_value(yellow_line, 1);
    gpiod_line_set_value(green_line, 1);
    gpiod_line_set_value(yellow_line_2, 1);

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Red light
        gpiod_line_set_value(red_line, 0);
        gpiod_line_set_value(yellow_line, 1);
        gpiod_line_set_value(green_line, 1);
        gpiod_line_set_value(yellow_line_2, 1);
        printf("Red light ON\n");
        sleep(10);

        // Red + Yellow light
        gpiod_line_set_value(red_line, 0);
        gpiod_line_set_value(yellow_line, 0);
        gpiod_line_set_value(green_line, 1);
        gpiod_line_set_value(yellow_line_2, 1);
        printf("Red + Yellow light ON\n");
        sleep(2);

        // Green light
        gpiod_line_set_value(red_line, 1);
        gpiod_line_set_value(yellow_line, 1);
        gpiod_line_set_value(green_line, 0);
        gpiod_line_set_value(yellow_line_2, 1);
        printf("Green light ON\n");
        sleep(10);

        // Yellow light
        gpiod_line_set_value(red_line, 1);
        gpiod_line_set_value(yellow_line, 0);
        gpiod_line_set_value(green_line, 1);
        gpiod_line_set_value(yellow_line_2, 0);
        printf("Yellow light ON\n");
        sleep(3);
    }

    // Cleanup
    return 0;

error_yellow_2:
    gpiod_line_request_release(green_line);
error_green:
    gpiod_line_request_release(yellow_line);
error_yellow:
    gpiod_line_request_release(red_line);
error_red:
    gpiod_chip_put(chip);
    return 1;
}

