#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define GPIO_PIN 17
#define LOG_FILE "touch_relay.log"

int i2c_fd;

void log_error(const char *msg) {
    time_t now;
    struct tm *now_tm;
    char time_str[32];

    time(&now);
    now_tm = localtime(&now);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", now_tm);

    fprintf(stderr, "%s: %s\n", time_str, msg);
}

void handle_sig(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpioInitialise() < 0) {
        log_error("Failed to close GPIO");
    }
    exit(signum);
}

int main() {
    int status, touch_status;
    char buf[2];
    int i2c_err;

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO mode");
        return 1;
    }

    if (gpioWrite(GPIO_PIN, PI_LOW) < 0) {
        log_error("Failed to set GPIO initial state");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
