#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define DEBOUNCE_INTERVAL 50 // milliseconds
#define LOG_FILE "flame_log.txt"

static gpiod_chip *chip;
static gpiod_line *flame_sensor, *buzzer, *led;
static FILE *log_file;

void handle_sigint(int signum) {
    gpiod_line_request_free(flame_sensor);
    gpiod_line_request_free(buzzer);
    gpiod_line_request_free(led);
    gpiod_chip_put(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if ((flame_sensor = gpiod_line_request_by_name(chip, "gpio%d", FLAME_SENSOR_PIN)) == NULL) {
        perror("Failed to request flame sensor line");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    if ((buzzer = gpiod_line_request_by_name(chip, "gpio%d", BUZZER_PIN)) == NULL) {
        perror("Failed to request buzzer line");
        gpiod_line_request_free(flame_sensor);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    if ((led = gpiod_line_request_by_name(chip, "gpio%d", LED_PIN)) == NULL) {
        perror("Failed to request LED line");
        gpiod_line_request_free(flame_sensor);
        gpiod_line_request_free(buzzer);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_direction_set(flame_sensor, GPIOD_LINE_DIRECTION_INPUT) < 0) {
        perror("Failed to set flame sensor direction");
        gpiod_line_request_free(flame_sensor);
        gpiod_line_request_free(buzzer);
        gpiod_line_request_free(led);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_direction_set(buzzer, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        perror("Failed to set buzzer direction");
        gpiod_line_request_free(flame_sensor);
        gpiod_line_request_free(buzzer);
        gpiod_line_request_free(led);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_direction_set(led, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        perror("Failed to set LED direction");
        gpiod_line_request_free(flame_sensor);
        gpiod_line_request_free(buzzer);
        gpiod_line_request_free(led);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        gpiod_line_request_free(flame_sensor);
        gpiod_line_request_free(buzzer);
        gpiod_line_request_free(led);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    while (1) {
        int flame_detected = 0;
        for (int i = 0; i < 3; i++) {
            if (gpiod_line_get_value(flame_sensor) == 0) {
                flame_detected = 1;
                break;
            }
            usleep(DEBOUNCE_INTERVAL * 1000);
        }

        if (flame_detected) {
            gpiod_line_set_value(buzzer, 1);
            gpiod_line_set_value(led, 1);
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            fprintf(log_file, "%02d:%02d:%02d Flame Detected\n", now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec);
            fflush(log_file);
        } else {
            gpiod_line_set_value(buzzer, 0);
            gpiod_line_set_value(led, 0);
        }

        usleep(DEBOUNCE_INTERVAL * 1000);
    }

    fclose(log_file);
    gpiod_line_request_free(flame_sensor);
    gpiod_line_request_free(buzzer);
    gpiod_line_request_free(led);
    gpiod_chip_put(chip);

    return 0;
}

