#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define SOLENOID_1 17
#define SOLENOID_2 27
#define DELAY_MS 1000
#define DELAY_BETWEEN_CYCLES_MS 5000
#define LOG_FILE "dispense_log.txt"

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return -1;
    }
    return 0;
}

int setup_gpios() {
    if (gpioSetMode(SOLENOID_1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output.\n", SOLENOID_1);
        return -1;
    }
    if (gpioSetMode(SOLENOID_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output.\n", SOLENOID_2);
        return -1;
    }
    return 0;
}

int dispense_cycle() {
    if (gpioWrite(SOLENOID_1, PI_ON) < 0) {
        fprintf(stderr, "Failed to activate solenoid 1.\n");
        return -1;
    }
    gpioDelay(DELAY_MS * 500); // 500 ms
    if (gpioWrite(SOLENOID_1, PI_OFF) < 0) {
        fprintf(stderr, "Failed to deactivate solenoid 1.\n");
        return -1;
    }
    if (gpioWrite(SOLENOID_2, PI_ON) < 0) {
        fprintf(stderr, "Failed to activate solenoid 2.\n");
        return -1;
    }
    gpioDelay(DELAY_MS * 500); // 500 ms
    if (gpioWrite(SOLENOID_2, PI_OFF) < 0) {
        fprintf(stderr, "Failed to deactivate solenoid 2.\n");
        return -1;
    }
    return 0;
}

int log_dispense_event(const char *event_message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        return -1;
    }
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    fprintf(log_file, "%s %s\n", asctime(timeinfo), event_message);
    fclose(log_file);
    return 0;
}

int main() {
    if (init_pigpio() < 0) {
        return 1;
    }
    if (setup_gpios() < 0) {
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!stop) {
        if (dispense_cycle() < 0) {
            return 1;
        }
        log_dispense_event("Dispense cycle completed");
        gpioDelay(DELAY_BETWEEN_CYCLES_MS * 1000); // 5 seconds
    }

    gpioWrite(SOLENOID_1, PI_OFF);
    gpioWrite(SOLENOID_2, PI_OFF);
    gpioTerminate();

    return 0;
}

