#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25
#define PID_KP 1.0
#define PID_KI 0.01
#define PID_KD 0.1
#define PID_DT 0.05
#define OBSTACLE_DISTANCE 20.0
#define OBSTACLE_SPEED 128
#define MAX_SPEED 255

FILE *log_file;

void pid_controller(float tilt_error, float *motor_a_speed, float *motor_b_speed) {
    static float prev_error = 0.0;
    static float integral = 0.0;
    float derivative = (tilt_error - prev_error) / PID_DT;
    integral += tilt_error * PID_DT;
    *motor_a_speed = PID_KP * tilt_error + PID_KI * integral + PID_KD * derivative;
    *motor_b_speed = *motor_a_speed;
    prev_error = tilt_error;
}

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    gpioWrite(ENA, 0);
    gpioWrite(ENB, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
