#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

volatile sig_atomic_t running = 1;

void handle_interrupt(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for touch sensor.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor for touch sensor.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetAlertFunc(TOUCH_SENSOR_PIN, &handle_touch) < 0) {
        fprintf(stderr, "Failed to set alert function for touch sensor.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void handle_touch(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        gpioDelay(50000); // Debounce delay of 50 ms
        if (gpioRead(TOUCH_SENSOR_PIN) == 1) {
            int relay_state = gpioRead(RELAY_PIN);
            if (relay_state == 0) {
                if (gpioWrite(RELAY_PIN, 1) < 0) {
                    fprintf(stderr, "Failed to toggle relay to ON.\n");
                }
            } else {
                if (gpioWrite(RELAY_PIN, 0) < 0) {
                    fprintf(stderr, "Failed to toggle relay to OFF.\n");
                }
            }
        }
    }
}

int main() {
    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    setup_gpio();

    while (running) {
        gpioSleep(1000000); // Sleep for 1 second
    }

    gpioTerminate();
    return 0;
}

