#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

#define ALSA_AVAILABLE 1

#define DEFAULT_SENSITIVITY 1.0
#define UPDATE_INTERVAL 10000 // 10 ms

static snd_pcm_t *pcm;
static int pcm_state;

static void cleanup_alsa(void) {
    if (pcm_state != -EPIPE) {
        snd_pcm_drain(pcm);
        snd_pcm_close(pcm);
    }
    snd_pcm_free(pcm);
}

static void cleanup_pigpio(void) {
    gpioTerminate();
}

static void cleanup(int signum) {
    cleanup_alsa();
    cleanup_pigpio();
    exit(signum);
}

static void handle_signal(int signum) {
    signal(signum, SIG_IGN);
    cleanup(signum);
}

static void update_led(float amplitude) {
    float scaled_amplitude = amplitude * DEFAULT_SENSITIVITY;
    int red, green, blue;

    if (scaled_amplitude < 0.25) {
        red = 0;
        green = 0;
        blue = 255;
    } else if (scaled_amplitude < 0.5) {
        red = 0;
        green = (int)(255 * (scaled_amplitude - 0.25) / 0.25);
        blue = 255 - (int)(255 * (scaled_amplitude - 0.25) / 0.25);
    } else if (scaled_amplitude < 0.75) {
        red = (int)(255 * (scaled_amplitude - 0.5) / 0.25);
        green = 255;
        blue = 0;
    } else {
        red = 255;
        green = 255 - (int)(255 * (scaled_amplitude - 0.75) / 0.25);
        blue = 0;
    }

    gpioPWM(17, red);
    gpioPWM(18, green);
    gpioPWM(27, blue);
}

static void process_audio(void) {
    snd_pcm_sframes_t frames_read;
    snd_pcm_uframes_t frames_per_period = 1024;
    snd_pcm_uframes_t frames_per_buffer = frames_per_period * 2;
    short *buffer = malloc(frames_per_buffer * sizeof(short));

    if (!buffer) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    while (1) {
        frames_read = snd_pcm_readi(pcm, buffer, frames_per_buffer);

        if (frames_read < 0) {
            if (frames_read == -EPIPE) {
                snd_pcm_prepare(pcm);
                continue;
            } else if (frames_read == -ESTRPIPE) {
                snd_pcm_resume(pcm);
                continue;
            } else {
                perror("snd_pcm_readi");
                cleanup_alsa();
                cleanup_pigpio();
                exit(EXIT_FAILURE);
            }
        }

        float sum_squares = 0.0;
        for (int i = 0; i < frames_read; i++) {
            sum_squares += buffer[i] * buffer[i];
        }

        float amplitude = sqrt(sum_squares / frames_read);
        update_led(amplitude);

        usleep(UPDATE_INTERVAL);
    }

    free(buffer);
}

int main(int argc, char *argv[]) {
    double sensitivity = DEFAULT_SENSITIVITY;

    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0.0) {
            fprintf(stderr, "Sensitivity must be positive.\n");
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return EXIT_FAILURE;
    }

    gpioSetMode(17, PI_OUTPUT);
    gpioSetMode(18, PI_OUTPUT);
    gpioSetMode(27, PI_OUTPUT);

    if (ALSA_AVAILABLE) {
        int err;
        snd_pcm_hw_params_t *hw_params;
        snd_pcm_sw_params_t *sw_params;

        err = snd_pcm_open(&pcm, "default", SND_PCM_STREAM_CAPTURE, 0);
        if (err < 0) {
            perror("snd_pcm_open");
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_hw_params_malloc(&hw_params);
        if (err < 0) {
            perror("snd_pcm_hw_params_malloc");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_sw_params_malloc(&sw_params);
        if (err < 0) {
            perror("snd_pcm_sw_params_malloc");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_hw_params_any(pcm, hw_params);
        if (err < 0) {
            perror("snd_pcm_hw_params_any");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_hw_params_set_access(pcm, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
        if (err < 0) {
            perror("snd_pcm_hw_params_set_access");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_hw_params_set_format(pcm, hw_params, SND_PCM_FORMAT_S16_LE);
        if (err < 0) {
            perror("snd_pcm_hw_params_set_format");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_hw_params_set_channels(pcm, hw_params, 1);
        if (err < 0) {
            perror("snd_pcm_hw_params_set_channels");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_hw_params_set_rate_near(pcm, hw_params, &err, 0);
        if (err < 0) {
            perror("snd_pcm_hw_params_set_rate_near");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_hw_params_set_period_size_near(pcm, hw_params, &frames_per_period, 0);
        if (err < 0) {
            perror("snd_pcm_hw_params_set_period_size_near");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_hw_params(pcm, hw_params);
        if (err < 0) {
            perror("snd_pcm_hw_params");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_sw_params_current(pcm, sw_params);
        if (err < 0) {
            perror("snd_pcm_sw_params_current");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_sw_params_set_start_threshold(pcm, sw_params, 0);
        if (err < 0) {
            perror("snd_pcm_sw_params_set_start_threshold");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_sw_params(pcm, sw_params);
        if (err < 0) {
            perror("snd_pcm_sw_params");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_prepare(pcm);
        if (err < 0) {
            perror("snd_pcm_prepare");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        pcm_state = 0;
        process_audio();
    } else {
        // Simulate audio input with a sine wave
        while (1) {
            double t = (double)pigpio_millis() / 1000.0;
            double amplitude = sin(2 * M_PI * 1.0 * t); // 1 Hz sine wave
            update_led(amplitude);
            usleep(UPDATE_INTERVAL);
        }
    }

    return EXIT_SUCCESS;
}

