        if (err < 0) {
            perror("snd_pcm_hw_params_malloc");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

        err = snd_pcm_sw_params_malloc(&sw_params);
        if (err < 0) {
            perror("snd_pcm_sw_params_malloc");
            cleanup_alsa();
            cleanup_pigpio();
            return EXIT_FAILURE;
        }

