    signal(SIGTERM, handle_signal);

    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    file = fopen("color_data.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        i2cClose(i2c_handle);
        return 1;
    }

    fprintf(file, "Timestamp,Clear,Red,Green,Blue\n");

    while (!stop) {
        if (i2cWriteReg(i2c_handle, TCS34725_CONTROL_REG, 0x03) < 0) {
            fprintf(stderr, "Failed to write to control register\n");
            clear = red = green = blue = 0;
        } else {
            if (i2cWriteReg(i2c_handle, TCS34725_ATIME, 0xD5) < 0) {
                fprintf(stderr, "Failed to write to ATIME register\n");
                clear = red = green = blue = 0;
            } else {
                if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATAL, 4, buffer) < 0) {
                    fprintf(stderr, "Failed to read clear data\n");
                    clear = red = green = blue = 0;
                } else {
                    clear = (buffer[0] << 8) | buffer[1];
                    red = (buffer[2] << 8) | buffer[3];
                    green = (buffer[4] << 8) | buffer[5];
                    blue = (buffer[6] << 8) | buffer[7];
                }
            }
        }

        timestamp = time(NULL);
        fprintf(file, "%lu,%lu,%lu,%lu,%lu\n", timestamp, clear, red, green, blue);

        gpioDelay(500000); // 500 ms delay
    }

    fclose(file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

