#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define SUNRISE_DURATION 3600 // 1 hour
#define DAYTIME_DURATION 21600 // 6 hours
#define SUNSET_DURATION 3600 // 1 hour
#define NIGHTTIME_DURATION 51840 // 14.4 hours

static gpiod_chip *chip;
static gpiod_line *lines[NUM_RELAYS];

void handle_signal(int signum) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(lines[i], 1);
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    exit(signum);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    const char *chip_name = "gpio";
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_string(errno));
        return 1;
    }

    const char *pins[] = {"17", "27", "22", "23"};
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line *line = gpiod_line_get(chip, pins[i]);
        if (!line) {
            fprintf(stderr, "Failed to get GPIO line %s: %s\n", pins[i], gpiod_error_string(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        if (gpiod_line_request_output(line, "Lamp %d", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %s for output: %s\n", pins[i], gpiod_error_string(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        lines[i] = line;
    }

    int total_duration = SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION + NIGHTTIME_DURATION;
    int current_time = 0;

    while (1) {
        if (current_time < SUNRISE_DURATION) {
            // Sunrise phase
            int duty_cycle = current_time * 255 / SUNRISE_DURATION;
            for (int i = 0; i < NUM_RELAYS; i++) {
                gpiod_line_set_value(lines[i], 1 - (duty_cycle & 1));
            }
        } else if (current_time < SUNRISE_DURATION + DAYTIME_DURATION) {
            // Daytime phase
            for (int i = 0; i < NUM_RELAYS; i++) {
                gpiod_line_set_value(lines[i], 0);
            }
        } else if (current_time < SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION) {
            // Sunset phase
            int duty_cycle = (SUNRISE_DURATION + DAYTIME_DURATION - current_time) * 255 / SUNSET_DURATION;
            for (int i = 0; i < NUM_RELAYS; i++) {
                gpiod_line_set_value(lines[i], 1 - (duty_cycle & 1));
            }
        } else {
            // Nighttime phase
            for (int i = 0; i < NUM_RELAYS; i++) {
                gpiod_line_set_value(lines[i], 1);
            }
        }

        usleep(1000000 / 60); // Sleep for 1/60th of a second
        current_time = (current_time + 1) % total_duration;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

