#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_INTERVAL 200000 // 200 ms
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

void log_event(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        return;
    }

    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    struct timespec last_event_time = {0, 0};
    struct timespec current_time;

    signal(SIGINT, handle_sigint);

    while (!stop) {
        clock_gettime(CLOCK_REALTIME, &current_time);

        if (current_time.tv_sec - last_event_time.tv_sec >= DEBOUNCE_INTERVAL / 1000000000) {
            if (gpioRead(GPIO_PIN) == 0) {
                char timestamp[20];
                time_t now = time(NULL);
                struct tm *now_tm = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", now_tm);

                log_event(timestamp);

                char video_filename[50];
                snprintf(video_filename, sizeof(video_filename), "%s%s.h264", VIDEO_DIR, timestamp);

                char raspivid_command[100];
                snprintf(raspivid_command, sizeof(raspivid_command), "raspivid -t 5000 -o %s", video_filename);

                FILE *log_file = fopen(LOG_FILE, "a");
                if (log_file == NULL) {
                    fprintf(stderr, "Failed to open log file for writing.\n");
                    continue;
                }

                fprintf(log_file, "Recording video: %s\n", video_filename);
                fclose(log_file);

                int result = system(raspivid_command);
                if (result != 0) {
                    fprintf(stderr, "Failed to execute raspivid command: %s\n", raspivid_command);
                }
            }

            last_event_time = current_time;
        }
    }

    gpioTerminate();
    return 0;
}

