#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define WAKE_REG 0x6B
#define SRD_REG 0x19
#define GFS_REG 0x1B
#define GYRO_DATA_REG 0x43
#define GYRO_DATA_LEN 6
#define SENSITIVITY 131.0
#define SAMPLE_RATE 100
#define SAMPLE_INTERVAL (1000000 / SAMPLE_RATE)

FILE *log_file;
int i2c_handle;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(signum);
}

void init_sensor() {
    if (i2cWriteByteData(i2c_handle, WAKE_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to wake the sensor.\n");
        exit(1);
    }
    if (i2cWriteByteData(i2c_handle, SRD_REG, 0x07) < 0) {
        fprintf(stderr, "Failed to set sample rate divider.\n");
        exit(1);
    }
    if (i2cWriteByteData(i2c_handle, GFS_REG, 0x00) < 0) {
