void handle_signal(int signum) {
    for (int i = 0; i < NUM_ZONES; i++) {
        gpioWrite(ZONE_PINS[i], PI_ON);
    }
    fclose(log_file);
    pigpioStop();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);

    srand(time(NULL));

    for (int i = 0; i < NUM_ZONES; i++) {
        if (gpioSetMode(ZONE_PINS[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO mode for pin %d\n", ZONE_PINS[i]);
            handle_signal(SIGINT);
        }
        gpioWrite(ZONE_PINS[i], PI_ON); // Deactivate all initially
    }

    while (1) {
        time_t now = time(NULL);
        char timestamp[20];
        struct tm *tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        for (int i = 0; i < NUM_ZONES; i++) {
            int moisture_reading = rand() % 101;
            fprintf(log_file, "%s - Zone %d: Moisture %d\n", timestamp, i + 1, moisture_reading);

            if (moisture_reading < 30) {
                if (gpioWrite(ZONE_PINS[i], PI_OFF) < 0) {
                    fprintf(stderr, "Failed to set GPIO state for pin %d\n", ZONE_PINS[i]);
                    handle_signal(SIGINT);
                }
                fprintf(log_file, " - Relay %d: Activated\n", i + 1);
            } else {
                if (gpioWrite(ZONE_PINS[i], PI_ON) < 0) {
                    fprintf(stderr, "Failed to set GPIO state for pin %d\n", ZONE_PINS[i]);
                    handle_signal(SIGINT);
                }
                fprintf(log_file, " - Relay %d: Deactivated\n", i + 1);
            }
        }

        sleep(5); // Wait 5 seconds before next reading
    }

    fclose(log_file);
    pigpioStop();

    return 0;
}

