#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_ADDR 0x53
#define DATA_FORMAT_REG 0x31
#define POWER_CTL_REG 0x2D
#define DATAX0_REG 0x32
#define SCALE_FACTOR 256.0
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 0.5
#define ALARM_GPIO 27

void handle_sigint(int signum) {
    if (i2c_handle) {
        i2c_close(i2c_handle);
    }
    if (pi_handle) {
        pi_set_mode(ALARM_GPIO, PI_OUTPUT);
        pi_write(ALARM_GPIO, 0);
        pi_stop();
    }
    exit(0);
}

int read_i2c_data(int handle, uint8_t reg, uint8_t *data, int length) {
    int result = i2c_read_device(handle, reg, data, length);
    if (result != length) {
        fprintf(stderr, "Error reading I2C data from register 0x%02X\n", reg);
    }
    return result;
}

int write_i2c_data(int handle, uint8_t reg, uint8_t *data, int length) {
    int result = i2c_write_device(handle, reg, data, length);
    if (result != length) {
        fprintf(stderr, "Error writing I2C data to register 0x%02X\n", reg);
    }
    return result;
}

int main() {
    int i2c_handle = -1;
    int pi_handle = -1;
    uint8_t data[6];
    struct timespec start_time, end_time;
    double x, y, z;
    FILE *log_file;

    signal(SIGINT, handle_sigint);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    pi_handle = pigpio_start();
    if (pi_handle < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    if ((i2c_handle = i2c_open(1, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    uint8_t config_data = 0x0B;
    if (write_i2c_data(i2c_handle, DATA_FORMAT_REG, &config_data, 1) != 1) {
        return 1;
    }

    config_data = 0x08;
    if (write_i2c_data(i2c_handle, POWER_CTL_REG, &config_data, 1) != 1) {
        return 1;
    }

    log_file = fopen("freefall.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        if (read_i2c_data(i2c_handle, DATAX0_REG, data, 6) != 6) {
            continue;
        }

        x = (double)((int16_t)data[0] << 8 | data[1]) / SCALE_FACTOR;
        y = (double)((int16_t)data[2] << 8 | data[3]) / SCALE_FACTOR;
        z = (double)((int16_t)data[4] << 8 | data[5]) / SCALE_FACTOR;

        if (abs(x) < FREEFALL_THRESHOLD && abs(y) < FREEFALL_THRESHOLD && abs(z) < FREEFALL_THRESHOLD) {
            clock_gettime(CLOCK_REALTIME, &start_time);
            while (1) {
                if (read_i2c_data(i2c_handle, DATAX0_REG, data, 6) != 6) {
                    continue;
                }

                x = (double)((int16_t)data[0] << 8 | data[1]) / SCALE_FACTOR;
                y = (double)((int16_t)data[2] << 8 | data[3]) / SCALE_FACTOR;
                z = (double)((int16_t)data[4] << 8 | data[5]) / SCALE_FACTOR;

                if (abs(x) >= FREEFALL_THRESHOLD || abs(y) >= FREEFALL_THRESHOLD || abs(z) >= FREEFALL_THRESHOLD) {
                    break;
                }

                clock_gettime(CLOCK_REALTIME, &end_time);
                if (end_time.tv_sec - start_time.tv_sec >= FREEFALL_DURATION) {
                    pi_set_mode(ALARM_GPIO, PI_OUTPUT);
                    pi_write(ALARM_GPIO, 1);
                    sleep(5);
                    pi_set_mode(ALARM_GPIO, PI_OUTPUT);
                    pi_write(ALARM_GPIO, 0);

                    char timestamp[20];
                    time_t rawtime;
                    struct tm * timeinfo;
                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
                    fflush(log_file);
                    break;
                }

                usleep(500000); // 0.5 seconds
            }
        }

        usleep(100000); // 100 ms
    }

    fclose(log_file);
    i2c_close(i2c_handle);
    pi_stop();

    return 0;
}

