#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE 23200 // 23200 µs (about 4 meters)
#define TIMEOUT 10000000 // 100 ms

volatile int trig_start_tick = 0;
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int distance_cm = 0;
volatile int valid_reading = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void trig_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        trig_start_tick = tick;
    }
}

void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
    } else if (level == 0) {
        echo_end_tick = tick;
        valid_reading = 1;
    }
}

void handle_sigint(int signum) {
    gpioSetAlertFunc(TRIG_PIN, NULL);
    gpioSetAlertFunc(ECHO_PIN, NULL);
    fclose(stdout);
    pigpioStop();
    pthread_mutex_destroy(&mutex);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    FILE *log_file = fopen("distance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioSetAlertFunc(TRIG_PIN, trig_callback);
    gpioSetAlertFunc(ECHO_PIN, echo_callback);

    while (1) {
        gpioWrite(TRIG_PIN, 0);
        usleep(2);
        gpioWrite(TRIG_PIN, 1);
        usleep(10);
        gpioWrite(TRIG_PIN, 0);

        while (!valid_reading) {
            usleep(200000); // 200 ms
        }

        if (echo_end_tick == 0 || echo_start_tick == 0) {
            fprintf(stderr, "Invalid pulse width\n");
            continue;
        }

        uint32_t pulse_width = echo_end_tick - echo_start_tick;
        if (pulse_width > MAX_DISTANCE || pulse_width < TIMEOUT) {
            fprintf(stderr, "Pulse width out of range\n");
            continue;
        }

        distance_cm = (pulse_width * 34000) / 2 / 1000000; // Speed of sound 340 m/s

        pthread_mutex_lock(&mutex);
        fprintf(log_file, "%lu,%d\n", pigpioGetTickDiff(trig_start_tick, echo_end_tick) * 1000000, distance_cm);
        pthread_mutex_unlock(&mutex);

        valid_reading = 0;
        echo_start_tick = 0;
        echo_end_tick = 0;
    }

    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&mutex);

    return 0;
}
