#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LIS3DH_I2C_ADDR 0x18
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x1E
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Z_L 0x2C

#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int read_acceleration(int i2c_handle) {
    int x, y, z;
    int retries = 3;

    while (retries > 0) {
        if (i2c_read_device(i2c_handle, LIS3DH_OUT_X_L, 6, (char*)&x, 1) == 6 &&
            i2c_read_device(i2c_handle, LIS3DH_OUT_Y_L, 6, (char*)&y, 1) == 6 &&
            i2c_read_device(i2c_handle, LIS3DH_OUT_Z_L, 6, (char*)&z, 1) == 6) {
            break;
        }
        retries--;
        usleep(100000); // 100 ms delay
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read acceleration data after 3 retries.\n");
        return -1;
    }

    return (x | (y << 16) | (z << 32)) / 16384; // Convert to g
}

int main(int argc, char *argv[]) {
    int i2c_handle;
    double freefall_threshold = FREEFALL_THRESHOLD;
    double impact_threshold = IMPACT_THRESHOLD;

    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if ((i2c_handle = i2cOpen(1, LIS3DH_I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteDevice(i2c_handle, LIS3DH_CTRL_REG1, 0x77) < 0 ||
        i2cWriteDevice(i2c_handle, LIS3DH_CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to configure LIS3DH.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!stop) {
        double acceleration = read_acceleration(i2c_handle);

        if (acceleration < 0) {
            continue;
        }

        double magnitude = sqrt(acceleration * acceleration);

        if (magnitude < freefall_threshold) {
            printf("Freefall detected.\n");
        } else if (magnitude > impact_threshold) {
            printf("Impact detected.\n");
            gpioWrite(17, PI_ON);
            usleep(1000000); // 1 second
            gpioWrite(17, PI_OFF);
        }

        usleep(100000); // 100 ms delay
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

