#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define ACCEL_DATA 0x28
#define DEFAULT_THRESHOLD 2.0
#define DEFAULT_INTERVAL 100

void handle_sigint(int signum) {
    if (pi != 0) {
        i2cClose(i2c_handle);
        pigpioStop();
    }
    exit(0);
}

int main(int argc, char *argv[]) {
    int i2c_handle = 0;
    float threshold = DEFAULT_THRESHOLD;
    int interval = DEFAULT_INTERVAL;
    unsigned char config_reg1 = 0x57;
    unsigned char config_reg4 = 0x88;
    unsigned char accel_data[6];
    int i;
    double x, y, z;
    struct timespec ts;

    if (argc > 1) {
        if (sscanf(argv[1], "-a %x", &I2C_ADDR) == 1 && I2C_ADDR >= 0x08 && I2C_ADDR <= 0x77) {
            printf("Using I2C address: 0x%02X\n", I2C_ADDR);
        } else {
            fprintf(stderr, "Invalid I2C address. Must be in range 0x08-0x77.\n");
            return 1;
        }
    }

    if (argc > 2) {
        if (sscanf(argv[2], "-t %f", &threshold) == 1 && threshold > 0) {
            printf("Using threshold: %.2f g\n", threshold);
        } else {
            fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    i2c_handle = i2cOpen(I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X.\n", I2C_ADDR);
        pigpioStop();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG1, config_reg1) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1.\n");
        i2cClose(i2c_handle);
        pigpioStop();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG4, config_reg4) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4.\n");
        i2cClose(i2c_handle);
        pigpioStop();
        return 1;
    }

    while (1) {
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_DATA, 6, accel_data) < 0) {
            printf("Failed to read acceleration data. Continuing...\n");
            continue;
        }

        x = ((accel_data[0] << 8) | accel_data[1]) >> 4;
        y = ((accel_data[2] << 8) | accel_data[3]) >> 4;
        z = ((accel_data[4] << 8) | accel_data[5]) >> 4;

        x *= 0.0009765625;
        y *= 0.0009765625;
        z *= 0.0009765625;

        ts.tv_sec = time(NULL);
        ts.tv_nsec = 0;

        if (abs(x) > threshold || abs(y) > threshold || abs(z) > threshold) {
            FILE *log_file = fopen("/var/log/high_acceleration.log", "a");
            if (log_file != NULL) {
                fprintf(log_file, "Timestamp: %ld.%09ld, X: %.4f g, Y: %.4f g, Z: %.4f g\n", ts.tv_sec, ts.tv_nsec, x, y, z);
                fclose(log_file);
            }
            system("sudo shutdown -h now");
        }

        usleep(interval * 1000);
    }

    i2cClose(i2c_handle);
    pigpioStop();

    return 0;
}

