    int center = gpiod_line_get_value(lines[1]);
    int right = gpiod_line_get_value(lines[2]);

    buffer[buffer_head][0] = left;
    buffer[buffer_head][1] = center;
    buffer[buffer_head][2] = right;

    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    if (center == 1) {
        int consecutive_no_line = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (buffer[(buffer_head + i) % BUFFER_SIZE][1] == 1) {
                consecutive_no_line++;
            } else {
                break;
            }
        }

        if (consecutive_no_line >= 5) {
            gpiod_line_set_value(lines[3], 1);
            usleep(ALERT_TIME * 1000);
            gpiod_line_set_value(lines[3], 0);
        }
    }

    if (center == 0) {
        // Move forward
    } else if (left == 0) {
        // Turn left
    } else if (right == 0) {
        // Turn right
    } else {
        // Stop
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    lines[0] = gpiod_line_request(chip, 4, "left", 0, 0);
    if (!lines[0]) {
        perror("Failed to request GPIO4");
        goto error_exit;
    }

    lines[1] = gpiod_line_request(chip, 17, "center", 0, 0);
    if (!lines[1]) {
        perror("Failed to request GPIO17");
        goto error_exit;
    }

    lines[2] = gpiod_line_request(chip, 27, "right", 0, 0);
    if (!lines[2]) {
        perror("Failed to request GPIO27");
        goto error_exit;
    }

    lines[3] = gpiod_line_request(chip, 22, "alert", 0, 0);
    if (!lines[3]) {
        perror("Failed to request GPIO22");
        goto error_exit;
    }

    while (1) {
        poll_sensors();
        usleep(POLL_INTERVAL * 1000);
    }

error_exit:
    for (int i = 0; i < 4; i++) {
        gpiod_line_free(lines[i]);
    }
    gpiod_chip_put(chip);

    return 0;
}

