#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x30
#define GPIO_RELAY 17
#define THRESHOLD 5.0
#define POLL_LIMIT 50
#define SAMPLE_INTERVAL 100

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    if (pi != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        printf("SIGINT received. Shutting down.\n");
    }
    stop = 1;
}

int main() {
    int i2c_handle = 0;
    int field_raw = 0;
    int msb = 0;
    int lsb = 0;
    int field_mT_x100 = 0;
    int poll_count = 0;
    int relay_state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        if (i2cWriteByte(i2c_handle, 0xC1, 0x01) < 0) {
            fprintf(stderr, "Failed to write to register 0xC1.\n");
            relay_state = 0;
            gpioWrite(GPIO_RELAY, relay_state);
            continue;
        }

        poll_count = 0;
        while (i2cReadByte(i2c_handle, 0xC1) != 0 && poll_count < POLL_LIMIT) {
            poll_count++;
            usleep(SAMPLE_INTERVAL * 1000);
        }

        if (poll_count == POLL_LIMIT) {
            fprintf(stderr, "Timeout while polling register 0xC1.\n");
            relay_state = 0;
            gpioWrite(GPIO_RELAY, relay_state);
            continue;
        }

        if (i2cReadByteData(i2c_handle, 0xC0, &lsb) < 0 || i2cReadByteData(i2c_handle, 0xC0, &msb) < 0) {
            fprintf(stderr, "Failed to read from register 0xC0.\n");
            relay_state = 0;
            gpioWrite(GPIO_RELAY, relay_state);
            continue;
        }

        field_raw = (msb << 8) | lsb;
        field_mT_x100 = field_raw * 25 / 1000;

        if (field_mT_x100 > THRESHOLD * 100) {
            relay_state = 1;
        } else {
            relay_state = 0;
        }

        if (relay_state != 0 && !gpioRead(GPIO_RELAY)) {
            if (gpioWrite(GPIO_RELAY, relay_state) < 0) {
                fprintf(stderr, "Failed to set relay state.\n");
            } else {
                printf("Relay activated at %s\n", ctime(&time(NULL)));
            }
        } else if (!relay_state && gpioRead(GPIO_RELAY)) {
            if (gpioWrite(GPIO_RELAY, relay_state) < 0) {
                fprintf(stderr, "Failed to set relay state.\n");
            } else {
                printf("Relay deactivated at %s\n", ctime(&time(NULL)));
            }
        }

        printf("Field strength: %.2f mT at %s\n", (double)field_mT_x100 / 100.0, ctime(&time(NULL)));

        usleep(SAMPLE_INTERVAL * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

