#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

int relay_pin = 18; // GPIO 18 (BCM numbering)

void handle_signal(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioGetErrorStr(pigpioGetError()));
    }
    gpioWrite(relay_pin, PI_OUTPUT);
    gpioWrite(relay_pin, PI_LOW);
    gpioTerminate();
    exit(signum);
}

void log_event(const char *event, int relay_state) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    fprintf(log_file, "%s %s %d\n", asctime(timeinfo), event, relay_state);
    fclose(log_file);
}

int main() {
    int sockfd, new_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len;
    char buffer[BUFFER_SIZE];
    int n;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioGetErrorStr(pigpioGetError()));
        return 1;
    }

    // Set relay pin to output
    if (gpioSetMode(relay_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", pigpioGetErrorStr(pigpioGetError()));
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        return 1;
    }

    // Bind socket to port
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);
    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind socket");
        close(sockfd);
        return 1;
    }

    // Listen for incoming connections
    if (listen(sockfd, 5) < 0) {
        perror("Failed to listen on socket");
        close(sockfd);
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    while (1) {
        addr_len = sizeof(client_addr);
        new_fd = accept(sockfd, (struct sockaddr *)&client_addr, &addr_len);
        if (new_fd < 0) {
            perror("Failed to accept connection");
            continue;
        }

        n = read(new_fd, buffer, BUFFER_SIZE - 1);
        if (n < 0) {
            perror("Failed to read from socket");
            close(new_fd);
            continue;
        }

        buffer[n] = '\0';
        if (strcasecmp("on", buffer) == 0) {
            if (gpioWrite(relay_pin, PI_HIGH) < 0) {
                fprintf(stderr, "Failed to set relay to ON: %s\n", pigpioGetErrorStr(pigpioGetError()));
            } else {
                log_event("ON", PI_HIGH);
            }
        } else if (strcasecmp("off", buffer) == 0) {
            if (gpioWrite(relay_pin, PI_LOW) < 0) {
                fprintf(stderr, "Failed to set relay to OFF: %s\n", pigpioGetErrorStr(pigpioGetError()));
            } else {
                log_event("OFF", PI_LOW);
            }
        } else {
            fprintf(stderr, "Invalid command: %s\n", buffer);
            log_event("Invalid command", PI_LOW);
        }

        close(new_fd);
    }

    // Clean up on exit
    close(sockfd);
    return 0;
}

