#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SLF3S_ADDR1 0x08
#define SLF3S_ADDR2 0x09
#define SLF3S_CMD 0x36
#define SLF3S_DATA_LEN 3
#define SLF3S_SCALE (1.0 / 1500.0)
#define SLF3S_MIN_FLOW 5.0
#define GPIO_PIN 18
#define GPIO_MODE PI_OUTPUT
#define GPIO_LEVEL 0

volatile sig_atomic_t shutdown_flag = 0;

void handle_signal(int signum) {
    shutdown_flag = 1;
}

int i2c_write(int handle, uint8_t* data, uint8_t len) {
    int ret = i2c_write_device(handle, data, len);
    if (ret != len) {
        fprintf(stderr, "Error writing to I2C device (handle: %d, expected: %d, got: %d)\n", handle, len, ret);
        return -1;
    }
    return 0;
}

int i2c_read(int handle, uint8_t* data, uint8_t len) {
    int ret = i2c_read_device(handle, data, len);
    if (ret != len) {
        fprintf(stderr, "Error reading from I2C device (handle: %d, expected: %d, got: %d)\n", handle, len, ret);
        return -1;
    }
    return 0;
}

uint8_t crc8(uint8_t* data, uint8_t len, uint8_t init, uint8_t poly) {
    uint8_t crc = init;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int handle1 = i2cOpen(1, SLF3S_ADDR1, 0);
    if (handle1 < 0) {
