#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24
#define POLL_INTERVAL 200000 // 200 ms
#define MOTOR_RUN_TIME 5000000 // 5 seconds
#define DRY_CHECK_COUNT 3

volatile sig_atomic_t shutdown = 0;

void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);
}

void handle_signal(int signum) {
    shutdown = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Rain-actuated window controller started");

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int dry_count = 0;
    int last_state = 1; // Assume initially dry

    while (!shutdown) {
        int current_state = gpioRead(RAIN_SENSOR_PIN);

        if (current_state != last_state) {
            if (current_state == 0 && last_state == 1) { // Rising edge: dry to wet
                log_message(LOG_INFO, "Rain detected, starting motor");

                if (gpioWrite(MOTOR_ENA_PIN, 1) < 0) {
                    log_message(LOG_WARNING, "Failed to set ENA HIGH");
                }
                if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
                    log_message(LOG_WARNING, "Failed to set IN1 HIGH");
                }
                if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
                    log_message(LOG_WARNING, "Failed to set IN2 LOW");
                }

                usleep(MOTOR_RUN_TIME);

                if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
                    log_message(LOG_WARNING, "Failed to set ENA LOW");
                }
                if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
                    log_message(LOG_WARNING, "Failed to set IN1 LOW");
                }
                if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
                    log_message(LOG_WARNING, "Failed to set IN2 LOW");
                }

                log_message(LOG_INFO, "Motor stopped");
                dry_count = 0; // Reset dry count after motor operation
            } else {
                dry_count++;
                if (dry_count >= DRY_CHECK_COUNT) {
                    dry_count = 0;
                }
            }
        }

        last_state = current_state;
        usleep(POLL_INTERVAL);
    }

    log_message(LOG_INFO, "Shutting down...");

    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        log_message(LOG_WARNING, "Failed to set ENA LOW during shutdown");
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        log_message(LOG_WARNING, "Failed to set IN1 LOW during shutdown");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        log_message(LOG_WARNING, "Failed to set IN2 LOW during shutdown");
    }

    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

