#include <stdio.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO_PIN 18
#define BUTTON1_PIN 21
#define BUTTON2_PIN 22
#define DEBOUNCE_DELAY 50

volatile sig_atomic_t shutdown = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        shutdown = 1;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetMode(SERVO_PIN, PI_SERVO);
    gpioServo(SERVO_PIN, 0); // Start with no pulse

    gpioSetMode(BUTTON1_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON1_PIN, PI_PUD_UP);

    gpioSetMode(BUTTON2_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON2_PIN, PI_PUD_UP);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!shutdown) {
        if (gpioRead(BUTTON1_PIN) == 0) {
            if (gpioServo(SERVO_PIN, 2000) < 0) {
                fprintf(stderr, "Failed to set servo to locked position.\n");
                shutdown = 1;
            } else {
                printf("Servo locked.\n");
                usleep(DEBOUNCE_DELAY * 1000); // Debounce delay
            }
        }

        if (gpioRead(BUTTON2_PIN) == 0) {
            if (gpioServo(SERVO_PIN, 1000) < 0) {
                fprintf(stderr, "Failed to set servo to unlocked position.\n");
                shutdown = 1;
            } else {
                printf("Servo unlocked.\n");
                usleep(DEBOUNCE_DELAY * 1000); // Debounce delay
            }
        }

        if (shutdown) {
            if (gpioServo(SERVO_PIN, 0) < 0) {
                fprintf(stderr, "Failed to stop servo on shutdown.\n");
            } else {
                printf("Servo stopped on shutdown.\n");
            }
            gpioTerminate();
            return 0;
        }

        usleep(10000); // Small sleep to avoid high CPU usage
    }

    return 0;
}

