#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define PIR_PIN 4
#define LED_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL 100 // ms

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

void log_event(const char *event, int duration) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Failed to open log file.\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s - %s - Duration: %d seconds\n", buffer, event, duration);

    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("pigpio initialization failed.\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    if (gpioRead(PIR_PIN) != 0) {
        printf("PIR sensor is already active.\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_OFF);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        if (gpioReadRising(PIR_PIN)) {
            log_event("Motion detected", 0);
            gpioWrite(LED_PIN, PI_ON);
            usleep(60000000); // Sleep for 60 seconds
            gpioWrite(LED_PIN, PI_OFF);
            log_event("Motion ended", 60);
        }

        usleep(POLL_INTERVAL * 1000); // Sleep for 100 ms
    }

    gpioWrite(LED_PIN, PI_OFF);
    log_event("Program stopped", 0);

    gpioTerminate();
    return 0;
}

