#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define GPIO_RELAY 17

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int i2c_write(int reg, uint8_t value) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire bus access/talk to slave");
        close(fd);
        return -1;
    }

    uint8_t buf[2] = {reg, value};
    int bytes_written = write(fd, buf, 2);
    if (bytes_written != 2) {
        perror("Failed to write to MPR121");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int i2c_read(int reg, uint8_t *value) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire bus access/talk to slave");
        close(fd);
        return -1;
    }

    uint8_t buf[2] = {reg, 0};
    int bytes_written = write(fd, buf, 2);
    if (bytes_written != 2) {
        perror("Failed to write to MPR121");
        close(fd);
        return -1;
    }

    int bytes_read = read(fd, value, 1);
    if (bytes_read != 1) {
        perror("Failed to read from MPR121");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, PI_OFF);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // MPR121 initialization
    if (i2c_write(0x00, 0x00)) { // Soft-reset
        fprintf(stderr, "Failed to perform MPR121 soft-reset\n");
        goto cleanup;
    }

    if (i2c_write(0x5B, 0x00)) { // Baseline filtering
        fprintf(stderr, "Failed to configure MPR121 baseline filtering\n");
        goto cleanup;
    }

    if (i2c_write(0x2C, 0x00)) { // Debounce
        fprintf(stderr, "Failed to set MPR121 debounce\n");
        goto cleanup;
    }

    if (i2c_write(0x7B, 0x00)) { // Auto-config
        fprintf(stderr, "Failed to set MPR121 auto-config\n");
        goto cleanup;
    }

    if (i2c_write(0x7C, 0x00)) {
        fprintf(stderr, "Failed to set MPR121 auto-config\n");
        goto cleanup;
    }

    if (i2c_write(0x7D, 0x00)) {
        fprintf(stderr, "Failed to set MPR121 auto-config\n");
        goto cleanup;
    }

    if (i2c_write(0x5E, 0x0C)) { // Enable 12 electrodes
        fprintf(stderr, "Failed to enable MPR121 electrodes\n");
        goto cleanup;
    }

    uint8_t prev_touch_status = 0;
    while (!stop_flag) {
        uint8_t touch_status;
        if (i2c_read(0x00, &touch_status)) {
            fprintf(stderr, "Failed to read touch status from MPR121\n");
            continue;
        }

        if ((touch_status & 0x01) && !(prev_touch_status & 0x01)) {
            // Rising edge detected on electrode 0
            gpioWrite(GPIO_RELAY, PI_ON);
            usleep(200000); // 200 ms debounce
            gpioWrite(GPIO_RELAY, PI_OFF);
        }

        prev_touch_status = touch_status;
    }

cleanup:
    gpioWrite(GPIO_RELAY, PI_OFF);
    gpioTerminate();
    return 0;
}

