#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <syslog.h>
#include <gpiod.h>
#include <stdarg.h>
#include <time.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define SOCKET_PORT 5000
#define LOG_FILE "security.log"

static gpiod_line *servo_line = NULL;
static gpiod_line *pir_line = NULL;
static int socket_fd = -1;
static FILE *log_file = NULL;

void log_message(const char *format, ...) {
    va_list args;
    char buffer[1024];
    time_t now;
    struct tm *tm_info;

    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    now = time(NULL);
    tm_info = localtime(&now);

    syslog(LOG_USER, "%s %s", asctime(tm_info), buffer);

    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", asctime(tm_info), buffer);
        fflush(log_file);
    }
}

void handle_servo_command(int angle) {
    if (angle < 0 || angle > 180) {
        log_message("Invalid servo angle: %d", angle);
        return;
    }

    int pulse_width = (angle * 1000 / 180) + 500; // 1ms to 2ms pulse width
    gpiod_line_set_value(servo_line, 1);
    usleep(pulse_width * 1000);
    gpiod_line_set_value(servo_line, 0);
}

void handle_pir_command() {
    int pir_value = gpiod_line_get_value(pir_line);
    char response[10];

    if (pir_value == 1) {
        snprintf(response, sizeof(response), "PIR:1");
    } else {
        snprintf(response, sizeof(response), "PIR:0");
    }

    log_message("PIR sensor value: %s", response);
}

void handle_command(const char *command) {
    int angle = 0;

    if (sscanf(command, "SERVO %d", &angle) == 1) {
        handle_servo_command(angle);
    } else if (strcmp(command, "PIR") == 0) {
        handle_pir_command();
    } else {
        log_message("Unknown command: %s", command);
    }
}

void *servo_thread(void *arg) {
    while (1) {
        handle_servo_command(0); // Default position
        usleep(20000); // 50 Hz (20 ms period)
    }
}

void init_gpiod() {
    gpiod_chip *chip;
    gpiod_line_request_flags flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT | GPIOD_LINE_REQUEST_ACTIVE_HIGH;

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        log_message("Failed to open GPIO chip");
        exit(1);
    }

    if (gpiod_line_request_by_name(chip, "gpio%d", SERVO_PIN, "servo", &servo_line, flags) < 0) {
        log_message("Failed to request servo GPIO line");
        exit(1);
    }

    flags = GPIOD_LINE_REQUEST_DIRECTION_INPUT | GPIOD_LINE_REQUEST_ACTIVE_HIGH;
    if (gpiod_line_request_by_name(chip, "gpio%d", PIR_PIN, "pir", &pir_line, flags) < 0) {
        log_message("Failed to request PIR GPIO line");
        exit(1);
    }
}

void cleanup_gpiod() {
    if (servo_line) {
        gpiod_line_free(servo_line);
        servo_line = NULL;
    }

    if (pir_line) {
        gpiod_line_free(pir_line);
        pir_line = NULL;
    }
}

void init_socket() {
    struct sockaddr_in server_addr;

    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        log_message("Failed to create socket");
        exit(1);
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SOCKET_PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        log_message("Failed to bind socket");
        exit(1);
    }

    if (listen(socket_fd, 5) < 0) {
        log_message("Failed to listen on socket");
        exit(1);
    }
}

void cleanup_socket() {
    if (socket_fd >= 0) {
        close(socket_fd);
        socket_fd = -1;
    }
}

void init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_message("Failed to open log file");
        exit(1);
    }
}

void cleanup_log_file() {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes_read;

    while ((bytes_read = read(client_fd, buffer, sizeof(buffer) - 1)) > 0) {
        buffer[bytes_read] = '\0';
        log_message("Received command: %s", buffer);
        handle_command(buffer);
    }

    if (bytes_read < 0) {
        log_message("Error reading from client: %s", strerror(errno));
    }

    close(client_fd);
}

int main() {
    struct sockaddr_in client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    int client_fd;
    pthread_t servo_thread_id;

    openlog("servo_control", LOG_PID, LOG_USER);
    init_gpiod();
    init_socket();
    init_log_file();

    log_message("Starting servo control service");

    while (1) {
        client_fd = accept(socket_fd, (struct sockaddr *)&client_addr, &client_addr_len);
        if (client_fd < 0) {
            log_message("Failed to accept connection: %s", strerror(errno));
            continue;
        }

        log_message("Accepted connection from %s:%d", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));

        pthread_create(&servo_thread_id, NULL, servo_thread, NULL);

        handle_client(client_fd);

        pthread_cancel(servo_thread_id);
        pthread_join(servo_thread_id, NULL);
    }

    cleanup_socket();
    cleanup_gpiod();
    cleanup_log_file();
    closelog();

    return 0;
}

