#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_COMMAND_HIGH_RES 0x20
#define BH1750_CONVERSION_TIME 120
#define LUX_THRESHOLD 150
#define GPIO_RELAY 23
#define LOG_FILE "grow_log.txt"

FILE *log_file;
int i2c_handle;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cUnexport(i2c_handle);
    }
    gpioTerminate();
    exit(signum);
}

void log_lux(unsigned int lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s %u\n", buffer, lux);
    fflush(log_file);
}

int read_lux() {
    unsigned char command[2] = {BH1750_COMMAND_HIGH_RES, 0};
    unsigned char data[2];
    int raw;

    if (i2cWriteByte(i2c_handle, BH1750_I2C_ADDR, command, 2) < 0) {
        fprintf(stderr, "Error writing command to BH1750\n");
        return -1;
    }

    usleep(BH1750_CONVERSION_TIME * 1000);

    if (i2cReadDevice(i2c_handle, BH1750_I2C_ADDR, data, 2) < 0) {
        fprintf(stderr, "Error reading data from BH1750\n");
        return -1;
    }

    raw = (data[0] << 8) | data[1];
    return raw / 1.2;
}

int main() {
    int lux;
    int relay_state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay\n");
        return 1;
    }

    if ((i2c_handle = i2cOpen(1, BH1750_I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        lux = read_lux();
        if (lux < 0) {
            continue;
        }

        if (lux < LUX_THRESHOLD) {
            if (relay_state == 0) {
                if (gpioWrite(GPIO_RELAY, 1) < 0) {
                    fprintf(stderr, "Failed to activate relay\n");
                }
                relay_state = 1;
            }
        } else {
            if (relay_state == 1) {
                if (gpioWrite(GPIO_RELAY, 0) < 0) {
                    fprintf(stderr, "Failed to deactivate relay\n");
                }
                relay_state = 0;
            }
        }

        log_lux(lux);

        sleep(2);
    }

    return 0;
}

