#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define DOUT_PIN 23
#define SCK_PIN 24
#define SOLENOID_PIN 25

#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200
#define POLL_INTERVAL 500

static int threshold = DEFAULT_THRESHOLD;
static double scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;

static gpiod_chip *chip;
static gpiod_line *dout, *sck, *solenoid;

static void handle_signal(int signum) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signum);
    gpiod_line_request_free(dout);
    gpiod_line_request_free(sck);
    gpiod_line_request_free(solenoid);
    gpiod_chip_put(chip);
    exit(0);
}

static int read_hx711(void) {
    int i, bit, data = 0;
    for (i = 0; i < 24; i++) {
        gpiod_line_set_value(sck, 0);
        usleep(10);
        bit = gpiod_line_get_value(dout);
        data = (data << 1) | bit;
        gpiod_line_set_value(sck, 1);
        usleep(10);
    }
    gpiod_line_set_value(sck, 0);
    usleep(10);
    gpiod_line_set_value(sck, 1);
    usleep(10);
    return data;
}

static void startup_tare(void) {
    int i, sum = 0;
    for (i = 0; i < 10; i++) {
        sum += read_hx711();
        usleep(100000); // 100 ms delay
    }
    syslog(LOG_INFO, "Startup tare offset: %d", sum / 10);
}

static void main_loop(void) {
    int i, sum = 0;
    for (i = 0; i < 5; i++) {
        sum += read_hx711();
        usleep(100000); // 100 ms delay
    }
    int average_raw = sum / 5;
    double weight = (average_raw - (sum / 10)) / scale;
    syslog(LOG_INFO, "Measured weight: %.2f grams", weight);

    if (weight > threshold) {
        gpiod_line_set_value(solenoid, 1);
        usleep(duration * 1000);
        gpiod_line_set_value(solenoid, 0);
    }

    usleep(POLL_INTERVAL * 1000); // 500 ms delay
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s --threshold <grams> --scale <factor> --duration <ms>\n", argv[0]);
                exit(1);
        }
    }

    openlog("hx711_monitor", LOG_PID, LOG_USER);

    chip = gpiod_chip_open_by_name("gpio");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(1);
    }

    dout = gpiod_line_request_by_name(chip, "gpio23", "DOUT", GPIOD_LINE_DIRECTION_IN);
    if (!dout) {
        syslog(LOG_ERR, "Failed to request DOUT line");
        gpiod_chip_put(chip);
        exit(1);
    }

    sck = gpiod_line_request_by_name(chip, "gpio24", "SCK", GPIOD_LINE_DIRECTION_OUT);
    if (!sck) {
        syslog(LOG_ERR, "Failed to request SCK line");
        gpiod_line_request_free(dout);
        gpiod_chip_put(chip);
        exit(1);
    }

    solenoid = gpiod_line_request_by_name(chip, "gpio25", "Solenoid", GPIOD_LINE_DIRECTION_OUT);
    if (!solenoid) {
        syslog(LOG_ERR, "Failed to request solenoid line");
        gpiod_line_request_free(dout);
        gpiod_line_request_free(sck);
        gpiod_chip_put(chip);
        exit(1);
    }

    startup_tare();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        main_loop();
    }

    gpiod_line_request_free(dout);
    gpiod_line_request_free(sck);
    gpiod_line_request_free(solenoid);
    gpiod_chip_put(chip);
    closelog();

    return 0;
}

