#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_KEEPALIVE 60
#define GPIO_PIN 17

static mosquitto *mosq;
static int mosq_loop_running = 1;

void mosq_connect_callback(struct mosquitto *mosq, void *obj, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT: Connected to broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        syslog(LOG_ERR, "MQTT: Connection failed, connack: %s", mosquitto_connack_string(result));
    }
}

void mosq_message_callback(struct mosquitto *mosq, void *obj, const struct mosquitto_message *message) {
    syslog(LOG_INFO, "MQTT: Received message on topic %s: %s", message->topic, message->payload);

    if (strcmp(message->payload, "ON") == 0) {
        if (gpioWrite(GPIO_PIN, 1) < 0) {
            syslog(LOG_ERR, "GPIO: Failed to set GPIO %d HIGH", GPIO_PIN);
        }
    } else if (strcmp(message->payload, "OFF") == 0) {
        if (gpioWrite(GPIO_PIN, 0) < 0) {
            syslog(LOG_ERR, "GPIO: Failed to set GPIO %d LOW", GPIO_PIN);
        }
    } else {
        syslog(LOG_ERR, "MQTT: Invalid payload '%s', expected 'ON' or 'OFF'", message->payload);
    }
}

void mosq_disconnect_callback(struct mosquitto *mosq, void *obj, int rc) {
    syslog(LOG_INFO, "MQTT: Disconnected from broker");
    sleep(5);
    mosquitto_connect_callback(mosq, obj, MOSQ_ERR_SUCCESS);
}

void mosq_error_callback(struct mosquitto *mosq, void *obj, int error) {
    syslog(LOG_ERR, "MQTT: Error: %s", mosquitto_strerror(error));
}

void sig_handler(int signum) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signum);
    mosq_loop_running = 0;
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    exit(0);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    int ret;

    if (openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER) == -1) {
        perror("openlog");
        exit(1);
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "GPIO: Failed to initialize pigpio");
        exit(1);
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "GPIO: Failed to set GPIO %d as output", GPIO_PIN);
        exit(1);
    }

    if (gpioWrite(GPIO_PIN, 0) < 0) {
        syslog(LOG_ERR, "GPIO: Failed to set GPIO %d LOW", GPIO_PIN);
        exit(1);
    }

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT: Failed to create client");
        exit(1);
    }

    mosquitto_connect_callback_set(mosq, mosq_connect_callback);
    mosquitto_message_callback_set(mosq, mosq_message_callback);
    mosquitto_disconnect_callback_set(mosq, mosq_disconnect_callback);
    mosquitto_error_callback_set(mosq, mosq_error_callback);

    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT: Failed to connect to broker");
        exit(1);
    }

    while (mosq_loop_running) {
        ret = mosquitto_loop(mosq, -1);
        if (ret != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT: Loop returned error: %s", mosquitto_strerror(ret));
            mosquitto_disconnect(mosq);
            sleep(5);
            mosquitto_connect_callback(mosq, NULL, MOSQ_ERR_SUCCESS);
        }
    }

    return 0;
}

