#include <stdio.h>
#include <pigpio.h>

#define SERVO_PINS {7, 8, 9, 10, 11}
#define SERVO_POSITIONS {1000, 1500, 2000, 500, 2500}

int main(void) {
    int i, ret;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set PWM frequency to 50 Hz (20 ms period)
    if (gpioSetPWMfrequency(SERVO_PINS[0], 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for pin %d\n", SERVO_PINS[0]);
        goto cleanup;
    }

    // Set PWM range to 2500 microseconds
    if (gpioSetPWMrange(SERVO_PINS[0], 2500) < 0) {
        fprintf(stderr, "Failed to set PWM range for pin %d\n", SERVO_PINS[0]);
        goto cleanup;
    }

    // Apply pulse widths to each servo
    for (i = 0; i < 5; i++) {
        if (gpioSetPWMdutycycle(SERVO_PINS[i], SERVO_POSITIONS[i]) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for pin %d\n", SERVO_PINS[i]);
            goto cleanup;
        }
    }

    // Hold the signals for 3 seconds
    sleep(3);

    // Cleanly stop the PWM and release the library resources
cleanup:
    for (i = 0; i < 5; i++) {
        gpioSetPWMdutycycle(SERVO_PINS[i], 0);
    }
    gpioTerminate();

    return 0;
}

