            fprintf(stderr, "Failed to set PWM duty cycle for Motor B\n");
            cleanup();
        }

        printf("Motor A RPM: %.2f, PWM Duty Cycle: %.2f\n", rpm_a, pwm_duty_cycle_a);
        printf("Motor B RPM: %.2f, PWM Duty Cycle: %.2f\n", rpm_b, pwm_duty_cycle_b);

        usleep(CONTROL_PERIOD_MS * 1000);
    }

    cleanup();
    return 0;
