#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define LUX_HYSTERESIS 10
#define LUX_READ_INTERVAL 5000 // 5 seconds
#define LUX_READ_WAIT 180 // 180 ms

FILE *log_file;
int relay_pin = 17;
int i2c_handle;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
    }
    gpioTerminate();
    exit(signum);
}

int read_lux() {
    int lux;
    char cmd[2] = {0x21, 0x00};
    char data[2];

    if (write(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write command to BH1750 sensor.\n");
        return -1;
    }

    usleep(LUX_READ_WAIT * 1000); // Wait 180 ms

    if (read(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read data from BH1750 sensor.\n");
        return -1;
    }

    lux = (data[0] << 8) | data[1];
    lux /= 1.2;

    return lux;
}

void log_event(const char *event, int lux, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S: ", timeinfo);
    fprintf(log_file, "%sLux = %d, Relay = %s\n", buffer, lux, relay_state ? "ON" : "OFF");
}

int main() {
    int lux, relay_state = 0;
    int prev_lux = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if ((i2c_handle = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        return 1;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address.\n");
        return 1;
    }

    if ((log_file = fopen("chicken_coop_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        lux = read_lux();
        if (lux < 0) {
            relay_state = 0;
            log_event("Error reading sensor, turning off relay.", lux, relay_state);
        } else {
            if (lux < LUX_THRESHOLD_DUSK - LUX_HYSTERESIS && relay_state == 0) {
                relay_state = 1;
                log_event("Dusk detected, turning on relay.", lux, relay_state);
                gpioWrite(relay_pin, PI_ON);
            } else if (lux > LUX_THRESHOLD_DAWN + LUX_HYSTERESIS && relay_state == 1) {
                relay_state = 0;
                log_event("Dawn detected, turning off relay.", lux, relay_state);
                gpioWrite(relay_pin, PI_OFF);
            }
        }

        prev_lux = lux;
        sleep(LUX_READ_INTERVAL / 1000); // Sleep for 5 seconds
    }

    return 0;
}

