int relay_state = 0;

void handle_sigint(int signum) {
    printf("Received SIGINT (Ctrl+C). Gracefully shutting down...\n");
    gpioWrite(GPIO_RELAY, 0);  // Turn relay OFF
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(GPIO_TOUCH, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input.\n", GPIO_TOUCH);
        goto cleanup;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", GPIO_RELAY);
        goto cleanup;
    }

    printf("Relay control program started.\n");

    while (1) {
        if (gpioRead(GPIO_TOUCH) == 1) {
            usleep(DEBOUNCE_DELAY);
            if (gpioRead(GPIO_TOUCH) == 1) {
                relay_state = !relay_state;
                if (gpioWrite(GPIO_RELAY, relay_state) < 0) {
                    fprintf(stderr, "Failed to toggle relay state.\n");
                } else {
                    time_t now = time(NULL);
                    struct tm *now_tm = localtime(&now);
                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);
                    printf("%s Relay state: %s\n", timestamp, relay_state ? "ON" : "OFF");
                }
            }
        }

        usleep(MAIN_LOOP_SLEEP);
    }

cleanup:
    gpioTerminate();
    return 0;
}

