#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define DEBOUNCE_TIMEOUT 1000000 // 1 second in microseconds
#define LOG_FILE "water_flow.log"

volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

void *isr_handler(void *arg) {
    while (1) {
        int ticks = gpioTick(FLOW_SENSOR_PIN);
        if (ticks > 0) {
            pthread_mutex_lock(&pulse_mutex);
            pulse_count += ticks;
            pthread_mutex_unlock(&pulse_mutex);
        }
    }
    return NULL;
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        exit(1);
    }
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - %s\n",
            now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
            now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, message);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(SOLENOID_PIN, PI_ON) < 0) {
        fprintf(stderr, "Failed to set solenoid initial state.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, isr_handler, 0, DEBOUNCE_TIMEOUT) < 0) {
        fprintf(stderr, "Failed to set ISR function for flow sensor.\n");
        gpioTerminate();
        return 1;
    }

    pthread_t isr_thread;
    if (pthread_create(&isr_thread, NULL, isr_handler, NULL) != 0) {
        fprintf(stderr, "Failed to create ISR thread.\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = (double)pulses / 450.0 * 60.0;
        log_message(lpm > 5.0 ? "Solenoid closed" : "Solenoid open");

        if (lpm > 5.0) {
            if (gpioWrite(SOLENOID_PIN, PI_OFF) < 0) {
                fprintf(stderr, "Failed to close solenoid.\n");
            }
        } else if (lpm < 4.5) {
            if (gpioWrite(SOLENOID_PIN, PI_ON) < 0) {
                fprintf(stderr, "Failed to open solenoid.\n");
            }
        }

        sleep(1);
    }

    pthread_cancel(isr_thread);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    return 0;
}

