#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <time.h>
#include <pigpio.h>

#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define MAX_WEIGHT_READINGS 1000
#define SERVO_PIN 18
#define LOAD_CELL_DATA_PIN 23
#define LOAD_CELL_SCK_PIN 24
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345

typedef struct {
    double calibration_factor;
    char server_ip[16];
    int server_port;
} Config;

Config config = {
    .calibration_factor = DEFAULT_CALIBRATION_FACTOR,
    .server_ip = DEFAULT_SERVER_IP,
    .server_port = DEFAULT_SERVER_PORT
};

void read_config(void) {
    FILE *config_file = fopen(CONFIG_FILE, "r");
    if (config_file == NULL) {
        printf("Config file not found, using defaults.\n");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), config_file)) {
        if (sscanf(line, "calibration_factor=%lf", &config.calibration_factor) == 1) {
            printf("Read calibration factor: %f\n", config.calibration_factor);
        } else if (sscanf(line, "server_ip=%15s", config.server_ip) == 1) {
            printf("Read server IP: %s\n", config.server_ip);
        } else if (sscanf(line, "server_port=%d", &config.server_port) == 1) {
            printf("Read server port: %d\n", config.server_port);
        }
    }

    fclose(config_file);
}

void handle_signal(int signum) {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO.\n");
    }
    if (close(servo_fd) < 0) {
        printf("Failed to close servo file descriptor.\n");
    }
    if (close(server_fd) < 0) {
        printf("Failed to close server socket.\n");
    }
    exit(signum);
}

void setup_signals(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

void setup_servo(void) {
    int servo_fd = gpioServo(SERVO_PIN, 1500, 2000);
    if (servo_fd < 0) {
        printf("Failed to set up servo on GPIO %d.\n", SERVO_PIN);
        exit(1);
    }
}

void setup_load_cell(void) {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO.\n");
        exit(1);
    }
    gpioSetMode(LOAD_CELL_DATA_PIN, PI_INPUT);
    gpioSetMode(LOAD_CELL_SCK_PIN, PI_OUTPUT);
}

double read_load_cell(void) {
    int count = 0;
    unsigned long long data = 0;
    while (count < MAX_WEIGHT_READINGS) {
        if (gpioRead(LOAD_CELL_DATA_PIN)) {
            data |= 1ULL << count;
        }
        gpioWrite(LOAD_CELL_SCK_PIN, 1);
        usleep(1000);
        gpioWrite(LOAD_CELL_SCK_PIN, 0);
        usleep(1000);
        count++;
    }
    if (count == MAX_WEIGHT_READINGS) {
        printf("Timeout reading from load cell.\n");
        return -1.0;
    }
    return (double)data * config.calibration_factor;
}

void dispense_ingredient(double target_weight) {
    setup_servo();
    setup_load_cell();

    double actual_weight = -1.0;
    while (actual_weight < target_weight) {
        actual_weight = read_load_cell();
        if (actual_weight < 0.0) {
            printf("Failed to read weight from load cell.\n");
            break;
        }
        printf("Actual weight: %f\n", actual_weight);
    }

    if (actual_weight >= 0.0) {
        double pulse_width = 1000 + (actual_weight / 1000.0) * 1000;
        if (gpioServo(SERVO_PIN, pulse_width, pulse_width) < 0) {
            printf("Failed to control servo.\n");
        }
    }

    gpioTerminate();
}

int main(void) {
    read_config();
    setup_signals();

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        printf("Failed to create server socket.\n");
        exit(1);
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(config.server_port);
    server_addr.sin_addr.s_addr = inet_addr(config.server_ip);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        printf("Failed to bind server socket.\n");
        exit(1);
    }

    if (listen(server_fd, 5) < 0) {
        printf("Failed to listen on server socket.\n");
        exit(1);
    }

    printf("Server listening on %s:%d\n", config.server_ip, config.server_port);

    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            printf("Failed to accept client connection.\n");
            continue;
        }

        char buffer[1024];
        int bytes_read = recv(client_fd, buffer, sizeof(buffer), 0);
        if (bytes_read <= 0) {
            printf("Failed to receive target weight from client.\n");
            close(client_fd);
            continue;
        }

        double target_weight = atof(buffer);
        if (target_weight <= 0.0) {
            printf("Invalid target weight received: %s\n", buffer);
            close(client_fd);
            continue;
        }

        printf("Received target weight: %f\n", target_weight);

        dispense_ingredient(target_weight);

        close(client_fd);
    }

    return 0;
}

