#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define DEBOUNCE_MS 50
#define GPIO_RELAY 17
#define GPIO_TOUCH 4

volatile int relay_state = 0;
volatile int last_touch_state = 0;
volatile int touch_debounce_timer = 0;
volatile int debounce_ms = DEBOUNCE_MS;

void handle_signal(int signum) {
    if (relay_state) {
        gpioWrite(GPIO_RELAY, 0);
        printf("SIGINT/SIGTERM received. Relay: OFF\n");
    }
    gpioTerminate();
    exit(signum == SIGINT ? 0 : 1);
}

void check_touch_and_toggle_relay() {
    int touch_state = gpioRead(GPIO_TOUCH);

    if (touch_state != last_touch_state) {
        touch_debounce_timer = debounce_ms;
        last_touch_state = touch_state;
    }

    if (touch_debounce_timer > 0) {
        touch_debounce_timer--;
    } else if (touch_state == 1) {
