        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(GPIO_TOUCH, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for touch sensor.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        check_touch_and_toggle_relay();
        usleep(10000); // Sleep for 10 ms
    }

    return 0;
