#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_STEP 10
#define SERVO_FREQ 50
#define SERVO_PERIOD (1000000 / SERVO_FREQ)

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

void set_servo_angle(int angle) {
    int pulse_width = SERVO_MIN_PULSE + ((angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE)) / 180);
    if (pulse_width < SERVO_MIN_PULSE) {
        pulse_width = SERVO_MIN_PULSE;
    } else if (pulse_width > SERVO_MAX_PULSE) {
        pulse_width = SERVO_MAX_PULSE;
    }
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    struct termios oldt, newt;
    int angle = 90;

    // Initialize terminal settings
    tcgetattr(STDIN_FILENO, &oldt);
    newt = oldt;
    newt.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &newt);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Set initial servo angle
    set_servo_angle(angle);
    printf("Initial angle: %d°\n", angle);

    while (!stop_flag) {
        char c = getchar();
        switch (c) {
            case '+':
                angle += SERVO_STEP;
                if (angle > 180) {
                    angle = 180;
                }
                set_servo_angle(angle);
                printf("Angle: %d°\n", angle);
                break;
            case '-':
                angle -= SERVO_STEP;
                if (angle < 0) {
                    angle = 0;
                }
                set_servo_angle(angle);
                printf("Angle: %d°\n", angle);
                break;
            case 'q':
            case 'Q':
                stop_flag = 1;
                break;
        }
    }

    // Stop PWM and clean up
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();

    // Restore terminal settings
    tcsetattr(STDIN_FILENO, TCSANOW, &oldt);

    return 0;
}

