#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_LINE 17
#define DEBOUNCE_MS 2
#define LOG_FILE "motor_rpm.log"

static gpiod_chip *chip;
static gpiod_line *line;
static FILE *log_file;

static void handle_signal(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct timespec start_time, end_time;
    double elapsed_time;
    int pulse_count = 0;
    double rpm = 0.0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    if ((line = gpiod_chip_get_line(chip, GPIO_LINE)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input_flags(line, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        pulse_count = 0;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        while (1) {
            int ret = gpiod_line_event_wait(line, DEBOUNCE_MS);
            if (ret < 0) {
                perror("gpiod_line_event_wait");
                break;
            }
            pulse_count++;
        }

        clock_gettime(CLOCK_MONOTONIC, &end_time);
        elapsed_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;

        if (elapsed_time >= 5.0) {
            rpm = (pulse_count / elapsed_time) * 60.0;
            fprintf(log_file, "%s,%f\n", ctime(&start_time.tv_sec), rpm);
            fflush(log_file);
            printf("Current RPM: %.2f\n", rpm);
        }
    }

    return 0;
}

