#include <stdio.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(17, PI_OUTPUT); // Relay GPIO
    gpioWrite(17, 0); // Initially off

    gpioSetMode(4, PI_INPUT); // Touch sensor GPIO

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int relay_state = 0;
    int touch_sensor_state = 0;
    int touch_sensor_last_state = 0;
    int touch_sensor_high_count = 0;
    int touch_sensor_high_timeout = 0;

    while (!exit_flag) {
        touch_sensor_state = gpioRead(4);

        if (touch_sensor_state == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading touch sensor GPIO\n");
            exit(1);
        }

        if (touch_sensor_state != touch_sensor_last_state) {
            touch_sensor_last_state = touch_sensor_state;
            touch_sensor_high_count = 0;
            touch_sensor_high_timeout = 0;
        }

        if (touch_sensor_state == 1) {
            touch_sensor_high_count++;
            touch_sensor_high_timeout++;
        } else {
            touch_sensor_high_count = 0;
            touch_sensor_high_timeout = 0;
        }

        if (touch_sensor_high_timeout > 200) { // 10 seconds @ 50ms intervals
            relay_state = 0;
            touch_sensor_high_timeout = 0;
        }

        if (touch_sensor_state == 1 && touch_sensor_last_state == 0) {
            relay_state = !relay_state;
            gpioWrite(17, relay_state);
        }

        usleep(50000); // 50ms delay
    }

    gpioWrite(17, 0); // Ensure relay is off before cleanup
    gpioTerminate();

    return 0;
}

