#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define TARGET_FLOW_RATE_ARG "-t"
#define TARGET_FLOW_RATE_DEFAULT 5.0
#define PWM_PIN 18
#define ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24
#define INTERVAL_MS 100
#define Kp 1.0
#define PULSES_PER_LITRE 450
#define FILE_NAME "flow_log.csv"

volatile int pulse_count = 0;
double target_flow_rate = TARGET_FLOW_RATE_DEFAULT;
double flow_rate = 0.0;
int valve_position = 0;
FILE *log_file = NULL;

void handle_interrupt(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (log_file) {
            fclose(log_file);
        }
        gpioWrite(ENABLE_PIN, PI_OUTPUT_LOW);
        gpioPWM(PWM_PIN, 0);
        pigpioStop();
        exit(0);
    }
}

void flow_sensor_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_count++;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    double flow_rate_per_second = 0.0;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate <= 0.0) {
                    fprintf(stderr, "Invalid target flow rate. Must be positive.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM pin mode.\n");
        return 1;
    }

    if (gpioSetMode(ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set enable pin mode.\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode.\n");
        return 1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set flow sensor pin pull-up/down.\n");
        return 1;
    }

    if (gpioSetISRFunc(FLOW_SENSOR_PIN, PI_RISING_EDGE, flow_sensor_callback, 0) < 0) {
        fprintf(stderr, "Failed to set flow sensor interrupt.\n");
        return 1;
    }

    if ((log_file = fopen(FILE_NAME, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    fprintf(log_file, "timestamp_ms,flow_rate,valve_position\n");

    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    while (1) {
        usleep(INTERVAL_MS * 1000);

        flow_rate_per_second = (double)pulse_count / (INTERVAL_MS / 1000.0) * 60.0 / PULSES_PER_LITRE;
        pulse_count = 0;

        flow_rate = flow_rate_per_second;
        valve_position = (int)((target_flow_rate - flow_rate) * Kp);
        valve_position = (valve_position < 0) ? 0 : (valve_position > 255) ? 255 : valve_position;

        gpioWrite(ENABLE_PIN, PI_OUTPUT_HIGH);
        gpioPWM(PWM_PIN, valve_position);

        fprintf(log_file, "%ld,%f,%d\n", pigpioGetTimeInMilli(), flow_rate, valve_position);
    }

    if (log_file) {
        fclose(log_file);
    }

    gpioWrite(ENABLE_PIN, PI_OUTPUT_LOW);
    gpioPWM(PWM_PIN, 0);
    pigpioStop();

    return 0;
}

