#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define RFID_TAG {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A}
#define LOCK_GPIO_17 17
#define LOCK_GPIO_27 27
#define BUTTON_GPIO_22 22
#define DEBOUNCE_TIME 50000
#define AUTH_TIME 5000000

volatile sig_atomic_t shutdown = 0;

void log_access_attempt(const char *message) {
    FILE *log_file = fopen("/var/log/door_access.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", now_tm);

    fprintf(log_file, "%s - %s\n", timestamp, message);
    fclose(log_file);
}

void handle_signal(int signum) {
    shutdown = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetMode(LOCK_GPIO_17, PI_OUTPUT);
    gpioWrite(LOCK_GPIO_17, PI_ON);
    gpioSetMode(LOCK_GPIO_27, PI_OUTPUT);
    gpioWrite(LOCK_GPIO_27, PI_ON);

    gpioSetMode(BUTTON_GPIO_22, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO_22, PI_PUD_UP);

    int spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!shutdown) {
        if (gpioRead(BUTTON_GPIO_22) == PI_OFF) {
            gpioDelay(DEBOUNCE_TIME);
            if (gpioRead(BUTTON_GPIO_22) == PI_OFF) {
                uint8_t tag_read[10];
                int bytes_read = spiXfer(spi_fd, tag_read, 10, tag_read);

                if (bytes_read != 10) {
                    log_access_attempt("RFID read failure");
                    continue;
                }

                if (memcmp(tag_read, RFID_TAG, 10) == 0) {
                    log_access_attempt("Successful authentication");
                    gpioWrite(LOCK_GPIO_17, PI_OFF);
                    gpioWrite(LOCK_GPIO_27, PI_OFF);
                    gpioDelay(AUTH_TIME);
                    gpioWrite(LOCK_GPIO_17, PI_ON);
                    gpioWrite(LOCK_GPIO_27, PI_ON);
                } else {
                    log_access_attempt("Invalid RFID tag");
                }
            } else {
                log_access_attempt("Button press without valid tag");
            }
        }
    }

    spiClose(spi_fd);
    gpioTerminate();
    return 0;
}

