#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>

#define TARGET_RPM 60.0
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME 100 // ms
#define PWM_FREQ 100 // Hz
#define PWM_PERIOD (1000000 / PWM_FREQ) // us

// Motor GPIOs
#define ENA_PIN 23
#define IN1_PIN 24
#define IN2_PIN 25
#define ENB_PIN 12
#define IN3_PIN 16
#define IN4_PIN 20

// Encoder GPIOs
#define ENC1_A_PIN 5
#define ENC1_B_PIN 6
#define ENC2_A_PIN 26
#define ENC2_B_PIN 19

// PID variables
double prev_error[2] = {0, 0};
double integral[2] = {0, 0};
double current_speed[2] = {0, 0};
double target_speed[2] = {TARGET_RPM, TARGET_RPM};

// Mutex for encoder counts
pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

// Encoder counts
volatile int encoder_count[2] = {0, 0};

// File for logging
FILE *log_file;

// Function prototypes
void *encoder_thread(void *arg);
void pid_control(int motor);
void handle_signal(int signum);

// Global variables for libgpiod
struct gpiod_chip *chip;
struct gpiod_line *ena_line[2], *in1_line[2], *in2_line[2];
struct gpiod_line *enc_a_line[2];
struct gpiod_event_trigger *enc_a_trigger[2];

// Function to initialize libgpiod
int init_gpiod() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    // Motor lines
    ena_line[0] = gpiod_line_request(chip, ENA_PIN, "ENA_PIN", 0);
    in1_line[0] = gpiod_line_request(chip, IN1_PIN, "IN1_PIN", 0);
    in2_line[0] = gpiod_line_request(chip, IN2_PIN, "IN2_PIN", 0);
    ena_line[1] = gpiod_line_request(chip, ENB_PIN, "ENB_PIN", 0);
    in1_line[1] = gpiod_line_request(chip, IN3_PIN, "IN3_PIN", 0);
    in2_line[1] = gpiod_line_request(chip, IN4_PIN, "IN4_PIN", 0);

    // Encoder lines
    enc_a_line[0] = gpiod_line_request(chip, ENC1_A_PIN, "ENC1_A_PIN", 0);
    enc_a_line[1] = gpiod_line_request(chip, ENC2_A_PIN, "ENC2_A_PIN", 0);

    // Set up edge events for encoders
    enc_a_trigger[0] = gpiod_line_request_event(enc_a_line[0], "ENC1_A_TRIGGER", GPIOD_LINE_BOTH_EDGES);
    enc_a_trigger[1] = gpiod_line_request_event(enc_a_line[1], "ENC2_A_TRIGGER", GPIOD_LINE_BOTH_EDGES);

    return 0;
}

// Function to handle encoder events
void *encoder_thread(void *arg) {
    int motor = *(int *)arg;
    struct gpiod_event_trigger *trigger = enc_a_trigger[motor];
    struct gpiod_line *b_line = gpiod_line_request(chip, motor == 0 ? ENC1_B_PIN : ENC2_B_PIN, "ENC_B_PIN", 0);

    while (1) {
        struct gpiod_event *event = gpiod_event_get(trigger);
        if (!event) {
            perror("Failed to get encoder event");
            continue;
        }

        int b_value = gpiod_line_get_value(b_line);
        int direction = (event->value == 1) ^ (b_value == 1);

        pthread_mutex_lock(&encoder_mutex);
        encoder_count[motor] += direction ? 1 : -1;
        pthread_mutex_unlock(&encoder_mutex);

        gpiod_event_put(event);
    }

    return NULL;
}

// Function to control the PID for each motor
void pid_control(int motor) {
    double error = target_speed[motor] - current_speed[motor];
    double derivative = (error - prev_error[motor]) / (SAMPLE_TIME / 1000.0);
    integral[motor] += error * (SAMPLE_TIME / 1000.0);

    double output = KP * error + KI * integral[motor] + KD * derivative;

    // Limit output to 0-100% duty cycle
    output = fmax(0.0, fmin(100.0, output));

    // Set PWM duty cycle
    gpiod_line_set_value(ena_line[motor], 1);
    gpiod_line_set_value(in1_line[motor], output >= 50.0 ? 1 : 0);
    gpiod_line_set_value(in2_line[motor], output < 50.0 ? 1 : 0);

    // Log PID values
    fprintf(log_file, "%f, %f, %f, %f\n", current_speed[motor], error, integral[motor], derivative);
    fflush(log_file);

    prev_error[motor] = error;
}

// Function to handle signals
void handle_signal(int signum) {
    for (int i = 0; i < 2; i++) {
        gpiod_line_free(ena_line[i]);
        gpiod_line_free(in1_line[i]);
        gpiod_line_free(in2_line[i]);
        gpiod_line_free(enc_a_line[i]);
        gpiod_event_trigger_free(enc_a_trigger[i]);
    }

    gpiod_chip_put(chip);
    fclose(log_file);
    exit(signum);
}

int main() {
    if (init_gpiod() < 0) {
        return -1;
    }

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    // Write header row
    fprintf(log_file, "Motor,Speed,Error,Integral,Derivative\n");

    // Start encoder threads
    pthread_t encoder_thread1, encoder_thread2;
    pthread_create(&encoder_thread1, NULL, encoder_thread, (void *)0);
    pthread_create(&encoder_thread2, NULL, encoder_thread, (void *)1);

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main control loop
    while (1) {
        // Read encoder counts
        pthread_mutex_lock(&encoder_mutex);
        current_speed[0] = (encoder_count[0] * 60.0) / (600.0 * (SAMPLE_TIME / 1000.0));
        current_speed[1] = (encoder_count[1] * 60.0) / (600.0 * (SAMPLE_TIME / 1000.0));
        encoder_count[0] = encoder_count[1] = 0;
        pthread_mutex_unlock(&encoder_mutex);

        // PID control
        pid_control(0);
        pid_control(1);

        // Sleep for the sample time
        usleep(SAMPLE_TIME * 1000);
    }

    return 0;
}

