#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MPR121_I2C_ADDR 0x5A
#define MPR121_SOFT_RESET 0x01
#define MPR121_CONFIG_REG 0x02
#define MPR121_THRESH_REG 0x03
#define MPR121_TOUCH_STATUS_REG 0x00
#define MPR121_RELEASE_STATUS_REG 0x01
#define GPIO_PIN 17
#define LOG_FILE "relay_log.txt"

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    gpioWrite(GPIO_PIN, PI_OUTPUT_LOW);
    printf("Received SIGINT, shutting down relay and closing I2C handle.\n");
    exit(0);
}

int main() {
    int i2c_handle = -1;
    int status = 0;
    char log_buffer[100];
    FILE *log_file = fopen(LOG_FILE, "w");

    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        fclose(log_file);
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, PI_OUTPUT_LOW);

    i2c_handle = i2cOpen(1, MPR121_I2C_ADDR, 0);
    if (i2c_handle == -1) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Soft reset
