#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define GPIO_VALVE1 17
#define GPIO_VALVE2 18
#define LOG_FILE "valve_log.txt"

gpiod_chip *chip;
gpiod_line *valve1, *valve2;
FILE *log_file;

void log_valve_event(const char *valve_name, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s %s at %s\n", buffer, valve_name, state ? "ON" : "OFF");
    fflush(log_file);
}

void handle_signal(int signum) {
    gpiod_line_free(valve1);
    gpiod_line_free(valve2);
    gpiod_chip_put(chip);
    fclose(log_file);
    exit(signum);
}

int main() {
    int err;

    // Initialize logging
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize gpiod chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return 1;
    }

    // Request GPIO lines
    valve1 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_VALVE1, "Valve1", 0);
    if (!valve1) {
        perror("Failed to request GPIO line for Valve1");
        gpiod_chip_put(chip);
        fclose(log_file);
        return 1;
    }

    valve2 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_VALVE2, "Valve2", 0);
    if (!valve2) {
        perror("Failed to request GPIO line for Valve2");
        gpiod_line_free(valve1);
        gpiod_chip_put(chip);
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Run the valve schedule indefinitely
    while (1) {
        gpiod_line_set_value(valve1, 1);
        log_valve_event("Valve1", 1);
        usleep(500000); // 500 ms
        gpiod_line_set_value(valve1, 0);
        log_valve_event("Valve1", 0);
        sleep(5); // 5 seconds

        gpiod_line_set_value(valve2, 1);
        log_valve_event("Valve2", 1);
        usleep(1000000); // 1000 ms
        gpiod_line_set_value(valve2, 0);
        log_valve_event("Valve2", 0);
        sleep(10); // 10 seconds
    }

    // This point is never reached due to the infinite loop
    return 0;
}

