#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <mpr121.h>

#define MPR121_I2C_ADDR 0x5A
#define MPR121_I2C_BUS 1
#define GPIO_RELAY 17
#define GPIO_SDA 2
#define GPIO_SCL 3

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int main() {
    int i2c_fd;
    int relay_state = 0;
    uint8_t touch_status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO17 as output
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" MPR121_I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd, MPR121_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set touch and release thresholds
    if (mpr121_set_thresholds(i2c_fd, 0x10, 0x0A) < 0) {
        fprintf(stderr, "Failed to set touch thresholds\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure filter/charge time and electrode current
    if (mpr121_set_config(i2c_fd, 0x20, 0x01) < 0) {
        fprintf(stderr, "Failed to set configuration\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Enter run mode
    if (mpr121_run_mode(i2c_fd, 0x20) < 0) {
        fprintf(stderr, "Failed to enter run mode\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Wait for stabilization
    usleep(100000);

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        // Read touch status
        if (mpr121_read_touch_status(i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Toggle relay if any electrode is touched
        if (touch_status > 0) {
            relay_state = !relay_state;
            if (gpioWrite(GPIO_RELAY, relay_state) < 0) {
                fprintf(stderr, "Failed to toggle relay\n");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }
            printf("Relay toggled: %s\n", relay_state ? "ON" : "OFF");
        }

        // Delay for 100 ms
        usleep(100000);
    }

    // Graceful shutdown
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

