#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIR 17
#define GPIO_RELAY 18
#define LOG_FILE "door_events.log"
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_MS 50

volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int signum) {
    exit_flag = 1;
}

void log_event(const char *event, int timestamp_ms) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%d %s\n", timestamp_ms, event);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(GPIO_PIR, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIR, PI_PUD_DOWN);

    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, PI_OFF);

    signal(SIGINT, handle_sigint);

    int last_state = 0;
    int last_motion_timestamp = 0;

    while (!exit_flag) {
        int current_state = gpioRead(GPIO_PIR);

        if (current_state != last_state) {
            int timestamp_ms = (int)(pigpioGetTime() * 1000);

            if (current_state == 1 && last_state == 0) {
                // Rising edge detected, motion detected
                if (timestamp_ms - last_motion_timestamp >= RATE_LIMIT_MS) {
                    log_event("Motion detected", timestamp_ms);
                    last_motion_timestamp = timestamp_ms;

                    // Unlock door
                    gpioWrite(GPIO_RELAY, PI_ON);
                    usleep(500000); // 500 ms
                    gpioWrite(GPIO_RELAY, PI_OFF);

                    log_event("Door unlocked", timestamp_ms);
                } else {
                    log_event("Rate-limited", timestamp_ms);
                }
            }

            last_state = current_state;
        }

        usleep(POLL_INTERVAL_MS * 1000); // Sleep for 50 ms
    }

    // Cleanup
    gpioWrite(GPIO_RELAY, PI_OFF);
    gpioTerminate();
    fclose(fopen(LOG_FILE, "w")); // Clear log file on exit

    return 0;
}

