#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define DATA_PIN 4
#define CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define CALIBRATION_THRESHOLD 10.0
#define CALIBRATION_READINGS 100
#define CALIBRATION_INTERVAL 500000 // 0.5 seconds

double scale_factor = 1.0;
double offset = 0.0;

void handle_sigint(int signum) {
    gpioTerminate();
    fclose(stdout);
    fclose(stderr);
    exit(0);
}

void read_calibration() {
    FILE *file = fopen(CALIBRATION_FILE, "r");
    if (file == NULL) {
        printf("Calibration file not found, using default values.\n");
        return;
    }

    if (fscanf(file, "%lf %lf", &scale_factor, &offset) != 2) {
        printf("Invalid calibration data in file, using default values.\n");
        fclose(file);
        return;
    }

    fclose(file);
}

void save_calibration() {
    FILE *file = fopen(CALIBRATION_FILE, "w");
    if (file == NULL) {
        perror("Failed to open calibration file for writing");
        return;
    }

    fprintf(file, "%.6f %.6f\n", scale_factor, offset);
    fclose(file);
}

void startup_calibration() {
    double sum = 0.0;
    for (int i = 0; i < CALIBRATION_READINGS; i++) {
        long raw_value = gpioRead(DATA_PIN, CLOCK_PIN, CALIBRATION_INTERVAL);
        if (raw_value == -1) {
            printf("Timeout reading HX711 data.\n");
            continue;
        }
        sum += raw_value;
    }

    offset = sum / CALIBRATION_READINGS;
    printf("Startup calibration offset: %.6f\n", offset);
    save_calibration();
}

long read_hx711() {
    return gpioRead(DATA_PIN, CLOCK_PIN, 500000); // 0.5 seconds timeout
}

double convert_to_weight(long raw_value) {
    return (raw_value - offset) * scale_factor;
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    read_calibration();
    startup_calibration();

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        long raw_value = read_hx711();
        if (raw_value == -1) {
            printf("Timeout reading HX711 data.\n");
            continue;
        }

        double weight = convert_to_weight(raw_value);
        printf("Weight: %.2f kg\n", weight);

        if (weight > CALIBRATION_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, PI_HIGH);
            printf("Lock engaged.\n");
        } else {
            gpioWrite(SOLENOID_PIN, PI_LOW);
            printf("Lock released.\n");
        }

        time_t rawtime;
        struct tm * timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        fprintf(log_file, "%s Weight: %.2f kg\n", asctime(timeinfo), weight);

        usleep(500000); // 500 ms
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

