#define GPIO_RAIN_SENSOR 4
#define GPIO_IN1 17
#define GPIO_IN2 18
#define GPIO_PWM_ENABLE 27
#define DEBOUNCE_COUNT 5
#define DEBOUNCE_INTERVAL 50
#define MOTOR_RUN_TIME 5000
#define CHECK_INTERVAL 60000

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

void log_event(const char *event) {
    time_t now;
    struct tm *now_tm;
    char buffer[80];

    now = time(NULL);
    now_tm = localtime(&now);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", now_tm);
    syslog(LOG_INFO, "%s: %s", buffer, event);
}

int main() {
    int i, j, rain_count = 0;
    int rain_sensor_value;
    int motor_running = 0;

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    gpioSetMode(GPIO_RAIN_SENSOR, PI_INPUT);
    gpioSetMode(GPIO_IN1, PI_OUTPUT);
    gpioSetMode(GPIO_IN2, PI_OUTPUT);
    gpioSetMode(GPIO_PWM_ENABLE, PI_OUTPUT);

    gpioSetPWMfrequency(GPIO_PWM_ENABLE, 1000);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        for (i = 0; i < DEBOUNCE_COUNT; i++) {
            rain_sensor_value = gpioRead(GPIO_RAIN_SENSOR);
            if (rain_sensor_value == 0) {
                rain_count++;
            }
            usleep(DEBOUNCE_INTERVAL * 1000);
        }

        if (rain_count >= 3) {
            if (!motor_running) {
                motor_running = 1;
                log_event("Rain detected, closing window");
                gpioWrite(GPIO_IN1, 1);
                gpioWrite(GPIO_IN2, 0);
                gpioPWM(GPIO_PWM_ENABLE, 150);
                sleep(MOTOR_RUN_TIME / 1000);
                gpioWrite(GPIO_IN1, 0);
                gpioWrite(GPIO_IN2, 0);
                gpioPWM(GPIO_PWM_ENABLE, 0);
                motor_running = 0;
                log_event("Window closed");
            }
        } else {
            rain_count = 0;
        }

        usleep(CHECK_INTERVAL * 1000);
    }

    if (motor_running) {
        gpioWrite(GPIO_IN1, 0);
        gpioWrite(GPIO_IN2, 0);
        gpioPWM(GPIO_PWM_ENABLE, 0);
    }

    gpioTerminate();
    return 0;
}

