#define LOG_FILE "stock_events.txt"

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - %s\n", buffer, message);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpioSetMode(LOAD_CELL_DT_PIN, PI_INPUT);
    gpioSetMode(LOAD_CELL_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        int weight = 0;
        int timeout = 0;
        int stuck_high = 0;

        // Read weight from HX711
        while (timeout < 1000) {
            if (gpioRead(LOAD_CELL_DT_PIN) == 1) {
                stuck_high = 1;
                break;
            }

            if (gpioRead(LOAD_CELL_SCK_PIN) == 0) {
                timeout = 0;
                while (gpioRead(LOAD_CELL_SCK_PIN) == 0) {
                    weight = (weight << 1) | gpioRead(LOAD_CELL_DT_PIN);
                    timeout++;
                    if (timeout >= 1000) {
                        break;
                    }
                }
            } else {
                timeout++;
            }
        }

        if (stuck_high) {
            fprintf(stderr, "Load cell data line stuck high.\n");
            continue;
        }

        if (timeout >= 1000) {
            fprintf(stderr, "Timeout reading load cell.\n");
            continue;
        }

        // Check weight and activate solenoid if necessary
        if (weight < LOW_WEIGHT_THRESHOLD) {
            if (gpioWrite(SOLENOID_PIN, 1) < 0) {
                fprintf(stderr, "Failed to activate solenoid.\n");
            } else {
                log_event("Solenoid activated due to low weight.");
                sleep(5);
                if (gpioWrite(SOLENOID_PIN, 0) < 0) {
                    fprintf(stderr, "Failed to deactivate solenoid.\n");
                }
            }
        }

        usleep(1000000); // Sleep for 1 second
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();

    return 0;
}

