#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG "security.log"
#define MAX_TIMEOUT 100000 // 100 ms in microseconds

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int read_hx711(int data_pin, int clock_pin) {
    int i, count = 0;
    unsigned long long raw_value = 0;
    unsigned char data;

    piHiPri(50); // Set priority to 50

    for (i = 0; i < 24; i++) {
        piWrite(clock_pin, 0);
        usleep(1); // Clock low delay
        piWrite(clock_pin, 1);
        usleep(1); // Clock high delay
        data = piRead(data_pin);
        raw_value = (raw_value << 1) | (data & 1);
        count++;

        if (count > MAX_TIMEOUT) {
            fprintf(stderr, "Timeout reading HX711 data.\n");
            return -1;
        }
    }

    piHiPri(0); // Reset priority

    return (int16_t)raw_value;
}

void calibrate_hx711() {
    int raw_value;
    float known_weight;
    FILE *calibration_file;

    printf("Place a known weight on the load cell (in kg): ");
    scanf("%f", &known_weight);

    raw_value = read_hx711(DATA_PIN, CLOCK_PIN);
    if (raw_value == -1) {
        fprintf(stderr, "Failed to read raw value during calibration.\n");
        return;
    }

    float calibration_factor = (float)raw_value / known_weight;

    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Failed to open calibration file.\n");
        return;
    }

    fprintf(calibration_file, "%f\n", calibration_factor);
    fclose(calibration_file);

    printf("Calibration factor saved to %s.\n", CALIBRATION_FILE);
}

void main_loop() {
    int raw_value;
    float weight;
    FILE *security_log;
    time_t rawtime;
    struct tm *timeinfo;

    while (!stop) {
        raw_value = read_hx711(DATA_PIN, CLOCK_PIN);
        if (raw_value == -1) {
            continue;
        }

        weight = (float)raw_value / calibration_factor;

        if (weight > 5.0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            security_log = fopen(SECURITY_LOG, "a");
            if (security_log == NULL) {
                fprintf(stderr, "Failed to open security log file.\n");
                continue;
            }

            fprintf(security_log, "%s Weight exceeded: %.2f kg\n", asctime(timeinfo), weight);
            fclose(security_log);

            piWrite(SOLENOID_PIN, 1);
            sleep(5);
            piWrite(SOLENOID_PIN, 0);
        }

        usleep(100000); // Sleep for 100 ms
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    calibrate_hx711();

    FILE *calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Failed to open calibration file.\n");
        return 1;
    }

    fscanf(calibration_file, "%f", &calibration_factor);
    fclose(calibration_file);

    main_loop();

    piWrite(SOLENOID_PIN, 0); // Unlock solenoid
    gpioTerminate();

    return 0;
}

