#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_SENSOR 16
#define GPIO_RELAY 20
#define LOG_FILE "relay_events.log"

static void handle_error(const char *msg, int err) {
    fprintf(stderr, "%s: %s\n", msg, gpiod_get_error_string(err));
    exit(EXIT_FAILURE);
}

static void handle_signal(int signum) {
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(sensor_chip);
    gpiod_chip_close(relay_chip);
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *sensor_chip = NULL;
    struct gpiod_chip *relay_chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *relay_line = NULL;
    FILE *log_file = NULL;
    int relay_state = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip for sensor
    sensor_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!sensor_chip) {
        handle_error("Failed to open sensor GPIO chip", errno);
    }

    // Request sensor line
    sensor_line = gpiod_chip_get_line(sensor_chip, GPIO_SENSOR);
    if (!sensor_line) {
        handle_error("Failed to get sensor GPIO line", errno);
    }

    // Request sensor line as input
    if (gpiod_line_request_bulk_inputs(sensor_line, 1) < 0) {
        handle_error("Failed to request sensor GPIO line as input", errno);
    }

    // Open GPIO chip for relay
    relay_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!relay_chip) {
        handle_error("Failed to open relay GPIO chip", errno);
    }

    // Request relay line
    relay_line = gpiod_chip_get_line(relay_chip, GPIO_RELAY);
    if (!relay_line) {
        handle_error("Failed to get relay GPIO line", errno);
    }

    // Request relay line as output
    if (gpiod_line_request_bulk_outputs(relay_line, 1) < 0) {
        handle_error("Failed to request relay GPIO line as output", errno);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        handle_error("Failed to open log file", errno);
    }

    // Main loop
    while (1) {
        int sensor_value;

        // Read sensor value
        if (gpiod_line_get_value(sensor_line, &sensor_value) < 0) {
            handle_error("Failed to read sensor value", errno);
        }

        // Toggle relay state if obstacle detected
        if (sensor_value == 0) {
            relay_state = !relay_state;
            if (gpiod_line_set_value(relay_line, relay_state) < 0) {
                handle_error("Failed to set relay state", errno);
            }

            // Log event
            char timestamp[20];
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", now_tm);
            fprintf(log_file, "%s: Relay state toggled to %s\n", timestamp, relay_state ? "ON" : "OFF");
            fflush(log_file);
        }
    }

    // Cleanup
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(sensor_chip);
    gpiod_chip_close(relay_chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

