#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <signal.h>

#define BUZZER_PIN 18
#define PIR_PIN 17
#define LOG_FILE "motion_log.txt"

static gpiod_chip *chip;
static gpiod_line *pir_line, *buzzer_line;

void handle_signal(int signum) {
    gpiod_line_set_value(pir_line, 0);
    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_free(pir_line);
    gpiod_line_free(buzzer_line);
    gpiod_chip_put(chip);
    exit(signum);
}

void log_motion_event(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
}

int main() {
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];

    // Initialize libgpiod
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request PIR sensor line as input
    if (gpiod_line_request(chip, PIR_PIN, "PIR_sensor", &pir_line, GPIOD_LINE_DIRECTION_IN) < 0) {
        perror("Failed to request PIR sensor line");
        exit(EXIT_FAILURE);
    }

    // Request buzzer line as output
    if (gpiod_line_request(chip, BUZZER_PIN, "Buzzer", &buzzer_line, GPIOD_LINE_DIRECTION_OUT) < 0) {
        perror("Failed to request buzzer line");
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        if (gpiod_line_get_value(pir_line) == 1) {
            clock_gettime(CLOCK_REALTIME, &ts);
            tm = localtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            log_motion_event(timestamp);

            // Activate buzzer for 2 seconds
            gpiod_line_set_value(buzzer_line, 1);
            usleep(2000000);
            gpiod_line_set_value(buzzer_line, 0);
        }
    }

    // Cleanup
    handle_signal(0);

    return 0;
}

