#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

volatile sig_atomic_t stop_requested = 0;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        stop_requested = 1;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    char buffer[128];
    int duration = 0;

    // Initialize libgpiod
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO18 as output
    if (gpiod_line_request_by_name(chip, "gpio18", "Timed Watering Valve", 0, &line) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set active-low and default output value
    if (gpiod_line_set_active_low(line, 0) < 0 || gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to configure GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Read duration from 'watering.conf'
    FILE *file = fopen("watering.conf", "r");
    if (file == NULL) {
        perror("Failed to open configuration file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (fgets(buffer, sizeof(buffer), file) == NULL) {
        fprintf(stderr, "Configuration file is empty\n");
        fclose(file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (sscanf(buffer, "duration=%d", &duration) != 1 || duration <= 0 || duration > 3600) {
        fprintf(stderr, "Invalid duration in configuration file\n");
        fclose(file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    fclose(file);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Watering duration configured: %d seconds\n", duration);

    // Activate valve
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to activate valve");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("Valve activated\n");

    // Wait for configured duration
    while (!stop_requested) {
        sleep(1);
    }

    // Deactivate valve
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to deactivate valve");
    }
    printf("Valve deactivated\n");

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

