    if (sscanf(buffer, "duration=%d", &duration) != 1 || duration <= 0 || duration > 3600) {
        fprintf(stderr, "Invalid duration in configuration file\n");
        fclose(file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    fclose(file);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Watering duration configured: %d seconds\n", duration);

    // Activate valve
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to activate valve");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("Valve activated\n");

    // Wait for configured duration
    while (!stop_requested) {
        sleep(1);
    }

    // Deactivate valve
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to deactivate valve");
    }
    printf("Valve deactivated\n");

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}
```

This C program uses the libgpiod library to control a Parker Hannifin Series 9 General Purpose Miniature Solenoid Valve connected to GPIO18 on a Raspberry Pi 3 Model B+. It reads the watering duration from a configuration file, activates the valve, waits for the specified duration, and then deactivates the valve. It handles errors, installs signal handlers for graceful shutdown, and ensures the GPIO line and chip are released on all exit paths.

