        gpioSetMode(gpio_right_sensor, PI_INPUT) < 0 ||
        gpioSetPWMrange(pwm_left_motor, 255) < 0 ||
        gpioSetPWMrange(pwm_right_motor, 255) < 0 ||
        gpioSetPWMrange(pwm_left_brake, 255) < 0 ||
        gpioSetPWMrange(pwm_right_brake, 255) < 0) {
