        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));

        int left_sensor = gpioRead(gpio_left_sensor);
        int middle_sensor = gpioRead(gpio_middle_sensor);
        int right_sensor = gpioRead(gpio_right_sensor);

        if (middle_sensor == 0) {
            // Drive straight
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 0) {
            // Turn right
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (right_sensor == 0) {
            // Turn left
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            // Stop
            left_speed = 0;
            right_speed = 0;
        }

        gpioPWM(pwm_left_motor, left_speed);
        gpioPWM(pwm_right_motor, right_speed);
        gpioPWM(pwm_left_brake, 0);
        gpioPWM(pwm_right_brake, 0);

        fprintf(log_file, "%s, %d, %d, %d, %d, %d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
        fflush(log_file);

        usleep(10000); // 10 ms delay
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

