#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_COMMAND_CONTINUOUS_HIGH_RESOLUTION 0x10
#define BH1750_MEASUREMENT_DELAY 180
#define LUX_THRESHOLD 150
#define GPIO_RELAY 23

FILE *log_file;

void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    pi_stop();
    exit(0);
}

void log_message(const char *message) {
    if (log_file) {
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d.%03d %s\n",
                timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
                (int)(rawtime % 1) * 1000, message);
        fflush(log_file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if ((log_file = fopen("grow_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int i2c_handle = i2cOpen(1, BH1750_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C bus for BH1750 sensor.");
        return 1;
    }

    if (i2cWriteReg(i2c_handle, BH1750_COMMAND_CONTINUOUS_HIGH_RESOLUTION, 0x00) < 0) {
        log_message("Failed to set BH1750 sensor to continuous high-resolution mode.");
        i2cClose(i2c_handle);
        return 1;
    }

    pi_set_mode(GPIO_RELAY, PI_OUTPUT);
    pi_write(GPIO_RELAY, 0); // Turn off relay initially

    while (1) {
        int lux = i2cReadReg(i2c_handle, 0x00, 2);
        if (lux < 0) {
            log_message("Failed to read lux value from BH1750 sensor.");
            continue;
        }

        if (lux < LUX_THRESHOLD) {
            pi_write(GPIO_RELAY, 1); // Turn on relay
            log_message("Lux reading below threshold - Relay activated.");
        } else {
            pi_write(GPIO_RELAY, 0); // Turn off relay
            log_message("Lux reading above threshold - Relay deactivated.");
        }

        log_message(lux ? "Lux reading: " : "Lux reading: 0");
        usleep(BH1750_MEASUREMENT_DELAY * 1000); // Sleep for 180 ms
    }

    return 0;
}

