#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define SERVO_PIN 18

#define LOCK_POSITION 1000
#define UNLOCK_POSITION 2000
#define DEBOUNCE_DELAY 100000  // 100 ms delay in microseconds

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistors.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioServo(SERVO_PIN, LOCK_POSITION) < 0) {
        fprintf(stderr, "Failed to set initial servo position.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (!stop) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            usleep(DEBOUNCE_DELAY);
            if (gpioRead(LOCK_BUTTON_PIN) == 0) {
                if (gpioServo(SERVO_PIN, LOCK_POSITION) < 0) {
                    fprintf(stderr, "Failed to move servo to lock position.\n");
                }
            }
        }

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            usleep(DEBOUNCE_DELAY);
            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                if (gpioServo(SERVO_PIN, UNLOCK_POSITION) < 0) {
                    fprintf(stderr, "Failed to move servo to unlock position.\n");
                }
            }
        }
    }

    gpioServo(SERVO_PIN, 0);  // Stop the servo
    gpioTerminate();

    return EXIT_SUCCESS;
}

