#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

static gpiod_chip *chip;
static gpiod_line *motor1, *motor2;

void handle_signal(int signum) {
    if (motor1) {
        gpiod_line_release(motor1);
        motor1 = NULL;
    }
    if (motor2) {
        gpiod_line_release(motor2);
        motor2 = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 ||
        sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    motor1 = gpiod_line_request(chip, MOTOR1_PIN, "Motor1", "Haptic feedback", 0);
    if (!motor1) {
        perror("gpiod_line_request (Motor1)");
        goto release_motor2;
    }

    motor2 = gpiod_line_request(chip, MOTOR2_PIN, "Motor2", "Haptic feedback", 0);
    if (!motor2) {
        perror("gpiod_line_request (Motor2)");
        goto release_motor1;
    }

    if (gpiod_line_set_value(motor1, 1) == -1) {
        perror("gpiod_line_set_value (Motor1)");
        goto release_motor2;
    }

    if (gpiod_line_set_value(motor2, 1) == -1) {
        perror("gpiod_line_set_value (Motor2)");
        goto release_motor1;
    }

    while (1) {
        usleep(200000); // 200 ms
        if (gpiod_line_set_value(motor1, 0) == -1) {
            perror("gpiod_line_set_value (Motor1)");
            goto release_motor2;
        }

        usleep(300000); // 300 ms
        if (gpiod_line_set_value(motor2, 0) == -1) {
            perror("gpiod_line_set_value (Motor2)");
            goto release_motor1;
        }
    }

release_motor1:
    gpiod_line_release(motor1);
    motor1 = NULL;

release_motor2:
    gpiod_line_release(motor2);
    motor2 = NULL;

    gpiod_chip_put(chip);
    chip = NULL;

    return 0;
}

