#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>
#include <paho-mqtt.h>

#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_SPACE_1 1690
#define NEC_SPACE_0 560
#define NEC_CHECKSUM_LEN 8

int g_mqtt_client = 0;
int g_gpio_handle = 0;

void handle_sigterm(int signum) {
    if (g_mqtt_client) {
        MQTT_Finalize(g_mqtt_client);
    }
    if (g_gpio_handle) {
        gpioTerminate();
    }
    exit(0);
}

void handle_sigint(int signum) {
    handle_sigterm(signum);
}

void ir_callback(int gpio, int level, uint32_t tick) {
    static uint32_t pulse_buffer[100];
    static int pulse_count = 0;

    if (level == 0) {
        pulse_buffer[pulse_count++] = tick;
        if (pulse_count >= 100) {
            syslog(LOG_INFO, "Pulse buffer overflow");
            pulse_count = 0;
        }
    }

    if (pulse_count >= 10) {
        uint32_t header_mark = pulse_buffer[0];
        uint32_t header_space = pulse_buffer[1];
        uint32_t address = 0;
        uint32_t command = 0;
        uint32_t checksum = 0;

        if (header_mark >= NEC_HEADER_MARK && header_space >= NEC_HEADER_SPACE) {
            for (int i = 2; i < 10; i += 2) {
                uint32_t bit_mark = pulse_buffer[i];
                uint32_t space = pulse_buffer[i + 1];

                if (space >= NEC_SPACE_1) {
                    address = (address << 1) | 1;
                    command = (command << 1) | 1;
                } else if (space >= NEC_SPACE_0) {
                    address = (address << 1);
                    command = (command << 1);
                } else {
                    syslog(LOG_INFO, "Invalid NEC frame");
                    pulse_count = 0;
                    return;
                }
            }

            checksum = (address ^ command) & 0xFF;
            if (pulse_buffer[10] == checksum) {
                char json[256];
                snprintf(json, sizeof(json), "{\"address\": %u, \"command\": %u}", address, command);
                MQTT_Publish(g_mqtt_client, "ir/decoded", strlen(json), json, 1);
            } else {
                syslog(LOG_INFO, "Invalid NEC checksum");
            }
        }

        pulse_count = 0;
    }
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    g_gpio_handle = 17; // GPIO17 (BCM)
    if (gpioSetAlertFunc(g_gpio_handle, ir_callback) < 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO %d", g_gpio_handle);
        gpioTerminate();
        return 1;
    }

    struct MQTT_Client_Options opts;
    memset(&opts, 0, sizeof(opts));
    opts.keepAliveInterval = 10;
    opts.cleansession = 1;
    opts.protocolVersion = MQTT_PV_3_1_1;
    opts.serverURI = "tcp://localhost:1883";
    opts.clientID = "ir_decoder";

    g_mqtt_client = MQTT_Init(&opts);
    if (!g_mqtt_client) {
        syslog(LOG_ERR, "Failed to initialize MQTT client");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    syslog(LOG_INFO, "NEC IR decoder started");

    while (1) {
        MQTT_Loop(g_mqtt_client, 100);
    }

    return 0;
}

