#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR_BASE 0x23
#define NUM_SENSORS 4
#define I2C_DEV "/dev/i2c-1"
#define I2C_CMD 0x20
#define I2C_DATA_LEN 2
#define UDP_ADDR "239.255.255.250"
#define UDP_PORT 5005

#define LUX_SCALE 1.2

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    exit_flag = 1;
}

int read_sensor(int fd, uint8_t addr) {
    uint8_t data[I2C_DATA_LEN];
    int ret;

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }

    if (write(fd, &I2C_CMD, 1) != 1) {
        perror("write");
        return -1;
    }

    usleep(180000); // 180 ms delay

    if ((ret = read(fd, data, I2C_DATA_LEN)) != I2C_DATA_LEN) {
        if (ret < 0) {
            perror("read");
        } else {
            fprintf(stderr, "Partial read (%d bytes)\n", ret);
        }
        return -1;
    }

    uint16_t lux = ((data[0] << 8) | data[1]) / LUX_SCALE;
    return lux;
}

int main() {
    int i2c_fd;
    int sockfd;
    struct sockaddr_in multicast_addr;
    struct ip_mreq multicast_group;
    char message[100];
    int sensor_lux[NUM_SENSORS];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        close(i2c_fd);
        return 1;
    }

    memset(&multicast_addr, 0, sizeof(multicast_addr));
    multicast_addr.sin_family = AF_INET;
    multicast_addr.sin_port = htons(UDP_PORT);
    multicast_addr.sin_addr.s_addr = inet_addr(UDP_ADDR);

    if (bind(sockfd, (struct sockaddr *)&multicast_addr, sizeof(multicast_addr)) < 0) {
        perror("bind");
        close(i2c_fd);
        close(sockfd);
        return 1;
    }

    multicast_group.imr_multiaddr.s_addr = inet_addr(UDP_ADDR);
    multicast_group.imr_interface.s_addr = htonl(INADDR_ANY);

    if (setsockopt(sockfd, IPPROTO_IP, IP_ADD_MEMBERSHIP, &multicast_group, sizeof(multicast_group)) < 0) {
        perror("setsockopt");
        close(i2c_fd);
        close(sockfd);
        return 1;
    }

    while (!exit_flag) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_lux[i] = read_sensor(i2c_fd, I2C_ADDR_BASE + i);
        }

        sprintf(message, "1,%.1f;2,%.1f;3,%.1f;4,%.1f",
                sensor_lux[0] == -1 ? 0.0 : sensor_lux[0],
                sensor_lux[1] == -1 ? 0.0 : sensor_lux[1],
                sensor_lux[2] == -1 ? 0.0 : sensor_lux[2],
                sensor_lux[3] == -1 ? 0.0 : sensor_lux[3]);

        if (sendto(sockfd, message, strlen(message), 0, (struct sockaddr *)&multicast_addr, sizeof(multicast_addr)) < 0) {
            perror("sendto");
        }

        sleep(1);
    }

    close(sockfd);
    close(i2c_fd);

    return 0;
}

