This C program reads ambient light levels from four BH1750FVI sensors connected to the I2C-1 bus on a Raspberry Pi 3 Model B+. It uses the standard Linux I2C ioctl interface to communicate with the sensors and broadcasts the readings as a UDP multicast packet every second. The program handles errors gracefully and exits cleanly on receiving SIGINT or SIGTERM signals.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x28
#define I2C_DEV "/dev/i2c-1"
#define MAX_RETRIES 3
#define RETRY_DELAY 100

static int i2c_fd = -1;
static FILE *log_file = NULL;

void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int read_flow_data() {
    int retries = 0;
    int raw_value = 0;
    char buffer[2];

    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, "", 0) == -1) {
            perror("Error writing to I2C device");
            return -1;
        }

        if (read(i2c_fd, buffer, 2) != 2) {
            if (retries < MAX_RETRIES - 1) {
                sleep(RETRY_DELAY / 1000);
                retries++;
                continue;
            } else {
                perror("Error reading from I2C device");
                return -1;
            }
        }

        raw_value = (buffer[0] << 8) | buffer[1];
        raw_value &= 0x3FFF;
        break;
    }

    return raw_value;
}

int main() {
    struct sigaction sa;
    struct timespec ts;
    int flow_value;

    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if ((log_file = fopen("airflow_log.txt", "w")) == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting SIGINT handler");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        flow_value = read_flow_data();
        if (flow_value == -1) {
            continue;
        }

        double slpm = (flow_value - 3277) * 0.1;
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d: %.2f SLPM\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, slpm);

        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

