#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>

#define I2C_ADDR 0x39
#define WHO_AM_I 0x24
#define ENABLE 0x80
#define CFG6 0xAF
#define SP_EN 0x01
#define F1 0x60
#define F8 0x67
#define CLEAR 0x68
#define NIR 0x69

#define LOG_FILE "spectral_log.csv"

int i2c_fd;

void handle_sigint(int signum) {
    close(i2c_fd);
    fclose(stdout);
    exit(0);
}

int read_i2c_register(uint8_t reg) {
    uint8_t data;
    int ret = read(i2c_fd, &data, 1);
    if (ret != 1) {
        perror("Error reading from I2C");
        return -1;
    }
    return data;
}

int write_i2c_register(uint8_t reg, uint8_t value) {
    int ret = write(i2c_fd, &value, 1);
    if (ret != 1) {
        perror("Error writing to I2C");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Verify WHO_AM_I register
    uint8_t who_am_i = read_i2c_register(WHO_AM_I);
    if (who_am_i != 0x19) {
        fprintf(stderr, "Invalid WHO_AM_I register value: 0x%02X\n", who_am_i);
        close(i2c_fd);
        return 1;
    }

    // Power on the sensor
    write_i2c_register(ENABLE, 0x01);

    // Configure SMUX for spectral readings
    write_i2c_register(CFG6, 0x00);

    // Enable spectral measurement
    write_i2c_register(CFG6, SP_EN);

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");

    while (1) {
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        uint16_t f1 = read_i2c_register(F1) << 8 | read_i2c_register(F1 + 1);
        uint16_t f2 = read_i2c_register(F2) << 8 | read_i2c_register(F2 + 1);
        uint16_t f3 = read_i2c_register(F3) << 8 | read_i2c_register(F3 + 1);
        uint16_t f4 = read_i2c_register(F4) << 8 | read_i2c_register(F4 + 1);
        uint16_t f5 = read_i2c_register(F5) << 8 | read_i2c_register(F5 + 1);
        uint16_t f6 = read_i2c_register(F6) << 8 | read_i2c_register(F6 + 1);
        uint16_t f7 = read_i2c_register(F7) << 8 | read_i2c_register(F7 + 1);
        uint16_t f8 = read_i2c_register(F8) << 8 | read_i2c_register(F8 + 1);
        uint16_t clear = read_i2c_register(CLEAR) << 8 | read_i2c_register(CLEAR + 1);
        uint16_t nir = read_i2c_register(NIR) << 8 | read_i2c_register(NIR + 1);

        // Simplified lux approximation (example)
        uint32_t lux = (f1 + f2 + f3 + f4 + f5 + f6 + f7 + f8 + clear + nir) / 10;

        fprintf(log_file, "%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d\n",
                (int)now_tm->tm_year + 1900, (int)now_tm->tm_mon + 1, (int)now_tm->tm_mday,
                (int)now_tm->tm_hour, (int)now_tm->tm_min, (int)now_tm->tm_sec,
                f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux);

        sleep(5);
    }

    fclose(log_file);
    close(i2c_fd);

    return 0;
}

