#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>

#define I2C_ADDR 0x37
#define I2C_DEV "/dev/i2c-1"
#define BUFFER_SIZE 6
#define MAX_RETRIES 3
#define BACKOFF_MS 10
#define G_SCALE 0.000244

int i2c_fd;
int i2c_addr;
int interval_sec;
char *output_filename;
FILE *csv_file;
FILE *error_log;

void handle_signal(int signum) {
    if (csv_file) {
        fclose(csv_file);
    }
    if (error_log) {
        fclose(error_log);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int i2c_read(int addr, uint8_t reg, uint8_t *buffer, int length) {
    int retries = 0;
    int result;
    do {
        result = write(i2c_fd, &reg, 1);
        if (result != 1) {
            fprintf(error_log, "Error writing register: %d\n", result);
            return -1;
        }
        result = read(i2c_fd, buffer, length);
        if (result != length) {
            fprintf(error_log, "Error reading data: %d\n", result);
            return -1;
        }
    } while (result != length && retries++ < MAX_RETRIES);
    return 0;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_addr = I2C_ADDR;
    interval_sec = 1;
    output_filename = "seismic_data.csv";

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0) {
            i2c_addr = strtol(argv[++i], NULL, 16);
        } else if (strcmp(argv[i], "-i") == 0) {
            interval_sec = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-f") == 0) {
            output_filename = argv[++i];
        }
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    csv_file = fopen(output_filename, "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    error_log = fopen("seismic_error.log", "w");
    if (!error_log) {
        perror("Failed to open error log file");
        fclose(csv_file);
        close(i2c_fd);
        return 1;
    }

    fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");

    while (1) {
        uint8_t buffer[BUFFER_SIZE];
        if (i2c_read(i2c_addr, 0x28, buffer, BUFFER_SIZE) < 0) {
            continue;
        }

        int64_t timestamp = time(NULL) * 1000 + (int64_t)clock() / (CLOCKS_PER_SEC / 1000);
        double x = (int16_t)((buffer[0] | (buffer[1] << 8)) * G_SCALE);
        double y = (int16_t)((buffer[2] | (buffer[3] << 8)) * G_SCALE);
        double z = (int16_t)((buffer[4] | (buffer[5] << 8)) * G_SCALE);

        fprintf(csv_file, "%lld,%f,%f,%f\n", timestamp, x, y, z);

        sleep(interval_sec);
    }

    fclose(csv_file);
    fclose(error_log);
    close(i2c_fd);

    return 0;
}

