#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define BH1750_ADDR 0x23
#define BH1750_POWER_ON 0x01
#define BH1750_CONTINUOUS_HIGH_RES 0x10
#define BH1750_READ_DATA 0x00
#define BH1750_MULTICAST_ADDR "239.255.255.250"
#define BH1750_MULTICAST_PORT 5000
#define BH1750_MULTICAST_TTL 1

int i2c_fd = -1;
int sock = -1;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (sock != -1) {
        close(sock);
    }
    exit(signum);
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t power_on_cmd = BH1750_POWER_ON;
    if (write(i2c_fd, &power_on_cmd, 1) != 1) {
        perror("Failed to send power-on command");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t continuous_high_res_cmd = BH1750_CONTINUOUS_HIGH_RES;
    if (write(i2c_fd, &continuous_high_res_cmd, 1) != 1) {
        perror("Failed to send continuous high-res mode command");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_socket() {
    struct sockaddr_in multicast_addr;
    struct ip_mreq multicast_request;

    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock == -1) {
        perror("Failed to create socket");
        exit(EXIT_FAILURE);
    }

    multicast_addr.sin_family = AF_INET;
    multicast_addr.sin_port = htons(BH1750_MULTICAST_PORT);
    multicast_addr.sin_addr.s_addr = inet_addr(BH1750_MULTICAST_ADDR);

    if (bind(sock, (struct sockaddr *)&multicast_addr, sizeof(multicast_addr)) == -1) {
        perror("Failed to bind socket");
        close(sock);
        exit(EXIT_FAILURE);
    }

    multicast_request.imr_multiaddr.s_addr = inet_addr(BH1750_MULTICAST_ADDR);
    multicast_request.imr_interface.s_addr = htonl(INADDR_ANY);

    if (setsockopt(sock, IPPROTO_IP, IP_ADD_MEMBERSHIP, &multicast_request, sizeof(multicast_request)) == -1) {
        perror("Failed to join multicast group");
        close(sock);
        exit(EXIT_FAILURE);
    }

    if (setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &multicast_addr, sizeof(multicast_addr)) == -1) {
        perror("Failed to set socket options");
        close(sock);
        exit(EXIT_FAILURE);
    }

    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &BH1750_MULTICAST_TTL, sizeof(BH1750_MULTICAST_TTL)) == -1) {
        perror("Failed to set multicast TTL");
        close(sock);
        exit(EXIT_FAILURE);
    }
}

void read_and_broadcast_lux() {
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read data from sensor");
        return;
    }

    uint16_t raw = (data[0] << 8) | data[1];
    float lux = (float)raw / 1.2;

    char lux_str[32];
    sprintf(lux_str, "%.2f", lux);

    if (sendto(sock, lux_str, strlen(lux_str), 0, (struct sockaddr *)&multicast_addr, sizeof(multicast_addr)) == -1) {
        perror("Failed to send data over socket");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c();
    init_socket();

    while (1) {
        read_and_broadcast_lux();
        sleep(1);
    }

    return 0;
}

