#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define UART_SPEED 921600
#define MAGIC_WORD "\x02\x04\x03\x06\x08\x05\x07\x09"
#define BUFFER_SIZE 1024

FILE *csv_file;

void handle_signal(int signum) {
    if (csv_file) {
        fclose(csv_file);
    }
    if (pi >= 0) {
        piClose();
    }
    exit(signum);
}

int main() {
    int pi = -1;
    char buffer[BUFFER_SIZE];
    int bytes_read;
    int magic_word_found = 0;
    int magic_word_index = 0;
    int object_index = 0;
    int range_m, velocity_mps;
    struct timeval tv;

    csv_file = fopen("radar_data.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open radar_data.csv\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    pi = pigpioOpen(UART_DEVICE, UART_SPEED, 0, 0);
    if (pi < 0) {
        fprintf(stderr, "Failed to open UART device\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        bytes_read = pigpioRead(pi, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART\n");
            continue;
        }

        for (int i = 0; i < bytes_read; i++) {
            if (magic_word_index < 8 && buffer[i] == MAGIC_WORD[magic_word_index]) {
                magic_word_index++;
                if (magic_word_index == 8) {
                    magic_word_found = 1;
                    magic_word_index = 0;
                }
            } else {
                magic_word_index = 0;
            }

            if (magic_word_found) {
                if (object_index < 2) {
                    range_m = (buffer[i] << 8) | buffer[i + 1];
                    velocity_mps = (buffer[i + 2] << 8) | buffer[i + 3];
                    gettimeofday(&tv, NULL);
                    fprintf(csv_file, "%ld,%d,%d,%d\n", tv.tv_sec, object_index, range_m, velocity_mps);
                    object_index++;
                    i += 3; // Skip the next 3 bytes (range and velocity)
                } else {
                    magic_word_found = 0;
                    object_index = 0;
                }
            }
        }
    }

    return 0;
}

