#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define BUFFER_SIZE 1024
#define TIMEOUT_SECONDS 2
#define INTER_BYTE_TIMEOUT 500000 // 0.5 seconds in microseconds

char line_buffer[BUFFER_SIZE];
int line_buffer_index = 0;

void handle_signal(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    close(0); // Close the UART
    exit(signum);
}

void parse_and_log_line(const char *line) {
    char timestamp[20];
    char range[10];
    sscanf(line, "%[^,],%[^,] meters", timestamp, range);
    printf("Timestamp: %s, Range: %s meters\n", timestamp, range);
}

int main() {
    struct termios options;
    struct sigaction signal_action;
    int fd;
    fd_set read_fds;
    struct timeval timeout;

    // Initialize signal handlers
    signal_action.sa_handler = handle_signal;
    signal_action.sa_flags = 0;
    sigemptyset(&signal_action.sa_mask);
    sigaction(SIGINT, &signal_action, NULL);
    sigaction(SIGTERM, &signal_action, NULL);

    // Open the UART
    fd = open("/dev/serial0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Failed to open UART");
        return errno;
    }

    // Configure the UART
    if (tcgetattr(fd, &options) == -1) {
        perror("Failed to get UART attributes");
        close(fd);
        return errno;
    }

    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = INTER_BYTE_TIMEOUT / 100; // 0.5 seconds

    if (tcsetattr(fd, TCSANOW, &options) == -1) {
        perror("Failed to set UART attributes");
        close(fd);
        return errno;
    }

    while (1) {
        FD_ZERO(&read_fds);
        FD_SET(fd, &read_fds);

        timeout.tv_sec = TIMEOUT_SECONDS;
        timeout.tv_usec = 0;

        if (select(fd + 1, &read_fds, NULL, NULL, &timeout) == -1) {
            perror("Failed to select");
            close(fd);
            return errno;
        }

        if (FD_ISSET(fd, &read_fds)) {
            int bytes_read = read(fd, line_buffer + line_buffer_index, BUFFER_SIZE - line_buffer_index);
            if (bytes_read == -1) {
                perror("Failed to read from UART");
                close(fd);
                return errno;
            }

            line_buffer_index += bytes_read;

            for (int i = 0; i < line_buffer_index; i++) {
                if (line_buffer[i] == '\n') {
                    line_buffer[i] = '\0';
                    parse_and_log_line(line_buffer);
                    line_buffer_index = 0;
                    break;
                }
            }
        }
    }

    close(fd);
    return 0;
}

