#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SERIAL_PORT "/dev/ttyAMA0"
#define SERIAL_SPEED 115200

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    if (stop_flag == 0) {
        stop_flag = 1;
        printf("Received signal %d, stopping...\n", signum);
    }
}

void log_sensor_states(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", buffer, left, middle, right);
}

int main() {
    int left_pin = 4;
    int middle_pin = 17;
    int right_pin = 27;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(left_pin, PI_INPUT);
    gpioSetMode(middle_pin, PI_INPUT);
    gpioSetMode(right_pin, PI_INPUT);

    gpioSetPullUpDown(left_pin, PI_PUD_UP);
    gpioSetPullUpDown(middle_pin, PI_PUD_UP);
    gpioSetPullUpDown(right_pin, PI_PUD_UP);

    if (serialOpen(SERIAL_PORT, SERIAL_SPEED, SERIAL_8N1, 0) < 0) {
        fprintf(stderr, "Failed to open serial port\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        int left = gpioRead(left_pin);
        int middle = gpioRead(middle_pin);
        int right = gpioRead(right_pin);

        log_sensor_states(left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            if (serialPutStr(SERIAL_PORT, "EMERGENCY STOP!\n") < 0) {
                fprintf(stderr, "Error writing to serial port\n");
            }
        }

        usleep(100000); // 100 ms delay
    }

    serialClose(SERIAL_PORT);
    gpioTerminate();

    return 0;
}
